/* 1. Código estándar para catálogos automáticos. */
CREATE OR ALTER FUNCTION [config].[FN_CodigoCatalogo]
(
    @cNombre NVARCHAR(150),
    @nId BIGINT
)
RETURNS VARCHAR(40)
AS
BEGIN
    IF @nId IS NULL
        RETURN NULL;

    DECLARE @cTexto NVARCHAR(300) =
        UPPER(LTRIM(RTRIM(ISNULL(@cNombre,N''))));

    SET @cTexto = TRANSLATE(
        @cTexto,
        N'ÁÉÍÓÚÜÑÀÈÌÒÙÂÊÎÔÛÄËÏÖÜÇ',
        N'AEIOUUNAEIOUAEIOUAEIOUC'
    );

    DECLARE
        @cLimpio NVARCHAR(300)=N'',
        @cCaracter NCHAR(1),
        @nPos INT=1;

    WHILE @nPos <= LEN(@cTexto)
    BEGIN
        SET @cCaracter=SUBSTRING(@cTexto,@nPos,1);

        IF @cCaracter LIKE N'[A-Z0-9]' COLLATE Latin1_General_100_BIN2
            SET @cLimpio += @cCaracter;
        ELSE
            SET @cLimpio += N' ';

        SET @nPos += 1;
    END;

    WHILE CHARINDEX(N'  ',@cLimpio)>0
        SET @cLimpio=REPLACE(@cLimpio,N'  ',N' ');

    SET @cLimpio=LTRIM(RTRIM(@cLimpio));

    DECLARE
        @cSigla VARCHAR(6)='',
        @cResto NVARCHAR(300)=@cLimpio,
        @cPalabra NVARCHAR(100),
        @nEspacio INT;

    WHILE LEN(@cResto)>0 AND LEN(@cSigla)<6
    BEGIN
        SET @nEspacio=CHARINDEX(N' ',@cResto+N' ');
        SET @cPalabra=LEFT(@cResto,@nEspacio-1);
        SET @cResto=LTRIM(SUBSTRING(@cResto,@nEspacio+1,300));

        IF @cPalabra<>N''
           AND @cPalabra NOT IN
           (
               N'DE',N'DEL',N'LA',N'LAS',N'EL',N'LOS',
               N'Y',N'E',N'EN',N'PARA',N'POR',N'CON',
               N'SIN',N'A',N'AL'
           )
        BEGIN
            SET @cSigla += CONVERT(VARCHAR(1),LEFT(@cPalabra,1));
        END;
    END;

    IF @cSigla=''
        SET @cSigla='X';

    RETURN LEFT(@cSigla,6)
        + '-'
        + RIGHT(REPLICATE('0',7)+CONVERT(VARCHAR(20),@nId),7);
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER FUNCTION config.FN_RespuestaUsuario
(@procedimiento NVARCHAR(257),@exitoso BIT,@texto NVARCHAR(300))
RETURNS TABLE
AS RETURN
 SELECT CONVERT(NVARCHAR(300),CASE WHEN @exitoso=1 THEN
   CASE WHEN M.mensaje=N'La acción ya se realizó.' THEN M.mensaje ELSE COALESCE(P.mensaje_exito,N'Acción realizada.') END
   ELSE COALESCE(M.mensaje,P.mensaje_error,N'No se pudo completar la acción.') END) mensaje,
 CONVERT(VARCHAR(60),CASE WHEN @exitoso=1 THEN COALESCE(P.codigo_exito,'ACCION_REALIZADA')
   ELSE COALESCE(M.codigo_error,'ACCION_NO_COMPLETADA') END) codigo,
 CONVERT(SMALLINT,CASE WHEN @exitoso=1 THEN 200 ELSE COALESCE(M.http_error,400) END) http_sugerido
 FROM (VALUES(1)) X(n)
 LEFT JOIN config.RespuestaProcedimiento P ON P.procedimiento=@procedimiento
 OUTER APPLY(SELECT TOP(1) mensaje,codigo_error,http_error FROM config.MensajeUsuario
  WHERE texto_origen=@texto ORDER BY texto_origen) M;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/*
INVENTARIO Y SUMINISTROS

Reglas:
- Los códigos de bienes y suministros los genera la BD después de conocer el ID.
- Formato: <SIGLA_UOT>-<SIGLA_RECURSO>-<ID_7_DIGITOS>.
- El código no cambia si después se edita el nombre.
- Vehículo es una especialización de un bien clasificado como Vehículo.
- Las incidencias gobiernan el estado operativo del bien.
*/

CREATE OR ALTER FUNCTION [logistica].[FN_CodigoRecursoUOT]
(
    @nUotId BIGINT,
    @cNombre NVARCHAR(180),
    @nId BIGINT
)
RETURNS VARCHAR(40)
AS
BEGIN
    IF @nUotId IS NULL OR @nId IS NULL
        RETURN NULL;

    DECLARE
        @cUotNombre NVARCHAR(180),
        @cTexto NVARCHAR(300),
        @cLimpio NVARCHAR(300),
        @cPalabra NVARCHAR(100),
        @cCaracter NCHAR(1),
        @cSiglaUot VARCHAR(6) = '',
        @cSiglaRecurso VARCHAR(6) = '',
        @nPos INT,
        @nEspacio INT;

    SELECT @cUotNombre = U.nombre
    FROM org.UOT U
    WHERE U.uot_id = @nUotId;

    /* -------- UOT -------- */
    SET @cTexto = UPPER(LTRIM(RTRIM(ISNULL(@cUotNombre, N''))));
    SET @cTexto = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(
        @cTexto, N'Á', N'A'), N'É', N'E'), N'Í', N'I'), N'Ó', N'O'),
        N'Ú', N'U'), N'Ü', N'U'), N'Ñ', N'N');

    SET @cLimpio = N'';
    SET @nPos = 1;

    WHILE @nPos <= LEN(@cTexto)
    BEGIN
        SET @cCaracter = SUBSTRING(@cTexto, @nPos, 1);

        SET @cLimpio +=
            CASE
                WHEN @cCaracter LIKE N'[A-Z0-9]'
                     COLLATE Latin1_General_100_BIN2
                    THEN @cCaracter
                ELSE N' '
            END;

        SET @nPos += 1;
    END;

    WHILE CHARINDEX(N'  ', @cLimpio) > 0
        SET @cLimpio = REPLACE(@cLimpio, N'  ', N' ');

    SET @cTexto = LTRIM(RTRIM(@cLimpio));

    WHILE LEN(@cTexto) > 0 AND LEN(@cSiglaUot) < 6
    BEGIN
        SET @nEspacio = CHARINDEX(N' ', @cTexto + N' ');
        SET @cPalabra = LEFT(@cTexto, @nEspacio - 1);
        SET @cTexto = LTRIM(SUBSTRING(@cTexto, @nEspacio + 1, 300));

        IF @cPalabra <> N''
           AND @cPalabra NOT IN
           (
               N'UOT', N'DE', N'DEL', N'LA', N'LAS', N'EL', N'LOS',
               N'Y', N'E', N'EN', N'PARA', N'POR', N'CON', N'SIN'
           )
        BEGIN
            SET @cSiglaUot += CONVERT(VARCHAR(1), LEFT(@cPalabra, 1));
        END;
    END;

    /* -------- recurso -------- */
    SET @cTexto = UPPER(LTRIM(RTRIM(ISNULL(@cNombre, N''))));
    SET @cTexto = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(
        @cTexto, N'Á', N'A'), N'É', N'E'), N'Í', N'I'), N'Ó', N'O'),
        N'Ú', N'U'), N'Ü', N'U'), N'Ñ', N'N');

    SET @cLimpio = N'';
    SET @nPos = 1;

    WHILE @nPos <= LEN(@cTexto)
    BEGIN
        SET @cCaracter = SUBSTRING(@cTexto, @nPos, 1);

        SET @cLimpio +=
            CASE
                WHEN @cCaracter LIKE N'[A-Z0-9]'
                     COLLATE Latin1_General_100_BIN2
                    THEN @cCaracter
                ELSE N' '
            END;

        SET @nPos += 1;
    END;

    WHILE CHARINDEX(N'  ', @cLimpio) > 0
        SET @cLimpio = REPLACE(@cLimpio, N'  ', N' ');

    SET @cTexto = LTRIM(RTRIM(@cLimpio));

    WHILE LEN(@cTexto) > 0 AND LEN(@cSiglaRecurso) < 6
    BEGIN
        SET @nEspacio = CHARINDEX(N' ', @cTexto + N' ');
        SET @cPalabra = LEFT(@cTexto, @nEspacio - 1);
        SET @cTexto = LTRIM(SUBSTRING(@cTexto, @nEspacio + 1, 300));

        IF @cPalabra <> N''
           AND @cPalabra NOT IN
           (
               N'DE', N'DEL', N'LA', N'LAS', N'EL', N'LOS',
               N'Y', N'E', N'EN', N'PARA', N'POR', N'CON', N'SIN'
           )
        BEGIN
            SET @cSiglaRecurso +=
                CONVERT(VARCHAR(1), LEFT(@cPalabra, 1));
        END;
    END;

    IF @cSiglaUot = ''
        SET @cSiglaUot = 'U' + CONVERT(VARCHAR(5), @nUotId);

    IF @cSiglaRecurso = ''
        SET @cSiglaRecurso = 'R';

    RETURN
        LEFT(@cSiglaUot, 6)
        + '-'
        + LEFT(@cSiglaRecurso, 6)
        + '-'
        + RIGHT(
            REPLICATE('0', 7) + CONVERT(VARCHAR(20), @nId),
            7
        );
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER FUNCTION [org].[FN_Documento_EsValido]
(
    @cTipoDocumento VARCHAR(15),
    @cNumeroDocumento VARCHAR(30)
)
RETURNS BIT
AS
BEGIN
    DECLARE @cTipo VARCHAR(15)=UPPER(NULLIF(LTRIM(RTRIM(@cTipoDocumento)),''));
    DECLARE @cDoc VARCHAR(30)=NULLIF(LTRIM(RTRIM(@cNumeroDocumento)),'');

    IF @cTipo='DNI'
        RETURN CASE WHEN @cDoc IS NOT NULL
                          AND LEN(@cDoc)=8
                          AND @cDoc NOT LIKE '%[^0-9]%'
                    THEN 1 ELSE 0 END;

    IF @cTipo='RUC'
        RETURN [org].[FN_Ruc_EsValido](@cDoc);

    IF @cTipo IN ('CE','PASAPORTE','OTRO')
        RETURN CASE WHEN @cDoc IS NOT NULL THEN 1 ELSE 0 END;

    RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER FUNCTION [org].[FN_Ruc_DesdeDni]
(
    @cDni VARCHAR(30)
)
RETURNS VARCHAR(11)
AS
BEGIN
    DECLARE @c VARCHAR(30)=NULLIF(LTRIM(RTRIM(@cDni)),'');
    DECLARE @cBase VARCHAR(10);
    DECLARE @nSuma INT;
    DECLARE @nDv INT;

    IF @c IS NULL OR LEN(@c)<>8 OR @c LIKE '%[^0-9]%'
        RETURN NULL;

    SET @cBase='10'+@c;
    SET @nSuma=
          CONVERT(INT,SUBSTRING(@cBase,1,1))*5
        + CONVERT(INT,SUBSTRING(@cBase,2,1))*4
        + CONVERT(INT,SUBSTRING(@cBase,3,1))*3
        + CONVERT(INT,SUBSTRING(@cBase,4,1))*2
        + CONVERT(INT,SUBSTRING(@cBase,5,1))*7
        + CONVERT(INT,SUBSTRING(@cBase,6,1))*6
        + CONVERT(INT,SUBSTRING(@cBase,7,1))*5
        + CONVERT(INT,SUBSTRING(@cBase,8,1))*4
        + CONVERT(INT,SUBSTRING(@cBase,9,1))*3
        + CONVERT(INT,SUBSTRING(@cBase,10,1))*2;

    SET @nDv=11-(@nSuma%11);
    IF @nDv=10 SET @nDv=0;
    ELSE IF @nDv=11 SET @nDv=1;

    RETURN @cBase+CONVERT(VARCHAR(1),@nDv);
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER FUNCTION [org].[FN_Ruc_EsValido]
(
    @cRuc VARCHAR(30)
)
RETURNS BIT
AS
BEGIN
    DECLARE @c VARCHAR(30)=NULLIF(LTRIM(RTRIM(@cRuc)),'');
    DECLARE @nSuma INT;
    DECLARE @nDv INT;

    IF @c IS NULL OR LEN(@c)<>11 OR @c LIKE '%[^0-9]%'
        RETURN 0;

    SET @nSuma=
          CONVERT(INT,SUBSTRING(@c,1,1))*5
        + CONVERT(INT,SUBSTRING(@c,2,1))*4
        + CONVERT(INT,SUBSTRING(@c,3,1))*3
        + CONVERT(INT,SUBSTRING(@c,4,1))*2
        + CONVERT(INT,SUBSTRING(@c,5,1))*7
        + CONVERT(INT,SUBSTRING(@c,6,1))*6
        + CONVERT(INT,SUBSTRING(@c,7,1))*5
        + CONVERT(INT,SUBSTRING(@c,8,1))*4
        + CONVERT(INT,SUBSTRING(@c,9,1))*3
        + CONVERT(INT,SUBSTRING(@c,10,1))*2;

    SET @nDv=11-(@nSuma%11);
    IF @nDv=10 SET @nDv=0;
    ELSE IF @nDv=11 SET @nDv=1;

    RETURN CASE WHEN @nDv=CONVERT(INT,RIGHT(@c,1)) THEN 1 ELSE 0 END;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER FUNCTION [org].[FN_Ruc_Naturaleza]
(
    @cRuc VARCHAR(30)
)
RETURNS VARCHAR(12)
AS
BEGIN
    DECLARE @c VARCHAR(30)=NULLIF(LTRIM(RTRIM(@cRuc)),'');

    IF [org].[FN_Ruc_EsValido](@c)=0
        RETURN NULL;

    IF LEFT(@c,2) IN ('10','15','17') RETURN 'NATURAL';
    IF LEFT(@c,2)='20' RETURN 'JURIDICA';

    RETURN 'OTRO';
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO


