       S.producto_id,P.codigo producto_codigo,P.nombre producto,P.unidad_medida,
       S.stock_actual,S.stock_reservado,S.stock_disponible,S.stock_minimo,S.fecha_actualizacion,
       CONVERT(BIT,CASE WHEN S.stock_disponible<=S.stock_minimo THEN 1 ELSE 0 END) requiere_reposicion
