CREATE OR ALTER VIEW org.VW_UOT_Jerarquia
AS
WITH J AS
(
    SELECT U.uot_id,U.uot_padre_id,U.codigo,U.nombre,U.ubicacion_id,U.es_raiz,U.estado,
           CONVERT(NVARCHAR(1000),U.nombre) ruta,0 nivel
