    UNION ALL
    SELECT U.uot_id,U.uot_padre_id,U.codigo,U.nombre,U.ubicacion_id,U.es_raiz,U.estado,
           CONVERT(NVARCHAR(1000),J.ruta+N' > '+U.nombre),J.nivel+1
    FROM org.UOT U JOIN J ON J.uot_id=U.uot_padre_id
)
SELECT * FROM J;

