-- archivo.PA_Archivo_Ins_Registro
CREATE OR ALTER PROCEDURE [archivo].[PA_Archivo_Ins_Registro]
(
    @cJson NVARCHAR(MAX),
    @nArchivoId BIGINT OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,
        @gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),
        @nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),
        @bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),@nAud BIGINT,@nTrans BIGINT,
        @cNombre NVARCHAR(255),@cMime VARCHAR(120),@cPublic NVARCHAR(255),@cUrl NVARCHAR(1000),
        @nTam BIGINT,@cTipo VARCHAR(40),@cCategoria VARCHAR(30),@cOrigen VARCHAR(20),
        @cDesc NVARCHAR(400),@dCaptura DATETIME2(0),@nLat DECIMAL(9,6),@nLon DECIMAL(9,6),
        @gPos GEOGRAPHY,@nVinculos INT,@cIdent NVARCHAR(200),@cPost NVARCHAR(MAX),
        @cAccionAuditoria VARCHAR(40),
        @nPredio BIGINT,@nSalida BIGINT,@nVisita BIGINT,@nCaso BIGINT,@nTrat BIGINT,@nEntrega BIGINT,
        @nInc BIGINT,@nAjuste BIGINT,@nGasto BIGINT,@nLiq BIGINT,@nPago BIGINT,@nCobro BIGINT,
        @nSocio BIGINT,@nEmpleado BIGINT,@nParcela BIGINT,@nCultivo BIGINT,@nCenso BIGINT,@nEval BIGINT,
        @nSeg BIGINT,@nProd BIGINT,@nCamp BIGINT,@nPrecio BIGINT,@nPart BIGINT,@nOper BIGINT,
        @nJA BIGINT,@nJD BIGINT,@nBien BIGINT,@nRecurso BIGINT;

    SELECT @bResultado=0,@cMensaje=N'No se pudo registrar el documento.';

    EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente]
        @cJson=@cJson,@cCodigoPermiso='ARCHIVOS_CREAR',@cAmbito='ARCHIVO_REGISTRAR',
        @nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,
        @nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,
        @nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,
        @cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@nOperacionIdempotenteId=@nOp OUTPUT,
        @bEsRepetida=@bRep OUTPUT,@cEstadoOperacion=@cEstadoOp OUTPUT,
        @cIdentificadorResultado=@cIdRes OUTPUT,@cCodigoResultado=@cCodRes OUTPUT,
        @bResultado=@bIni OUTPUT,@cMensaje=@cMsg OUTPUT;

    IF @bIni=0 AND @bRep=0
    BEGIN
        SET @cMensaje=@cMsg;
        GOTO __DESCO_Salida;
    END;

    IF @bRep=1
    BEGIN
        SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
        SET @nArchivoId=CASE WHEN @cEstadoOp='COMPLETADA' THEN TRY_CONVERT(BIGINT,@cIdRes) ELSE NULL END;
        SET @cMensaje=CASE
            WHEN @cEstadoOp='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.'
            ELSE N'La solicitud ya se encuentra en proceso.'
        END;
        GOTO __DESCO_Salida;
    END;

    SET @nArchivoId=NULL;

    SELECT
        @cNombre=NULLIF(LTRIM(RTRIM(nombreOriginal)),N''),
        @cMime=NULLIF(LTRIM(RTRIM(mimeType)),''),
        @cPublic=NULLIF(LTRIM(RTRIM(cloudinaryPublicId)),N''),
        @cUrl=NULLIF(LTRIM(RTRIM(secureUrl)),N''),
        @nTam=tamanoBytes,
        @cTipo=UPPER(NULLIF(LTRIM(RTRIM(tipoEvidencia)),'')),
        @cCategoria=UPPER(NULLIF(LTRIM(RTRIM(categoria)),'')),
        @cOrigen=UPPER(NULLIF(LTRIM(RTRIM(origenCaptura)),'')),
        @cDesc=NULLIF(LTRIM(RTRIM(descripcion)),N''),
        @dCaptura=fechaCaptura,
        @nLat=latitudCaptura,
        @nLon=longitudCaptura
    FROM OPENJSON(@cJson,'$.archivo')
    WITH
    (
        nombreOriginal NVARCHAR(255) '$.nombreOriginal',
        mimeType VARCHAR(120) '$.mimeType',
        cloudinaryPublicId NVARCHAR(255) '$.cloudinaryPublicId',
        secureUrl NVARCHAR(1000) '$.secureUrl',
        tamanoBytes BIGINT '$.tamanoBytes',
        tipoEvidencia VARCHAR(40) '$.tipoEvidencia',
        categoria VARCHAR(30) '$.categoria',
        origenCaptura VARCHAR(20) '$.origenCaptura',
        descripcion NVARCHAR(400) '$.descripcion',
        fechaCaptura DATETIME2(0) '$.fechaCaptura',
        latitudCaptura DECIMAL(9,6) '$.latitudCaptura',
        longitudCaptura DECIMAL(9,6) '$.longitudCaptura'
    );

    IF @cOrigen IS NULL
        SET @cOrigen='CARGA';

    IF @cOrigen='ARCHIVO'
        SET @cOrigen='CARGA';

    IF @cOrigen NOT IN('CARGA','CAMARA')
    BEGIN
        SET @cMensaje=N'El origen del documento no es válido.';
        GOTO Fallar;
    END;

    IF @cCategoria IS NOT NULL
       AND @cCategoria NOT IN('FOTOGRAFIA','DOCUMENTO','TICKET','COMPROBANTE','OTRO')
    BEGIN
        SET @cMensaje=N'La categoría del documento no es válida.';
        GOTO Fallar;
    END;

    IF @cOrigen='CAMARA' AND @cCategoria IS NULL
        SET @cCategoria='FOTOGRAFIA';

    IF (@nLat IS NULL AND @nLon IS NOT NULL)
       OR (@nLat IS NOT NULL AND @nLon IS NULL)
       OR (@nLat IS NOT NULL AND (@nLat<-90 OR @nLat>90))
       OR (@nLon IS NOT NULL AND (@nLon<-180 OR @nLon>180))
    BEGIN
        SET @cMensaje=N'La ubicación de captura no es válida.';
        GOTO Fallar;
    END;

    IF @dCaptura IS NOT NULL AND @dCaptura>SYSUTCDATETIME()
    BEGIN
        SET @cMensaje=N'La fecha de captura no puede estar en el futuro.';
        GOTO Fallar;
    END;

    IF @cOrigen='CAMARA' AND @dCaptura IS NULL
        SET @dCaptura=SYSUTCDATETIME();

    IF @nLat IS NOT NULL AND @nLon IS NOT NULL
        SET @gPos=GEOGRAPHY::Point(CONVERT(FLOAT,@nLat),CONVERT(FLOAT,@nLon),4326);

    SELECT
        @nPredio=predioId,@nSalida=salidaCampoId,@nVisita=visitaTecnicaId,
        @nCaso=casoFitosanitarioId,@nTrat=tratamientoId,@nEntrega=entregaSocioId,
        @nInc=incidenciaOperativaId,@nAjuste=ajustePrecioSocioId,@nGasto=gastoCampaniaId,
        @nLiq=liquidacionSocioId,@nPago=pagoSocioId,@nCobro=cobroCompradorId,
        @nSocio=socioId,@nEmpleado=empleadoId,@nParcela=parcelaId,@nCultivo=parcelaCultivoId,
        @nCenso=censoPlantasId,@nEval=evaluacionAgronomicaId,@nSeg=seguimientoFitosanitarioId,
        @nProd=disponibilidadProduccionId,@nCamp=campaniaVentaId,@nPrecio=precioComercialId,
        @nPart=participacionCampaniaSocioId,@nOper=operativoVentaId,@nJA=jabaAsignacionId,
        @nJD=jabaDevolucionId,@nBien=bienInventarioId,@nRecurso=recursoProgramadoId
    FROM OPENJSON(@cJson,'$.vinculo')
    WITH
    (
        predioId BIGINT '$.predioId',
        salidaCampoId BIGINT '$.salidaCampoId',
        visitaTecnicaId BIGINT '$.visitaTecnicaId',
        casoFitosanitarioId BIGINT '$.casoFitosanitarioId',
        tratamientoId BIGINT '$.tratamientoId',
        entregaSocioId BIGINT '$.entregaSocioId',
        incidenciaOperativaId BIGINT '$.incidenciaOperativaId',
        ajustePrecioSocioId BIGINT '$.ajustePrecioSocioId',
        gastoCampaniaId BIGINT '$.gastoCampaniaId',
        liquidacionSocioId BIGINT '$.liquidacionSocioId',
        pagoSocioId BIGINT '$.pagoSocioId',
        cobroCompradorId BIGINT '$.cobroCompradorId',
        socioId BIGINT '$.socioId',
        empleadoId BIGINT '$.empleadoId',
        parcelaId BIGINT '$.parcelaId',
        parcelaCultivoId BIGINT '$.parcelaCultivoId',
        censoPlantasId BIGINT '$.censoPlantasId',
        evaluacionAgronomicaId BIGINT '$.evaluacionAgronomicaId',
        seguimientoFitosanitarioId BIGINT '$.seguimientoFitosanitarioId',
        disponibilidadProduccionId BIGINT '$.disponibilidadProduccionId',
        campaniaVentaId BIGINT '$.campaniaVentaId',
        precioComercialId BIGINT '$.precioComercialId',
        participacionCampaniaSocioId BIGINT '$.participacionCampaniaSocioId',
        operativoVentaId BIGINT '$.operativoVentaId',
        jabaAsignacionId BIGINT '$.jabaAsignacionId',
        jabaDevolucionId BIGINT '$.jabaDevolucionId',
        bienInventarioId BIGINT '$.bienInventarioId',
        recursoProgramadoId BIGINT '$.recursoProgramadoId'
    );

    SET @nVinculos=
        (CASE WHEN @nPredio IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nSalida IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nVisita IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nCaso IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nTrat IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nEntrega IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nInc IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nAjuste IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nGasto IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nLiq IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nPago IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nCobro IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nSocio IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nEmpleado IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nParcela IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nCultivo IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nCenso IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nEval IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nSeg IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nProd IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nCamp IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nPrecio IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nPart IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nOper IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nJA IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nJD IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nBien IS NULL THEN 0 ELSE 1 END)+
        (CASE WHEN @nRecurso IS NULL THEN 0 ELSE 1 END);

    IF @cNombre IS NULL
       OR @cMime IS NULL
       OR @cPublic IS NULL
       OR @cUrl IS NULL
       OR @cUrl NOT LIKE 'https://%'
       OR @nVinculos<>1
       OR (@nTam IS NOT NULL AND @nTam<0)
    BEGIN
        SET @cMensaje=N'Complete correctamente los datos del documento y seleccione un solo contexto.';
        GOTO Fallar;
    END;

    DECLARE @PermisosContexto TABLE(codigo VARCHAR(40) NOT NULL PRIMARY KEY);
    INSERT INTO @PermisosContexto(codigo)
    SELECT DISTINCT P.codigo
    FROM [seg].[UsuarioRol] UR
    INNER JOIN [seg].[Rol] R ON R.rol_id=UR.rol_id AND R.estado=1
    INNER JOIN [seg].[RolPermiso] RP ON RP.rol_id=R.rol_id AND RP.estado=1
    INNER JOIN [seg].[Permiso] P ON P.permiso_id=RP.permiso_id AND P.estado=1
    WHERE UR.usuario_id=@nUsuario
      AND UR.estado=1
      AND UR.fecha_desde<=SYSUTCDATETIME()
      AND (UR.fecha_hasta IS NULL OR UR.fecha_hasta>=SYSUTCDATETIME());

    IF NOT
    (
        (@nSocio IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PRODUCTORES_LISTAR','PRODUCTORES_VER')))
     OR (@nEmpleado IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('EMPLEADOS_LISTAR','EMPLEADOS_VER')))
     OR (@nPredio IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PREDIOS_LISTAR','PREDIOS_VER')))
     OR ((@nParcela IS NOT NULL OR @nCultivo IS NOT NULL) AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('CULTIVOS_LISTAR','CULTIVOS_VER')))
     OR (@nCenso IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('CENSOS_LISTAR','CENSOS_VER')))
     OR (@nSalida IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('SALIDAS_LISTAR','SALIDAS_VER')))
     OR (@nVisita IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('VISITAS_LISTAR','VISITAS_VER')))
     OR (@nEval IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('EVALUACIONES_LISTAR','EVALUACIONES_VER')))
     OR ((@nCaso IS NOT NULL OR @nTrat IS NOT NULL OR @nSeg IS NOT NULL) AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('SANIDAD_LISTAR','SANIDAD_VER')))
     OR (@nProd IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PRODUCCION_LISTAR','PRODUCCION_VER')))
     OR (@nCamp IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('CAMPANIAS_LISTAR','CAMPANIAS_VER')))
     OR (@nPrecio IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PRECIOS_LISTAR','PRECIOS_VER')))
     OR (@nPart IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PARTICIPANTES_LISTAR','PARTICIPANTES_VER')))
     OR (@nOper IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('OPERATIVOS_LISTAR','OPERATIVOS_VER')))
     OR ((@nJA IS NOT NULL OR @nJD IS NOT NULL) AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('JABAS_LISTAR','JABAS_VER')))
     OR (@nEntrega IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('ENTREGAS_LISTAR','ENTREGAS_VER')))
     OR (@nInc IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('INCIDENCIAS_LISTAR','INCIDENCIAS_VER')))
     OR (@nAjuste IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('AJUSTES_LISTAR','AJUSTES_VER')))
     OR (@nBien IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('INVENTARIO_LISTAR','INVENTARIO_VER')))
     OR (@nRecurso IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('RECURSOS_LISTAR','RECURSOS_VER')))
     OR (@nGasto IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('GASTOS_LISTAR','GASTOS_VER')))
     OR (@nLiq IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('LIQUIDACIONES_LISTAR','LIQUIDACIONES_VER')))
     OR (@nPago IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PAGOS_LISTAR','PAGOS_VER')))
     OR (@nCobro IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('COBROS_LISTAR','COBROS_VER')))
    )
    BEGIN
        SET @cMensaje=N'El contexto seleccionado no está disponible para su perfil.';
        GOTO Fallar;
    END;

    IF @cOrigen='CAMARA' AND @cMime NOT LIKE 'image/%'
    BEGIN
        SET @cMensaje=N'La captura de cámara debe corresponder a una imagen.';
        GOTO Fallar;
    END;

    IF
       (@nSalida IS NOT NULL AND EXISTS
        (
            SELECT 1 FROM [campo].[SalidaCampo]
            WHERE salida_campo_id=@nSalida
              AND estado=1
              AND estado_proceso IN('FINALIZADA','CANCELADA')
        ))
       OR
       (@nVisita IS NOT NULL AND EXISTS
        (
            SELECT 1 FROM [campo].[VisitaTecnica]
            WHERE visita_tecnica_id=@nVisita
              AND estado=1
              AND estado_proceso IN('FINALIZADA','ANULADA')
        ))
       OR
       (@nEval IS NOT NULL AND EXISTS
        (
            SELECT 1
            FROM [campo].[EvaluacionAgronomica] EA
            INNER JOIN [campo].[VisitaTecnica] V
                ON V.visita_tecnica_id=EA.visita_tecnica_id
            WHERE EA.evaluacion_agronomica_id=@nEval
              AND EA.estado=1
              AND V.estado=1
              AND V.estado_proceso IN('FINALIZADA','ANULADA')
        ))
       OR
       (@nCaso IS NOT NULL AND EXISTS
        (
            SELECT 1 FROM [sanidad].[CasoFitosanitario]
            WHERE caso_fitosanitario_id=@nCaso
              AND estado=1
              AND estado_caso='CERRADO'
        ))
       OR
       (@nTrat IS NOT NULL AND EXISTS
        (
            SELECT 1
            FROM [sanidad].[TratamientoFitosanitario] T
            INNER JOIN [sanidad].[CasoFitosanitario] C
                ON C.caso_fitosanitario_id=T.caso_fitosanitario_id
            WHERE T.tratamiento_fitosanitario_id=@nTrat
              AND T.estado=1
              AND C.estado=1
              AND C.estado_caso='CERRADO'
        ))
       OR
       (@nSeg IS NOT NULL AND EXISTS
        (
            SELECT 1
            FROM [sanidad].[SeguimientoFitosanitario] S
            INNER JOIN [sanidad].[CasoFitosanitario] C
                ON C.caso_fitosanitario_id=S.caso_fitosanitario_id
            WHERE S.seguimiento_fitosanitario_id=@nSeg
              AND S.estado=1
              AND C.estado=1
              AND C.estado_caso='CERRADO'
        ))
       OR
       (@nProd IS NOT NULL AND EXISTS
        (
            SELECT 1 FROM [prod].[DisponibilidadProduccion]
            WHERE disponibilidad_produccion_id=@nProd
              AND estado=1
              AND estado_estimacion IN('CONFIRMADA','DESCARTADA')
        ))
       OR
       (@nCultivo IS NOT NULL AND EXISTS
        (
            SELECT 1 FROM [prod].[ParcelaCultivo]
            WHERE parcela_cultivo_id=@nCultivo
              AND estado=1
              AND situacion_cultivo IN('FINALIZADO','ABANDONADO')
        ))
       OR
       (@nCenso IS NOT NULL AND EXISTS
        (
            SELECT 1
            FROM [prod].[CensoPlantas] C
            INNER JOIN [prod].[ParcelaCultivo] PC
                ON PC.parcela_cultivo_id=C.parcela_cultivo_id
            WHERE C.censo_plantas_id=@nCenso
              AND C.estado=1
              AND PC.estado=1
              AND PC.situacion_cultivo IN('FINALIZADO','ABANDONADO')
        ))
    BEGIN
        SET @cMensaje=N'El contexto seleccionado ya forma parte del historial cerrado y no admite nuevas evidencias.';
        GOTO Fallar;
    END;

    IF
       (@nCamp IS NOT NULL AND EXISTS(SELECT 1 FROM [comercial].[CampaniaVenta] WHERE campania_venta_id=@nCamp AND estado=1 AND estado_proceso IN('CERRADA','CANCELADA')))
       OR (@nPrecio IS NOT NULL AND EXISTS
           (SELECT 1 FROM [comercial].[PrecioComercial] P INNER JOIN [comercial].[CampaniaVenta] C ON C.campania_venta_id=P.campania_venta_id WHERE P.precio_comercial_id=@nPrecio AND (P.estado=0 OR C.estado_proceso IN('CERRADA','CANCELADA'))))
       OR (@nPart IS NOT NULL AND EXISTS
           (SELECT 1 FROM [comercial].[ParticipacionCampaniaSocio] P INNER JOIN [comercial].[CampaniaVenta] C ON C.campania_venta_id=P.campania_venta_id WHERE P.participacion_campania_socio_id=@nPart AND P.estado=1 AND (P.estado_participacion IN('RETIRADO','EXCLUIDO') OR C.estado_proceso IN('CERRADA','CANCELADA'))))
       OR (@nOper IS NOT NULL AND EXISTS(SELECT 1 FROM [comercial].[OperativoVenta] WHERE operativo_venta_id=@nOper AND estado=1 AND estado_proceso IN('CERRADO','CANCELADO')))
       OR (@nJA IS NOT NULL AND EXISTS
           (SELECT 1 FROM [comercial].[JabaAsignacion] JA INNER JOIN [comercial].[OperativoSocio] OS ON OS.operativo_socio_id=JA.operativo_socio_id INNER JOIN [comercial].[OperativoVenta] O ON O.operativo_venta_id=OS.operativo_venta_id WHERE JA.jaba_asignacion_id=@nJA AND (JA.estado=0 OR O.estado_proceso IN('CERRADO','CANCELADO'))))
       OR (@nJD IS NOT NULL AND EXISTS
           (SELECT 1 FROM [comercial].[JabaDevolucion] JD INNER JOIN [comercial].[JabaAsignacion] JA ON JA.jaba_asignacion_id=JD.jaba_asignacion_id INNER JOIN [comercial].[OperativoSocio] OS ON OS.operativo_socio_id=JA.operativo_socio_id INNER JOIN [comercial].[OperativoVenta] O ON O.operativo_venta_id=OS.operativo_venta_id WHERE JD.jaba_devolucion_id=@nJD AND (JD.estado=0 OR O.estado_proceso IN('CERRADO','CANCELADO'))))
       OR (@nEntrega IS NOT NULL AND EXISTS(SELECT 1 FROM [comercial].[EntregaSocio] WHERE entrega_socio_id=@nEntrega AND estado=1 AND estado_proceso IN('CONFIRMADA','ANULADA')))
       OR (@nInc IS NOT NULL AND EXISTS(SELECT 1 FROM [comercial].[IncidenciaOperativa] WHERE incidencia_operativa_id=@nInc AND estado=1 AND estado_incidencia IN('RESUELTA','ANULADA')))
       OR (@nAjuste IS NOT NULL AND EXISTS(SELECT 1 FROM [comercial].[AjustePrecioSocio] WHERE ajuste_precio_socio_id=@nAjuste AND estado=1 AND estado_ajuste='ANULADO'))
       OR (@nGasto IS NOT NULL AND EXISTS(SELECT 1 FROM [finanzas].[GastoCampania] WHERE gasto_campania_id=@nGasto AND estado=1 AND estado_proceso IN('APROBADO','ANULADO')))
       OR (@nLiq IS NOT NULL AND EXISTS(SELECT 1 FROM [finanzas].[LiquidacionSocio] WHERE liquidacion_socio_id=@nLiq AND estado=1 AND estado_proceso IN('APROBADA','PAGADA_PARCIAL','PAGADA','ANULADA')))
       OR (@nPago IS NOT NULL AND EXISTS(SELECT 1 FROM [finanzas].[PagoSocio] WHERE pago_socio_id=@nPago AND estado=1 AND estado_proceso IN('CONFIRMADO','ANULADO')))
       OR (@nCobro IS NOT NULL AND EXISTS(SELECT 1 FROM [finanzas].[CobroComprador] WHERE cobro_comprador_id=@nCobro AND estado=1 AND estado_proceso IN('CONFIRMADO','ANULADO')))
    BEGIN
        SET @cMensaje=N'El contexto seleccionado ya fue cerrado, confirmado o anulado y debe conservarse sin nuevas evidencias.';
        GOTO Fallar;
    END;

    BEGIN TRY
        BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

        INSERT [archivo].[Archivo]
        (
            nombre_original,mime_type,cloudinary_public_id,secure_url,tamano_bytes,
            usuario_id,fecha_carga,estado,categoria,origen_captura,descripcion,
            fecha_captura,posicion_captura,tipo_evidencia
        )
        VALUES
        (
            @cNombre,@cMime,@cPublic,@cUrl,@nTam,
            @nUsuario,SYSUTCDATETIME(),1,@cCategoria,@cOrigen,@cDesc,
            @dCaptura,@gPos,@cTipo
        );

        SET @nArchivoId=CONVERT(BIGINT,SCOPE_IDENTITY());

        INSERT [archivo].[ArchivoVinculo]
        (
            archivo_id,predio_id,salida_campo_id,visita_tecnica_id,caso_fitosanitario_id,
            tratamiento_id,entrega_socio_id,incidencia_operativa_id,ajuste_precio_socio_id,
            gasto_campania_id,liquidacion_socio_id,pago_socio_id,cobro_comprador_id,
            socio_id,empleado_id,parcela_id,parcela_cultivo_id,censo_plantas_id,
            evaluacion_agronomica_id,seguimiento_fitosanitario_id,disponibilidad_produccion_id,
            campania_venta_id,precio_comercial_id,participacion_campania_socio_id,
            operativo_venta_id,jaba_asignacion_id,jaba_devolucion_id,bien_inventario_id,
            recurso_programado_id,estado
        )
        VALUES
        (
            @nArchivoId,@nPredio,@nSalida,@nVisita,@nCaso,
            @nTrat,@nEntrega,@nInc,@nAjuste,
            @nGasto,@nLiq,@nPago,@nCobro,
            @nSocio,@nEmpleado,@nParcela,@nCultivo,@nCenso,
            @nEval,@nSeg,@nProd,
            @nCamp,@nPrecio,@nPart,
            @nOper,@nJA,@nJD,@nBien,
            @nRecurso,1
        );

        SET @cIdent=CONVERT(NVARCHAR(200),@nArchivoId);

        SELECT @cPost=
        (
            SELECT
                @nArchivoId archivoId,
                @cNombre nombreOriginal,
                @cTipo tipoEvidencia,
                @cCategoria categoria,
                @cOrigen origenCaptura,
                @dCaptura fechaCaptura
            FOR JSON PATH,WITHOUT_ARRAY_WRAPPER
        );

        SET @cAccionAuditoria =
            CASE
                WHEN @cOrigen='CAMARA' THEN 'FOTOGRAFIA'
                ELSE 'SUBIR'
            END;

        EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio]
            @nUsuarioId=@nUsuario,
            @nSesionUsuarioId=@nSesion,
            @nDispositivoUsuarioId=@nDisp,
            @nModuloId=@nModulo,
            @cAccion=@cAccionAuditoria,
            @cEsquemaEntidad='archivo',
            @cNombreEntidad='Archivo',
            @cIdentificador=@cIdent,
            @cDatosAnteriores=NULL,
            @cDatosPosteriores=@cPost,
            @cMotivo=NULL,
            @cCampoEstado=NULL,
            @cEstadoAnterior=NULL,
            @cEstadoNuevo=NULL,
            @cIp=@cIp,
            @gCorrelacionId=@gCorr,
            @gSolicitudId=@gSol,
            @cEndpoint=@cEnd,
            @nAuditoriaEventoId=@nAud OUTPUT,
            @nTransicionEstadoId=@nTrans OUTPUT;

        /* Confirmar datos e idempotencia juntos. */

        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
            @nOperacionIdempotenteId=@nOp,
            @cEstadoOperacion='COMPLETADA',
            @cEsquemaEntidad='archivo',
            @cNombreEntidad='Archivo',
            @cIdentificadorResultado=@cIdent,
            @cCodigoResultado='ARCHIVO_REGISTRADO',
            @bResultado=@bFin OUTPUT,
            @cMensaje=@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;

        SET @bResultado=1;
        SET @cMensaje=CASE
            WHEN @cOrigen='CAMARA' THEN N'Fotografía registrada correctamente.'
            ELSE N'Documento registrado correctamente.'
        END;
        GOTO __DESCO_Salida;
    END TRY
    BEGIN CATCH
SET @bResultado = 0;

        IF XACT_STATE()<>0
            BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;

        SET @cMensaje=N'No se pudo registrar el documento. Verifique el contexto seleccionado e intente nuevamente.';
    
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'archivo.PA_Archivo_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;

Fallar:
    IF @nOp IS NOT NULL AND @bResultado=0
        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
            @nOperacionIdempotenteId=@nOp,
            @cEstadoOperacion='FALLIDA',
            @cEsquemaEntidad=NULL,
            @cNombreEntidad=NULL,
            @cIdentificadorResultado=NULL,
            @cCodigoResultado='NO_PROCESADO',
            @bResultado=@bFin OUTPUT,
            @cMensaje=@cMsgFin OUTPUT;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'archivo.PA_Archivo_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

    IF @bResultado = 0 AND @nOp IS NOT NULL AND XACT_STATE() <> -1
    BEGIN
        IF ISNULL(@bRep,0) = 0
        BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                 @nOperacionIdempotenteId = @nOp, @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
            -- No sustituir el motivo funcional por un fallo de registro secundario.
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'archivo.PA_Archivo_Ins_Registro',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
        END CATCH;
        END
        ELSE
        BEGIN
            SELECT @cMensaje = COALESCE(mensaje_resultado,
                CASE WHEN estado_operacion = 'FALLIDA'
                     THEN N'La solicitud anterior no se completó. Corrija los datos y envíe una nueva solicitud.'
                     ELSE N'La solicitud todavía se está procesando. Consulte el resultado antes de repetirla.' END)
            FROM [auditoria].[OperacionIdempotente]
            WHERE operacion_idempotente_id = @nOp;
        END;
    END;
IF @bResultado = 0
    SELECT @nArchivoId = NULL;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'archivo.PA_Archivo_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'archivo.PA_Archivo_Ins_Registro',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE archivo.PA_Archivo_Ins_RegistroAlmacenamiento
 @nUsuarioId BIGINT,@nUotId BIGINT,@cNombreOriginal NVARCHAR(255),@cMimeType VARCHAR(120),@cProveedor VARCHAR(20),
 @cClave NVARCHAR(1000),@cUrl NVARCHAR(1000)=NULL,@nTamano BIGINT=NULL,@cCategoria VARCHAR(30)=NULL,@cDescripcion NVARCHAR(400)=NULL,
 @nArchivoId BIGINT OUTPUT,@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SET @nArchivoId=NULL; SET @bResultado=0; SET @cMensaje=N'No se pudo registrar el archivo.';
 IF seg.FN_Usuario_TieneAccesoUOT(@nUsuarioId,@nUotId)=0 BEGIN SET @cMensaje=N'No tiene acceso a la UOT seleccionada.'; RETURN; END;
 SET @cProveedor=UPPER(NULLIF(LTRIM(RTRIM(@cProveedor)),'')); SET @cNombreOriginal=NULLIF(LTRIM(RTRIM(@cNombreOriginal)),N''); SET @cClave=NULLIF(LTRIM(RTRIM(@cClave)),N'');
 SET @cCategoria=UPPER(NULLIF(LTRIM(RTRIM(@cCategoria)),''));
 IF @cProveedor IS NULL OR @cProveedor NOT IN('LOCAL','SERVIDOR','S3','CLOUDINARY','OTRO') OR @cNombreOriginal IS NULL OR @cClave IS NULL OR NULLIF(LTRIM(RTRIM(@cMimeType)),'') IS NULL
 BEGIN SET @cMensaje=N'Complete correctamente los datos del archivo.'; RETURN; END;
 IF @cCategoria IS NOT NULL AND @cCategoria NOT IN('FOTOGRAFIA','DOCUMENTO','TICKET','COMPROBANTE','OTRO')
 BEGIN SET @cMensaje=N'La categoría del archivo no es válida.'; RETURN; END;
 IF @nTamano IS NOT NULL AND @nTamano<0 BEGIN SET @cMensaje=N'El tamaño del archivo no es válido.'; RETURN; END;
 INSERT archivo.Archivo(nombre_original,mime_type,cloudinary_public_id,secure_url,tamano_bytes,usuario_id,fecha_carga,estado,categoria,origen_captura,descripcion,uot_id,proveedor_almacenamiento,clave_almacenamiento,url_almacenamiento)
 VALUES(@cNombreOriginal,@cMimeType,CASE WHEN @cProveedor='CLOUDINARY' THEN LEFT(@cClave,255) ELSE NULL END,CASE WHEN @cProveedor='CLOUDINARY' THEN @cUrl ELSE NULL END,@nTamano,@nUsuarioId,SYSUTCDATETIME(),1,@cCategoria,'CARGA',@cDescripcion,@nUotId,@cProveedor,@cClave,@cUrl);
 SET @nArchivoId=SCOPE_IDENTITY(); SET @bResultado=1; SET @cMensaje=N'Archivo registrado correctamente.';
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- archivo.PA_Archivo_Sel_Detalle
CREATE OR ALTER PROCEDURE [archivo].[PA_Archivo_Sel_Detalle]
(
    @cJson NVARCHAR(MAX),
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;

    DECLARE
        @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,
        @gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),
        @bCtx BIT,@cMsg NVARCHAR(300),@nId BIGINT;

    SELECT @bResultado=0,@cMensaje=N'No se pudo consultar el documento.';

    EXEC [seg].[PA_Operacion_Sel_ContextoAutorizado]
        @cJson=@cJson,@cCodigoPermiso='ARCHIVOS_VER',
        @nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,
        @nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,
        @nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,
        @gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,
        @bResultado=@bCtx OUTPUT,@cMensaje=@cMsg OUTPUT;

    IF @bCtx=0
    BEGIN
        SET @cMensaje=@cMsg;
        GOTO __DESCO_Salida;
    END;

    SELECT @nId=archivoId
    FROM OPENJSON(@cJson,'$.archivo')
    WITH(archivoId BIGINT '$.archivoId');

    DECLARE @PermisosContexto TABLE(codigo VARCHAR(40) NOT NULL PRIMARY KEY);
    INSERT INTO @PermisosContexto(codigo)
    SELECT DISTINCT P.codigo
    FROM [seg].[UsuarioRol] UR
    INNER JOIN [seg].[Rol] R ON R.rol_id=UR.rol_id AND R.estado=1
    INNER JOIN [seg].[RolPermiso] RP ON RP.rol_id=R.rol_id AND RP.estado=1
    INNER JOIN [seg].[Permiso] P ON P.permiso_id=RP.permiso_id AND P.estado=1
    WHERE UR.usuario_id=@nUsuario
      AND UR.estado=1
      AND UR.fecha_desde<=SYSUTCDATETIME()
      AND (UR.fecha_hasta IS NULL OR UR.fecha_hasta>=SYSUTCDATETIME());

    IF @nId IS NULL
       OR NOT EXISTS(SELECT 1 FROM [archivo].[Archivo] WHERE archivo_id=@nId AND estado=1)
    BEGIN
        SET @cMensaje=N'El documento seleccionado no está disponible.';
        GOTO __DESCO_Salida;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [archivo].[ArchivoVinculo] V
        WHERE V.archivo_id=@nId
          AND V.estado=1
          AND (
            (V.socio_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PRODUCTORES_LISTAR','PRODUCTORES_VER')))
         OR (V.empleado_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('EMPLEADOS_LISTAR','EMPLEADOS_VER')))
         OR (V.predio_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PREDIOS_LISTAR','PREDIOS_VER')))
         OR ((V.parcela_id IS NOT NULL OR V.parcela_cultivo_id IS NOT NULL) AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('CULTIVOS_LISTAR','CULTIVOS_VER')))
         OR (V.censo_plantas_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('CENSOS_LISTAR','CENSOS_VER')))
         OR (V.salida_campo_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('SALIDAS_LISTAR','SALIDAS_VER')))
         OR (V.visita_tecnica_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('VISITAS_LISTAR','VISITAS_VER')))
         OR (V.evaluacion_agronomica_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('EVALUACIONES_LISTAR','EVALUACIONES_VER')))
         OR ((V.caso_fitosanitario_id IS NOT NULL OR V.tratamiento_id IS NOT NULL OR V.seguimiento_fitosanitario_id IS NOT NULL) AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('SANIDAD_LISTAR','SANIDAD_VER')))
         OR (V.disponibilidad_produccion_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PRODUCCION_LISTAR','PRODUCCION_VER')))
         OR (V.campania_venta_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('CAMPANIAS_LISTAR','CAMPANIAS_VER')))
         OR (V.precio_comercial_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PRECIOS_LISTAR','PRECIOS_VER')))
         OR (V.participacion_campania_socio_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PARTICIPANTES_LISTAR','PARTICIPANTES_VER')))
         OR (V.operativo_venta_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('OPERATIVOS_LISTAR','OPERATIVOS_VER')))
         OR ((V.jaba_asignacion_id IS NOT NULL OR V.jaba_devolucion_id IS NOT NULL) AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('JABAS_LISTAR','JABAS_VER')))
         OR (V.entrega_socio_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('ENTREGAS_LISTAR','ENTREGAS_VER')))
         OR (V.incidencia_operativa_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('INCIDENCIAS_LISTAR','INCIDENCIAS_VER')))
         OR (V.ajuste_precio_socio_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('AJUSTES_LISTAR','AJUSTES_VER')))
         OR (V.bien_inventario_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('INVENTARIO_LISTAR','INVENTARIO_VER')))
         OR (V.recurso_programado_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('RECURSOS_LISTAR','RECURSOS_VER')))
         OR (V.gasto_campania_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('GASTOS_LISTAR','GASTOS_VER')))
         OR (V.liquidacion_socio_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('LIQUIDACIONES_LISTAR','LIQUIDACIONES_VER')))
         OR (V.pago_socio_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PAGOS_LISTAR','PAGOS_VER')))
         OR (V.cobro_comprador_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('COBROS_LISTAR','COBROS_VER')))
        )
    )
    BEGIN
        SET @cMensaje=N'El documento seleccionado no está disponible dentro de su contexto autorizado.';
        GOTO __DESCO_Salida;
    END;

    SELECT
        A.archivo_id archivoId,
        A.nombre_original nombreOriginal,
        A.mime_type mimeType,
        A.cloudinary_public_id cloudinaryPublicId,
        A.secure_url secureUrl,
        A.tamano_bytes tamanoBytes,
        A.categoria,
        A.tipo_evidencia tipoEvidencia,
        A.origen_captura origenCaptura,
        A.descripcion,
        A.fecha_captura fechaCaptura,
        CASE WHEN A.posicion_captura IS NULL THEN NULL ELSE A.posicion_captura.Lat END latitudCaptura,
        CASE WHEN A.posicion_captura IS NULL THEN NULL ELSE A.posicion_captura.Long END longitudCaptura,
        A.fecha_carga fechaCarga,
        A.usuario_id usuarioId,
        U.nombre_usuario nombreUsuario
    FROM [archivo].[Archivo] A
    INNER JOIN [seg].[Usuario] U
        ON U.usuario_id=A.usuario_id
    WHERE A.archivo_id=@nId;

    SELECT
        V.archivo_vinculo_id archivoVinculoId,
        CASE
            WHEN V.socio_id IS NOT NULL THEN N'Productor / socio'
            WHEN V.empleado_id IS NOT NULL THEN N'Empleado'
            WHEN V.predio_id IS NOT NULL THEN N'Predio'
            WHEN V.parcela_id IS NOT NULL THEN N'Parcela'
            WHEN V.parcela_cultivo_id IS NOT NULL THEN N'Cultivo'
            WHEN V.censo_plantas_id IS NOT NULL THEN N'Censo de plantas'
            WHEN V.salida_campo_id IS NOT NULL THEN N'Salida de campo'
            WHEN V.visita_tecnica_id IS NOT NULL THEN N'Visita técnica'
            WHEN V.evaluacion_agronomica_id IS NOT NULL THEN N'Evaluación agronómica'
            WHEN V.caso_fitosanitario_id IS NOT NULL THEN N'Caso de sanidad vegetal'
            WHEN V.tratamiento_id IS NOT NULL THEN N'Tratamiento sanitario'
            WHEN V.seguimiento_fitosanitario_id IS NOT NULL THEN N'Seguimiento sanitario'
            WHEN V.disponibilidad_produccion_id IS NOT NULL THEN N'Producción disponible'
            WHEN V.campania_venta_id IS NOT NULL THEN N'Campaña de venta'
            WHEN V.precio_comercial_id IS NOT NULL THEN N'Precio comercial'
            WHEN V.participacion_campania_socio_id IS NOT NULL THEN N'Participación en campaña'
            WHEN V.operativo_venta_id IS NOT NULL THEN N'Operativo de venta'
            WHEN V.jaba_asignacion_id IS NOT NULL THEN N'Asignación de jabas'
            WHEN V.jaba_devolucion_id IS NOT NULL THEN N'Devolución de jabas'
            WHEN V.entrega_socio_id IS NOT NULL THEN N'Entrega del socio'
            WHEN V.incidencia_operativa_id IS NOT NULL THEN N'Incidencia operativa'
            WHEN V.ajuste_precio_socio_id IS NOT NULL THEN N'Ajuste de precio'
            WHEN V.bien_inventario_id IS NOT NULL THEN N'Bien de inventario'
            WHEN V.recurso_programado_id IS NOT NULL THEN N'Recurso programado'
            WHEN V.gasto_campania_id IS NOT NULL THEN N'Gasto de campaña'
            WHEN V.liquidacion_socio_id IS NOT NULL THEN N'Liquidación'
            WHEN V.pago_socio_id IS NOT NULL THEN N'Pago al socio'
            WHEN V.cobro_comprador_id IS NOT NULL THEN N'Cobro del comprador'
            ELSE N'Sin contexto'
        END tipoContexto,
        COALESCE
        (
            V.socio_id,V.empleado_id,V.predio_id,V.parcela_id,V.parcela_cultivo_id,V.censo_plantas_id,
            V.salida_campo_id,V.visita_tecnica_id,V.evaluacion_agronomica_id,V.caso_fitosanitario_id,
            V.tratamiento_id,V.seguimiento_fitosanitario_id,V.disponibilidad_produccion_id,
            V.campania_venta_id,V.precio_comercial_id,V.participacion_campania_socio_id,V.operativo_venta_id,
            V.jaba_asignacion_id,V.jaba_devolucion_id,V.entrega_socio_id,V.incidencia_operativa_id,
            V.ajuste_precio_socio_id,V.bien_inventario_id,V.recurso_programado_id,V.gasto_campania_id,
            V.liquidacion_socio_id,V.pago_socio_id,V.cobro_comprador_id
        ) contextoId,
        V.predio_id predioId,
        V.salida_campo_id salidaCampoId,
        V.visita_tecnica_id visitaTecnicaId,
        V.caso_fitosanitario_id casoFitosanitarioId,
        V.tratamiento_id tratamientoId,
        V.entrega_socio_id entregaSocioId,
        V.incidencia_operativa_id incidenciaOperativaId,
        V.ajuste_precio_socio_id ajustePrecioSocioId,
        V.gasto_campania_id gastoCampaniaId,
        V.liquidacion_socio_id liquidacionSocioId,
        V.pago_socio_id pagoSocioId,
        V.cobro_comprador_id cobroCompradorId,
        V.socio_id socioId,
        V.empleado_id empleadoId,
        V.parcela_id parcelaId,
        V.parcela_cultivo_id parcelaCultivoId,
        V.censo_plantas_id censoPlantasId,
        V.evaluacion_agronomica_id evaluacionAgronomicaId,
        V.seguimiento_fitosanitario_id seguimientoFitosanitarioId,
        V.disponibilidad_produccion_id disponibilidadProduccionId,
        V.campania_venta_id campaniaVentaId,
        V.precio_comercial_id precioComercialId,
        V.participacion_campania_socio_id participacionCampaniaSocioId,
        V.operativo_venta_id operativoVentaId,
        V.jaba_asignacion_id jabaAsignacionId,
        V.jaba_devolucion_id jabaDevolucionId,
        V.bien_inventario_id bienInventarioId,
        V.recurso_programado_id recursoProgramadoId
    FROM [archivo].[ArchivoVinculo] V
    WHERE V.archivo_id=@nId
      AND V.estado=1;

    SET @bResultado=1;
    SET @cMensaje=N'Documento consultado correctamente.';

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'archivo.PA_Archivo_Sel_Detalle',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'archivo.PA_Archivo_Sel_Detalle',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'archivo.PA_Archivo_Sel_Detalle',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- archivo.PA_Archivo_Sel_Listado
CREATE OR ALTER PROCEDURE [archivo].[PA_Archivo_Sel_Listado]
(
    @cJson NVARCHAR(MAX),
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;

    DECLARE
        @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,
        @gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),
        @bCtx BIT,@cMsg NVARCHAR(300),
        @cTipo VARCHAR(40),@cOrigen VARCHAR(20),@nUsuarioFiltro BIGINT,
        @cContexto VARCHAR(40),@nContextoId BIGINT,
        @dDesde DATETIME2(0),@dHasta DATETIME2(0),
        @nPagina INT=1,@nTam INT=25,@nOffset INT;

    SELECT @bResultado=0,@cMensaje=N'No se pudieron consultar los documentos.';

    EXEC [seg].[PA_Operacion_Sel_ContextoAutorizado]
        @cJson=@cJson,@cCodigoPermiso='ARCHIVOS_LISTAR',
        @nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,
        @nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,
        @nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,
        @gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,
        @bResultado=@bCtx OUTPUT,@cMensaje=@cMsg OUTPUT;

    IF @bCtx=0
    BEGIN
        SET @cMensaje=@cMsg;
        GOTO __DESCO_Salida;
    END;

    SELECT
        @cTipo=UPPER(NULLIF(LTRIM(RTRIM(tipoEvidencia)),'')),
        @cOrigen=UPPER(NULLIF(LTRIM(RTRIM(origenCaptura)),'')),
        @nUsuarioFiltro=usuarioId,
        @cContexto=UPPER(NULLIF(LTRIM(RTRIM(contextoTipo)),'')),
        @nContextoId=contextoId,
        @dDesde=fechaDesde,
        @dHasta=fechaHasta
    FROM OPENJSON(@cJson,'$.filtros')
    WITH
    (
        tipoEvidencia VARCHAR(40) '$.tipoEvidencia',
        origenCaptura VARCHAR(20) '$.origenCaptura',
        usuarioId BIGINT '$.usuarioId',
        contextoTipo VARCHAR(40) '$.contextoTipo',
        contextoId BIGINT '$.contextoId',
        fechaDesde DATETIME2(0) '$.fechaDesde',
        fechaHasta DATETIME2(0) '$.fechaHasta'
    );

    IF @cOrigen='ARCHIVO'
        SET @cOrigen='CARGA';

    IF @cOrigen IS NOT NULL AND @cOrigen NOT IN('CARGA','CAMARA')
    BEGIN
        SET @cMensaje=N'El origen de captura seleccionado no es válido.';
        GOTO __DESCO_Salida;
    END;

    IF @dDesde IS NOT NULL AND @dHasta IS NOT NULL AND @dHasta<@dDesde
    BEGIN
        SET @cMensaje=N'El rango de fechas seleccionado no es válido.';
        GOTO __DESCO_Salida;
    END;

    IF (@cContexto IS NULL AND @nContextoId IS NOT NULL) OR (@cContexto IS NOT NULL AND @nContextoId IS NULL)
    BEGIN
        SET @cMensaje=N'Complete correctamente el contexto que desea consultar.';
        GOTO __DESCO_Salida;
    END;

    IF @cContexto IS NOT NULL AND @cContexto NOT IN
       ('SOCIO','EMPLEADO','PREDIO','PARCELA','CULTIVO','CENSO','SALIDA','VISITA','EVALUACION','CASO_SANIDAD','TRATAMIENTO','SEGUIMIENTO','PRODUCCION','CAMPANIA','PRECIO','PARTICIPANTE','OPERATIVO','JABA_ASIGNACION','JABA_DEVOLUCION','ENTREGA','INCIDENCIA','AJUSTE','BIEN','RECURSO','GASTO','LIQUIDACION','PAGO','COBRO')
    BEGIN
        SET @cMensaje=N'El contexto seleccionado no es válido.';
        GOTO __DESCO_Salida;
    END;

    DECLARE @PermisosContexto TABLE(codigo VARCHAR(40) NOT NULL PRIMARY KEY);
    INSERT INTO @PermisosContexto(codigo)
    SELECT DISTINCT P.codigo
    FROM [seg].[UsuarioRol] UR
    INNER JOIN [seg].[Rol] R ON R.rol_id=UR.rol_id AND R.estado=1
    INNER JOIN [seg].[RolPermiso] RP ON RP.rol_id=R.rol_id AND RP.estado=1
    INNER JOIN [seg].[Permiso] P ON P.permiso_id=RP.permiso_id AND P.estado=1
    WHERE UR.usuario_id=@nUsuario
      AND UR.estado=1
      AND UR.fecha_desde<=SYSUTCDATETIME()
      AND (UR.fecha_hasta IS NULL OR UR.fecha_hasta>=SYSUTCDATETIME());

    SELECT
        @nPagina=COALESCE(pagina,1),
        @nTam=COALESCE(tamano,25)
    FROM OPENJSON(@cJson,'$.paginacion')
    WITH
    (
        pagina INT '$.pagina',
        tamano INT '$.tamano'
    );

    IF @nPagina<1 SET @nPagina=1;
    IF @nTam<1 SET @nTam=25;
    IF @nTam>200 SET @nTam=200;
    SET @nOffset=(@nPagina-1)*@nTam;

    SELECT
        A.archivo_id archivoId,
        A.nombre_original nombreOriginal,
        A.mime_type mimeType,
        A.secure_url secureUrl,
        A.tamano_bytes tamanoBytes,
        A.categoria,
        A.tipo_evidencia tipoEvidencia,
        A.origen_captura origenCaptura,
        A.descripcion,
        A.fecha_captura fechaCaptura,
        CASE WHEN A.posicion_captura IS NULL THEN NULL ELSE A.posicion_captura.Lat END latitudCaptura,
        CASE WHEN A.posicion_captura IS NULL THEN NULL ELSE A.posicion_captura.Long END longitudCaptura,
        A.fecha_carga fechaCarga,
        A.usuario_id usuarioId,
        U.nombre_usuario nombreUsuario,
        CASE
            WHEN V.socio_id IS NOT NULL THEN N'Productor / socio'
            WHEN V.empleado_id IS NOT NULL THEN N'Empleado'
            WHEN V.predio_id IS NOT NULL THEN N'Predio'
            WHEN V.parcela_id IS NOT NULL THEN N'Parcela'
            WHEN V.parcela_cultivo_id IS NOT NULL THEN N'Cultivo'
            WHEN V.censo_plantas_id IS NOT NULL THEN N'Censo de plantas'
            WHEN V.salida_campo_id IS NOT NULL THEN N'Salida de campo'
            WHEN V.visita_tecnica_id IS NOT NULL THEN N'Visita técnica'
            WHEN V.evaluacion_agronomica_id IS NOT NULL THEN N'Evaluación agronómica'
            WHEN V.caso_fitosanitario_id IS NOT NULL THEN N'Caso de sanidad vegetal'
            WHEN V.tratamiento_id IS NOT NULL THEN N'Tratamiento sanitario'
            WHEN V.seguimiento_fitosanitario_id IS NOT NULL THEN N'Seguimiento sanitario'
            WHEN V.disponibilidad_produccion_id IS NOT NULL THEN N'Producción disponible'
            WHEN V.campania_venta_id IS NOT NULL THEN N'Campaña de venta'
            WHEN V.precio_comercial_id IS NOT NULL THEN N'Precio comercial'
            WHEN V.participacion_campania_socio_id IS NOT NULL THEN N'Participación en campaña'
            WHEN V.operativo_venta_id IS NOT NULL THEN N'Operativo de venta'
            WHEN V.jaba_asignacion_id IS NOT NULL THEN N'Asignación de jabas'
            WHEN V.jaba_devolucion_id IS NOT NULL THEN N'Devolución de jabas'
            WHEN V.entrega_socio_id IS NOT NULL THEN N'Entrega del socio'
            WHEN V.incidencia_operativa_id IS NOT NULL THEN N'Incidencia operativa'
            WHEN V.ajuste_precio_socio_id IS NOT NULL THEN N'Ajuste de precio'
            WHEN V.bien_inventario_id IS NOT NULL THEN N'Bien de inventario'
            WHEN V.recurso_programado_id IS NOT NULL THEN N'Recurso programado'
            WHEN V.gasto_campania_id IS NOT NULL THEN N'Gasto de campaña'
            WHEN V.liquidacion_socio_id IS NOT NULL THEN N'Liquidación'
            WHEN V.pago_socio_id IS NOT NULL THEN N'Pago al socio'
            WHEN V.cobro_comprador_id IS NOT NULL THEN N'Cobro del comprador'
            ELSE N'Sin contexto'
        END tipoContexto,
        COALESCE
        (
            V.socio_id,V.empleado_id,V.predio_id,V.parcela_id,V.parcela_cultivo_id,V.censo_plantas_id,
            V.salida_campo_id,V.visita_tecnica_id,V.evaluacion_agronomica_id,V.caso_fitosanitario_id,
            V.tratamiento_id,V.seguimiento_fitosanitario_id,V.disponibilidad_produccion_id,
            V.campania_venta_id,V.precio_comercial_id,V.participacion_campania_socio_id,V.operativo_venta_id,
            V.jaba_asignacion_id,V.jaba_devolucion_id,V.entrega_socio_id,V.incidencia_operativa_id,
            V.ajuste_precio_socio_id,V.bien_inventario_id,V.recurso_programado_id,V.gasto_campania_id,
            V.liquidacion_socio_id,V.pago_socio_id,V.cobro_comprador_id
        ) contextoId,
        COUNT_BIG(*) OVER() totalRegistros
    FROM [archivo].[Archivo] A
    INNER JOIN [seg].[Usuario] U
        ON U.usuario_id=A.usuario_id
    OUTER APPLY
    (
        SELECT TOP(1) AV.*
        FROM [archivo].[ArchivoVinculo] AV
        WHERE AV.archivo_id=A.archivo_id
          AND AV.estado=1
        ORDER BY AV.archivo_vinculo_id
    ) V
    WHERE A.estado=1
      AND (@cTipo IS NULL OR A.tipo_evidencia=@cTipo)
      AND (@cOrigen IS NULL OR A.origen_captura=@cOrigen)
      AND (@nUsuarioFiltro IS NULL OR A.usuario_id=@nUsuarioFiltro)
      AND (@dDesde IS NULL OR A.fecha_carga>=@dDesde)
      AND (@dHasta IS NULL OR A.fecha_carga<=@dHasta)
      AND (
            (V.socio_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PRODUCTORES_LISTAR','PRODUCTORES_VER')))
         OR (V.empleado_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('EMPLEADOS_LISTAR','EMPLEADOS_VER')))
         OR (V.predio_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PREDIOS_LISTAR','PREDIOS_VER')))
         OR ((V.parcela_id IS NOT NULL OR V.parcela_cultivo_id IS NOT NULL) AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('CULTIVOS_LISTAR','CULTIVOS_VER')))
         OR (V.censo_plantas_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('CENSOS_LISTAR','CENSOS_VER')))
         OR (V.salida_campo_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('SALIDAS_LISTAR','SALIDAS_VER')))
         OR (V.visita_tecnica_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('VISITAS_LISTAR','VISITAS_VER')))
         OR (V.evaluacion_agronomica_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('EVALUACIONES_LISTAR','EVALUACIONES_VER')))
         OR ((V.caso_fitosanitario_id IS NOT NULL OR V.tratamiento_id IS NOT NULL OR V.seguimiento_fitosanitario_id IS NOT NULL) AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('SANIDAD_LISTAR','SANIDAD_VER')))
         OR (V.disponibilidad_produccion_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PRODUCCION_LISTAR','PRODUCCION_VER')))
         OR (V.campania_venta_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('CAMPANIAS_LISTAR','CAMPANIAS_VER')))
         OR (V.precio_comercial_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PRECIOS_LISTAR','PRECIOS_VER')))
         OR (V.participacion_campania_socio_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PARTICIPANTES_LISTAR','PARTICIPANTES_VER')))
         OR (V.operativo_venta_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('OPERATIVOS_LISTAR','OPERATIVOS_VER')))
         OR ((V.jaba_asignacion_id IS NOT NULL OR V.jaba_devolucion_id IS NOT NULL) AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('JABAS_LISTAR','JABAS_VER')))
         OR (V.entrega_socio_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('ENTREGAS_LISTAR','ENTREGAS_VER')))
         OR (V.incidencia_operativa_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('INCIDENCIAS_LISTAR','INCIDENCIAS_VER')))
         OR (V.ajuste_precio_socio_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('AJUSTES_LISTAR','AJUSTES_VER')))
         OR (V.bien_inventario_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('INVENTARIO_LISTAR','INVENTARIO_VER')))
         OR (V.recurso_programado_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('RECURSOS_LISTAR','RECURSOS_VER')))
         OR (V.gasto_campania_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('GASTOS_LISTAR','GASTOS_VER')))
         OR (V.liquidacion_socio_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('LIQUIDACIONES_LISTAR','LIQUIDACIONES_VER')))
         OR (V.pago_socio_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PAGOS_LISTAR','PAGOS_VER')))
         OR (V.cobro_comprador_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('COBROS_LISTAR','COBROS_VER')))
        )
      AND
      (
          @cContexto IS NULL
          OR (@cContexto='SOCIO' AND V.socio_id=@nContextoId)
          OR (@cContexto='EMPLEADO' AND V.empleado_id=@nContextoId)
          OR (@cContexto='PREDIO' AND V.predio_id=@nContextoId)
          OR (@cContexto='PARCELA' AND V.parcela_id=@nContextoId)
          OR (@cContexto='CULTIVO' AND V.parcela_cultivo_id=@nContextoId)
          OR (@cContexto='CENSO' AND V.censo_plantas_id=@nContextoId)
          OR (@cContexto='SALIDA' AND V.salida_campo_id=@nContextoId)
          OR (@cContexto='VISITA' AND V.visita_tecnica_id=@nContextoId)
          OR (@cContexto='EVALUACION' AND V.evaluacion_agronomica_id=@nContextoId)
          OR (@cContexto='CASO_SANIDAD' AND V.caso_fitosanitario_id=@nContextoId)
          OR (@cContexto='TRATAMIENTO' AND V.tratamiento_id=@nContextoId)
          OR (@cContexto='SEGUIMIENTO' AND V.seguimiento_fitosanitario_id=@nContextoId)
          OR (@cContexto='PRODUCCION' AND V.disponibilidad_produccion_id=@nContextoId)
          OR (@cContexto='CAMPANIA' AND V.campania_venta_id=@nContextoId)
          OR (@cContexto='PRECIO' AND V.precio_comercial_id=@nContextoId)
          OR (@cContexto='PARTICIPANTE' AND V.participacion_campania_socio_id=@nContextoId)
          OR (@cContexto='OPERATIVO' AND V.operativo_venta_id=@nContextoId)
          OR (@cContexto='JABA_ASIGNACION' AND V.jaba_asignacion_id=@nContextoId)
          OR (@cContexto='JABA_DEVOLUCION' AND V.jaba_devolucion_id=@nContextoId)
          OR (@cContexto='ENTREGA' AND V.entrega_socio_id=@nContextoId)
          OR (@cContexto='INCIDENCIA' AND V.incidencia_operativa_id=@nContextoId)
          OR (@cContexto='AJUSTE' AND V.ajuste_precio_socio_id=@nContextoId)
          OR (@cContexto='BIEN' AND V.bien_inventario_id=@nContextoId)
          OR (@cContexto='RECURSO' AND V.recurso_programado_id=@nContextoId)
          OR (@cContexto='GASTO' AND V.gasto_campania_id=@nContextoId)
          OR (@cContexto='LIQUIDACION' AND V.liquidacion_socio_id=@nContextoId)
          OR (@cContexto='PAGO' AND V.pago_socio_id=@nContextoId)
          OR (@cContexto='COBRO' AND V.cobro_comprador_id=@nContextoId)
      )
    ORDER BY A.fecha_carga DESC,A.archivo_id DESC
    OFFSET @nOffset ROWS FETCH NEXT @nTam ROWS ONLY;

    SET @bResultado=1;
    SET @cMensaje=N'Documentos consultados correctamente.';

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'archivo.PA_Archivo_Sel_Listado',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'archivo.PA_Archivo_Sel_Listado',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'archivo.PA_Archivo_Sel_Listado',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- archivo.PA_Archivo_Upd_Retirar
CREATE OR ALTER PROCEDURE [archivo].[PA_Archivo_Upd_Retirar]
(
    @cJson NVARCHAR(MAX),
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,
        @gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),
        @nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),
        @bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),
        @nAud BIGINT,@nTrans BIGINT,@nId BIGINT,@cMotivo NVARCHAR(300),@cIdent NVARCHAR(200);

    SELECT @bResultado=0,@cMensaje=N'No se pudo retirar el documento.';

    EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente]
        @cJson=@cJson,@cCodigoPermiso='ARCHIVOS_RETIRAR',@cAmbito='ARCHIVO_RETIRAR',
        @nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,
        @nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,
        @nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,
        @cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@nOperacionIdempotenteId=@nOp OUTPUT,
        @bEsRepetida=@bRep OUTPUT,@cEstadoOperacion=@cEstadoOp OUTPUT,
        @cIdentificadorResultado=@cIdRes OUTPUT,@cCodigoResultado=@cCodRes OUTPUT,
        @bResultado=@bIni OUTPUT,@cMensaje=@cMsg OUTPUT;

    IF @bIni=0 AND @bRep=0
    BEGIN
        SET @cMensaje=@cMsg;
        GOTO __DESCO_Salida;
    END;

    IF @bRep=1
    BEGIN
        SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
        SET @cMensaje=CASE
            WHEN @cEstadoOp='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.'
            ELSE N'La solicitud ya se encuentra en proceso.'
        END;
        GOTO __DESCO_Salida;
    END;

    SELECT
        @nId=archivoId,
        @cMotivo=NULLIF(LTRIM(RTRIM(motivo)),N'')
    FROM OPENJSON(@cJson,'$.archivo')
    WITH
    (
        archivoId BIGINT '$.archivoId',
        motivo NVARCHAR(300) '$.motivo'
    );

    IF @nId IS NULL OR @cMotivo IS NULL
    BEGIN
        SET @cMensaje=N'Seleccione el documento e indique el motivo.';
        GOTO Fallar;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [archivo].[Archivo]
        WHERE archivo_id=@nId
          AND estado=1
    )
    BEGIN
        SET @cMensaje=N'El documento seleccionado no está disponible.';
        GOTO Fallar;
    END;

    DECLARE @PermisosContexto TABLE(codigo VARCHAR(40) NOT NULL PRIMARY KEY);
    INSERT INTO @PermisosContexto(codigo)
    SELECT DISTINCT P.codigo
    FROM [seg].[UsuarioRol] UR
    INNER JOIN [seg].[Rol] R ON R.rol_id=UR.rol_id AND R.estado=1
    INNER JOIN [seg].[RolPermiso] RP ON RP.rol_id=R.rol_id AND RP.estado=1
    INNER JOIN [seg].[Permiso] P ON P.permiso_id=RP.permiso_id AND P.estado=1
    WHERE UR.usuario_id=@nUsuario
      AND UR.estado=1
      AND UR.fecha_desde<=SYSUTCDATETIME()
      AND (UR.fecha_hasta IS NULL OR UR.fecha_hasta>=SYSUTCDATETIME());

    IF NOT EXISTS
    (
        SELECT 1
        FROM [archivo].[ArchivoVinculo] V
        WHERE V.archivo_id=@nId
          AND V.estado=1
          AND (
            (V.socio_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PRODUCTORES_LISTAR','PRODUCTORES_VER')))
         OR (V.empleado_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('EMPLEADOS_LISTAR','EMPLEADOS_VER')))
         OR (V.predio_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PREDIOS_LISTAR','PREDIOS_VER')))
         OR ((V.parcela_id IS NOT NULL OR V.parcela_cultivo_id IS NOT NULL) AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('CULTIVOS_LISTAR','CULTIVOS_VER')))
         OR (V.censo_plantas_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('CENSOS_LISTAR','CENSOS_VER')))
         OR (V.salida_campo_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('SALIDAS_LISTAR','SALIDAS_VER')))
         OR (V.visita_tecnica_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('VISITAS_LISTAR','VISITAS_VER')))
         OR (V.evaluacion_agronomica_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('EVALUACIONES_LISTAR','EVALUACIONES_VER')))
         OR ((V.caso_fitosanitario_id IS NOT NULL OR V.tratamiento_id IS NOT NULL OR V.seguimiento_fitosanitario_id IS NOT NULL) AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('SANIDAD_LISTAR','SANIDAD_VER')))
         OR (V.disponibilidad_produccion_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PRODUCCION_LISTAR','PRODUCCION_VER')))
         OR (V.campania_venta_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('CAMPANIAS_LISTAR','CAMPANIAS_VER')))
         OR (V.precio_comercial_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PRECIOS_LISTAR','PRECIOS_VER')))
         OR (V.participacion_campania_socio_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PARTICIPANTES_LISTAR','PARTICIPANTES_VER')))
         OR (V.operativo_venta_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('OPERATIVOS_LISTAR','OPERATIVOS_VER')))
         OR ((V.jaba_asignacion_id IS NOT NULL OR V.jaba_devolucion_id IS NOT NULL) AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('JABAS_LISTAR','JABAS_VER')))
         OR (V.entrega_socio_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('ENTREGAS_LISTAR','ENTREGAS_VER')))
         OR (V.incidencia_operativa_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('INCIDENCIAS_LISTAR','INCIDENCIAS_VER')))
         OR (V.ajuste_precio_socio_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('AJUSTES_LISTAR','AJUSTES_VER')))
         OR (V.bien_inventario_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('INVENTARIO_LISTAR','INVENTARIO_VER')))
         OR (V.recurso_programado_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('RECURSOS_LISTAR','RECURSOS_VER')))
         OR (V.gasto_campania_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('GASTOS_LISTAR','GASTOS_VER')))
         OR (V.liquidacion_socio_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('LIQUIDACIONES_LISTAR','LIQUIDACIONES_VER')))
         OR (V.pago_socio_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('PAGOS_LISTAR','PAGOS_VER')))
         OR (V.cobro_comprador_id IS NOT NULL AND EXISTS(SELECT 1 FROM @PermisosContexto WHERE codigo IN('COBROS_LISTAR','COBROS_VER')))
        )
    )
    BEGIN
        SET @cMensaje=N'El documento seleccionado no está disponible dentro de su contexto autorizado.';
        GOTO Fallar;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM [archivo].[ArchivoVinculo] V
        LEFT JOIN [campo].[SalidaCampo] SC
            ON SC.salida_campo_id=V.salida_campo_id
        LEFT JOIN [campo].[VisitaTecnica] VT
            ON VT.visita_tecnica_id=V.visita_tecnica_id
        LEFT JOIN [campo].[EvaluacionAgronomica] EA
            ON EA.evaluacion_agronomica_id=V.evaluacion_agronomica_id
        LEFT JOIN [campo].[VisitaTecnica] VEA
            ON VEA.visita_tecnica_id=EA.visita_tecnica_id
        LEFT JOIN [sanidad].[CasoFitosanitario] CF
            ON CF.caso_fitosanitario_id=V.caso_fitosanitario_id
        LEFT JOIN [sanidad].[TratamientoFitosanitario] TF
            ON TF.tratamiento_fitosanitario_id=V.tratamiento_id
        LEFT JOIN [sanidad].[CasoFitosanitario] CFT
            ON CFT.caso_fitosanitario_id=TF.caso_fitosanitario_id
        LEFT JOIN [sanidad].[SeguimientoFitosanitario] SF
            ON SF.seguimiento_fitosanitario_id=V.seguimiento_fitosanitario_id
        LEFT JOIN [sanidad].[CasoFitosanitario] CFS
            ON CFS.caso_fitosanitario_id=SF.caso_fitosanitario_id
        LEFT JOIN [prod].[DisponibilidadProduccion] DP
            ON DP.disponibilidad_produccion_id=V.disponibilidad_produccion_id
        LEFT JOIN [prod].[ParcelaCultivo] PCV
            ON PCV.parcela_cultivo_id=V.parcela_cultivo_id
        LEFT JOIN [prod].[CensoPlantas] CEN
            ON CEN.censo_plantas_id=V.censo_plantas_id
        LEFT JOIN [prod].[ParcelaCultivo] PCEN
            ON PCEN.parcela_cultivo_id=CEN.parcela_cultivo_id
        LEFT JOIN [comercial].[EntregaSocio] E
            ON E.entrega_socio_id=V.entrega_socio_id
        LEFT JOIN [finanzas].[GastoCampania] G
            ON G.gasto_campania_id=V.gasto_campania_id
        LEFT JOIN [finanzas].[LiquidacionSocio] L
            ON L.liquidacion_socio_id=V.liquidacion_socio_id
        LEFT JOIN [finanzas].[PagoSocio] P
            ON P.pago_socio_id=V.pago_socio_id
        LEFT JOIN [finanzas].[CobroComprador] C
            ON C.cobro_comprador_id=V.cobro_comprador_id
        WHERE V.archivo_id=@nId
          AND V.estado=1
          AND
          (
              SC.estado_proceso IN('FINALIZADA','CANCELADA')
              OR VT.estado_proceso IN('FINALIZADA','ANULADA')
              OR VEA.estado_proceso IN('FINALIZADA','ANULADA')
              OR CF.estado_caso='CERRADO'
              OR CFT.estado_caso='CERRADO'
              OR CFS.estado_caso='CERRADO'
              OR DP.estado_estimacion IN('CONFIRMADA','DESCARTADA')
              OR PCV.situacion_cultivo IN('FINALIZADO','ABANDONADO')
              OR PCEN.situacion_cultivo IN('FINALIZADO','ABANDONADO')
              OR E.estado_proceso='CONFIRMADA'
              OR G.estado_proceso='APROBADO'
              OR L.estado_proceso IN('APROBADA','PAGADA_PARCIAL','PAGADA')
              OR P.estado_proceso='CONFIRMADO'
              OR C.estado_proceso='CONFIRMADO'
          )
    )
    BEGIN
        SET @cMensaje=N'El documento forma parte de un registro ya cerrado o confirmado y debe conservarse como evidencia.';
        GOTO Fallar;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM [archivo].[ArchivoVinculo] V
        LEFT JOIN [comercial].[CampaniaVenta] CA ON CA.campania_venta_id=V.campania_venta_id
        LEFT JOIN [comercial].[PrecioComercial] PR ON PR.precio_comercial_id=V.precio_comercial_id
        LEFT JOIN [comercial].[CampaniaVenta] CAPR ON CAPR.campania_venta_id=PR.campania_venta_id
        LEFT JOIN [comercial].[ParticipacionCampaniaSocio] PCS ON PCS.participacion_campania_socio_id=V.participacion_campania_socio_id
        LEFT JOIN [comercial].[CampaniaVenta] CAPS ON CAPS.campania_venta_id=PCS.campania_venta_id
        LEFT JOIN [comercial].[OperativoVenta] OV ON OV.operativo_venta_id=V.operativo_venta_id
        LEFT JOIN [comercial].[JabaAsignacion] JA ON JA.jaba_asignacion_id=V.jaba_asignacion_id
        LEFT JOIN [comercial].[OperativoSocio] OSA ON OSA.operativo_socio_id=JA.operativo_socio_id
        LEFT JOIN [comercial].[OperativoVenta] OVA ON OVA.operativo_venta_id=OSA.operativo_venta_id
        LEFT JOIN [comercial].[JabaDevolucion] JD ON JD.jaba_devolucion_id=V.jaba_devolucion_id
        LEFT JOIN [comercial].[JabaAsignacion] JDA ON JDA.jaba_asignacion_id=JD.jaba_asignacion_id
        LEFT JOIN [comercial].[OperativoSocio] OSJ ON OSJ.operativo_socio_id=JDA.operativo_socio_id
        LEFT JOIN [comercial].[OperativoVenta] OVJ ON OVJ.operativo_venta_id=OSJ.operativo_venta_id
        LEFT JOIN [comercial].[EntregaSocio] EN ON EN.entrega_socio_id=V.entrega_socio_id
        LEFT JOIN [comercial].[IncidenciaOperativa] IO ON IO.incidencia_operativa_id=V.incidencia_operativa_id
        LEFT JOIN [comercial].[AjustePrecioSocio] AP ON AP.ajuste_precio_socio_id=V.ajuste_precio_socio_id
        LEFT JOIN [finanzas].[GastoCampania] GC ON GC.gasto_campania_id=V.gasto_campania_id
        LEFT JOIN [finanzas].[LiquidacionSocio] LS ON LS.liquidacion_socio_id=V.liquidacion_socio_id
        LEFT JOIN [finanzas].[PagoSocio] PS ON PS.pago_socio_id=V.pago_socio_id
        LEFT JOIN [finanzas].[CobroComprador] CB ON CB.cobro_comprador_id=V.cobro_comprador_id
        WHERE V.archivo_id=@nId
          AND V.estado=1
          AND
          (
              CA.estado_proceso IN('CERRADA','CANCELADA')
              OR PR.estado=0 OR CAPR.estado_proceso IN('CERRADA','CANCELADA')
              OR PCS.estado_participacion IN('RETIRADO','EXCLUIDO') OR CAPS.estado_proceso IN('CERRADA','CANCELADA')
              OR OV.estado_proceso IN('CERRADO','CANCELADO')
              OR JA.estado=0 OR OVA.estado_proceso IN('CERRADO','CANCELADO')
              OR JD.estado=0 OR OVJ.estado_proceso IN('CERRADO','CANCELADO')
              OR EN.estado_proceso='ANULADA'
              OR IO.estado_incidencia IN('RESUELTA','ANULADA')
              OR AP.estado_ajuste='ANULADO'
              OR GC.estado_proceso='ANULADO'
              OR LS.estado_proceso='ANULADA'
              OR PS.estado_proceso='ANULADO'
              OR CB.estado_proceso='ANULADO'
          )
    )
    BEGIN
        SET @cMensaje=N'El documento forma parte de un registro cerrado, resuelto o anulado y debe conservarse como evidencia.';
        GOTO Fallar;
    END;

    BEGIN TRY
        BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

        UPDATE [archivo].[Archivo]
        SET estado=0,
            fecha_retiro=SYSUTCDATETIME(),
            usuario_retiro_id=@nUsuario,
            retirado_por_usuario_id=@nUsuario,
            motivo_retiro=@cMotivo
        WHERE archivo_id=@nId
          AND estado=1;

        UPDATE [archivo].[ArchivoVinculo]
        SET estado=0
        WHERE archivo_id=@nId
          AND estado=1;

        SET @cIdent=CONVERT(NVARCHAR(200),@nId);

        EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio]
            @nUsuario,@nSesion,@nDisp,@nModulo,'RETIRAR','archivo','Archivo',
            @cIdent,NULL,NULL,@cMotivo,'estado','1','0',
            @cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;

        /* Confirmar datos e idempotencia juntos. */

        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
            @nOperacionIdempotenteId=@nOp,
            @cEstadoOperacion='COMPLETADA',
            @cEsquemaEntidad='archivo',
            @cNombreEntidad='Archivo',
            @cIdentificadorResultado=@cIdent,
            @cCodigoResultado='ARCHIVO_RETIRADO',
            @bResultado=@bFin OUTPUT,
            @cMensaje=@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;

        SET @bResultado=1;
        SET @cMensaje=N'Documento retirado correctamente.';
        GOTO __DESCO_Salida;
    END TRY
    BEGIN CATCH
SET @bResultado = 0;

        IF XACT_STATE()<>0
            BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;

        SET @cMensaje=N'No se pudo retirar el documento. Intente nuevamente.';
    
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'archivo.PA_Archivo_Upd_Retirar',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;

Fallar:
    IF @nOp IS NOT NULL AND @bResultado=0
        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
            @nOperacionIdempotenteId=@nOp,
            @cEstadoOperacion='FALLIDA',
            @cEsquemaEntidad=NULL,
            @cNombreEntidad=NULL,
            @cIdentificadorResultado=NULL,
            @cCodigoResultado='NO_PROCESADO',
            @bResultado=@bFin OUTPUT,
            @cMensaje=@cMsgFin OUTPUT;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'archivo.PA_Archivo_Upd_Retirar',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

    IF @bResultado = 0 AND @nOp IS NOT NULL AND XACT_STATE() <> -1
    BEGIN
        IF ISNULL(@bRep,0) = 0
        BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                 @nOperacionIdempotenteId = @nOp, @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
            -- No sustituir el motivo funcional por un fallo de registro secundario.
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'archivo.PA_Archivo_Upd_Retirar',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
        END CATCH;
        END
        ELSE
        BEGIN
            SELECT @cMensaje = COALESCE(mensaje_resultado,
                CASE WHEN estado_operacion = 'FALLIDA'
                     THEN N'La solicitud anterior no se completó. Corrija los datos y envíe una nueva solicitud.'
                     ELSE N'La solicitud todavía se está procesando. Consulte el resultado antes de repetirla.' END)
            FROM [auditoria].[OperacionIdempotente]
            WHERE operacion_idempotente_id = @nOp;
        END;
    END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'archivo.PA_Archivo_Upd_Retirar',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'archivo.PA_Archivo_Upd_Retirar',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- auditoria.PA_Auditoria_Ins_Evento
CREATE OR ALTER PROCEDURE [auditoria].[PA_Auditoria_Ins_Evento]
(
    @nUsuarioId                 BIGINT = NULL,
    @nSesionUsuarioId           BIGINT = NULL,
    @nDispositivoUsuarioId      BIGINT = NULL,
    @nModuloId                  INT = NULL,
    @cAccion                    VARCHAR(40),
    @cEsquemaEntidad            SYSNAME,
    @cNombreEntidad             SYSNAME,
    @cIdentificador             NVARCHAR(200),
    @cDatosAnteriores           NVARCHAR(MAX) = NULL,
    @cDatosPosteriores          NVARCHAR(MAX) = NULL,
    @cMotivo                    NVARCHAR(500) = NULL,
    @cIp                        VARCHAR(64) = NULL,
    @cDispositivo               NVARCHAR(200) = NULL,
    @cResultado                 VARCHAR(20) = NULL,
    @gCorrelacionId             UNIQUEIDENTIFIER = NULL,
    @gSolicitudId               UNIQUEIDENTIFIER = NULL,
    @cEndpoint                  NVARCHAR(250) = NULL,
    @nAuditoriaEventoId         BIGINT OUTPUT,
    @bResultado BIT=NULL OUTPUT,
    @cMensaje NVARCHAR(300)=NULL OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    SET @bResultado=0;
BEGIN TRY

    /* DESCO_SEGURIDAD_V2_20260825 */
    SET NOCOUNT ON;

    SET @nAuditoriaEventoId = NULL;

    SET @cAccion = NULLIF(LTRIM(RTRIM(@cAccion)), '');
    SET @cEsquemaEntidad = NULLIF(LTRIM(RTRIM(@cEsquemaEntidad)), '');
    SET @cNombreEntidad = NULLIF(LTRIM(RTRIM(@cNombreEntidad)), '');
    SET @cIdentificador = NULLIF(LTRIM(RTRIM(@cIdentificador)), '');
    SET @cResultado = NULLIF(UPPER(LTRIM(RTRIM(@cResultado))), '');

    IF @cAccion IS NULL
       OR @cEsquemaEntidad IS NULL
       OR @cNombreEntidad IS NULL
       OR @cIdentificador IS NULL
    BEGIN
        THROW 52100, N'No se pudo registrar la trazabilidad de la operacion.', 1;
    END;

    IF @cResultado IS NOT NULL
       AND @cResultado NOT IN ('EXITOSO','RECHAZADO','ERROR_CONTROLADO')
    BEGIN
        SET @cResultado = 'ERROR_CONTROLADO';
    END;

    IF @cDatosAnteriores IS NOT NULL
       AND ISJSON(@cDatosAnteriores) <> 1
    BEGIN
        SET @cDatosAnteriores = NULL;
    END;

    IF @cDatosPosteriores IS NOT NULL
       AND ISJSON(@cDatosPosteriores) <> 1
    BEGIN
        SET @cDatosPosteriores = NULL;
    END;

    /*
       Defensa adicional:
       para entidades de autenticacion nunca se persiste payload antes/despues.
       La trazabilidad conserva evento, actor, fecha, resultado y contexto.
    */
    IF LOWER(@cEsquemaEntidad) = N'seg'
       AND LOWER(@cNombreEntidad) IN
       (
           N'usuario',
           N'codigounsolouso',
           N'refreshtokensesion',
           N'tokenaccesorevocado',
           N'historialpassword',
           N'sesionusuario'
       )
    BEGIN
        SET @cDatosAnteriores = NULL;
        SET @cDatosPosteriores = NULL;
    END;

    INSERT INTO [auditoria].[AuditoriaEvento]
    (
        [usuario_id],
        [modulo_id],
        [fecha_hora],
        [accion],
        [esquema_entidad],
        [nombre_entidad],
        [identificador],
        [datos_anteriores],
        [datos_posteriores],
        [motivo],
        [ip],
        [dispositivo],
        [estado],
        [sesion_usuario_id],
        [dispositivo_usuario_id],
        [correlacion_id],
        [solicitud_id],
        [resultado],
        [endpoint]
    )
    VALUES
    (
        @nUsuarioId,
        @nModuloId,
        SYSUTCDATETIME(),
        @cAccion,
        @cEsquemaEntidad,
        @cNombreEntidad,
        @cIdentificador,
        @cDatosAnteriores,
        @cDatosPosteriores,
        @cMotivo,
        NULLIF(LTRIM(RTRIM(@cIp)), ''),
        @cDispositivo,
        1,
        @nSesionUsuarioId,
        @nDispositivoUsuarioId,
        @gCorrelacionId,
        @gSolicitudId,
        @cResultado,
        @cEndpoint
    );

    SET @nAuditoriaEventoId = SCOPE_IDENTITY();

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'auditoria.PA_Auditoria_Ins_Evento',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
SET @bResultado=0; SET @cMensaje=@__DbMensaje;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'auditoria.PA_Auditoria_Ins_Evento',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
SET @bResultado=0; SET @cMensaje=@__DbMensaje;
END CATCH;
SET @bResultado=CASE WHEN @__DbError=0 AND @nAuditoriaEventoId IS NOT NULL THEN 1 ELSE 0 END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'auditoria.PA_Auditoria_Ins_Evento',@bResultado,@cMensaje) R;
IF @bResultado=0 AND @@NESTLEVEL>1 THROW 51000,@cMensaje,1;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- auditoria.PA_Auditoria_Ins_TransicionEstado
CREATE OR ALTER PROCEDURE [auditoria].[PA_Auditoria_Ins_TransicionEstado]
(
    @nUsuarioId                 BIGINT = NULL,
    @nSesionUsuarioId           BIGINT = NULL,
    @nDispositivoUsuarioId      BIGINT = NULL,
    @nModuloId                  INT = NULL,
    @cEsquemaEntidad            SYSNAME,
    @cNombreEntidad             SYSNAME,
    @cIdentificador             NVARCHAR(200),
    @cCampoEstado               SYSNAME,
    @cEstadoAnterior            VARCHAR(40) = NULL,
    @cEstadoNuevo               VARCHAR(40),
    @cMotivo                    NVARCHAR(500) = NULL,
    @cIp                        VARCHAR(64) = NULL,
    @gCorrelacionId             UNIQUEIDENTIFIER = NULL,
    @nTransicionEstadoId        BIGINT OUTPUT,
    @bResultado BIT=NULL OUTPUT,
    @cMensaje NVARCHAR(300)=NULL OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    SET @bResultado=0;
BEGIN TRY

    /* DESCO_SEGURIDAD_V2_20260825 */
    SET NOCOUNT ON;

    DECLARE @nAuditoriaEventoId BIGINT;
    DECLARE @cAntes NVARCHAR(MAX);
    DECLARE @cDespues NVARCHAR(MAX);

    SET @nTransicionEstadoId = NULL;

    SET @cEsquemaEntidad = NULLIF(LTRIM(RTRIM(@cEsquemaEntidad)), '');
    SET @cNombreEntidad = NULLIF(LTRIM(RTRIM(@cNombreEntidad)), '');
    SET @cIdentificador = NULLIF(LTRIM(RTRIM(@cIdentificador)), '');
    SET @cCampoEstado = NULLIF(LTRIM(RTRIM(@cCampoEstado)), '');
    SET @cEstadoAnterior = NULLIF(LTRIM(RTRIM(@cEstadoAnterior)), '');
    SET @cEstadoNuevo = NULLIF(LTRIM(RTRIM(@cEstadoNuevo)), '');

    IF @cEsquemaEntidad IS NULL
       OR @cNombreEntidad IS NULL
       OR @cIdentificador IS NULL
       OR @cCampoEstado IS NULL
       OR @cEstadoNuevo IS NULL
    BEGIN
        THROW 52110, N'No se pudo registrar el cambio de estado.', 1;
    END;

    INSERT INTO [auditoria].[TransicionEstado]
    (
        [usuario_id],
        [sesion_usuario_id],
        [dispositivo_usuario_id],
        [modulo_id],
        [fecha_hora],
        [esquema_entidad],
        [nombre_entidad],
        [identificador],
        [campo_estado],
        [estado_anterior],
        [estado_nuevo],
        [motivo],
        [correlacion_id],
        [estado]
    )
    VALUES
    (
        @nUsuarioId,
        @nSesionUsuarioId,
        @nDispositivoUsuarioId,
        @nModuloId,
        SYSUTCDATETIME(),
        @cEsquemaEntidad,
        @cNombreEntidad,
        @cIdentificador,
        @cCampoEstado,
        @cEstadoAnterior,
        @cEstadoNuevo,
        @cMotivo,
        @gCorrelacionId,
        1
    );

    SET @nTransicionEstadoId = SCOPE_IDENTITY();

    SELECT @cAntes =
    (
        SELECT
            @cCampoEstado AS campo,
            @cEstadoAnterior AS valor
        FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    SELECT @cDespues =
    (
        SELECT
            @cCampoEstado AS campo,
            @cEstadoNuevo AS valor
        FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
    );

    EXEC [auditoria].[PA_Auditoria_Ins_Evento]
         @nUsuarioId = @nUsuarioId,
         @nSesionUsuarioId = @nSesionUsuarioId,
         @nDispositivoUsuarioId = @nDispositivoUsuarioId,
         @nModuloId = @nModuloId,
         @cAccion = 'CAMBIO_ESTADO',
         @cEsquemaEntidad = @cEsquemaEntidad,
         @cNombreEntidad = @cNombreEntidad,
         @cIdentificador = @cIdentificador,
         @cDatosAnteriores = @cAntes,
