 SET XACT_ABORT ON;
    DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),@nSalida BIGINT,@dRetorno DATETIME2(0),@cMotivo NVARCHAR(500),@dInicio DATETIME2(0),@cAnt NVARCHAR(MAX),@cPost NVARCHAR(MAX),@cIdent NVARCHAR(200),@nAud BIGINT,@nTrans BIGINT;
    SET @bResultado=0;
 SET @cMensaje=N'No se pudo finalizar la salida.';
    EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente] @cJson,'SALIDAS_CONFIRMAR','SALIDA_FINALIZAR',@nUsuario OUTPUT,@nSesion OUTPUT,@nDisp OUTPUT,@nEmp OUTPUT,@nModulo OUTPUT,@gCorr OUTPUT,@gSol OUTPUT,@cIp OUTPUT,@cEnd OUTPUT,@nOp OUTPUT,@bRep OUTPUT,@cEstadoOp OUTPUT,@cIdRes OUTPUT,@cCodRes OUTPUT,@bIni OUTPUT,@cMsg OUTPUT;
    IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
 GOTO __DESCO_Salida;
 END;
 IF @bRep=1 BEGIN IF @cEstadoOp='COMPLETADA' BEGIN SET @bResultado=1;
 SET @cMensaje=N'La solicitud ya fue procesada correctamente.';
 END ELSE SET @cMensaje=N'La solicitud ya se encuentra en proceso.';
 GOTO __DESCO_Salida;
 END;
    SELECT @nSalida=salidaCampoId,@dRetorno=fechaHoraRetornoReal,@cMotivo=NULLIF(LTRIM(RTRIM(motivo)),N'') FROM OPENJSON(@cJson,'$.salida') WITH (salidaCampoId BIGINT '$.salidaCampoId',fechaHoraRetornoReal DATETIME2(0) '$.fechaHoraRetornoReal',motivo NVARCHAR(500) '$.motivo');
 IF @dRetorno IS NULL SET @dRetorno=SYSUTCDATETIME();
    SELECT @dInicio=fecha_hora_salida_real FROM [campo].[SalidaCampo] WHERE salida_campo_id=@nSalida AND estado=1 AND estado_proceso='EN_CURSO';
 IF @dInicio IS NULL BEGIN SET @cMensaje=N'La salida debe estar en curso antes de finalizarla.';
 GOTO Fallar;
 END;
 IF @dRetorno<@dInicio BEGIN SET @cMensaje=N'La hora de retorno no es válida.';
 GOTO Fallar;
 END;
    IF EXISTS(SELECT 1 FROM [campo].[VisitaTecnica] V INNER JOIN [campo].[SalidaParticipante] SP ON SP.salida_participante_id=V.salida_participante_id WHERE SP.salida_campo_id=@nSalida AND V.estado=1 AND V.estado_proceso='INICIADA') BEGIN SET @cMensaje=N'Finalice las visitas que aún están en curso antes de cerrar la salida.';
 GOTO Fallar;
 END;
    BEGIN TRY BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;
      SELECT @cAnt=(SELECT * FROM [campo].[SalidaCampo] WHERE salida_campo_id=@nSalida FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
 UPDATE [campo].[SalidaCampo] SET fecha_hora_retorno_real=@dRetorno,estado_proceso='FINALIZADA' WHERE salida_campo_id=@nSalida AND estado=1 AND estado_proceso='EN_CURSO';
 SELECT @cPost=(SELECT * FROM [campo].[SalidaCampo] WHERE salida_campo_id=@nSalida FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
 SET @cIdent=CONVERT(NVARCHAR(200),@nSalida);
      EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio] @nUsuario,@nSesion,@nDisp,@nModulo,'FINALIZAR','campo','SalidaCampo',@cIdent,@cAnt,@cPost,@cMotivo,'estado_proceso','EN_CURSO','FINALIZADA',@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
 /* Confirmar datos e idempotencia juntos. */
      EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar] @nOp,'COMPLETADA','campo','SalidaCampo',@cIdent,'SALIDA_FINALIZADA',@bFin OUTPUT,@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
 SET @bResultado=1;
 SET @cMensaje=N'Salida finalizada correctamente.';
 GOTO __DESCO_Salida;
    END TRY BEGIN CATCH
SET @bResultado = 0;
 IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
