        SET @__DbTranAbierta = 0;
    END;
END;
 SET @cMensaje=N'No se pudo finalizar la salida. Intente nuevamente.';
 
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'campo.PA_SalidaCampo_Upd_Finalizar',
