-- campo.PA_VisitaTecnica_Upd_Registro
CREATE OR ALTER PROCEDURE [campo].[PA_VisitaTecnica_Upd_Registro]
(
    @cJson NVARCHAR(MAX), @bResultado BIT OUTPUT, @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;
 SET XACT_ABORT ON;
    DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,
            @gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),
            @nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),
            @bFin BIT,@cMsgFin NVARCHAR(300),@nVisita BIGINT,@cObjetivo NVARCHAR(250),@cResumen NVARCHAR(600),
            @cRecomendaciones NVARCHAR(600),@cAnt NVARCHAR(MAX),@cPost NVARCHAR(MAX),@cIdent NVARCHAR(200),@nAud BIGINT,@nTrans BIGINT;
    SET @bResultado=0;
 SET @cMensaje=N'No se pudo actualizar la visita.';
    EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente]
        @cJson,'VISITAS_EDITAR','VISITA_EDITAR',@nUsuario OUTPUT,@nSesion OUTPUT,@nDisp OUTPUT,@nEmp OUTPUT,
        @nModulo OUTPUT,@gCorr OUTPUT,@gSol OUTPUT,@cIp OUTPUT,@cEnd OUTPUT,@nOp OUTPUT,@bRep OUTPUT,
        @cEstadoOp OUTPUT,@cIdRes OUTPUT,@cCodRes OUTPUT,@bIni OUTPUT,@cMsg OUTPUT;
    IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
 GOTO __DESCO_Salida;
 END;
    IF @bRep=1 BEGIN IF @cEstadoOp='COMPLETADA' BEGIN SET @bResultado=1;
 SET @cMensaje=N'La solicitud ya fue procesada correctamente.';
 END ELSE SET @cMensaje=N'La solicitud ya se encuentra en proceso.';
 GOTO __DESCO_Salida;
 END;

    SELECT @nVisita=visitaTecnicaId,@cObjetivo=NULLIF(LTRIM(RTRIM(objetivo)),N''),
           @cResumen=NULLIF(LTRIM(RTRIM(resumen)),N''),@cRecomendaciones=NULLIF(LTRIM(RTRIM(recomendaciones)),N'')
    FROM OPENJSON(@cJson,'$.visita') WITH
    (visitaTecnicaId BIGINT '$.visitaTecnicaId',objetivo NVARCHAR(250) '$.objetivo',
     resumen NVARCHAR(600) '$.resumen',recomendaciones NVARCHAR(600) '$.recomendaciones');
    IF NOT EXISTS(SELECT 1 FROM [campo].[VisitaTecnica] WHERE visita_tecnica_id=@nVisita AND estado=1 AND estado_proceso='INICIADA')
    BEGIN SET @cMensaje=N'Solo las visitas en curso pueden modificarse.';
 GOTO Fallar;
 END;

    BEGIN TRY
      BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;
      SELECT @cAnt=(
          SELECT
              [visita_tecnica_id],
              [salida_participante_id],
              [predio_id],
              [fecha_hora_inicio],
              [fecha_hora_fin],
              CASE WHEN [posicion_inicio] IS NULL THEN NULL ELSE [posicion_inicio].STAsText() END AS [posicion_inicio_wkt],
              CASE WHEN [posicion_inicio] IS NULL THEN NULL ELSE [posicion_inicio].STSrid END AS [posicion_inicio_srid],
              [objetivo],
              [resumen],
              [recomendaciones],
              [estado_proceso],
              [estado]
          FROM [campo].[VisitaTecnica]
          WHERE [visita_tecnica_id]=@nVisita
          FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
      );
      UPDATE [campo].[VisitaTecnica]
      SET objetivo=@cObjetivo,resumen=@cResumen,recomendaciones=@cRecomendaciones
      WHERE visita_tecnica_id=@nVisita AND estado=1 AND estado_proceso='INICIADA';
      SELECT @cPost=(
          SELECT
              [visita_tecnica_id],
              [salida_participante_id],
              [predio_id],
              [fecha_hora_inicio],
              [fecha_hora_fin],
              CASE WHEN [posicion_inicio] IS NULL THEN NULL ELSE [posicion_inicio].STAsText() END AS [posicion_inicio_wkt],
              CASE WHEN [posicion_inicio] IS NULL THEN NULL ELSE [posicion_inicio].STSrid END AS [posicion_inicio_srid],
              [objetivo],
              [resumen],
              [recomendaciones],
              [estado_proceso],
              [estado]
          FROM [campo].[VisitaTecnica]
          WHERE [visita_tecnica_id]=@nVisita
          FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
      );
      SET @cIdent=CONVERT(NVARCHAR(200),@nVisita);
      EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio]
          @nUsuario,@nSesion,@nDisp,@nModulo,'EDITAR','campo','VisitaTecnica',@cIdent,@cAnt,@cPost,NULL,NULL,NULL,NULL,
          @cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
      /* Confirmar datos e idempotencia juntos. */
      EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
          @nOp,'COMPLETADA','campo','VisitaTecnica',@cIdent,'VISITA_ACTUALIZADA',@bFin OUTPUT,@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;

      SET @bResultado=1;
 SET @cMensaje=N'Visita actualizada correctamente.';
 GOTO __DESCO_Salida;
    END TRY
    BEGIN CATCH
SET @bResultado = 0;
 IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
 SET @cMensaje=N'No se pudo actualizar la visita. Intente nuevamente.';
 
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'campo.PA_VisitaTecnica_Upd_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;
Fallar:
    IF @nOp IS NOT NULL AND @bResultado=0
        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar] @nOp,'FALLIDA',NULL,NULL,NULL,'NO_PROCESADO',@bFin OUTPUT,@cMsgFin OUTPUT;

    END TRY
    BEGIN CATCH

