/* ================================================================
   PA_Cliente_Ins_Manual
   ================================================================ */
CREATE OR ALTER PROCEDURE [comercial].[PA_Cliente_Ins_Manual]
    @nUsuarioId BIGINT,@nUotId BIGINT,@cTipoCliente VARCHAR(10),@cTipoDocumento VARCHAR(15),@cNumeroDocumento VARCHAR(30),
    @cNombres NVARCHAR(100)=NULL,@cApellidoPaterno NVARCHAR(80)=NULL,@cApellidoMaterno NVARCHAR(80)=NULL,
    @cRazonSocial NVARCHAR(200)=NULL,@cTelefono VARCHAR(30)=NULL,@cCorreo VARCHAR(180)=NULL,
    @nClientePersonaId BIGINT OUTPUT,@nClienteEmpresaId BIGINT OUTPUT,@bReutilizado BIT OUTPUT,
    @cTipoDocumentoResultado VARCHAR(15) OUTPUT,@cNumeroDocumentoResultado VARCHAR(30) OUTPUT,@cNombreCliente NVARCHAR(220) OUTPUT,
    @bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,@cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    SELECT @nClientePersonaId=NULL,@nClienteEmpresaId=NULL,@bReutilizado=0,@cNombreCliente=NULL,@bResultado=0,
           @cMensaje=N'No se pudo registrar el cliente.',@cCodigoRespuesta='CLIENTE_NO_REGISTRADO',@nHttpRespuesta=400;
    SELECT @cTipoCliente=UPPER(NULLIF(LTRIM(RTRIM(@cTipoCliente)),'')),
           @cTipoDocumento=UPPER(NULLIF(LTRIM(RTRIM(@cTipoDocumento)),'')),
           @cNumeroDocumento=UPPER(NULLIF(LTRIM(RTRIM(@cNumeroDocumento)),'')),
           @cNombres=NULLIF(LTRIM(RTRIM(@cNombres)),N''),@cApellidoPaterno=NULLIF(LTRIM(RTRIM(@cApellidoPaterno)),N''),
           @cApellidoMaterno=NULLIF(LTRIM(RTRIM(@cApellidoMaterno)),N''),@cRazonSocial=NULLIF(LTRIM(RTRIM(@cRazonSocial)),N''),
           @cTelefono=NULLIF(LTRIM(RTRIM(@cTelefono)),''),@cCorreo=LOWER(NULLIF(LTRIM(RTRIM(@cCorreo)),''));
    SELECT @cTipoDocumentoResultado=@cTipoDocumento,@cNumeroDocumentoResultado=@cNumeroDocumento;

    IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotId,'POS_OPERAR')=0
    BEGIN SET @cMensaje=N'No tiene permiso para registrar clientes de una venta.'; SET @cCodigoRespuesta='NO_AUTORIZADO'; SET @nHttpRespuesta=403; RETURN 1; END;
    IF @cTipoCliente NOT IN('PERSONA','EMPRESA') OR @cTipoDocumento NOT IN('DNI','RUC') OR @cNumeroDocumento IS NULL
    BEGIN SET @cMensaje=N'Complete correctamente los datos del cliente.'; RETURN 1; END;
    IF (@cTipoDocumento='DNI' AND (LEN(@cNumeroDocumento)<>8 OR @cNumeroDocumento LIKE '%[^0-9]%'))
       OR (@cTipoDocumento='RUC' AND (LEN(@cNumeroDocumento)<>11 OR @cNumeroDocumento LIKE '%[^0-9]%'))
    BEGIN SET @cMensaje=N'El documento ingresado no es válido.'; RETURN 1; END;

    /*
     * La carga manual es un fallback del flujo POS:
     * DESCO local -> Factiliza -> manual.
     * No se permite saltar la consulta automática invocando este PA directamente.
     */
    DECLARE @cClaveConsulta VARCHAR(60),
            @cEstadoConsulta VARCHAR(25);

    SET @cClaveConsulta =
        CASE
            WHEN @cTipoCliente='EMPRESA'
                THEN 'RUC:' + @cNumeroDocumento
            WHEN @cTipoDocumento='DNI'
                THEN 'DNI:' + @cNumeroDocumento
            WHEN @cTipoDocumento='RUC' AND LEFT(@cNumeroDocumento,2)='10'
                THEN 'DNI:' + SUBSTRING(@cNumeroDocumento,3,8)
            ELSE 'RUC:' + @cNumeroDocumento
        END;

    SELECT TOP(1)
           @cEstadoConsulta=CD.estado_consulta
    FROM integracion.ConsultaDocumento CD
    WHERE CD.entidad_objetivo=@cTipoCliente
      AND CD.clave_documento=@cClaveConsulta
      AND CD.estado=1
    ORDER BY CD.consulta_documento_id DESC;

    IF @cEstadoConsulta IS NULL
       OR @cEstadoConsulta NOT IN('ERROR','NO_ENCONTRADO','DATOS_INSUFICIENTES')
    BEGIN
        SET @cMensaje=N'Busque primero el cliente. La carga manual solo se habilita cuando la validación automática no puede completarse.';
        SET @cCodigoRespuesta='VALIDACION_AUTOMATICA_REQUERIDA';
        SET @nHttpRespuesta=409;
        RETURN 1;
    END;

    BEGIN TRY
      SET TRANSACTION ISOLATION LEVEL SERIALIZABLE; BEGIN TRAN;
      IF @cTipoCliente='PERSONA'
      BEGIN
        IF @cNombres IS NULL OR @cApellidoPaterno IS NULL
        BEGIN ROLLBACK; SET @cMensaje=N'Complete los nombres y apellidos del cliente.'; RETURN 1; END;
        DECLARE @Clave VARCHAR(50)=CASE WHEN @cTipoDocumento='DNI' THEN 'DNI:'+@cNumeroDocumento
             WHEN @cTipoDocumento='RUC' AND LEFT(@cNumeroDocumento,2)='10' THEN 'DNI:'+SUBSTRING(@cNumeroDocumento,3,8)
             ELSE @cTipoDocumento+':'+@cNumeroDocumento END;
        SELECT @nClientePersonaId=persona_id,@cTipoDocumentoResultado=tipo_documento,@cNumeroDocumentoResultado=numero_documento,
               @cNombreCliente=LTRIM(RTRIM(CONCAT(nombres,N' ',apellido_paterno,N' ',COALESCE(apellido_materno,N''))))
        FROM org.Persona WITH(UPDLOCK,HOLDLOCK)
        WHERE documento_clave_desco=@Clave;
        IF @nClientePersonaId IS NULL
        BEGIN
          INSERT org.Persona(tipo_documento,numero_documento,nombres,apellido_paterno,apellido_materno,telefono,correo,estado,fecha_creacion,tipo_persona)
          VALUES(@cTipoDocumento,@cNumeroDocumento,@cNombres,@cApellidoPaterno,@cApellidoMaterno,@cTelefono,@cCorreo,1,SYSUTCDATETIME(),'NATURAL');
          SET @nClientePersonaId=SCOPE_IDENTITY();
          SET @cNombreCliente=LTRIM(RTRIM(CONCAT(@cNombres,N' ',@cApellidoPaterno,N' ',COALESCE(@cApellidoMaterno,N''))));
        END ELSE SET @bReutilizado=1;
      END
      ELSE
      BEGIN
        IF @cTipoDocumento<>'RUC' OR @cRazonSocial IS NULL
        BEGIN ROLLBACK; SET @cMensaje=N'Para una empresa ingrese RUC y razón social.'; RETURN 1; END;
        SELECT @nClienteEmpresaId=empresa_id,@cNumeroDocumentoResultado=ruc,@cNombreCliente=razon_social
        FROM org.Empresa WITH(UPDLOCK,HOLDLOCK) WHERE ruc=@cNumeroDocumento;
        IF @nClienteEmpresaId IS NULL
        BEGIN
          INSERT org.Empresa(ruc,razon_social,nombre_comercial,telefono,correo,fecha_creacion,estado)
          VALUES(@cNumeroDocumento,@cRazonSocial,NULL,@cTelefono,@cCorreo,SYSUTCDATETIME(),1);
          SET @nClienteEmpresaId=SCOPE_IDENTITY(); SET @cNombreCliente=@cRazonSocial;
        END ELSE SET @bReutilizado=1;
      END;
      COMMIT;
      SELECT @bResultado=1,
             @cMensaje=CASE WHEN @bReutilizado=1 THEN N'El cliente ya se encontraba registrado.' ELSE N'Cliente registrado correctamente.' END,
             @cCodigoRespuesta=CASE WHEN @bReutilizado=1 THEN 'CLIENTE_REUTILIZADO' ELSE 'CLIENTE_REGISTRADO' END,
             @nHttpRespuesta=200;
      RETURN 0;
    END TRY
    BEGIN CATCH
      IF XACT_STATE()<>0 ROLLBACK;
      IF ERROR_NUMBER() IN(2601,2627)
          SET @cMensaje=N'El documento ya se encuentra registrado. Vuelva a consultar el cliente.';
      ELSE SET @cMensaje=N'No se pudo registrar el cliente.';
      RETURN 1;
    END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- comercial.PA_CondicionComercial_Ins_Registro
CREATE OR ALTER PROCEDURE [comercial].[PA_CondicionComercial_Ins_Registro](@cJson NVARCHAR(MAX),@nCondicionComercialId BIGINT OUTPUT,@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY
  SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),@nAud BIGINT,@nTrans BIGINT,@nModalidad SMALLINT,@cCodigo VARCHAR(40),@cNombre NVARCHAR(160),@cDesc NVARCHAR(300),@nMin DECIMAL(8,2),@nMax DECIMAL(8,2),@cIdent NVARCHAR(200);
    SELECT @bResultado=0,@cMensaje=N'No se pudo registrar la condición comercial.';
    EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente] @cJson=@cJson,@cCodigoPermiso='PRECIOS_CREAR',@cAmbito='CONDICION_CREAR',@nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@nOperacionIdempotenteId=@nOp OUTPUT,@bEsRepetida=@bRep OUTPUT,@cEstadoOperacion=@cEstadoOp OUTPUT,@cIdentificadorResultado=@cIdRes OUTPUT,@cCodigoResultado=@cCodRes OUTPUT,@bResultado=@bIni OUTPUT,@cMensaje=@cMsg OUTPUT;
    IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
GOTO __DESCO_Salida;
END;
    IF @bRep=1 BEGIN SET @nCondicionComercialId=CASE WHEN @cEstadoOp='COMPLETADA' THEN TRY_CONVERT(BIGINT,@cIdRes) ELSE NULL END;
 SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
SET @cMensaje=CASE WHEN @cEstadoOp='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.' ELSE N'La solicitud ya se encuentra en proceso.' END;
GOTO __DESCO_Salida;
END;
 SET @nCondicionComercialId=NULL;
SELECT @nModalidad=modalidadVentaId,@cCodigo=UPPER(NULLIF(LTRIM(RTRIM(codigo)),'')),@cNombre=NULLIF(LTRIM(RTRIM(nombre)),N''),@cDesc=NULLIF(LTRIM(RTRIM(descripcion)),N''),@nMin=pesoMinimoG,@nMax=pesoMaximoG FROM OPENJSON(@cJson,'$.condicion') WITH(modalidadVentaId SMALLINT '$.modalidadVentaId',codigo VARCHAR(40) '$.codigo',nombre NVARCHAR(160) '$.nombre',descripcion NVARCHAR(300) '$.descripcion',pesoMinimoG DECIMAL(8,2) '$.pesoMinimoG',pesoMaximoG DECIMAL(8,2) '$.pesoMaximoG');
IF @nModalidad IS NULL OR @cCodigo IS NULL OR @cNombre IS NULL OR (@nMin IS NOT NULL AND @nMax IS NOT NULL AND @nMax<@nMin) BEGIN SET @cMensaje=N'Complete correctamente los datos de la condición.';
GOTO Fallar;
END;
IF NOT EXISTS(SELECT 1 FROM comercial.ModalidadVenta WHERE modalidad_venta_id=@nModalidad AND estado=1) BEGIN SET @cMensaje=N'La modalidad seleccionada no está disponible.';
GOTO Fallar;
END;
IF EXISTS(SELECT 1 FROM comercial.CondicionComercial WHERE codigo=@cCodigo) BEGIN SET @cMensaje=N'El código de condición ya se encuentra registrado.';
GOTO Fallar;
END;
BEGIN TRY BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;
INSERT comercial.CondicionComercial(modalidad_venta_id,codigo,nombre,descripcion,peso_minimo_g,peso_maximo_g,estado) VALUES(@nModalidad,@cCodigo,@cNombre,@cDesc,@nMin,@nMax,1);
SET @nCondicionComercialId=SCOPE_IDENTITY();
SET @cIdent=CONVERT(NVARCHAR(200),@nCondicionComercialId);
EXEC auditoria.PA_Operacion_Ins_RegistrarCambio @nUsuario,@nSesion,@nDisp,@nModulo,'CREAR','comercial','CondicionComercial',@cIdent,NULL,NULL,NULL,NULL,NULL,NULL,@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
/* Confirmar datos e idempotencia juntos. */EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar] @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='COMPLETADA',@cEsquemaEntidad='comercial',@cNombreEntidad='CondicionComercial',@cIdentificadorResultado=@cIdent,@cCodigoResultado='CONDICION_CREADA',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado=1;
SET @cMensaje=N'Condición comercial registrada correctamente.';
GOTO __DESCO_Salida;
 END TRY BEGIN CATCH
SET @bResultado = 0;
 IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @cMensaje=N'No se pudo registrar la condición. Intente nuevamente.';
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'comercial.PA_CondicionComercial_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;
Fallar:
    IF @nOp IS NOT NULL AND @bResultado=0 EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar] @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='FALLIDA',@cEsquemaEntidad=NULL,@cNombreEntidad=NULL,@cIdentificadorResultado=NULL,@cCodigoResultado='NO_PROCESADO',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
 
    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'comercial.PA_CondicionComercial_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

    IF @bResultado = 0 AND @nOp IS NOT NULL AND XACT_STATE() <> -1
    BEGIN
        IF ISNULL(@bRep,0) = 0
        BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                 @nOperacionIdempotenteId = @nOp, @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
            -- No sustituir el motivo funcional por un fallo de registro secundario.
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'comercial.PA_CondicionComercial_Ins_Registro',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
        END CATCH;
        END
        ELSE
        BEGIN
            SELECT @cMensaje = COALESCE(mensaje_resultado,
                CASE WHEN estado_operacion = 'FALLIDA'
                     THEN N'La solicitud anterior no se completó. Corrija los datos y envíe una nueva solicitud.'
                     ELSE N'La solicitud todavía se está procesando. Consulte el resultado antes de repetirla.' END)
            FROM [auditoria].[OperacionIdempotente]
            WHERE operacion_idempotente_id = @nOp;
        END;
    END;
IF @bResultado = 0
    SELECT @nCondicionComercialId = NULL;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'comercial.PA_CondicionComercial_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'comercial.PA_CondicionComercial_Ins_Registro',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

