END;
IF @bRep=1 BEGIN SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
SET @cMensaje=CASE WHEN @cEstadoOp='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.' ELSE N'La solicitud ya se encuentra en proceso.' END;
GOTO __DESCO_Salida;
END;
 SELECT @nId=incidenciaId,@cMotivo=NULLIF(LTRIM(RTRIM(motivo)),N'') FROM OPENJSON(@cJson,'$.incidencia') WITH(incidenciaId BIGINT '$.incidenciaId',motivo NVARCHAR(500) '$.motivo');
SELECT @cAnt=estado_incidencia FROM comercial.IncidenciaOperativa WHERE incidencia_operativa_id=@nId AND estado=1;
IF @cAnt NOT IN('ABIERTA','EN_REVISION') OR @cMotivo IS NULL BEGIN SET @cMensaje=N'La incidencia no está disponible para esta acción o falta indicar el motivo.';
