  SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),@nAud BIGINT,@nTrans BIGINT,@nId BIGINT,@nPeso DECIMAL(14,3),@cSev VARCHAR(10),@cDesc NVARCHAR(500),@cEstado VARCHAR(20),@cIdent NVARCHAR(200);
SELECT @bResultado=0,@cMensaje=N'No se pudo actualizar la revisión.';
EXEC seg.PA_Operacion_Ins_IniciarIdempotente @cJson=@cJson,@cCodigoPermiso='INCIDENCIAS_EDITAR',@cAmbito='INCIDENCIA_REVISAR',@nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@nOperacionIdempotenteId=@nOp OUTPUT,@bEsRepetida=@bRep OUTPUT,@cEstadoOperacion=@cEstadoOp OUTPUT,@cIdentificadorResultado=@cIdRes OUTPUT,@cCodigoResultado=@cCodRes OUTPUT,@bResultado=@bIni OUTPUT,@cMensaje=@cMsg OUTPUT;
IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
GOTO __DESCO_Salida;
END;
IF @bRep=1 BEGIN SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
SET @cMensaje=CASE WHEN @cEstadoOp='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.' ELSE N'La solicitud ya se encuentra en proceso.' END;
GOTO __DESCO_Salida;
END;
 SELECT @nId=incidenciaId,@nPeso=pesoAfectadoKg,@cSev=UPPER(NULLIF(LTRIM(RTRIM(severidad)),'')),@cDesc=NULLIF(LTRIM(RTRIM(descripcion)),N'') FROM OPENJSON(@cJson,'$.incidencia') WITH(incidenciaId BIGINT '$.incidenciaId',pesoAfectadoKg DECIMAL(14,3) '$.pesoAfectadoKg',severidad VARCHAR(10) '$.severidad',descripcion NVARCHAR(500) '$.descripcion');
SELECT @cEstado=estado_incidencia FROM comercial.IncidenciaOperativa WHERE incidencia_operativa_id=@nId AND estado=1;
IF @cEstado NOT IN('ABIERTA','EN_REVISION') OR @cSev NOT IN('BAJA','MEDIA','ALTA') OR @cDesc IS NULL BEGIN SET @cMensaje=N'La incidencia no está disponible para revisión o faltan datos.';
GOTO Fallar;
END;
BEGIN TRY BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;
UPDATE comercial.IncidenciaOperativa SET peso_afectado_kg=@nPeso,severidad=@cSev,descripcion=@cDesc,estado_incidencia='EN_REVISION' WHERE incidencia_operativa_id=@nId;
SET @cIdent=CONVERT(NVARCHAR(200),@nId);
EXEC auditoria.PA_Operacion_Ins_RegistrarCambio @nUsuario,@nSesion,@nDisp,@nModulo,'REVISAR','comercial','IncidenciaOperativa',@cIdent,NULL,NULL,NULL,'estado_incidencia',@cEstado,'EN_REVISION',@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
/* Confirmar datos e idempotencia juntos. */EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='COMPLETADA',@cEsquemaEntidad='comercial',@cNombreEntidad='IncidenciaOperativa',@cIdentificadorResultado=@cIdent,@cCodigoResultado='INCIDENCIA_REVISION',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado=1;
SET @cMensaje=N'Incidencia actualizada para revisión.';
GOTO __DESCO_Salida;
 END TRY BEGIN CATCH
SET @bResultado = 0;
 IF XACT_STATE()<>0 BEGIN
