GOTO __DESCO_Salida;
END;
IF @bRep=1 BEGIN SET @nJabaDevolucionId=CASE WHEN @cEstadoOp='COMPLETADA' THEN TRY_CONVERT(BIGINT,@cIdRes) ELSE NULL END;
 SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
SET @cMensaje=CASE WHEN @cEstadoOp='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.' ELSE N'La solicitud ya se encuentra en proceso.' END;
GOTO __DESCO_Salida;
END;
 SET @nJabaDevolucionId=NULL;
SELECT @nAsig=jabaAsignacionId,@nEntrega=entregaSocioId,@nLlenas=COALESCE(cantidadLlenas,0),@nVacias=COALESCE(cantidadVacias,0),@cObs=NULLIF(LTRIM(RTRIM(observacion)),N'') FROM OPENJSON(@cJson,'$.jabas') WITH(jabaAsignacionId BIGINT '$.jabaAsignacionId',entregaSocioId BIGINT '$.entregaSocioId',cantidadLlenas INT '$.cantidadLlenas',cantidadVacias INT '$.cantidadVacias',observacion NVARCHAR(300) '$.observacion');
SELECT @nOS=operativo_socio_id,@nAsignadas=cantidad_asignada FROM comercial.JabaAsignacion WHERE jaba_asignacion_id=@nAsig AND estado=1;
SELECT @nOpVenta=operativo_venta_id FROM comercial.OperativoSocio WHERE operativo_socio_id=@nOS AND estado=1;
SELECT @nDevueltas=COALESCE(SUM(cantidad_llenas+cantidad_vacias),0) FROM comercial.JabaDevolucion WHERE jaba_asignacion_id=@nAsig AND estado=1;
IF @nOpVenta IS NULL OR @nLlenas<0 OR @nVacias<0 OR @nLlenas+@nVacias<=0 BEGIN SET @cMensaje=N'Complete correctamente la devolución de jabas.';
GOTO Fallar;
END;
IF NOT EXISTS(SELECT 1 FROM comercial.OperativoVenta WHERE operativo_venta_id=@nOpVenta AND estado=1 AND estado_proceso='EN_RECEPCION')
BEGIN SET @cMensaje=N'El operativo ya no permite registrar devoluciones de jabas.';
GOTO Fallar;
END;
IF @nDevueltas+@nLlenas+@nVacias>@nAsignadas BEGIN SET @cMensaje=N'La devolución supera la cantidad de jabas asignadas.';
GOTO Fallar;
END;
IF @nEntrega IS NOT NULL AND NOT EXISTS(SELECT 1 FROM comercial.EntregaSocio WHERE entrega_socio_id=@nEntrega AND operativo_socio_id=@nOS AND estado=1 AND estado_proceso<>'ANULADA') BEGIN SET @cMensaje=N'La entrega seleccionada no corresponde al participante.';
GOTO Fallar;
END;
BEGIN TRY BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;
INSERT comercial.JabaDevolucion(jaba_asignacion_id,entrega_socio_id,fecha_hora,cantidad_llenas,cantidad_vacias,observacion,estado,usuario_registro_id) VALUES(@nAsig,@nEntrega,SYSUTCDATETIME(),@nLlenas,@nVacias,@cObs,1,@nUsuario);
SET @nJabaDevolucionId=SCOPE_IDENTITY();
/* Kardex generado por el registro de origen. */
/* Kardex generado por el registro de origen. */
SET @cIdent=CONVERT(NVARCHAR(200),@nJabaDevolucionId);
EXEC auditoria.PA_Operacion_Ins_RegistrarCambio @nUsuario,@nSesion,@nDisp,@nModulo,'DEVOLVER','comercial','JabaDevolucion',@cIdent,NULL,NULL,@cObs,NULL,NULL,NULL,@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
/* Confirmar datos e idempotencia juntos. */EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='COMPLETADA',@cEsquemaEntidad='comercial',@cNombreEntidad='JabaDevolucion',@cIdentificadorResultado=@cIdent,@cCodigoResultado='JABAS_DEVUELTAS',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado=1;
SET @cMensaje=N'Devolución de jabas registrada correctamente.';
GOTO __DESCO_Salida;
 END TRY BEGIN CATCH
SET @bResultado = 0;
 IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @cMensaje=N'No se pudo registrar la devolución. Intente nuevamente.';
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'comercial.PA_Jabas_Ins_Devolucion',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;
Fallar: IF @nOp IS NOT NULL AND @bResultado=0 EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='FALLIDA',@cEsquemaEntidad=NULL,@cNombreEntidad=NULL,@cIdentificadorResultado=NULL,@cCodigoResultado='NO_PROCESADO',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
 
    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
