-- comercial.PA_Jabas_Sel_SaldoInterno
CREATE OR ALTER PROCEDURE [comercial].[PA_Jabas_Sel_SaldoInterno]
(
    @nOperativoVentaId BIGINT,
    @nOperativoSocioId BIGINT = NULL,
    @nRecibidas INT OUTPUT,
    @nAsignadas INT OUTPUT,
    @nDevueltas INT OUTPUT,
    @nPendientes INT OUTPUT,
    @nDisponibles INT OUTPUT
,@bResultado BIT=NULL OUTPUT,@cMensaje NVARCHAR(300)=NULL OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

 SET NOCOUNT ON;
 SELECT @bResultado=0,@cMensaje=N'No se pudo consultar la información.';
 BEGIN TRY

  SELECT @nRecibidas=NULL,@nAsignadas=0,@nDevueltas=0,@nPendientes=0,@nDisponibles=0;
  SELECT @nRecibidas=CONVERT(INT,recibidas),@nAsignadas=CONVERT(INT,asignadas),
   @nDevueltas=CONVERT(INT,devueltas_llenas+devueltas_vacias),@nPendientes=CONVERT(INT,pendientes),@nDisponibles=CONVERT(INT,disponibles)
  FROM comercial.JabaSaldoOperativo WHERE operativo_venta_id=@nOperativoVentaId;
  IF @nRecibidas IS NULL THROW 51100,N'DESCO_RECURSO_NO_DISPONIBLE',1;
  IF @nOperativoSocioId IS NOT NULL
  BEGIN
   IF NOT EXISTS(SELECT 1 FROM comercial.OperativoSocio WHERE operativo_socio_id=@nOperativoSocioId AND operativo_venta_id=@nOperativoVentaId)
    THROW 51100,N'DESCO_JABA_RELACION',1;
   SELECT @nAsignadas=CONVERT(INT,COALESCE(SUM(CONVERT(BIGINT,A.cantidad_asignada)),0)),
    @nDevueltas=CONVERT(INT,COALESCE(SUM(A.cantidad_devuelta),0))
   FROM comercial.JabaAsignacion A WHERE A.operativo_socio_id=@nOperativoSocioId AND A.estado=1;
   SELECT @nPendientes=@nAsignadas-@nDevueltas,@nDisponibles=@nAsignadas-@nDevueltas;
  END;

  SELECT @bResultado=1,@cMensaje=N'Saldo de jabas consultado.';
 END TRY
 BEGIN CATCH
  SET @bResultado=0;
  EXEC config.PA_Respuesta_ResolverError @cProcedimiento=N'comercial.PA_Jabas_Sel_SaldoInterno',@cMensaje=@cMensaje OUTPUT,@cJson=NULL;
 END CATCH;
Salida:
 SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'comercial.PA_Jabas_Sel_SaldoInterno',@bResultado,@cMensaje) R;
IF @bResultado=0 AND @@NESTLEVEL>1 THROW 51000,@cMensaje,1;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- comercial.PA_Jabas_Upd_AnularMovimiento
CREATE OR ALTER PROCEDURE [comercial].[PA_Jabas_Upd_AnularMovimiento](@cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY
  SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),@nAud BIGINT,@nTrans BIGINT,@cTipo VARCHAR(20),@nId BIGINT,@cMotivo NVARCHAR(300),@cIdent NVARCHAR(200),@nOpVenta BIGINT;
SELECT @bResultado=0,@cMensaje=N'No se pudo anular el movimiento de jabas.';
EXEC seg.PA_Operacion_Ins_IniciarIdempotente @cJson=@cJson,@cCodigoPermiso='JABAS_RETIRAR',@cAmbito='JABAS_ANULAR',@nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@nOperacionIdempotenteId=@nOp OUTPUT,@bEsRepetida=@bRep OUTPUT,@cEstadoOperacion=@cEstadoOp OUTPUT,@cIdentificadorResultado=@cIdRes OUTPUT,@cCodigoResultado=@cCodRes OUTPUT,@bResultado=@bIni OUTPUT,@cMensaje=@cMsg OUTPUT;
IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
GOTO __DESCO_Salida;
END;
IF @bRep=1 BEGIN SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
SET @cMensaje=CASE WHEN @cEstadoOp='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.' ELSE N'La solicitud ya se encuentra en proceso.' END;
GOTO __DESCO_Salida;
END;
 SELECT @cTipo=UPPER(NULLIF(LTRIM(RTRIM(tipo)),'')),@nId=movimientoId,@cMotivo=NULLIF(LTRIM(RTRIM(motivo)),N'') FROM OPENJSON(@cJson,'$.jabas') WITH(tipo VARCHAR(20) '$.tipo',movimientoId BIGINT '$.movimientoId',motivo NVARCHAR(300) '$.motivo');
IF @cTipo NOT IN('ASIGNACION','DEVOLUCION') OR @nId IS NULL OR @cMotivo IS NULL BEGIN SET @cMensaje=N'Seleccione el movimiento e indique el motivo de la anulación.';
GOTO Fallar;
END;
IF @cTipo='ASIGNACION'
    SELECT @nOpVenta=OS.operativo_venta_id
    FROM comercial.JabaAsignacion JA
    INNER JOIN comercial.OperativoSocio OS ON OS.operativo_socio_id=JA.operativo_socio_id
    WHERE JA.jaba_asignacion_id=@nId AND JA.estado=1 AND OS.estado=1;
ELSE
    SELECT @nOpVenta=OS.operativo_venta_id
    FROM comercial.JabaDevolucion JD
    INNER JOIN comercial.JabaAsignacion JA ON JA.jaba_asignacion_id=JD.jaba_asignacion_id
    INNER JOIN comercial.OperativoSocio OS ON OS.operativo_socio_id=JA.operativo_socio_id
    WHERE JD.jaba_devolucion_id=@nId AND JD.estado=1 AND JA.estado=1 AND OS.estado=1;
IF @nOpVenta IS NULL OR NOT EXISTS(SELECT 1 FROM comercial.OperativoVenta WHERE operativo_venta_id=@nOpVenta AND estado=1 AND estado_proceso='EN_RECEPCION')
BEGIN SET @cMensaje=N'El movimiento ya forma parte de un operativo cerrado o no está disponible para anulación.';
GOTO Fallar;
END;
IF @cTipo='ASIGNACION' AND EXISTS(SELECT 1 FROM comercial.JabaDevolucion WHERE jaba_asignacion_id=@nId AND estado=1) BEGIN SET @cMensaje=N'La asignación ya tiene devoluciones registradas y no puede anularse directamente.';
GOTO Fallar;
END;
IF @cTipo='DEVOLUCION' AND EXISTS(SELECT 1 FROM comercial.JabaDevolucion D INNER JOIN comercial.EntregaSocio E ON E.entrega_socio_id=D.entrega_socio_id WHERE D.jaba_devolucion_id=@nId AND D.estado=1 AND E.estado=1 AND E.estado_proceso='CONFIRMADA') BEGIN SET @cMensaje=N'La devolución está vinculada a una entrega confirmada y no puede anularse.';
GOTO Fallar;
END;
BEGIN TRY BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;
IF @cTipo='ASIGNACION' BEGIN UPDATE comercial.JabaAsignacion SET estado=0,fecha_anulacion=SYSUTCDATETIME(),usuario_anulacion_id=@nUsuario,motivo_anulacion=@cMotivo WHERE jaba_asignacion_id=@nId AND estado=1;
/* La anulación del origen actualiza su kardex. */
END ELSE BEGIN UPDATE comercial.JabaDevolucion SET estado=0,fecha_anulacion=SYSUTCDATETIME(),usuario_anulacion_id=@nUsuario,motivo_anulacion=@cMotivo WHERE jaba_devolucion_id=@nId AND estado=1;
/* La anulación del origen actualiza su kardex. */
END IF @@ROWCOUNT=0 BEGIN BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @cMensaje=N'El movimiento seleccionado no está disponible.';
GOTO Fallar;
END;
SET @cIdent=CONVERT(NVARCHAR(200),@nId);
DECLARE @cEntidadJaba SYSNAME;
 SET @cEntidadJaba=CASE WHEN @cTipo='ASIGNACION' THEN N'JabaAsignacion' ELSE N'JabaDevolucion' END;
 EXEC auditoria.PA_Operacion_Ins_RegistrarCambio @nUsuario,@nSesion,@nDisp,@nModulo,'ANULAR','comercial',@cEntidadJaba,@cIdent,NULL,NULL,@cMotivo,'estado','1','0',@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
/* Confirmar datos e idempotencia juntos. */EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='COMPLETADA',@cEsquemaEntidad='comercial',@cNombreEntidad='JabaMovimiento',@cIdentificadorResultado=@cIdent,@cCodigoResultado='JABAS_ANULADAS',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado=1;
SET @cMensaje=N'Movimiento de jabas anulado correctamente.';
GOTO __DESCO_Salida;
 END TRY BEGIN CATCH
SET @bResultado = 0;
 IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @cMensaje=N'No se pudo anular el movimiento. Intente nuevamente.';
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'comercial.PA_Jabas_Upd_AnularMovimiento',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;
Fallar: IF @nOp IS NOT NULL AND @bResultado=0 EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='FALLIDA',@cEsquemaEntidad=NULL,@cNombreEntidad=NULL,@cIdentificadorResultado=NULL,@cCodigoResultado='NO_PROCESADO',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
 
    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'comercial.PA_Jabas_Upd_AnularMovimiento',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
