-- comercial.PA_OperativoVenta_Ins_Registro
CREATE OR ALTER PROCEDURE [comercial].[PA_OperativoVenta_Ins_Registro](@cJson NVARCHAR(MAX),@nOperativoVentaId BIGINT OUTPUT,@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
