    SELECT @bResultado=0,@cMensaje=N'No se pudo incluir al socio.';
    EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente] @cJson=@cJson,@cCodigoPermiso='PARTICIPANTES_CREAR',@cAmbito='PARTICIPANTE_INCLUIR',@nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@nOperacionIdempotenteId=@nOp OUTPUT,@bEsRepetida=@bRep OUTPUT,@cEstadoOperacion=@cEstadoOp OUTPUT,@cIdentificadorResultado=@cIdRes OUTPUT,@cCodigoResultado=@cCodRes OUTPUT,@bResultado=@bIni OUTPUT,@cMensaje=@cMsg OUTPUT;
    IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
GOTO __DESCO_Salida;
END;
    IF @bRep=1 BEGIN SET @nParticipacionId=CASE WHEN @cEstadoOp='COMPLETADA' THEN TRY_CONVERT(BIGINT,@cIdRes) ELSE NULL END;
 SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
SET @cMensaje=CASE WHEN @cEstadoOp='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.' ELSE N'La solicitud ya se encuentra en proceso.' END;
GOTO __DESCO_Salida;
END;
 SET @nParticipacionId=NULL;
SELECT @nCamp=campaniaVentaId,@nSA=socioAsociacionId FROM OPENJSON(@cJson,'$.participacion') WITH(campaniaVentaId BIGINT '$.campaniaVentaId',socioAsociacionId BIGINT '$.socioAsociacionId');
SELECT @nAsoc=asociacion_id FROM comercial.CampaniaVenta WHERE campania_venta_id=@nCamp AND estado=1 AND estado_proceso IN('PLANIFICACION','ACTIVA');
IF @nAsoc IS NULL BEGIN SET @cMensaje=N'La campaña seleccionada no permite incluir participantes.';
GOTO Fallar;
END;
IF NOT EXISTS(SELECT 1 FROM org.SocioAsociacion WHERE socio_asociacion_id=@nSA AND asociacion_id=@nAsoc AND estado=1 AND situacion_membresia='ACTIVO') BEGIN SET @cMensaje=N'El socio seleccionado no pertenece activamente a la asociación de la campaña.';
GOTO Fallar;
END;
IF EXISTS(SELECT 1 FROM comercial.ParticipacionCampaniaSocio WHERE campania_venta_id=@nCamp AND socio_asociacion_id=@nSA) BEGIN SET @cMensaje=N'El socio ya fue registrado en esta campaña.';
GOTO Fallar;
END;
