-- comercial.PA_ParticipacionCampaniaSocio_Sel_Detalle
CREATE OR ALTER PROCEDURE [comercial].[PA_ParticipacionCampaniaSocio_Sel_Detalle](@cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;

    BEGIN TRY
  SET NOCOUNT ON;
DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@bCtx BIT,@cMsg NVARCHAR(300);
    SELECT @bResultado=0,@cMensaje=N'No se pudo consultar el participante.';
    EXEC [seg].[PA_Operacion_Sel_ContextoAutorizado] @cJson=@cJson,@cCodigoPermiso='PARTICIPANTES_VER',@nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@bResultado=@bCtx OUTPUT,@cMensaje=@cMsg OUTPUT;
    IF @bCtx=0 BEGIN SET @cMensaje=@cMsg;
 GOTO __DESCO_Salida;
 END;
 DECLARE @nId BIGINT;
SELECT @nId=participacionId FROM OPENJSON(@cJson,'$.participacion') WITH(participacionId BIGINT '$.participacionId');
IF NOT EXISTS(SELECT 1 FROM comercial.ParticipacionCampaniaSocio WHERE participacion_campania_socio_id=@nId AND estado=1) BEGIN SET @cMensaje=N'El participante seleccionado no está disponible.';
GOTO __DESCO_Salida;
END;
SELECT P.participacion_campania_socio_id participacionId,P.estado_participacion estadoParticipacion,P.fecha_registro fechaRegistro,C.campania_venta_id campaniaVentaId,C.nombre campania,S.socio_id socioId,PE.numero_documento numeroDocumento,CONCAT(PE.nombres,N' ',PE.apellido_paterno,N' ',COALESCE(PE.apellido_materno,N'')) socioNombre FROM comercial.ParticipacionCampaniaSocio P INNER JOIN comercial.CampaniaVenta C ON C.campania_venta_id=P.campania_venta_id INNER JOIN org.SocioAsociacion SA ON SA.socio_asociacion_id=P.socio_asociacion_id INNER JOIN org.Socio S ON S.socio_id=SA.socio_id INNER JOIN org.Persona PE ON PE.persona_id=S.socio_id WHERE P.participacion_campania_socio_id=@nId;
SELECT OS.operativo_socio_id operativoSocioId,O.operativo_venta_id operativoVentaId,O.codigo,O.estado_proceso estadoOperativo,OS.estado_participacion estadoParticipacion FROM comercial.OperativoSocio OS INNER JOIN comercial.OperativoVenta O ON O.operativo_venta_id=OS.operativo_venta_id WHERE OS.participacion_campania_socio_id=@nId AND OS.estado=1 ORDER BY O.fecha_inicio_programada;
SELECT E.entrega_socio_id entregaSocioId,E.codigo_lote codigoLote,E.fecha_hora fechaHora,E.peso_aceptado_kg pesoAceptadoKg,E.estado_control_calidad estadoControlCalidad,E.estado_proceso estadoProceso FROM comercial.EntregaSocio E INNER JOIN comercial.OperativoSocio OS ON OS.operativo_socio_id=E.operativo_socio_id WHERE OS.participacion_campania_socio_id=@nId AND E.estado=1 ORDER BY E.fecha_hora DESC;
SET @bResultado=1;
SET @cMensaje=N'Participante consultado correctamente.';
    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
