/* ================================================================
   PA_Venta_Ins_Comprobante
   ================================================================ */
CREATE OR ALTER PROCEDURE [comercial].[PA_Venta_Ins_Comprobante]
 @nUsuarioId BIGINT,@nVentaId BIGINT,@cTipo VARCHAR(10),@cSerie VARCHAR(10),@nNumero BIGINT,@cDocumentoCliente VARCHAR(30)=NULL,@cNombreCliente NVARCHAR(220)=NULL,
 @nComprobanteId BIGINT OUTPUT,@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON; SET @nComprobanteId=NULL; SET @bResultado=0; SET @cMensaje=N'No se pudo emitir el comprobante.';
 DECLARE @UOT BIGINT,@Subtotal DECIMAL(19,4),@Impuesto DECIMAL(19,4),@Total DECIMAL(19,4); SELECT @UOT=uot_id,@Subtotal=subtotal,@Impuesto=impuesto,@Total=total FROM comercial.Venta WHERE venta_id=@nVentaId AND estado=1 AND estado_venta<>'ANULADA';
 IF @UOT IS NULL BEGIN SET @cMensaje=N'La venta no está disponible.'; RETURN; END;
 IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@UOT,'POS_OPERAR')=0 BEGIN SET @cMensaje=N'No tiene permiso para emitir comprobantes.'; RETURN; END;
 SET @cTipo=UPPER(NULLIF(LTRIM(RTRIM(@cTipo)),'')); SET @cSerie=UPPER(NULLIF(LTRIM(RTRIM(@cSerie)),''));
 IF @cTipo NOT IN('BOLETA','FACTURA') OR @cSerie IS NULL OR @nNumero<=0 BEGIN SET @cMensaje=N'Complete correctamente los datos del comprobante.'; RETURN; END;
 BEGIN TRY
  IF @cTipo='BOLETA'
  BEGIN
    INSERT comercial.Boleta(venta_id,serie,numero,cliente_documento,cliente_nombre,subtotal,impuesto,total,estado_comprobante,estado)
    VALUES(@nVentaId,@cSerie,@nNumero,@cDocumentoCliente,@cNombreCliente,@Subtotal,@Impuesto,@Total,'EMITIDO',1); SET @nComprobanteId=SCOPE_IDENTITY();
  END
  ELSE
  BEGIN
    IF LEN(ISNULL(@cDocumentoCliente,''))<>11 OR @cDocumentoCliente LIKE '%[^0-9]%' OR NULLIF(LTRIM(RTRIM(@cNombreCliente)),N'') IS NULL BEGIN SET @cMensaje=N'Para factura ingrese RUC y razón social válidos.'; RETURN; END;
    INSERT comercial.Factura(venta_id,serie,numero,cliente_ruc,cliente_razon_social,subtotal,impuesto,total,estado_comprobante,estado)
    VALUES(@nVentaId,@cSerie,@nNumero,@cDocumentoCliente,@cNombreCliente,@Subtotal,@Impuesto,@Total,'EMITIDO',1); SET @nComprobanteId=SCOPE_IDENTITY();
  END;
  SET @bResultado=1; SET @cMensaje=N'Comprobante emitido correctamente.';
 END TRY BEGIN CATCH SET @nComprobanteId=NULL; SET @cMensaje=N'No se pudo emitir el comprobante. Revise la serie, número y la venta.'; END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* ================================================================
   PA_Venta_Ins_Pago
   ================================================================ */
CREATE OR ALTER PROCEDURE [comercial].[PA_Venta_Ins_Pago]
 @nUsuarioId BIGINT,@nVentaId BIGINT,@nMetodoPagoId SMALLINT,@nImporte DECIMAL(19,4),@gClaveIdempotencia UNIQUEIDENTIFIER,@cNumeroOperacion VARCHAR(120)=NULL,
 @nPagoVentaId BIGINT OUTPUT,@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON; SET @nPagoVentaId=NULL; SET @bResultado=0; SET @cMensaje=N'No se pudo registrar el pago.';
 DECLARE @UOT BIGINT,@Total DECIMAL(19,4); SELECT @UOT=uot_id,@Total=total FROM comercial.Venta WHERE venta_id=@nVentaId AND estado=1 AND estado_venta<>'ANULADA';
 IF @UOT IS NULL BEGIN SET @cMensaje=N'La venta no está disponible.'; RETURN; END;
 IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@UOT,'POS_OPERAR')=0 BEGIN SET @cMensaje=N'No tiene permiso para registrar pagos.'; RETURN; END;
 IF @nImporte<=0 BEGIN SET @cMensaje=N'El importe debe ser mayor que cero.'; RETURN; END;
 IF @gClaveIdempotencia IS NULL BEGIN SET @cMensaje=N'La clave de idempotencia del pago es obligatoria.'; RETURN; END;
 SELECT @nPagoVentaId=pago_venta_id FROM comercial.PagoVenta WHERE clave_idempotencia=@gClaveIdempotencia; IF @nPagoVentaId IS NOT NULL BEGIN SET @bResultado=1; SET @cMensaje=N'El pago ya fue registrado correctamente.'; RETURN; END;
 IF NOT EXISTS(SELECT 1 FROM comercial.MetodoPago WHERE metodo_pago_id=@nMetodoPagoId AND estado=1) BEGIN SET @cMensaje=N'El método de pago no está disponible.'; RETURN; END;
 IF EXISTS(SELECT 1 FROM comercial.MetodoPago WHERE metodo_pago_id=@nMetodoPagoId AND requiere_numero_operacion=1 AND NULLIF(LTRIM(RTRIM(@cNumeroOperacion)),'') IS NULL) BEGIN SET @cMensaje=N'Ingrese el número de operación del pago.'; RETURN; END;
 BEGIN TRY SET TRANSACTION ISOLATION LEVEL SERIALIZABLE; BEGIN TRAN;
 DECLARE @Pagado DECIMAL(19,4)=ISNULL((SELECT SUM(importe) FROM comercial.PagoVenta WITH(UPDLOCK,HOLDLOCK) WHERE venta_id=@nVentaId AND estado=1 AND estado_pago='CONFIRMADO'),0);
 IF @Pagado+@nImporte>@Total THROW 51070,N'PAGO_SUPERA_TOTAL',1;
 INSERT comercial.PagoVenta(venta_id,metodo_pago_id,importe,moneda,numero_operacion,usuario_id,estado_pago,estado,clave_idempotencia) VALUES(@nVentaId,@nMetodoPagoId,@nImporte,'PEN',NULLIF(LTRIM(RTRIM(@cNumeroOperacion)),''),@nUsuarioId,'CONFIRMADO',1,@gClaveIdempotencia);
 SET @nPagoVentaId=SCOPE_IDENTITY(); SET @Pagado=@Pagado+@nImporte;
 UPDATE comercial.Venta SET estado_venta=CASE WHEN @Pagado=@Total THEN 'PAGADA' ELSE 'PAGO_PARCIAL' END WHERE venta_id=@nVentaId AND estado_venta<>'ENTREGADA';
 COMMIT; SET @bResultado=1; SET @cMensaje=CASE WHEN @Pagado=@Total THEN N'Pago registrado. La venta quedó pagada.' ELSE N'Adelanto registrado correctamente.' END;
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SET @nPagoVentaId=NULL; SET @cMensaje=CASE WHEN ERROR_MESSAGE() LIKE '%PAGO_SUPERA_TOTAL%' THEN N'El pago supera el saldo pendiente de la venta.' ELSE N'No se pudo registrar el pago.' END; END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* ================================================================
   PA_Venta_Ins_Registrar
   ================================================================ */
CREATE OR ALTER PROCEDURE [comercial].[PA_Venta_Ins_Registrar]
 @nUsuarioId BIGINT,@nUotId BIGINT,@nAlmacenId BIGINT,@nClientePersonaId BIGINT=NULL,@nClienteEmpresaId BIGINT=NULL,
 @gClaveIdempotencia UNIQUEIDENTIFIER,@cDetalleJson NVARCHAR(MAX),@bSeparar BIT=0,@dReservaHasta DATETIME2(0)=NULL,@cObservacion NVARCHAR(500)=NULL,
 @nVentaId BIGINT OUTPUT,@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON; SET @nVentaId=NULL; SET @bResultado=0; SET @cMensaje=N'No se pudo registrar la venta.';
 IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotId,'POS_OPERAR')=0 BEGIN SET @cMensaje=N'No tiene permiso para registrar ventas.'; RETURN; END;
 IF NOT EXISTS(SELECT 1 FROM logistica.AlmacenUOT WHERE almacen_id=@nAlmacenId AND uot_id=@nUotId AND estado=1 AND fecha_hasta IS NULL AND permite_salida=1) BEGIN SET @cMensaje=N'La UOT no puede vender desde el almacén seleccionado.'; RETURN; END;
 IF @nClientePersonaId IS NOT NULL AND @nClienteEmpresaId IS NOT NULL BEGIN SET @cMensaje=N'Seleccione un solo cliente para la venta.'; RETURN; END;
 IF @nClientePersonaId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM org.Persona WHERE persona_id=@nClientePersonaId AND estado=1) BEGIN SET @cMensaje=N'El cliente seleccionado no está disponible.'; RETURN; END;
 IF @nClienteEmpresaId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM org.Empresa WHERE empresa_id=@nClienteEmpresaId AND estado=1) BEGIN SET @cMensaje=N'El cliente seleccionado no está disponible.'; RETURN; END;
 IF @bSeparar=1 AND (@dReservaHasta IS NULL OR @dReservaHasta<=SYSUTCDATETIME()) BEGIN SET @cMensaje=N'La fecha límite de la separación debe ser futura.'; RETURN; END;
 IF @gClaveIdempotencia IS NULL OR ISJSON(@cDetalleJson)<>1 OR NOT EXISTS(SELECT 1 FROM OPENJSON(@cDetalleJson)) BEGIN SET @cMensaje=N'La venta debe incluir productos válidos.'; RETURN; END;
 SELECT @nVentaId=venta_id FROM comercial.Venta WHERE clave_idempotencia=@gClaveIdempotencia;
 IF @nVentaId IS NOT NULL BEGIN SET @bResultado=1; SET @cMensaje=N'La venta ya fue registrada correctamente.'; RETURN; END;
 BEGIN TRY
  SET TRANSACTION ISOLATION LEVEL SERIALIZABLE; BEGIN TRAN;
  DECLARE @Detalle TABLE(producto_id BIGINT PRIMARY KEY,cantidad DECIMAL(19,3),precio_id BIGINT,precio_inicial DECIMAL(19,4),precio_venta DECIMAL(19,4),moneda CHAR(3));
  ;WITH Raw AS(
      SELECT productoId,cantidad FROM OPENJSON(@cDetalleJson)
      WITH(productoId BIGINT '$.productoId',cantidad DECIMAL(19,3) '$.cantidad')
  ), Agrupado AS(
      SELECT productoId,SUM(cantidad) cantidad FROM Raw GROUP BY productoId
  )
  INSERT @Detalle(producto_id,cantidad,precio_id,precio_inicial,precio_venta,moneda)
  SELECT D.productoId,D.cantidad,P.producto_precio_id,P.precio_inicial,P.precio_venta,P.moneda
  FROM Agrupado D
  OUTER APPLY(SELECT TOP(1) PP.producto_precio_id,PP.precio_inicial,PP.precio_venta,PP.moneda
              FROM logistica.ProductoPrecio PP
              WHERE PP.producto_id=D.productoId AND PP.estado=1 AND PP.fecha_hasta IS NULL AND (PP.uot_id=@nUotId OR PP.uot_id IS NULL)
              ORDER BY CASE WHEN PP.uot_id=@nUotId THEN 0 ELSE 1 END,PP.version DESC,PP.producto_precio_id DESC) P;

  IF EXISTS(SELECT 1 FROM @Detalle WHERE producto_id IS NULL OR cantidad IS NULL OR cantidad<=0 OR precio_id IS NULL) THROW 51060,N'VENTA_DETALLE_INVALIDO',1;
  IF EXISTS(SELECT 1 FROM @Detalle D LEFT JOIN logistica.AlmacenProductoStock S WITH(UPDLOCK,HOLDLOCK) ON S.almacen_id=@nAlmacenId AND S.producto_id=D.producto_id WHERE ISNULL(S.stock_disponible,0)<D.cantidad) THROW 51061,N'VENTA_STOCK_INSUFICIENTE',1;
  IF (SELECT COUNT(DISTINCT moneda) FROM @Detalle)<>1 THROW 51062,N'VENTA_MONEDA_MIXTA',1;

  DECLARE @Moneda CHAR(3)=(SELECT TOP(1) moneda FROM @Detalle);
  DECLARE @Subtotal DECIMAL(19,4)=(SELECT SUM(CONVERT(DECIMAL(19,4),cantidad*precio_venta)) FROM @Detalle);
  INSERT comercial.Venta(uot_id,almacen_id,cliente_persona_id,cliente_empresa_id,vendedor_usuario_id,clave_idempotencia,fecha_reserva_hasta,moneda,subtotal,descuento,impuesto,total,estado_venta,observacion,estado)
  VALUES(@nUotId,@nAlmacenId,@nClientePersonaId,@nClienteEmpresaId,@nUsuarioId,@gClaveIdempotencia,@dReservaHasta,@Moneda,@Subtotal,0,0,@Subtotal,CASE WHEN @bSeparar=1 THEN 'SEPARADA' ELSE 'REGISTRADA' END,@cObservacion,1);
  SET @nVentaId=SCOPE_IDENTITY();
  INSERT comercial.DetalleVenta(venta_id,producto_id,producto_precio_id,cantidad,precio_inicial_referencia,precio_unitario,descuento_unitario,estado)
  SELECT @nVentaId,producto_id,precio_id,cantidad,precio_inicial,precio_venta,0,1 FROM @Detalle;
  IF @bSeparar=1
  BEGIN
    INSERT logistica.ReservaStock(detalle_venta_id,almacen_id,producto_id,cantidad,fecha_expiracion,estado_reserva,estado)
    SELECT DV.detalle_venta_id,@nAlmacenId,DV.producto_id,DV.cantidad,@dReservaHasta,'ACTIVA',1 FROM comercial.DetalleVenta DV WHERE DV.venta_id=@nVentaId AND DV.estado=1;
    UPDATE S SET stock_reservado=S.stock_reservado+D.cantidad,fecha_actualizacion=SYSUTCDATETIME()
    FROM logistica.AlmacenProductoStock S JOIN @Detalle D ON D.producto_id=S.producto_id WHERE S.almacen_id=@nAlmacenId;
  END;
  COMMIT; SET @bResultado=1; SET @cMensaje=CASE WHEN @bSeparar=1 THEN N'Venta separada correctamente.' ELSE N'Venta registrada correctamente.' END;
 END TRY BEGIN CATCH
  IF XACT_STATE()<>0 ROLLBACK; SET @nVentaId=NULL;
  SET @cMensaje=CASE
      WHEN ERROR_MESSAGE() LIKE '%VENTA_STOCK_INSUFICIENTE%' THEN N'No hay stock suficiente para completar la venta.'
      WHEN ERROR_MESSAGE() LIKE '%VENTA_DETALLE_INVALIDO%' THEN N'Uno o más productos no tienen cantidad o precio vigente válido.'
      WHEN ERROR_MESSAGE() LIKE '%VENTA_MONEDA_MIXTA%' THEN N'Los productos de una venta deben utilizar la misma moneda.'
      ELSE N'No se pudo registrar la venta.' END;
 END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/*
    DESCO - POS
    Corrección incremental del catálogo de métodos de pago.

    Problema corregido:
    - /api/v1/ventas/metodos-pago era consultado desde una sesión en modo GENERAL.
    - El flujo legacy de persistencia de ventas intentaba resolver una UOT específica
      desde la sesión y devolvía:
        METODOS_PAGO_NO_LISTADOS
        "Seleccione un contexto con acceso a ventas."

    Regla:
    - MetodoPago es un catálogo comercial global.
    - No depende del almacén ni de una UOT específica.
    - Sí exige que el usuario tenga POS_OPERAR en al menos una UOT activa a la que
      tenga acceso.
*/

CREATE OR ALTER PROCEDURE [comercial].[PA_Venta_Sel_MetodosPago]
    @nUsuarioId BIGINT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(80) OUTPUT,
    @nHttpRespuesta SMALLINT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    SET @bResultado = 0;
    SET @cMensaje = N'No se pudieron consultar los métodos de pago.';
    SET @cCodigoRespuesta = 'METODOS_PAGO_NO_LISTADOS';
    SET @nHttpRespuesta = 400;

    IF @nUsuarioId IS NULL
    BEGIN
        SET @cMensaje = N'La sesión ya no está disponible.';
        SET @cCodigoRespuesta = 'SESION_NO_DISPONIBLE';
        SET @nHttpRespuesta = 401;
        RETURN;
    END;

    /*
        En modo GENERAL no existe una UOT específica en SesionUsuario.
        Para un catálogo global basta comprobar que el usuario pueda operar el POS
        en al menos una UOT activa asignada.
    */
    IF NOT EXISTS
    (
        SELECT 1
        FROM seg.UsuarioUOT AS UU
        INNER JOIN org.UOT AS U
            ON U.uot_id = UU.uot_id
           AND U.estado = 1
        WHERE UU.usuario_id = @nUsuarioId
          AND UU.estado = 1
          AND UU.fecha_hasta IS NULL
          AND seg.FN_Usuario_TienePermisoUOT(
                @nUsuarioId,
                UU.uot_id,
                'POS_OPERAR'
              ) = 1
    )
    BEGIN
        SET @cMensaje = N'No tiene permiso para operar el punto de venta.';
        SET @cCodigoRespuesta = 'POS_SIN_PERMISO';
        SET @nHttpRespuesta = 403;
        RETURN;
    END;

    SELECT
        CONVERT(INT, MP.metodo_pago_id) AS metodoPagoId,
        MP.codigo AS codigo,
        MP.nombre AS nombre,
        MP.requiere_numero_operacion AS requiereNumeroOperacion
    FROM comercial.MetodoPago AS MP
    WHERE MP.estado = 1
    ORDER BY
        CASE MP.codigo
            WHEN 'EFECTIVO' THEN 1
            WHEN 'YAPE' THEN 2
            WHEN 'PLIN' THEN 3
            WHEN 'TARJETA' THEN 4
            WHEN 'TRANSFERENCIA' THEN 5
            WHEN 'DEPOSITO' THEN 6
            ELSE 99
        END,
        MP.nombre;

    SET @bResultado = 1;
    SET @cMensaje = N'Métodos de pago consultados.';
    SET @cCodigoRespuesta = 'METODOS_PAGO_LISTADOS';
    SET @nHttpRespuesta = 200;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* ================================================================
   PA_Venta_Upd_Anular
   ================================================================ */
CREATE OR ALTER PROCEDURE [comercial].[PA_Venta_Upd_Anular]
 @nUsuarioId BIGINT,@nVentaId BIGINT,@cMotivo NVARCHAR(500),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON; SET @bResultado=0; SET @cMensaje=N'No se pudo anular la venta.';
 DECLARE @UOT BIGINT,@Almacen BIGINT,@Estado VARCHAR(20); SELECT @UOT=uot_id,@Almacen=almacen_id,@Estado=estado_venta FROM comercial.Venta WHERE venta_id=@nVentaId AND estado=1;
 IF @UOT IS NULL BEGIN SET @cMensaje=N'La venta no está disponible.'; RETURN; END;
 IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@UOT,'POS_OPERAR')=0 BEGIN SET @cMensaje=N'No tiene permiso para anular ventas.'; RETURN; END;
 IF NULLIF(LTRIM(RTRIM(@cMotivo)),N'') IS NULL BEGIN SET @cMensaje=N'Indique el motivo de anulación.'; RETURN; END;
 IF @Estado='ENTREGADA' BEGIN SET @cMensaje=N'Una venta entregada requiere un proceso de devolución, no anulación directa.'; RETURN; END;
 IF EXISTS(SELECT 1 FROM comercial.PagoVenta WHERE venta_id=@nVentaId AND estado=1 AND estado_pago='CONFIRMADO') BEGIN SET @cMensaje=N'Anule primero los pagos confirmados antes de anular la venta.'; RETURN; END;
 IF @Estado='ANULADA' BEGIN SET @bResultado=1; SET @cMensaje=N'La venta ya se encuentra anulada.'; RETURN; END;
 BEGIN TRY BEGIN TRAN;
 UPDATE S SET stock_reservado=S.stock_reservado-RS.cantidad,fecha_actualizacion=SYSUTCDATETIME()
 FROM logistica.AlmacenProductoStock S JOIN logistica.ReservaStock RS ON RS.almacen_id=S.almacen_id AND RS.producto_id=S.producto_id
 JOIN comercial.DetalleVenta DV ON DV.detalle_venta_id=RS.detalle_venta_id WHERE DV.venta_id=@nVentaId AND RS.estado_reserva='ACTIVA' AND RS.estado=1;
 UPDATE RS SET estado_reserva='LIBERADA',fecha_liberacion=SYSUTCDATETIME() FROM logistica.ReservaStock RS JOIN comercial.DetalleVenta DV ON DV.detalle_venta_id=RS.detalle_venta_id WHERE DV.venta_id=@nVentaId AND RS.estado_reserva='ACTIVA';
 UPDATE comercial.Venta SET estado_venta='ANULADA',fecha_anulacion=SYSUTCDATETIME(),usuario_anulacion_id=@nUsuarioId,motivo_anulacion=@cMotivo WHERE venta_id=@nVentaId;
 COMMIT; SET @bResultado=1; SET @cMensaje=N'Venta anulada correctamente.';
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SET @cMensaje=N'No se pudo anular la venta.'; END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* ================================================================
   PA_Venta_Upd_Entregar
   ================================================================ */
CREATE OR ALTER PROCEDURE [comercial].[PA_Venta_Upd_Entregar]
 @nUsuarioId BIGINT,@nVentaId BIGINT,@gClaveIdempotencia UNIQUEIDENTIFIER,@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON; SET @bResultado=0; SET @cMensaje=N'No se pudo entregar la venta.';
 DECLARE @UOT BIGINT,@Almacen BIGINT,@Total DECIMAL(19,4),@Estado VARCHAR(20); SELECT @UOT=uot_id,@Almacen=almacen_id,@Total=total,@Estado=estado_venta FROM comercial.Venta WHERE venta_id=@nVentaId AND estado=1;
 IF @UOT IS NULL BEGIN SET @cMensaje=N'La venta no está disponible.'; RETURN; END;
 IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@UOT,'POS_OPERAR')=0 BEGIN SET @cMensaje=N'No tiene permiso para entregar ventas.'; RETURN; END;
 IF @Estado='ENTREGADA' BEGIN SET @bResultado=1; SET @cMensaje=N'La venta ya fue entregada.'; RETURN; END;
 IF @Estado<>'PAGADA' BEGIN SET @cMensaje=N'La venta debe estar totalmente pagada antes de la entrega.'; RETURN; END;
 IF ISNULL((SELECT SUM(importe) FROM comercial.PagoVenta WHERE venta_id=@nVentaId AND estado=1 AND estado_pago='CONFIRMADO'),0)<>@Total BEGIN SET @cMensaje=N'El total pagado no coincide con el total de la venta.'; RETURN; END;
 BEGIN TRY SET TRANSACTION ISOLATION LEVEL SERIALIZABLE; BEGIN TRAN;
 /* Reservas activas consumen stock reservado; ventas directas descuentan disponible. */
 IF EXISTS(SELECT 1 FROM logistica.ReservaStock RS JOIN comercial.DetalleVenta DV ON DV.detalle_venta_id=RS.detalle_venta_id WHERE DV.venta_id=@nVentaId AND RS.estado_reserva='ACTIVA' AND RS.estado=1)
 BEGIN
   UPDATE S SET stock_actual=S.stock_actual-DV.cantidad,stock_reservado=S.stock_reservado-DV.cantidad,fecha_actualizacion=SYSUTCDATETIME()
   FROM logistica.AlmacenProductoStock S JOIN comercial.DetalleVenta DV ON DV.producto_id=S.producto_id AND DV.venta_id=@nVentaId AND DV.estado=1 WHERE S.almacen_id=@Almacen;
   UPDATE RS SET estado_reserva='CONSUMIDA',fecha_liberacion=SYSUTCDATETIME()
   FROM logistica.ReservaStock RS JOIN comercial.DetalleVenta DV ON DV.detalle_venta_id=RS.detalle_venta_id WHERE DV.venta_id=@nVentaId AND RS.estado_reserva='ACTIVA';
 END
 ELSE
 BEGIN
   IF EXISTS(SELECT 1 FROM comercial.DetalleVenta DV LEFT JOIN logistica.AlmacenProductoStock S WITH(UPDLOCK,HOLDLOCK) ON S.almacen_id=@Almacen AND S.producto_id=DV.producto_id WHERE DV.venta_id=@nVentaId AND DV.estado=1 AND ISNULL(S.stock_disponible,0)<DV.cantidad) THROW 51080,N'ENTREGA_STOCK_INSUFICIENTE',1;
   UPDATE S SET stock_actual=S.stock_actual-DV.cantidad,fecha_actualizacion=SYSUTCDATETIME()
   FROM logistica.AlmacenProductoStock S JOIN comercial.DetalleVenta DV ON DV.producto_id=S.producto_id AND DV.venta_id=@nVentaId AND DV.estado=1 WHERE S.almacen_id=@Almacen;
 END;
 INSERT logistica.MovimientoInventario(almacen_id,uot_id,tipo_movimiento,naturaleza,documento_referencia,clave_idempotencia,usuario_id,observacion,estado)
 VALUES(@Almacen,@UOT,'VENTA','S',CONCAT('VENTA-',@nVentaId),@gClaveIdempotencia,@nUsuarioId,N'Salida generada por entrega de venta.',1);
 DECLARE @Mov BIGINT=SCOPE_IDENTITY();
 INSERT logistica.DetalleMovimientoInventario(movimiento_inventario_id,producto_id,cantidad,costo_unitario,moneda)
 SELECT @Mov,producto_id,cantidad,NULL,'PEN' FROM comercial.DetalleVenta WHERE venta_id=@nVentaId AND estado=1;
 UPDATE comercial.Venta SET estado_venta='ENTREGADA' WHERE venta_id=@nVentaId;
 COMMIT; SET @bResultado=1; SET @cMensaje=N'Venta entregada correctamente.';
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SET @cMensaje=CASE WHEN ERROR_MESSAGE() LIKE '%ENTREGA_STOCK_INSUFICIENTE%' THEN N'No hay stock suficiente para entregar la venta.' WHEN ERROR_NUMBER() IN(2601,2627) THEN N'La entrega ya fue procesada.' ELSE N'No se pudo entregar la venta.' END; END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE comercial.PA_Venta_Upd_VencerReservas
 @dAhora DATETIME2(0)=NULL,@nProcesadas INT OUTPUT,@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON; SET @dAhora=COALESCE(@dAhora,SYSUTCDATETIME()); SET @nProcesadas=0; SET @bResultado=0; SET @cMensaje=N'No se pudieron liberar las reservas vencidas.';
 BEGIN TRY BEGIN TRAN;
 ;WITH R AS(SELECT RS.reserva_stock_id,RS.almacen_id,RS.producto_id,RS.cantidad,DV.venta_id FROM logistica.ReservaStock RS JOIN comercial.DetalleVenta DV ON DV.detalle_venta_id=RS.detalle_venta_id JOIN comercial.Venta V ON V.venta_id=DV.venta_id WHERE RS.estado=1 AND RS.estado_reserva='ACTIVA' AND RS.fecha_expiracion IS NOT NULL AND RS.fecha_expiracion<=@dAhora AND V.estado_venta IN('SEPARADA','REGISTRADA'))
 UPDATE S SET stock_reservado=S.stock_reservado-R.cantidad,fecha_actualizacion=SYSUTCDATETIME() FROM logistica.AlmacenProductoStock S JOIN R ON R.almacen_id=S.almacen_id AND R.producto_id=S.producto_id;
 UPDATE RS SET estado_reserva='VENCIDA',fecha_liberacion=@dAhora FROM logistica.ReservaStock RS JOIN comercial.DetalleVenta DV ON DV.detalle_venta_id=RS.detalle_venta_id JOIN comercial.Venta V ON V.venta_id=DV.venta_id WHERE RS.estado=1 AND RS.estado_reserva='ACTIVA' AND RS.fecha_expiracion IS NOT NULL AND RS.fecha_expiracion<=@dAhora AND V.estado_venta IN('SEPARADA','REGISTRADA');
 SET @nProcesadas=@@ROWCOUNT;
 UPDATE V SET estado_venta='ANULADA',fecha_anulacion=@dAhora,motivo_anulacion=N'Reserva vencida automáticamente.' FROM comercial.Venta V WHERE V.estado_venta='SEPARADA' AND V.fecha_reserva_hasta<=@dAhora AND NOT EXISTS(SELECT 1 FROM comercial.PagoVenta P WHERE P.venta_id=V.venta_id AND P.estado=1 AND P.estado_pago='CONFIRMADO');
 COMMIT; SET @bResultado=1; SET @cMensaje=N'Reservas vencidas procesadas correctamente.';
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SET @cMensaje=N'No se pudieron liberar las reservas vencidas.'; END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* Corrige creación genérica:
   - acepta el JSON real enviado por backend;
   - ignora el código artificial del frontend;
   - genera el código a partir del nombre + id. */
CREATE OR ALTER PROCEDURE [config].[PA_Catalogo_Ins_Registro](@cJson NVARCHAR(MAX),@nCatalogoId BIGINT OUTPUT,@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY
  SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),@nAud BIGINT,@nTrans BIGINT,@cCat VARCHAR(40),@cCodigo VARCHAR(40),@cNombre NVARCHAR(150),@cDesc NVARCHAR(300),@cCategoria VARCHAR(20),@cIdent NVARCHAR(200);
    SELECT @bResultado=0,@cMensaje=N'No se pudo registrar el valor del catálogo.';
    EXEC seg.PA_Operacion_Ins_IniciarIdempotente @cJson=@cJson,@cCodigoPermiso='CATALOGOS_CREAR',@cAmbito='CATALOGO_CREAR',@nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@nOperacionIdempotenteId=@nOp OUTPUT,@bEsRepetida=@bRep OUTPUT,@cEstadoOperacion=@cEstadoOp OUTPUT,@cIdentificadorResultado=@cIdRes OUTPUT,@cCodigoResultado=@cCodRes OUTPUT,@bResultado=@bIni OUTPUT,@cMensaje=@cMsg OUTPUT;
    IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
GOTO __DESCO_Salida;
END;
    IF @bRep=1 BEGIN SET @nCatalogoId=CASE WHEN @cEstadoOp='COMPLETADA' THEN TRY_CONVERT(BIGINT,@cIdRes) ELSE NULL END;
 SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
SET @cMensaje=CASE WHEN @cEstadoOp='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.' ELSE N'La solicitud ya se encuentra en proceso.' END;
GOTO __DESCO_Salida;
END;
SET @nCatalogoId=NULL;
SELECT
    @cCat = UPPER(NULLIF(LTRIM(RTRIM(COALESCE(
        JSON_VALUE(@cJson,'$.catalogo.catalogo'),
        JSON_VALUE(@cJson,'$.catalogo'),
        JSON_VALUE(@cJson,'$.datos.catalogo'),
        JSON_VALUE(@cJson,'$.command.catalogo')
    ))),'')),
    @cNombre = NULLIF(LTRIM(RTRIM(COALESCE(
        JSON_VALUE(@cJson,'$.catalogo.nombre'),
        JSON_VALUE(@cJson,'$.nombre'),
        JSON_VALUE(@cJson,'$.datos.nombre'),
        JSON_VALUE(@cJson,'$.command.nombre')
    ))),N''),
    @cDesc = NULLIF(LTRIM(RTRIM(COALESCE(
        JSON_VALUE(@cJson,'$.catalogo.descripcion'),
        JSON_VALUE(@cJson,'$.descripcion'),
        JSON_VALUE(@cJson,'$.datos.descripcion'),
        JSON_VALUE(@cJson,'$.command.descripcion')
    ))),N''),
    @cCategoria = UPPER(NULLIF(LTRIM(RTRIM(COALESCE(
        JSON_VALUE(@cJson,'$.catalogo.categoria'),
        JSON_VALUE(@cJson,'$.categoria'),
        JSON_VALUE(@cJson,'$.datos.categoria'),
        JSON_VALUE(@cJson,'$.command.categoria')
    ))),''));

IF @cCat IS NULL OR @cNombre IS NULL
BEGIN
    SET @cMensaje=N'Complete correctamente los datos del catálogo.';
    GOTO Fallar;
END;

SET @cCodigo = CONCAT(
    'TMP-',
    LEFT(REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),20)
);
BEGIN TRY BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;
IF @cCat='MOTIVO_SALIDA' BEGIN IF EXISTS(SELECT 1 FROM campo.MotivoSalida WHERE codigo=@cCodigo) THROW 53401,N'VALOR_DUPLICADO',1;
 INSERT campo.MotivoSalida(codigo,nombre,estado) VALUES(@cCodigo,@cNombre,1);
SET @nCatalogoId=SCOPE_IDENTITY();
END
ELSE IF @cCat='TIPO_EVALUACION' BEGIN IF EXISTS(SELECT 1 FROM campo.TipoEvaluacion WHERE codigo=@cCodigo) THROW 53401,N'VALOR_DUPLICADO',1;
 INSERT campo.TipoEvaluacion(codigo,nombre,estado) VALUES(@cCodigo,@cNombre,1);
SET @nCatalogoId=SCOPE_IDENTITY();
END
ELSE IF @cCat='VARIEDAD_PALTA' BEGIN IF EXISTS(SELECT 1 FROM prod.VariedadPalta WHERE codigo=@cCodigo) THROW 53401,N'VALOR_DUPLICADO',1;
 INSERT prod.VariedadPalta(codigo,nombre,estado) VALUES(@cCodigo,@cNombre,1);
SET @nCatalogoId=SCOPE_IDENTITY();
END
ELSE IF @cCat='PROBLEMA_FITOSANITARIO' BEGIN IF @cCategoria NOT IN('PLAGA','ENFERMEDAD','OTRO') BEGIN BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @cMensaje=N'Seleccione una categoría válida.';
GOTO Fallar;
END;
 IF EXISTS(SELECT 1 FROM sanidad.TipoProblemaFitosanitario WHERE codigo=@cCodigo) THROW 53401,N'VALOR_DUPLICADO',1;
 INSERT sanidad.TipoProblemaFitosanitario(categoria,codigo,nombre,estado) VALUES(@cCategoria,@cCodigo,@cNombre,1);
SET @nCatalogoId=SCOPE_IDENTITY();
END
ELSE IF @cCat='MODALIDAD_VENTA' BEGIN IF EXISTS(SELECT 1 FROM comercial.ModalidadVenta WHERE codigo=@cCodigo) THROW 53401,N'VALOR_DUPLICADO',1;
 INSERT comercial.ModalidadVenta(codigo,nombre,estado) VALUES(@cCodigo,@cNombre,1);
SET @nCatalogoId=SCOPE_IDENTITY();
END
ELSE IF @cCat='TIPO_GASTO' BEGIN IF EXISTS(SELECT 1 FROM finanzas.TipoGasto WHERE codigo=@cCodigo) THROW 53401,N'VALOR_DUPLICADO',1;
 INSERT finanzas.TipoGasto(codigo,nombre,estado) VALUES(@cCodigo,@cNombre,1);
SET @nCatalogoId=SCOPE_IDENTITY();
END
ELSE IF @cCat='REGLA_PRORRATEO' BEGIN IF EXISTS(SELECT 1 FROM finanzas.ReglaProrrateo WHERE codigo=@cCodigo) THROW 53401,N'VALOR_DUPLICADO',1;
 INSERT finanzas.ReglaProrrateo(codigo,nombre,estado) VALUES(@cCodigo,@cNombre,1);
SET @nCatalogoId=SCOPE_IDENTITY();
END
ELSE IF @cCat='TIPO_BIEN' BEGIN IF EXISTS(SELECT 1 FROM logistica.TipoBien WHERE codigo=@cCodigo) THROW 53401,N'VALOR_DUPLICADO',1;
 INSERT logistica.TipoBien(codigo,nombre,estado) VALUES(@cCodigo,@cNombre,1);
SET @nCatalogoId=SCOPE_IDENTITY();
END
ELSE IF @cCat='ZONA_PRODUCTIVA' BEGIN IF EXISTS(SELECT 1 FROM geo.ZonaProductiva WHERE codigo=@cCodigo) THROW 53401,N'VALOR_DUPLICADO',1;
 INSERT geo.ZonaProductiva(codigo,nombre,descripcion,estado) VALUES(@cCodigo,@cNombre,@cDesc,1);
SET @nCatalogoId=SCOPE_IDENTITY();
END
ELSE BEGIN BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @cMensaje=N'El catálogo seleccionado no está disponible para registro.';
GOTO Fallar;
END;
SET @cCodigo = [config].[FN_CodigoCatalogo](@cNombre,@nCatalogoId);

IF @cCat='MOTIVO_SALIDA'
    UPDATE campo.MotivoSalida SET codigo=@cCodigo WHERE motivo_salida_id=@nCatalogoId;
ELSE IF @cCat='TIPO_EVALUACION'
    UPDATE campo.TipoEvaluacion SET codigo=@cCodigo WHERE tipo_evaluacion_id=@nCatalogoId;
ELSE IF @cCat='VARIEDAD_PALTA'
    UPDATE prod.VariedadPalta SET codigo=@cCodigo WHERE variedad_palta_id=@nCatalogoId;
ELSE IF @cCat='PROBLEMA_FITOSANITARIO'
    UPDATE sanidad.TipoProblemaFitosanitario SET codigo=@cCodigo WHERE tipo_problema_fitosanitario_id=@nCatalogoId;
ELSE IF @cCat='MODALIDAD_VENTA'
    UPDATE comercial.ModalidadVenta SET codigo=@cCodigo WHERE modalidad_venta_id=@nCatalogoId;
ELSE IF @cCat='TIPO_GASTO'
    UPDATE finanzas.TipoGasto SET codigo=@cCodigo WHERE tipo_gasto_id=@nCatalogoId;
ELSE IF @cCat='REGLA_PRORRATEO'
    UPDATE finanzas.ReglaProrrateo SET codigo=@cCodigo WHERE regla_prorrateo_id=@nCatalogoId;
ELSE IF @cCat='TIPO_BIEN'
    UPDATE logistica.TipoBien SET codigo=@cCodigo WHERE tipo_bien_id=@nCatalogoId;
ELSE IF @cCat='ZONA_PRODUCTIVA'
    UPDATE geo.ZonaProductiva SET codigo=@cCodigo WHERE zona_productiva_id=@nCatalogoId;

SET @cIdent=CONVERT(NVARCHAR(200),@nCatalogoId);
EXEC auditoria.PA_Operacion_Ins_RegistrarCambio @nUsuario,@nSesion,@nDisp,@nModulo,'CREAR','config',@cCat,@cIdent,NULL,NULL,NULL,NULL,NULL,NULL,@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
/* Confirmar datos e idempotencia juntos. */
EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='COMPLETADA',@cEsquemaEntidad='config',@cNombreEntidad='Catalogo',@cIdentificadorResultado=@cIdent,@cCodigoResultado='CATALOGO_REGISTRADO',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
 SET @bResultado=1;
SET @cMensaje=N'Valor registrado correctamente.';
GOTO __DESCO_Salida;
END TRY BEGIN CATCH
SET @bResultado = 0;
 IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ERROR_MESSAGE()=N'VALOR_DUPLICADO' SET @cMensaje=N'Ya existe un valor con ese código.';
ELSE SET @cMensaje=N'No se pudo registrar el valor. Intente nuevamente.';
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'config.PA_Catalogo_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;
Fallar: IF @nOp IS NOT NULL AND @bResultado=0 EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='FALLIDA',@cEsquemaEntidad=NULL,@cNombreEntidad=NULL,@cIdentificadorResultado=NULL,@cCodigoResultado='NO_PROCESADO',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
 
    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'config.PA_Catalogo_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

    IF @bResultado = 0 AND @nOp IS NOT NULL AND XACT_STATE() <> -1
    BEGIN
        IF ISNULL(@bRep,0) = 0
        BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                 @nOperacionIdempotenteId = @nOp, @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
            -- No sustituir el motivo funcional por un fallo de registro secundario.
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'config.PA_Catalogo_Ins_Registro',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
        END CATCH;
        END
        ELSE
        BEGIN
            SELECT @cMensaje = COALESCE(mensaje_resultado,
                CASE WHEN estado_operacion = 'FALLIDA'
                     THEN N'La solicitud anterior no se completó. Corrija los datos y envíe una nueva solicitud.'
                     ELSE N'La solicitud todavía se está procesando. Consulte el resultado antes de repetirla.' END)
            FROM [auditoria].[OperacionIdempotente]
            WHERE operacion_idempotente_id = @nOp;
        END;
    END;
IF @bResultado = 0
    SELECT @nCatalogoId = NULL;

END TRY
BEGIN CATCH

