SET @bResultado = 0;
END;

    IF @bResultado = 0 AND @nOp IS NOT NULL AND XACT_STATE() <> -1
    BEGIN
        IF ISNULL(@bRep,0) = 0
        BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                 @nOperacionIdempotenteId = @nOp, @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
            -- No sustituir el motivo funcional por un fallo de registro secundario.
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'config.PA_Catalogo_Upd_Registro',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
        END CATCH;
        END
        ELSE
        BEGIN
            SELECT @cMensaje = COALESCE(mensaje_resultado,
                CASE WHEN estado_operacion = 'FALLIDA'
                     THEN N'La solicitud anterior no se completó. Corrija los datos y envíe una nueva solicitud.'
                     ELSE N'La solicitud todavía se está procesando. Consulte el resultado antes de repetirla.' END)
            FROM [auditoria].[OperacionIdempotente]
            WHERE operacion_idempotente_id = @nOp;
        END;
    END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'config.PA_Catalogo_Upd_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'config.PA_Catalogo_Upd_Registro',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [config].[PA_CatalogoRecurso_Ins_Registro]
    @nUsuarioId BIGINT,
    @cCatalogo VARCHAR(40),
    @cCodigo VARCHAR(40),
    @cNombre NVARCHAR(150),
    @cDescripcion NVARCHAR(300)=NULL,
    @nCatalogoId BIGINT OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        @nCatalogoId=NULL,
        @bResultado=0,
        @cMensaje=N'No se pudo registrar el valor.',
        @cCodigoRespuesta='CATALOGO_NO_CREADO',
        @nHttpRespuesta=400;

    SELECT
        @cCatalogo=UPPER(NULLIF(LTRIM(RTRIM(@cCatalogo)),'')),
        @cCodigo=UPPER(NULLIF(LTRIM(RTRIM(@cCodigo)),'')),
        @cNombre=NULLIF(LTRIM(RTRIM(@cNombre)),N''),
        @cDescripcion=NULLIF(LTRIM(RTRIM(@cDescripcion)),N'');

    IF @cCatalogo NOT IN
       (
           'TIPO_VEHICULO',
           'UNIDAD_MEDIDA',
           'CATEGORIA_PRODUCTO',
           'MONEDA',
           'CARGO_EMPLEADO'
       )
       OR @cNombre IS NULL
    BEGIN
        SET @cMensaje=N'Complete correctamente los datos del catálogo.';
        RETURN 1;
    END;

    IF @cCatalogo IN('MONEDA','UNIDAD_MEDIDA')
       AND @cCodigo IS NULL
    BEGIN
        SET @cMensaje=N'Ingrese el código del valor.';
        RETURN 1;
    END;

    IF @cCatalogo='MONEDA'
       AND
       (
           LEN(@cCodigo)<>3
           OR @cCodigo LIKE '%[^A-Z]%'
       )
    BEGIN
        SET @cMensaje=N'El código de moneda debe tener tres letras.';
        RETURN 1;
    END;

    IF @cCatalogo='UNIDAD_MEDIDA'
       AND LEN(@cCodigo)>20
    BEGIN
        SET @cMensaje=N'El código de unidad de medida es demasiado largo.';
        RETURN 1;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM seg.UsuarioRol UR
        JOIN seg.Rol R
          ON R.rol_id=UR.rol_id
         AND R.estado=1
        JOIN seg.RolPermiso RP
          ON RP.rol_id=R.rol_id
         AND RP.estado=1
        JOIN seg.Permiso P
          ON P.permiso_id=RP.permiso_id
         AND P.estado=1
         AND P.codigo='CATALOGOS_CREAR'
        WHERE UR.usuario_id=@nUsuarioId
          AND UR.estado=1
          AND UR.fecha_desde<=SYSUTCDATETIME()
          AND
          (
              UR.fecha_hasta IS NULL
              OR UR.fecha_hasta>SYSUTCDATETIME()
          )
    )
    BEGIN
        SET @cMensaje=N'No tiene permiso para registrar catálogos.';
        SET @cCodigoRespuesta='NO_AUTORIZADO';
        SET @nHttpRespuesta=403;
        RETURN 1;
    END;

    IF @cCatalogo IN('TIPO_VEHICULO','CATEGORIA_PRODUCTO','CARGO_EMPLEADO')
    BEGIN
        SET @cCodigo=CONCAT(
            'TMP-',
            LEFT(
                REPLACE(
                    CONVERT(VARCHAR(36),NEWID()),
                    '-',
                    ''
                ),
                20
            )
        );
    END;

    IF EXISTS
    (
        SELECT 1
        FROM config.CatalogoRecursoValor
        WHERE catalogo=@cCatalogo
          AND codigo=@cCodigo
    )
    BEGIN
        SET @cMensaje=N'El código ya está registrado.';
        SET @cCodigoRespuesta='DATO_DUPLICADO';
        SET @nHttpRespuesta=409;
        RETURN 1;
    END;

    BEGIN TRY
        BEGIN TRANSACTION;

        INSERT config.CatalogoRecursoValor
        (
            catalogo,
            codigo,
            nombre,
            descripcion,
            estado
        )
        VALUES
        (
            @cCatalogo,
            @cCodigo,
            @cNombre,
            @cDescripcion,
            1
        );

        SET @nCatalogoId=CONVERT(BIGINT,SCOPE_IDENTITY());

        IF @cCatalogo IN('TIPO_VEHICULO','CATEGORIA_PRODUCTO','CARGO_EMPLEADO')
        BEGIN
            SET @cCodigo=
                config.FN_CodigoCatalogo(
                    @cNombre,
                    @nCatalogoId
                );

            UPDATE config.CatalogoRecursoValor
               SET codigo=@cCodigo,
                   fecha_actualizacion=SYSUTCDATETIME()
             WHERE catalogo_recurso_valor_id=@nCatalogoId;
        END;

        COMMIT TRANSACTION;

        SELECT
            @bResultado=1,
            @cMensaje=N'Valor registrado.',
            @cCodigoRespuesta='CATALOGO_CREADO',
            @nHttpRespuesta=201;

        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0
            ROLLBACK TRANSACTION;

        SET @nCatalogoId=NULL;
        SET @cMensaje=N'No se pudo registrar el valor.';
        RETURN 1;
    END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* 2. Catálogo administrable de cargos. */
CREATE OR ALTER PROCEDURE [config].[PA_CatalogoRecurso_Sel_Listado]
    @nUsuarioId BIGINT,
    @cCatalogo VARCHAR(40),
    @nPagina INT=1,
    @nTamano INT=20,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT @bResultado=0,@cMensaje=N'No se pudo consultar el catálogo.',@cCodigoRespuesta='CATALOGO_NO_LISTADO',@nHttpRespuesta=400;
    SET @cCatalogo=UPPER(NULLIF(LTRIM(RTRIM(@cCatalogo)),''));
    SET @nPagina=CASE WHEN ISNULL(@nPagina,0)<1 THEN 1 ELSE @nPagina END;
    SET @nTamano=CASE WHEN ISNULL(@nTamano,0)<1 THEN 20 WHEN @nTamano>100 THEN 100 ELSE @nTamano END;
    IF @cCatalogo NOT IN('TIPO_VEHICULO','UNIDAD_MEDIDA','CATEGORIA_PRODUCTO','MONEDA','CARGO_EMPLEADO') BEGIN SET @cMensaje=N'El catálogo seleccionado no está disponible.'; RETURN 1; END;
    IF NOT EXISTS(
        SELECT 1 FROM seg.UsuarioRol UR JOIN seg.Rol R ON R.rol_id=UR.rol_id AND R.estado=1
        JOIN seg.RolPermiso RP ON RP.rol_id=R.rol_id AND RP.estado=1
        JOIN seg.Permiso P ON P.permiso_id=RP.permiso_id AND P.estado=1 AND P.codigo='REFERENCIAS_LISTAR'
        WHERE UR.usuario_id=@nUsuarioId AND UR.estado=1 AND UR.fecha_desde<=SYSUTCDATETIME()
          AND (UR.fecha_hasta IS NULL OR UR.fecha_hasta>SYSUTCDATETIME())
    ) BEGIN SET @cMensaje=N'No tiene permiso para consultar catálogos.'; SET @cCodigoRespuesta='NO_AUTORIZADO'; SET @nHttpRespuesta=403; RETURN 1; END;

    ;WITH C AS(
        SELECT V.*,
          CONVERT(BIGINT,
             CASE V.catalogo
              WHEN 'TIPO_VEHICULO' THEN (SELECT COUNT_BIG(*) FROM logistica.Vehiculo X WHERE UPPER(X.tipo_vehiculo)=V.codigo)
              WHEN 'UNIDAD_MEDIDA' THEN (SELECT COUNT_BIG(*) FROM logistica.Producto X WHERE UPPER(X.unidad_medida)=V.codigo)+(SELECT COUNT_BIG(*) FROM logistica.Suministro X WHERE UPPER(X.unidad_medida)=V.codigo)
              WHEN 'CATEGORIA_PRODUCTO' THEN (SELECT COUNT_BIG(*) FROM logistica.Producto X WHERE UPPER(CONVERT(VARCHAR(100),X.categoria))=V.codigo)
              WHEN 'MONEDA' THEN (SELECT COUNT_BIG(*) FROM logistica.ProductoPrecio X WHERE UPPER(X.moneda)=V.codigo)+(SELECT COUNT_BIG(*) FROM logistica.DetalleMovimientoInventario X WHERE UPPER(X.moneda)=V.codigo)+(SELECT COUNT_BIG(*) FROM logistica.BienInventario X WHERE UPPER(X.moneda_adquisicion)=V.codigo)
              WHEN 'CARGO_EMPLEADO' THEN (SELECT COUNT_BIG(*) FROM org.EmpleadoArea X WHERE X.cargo COLLATE DATABASE_DEFAULT
                    = V.nombre COLLATE DATABASE_DEFAULT)
              ELSE 0 END) cantidadUso
        FROM config.CatalogoRecursoValor V WHERE V.catalogo=@cCatalogo
    )
    SELECT catalogo_recurso_valor_id id,codigo,nombre,descripcion,estado,cantidadUso,
           CONVERT(BIT,CASE WHEN cantidadUso>0 THEN 1 ELSE 0 END) enUso,COUNT_BIG(*) OVER() totalRegistros
    FROM C
    ORDER BY nombre,catalogo_recurso_valor_id
    OFFSET (@nPagina-1)*@nTamano ROWS FETCH NEXT @nTamano ROWS ONLY;

    SELECT @bResultado=1,@cMensaje=N'Catálogo consultado.',@cCodigoRespuesta='CATALOGO_LISTADO',@nHttpRespuesta=200;
    RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [config].[PA_CatalogoRecurso_Upd_Deshabilitar]
    @nUsuarioId BIGINT,@cCatalogo VARCHAR(40),@nCatalogoId BIGINT,@cMotivo NVARCHAR(300),
    @bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,@cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT @bResultado=0,@cMensaje=N'No se pudo deshabilitar el valor.',@cCodigoRespuesta='CATALOGO_NO_DESHABILITADO',@nHttpRespuesta=400;
    SELECT @cCatalogo=UPPER(NULLIF(LTRIM(RTRIM(@cCatalogo)),'')),@cMotivo=NULLIF(LTRIM(RTRIM(@cMotivo)),N'');
    IF @cCatalogo NOT IN('TIPO_VEHICULO','UNIDAD_MEDIDA','CATEGORIA_PRODUCTO','MONEDA') OR @nCatalogoId IS NULL OR @cMotivo IS NULL BEGIN SET @cMensaje=N'Seleccione el valor e indique el motivo.'; RETURN 1; END;
    IF NOT EXISTS(
        SELECT 1 FROM seg.UsuarioRol UR JOIN seg.Rol R ON R.rol_id=UR.rol_id AND R.estado=1 JOIN seg.RolPermiso RP ON RP.rol_id=R.rol_id AND RP.estado=1 JOIN seg.Permiso P ON P.permiso_id=RP.permiso_id AND P.estado=1 AND P.codigo='CATALOGOS_RETIRAR'
        WHERE UR.usuario_id=@nUsuarioId AND UR.estado=1 AND UR.fecha_desde<=SYSUTCDATETIME() AND (UR.fecha_hasta IS NULL OR UR.fecha_hasta>SYSUTCDATETIME())
    ) BEGIN SET @cMensaje=N'No tiene permiso para deshabilitar catálogos.'; SET @cCodigoRespuesta='NO_AUTORIZADO'; SET @nHttpRespuesta=403; RETURN 1; END;
    DECLARE @cCodigo VARCHAR(40);
    SELECT @cCodigo=codigo FROM config.CatalogoRecursoValor WHERE catalogo_recurso_valor_id=@nCatalogoId AND catalogo=@cCatalogo AND estado=1;
    IF @cCodigo IS NULL BEGIN SET @cMensaje=N'El valor seleccionado no está disponible.'; SET @cCodigoRespuesta='NO_ENCONTRADO'; SET @nHttpRespuesta=404; RETURN 1; END;
    UPDATE config.CatalogoRecursoValor SET estado=0,fecha_actualizacion=SYSUTCDATETIME() WHERE catalogo_recurso_valor_id=@nCatalogoId;
    SELECT @bResultado=1,@cMensaje=N'Valor deshabilitado.',@cCodigoRespuesta='CATALOGO_DESHABILITADO',@nHttpRespuesta=200; RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [config].[PA_CatalogoRecurso_Upd_Registro]
    @nUsuarioId BIGINT,
    @cCatalogo VARCHAR(40),
    @nCatalogoId BIGINT,
    @cNombre NVARCHAR(150),
    @cDescripcion NVARCHAR(300)=NULL,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        @bResultado=0,
        @cMensaje=N'No se pudo actualizar el valor.',
        @cCodigoRespuesta='CATALOGO_NO_ACTUALIZADO',
        @nHttpRespuesta=400;

    SELECT
        @cCatalogo=UPPER(NULLIF(LTRIM(RTRIM(@cCatalogo)),'')),
        @cNombre=NULLIF(LTRIM(RTRIM(@cNombre)),N''),
        @cDescripcion=NULLIF(LTRIM(RTRIM(@cDescripcion)),N'');

    IF @cCatalogo NOT IN
       (
           'TIPO_VEHICULO',
           'UNIDAD_MEDIDA',
           'CATEGORIA_PRODUCTO',
           'MONEDA',
           'CARGO_EMPLEADO'
       )
       OR @nCatalogoId IS NULL
       OR @cNombre IS NULL
    BEGIN
        SET @cMensaje=N'Complete correctamente los datos del catálogo.';
        RETURN 1;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM seg.UsuarioRol UR
        JOIN seg.Rol R
          ON R.rol_id=UR.rol_id
         AND R.estado=1
        JOIN seg.RolPermiso RP
          ON RP.rol_id=R.rol_id
         AND RP.estado=1
        JOIN seg.Permiso P
          ON P.permiso_id=RP.permiso_id
         AND P.estado=1
         AND P.codigo='CATALOGOS_EDITAR'
        WHERE UR.usuario_id=@nUsuarioId
          AND UR.estado=1
          AND UR.fecha_desde<=SYSUTCDATETIME()
          AND
          (
              UR.fecha_hasta IS NULL
              OR UR.fecha_hasta>SYSUTCDATETIME()
          )
    )
    BEGIN
        SET @cMensaje=N'No tiene permiso para actualizar catálogos.';
        SET @cCodigoRespuesta='NO_AUTORIZADO';
        SET @nHttpRespuesta=403;
        RETURN 1;
    END;

    DECLARE
        @cCodigoAnterior VARCHAR(40),
        @cCodigoNuevo VARCHAR(40),
        @cNombreAnterior NVARCHAR(150);

    SELECT
        @cCodigoAnterior=codigo,
        @cNombreAnterior=nombre
    FROM config.CatalogoRecursoValor
    WHERE catalogo_recurso_valor_id=@nCatalogoId
      AND catalogo=@cCatalogo
      AND estado=1;

    IF @cCodigoAnterior IS NULL
    BEGIN
        SET @cMensaje=N'El valor seleccionado no está disponible.';
        SET @cCodigoRespuesta='NO_ENCONTRADO';
        SET @nHttpRespuesta=404;
        RETURN 1;
    END;

    SET @cCodigoNuevo=
        CASE
            WHEN @cCatalogo IN
                 (
                     'TIPO_VEHICULO',
                     'CATEGORIA_PRODUCTO',
                     'CARGO_EMPLEADO'
                 )
            THEN config.FN_CodigoCatalogo(
                     @cNombre,
                     @nCatalogoId
                 )
            ELSE @cCodigoAnterior
        END;

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @cCatalogo='TIPO_VEHICULO'
           AND @cCodigoNuevo<>@cCodigoAnterior
        BEGIN
            UPDATE logistica.Vehiculo
               SET tipo_vehiculo=@cCodigoNuevo
             WHERE UPPER(tipo_vehiculo)=UPPER(@cCodigoAnterior);
        END;

        IF @cCatalogo='CATEGORIA_PRODUCTO'
           AND @cCodigoNuevo<>@cCodigoAnterior
        BEGIN
            UPDATE logistica.Producto
               SET categoria=@cCodigoNuevo
             WHERE UPPER(CONVERT(VARCHAR(100),categoria))
                   =UPPER(@cCodigoAnterior);
        END;

        IF @cCatalogo='CARGO_EMPLEADO'
           AND ISNULL(@cNombreAnterior,N'')<>ISNULL(@cNombre,N'')
        BEGIN
            UPDATE org.EmpleadoArea
               SET cargo=@cNombre
             WHERE cargo=@cNombreAnterior;
        END;

        UPDATE config.CatalogoRecursoValor
           SET codigo=@cCodigoNuevo,
               nombre=@cNombre,
               descripcion=@cDescripcion,
               fecha_actualizacion=SYSUTCDATETIME()
         WHERE catalogo_recurso_valor_id=@nCatalogoId
           AND catalogo=@cCatalogo
           AND estado=1;

        IF @@ROWCOUNT=0
        BEGIN
            ROLLBACK TRANSACTION;
            SET @cMensaje=N'El valor seleccionado no está disponible.';
            SET @cCodigoRespuesta='NO_ENCONTRADO';
            SET @nHttpRespuesta=404;
            RETURN 1;
        END;

        COMMIT TRANSACTION;

        SELECT
            @bResultado=1,
            @cMensaje=N'Valor actualizado.',
            @cCodigoRespuesta='CATALOGO_ACTUALIZADO',
            @nHttpRespuesta=200;

        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0
            ROLLBACK TRANSACTION;

        SET @cMensaje=N'No se pudo actualizar el valor.';
        RETURN 1;
    END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- config.PA_Dashboard_Sel_Configuracion
CREATE OR ALTER PROCEDURE [config].[PA_Dashboard_Sel_Configuracion]
(
    @cJson NVARCHAR(MAX),
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;

    BEGIN TRY

    SET NOCOUNT ON;

    DECLARE
        @nUsuario BIGINT,
        @nSesion BIGINT,
        @nDisp BIGINT,
        @nEmp BIGINT,
        @nModulo INT,
        @gCorr UNIQUEIDENTIFIER,
        @gSol UNIQUEIDENTIFIER,
        @cIp VARCHAR(64),
        @cEnd NVARCHAR(250),
        @bCtx BIT,
        @cMsg NVARCHAR(300);

    SELECT @bResultado=0,@cMensaje=N'No se pudo consultar la configuración del dashboard.';

    EXEC [seg].[PA_Operacion_Sel_ContextoAutorizado]
        @cJson=@cJson,
        @cCodigoPermiso='INICIO_ADMINISTRAR',
        @nUsuarioId=@nUsuario OUTPUT,
        @nSesionUsuarioId=@nSesion OUTPUT,
        @nDispositivoUsuarioId=@nDisp OUTPUT,
        @nEmpleadoId=@nEmp OUTPUT,
        @nModuloId=@nModulo OUTPUT,
        @gCorrelacionId=@gCorr OUTPUT,
        @gSolicitudId=@gSol OUTPUT,
        @cIp=@cIp OUTPUT,
        @cEndpoint=@cEnd OUTPUT,
        @bResultado=@bCtx OUTPUT,
        @cMensaje=@cMsg OUTPUT;

    IF @bCtx=0
    BEGIN
        SET @cMensaje=@cMsg;
        GOTO __DESCO_Salida;
    END;

    SELECT
        E.dashboard_elemento_id dashboardElementoId,
        E.codigo,
        E.tipo,
        E.titulo,
        E.subtitulo,
        P.codigo permisoRequerido,
        M.codigo codigoModulo,
        M.nombre nombreModulo,
        E.unidad,
        E.tipo_grafico tipoGrafico,
        E.permite_fechas permiteFechas,
        E.ancho,
        E.orden,
        E.estado
    FROM [config].[DashboardElemento] E
    INNER JOIN [seg].[Permiso] P
        ON P.permiso_id=E.permiso_id
    INNER JOIN [seg].[Modulo] M
        ON M.modulo_id=P.modulo_id
    ORDER BY E.tipo,E.orden,E.titulo;

    SELECT
        R.rol_id rolId,
        R.codigo codigoRol,
        R.nombre nombreRol,
        E.codigo codigoElemento,
        RE.visible,
        RE.orden
    FROM [config].[DashboardRolElemento] RE
    INNER JOIN [seg].[Rol] R
        ON R.rol_id=RE.rol_id
    INNER JOIN [config].[DashboardElemento] E
        ON E.dashboard_elemento_id=RE.dashboard_elemento_id
    WHERE R.estado=1
    ORDER BY R.nombre,COALESCE(RE.orden,E.orden),E.titulo;

    SELECT
        U.usuario_id usuarioId,
        U.nombre_usuario nombreUsuario,
        E.codigo codigoElemento,
        UE.visible,
        UE.orden
    FROM [config].[DashboardUsuarioElemento] UE
    INNER JOIN [seg].[Usuario] U
        ON U.usuario_id=UE.usuario_id
    INNER JOIN [config].[DashboardElemento] E
        ON E.dashboard_elemento_id=UE.dashboard_elemento_id
    WHERE U.estado=1
    ORDER BY U.nombre_usuario,COALESCE(UE.orden,E.orden),E.titulo;

    SET @bResultado=1;
    SET @cMensaje=N'Configuración del dashboard consultada correctamente.';

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'config.PA_Dashboard_Sel_Configuracion',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'config.PA_Dashboard_Sel_Configuracion',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'config.PA_Dashboard_Sel_Configuracion',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- config.PA_Respuesta_ResolverError
CREATE OR ALTER PROCEDURE config.PA_Respuesta_ResolverError
 @cProcedimiento NVARCHAR(257),@cMensaje NVARCHAR(300) OUTPUT,@cJson NVARCHAR(MAX)=NULL,
 @bMensajePublicoGenerico BIT=0,@nNumeroError INT=NULL,@cDetalleError NVARCHAR(4000)=NULL,
 @bRegistrar BIT=1,@cCodigo VARCHAR(60)=NULL OUTPUT,@nHttpSugerido SMALLINT=NULL OUTPUT,
 @bReintentable BIT=NULL OUTPUT,@bResultado BIT=NULL OUTPUT,
 @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON;
 DECLARE @numero INT=COALESCE(@nNumeroError,ERROR_NUMBER(),0),
 @detalle NVARCHAR(4000)=COALESCE(@cDetalleError,ERROR_MESSAGE(),N''),
 @linea INT=ERROR_LINE(),@origen NVARCHAR(257)=COALESCE(ERROR_PROCEDURE(),@cProcedimiento),
 @clave VARCHAR(150),@correlacion UNIQUEIDENTIFIER;
 SELECT @bResultado=0,@cMensaje=N'No se pudo completar la acción. Intente nuevamente.',
 @cCodigo='ERROR_INTERNO',@nHttpSugerido=500,@bReintentable=0;
 BEGIN TRY
  SELECT TOP(1) @clave=R.clave,@cMensaje=R.mensaje,@cCodigo=R.codigo,
   @nHttpSugerido=R.http_sugerido,@bReintentable=R.reintentable
  FROM config.RespuestaBaseDatos R WHERE R.estado=1 AND
   ((@numero IN(2601,2627,547) AND
     (CHARINDEX(NCHAR(39)+CONVERT(NVARCHAR(150),R.clave)+NCHAR(39),@detalle)>0
       OR CHARINDEX(N'"'+CONVERT(NVARCHAR(150),R.clave)+N'"',@detalle)>0
       OR CHARINDEX(N'['+CONVERT(NVARCHAR(150),R.clave)+N']',@detalle)>0))
    OR (@numero>=50000 AND @detalle=CONVERT(NVARCHAR(150),R.clave)))
  ORDER BY LEN(R.clave) DESC,R.clave;
  IF @clave IS NULL AND @numero>=50000
  BEGIN
   SELECT TOP(1) @clave='MENSAJE_APROBADO',@cMensaje=M.mensaje,@cCodigo=M.codigo_error,@nHttpSugerido=M.http_error
   FROM config.MensajeUsuario M WHERE M.texto_origen=@detalle OR M.mensaje=@detalle
   ORDER BY CASE WHEN M.texto_origen=@detalle THEN 0 ELSE 1 END,M.texto_origen;
  END;
  IF @clave IS NULL
   SELECT @cMensaje=R.mensaje,@cCodigo=R.codigo,@nHttpSugerido=R.http_sugerido,@bReintentable=R.reintentable
   FROM config.RespuestaBaseDatos R WHERE R.estado=1 AND R.clave='SQL_'+CONVERT(VARCHAR(11),@numero);
  IF ISJSON(@cJson)=1
   SET @correlacion=TRY_CONVERT(UNIQUEIDENTIFIER,COALESCE(JSON_VALUE(@cJson,'$.contexto.correlacionId'),JSON_VALUE(@cJson,'$.correlacionId')));
  IF @bRegistrar=1 AND XACT_STATE()<>-1
  BEGIN TRY
   -- No se almacenan documentos, correos, contraseñas, tokens ni el contenido de la solicitud.
   INSERT auditoria.ErrorBaseDatos(fecha_utc,numero_error,procedimiento,linea,codigo,correlacion_id)
   VALUES(SYSUTCDATETIME(),@numero,@origen,@linea,@cCodigo,@correlacion);
  END TRY
  BEGIN CATCH
   SET @bResultado=0;
  END CATCH;
 END TRY
 BEGIN CATCH
  SELECT @cMensaje=N'No se pudo completar la acción. Intente nuevamente.',@cCodigo='ERROR_INTERNO',@nHttpSugerido=500;
 END CATCH;
 IF @bMensajePublicoGenerico=1
  SELECT @cMensaje=N'No se pudo completar la solicitud. Verifique los datos.',@cCodigo='SOLICITUD_NO_COMPLETADA';
 SELECT @cCodigoRespuesta=@cCodigo,@nHttpRespuesta=@nHttpSugerido;
 RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- config.PA_Respuesta_Sel_Catalogo
CREATE OR ALTER PROCEDURE [config].[PA_Respuesta_Sel_Catalogo]
    @cCodigo VARCHAR(60) = NULL,@bResultado BIT=NULL OUTPUT,@cMensaje NVARCHAR(300)=NULL OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

 SET NOCOUNT ON;
 SELECT @bResultado=0,@cMensaje=N'No se pudo consultar la información.';
 BEGIN TRY
  
  SELECT clave,codigo,numero_sql,mensaje,http_sugerido,reintentable
 FROM config.RespuestaBaseDatos WHERE estado=1 AND (@cCodigo IS NULL OR codigo=@cCodigo) ORDER BY codigo,clave;
  SELECT @bResultado=1,@cMensaje=N'Consulta realizada.';
 END TRY
 BEGIN CATCH
  SET @bResultado=0;
  EXEC config.PA_Respuesta_ResolverError @cProcedimiento=N'config.PA_Respuesta_Sel_Catalogo',@cMensaje=@cMensaje OUTPUT,@cJson=NULL;
 END CATCH;
Salida:
 SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'config.PA_Respuesta_Sel_Catalogo',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- dbo.PA_Dashboard_Sel_Resumen
CREATE OR ALTER PROCEDURE [dbo].[PA_Dashboard_Sel_Resumen]
(
    @cJson NVARCHAR(MAX),
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @nUsuario BIGINT,
        @nSesion BIGINT,
        @nDisp BIGINT,
        @nEmp BIGINT,
        @nModulo INT,
        @gCorr UNIQUEIDENTIFIER,
        @gSol UNIQUEIDENTIFIER,
        @cIp VARCHAR(64),
        @cEnd NVARCHAR(250),
        @bCtx BIT,
        @cMsg NVARCHAR(300),
        @dDesde DATE,
        @dHasta DATE,
        @dtDesde DATETIME2(0),
        @dtHastaExclusivo DATETIME2(0);

    SELECT
        @bResultado=0,
        @cMensaje=N'No se pudo cargar el inicio.';

    EXEC [seg].[PA_Operacion_Sel_ContextoAutorizado]
        @cJson=@cJson,
        @cCodigoPermiso='INICIO_LISTAR',
        @nUsuarioId=@nUsuario OUTPUT,
        @nSesionUsuarioId=@nSesion OUTPUT,
        @nDispositivoUsuarioId=@nDisp OUTPUT,
        @nEmpleadoId=@nEmp OUTPUT,
        @nModuloId=@nModulo OUTPUT,
        @gCorrelacionId=@gCorr OUTPUT,
        @gSolicitudId=@gSol OUTPUT,
        @cIp=@cIp OUTPUT,
        @cEndpoint=@cEnd OUTPUT,
        @bResultado=@bCtx OUTPUT,
        @cMensaje=@cMsg OUTPUT;

    IF @bCtx=0
    BEGIN
        SET @cMensaje=@cMsg;
        GOTO __DESCO_Salida;
    END;

    SET @dHasta=TRY_CONVERT(DATE,JSON_VALUE(@cJson,'$.datos.hasta'));
    SET @dDesde=TRY_CONVERT(DATE,JSON_VALUE(@cJson,'$.datos.desde'));

    IF @dHasta IS NULL
        SET @dHasta=CONVERT(DATE,SYSUTCDATETIME());

    IF @dDesde IS NULL
        SET @dDesde=DATEADD(DAY,-89,@dHasta);

    IF @dDesde>@dHasta
    BEGIN
        SET @cMensaje=N'La fecha desde no puede ser posterior a la fecha hasta.';
        GOTO __DESCO_Salida;
    END;

    IF DATEDIFF(DAY,@dDesde,@dHasta)>365
    BEGIN
        SET @cMensaje=N'El dashboard admite como máximo 366 días por consulta.';
        GOTO __DESCO_Salida;
    END;

    IF @dHasta>CONVERT(DATE,SYSUTCDATETIME())
    BEGIN
        SET @cMensaje=N'La fecha hasta no puede ser posterior a la fecha actual.';
        GOTO __DESCO_Salida;
    END;

    SET @dtDesde=CONVERT(DATETIME2(0),@dDesde);
    SET @dtHastaExclusivo=DATEADD(DAY,1,CONVERT(DATETIME2(0),@dHasta));

    /* ------------------------------------------------------------------------
       5.1. Permisos efectivos de la sesión
       ------------------------------------------------------------------------ */
    CREATE TABLE #Permisos
    (
        permiso_id BIGINT NOT NULL PRIMARY KEY,
        codigo VARCHAR(80) NOT NULL,
        modulo_id INT NOT NULL
    );

    INSERT INTO #Permisos(permiso_id,codigo,modulo_id)
    SELECT DISTINCT
        P.permiso_id,
        P.codigo,
        P.modulo_id
    FROM [seg].[UsuarioRol] UR
    INNER JOIN [seg].[Rol] R
        ON R.rol_id=UR.rol_id
       AND R.estado=1
    INNER JOIN [seg].[RolPermiso] RP
        ON RP.rol_id=R.rol_id
       AND RP.estado=1
    INNER JOIN [seg].[Permiso] P
        ON P.permiso_id=RP.permiso_id
       AND P.estado=1
    WHERE UR.usuario_id=@nUsuario
      AND UR.estado=1
      AND UR.fecha_desde<=SYSUTCDATETIME()
      AND (UR.fecha_hasta IS NULL OR UR.fecha_hasta>=SYSUTCDATETIME());

    /* ------------------------------------------------------------------------
       5.2. Elementos visibles

       La excepción de usuario prevalece sobre las asignaciones de rol.
       El JOIN contra #Permisos evita usar el dashboard como bypass de RBAC.
       ------------------------------------------------------------------------ */
    CREATE TABLE #ElementosVisibles
    (
        dashboard_elemento_id BIGINT NOT NULL PRIMARY KEY,
        codigo VARCHAR(80) NOT NULL,
        tipo VARCHAR(12) NOT NULL,
        titulo NVARCHAR(180) NOT NULL,
        subtitulo NVARCHAR(300) NULL,
        permiso_id BIGINT NOT NULL,
        permiso_codigo VARCHAR(80) NOT NULL,
        modulo_id INT NOT NULL,
        unidad NVARCHAR(30) NULL,
        icono VARCHAR(80) NULL,
        tipo_grafico VARCHAR(20) NULL,
        permite_fechas BIT NOT NULL,
        ancho TINYINT NOT NULL,
        orden SMALLINT NOT NULL
    );

    INSERT INTO #ElementosVisibles
    (
        dashboard_elemento_id,codigo,tipo,titulo,subtitulo,permiso_id,
        permiso_codigo,modulo_id,unidad,icono,tipo_grafico,permite_fechas,
        ancho,orden
    )
    SELECT
        E.dashboard_elemento_id,
        E.codigo,
        E.tipo,
        E.titulo,
        E.subtitulo,
        E.permiso_id,
        P.codigo,
        P.modulo_id,
        E.unidad,
        E.icono,
        E.tipo_grafico,
        E.permite_fechas,
        E.ancho,
        CONVERT(SMALLINT,COALESCE(U.orden,RX.orden_rol,E.orden))
    FROM [config].[DashboardElemento] E
    INNER JOIN #Permisos P
        ON P.permiso_id=E.permiso_id
    OUTER APPLY
    (
        SELECT TOP(1)
            UE.usuario_id,
            UE.visible,
            UE.orden
        FROM [config].[DashboardUsuarioElemento] UE
        WHERE UE.usuario_id=@nUsuario
          AND UE.dashboard_elemento_id=E.dashboard_elemento_id
    ) U
    OUTER APPLY
    (
        SELECT
            CONVERT(BIT,1) tiene_rol_visible,
            MIN(RE.orden) orden_rol
        FROM [config].[DashboardRolElemento] RE
        INNER JOIN [seg].[UsuarioRol] UR
            ON UR.rol_id=RE.rol_id
           AND UR.usuario_id=@nUsuario
           AND UR.estado=1
           AND UR.fecha_desde<=SYSUTCDATETIME()
           AND (UR.fecha_hasta IS NULL OR UR.fecha_hasta>=SYSUTCDATETIME())
        INNER JOIN [seg].[Rol] R
            ON R.rol_id=UR.rol_id
           AND R.estado=1
        WHERE RE.dashboard_elemento_id=E.dashboard_elemento_id
          AND RE.visible=1
        HAVING COUNT_BIG(*)>0
    ) RX
    WHERE E.estado=1
      AND
      (
          (U.usuario_id IS NOT NULL AND U.visible=1)
          OR
          (U.usuario_id IS NULL AND RX.tiene_rol_visible=1)
      );

    /* ------------------------------------------------------------------------
       5.3. KPI: solo se calcula lo que realmente será mostrado
       ------------------------------------------------------------------------ */
    CREATE TABLE #KpiValor
    (
        codigo VARCHAR(80) NOT NULL PRIMARY KEY,
        valor DECIMAL(19,2) NOT NULL
    );

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_PRODUCTORES_ACTIVOS')
        INSERT INTO #KpiValor SELECT 'KPI_PRODUCTORES_ACTIVOS',CONVERT(DECIMAL(19,2),COUNT_BIG(*)) FROM [org].[Socio] WHERE estado=1;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_PREDIOS_ACTIVOS')
        INSERT INTO #KpiValor SELECT 'KPI_PREDIOS_ACTIVOS',CONVERT(DECIMAL(19,2),COUNT_BIG(*)) FROM [prod].[Predio] WHERE estado=1;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_CULTIVOS_ACTIVOS')
        INSERT INTO #KpiValor SELECT 'KPI_CULTIVOS_ACTIVOS',CONVERT(DECIMAL(19,2),COUNT_BIG(*)) FROM [prod].[ParcelaCultivo] WHERE estado=1 AND situacion_cultivo='ACTIVO';

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_CENSOS_PERIODO')
        INSERT INTO #KpiValor
        SELECT 'KPI_CENSOS_PERIODO',CONVERT(DECIMAL(19,2),COUNT_BIG(*))
        FROM [prod].[CensoPlantas]
        WHERE estado=1
          AND fecha_censo>=@dDesde
          AND fecha_censo<=@dHasta;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_SALIDAS_PROGRAMADAS')
        INSERT INTO #KpiValor SELECT 'KPI_SALIDAS_PROGRAMADAS',CONVERT(DECIMAL(19,2),COUNT_BIG(*)) FROM [campo].[SalidaCampo] WHERE estado=1 AND estado_proceso='PROGRAMADA';

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_VISITAS_CURSO')
        INSERT INTO #KpiValor SELECT 'KPI_VISITAS_CURSO',CONVERT(DECIMAL(19,2),COUNT_BIG(*)) FROM [campo].[VisitaTecnica] WHERE estado=1 AND estado_proceso='INICIADA';

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_SANIDAD_ABIERTA')
        INSERT INTO #KpiValor SELECT 'KPI_SANIDAD_ABIERTA',CONVERT(DECIMAL(19,2),COUNT_BIG(*)) FROM [sanidad].[CasoFitosanitario] WHERE estado=1 AND estado_caso<>'CERRADO';

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_PRODUCCION_CONFIRMADA')
        INSERT INTO #KpiValor
        SELECT 'KPI_PRODUCCION_CONFIRMADA',CONVERT(DECIMAL(19,2),COALESCE(SUM(cantidad_estimada_kg),0))
        FROM [prod].[DisponibilidadProduccion]
        WHERE estado=1
          AND estado_estimacion='CONFIRMADA'
          AND fecha_estimacion>=@dtDesde
          AND fecha_estimacion<@dtHastaExclusivo;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_CAMPANIAS_ACTIVAS')
        INSERT INTO #KpiValor SELECT 'KPI_CAMPANIAS_ACTIVAS',CONVERT(DECIMAL(19,2),COUNT_BIG(*)) FROM [comercial].[CampaniaVenta] WHERE estado=1 AND estado_proceso='ACTIVA';

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_OPERATIVOS_RECEPCION')
        INSERT INTO #KpiValor SELECT 'KPI_OPERATIVOS_RECEPCION',CONVERT(DECIMAL(19,2),COUNT_BIG(*)) FROM [comercial].[OperativoVenta] WHERE estado=1 AND estado_proceso='EN_RECEPCION';

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_PRODUCTORES_PROGRAMADOS')
        INSERT INTO #KpiValor
        SELECT 'KPI_PRODUCTORES_PROGRAMADOS',CONVERT(DECIMAL(19,2),COUNT_BIG(*))
        FROM [comercial].[OperativoSocio] OS
        INNER JOIN [comercial].[OperativoVenta] O
            ON O.operativo_venta_id=OS.operativo_venta_id
           AND O.estado=1
           AND O.estado_proceso IN('PLANIFICADO','EN_RECEPCION')
        WHERE OS.estado=1
          AND OS.estado_participacion='PROGRAMADO';

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_JABAS_RECIBIDAS')
        INSERT INTO #KpiValor
        SELECT 'KPI_JABAS_RECIBIDAS',CONVERT(DECIMAL(19,2),COALESCE(SUM(CASE WHEN JM.tipo_movimiento IN('RECEPCION','AJUSTE_ENTRADA') THEN JM.cantidad WHEN JM.tipo_movimiento='AJUSTE_SALIDA' THEN -JM.cantidad ELSE 0 END),0))
        FROM [comercial].[JabaMovimiento] JM
        INNER JOIN [comercial].[OperativoVenta] O
            ON O.operativo_venta_id=JM.operativo_venta_id
           AND O.estado=1
           AND O.estado_proceso='EN_RECEPCION'
        WHERE JM.estado=1;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_JABAS_ASIGNADAS')
        INSERT INTO #KpiValor
        SELECT 'KPI_JABAS_ASIGNADAS',CONVERT(DECIMAL(19,2),COALESCE(SUM(CASE WHEN JM.tipo_movimiento='ASIGNACION' THEN JM.cantidad ELSE 0 END),0))
        FROM [comercial].[JabaMovimiento] JM
        INNER JOIN [comercial].[OperativoVenta] O
            ON O.operativo_venta_id=JM.operativo_venta_id
           AND O.estado=1
           AND O.estado_proceso='EN_RECEPCION'
        WHERE JM.estado=1;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_JABAS_PENDIENTES')
        INSERT INTO #KpiValor
        SELECT 'KPI_JABAS_PENDIENTES',CONVERT(DECIMAL(19,2),COALESCE(SUM(CASE WHEN JM.tipo_movimiento='ASIGNACION' THEN JM.cantidad WHEN JM.tipo_movimiento IN('DEVOLUCION_LLENA','DEVOLUCION_VACIA') THEN -JM.cantidad ELSE 0 END),0))
        FROM [comercial].[JabaMovimiento] JM
        INNER JOIN [comercial].[OperativoVenta] O
            ON O.operativo_venta_id=JM.operativo_venta_id
           AND O.estado=1
           AND O.estado_proceso='EN_RECEPCION'
        WHERE JM.estado=1;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_KILOS_RECIBIDOS')
        INSERT INTO #KpiValor
        SELECT 'KPI_KILOS_RECIBIDOS',CONVERT(DECIMAL(19,2),COALESCE(SUM(E.peso_aceptado_kg),0))
        FROM [comercial].[EntregaSocio] E
        WHERE E.estado=1
          AND E.estado_proceso='CONFIRMADA'
          AND E.fecha_hora>=@dtDesde
          AND E.fecha_hora<@dtHastaExclusivo;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_ENTREGAS_CONFIRMAR')
        INSERT INTO #KpiValor SELECT 'KPI_ENTREGAS_CONFIRMAR',CONVERT(DECIMAL(19,2),COUNT_BIG(*)) FROM [comercial].[EntregaSocio] WHERE estado=1 AND estado_proceso='REGISTRADA';

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_INCIDENCIAS_ABIERTAS')
        INSERT INTO #KpiValor SELECT 'KPI_INCIDENCIAS_ABIERTAS',CONVERT(DECIMAL(19,2),COUNT_BIG(*)) FROM [comercial].[IncidenciaOperativa] WHERE estado=1 AND estado_incidencia IN('ABIERTA','EN_REVISION');

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_BIENES_DISPONIBLES')
        INSERT INTO #KpiValor SELECT 'KPI_BIENES_DISPONIBLES',CONVERT(DECIMAL(19,2),COUNT_BIG(*)) FROM [logistica].[BienInventario] WHERE estado=1 AND estado_bien='DISPONIBLE';

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_BIENES_ASIGNADOS')
        INSERT INTO #KpiValor SELECT 'KPI_BIENES_ASIGNADOS',CONVERT(DECIMAL(19,2),COUNT_BIG(*)) FROM [logistica].[BienInventario] WHERE estado=1 AND estado_bien='ASIGNADO';

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_RECURSOS_PROGRAMADOS')
        INSERT INTO #KpiValor SELECT 'KPI_RECURSOS_PROGRAMADOS',CONVERT(DECIMAL(19,2),COUNT_BIG(*)) FROM [logistica].[RecursoProgramado] WHERE estado=1 AND estado_proceso='PROGRAMADO';

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_RECURSOS_PENDIENTES')
        INSERT INTO #KpiValor SELECT 'KPI_RECURSOS_PENDIENTES',CONVERT(DECIMAL(19,2),COUNT_BIG(*)) FROM [logistica].[RecursoProgramado] WHERE estado=1 AND estado_proceso='EN_EJECUCION';

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_GASTOS_APROBAR')
        INSERT INTO #KpiValor SELECT 'KPI_GASTOS_APROBAR',CONVERT(DECIMAL(19,2),COUNT_BIG(*)) FROM [finanzas].[GastoCampania] WHERE estado=1 AND estado_proceso='REGISTRADO';

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_LIQUIDACIONES_CALCULAR')
        INSERT INTO #KpiValor
        SELECT 'KPI_LIQUIDACIONES_CALCULAR',CONVERT(DECIMAL(19,2),COUNT_BIG(*))
        FROM [comercial].[ParticipacionCampaniaSocio] PCS
        WHERE PCS.estado=1
          AND PCS.estado_participacion='ACTIVO'
          AND EXISTS
          (
              SELECT 1
              FROM [comercial].[OperativoSocio] OS
              INNER JOIN [comercial].[EntregaSocio] E
                  ON E.operativo_socio_id=OS.operativo_socio_id
                 AND E.estado=1
                 AND E.estado_proceso='CONFIRMADA'
              WHERE OS.participacion_campania_socio_id=PCS.participacion_campania_socio_id
                AND OS.estado=1
          )
          AND NOT EXISTS
          (
              SELECT 1
              FROM [finanzas].[LiquidacionSocio] L
              WHERE L.participacion_campania_socio_id=PCS.participacion_campania_socio_id
                AND L.estado=1
                AND L.estado_proceso IN('CALCULADA','APROBADA','PAGADA_PARCIAL','PAGADA')
          );

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_LIQUIDACIONES_APROBAR')
        INSERT INTO #KpiValor SELECT 'KPI_LIQUIDACIONES_APROBAR',CONVERT(DECIMAL(19,2),COUNT_BIG(*)) FROM [finanzas].[LiquidacionSocio] WHERE estado=1 AND estado_proceso='CALCULADA';

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_PAGOS_CONFIRMAR')
        INSERT INTO #KpiValor SELECT 'KPI_PAGOS_CONFIRMAR',CONVERT(DECIMAL(19,2),COUNT_BIG(*)) FROM [finanzas].[PagoSocio] WHERE estado=1 AND estado_proceso='REGISTRADO';

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_COBROS_CONFIRMAR')
        INSERT INTO #KpiValor SELECT 'KPI_COBROS_CONFIRMAR',CONVERT(DECIMAL(19,2),COUNT_BIG(*)) FROM [finanzas].[CobroComprador] WHERE estado=1 AND estado_proceso='REGISTRADO';

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='KPI_SALDO_SOCIOS')
        INSERT INTO #KpiValor
        SELECT
            'KPI_SALDO_SOCIOS',
            CONVERT(DECIMAL(19,2),COALESCE(SUM(
                CASE
                    WHEN L.importe_neto-COALESCE(P.total_pagado,0)>0
                        THEN L.importe_neto-COALESCE(P.total_pagado,0)
                    ELSE 0
                END
            ),0))
        FROM [finanzas].[LiquidacionSocio] L
        OUTER APPLY
        (
            SELECT SUM(PG.importe) total_pagado
            FROM [finanzas].[PagoSocio] PG
            WHERE PG.liquidacion_socio_id=L.liquidacion_socio_id
              AND PG.estado=1
              AND PG.estado_proceso='CONFIRMADO'
        ) P
        WHERE L.estado=1
          AND L.moneda='PEN'
          AND L.estado_proceso IN('APROBADA','PAGADA_PARCIAL');

    /* RESULT SET 1 */
    SELECT
        E.codigo,
        E.titulo indicador,
        V.valor,
        E.unidad,
        E.icono,
        E.orden
    FROM #ElementosVisibles E
    INNER JOIN #KpiValor V
        ON V.codigo=E.codigo
    WHERE E.tipo='KPI'
    ORDER BY E.orden,E.titulo;

    /* ------------------------------------------------------------------------
       5.4. Alertas: solo de dominios representados en el dashboard visible
       ------------------------------------------------------------------------ */
    CREATE TABLE #Alertas
    (
        tipo VARCHAR(30) NOT NULL,
        mensaje NVARCHAR(300) NOT NULL,
        cantidad BIGINT NOT NULL,
        orden SMALLINT NOT NULL
    );

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE permiso_codigo='SALIDAS_LISTAR')
    BEGIN
        INSERT INTO #Alertas
        SELECT 'SALIDAS',N'Hay salidas programadas cuya hora prevista ya llegó.',COUNT_BIG(*),10
        FROM [campo].[SalidaCampo]
        WHERE estado=1
          AND estado_proceso='PROGRAMADA'
          AND fecha_hora_programada<=SYSUTCDATETIME()
        HAVING COUNT_BIG(*)>0;
    END;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE permiso_codigo='VISITAS_LISTAR')
    BEGIN
        INSERT INTO #Alertas
        SELECT 'VISITAS',N'Hay visitas técnicas en curso pendientes de finalización.',COUNT_BIG(*),20
        FROM [campo].[VisitaTecnica]
        WHERE estado=1
          AND estado_proceso='INICIADA'
        HAVING COUNT_BIG(*)>0;
    END;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE permiso_codigo='SANIDAD_LISTAR')
    BEGIN
        INSERT INTO #Alertas
        SELECT 'SANIDAD',N'Existen casos sanitarios que requieren seguimiento.',COUNT_BIG(*),30
        FROM [sanidad].[CasoFitosanitario]
        WHERE estado=1
          AND estado_caso IN('DETECTADO','EN_TRATAMIENTO','EN_SEGUIMIENTO')
        HAVING COUNT_BIG(*)>0;
    END;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE permiso_codigo='PRODUCCION_LISTAR')
    BEGIN
        INSERT INTO #Alertas
        SELECT 'PRODUCCION',N'Hay estimaciones de producción pendientes de confirmación.',COUNT_BIG(*),40
        FROM [prod].[DisponibilidadProduccion]
        WHERE estado=1
          AND estado_estimacion='ESTIMADA'
        HAVING COUNT_BIG(*)>0;
    END;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE permiso_codigo='JABAS_LISTAR')
    BEGIN
        INSERT INTO #Alertas
        SELECT
            'JABAS',
            N'Hay jabas pendientes de retorno en operativos en recepción.',
            CONVERT(BIGINT,SUM(CASE WHEN JM.tipo_movimiento='ASIGNACION' THEN JM.cantidad WHEN JM.tipo_movimiento IN('DEVOLUCION_LLENA','DEVOLUCION_VACIA') THEN -JM.cantidad ELSE 0 END)),
            45
        FROM [comercial].[JabaMovimiento] JM
        INNER JOIN [comercial].[OperativoVenta] O
            ON O.operativo_venta_id=JM.operativo_venta_id
           AND O.estado=1
           AND O.estado_proceso='EN_RECEPCION'
        WHERE JM.estado=1
        HAVING SUM(CASE WHEN JM.tipo_movimiento='ASIGNACION' THEN JM.cantidad WHEN JM.tipo_movimiento IN('DEVOLUCION_LLENA','DEVOLUCION_VACIA') THEN -JM.cantidad ELSE 0 END)>0;
    END;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE permiso_codigo='ENTREGAS_LISTAR')
    BEGIN
        INSERT INTO #Alertas
        SELECT 'ENTREGAS',N'Hay entregas pendientes de confirmación.',COUNT_BIG(*),50
        FROM [comercial].[EntregaSocio]
        WHERE estado=1
          AND estado_proceso='REGISTRADA'
        HAVING COUNT_BIG(*)>0;
    END;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE permiso_codigo='INCIDENCIAS_LISTAR')
    BEGIN
        INSERT INTO #Alertas
        SELECT 'INCIDENCIAS',N'Hay incidencias operativas pendientes de resolver.',COUNT_BIG(*),60
        FROM [comercial].[IncidenciaOperativa]
        WHERE estado=1
          AND estado_incidencia IN('ABIERTA','EN_REVISION')
        HAVING COUNT_BIG(*)>0;
    END;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE permiso_codigo='RECURSOS_LISTAR')
    BEGIN
        INSERT INTO #Alertas
        SELECT 'LOGISTICA',N'Hay recursos programados pendientes de asignación.',COUNT_BIG(*),65
        FROM [logistica].[RecursoProgramado]
        WHERE estado=1
          AND estado_proceso='PROGRAMADO'
        HAVING COUNT_BIG(*)>0;

        INSERT INTO #Alertas
        SELECT 'LOGISTICA',N'Hay recursos entregados pendientes de devolución o cierre.',COUNT_BIG(*),66
        FROM [logistica].[RecursoProgramado]
        WHERE estado=1
          AND estado_proceso='EN_EJECUCION'
        HAVING COUNT_BIG(*)>0;
    END;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE permiso_codigo='GASTOS_LISTAR')
    BEGIN
        INSERT INTO #Alertas
        SELECT 'FINANZAS',N'Hay gastos pendientes de aprobación.',COUNT_BIG(*),70
        FROM [finanzas].[GastoCampania]
        WHERE estado=1
          AND estado_proceso='REGISTRADO'
        HAVING COUNT_BIG(*)>0;
    END;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE permiso_codigo='LIQUIDACIONES_LISTAR')
    BEGIN
        INSERT INTO #Alertas
        SELECT 'FINANZAS',N'Hay liquidaciones pendientes de aprobación.',COUNT_BIG(*),71
        FROM [finanzas].[LiquidacionSocio]
        WHERE estado=1
          AND estado_proceso='CALCULADA'
        HAVING COUNT_BIG(*)>0;
    END;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE permiso_codigo='PAGOS_LISTAR')
    BEGIN
        INSERT INTO #Alertas
        SELECT 'FINANZAS',N'Hay pagos pendientes de confirmación.',COUNT_BIG(*),72
        FROM [finanzas].[PagoSocio]
        WHERE estado=1
          AND estado_proceso='REGISTRADO'
        HAVING COUNT_BIG(*)>0;
    END;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE permiso_codigo='COBROS_LISTAR')
    BEGIN
        INSERT INTO #Alertas
        SELECT 'FINANZAS',N'Hay cobros pendientes de confirmación.',COUNT_BIG(*),73
        FROM [finanzas].[CobroComprador]
        WHERE estado=1
          AND estado_proceso='REGISTRADO'
        HAVING COUNT_BIG(*)>0;
    END;

    /* RESULT SET 2 */
    SELECT tipo,mensaje,cantidad,orden
    FROM #Alertas
    ORDER BY orden,tipo;

    /* ------------------------------------------------------------------------
       5.5. Accesos rápidos: módulos relacionados con los elementos visibles.
       Máximo ocho para evitar saturar el Inicio del administrador.
       ------------------------------------------------------------------------ */
    ;
WITH ModulosRelacionados AS
    (
        SELECT
            M.modulo_id,
            M.codigo,
            M.nombre,
            M.ruta,
            M.icono,
            MIN(CONVERT(INT,E.orden)) orden_dashboard,
            MIN(CONVERT(INT,M.orden)) orden_modulo
        FROM #ElementosVisibles E
        INNER JOIN [seg].[Modulo] M
            ON M.modulo_id=E.modulo_id
           AND M.estado=1
           AND M.visible_menu=1
           AND M.es_grupo=0
           AND M.ruta IS NOT NULL
        GROUP BY M.modulo_id,M.codigo,M.nombre,M.ruta,M.icono
    )
    SELECT TOP(8)
        modulo_id moduloId,
        codigo codigoModulo,
        nombre nombreModulo,
        ruta,
        icono,
        CONVERT(INT,ROW_NUMBER() OVER(ORDER BY orden_dashboard,orden_modulo,nombre)) orden
    FROM ModulosRelacionados
    ORDER BY orden_dashboard,orden_modulo,nombre;

    /* ------------------------------------------------------------------------
       5.6. Definición de gráficos
       ------------------------------------------------------------------------ */
    /* RESULT SET 4 */
    SELECT
        codigo,
        titulo,
        subtitulo,
        tipo_grafico tipoGrafico,
        unidad,
        CONVERT(INT,ancho) ancho,
        CONVERT(INT,orden) orden
    FROM #ElementosVisibles
    WHERE tipo='GRAFICO'
    ORDER BY orden,titulo;

    /* ------------------------------------------------------------------------
       5.7. Datos de gráficos
       ------------------------------------------------------------------------ */
    CREATE TABLE #GraficoPunto
    (
        codigo_grafico VARCHAR(80) NOT NULL,
        serie NVARCHAR(100) NOT NULL,
        categoria NVARCHAR(100) NOT NULL,
        valor DECIMAL(19,4) NOT NULL,
        orden INT NOT NULL
    );

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='GRAF_PRODUCCION_MENSUAL')
    BEGIN
        INSERT INTO #GraficoPunto
        SELECT
            'GRAF_PRODUCCION_MENSUAL',
            N'Producción confirmada',
            CONCAT(YEAR(fecha_estimacion),'-',RIGHT('0'+CONVERT(VARCHAR(2),MONTH(fecha_estimacion)),2)),
            CONVERT(DECIMAL(19,4),SUM(cantidad_estimada_kg)),
            YEAR(fecha_estimacion)*100+MONTH(fecha_estimacion)
        FROM [prod].[DisponibilidadProduccion]
        WHERE estado=1
          AND estado_estimacion='CONFIRMADA'
          AND fecha_estimacion>=@dtDesde
          AND fecha_estimacion<@dtHastaExclusivo
        GROUP BY YEAR(fecha_estimacion),MONTH(fecha_estimacion);
    END;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='GRAF_VISITAS_ESTADO')
    BEGIN
        INSERT INTO #GraficoPunto
        SELECT
            'GRAF_VISITAS_ESTADO',
            N'Visitas',
            CASE estado_proceso
                WHEN 'INICIADA' THEN N'Iniciadas'
                WHEN 'FINALIZADA' THEN N'Finalizadas'
                WHEN 'ANULADA' THEN N'Anuladas'
                ELSE estado_proceso
            END,
            CONVERT(DECIMAL(19,4),COUNT_BIG(*)),
            CASE estado_proceso WHEN 'INICIADA' THEN 10 WHEN 'FINALIZADA' THEN 20 WHEN 'ANULADA' THEN 30 ELSE 90 END
        FROM [campo].[VisitaTecnica]
        WHERE estado=1
          AND fecha_hora_inicio>=@dtDesde
          AND fecha_hora_inicio<@dtHastaExclusivo
        GROUP BY estado_proceso;
    END;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='GRAF_CAMPANIAS_ESTADO')
    BEGIN
        INSERT INTO #GraficoPunto
        SELECT
            'GRAF_CAMPANIAS_ESTADO',
            N'Campañas',
            CASE estado_proceso
                WHEN 'PLANIFICACION' THEN N'Planificación'
                WHEN 'ACTIVA' THEN N'Activas'
                WHEN 'CERRADA' THEN N'Cerradas'
                WHEN 'CANCELADA' THEN N'Canceladas'
                ELSE estado_proceso
            END,
            CONVERT(DECIMAL(19,4),COUNT_BIG(*)),
            CASE estado_proceso WHEN 'PLANIFICACION' THEN 10 WHEN 'ACTIVA' THEN 20 WHEN 'CERRADA' THEN 30 WHEN 'CANCELADA' THEN 40 ELSE 90 END
        FROM [comercial].[CampaniaVenta]
        WHERE estado=1
          AND fecha_inicio<=@dHasta
          AND (fecha_fin IS NULL OR fecha_fin>=@dDesde)
        GROUP BY estado_proceso;
    END;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='GRAF_ACOPIO_MENSUAL')
    BEGIN
        INSERT INTO #GraficoPunto
        SELECT
            'GRAF_ACOPIO_MENSUAL',
            N'Peso aceptado',
            CONCAT(YEAR(fecha_hora),'-',RIGHT('0'+CONVERT(VARCHAR(2),MONTH(fecha_hora)),2)),
            CONVERT(DECIMAL(19,4),SUM(peso_aceptado_kg)),
            YEAR(fecha_hora)*100+MONTH(fecha_hora)
        FROM [comercial].[EntregaSocio]
        WHERE estado=1
          AND estado_proceso='CONFIRMADA'
          AND fecha_hora>=@dtDesde
          AND fecha_hora<@dtHastaExclusivo
        GROUP BY YEAR(fecha_hora),MONTH(fecha_hora);
    END;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='GRAF_INCIDENCIAS_ESTADO')
    BEGIN
        INSERT INTO #GraficoPunto
        SELECT
            'GRAF_INCIDENCIAS_ESTADO',
            N'Incidencias',
            CASE estado_incidencia
                WHEN 'ABIERTA' THEN N'Abiertas'
                WHEN 'EN_REVISION' THEN N'En revisión'
                WHEN 'RESUELTA' THEN N'Resueltas'
                WHEN 'ANULADA' THEN N'Anuladas'
                ELSE estado_incidencia
            END,
            CONVERT(DECIMAL(19,4),COUNT_BIG(*)),
            CASE estado_incidencia WHEN 'ABIERTA' THEN 10 WHEN 'EN_REVISION' THEN 20 WHEN 'RESUELTA' THEN 30 WHEN 'ANULADA' THEN 40 ELSE 90 END
        FROM [comercial].[IncidenciaOperativa]
        WHERE estado=1
          AND fecha_hora>=@dtDesde
          AND fecha_hora<@dtHastaExclusivo
        GROUP BY estado_incidencia;
    END;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='GRAF_RECURSOS_ESTADO')
    BEGIN
        INSERT INTO #GraficoPunto
        SELECT
            'GRAF_RECURSOS_ESTADO',
            N'Recursos',
            CASE estado_proceso
                WHEN 'PROGRAMADO' THEN N'Programados'
                WHEN 'EN_EJECUCION' THEN N'En ejecución'
                WHEN 'DEVUELTO' THEN N'Devueltos'
                WHEN 'CERRADO' THEN N'Cerrados'
                WHEN 'CANCELADO' THEN N'Cancelados'
                ELSE REPLACE(estado_proceso,'_',N' ')
            END,
            CONVERT(DECIMAL(19,4),COUNT_BIG(*)),
            CASE estado_proceso WHEN 'PROGRAMADO' THEN 10 WHEN 'EN_EJECUCION' THEN 20 WHEN 'DEVUELTO' THEN 30 WHEN 'CERRADO' THEN 40 WHEN 'CANCELADO' THEN 50 ELSE 90 END
        FROM [logistica].[RecursoProgramado]
        WHERE estado=1
          AND fecha_programacion>=@dtDesde
          AND fecha_programacion<@dtHastaExclusivo
        GROUP BY estado_proceso;
    END;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='GRAF_PAGOS_MENSUAL')
    BEGIN
        INSERT INTO #GraficoPunto
        SELECT
            'GRAF_PAGOS_MENSUAL',
            N'Pagos confirmados',
            CONCAT(YEAR(fecha_hora),'-',RIGHT('0'+CONVERT(VARCHAR(2),MONTH(fecha_hora)),2)),
            CONVERT(DECIMAL(19,4),SUM(importe)),
            YEAR(fecha_hora)*100+MONTH(fecha_hora)
        FROM [finanzas].[PagoSocio]
        WHERE estado=1
          AND estado_proceso='CONFIRMADO'
          AND fecha_hora>=@dtDesde
          AND fecha_hora<@dtHastaExclusivo
        GROUP BY YEAR(fecha_hora),MONTH(fecha_hora);
    END;

    IF EXISTS(SELECT 1 FROM #ElementosVisibles WHERE codigo='GRAF_COBROS_MENSUAL')
    BEGIN
        INSERT INTO #GraficoPunto
        SELECT
            'GRAF_COBROS_MENSUAL',
            N'Cobros confirmados',
            CONCAT(YEAR(fecha_hora),'-',RIGHT('0'+CONVERT(VARCHAR(2),MONTH(fecha_hora)),2)),
            CONVERT(DECIMAL(19,4),SUM(importe)),
            YEAR(fecha_hora)*100+MONTH(fecha_hora)
        FROM [finanzas].[CobroComprador]
        WHERE estado=1
          AND estado_proceso='CONFIRMADO'
          AND moneda='PEN'
          AND fecha_hora>=@dtDesde
          AND fecha_hora<@dtHastaExclusivo
        GROUP BY YEAR(fecha_hora),MONTH(fecha_hora);
    END;

    /* RESULT SET 5 */
    SELECT
        codigo_grafico codigoGrafico,
        serie,
        categoria,
        valor,
        orden
    FROM #GraficoPunto
    ORDER BY codigo_grafico,serie,orden,categoria;

    SET @bResultado=1;
    SET @cMensaje=N'Inicio cargado correctamente.';

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'dbo.PA_Dashboard_Sel_Resumen',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'dbo.PA_Dashboard_Sel_Resumen',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'dbo.PA_Dashboard_Sel_Resumen',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- finanzas.PA_Campania_Sel_SaldoCompradorInterno
CREATE OR ALTER PROCEDURE [finanzas].[PA_Campania_Sel_SaldoCompradorInterno]
(
    @nCampaniaVentaId BIGINT,
    @nOperativoVentaId BIGINT = NULL,
    @nTotalValorizado DECIMAL(19,4) OUTPUT,
    @nTotalCobrado DECIMAL(19,4) OUTPUT,
    @nSaldoPendiente DECIMAL(19,4) OUTPUT
,@cMoneda CHAR(3)=NULL,@bResultado BIT=NULL OUTPUT,@cMensaje NVARCHAR(300)=NULL OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

 SET NOCOUNT ON;
 SELECT @bResultado=0,@cMensaje=N'No se pudo consultar la información.';
 BEGIN TRY

  SELECT @nTotalValorizado=0,@nTotalCobrado=0,@nSaldoPendiente=0;
  IF @cMoneda IS NULL
  BEGIN
   DECLARE @monedas INT;
   SELECT @monedas=COUNT(DISTINCT P.moneda),@cMoneda=MIN(P.moneda)
   FROM comercial.EntregaSocio E JOIN comercial.OperativoSocio OS ON OS.operativo_socio_id=E.operativo_socio_id
   JOIN comercial.OperativoVenta O ON O.operativo_venta_id=OS.operativo_venta_id
   JOIN comercial.EntregaDetalle D ON D.entrega_socio_id=E.entrega_socio_id AND D.estado=1
   JOIN comercial.PrecioComercial P ON P.precio_comercial_id=D.precio_comercial_id
   WHERE O.campania_venta_id=@nCampaniaVentaId AND (@nOperativoVentaId IS NULL OR O.operativo_venta_id=@nOperativoVentaId)
   AND E.estado=1 AND E.estado_proceso='CONFIRMADA';
   IF @monedas>1 THROW 51000,N'Seleccione la moneda para consultar el saldo.',1;
  END;
  SELECT @nTotalValorizado=COALESCE(SUM(D.importe),0)
  FROM comercial.EntregaSocio E JOIN comercial.OperativoSocio OS ON OS.operativo_socio_id=E.operativo_socio_id
  JOIN comercial.OperativoVenta O ON O.operativo_venta_id=OS.operativo_venta_id
  JOIN comercial.EntregaDetalle D ON D.entrega_socio_id=E.entrega_socio_id AND D.estado=1
  JOIN comercial.PrecioComercial P ON P.precio_comercial_id=D.precio_comercial_id AND P.moneda=@cMoneda
  WHERE O.campania_venta_id=@nCampaniaVentaId AND (@nOperativoVentaId IS NULL OR O.operativo_venta_id=@nOperativoVentaId)
  AND E.estado=1 AND E.estado_proceso='CONFIRMADA';
  SELECT @nTotalCobrado=COALESCE(SUM(importe),0) FROM finanzas.CobroComprador
  WHERE campania_venta_id=@nCampaniaVentaId AND (@nOperativoVentaId IS NULL OR operativo_venta_id=@nOperativoVentaId)
  AND moneda=@cMoneda AND estado=1 AND estado_proceso='CONFIRMADO';
  SET @nSaldoPendiente=@nTotalValorizado-@nTotalCobrado;
  IF @nSaldoPendiente<0 THROW 51100,N'DESCO_KARDEX_REVISAR',1;

  SELECT @bResultado=1,@cMensaje=N'Saldo consultado.';
 END TRY
 BEGIN CATCH
  SET @bResultado=0;
  EXEC config.PA_Respuesta_ResolverError @cProcedimiento=N'finanzas.PA_Campania_Sel_SaldoCompradorInterno',@cMensaje=@cMensaje OUTPUT,@cJson=NULL;
 END CATCH;
Salida:
 SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'finanzas.PA_Campania_Sel_SaldoCompradorInterno',@bResultado,@cMensaje) R;
IF @bResultado=0 AND @@NESTLEVEL>1 THROW 51000,@cMensaje,1;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

