-- finanzas.PA_CobroComprador_Sel_SaldoCampania
CREATE OR ALTER PROCEDURE [finanzas].[PA_CobroComprador_Sel_SaldoCampania](@cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;

    BEGIN TRY
DECLARE @__MonedaSaldo CHAR(3)=COALESCE(JSON_VALUE(@cJson,'$.cobro.moneda'),JSON_VALUE(@cJson,'$.filtros.moneda'));
IF @__MonedaSaldo IS NULL
 SELECT @__MonedaSaldo=moneda FROM finanzas.CobroComprador WHERE cobro_comprador_id=TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.cobro.cobroCompradorId'));

  SET NOCOUNT ON;
DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@bCtx BIT,@cMsg NVARCHAR(300);
SELECT @bResultado=0,@cMensaje=N'No se pudo consultar el saldo de la campaña.';
EXEC seg.PA_Operacion_Sel_ContextoAutorizado @cJson=@cJson,@cCodigoPermiso='COBROS_VER',@nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@bResultado=@bCtx OUTPUT,@cMensaje=@cMsg OUTPUT;
IF @bCtx=0 BEGIN SET @cMensaje=@cMsg;
GOTO __DESCO_Salida;
END;
 DECLARE @nCamp BIGINT,@nOpVenta BIGINT,@nVal DECIMAL(19,4),@nCob DECIMAL(19,4),@nSaldo DECIMAL(19,4);
SELECT @nCamp=campaniaVentaId,@nOpVenta=operativoVentaId FROM OPENJSON(@cJson,'$.filtros') WITH(campaniaVentaId BIGINT '$.campaniaVentaId',operativoVentaId BIGINT '$.operativoVentaId');
IF NOT EXISTS(SELECT 1 FROM comercial.CampaniaVenta WHERE campania_venta_id=@nCamp AND estado=1) BEGIN SET @cMensaje=N'La campaña seleccionada no está disponible.';
GOTO __DESCO_Salida;
END;
EXEC finanzas.PA_Campania_Sel_SaldoCompradorInterno @nCampaniaVentaId=@nCamp,@nOperativoVentaId=@nOpVenta,@nTotalValorizado=@nVal OUTPUT,@nTotalCobrado=@nCob OUTPUT,@nSaldoPendiente=@nSaldo OUTPUT,@cMoneda=@__MonedaSaldo;
SELECT @nCamp campaniaVentaId,@nOpVenta operativoVentaId,@nVal totalValorizado,@nCob totalCobrado,@nSaldo saldoPendiente;
SET @bResultado=1;
SET @cMensaje=N'Saldo consultado correctamente.';
