GOTO __DESCO_Salida;
END;
 SELECT @nId=cobroCompradorId,@cMotivo=NULLIF(LTRIM(RTRIM(motivo)),N'') FROM OPENJSON(@cJson,'$.cobro') WITH(cobroCompradorId BIGINT '$.cobroCompradorId',motivo NVARCHAR(500) '$.motivo');
SELECT @cAnt=estado_proceso FROM finanzas.CobroComprador WHERE cobro_comprador_id=@nId AND estado=1;
IF @cAnt NOT IN('REGISTRADO','CONFIRMADO') OR @cMotivo IS NULL BEGIN SET @cMensaje=N'El cobro no está disponible para anulación o falta indicar el motivo.';
GOTO Fallar;
END;
BEGIN TRY BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;
