-- finanzas.PA_GastoCampania_Upd_Anular
CREATE OR ALTER PROCEDURE [finanzas].[PA_GastoCampania_Upd_Anular](@cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY
  SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),@nAud BIGINT,@nTrans BIGINT,@nId BIGINT,@cMotivo NVARCHAR(500),@cAnt VARCHAR(20),@cIdent NVARCHAR(200);
SELECT @bResultado=0,@cMensaje=N'No se pudo anular el gasto.';
EXEC seg.PA_Operacion_Ins_IniciarIdempotente @cJson=@cJson,@cCodigoPermiso='GASTOS_RETIRAR',@cAmbito='GASTO_ANULAR',@nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@nOperacionIdempotenteId=@nOp OUTPUT,@bEsRepetida=@bRep OUTPUT,@cEstadoOperacion=@cEstadoOp OUTPUT,@cIdentificadorResultado=@cIdRes OUTPUT,@cCodigoResultado=@cCodRes OUTPUT,@bResultado=@bIni OUTPUT,@cMensaje=@cMsg OUTPUT;
IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
GOTO __DESCO_Salida;
END;
IF @bRep=1 BEGIN SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
SET @cMensaje=CASE WHEN @cEstadoOp='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.' ELSE N'La solicitud ya se encuentra en proceso.' END;
GOTO __DESCO_Salida;
END;
 SELECT @nId=gastoCampaniaId,@cMotivo=NULLIF(LTRIM(RTRIM(motivo)),N'') FROM OPENJSON(@cJson,'$.gasto') WITH(gastoCampaniaId BIGINT '$.gastoCampaniaId',motivo NVARCHAR(500) '$.motivo');
SELECT @cAnt=estado_proceso FROM finanzas.GastoCampania WHERE gasto_campania_id=@nId AND estado=1;
IF @cAnt NOT IN('REGISTRADO','APROBADO') OR @cMotivo IS NULL BEGIN SET @cMensaje=N'El gasto no está disponible para anulación o falta indicar el motivo.';
GOTO Fallar;
END;
IF EXISTS(SELECT 1 FROM finanzas.LiquidacionDetalle LD INNER JOIN finanzas.LiquidacionSocio L ON L.liquidacion_socio_id=LD.liquidacion_socio_id WHERE LD.gasto_prorrateo_socio_id IN(SELECT gasto_prorrateo_socio_id FROM finanzas.GastoProrrateoSocio WHERE gasto_campania_id=@nId) AND LD.estado=1 AND L.estado=1 AND L.estado_proceso IN('APROBADA','PAGADA_PARCIAL','PAGADA')) BEGIN SET @cMensaje=N'El gasto ya forma parte de una liquidación aprobada y no puede anularse.';
