 SELECT @nId=gastoCampaniaId FROM OPENJSON(@cJson,'$.gasto') WITH(gastoCampaniaId BIGINT '$.gastoCampaniaId');
SELECT @nImporte=importe FROM finanzas.GastoCampania WHERE gasto_campania_id=@nId AND estado=1 AND estado_proceso='REGISTRADO';
SELECT @nProrr=COALESCE(SUM(importe_asignado),0) FROM finanzas.GastoProrrateoSocio WHERE gasto_campania_id=@nId AND estado=1;
IF @nImporte IS NULL BEGIN SET @cMensaje=N'El gasto seleccionado no está disponible para aprobación.';
GOTO Fallar;
END;
IF ABS(@nImporte-@nProrr)>0.01 BEGIN SET @cMensaje=N'Complete correctamente el prorrateo antes de aprobar el gasto.';
GOTO Fallar;
END;
