    BEGIN TRY
  SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),@nAud BIGINT,@nTrans BIGINT,@nLiq BIGINT,@nImporte DECIMAL(19,4),@cMedio VARCHAR(30),@cOperacion VARCHAR(100),@nNeto DECIMAL(19,4),@nPagado DECIMAL(19,4),@nSaldo DECIMAL(19,4),@cIdent NVARCHAR(200);
SELECT @bResultado=0,@cMensaje=N'No se pudo registrar el pago.';
EXEC seg.PA_Operacion_Ins_IniciarIdempotente @cJson=@cJson,@cCodigoPermiso='PAGOS_CREAR',@cAmbito='PAGO_REGISTRAR',@nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@nOperacionIdempotenteId=@nOp OUTPUT,@bEsRepetida=@bRep OUTPUT,@cEstadoOperacion=@cEstadoOp OUTPUT,@cIdentificadorResultado=@cIdRes OUTPUT,@cCodigoResultado=@cCodRes OUTPUT,@bResultado=@bIni OUTPUT,@cMensaje=@cMsg OUTPUT;
IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
GOTO __DESCO_Salida;
END;
IF @bRep=1 BEGIN SET @nPagoSocioId=CASE WHEN @cEstadoOp='COMPLETADA' THEN TRY_CONVERT(BIGINT,@cIdRes) ELSE NULL END;
 SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
SET @cMensaje=CASE WHEN @cEstadoOp='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.' ELSE N'La solicitud ya se encuentra en proceso.' END;
GOTO __DESCO_Salida;
END;
 SET @nPagoSocioId=NULL;
SELECT @nLiq=liquidacionSocioId,@nImporte=importe,@cMedio=UPPER(NULLIF(LTRIM(RTRIM(medioPago)),'')),@cOperacion=NULLIF(LTRIM(RTRIM(numeroOperacion)),'') FROM OPENJSON(@cJson,'$.pago') WITH(liquidacionSocioId BIGINT '$.liquidacionSocioId',importe DECIMAL(19,4) '$.importe',medioPago VARCHAR(30) '$.medioPago',numeroOperacion VARCHAR(100) '$.numeroOperacion');
IF NOT EXISTS(SELECT 1 FROM finanzas.LiquidacionSocio WHERE liquidacion_socio_id=@nLiq AND estado=1 AND estado_proceso IN('APROBADA','PAGADA_PARCIAL')) OR @nImporte<=0 OR @cMedio IS NULL BEGIN SET @cMensaje=N'La liquidación o los datos del pago no son válidos.';
GOTO Fallar;
END;
EXEC finanzas.PA_Liquidacion_Sel_SaldoPendienteInterno @nLiquidacionSocioId=@nLiq,@nImporteNeto=@nNeto OUTPUT,@nTotalPagado=@nPagado OUTPUT,@nSaldoPendiente=@nSaldo OUTPUT;
IF @nImporte>@nSaldo BEGIN SET @cMensaje=N'El importe del pago supera el saldo pendiente de la liquidación.';
GOTO Fallar;
END;
BEGIN TRY BEGIN
