    SET @__DbTranAbierta = 1;
END;
INSERT finanzas.PagoSocio(liquidacion_socio_id,fecha_hora,importe,medio_pago,numero_operacion,estado_proceso,estado) VALUES(@nLiq,SYSUTCDATETIME(),@nImporte,@cMedio,@cOperacion,'REGISTRADO',1);
SET @nPagoSocioId=SCOPE_IDENTITY();
