GO
SET QUOTED_IDENTIFIER ON;
GO

/* ----------------------------------------------------------------------------
   3. Resolver una ubicación de almacén a partir de datos que el usuario conoce.
   El frontend ya no necesita pedir el FK ubicacion_id.
   ---------------------------------------------------------------------------- */
CREATE OR ALTER PROCEDURE [geo].[PA_Ubicacion_Ins_ResolverRecurso]
    @nUsuarioId BIGINT,
    @nSesionUsuarioId BIGINT,
    @nUotId BIGINT,
    @cDistritoCodigo CHAR(6),
    @nCentroPobladoId BIGINT = NULL,
    @cReferencia NVARCHAR(300) = NULL,
    @nUbicacionId BIGINT OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60) = NULL OUTPUT,
    @nHttpRespuesta SMALLINT = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SELECT
        @nUbicacionId = NULL,
        @bResultado = 0,
        @cMensaje = N'No se pudo resolver la ubicación.',
        @cCodigoRespuesta = 'UBICACION_NO_RESUELTA',
        @nHttpRespuesta = 400;

    DECLARE
        @nUotResuelta BIGINT = @nUotId,
        @bModoGeneral BIT,
        @bOk BIT,
        @cMsg NVARCHAR(300);

    EXEC [seg].[PA_UOT_Sel_ResolverContextoSesion]
        @nUsuarioId = @nUsuarioId,
        @nSesionUsuarioId = @nSesionUsuarioId,
        @nUotSolicitada = @nUotResuelta,
        @cCodigoPermiso = 'ALMACENES_CREAR',
        @bRequiereUot = 1,
        @nUotId = @nUotResuelta OUTPUT,
        @bModoGeneral = @bModoGeneral OUTPUT,
        @bResultado = @bOk OUTPUT,
        @cMensaje = @cMsg OUTPUT;

    IF ISNULL(@bOk, 0) = 0
    BEGIN
        SET @cMensaje = COALESCE(NULLIF(@cMsg, N''), @cMensaje);
        RETURN 1;
    END;

    SET @cDistritoCodigo = NULLIF(LTRIM(RTRIM(@cDistritoCodigo)), '');
    SET @cReferencia = NULLIF(LTRIM(RTRIM(@cReferencia)), N'');

    IF @cDistritoCodigo IS NULL
       OR LEN(@cDistritoCodigo) <> 6
       OR @cDistritoCodigo LIKE '%[^0-9]%'
       OR NOT EXISTS
       (
           SELECT 1
           FROM [geo].[Distrito]
           WHERE distrito_codigo = @cDistritoCodigo
             AND estado = 1
       )
    BEGIN
        SET @cMensaje = N'Seleccione un distrito válido.';
        RETURN 1;
    END;

    IF @nCentroPobladoId IS NOT NULL
       AND NOT EXISTS
       (
           SELECT 1
           FROM [geo].[CentroPoblado]
           WHERE centro_poblado_id = @nCentroPobladoId
             AND distrito_codigo = @cDistritoCodigo
             AND estado = 1
       )
    BEGIN
        SET @cMensaje = N'El centro poblado no corresponde al distrito seleccionado.';
        RETURN 1;
    END;

    SELECT TOP (1)
        @nUbicacionId = U.ubicacion_id
    FROM [geo].[Ubicacion] U
    WHERE U.estado = 1
      AND U.distrito_codigo = @cDistritoCodigo
      AND ISNULL(U.centro_poblado_id, 0) = ISNULL(@nCentroPobladoId, 0)
      AND ISNULL(U.referencia, N'') = ISNULL(@cReferencia, N'')
      AND U.posicion IS NULL
      AND U.altitud_m IS NULL
    ORDER BY U.ubicacion_id;

    IF @nUbicacionId IS NULL
    BEGIN
        BEGIN TRY
            INSERT INTO [geo].[Ubicacion]
            (
                distrito_codigo,
                centro_poblado_id,
                referencia,
                estado
            )
            VALUES
            (
                @cDistritoCodigo,
                @nCentroPobladoId,
                @cReferencia,
                1
            );

            SET @nUbicacionId = CONVERT(BIGINT, SCOPE_IDENTITY());
        END TRY
        BEGIN CATCH
            SET @nUbicacionId = NULL;
            SET @cMensaje = N'No se pudo registrar la ubicación del almacén.';
            RETURN 1;
        END CATCH;
    END;

    SELECT
        @bResultado = 1,
        @cMensaje = N'Ubicación validada.',
        @cCodigoRespuesta = 'UBICACION_RESUELTA',
        @nHttpRespuesta = 200;

    RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- geo.PA_Ubicacion_Upd_Interna
CREATE OR ALTER PROCEDURE [geo].[PA_Ubicacion_Upd_Interna]
(
    @nUbicacionId            BIGINT,
    @cDistritoCodigo         CHAR(6),
    @nCentroPobladoId        BIGINT = NULL,
    @cReferencia             NVARCHAR(300) = NULL,
    @bResultado              BIT OUTPUT,
    @cMensaje                NVARCHAR(300) OUTPUT,

    /* Parámetros añadidos al final para mantener compatibilidad con
       las llamadas posicionales del parche Persona/Empresa V2. */
    @nLatitud                DECIMAL(9,6) = NULL,
    @nLongitud               DECIMAL(9,6) = NULL,
    @nAltitudM               DECIMAL(8,2) = NULL,
    @bActualizarGeoposicion  BIT = 0,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;

    DECLARE @gPosicion GEOGRAPHY = NULL;

    SET @bResultado=0;
    SET @cMensaje=N'No se pudo actualizar la ubicación.';
    SET @cDistritoCodigo=NULLIF(LTRIM(RTRIM(@cDistritoCodigo)),'');
    SET @cReferencia=NULLIF(LTRIM(RTRIM(@cReferencia)),N'');

    IF @nUbicacionId IS NULL
    BEGIN
        SET @cMensaje=N'La ubicación seleccionada no es válida.';
        GOTO __DESCO_Salida;
    END;

    IF @cDistritoCodigo IS NULL
    BEGIN
        SET @cMensaje=N'Seleccione un distrito.';
        GOTO __DESCO_Salida;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [geo].[Distrito] D
        WHERE D.distrito_codigo=@cDistritoCodigo
          AND D.estado=1
    )
    BEGIN
        SET @cMensaje=N'El distrito seleccionado no está disponible.';
        GOTO __DESCO_Salida;
    END;

    IF @nCentroPobladoId IS NOT NULL
       AND NOT EXISTS
       (
           SELECT 1
           FROM [geo].[CentroPoblado] CP
           WHERE CP.centro_poblado_id=@nCentroPobladoId
             AND CP.distrito_codigo=@cDistritoCodigo
             AND CP.estado=1
       )
    BEGIN
        SET @cMensaje=N'El centro poblado seleccionado no corresponde al distrito.';
        GOTO __DESCO_Salida;
    END;

    IF @bActualizarGeoposicion=1
    BEGIN
        IF (@nLatitud IS NULL AND @nLongitud IS NOT NULL)
           OR (@nLatitud IS NOT NULL AND @nLongitud IS NULL)
           OR (@nLatitud IS NOT NULL AND (@nLatitud < -90 OR @nLatitud > 90))
           OR (@nLongitud IS NOT NULL AND (@nLongitud < -180 OR @nLongitud > 180))
        BEGIN
            SET @cMensaje=N'La latitud y longitud seleccionadas no son válidas.';
            GOTO __DESCO_Salida;
        END;

        IF @nLatitud IS NOT NULL
        BEGIN
            SET @gPosicion=geography::Point(@nLatitud,@nLongitud,4326);
        END;
    END;

    IF @bActualizarGeoposicion=1
    BEGIN
        UPDATE [geo].[Ubicacion]
           SET distrito_codigo=@cDistritoCodigo,
               centro_poblado_id=@nCentroPobladoId,
               referencia=@cReferencia,
               posicion=@gPosicion,
               altitud_m=@nAltitudM,
               estado=1
         WHERE ubicacion_id=@nUbicacionId;
    END
    ELSE
    BEGIN
        UPDATE [geo].[Ubicacion]
           SET distrito_codigo=@cDistritoCodigo,
               centro_poblado_id=@nCentroPobladoId,
               referencia=@cReferencia,
               estado=1
         WHERE ubicacion_id=@nUbicacionId;
    END;

    IF @@ROWCOUNT=0
    BEGIN
        SET @cMensaje=N'La ubicación seleccionada no está disponible.';
        GOTO __DESCO_Salida;
    END;

    SET @bResultado=1;
    SET @cMensaje=N'Ubicación actualizada correctamente.';

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'geo.PA_Ubicacion_Upd_Interna',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'geo.PA_Ubicacion_Upd_Interna',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'geo.PA_Ubicacion_Upd_Interna',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- integracion.PA_Identidad_Ins_ReservarConsultaExterna
CREATE OR ALTER PROCEDURE [integracion].[PA_Identidad_Ins_ReservarConsultaExterna]
(
    @cJson NVARCHAR(MAX),
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,
            @gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),
            @bCtx BIT,@cMsg NVARCHAR(300);
    DECLARE @cEntidad VARCHAR(10),@cTipo VARCHAR(15),@cDoc VARCHAR(30),
            @cTipoExt VARCHAR(15),@cDocExt VARCHAR(30),@cClave VARCHAR(60),
            @nLocal BIGINT=NULL,@nCoin INT,@bBusca BIT,@cMsgBusca NVARCHAR(300),
            @nConsulta BIGINT=NULL,@cEstado VARCHAR(25)=NULL,@dBloqueo DATETIME2(0)=NULL,
            @dReintento DATETIME2(0)=NULL,@bPuede BIT=0;

    SELECT @bResultado=0,@cMensaje=N'No se pudo reservar la consulta externa.';

    EXEC [seg].[PA_Operacion_Sel_ContextoAutorizado]
         @cJson=@cJson,@cCodigoPermiso='VALIDACIONIDENTIDAD_CONSULTAR',
         @nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,
         @nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,
         @nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,
         @gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,
         @bResultado=@bCtx OUTPUT,@cMensaje=@cMsg OUTPUT;

    IF @bCtx=0 BEGIN SET @cMensaje=@cMsg;
 GOTO __DESCO_Salida;
 END;

    SELECT @cEntidad=UPPER(NULLIF(LTRIM(RTRIM(entidadObjetivo)),'')),
           @cTipo=UPPER(NULLIF(LTRIM(RTRIM(tipoDocumento)),'')),
           @cDoc=NULLIF(LTRIM(RTRIM(numeroDocumento)),'')
    FROM OPENJSON(@cJson,'$.consulta')
    WITH(entidadObjetivo VARCHAR(10) '$.entidadObjetivo',tipoDocumento VARCHAR(15) '$.tipoDocumento',numeroDocumento VARCHAR(30) '$.numeroDocumento');

    IF @cEntidad NOT IN('PERSONA','EMPRESA') OR @cTipo NOT IN('DNI','RUC')
       OR [org].[FN_Documento_EsValido](@cTipo,@cDoc)=0
    BEGIN
        SET @cMensaje=N'El documento no es válido para consulta externa.';
        GOTO __DESCO_Salida;
    END;

    IF @cEntidad='EMPRESA'
    BEGIN
        IF @cTipo<>'RUC' OR [org].[FN_Ruc_Naturaleza](@cDoc)<>'JURIDICA'
        BEGIN SET @cMensaje=N'Empresa requiere RUC jurídico válido.';
 GOTO __DESCO_Salida;
 END;

        SELECT @nLocal=empresa_id FROM [org].[Empresa] WHERE ruc=@cDoc;
        SET @cTipoExt='RUC';
 SET @cDocExt=@cDoc;
 SET @cClave='RUC:'+@cDoc;
    END
    ELSE
    BEGIN
        IF @cTipo='RUC' AND [org].[FN_Ruc_Naturaleza](@cDoc)='JURIDICA'
        BEGIN SET @cMensaje=N'El RUC jurídico debe consultarse como EMPRESA.';
 GOTO __DESCO_Salida;
 END;

        EXEC [org].[PA_Persona_Sel_IdPorDocumentoInterno]
             @cTipoDocumento=@cTipo,@cNumeroDocumento=@cDoc,@nExcluirPersonaId=NULL,
             @nPersonaId=@nLocal OUTPUT,@nCoincidencias=@nCoin OUTPUT,
             @bResultado=@bBusca OUTPUT,@cMensaje=@cMsgBusca OUTPUT;
        IF @bBusca=0 BEGIN SET @cMensaje=@cMsgBusca;
 GOTO __DESCO_Salida;
 END;

        IF @cTipo='RUC' AND LEFT(@cDoc,2)='10'
        BEGIN SET @cTipoExt='DNI';
 SET @cDocExt=SUBSTRING(@cDoc,3,8);
 SET @cClave='DNI:'+@cDocExt;
 END
        ELSE IF @cTipo='DNI'
        BEGIN SET @cTipoExt='DNI';
 SET @cDocExt=@cDoc;
 SET @cClave='DNI:'+@cDoc;
 END
        ELSE
        BEGIN SET @cTipoExt='RUC';
 SET @cDocExt=@cDoc;
 SET @cClave='RUC:'+@cDoc;
 END;
    END;

    IF @nLocal IS NOT NULL
    BEGIN
        SELECT CONVERT(BIT,0) puedeConsultar,@cTipoExt tipoDocumentoConsultaExterna,
               @cDocExt numeroDocumentoConsultaExterna,@cClave claveConsulta,
               CAST(NULL AS DATETIME2(0)) reintentoDesdeUtc;
        SET @bResultado=1;
        SET @cMensaje=N'La información ya se encuentra registrada.';
        GOTO __DESCO_Salida;
    END;

    BEGIN TRY
        BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

        SELECT @nConsulta=consulta_documento_id,@cEstado=estado_consulta,
               @dBloqueo=bloqueo_hasta_utc,@dReintento=reintento_desde_utc
        FROM [integracion].[ConsultaDocumento] WITH (UPDLOCK,HOLDLOCK)
        WHERE entidad_objetivo=@cEntidad AND clave_documento=@cClave;

        IF @nConsulta IS NULL
        BEGIN
            INSERT [integracion].[ConsultaDocumento]
            (
                entidad_objetivo,clave_documento,tipo_documento_solicitado,
                numero_documento_solicitado,tipo_documento_externo,
                numero_documento_externo,proveedor,estado_consulta,cantidad_intentos,
                fecha_primera_solicitud_utc,fecha_ultimo_intento_utc,
                bloqueo_hasta_utc,reintento_desde_utc,estado
            )
            VALUES
            (
                @cEntidad,@cClave,@cTipo,@cDoc,@cTipoExt,@cDocExt,'FACTILIZA',
                'RESERVADA',1,SYSUTCDATETIME(),SYSUTCDATETIME(),
                DATEADD(SECOND,30,SYSUTCDATETIME()),NULL,1
            );
            SET @bPuede=1;
            SET @dReintento=NULL;
        END
        ELSE IF @cEstado='RESERVADA' AND @dBloqueo>SYSUTCDATETIME()
        BEGIN
            SET @bPuede=0;
            SET @dReintento=@dBloqueo;
        END
        ELSE IF @cEstado IN('ERROR','NO_ENCONTRADO') AND @dReintento>SYSUTCDATETIME()
        BEGIN
            SET @bPuede=0;
        END
        ELSE IF @cEstado='DATOS_INSUFICIENTES'
        BEGIN
            SET @bPuede=0;
            SET @dReintento=NULL;
        END
        ELSE
        BEGIN
            UPDATE [integracion].[ConsultaDocumento]
               SET tipo_documento_solicitado=@cTipo,
                   numero_documento_solicitado=@cDoc,
                   tipo_documento_externo=@cTipoExt,
                   numero_documento_externo=@cDocExt,
                   proveedor='FACTILIZA',
                   estado_consulta='RESERVADA',
                   cantidad_intentos=cantidad_intentos+1,
                   fecha_ultimo_intento_utc=SYSUTCDATETIME(),
                   bloqueo_hasta_utc=DATEADD(SECOND,30,SYSUTCDATETIME()),
                   reintento_desde_utc=NULL,
                   ultimo_codigo_error=NULL,
                   estado=1
             WHERE consulta_documento_id=@nConsulta;
            SET @bPuede=1;
            SET @dReintento=NULL;
        END;

        BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
    END TRY
    BEGIN CATCH
SET @bResultado = 0;

        IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
        SET @cMensaje=N'No se pudo reservar la consulta externa.';
        
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'integracion.PA_Identidad_Ins_ReservarConsultaExterna',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
GOTO __DESCO_Salida;
    
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'integracion.PA_Identidad_Ins_ReservarConsultaExterna',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;

    SELECT @bPuede puedeConsultar,@cTipoExt tipoDocumentoConsultaExterna,
           @cDocExt numeroDocumentoConsultaExterna,@cClave claveConsulta,
           @dReintento reintentoDesdeUtc;

    SET @bResultado=1;
    SET @cMensaje=CASE WHEN @bPuede=1
                       THEN N'La validación automática fue reservada correctamente.'
                       ELSE N'La validación automática no está disponible en este momento. Puede continuar con carga manual.' END;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'integracion.PA_Identidad_Ins_ReservarConsultaExterna',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'integracion.PA_Identidad_Ins_ReservarConsultaExterna',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'integracion.PA_Identidad_Ins_ReservarConsultaExterna',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* 5. Resolver identidad devuelve los campos protegidos sin cambiar el contrato REST. */
CREATE OR ALTER PROCEDURE [integracion].[PA_Identidad_Sel_ResolverDocumento]
(
    @cJson NVARCHAR(MAX),
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;

    BEGIN TRY

    SET NOCOUNT ON;

    DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,
            @gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),
            @bCtx BIT,@cMsg NVARCHAR(300);
    DECLARE @cEntidad VARCHAR(10),@cTipo VARCHAR(15),@cDoc VARCHAR(30),
            @cTipoExterno VARCHAR(15),@cDocExterno VARCHAR(30),@cClave VARCHAR(60),
            @nEntidadId BIGINT=NULL,@cTipoPersona VARCHAR(12)=NULL,
            @bEmpleado BIT=0,@bSocio BIT=0,@bAsociacion BIT=0,@bEstadoEntidad BIT=NULL,
            @nCoincidencias INT,@bBusca BIT,@cMsgBusca NVARCHAR(300),@cRucDni VARCHAR(11),
            @cEstadoPrevio VARCHAR(25)=NULL,@cEstadoSalida VARCHAR(300)=NULL,@dReintento DATETIME2(0)=NULL,@dBloqueo DATETIME2(0)=NULL,
            @bRequiereExterno BIT=0;

    SELECT @bResultado=0,@cMensaje=N'No se pudo resolver el documento.';

    EXEC [seg].[PA_Operacion_Sel_ContextoAutorizado]
         @cJson=@cJson,@cCodigoPermiso='VALIDACIONIDENTIDAD_CONSULTAR',
         @nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,
         @nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,
         @nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,
         @gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,
         @bResultado=@bCtx OUTPUT,@cMensaje=@cMsg OUTPUT;

    IF @bCtx=0
    BEGIN
        SET @cMensaje=@cMsg;
        GOTO __DESCO_Salida;
    END;

    SELECT
        @cEntidad=UPPER(NULLIF(LTRIM(RTRIM(entidadObjetivo)),'')),
        @cTipo=UPPER(NULLIF(LTRIM(RTRIM(tipoDocumento)),'')),
        @cDoc=NULLIF(LTRIM(RTRIM(numeroDocumento)),'')
    FROM OPENJSON(@cJson,'$.consulta')
    WITH
    (
        entidadObjetivo VARCHAR(10) '$.entidadObjetivo',
        tipoDocumento VARCHAR(15) '$.tipoDocumento',
        numeroDocumento VARCHAR(30) '$.numeroDocumento'
    );

    IF @cEntidad NOT IN('PERSONA','EMPRESA') OR @cTipo NOT IN('DNI','RUC')
    BEGIN
        SET @cMensaje=N'La solicitud de validación no es válida.';
        GOTO __DESCO_Salida;
    END;

    IF @cEntidad='EMPRESA'
    BEGIN
        IF @cTipo<>'RUC'
           OR LEN(@cDoc)<>11
           OR @cDoc LIKE '%[^0-9]%'
        BEGIN
            SET @cMensaje=N'El RUC debe tener 11 dígitos.';
            GOTO __DESCO_Salida;
        END;

        SELECT @nEntidadId=E.empresa_id,@bEstadoEntidad=E.estado,
               @bAsociacion=CASE WHEN A.asociacion_id IS NULL THEN 0 ELSE 1 END
        FROM [org].[Empresa] E
        LEFT JOIN [org].[Asociacion] A ON A.asociacion_id=E.empresa_id
        WHERE E.ruc=@cDoc;

        SET @cTipoPersona='JURIDICA';
        SET @cTipoExterno='RUC';
        SET @cDocExterno=@cDoc;
        SET @cClave='RUC:'+@cDoc;
    END
    ELSE
    BEGIN
        IF [org].[FN_Documento_EsValido](@cTipo,@cDoc)=0
        BEGIN
            SET @cMensaje=N'El documento ingresado no es válido.';
            GOTO __DESCO_Salida;
        END;

        IF @cTipo='RUC' AND [org].[FN_Ruc_Naturaleza](@cDoc)='JURIDICA'
        BEGIN
            SET @cMensaje=N'El RUC corresponde a una persona jurídica. Realice la búsqueda como EMPRESA.';
            GOTO __DESCO_Salida;
        END;

        EXEC [org].[PA_Persona_Sel_IdPorDocumentoInterno]
             @cTipoDocumento=@cTipo,
             @cNumeroDocumento=@cDoc,
             @nExcluirPersonaId=NULL,
             @nPersonaId=@nEntidadId OUTPUT,
             @nCoincidencias=@nCoincidencias OUTPUT,
             @bResultado=@bBusca OUTPUT,
             @cMensaje=@cMsgBusca OUTPUT;

        IF @bBusca=0
        BEGIN
            SET @cMensaje=@cMsgBusca;
            GOTO __DESCO_Salida;
        END;

        IF @nEntidadId IS NOT NULL
        BEGIN
            SELECT @cTipoPersona=P.tipo_persona,@bEstadoEntidad=P.estado
            FROM [org].[Persona] P WHERE P.persona_id=@nEntidadId;
            SET @bEmpleado=CASE WHEN EXISTS(SELECT 1 FROM [org].[Empleado] WHERE empleado_id=@nEntidadId) THEN 1 ELSE 0 END;
            SET @bSocio=CASE WHEN EXISTS(SELECT 1 FROM [org].[Socio] WHERE socio_id=@nEntidadId) THEN 1 ELSE 0 END;
        END
        ELSE
            SET @cTipoPersona='NATURAL';

        IF @cTipo='RUC' AND LEFT(@cDoc,2)='10'
        BEGIN
            SET @cTipoExterno='DNI';
            SET @cDocExterno=SUBSTRING(@cDoc,3,8);
            SET @cClave='DNI:'+@cDocExterno;
        END
        ELSE IF @cTipo='DNI'
        BEGIN
            SET @cTipoExterno='DNI';
            SET @cDocExterno=@cDoc;
            SET @cClave='DNI:'+@cDoc;
        END
        ELSE
        BEGIN
            /* RUC 15/17: persona natural sin DNI derivable de forma segura. */
            SET @cTipoExterno='RUC';
            SET @cDocExterno=@cDoc;
            SET @cClave='RUC:'+@cDoc;
        END;
    END;

    SELECT TOP(1)
           @cEstadoPrevio=CD.estado_consulta,
           @dReintento=CD.reintento_desde_utc,
           @dBloqueo=CD.bloqueo_hasta_utc
    FROM [integracion].[ConsultaDocumento] CD
    WHERE CD.entidad_objetivo=@cEntidad
      AND CD.clave_documento=@cClave
      AND CD.estado=1
    ORDER BY CD.consulta_documento_id DESC;

    IF @nEntidadId IS NOT NULL
    BEGIN
        SET @bRequiereExterno=0;
    END
    ELSE
    BEGIN
        SELECT @cEstadoPrevio=estado_consulta,
               @dReintento=reintento_desde_utc,
               @dBloqueo=bloqueo_hasta_utc
        FROM [integracion].[ConsultaDocumento]
        WHERE entidad_objetivo=@cEntidad AND clave_documento=@cClave AND estado=1;

        SET @bRequiereExterno=1;

        IF @cEstadoPrevio='RESERVADA' AND @dBloqueo>SYSUTCDATETIME()
            SET @bRequiereExterno=0;
        ELSE IF @cEstadoPrevio IN('ERROR','NO_ENCONTRADO') AND @dReintento>SYSUTCDATETIME()
            SET @bRequiereExterno=0;
        ELSE IF @cEstadoPrevio='DATOS_INSUFICIENTES'
            SET @bRequiereExterno=0;
    END;

    IF @cEntidad='PERSONA' AND @nEntidadId IS NOT NULL
    BEGIN
        SET @cEstadoSalida=@cEstadoPrevio;

        IF @cEstadoPrevio='EXITO'
        BEGIN
            DECLARE @cCamposFactiliza VARCHAR(240);

            SELECT @cCamposFactiliza=
                STRING_AGG(C.campo, ',')
                    WITHIN GROUP (ORDER BY C.campo)
            FROM [integracion].[IdentidadCampoOrigen] C
            WHERE C.entidad_objetivo='PERSONA'
              AND C.entidad_id=@nEntidadId
              AND C.proveedor='FACTILIZA'
              AND C.estado=1;

            IF NULLIF(@cCamposFactiliza,'') IS NOT NULL
                SET @cEstadoSalida='EXITO|'+@cCamposFactiliza;
        END;

        SELECT
            CONVERT(BIT,1) encontradoLocal,
            @cEntidad entidadObjetivo,
            P.persona_id entidadId,
            P.tipo_persona tipoPersona,
            P.tipo_documento tipoDocumento,
            P.numero_documento numeroDocumento,
            P.nombres,
            P.apellido_paterno apellidoPaterno,
            P.apellido_materno apellidoMaterno,
            P.telefono telefono,
            P.correo correo,
            CAST(NULL AS NVARCHAR(200)) razonSocial,
            P.fecha_nacimiento fechaNacimiento,
            P.sexo,
            P.ubicacion_id ubicacionId,
            RTRIM(DEP.departamento_codigo) departamentoCodigo,
            DEP.nombre departamentoNombre,
            RTRIM(PR.provincia_codigo) provinciaCodigo,
            PR.nombre provinciaNombre,
            RTRIM(D.distrito_codigo) distritoCodigo,
            D.nombre distritoNombre,
            U.centro_poblado_id centroPobladoId,
            CP.nombre centroPobladoNombre,
            U.referencia referenciaUbicacion,
            P.estado estadoEntidad,
            @bEmpleado esEmpleado,
            @bSocio esSocio,
            CONVERT(BIT,0) esAsociacion,
            CONVERT(BIT,0) requiereConsultaExterna,
            @cTipoExterno tipoDocumentoConsultaExterna,
            @cDocExterno numeroDocumentoConsultaExterna,
            @cClave claveConsulta,
            @cEstadoSalida estadoConsultaPrevia,
            @dReintento reintentoDesdeUtc,
            @dBloqueo bloqueoHastaUtc
        FROM [org].[Persona] P
        LEFT JOIN [geo].[Ubicacion] U
               ON U.ubicacion_id = P.ubicacion_id
        LEFT JOIN [geo].[Distrito] D
               ON D.distrito_codigo = U.distrito_codigo
        LEFT JOIN [geo].[Provincia] PR
               ON PR.provincia_codigo = D.provincia_codigo
        LEFT JOIN [geo].[Departamento] DEP
               ON DEP.departamento_codigo = PR.departamento_codigo
        LEFT JOIN [geo].[CentroPoblado] CP
               ON CP.centro_poblado_id = U.centro_poblado_id
        WHERE P.persona_id=@nEntidadId;
    END
    ELSE IF @cEntidad='EMPRESA' AND @nEntidadId IS NOT NULL
    BEGIN
        SELECT
            CONVERT(BIT,1) encontradoLocal,
            @cEntidad entidadObjetivo,
            E.empresa_id entidadId,
            'JURIDICA' tipoPersona,
            'RUC' tipoDocumento,
            RTRIM(E.ruc) numeroDocumento,
            CAST(NULL AS NVARCHAR(100)) nombres,
            CAST(NULL AS NVARCHAR(80)) apellidoPaterno,
            CAST(NULL AS NVARCHAR(80)) apellidoMaterno,
            E.telefono telefono,
            E.correo correo,
            E.razon_social razonSocial,
            CAST(NULL AS DATE) fechaNacimiento,
            CAST(NULL AS VARCHAR(20)) sexo,
            E.ubicacion_id ubicacionId,
            RTRIM(DEP.departamento_codigo) departamentoCodigo,
            DEP.nombre departamentoNombre,
            RTRIM(PR.provincia_codigo) provinciaCodigo,
            PR.nombre provinciaNombre,
            RTRIM(D.distrito_codigo) distritoCodigo,
            D.nombre distritoNombre,
            U.centro_poblado_id centroPobladoId,
            CP.nombre centroPobladoNombre,
            U.referencia referenciaUbicacion,
            E.estado estadoEntidad,
            CONVERT(BIT,0) esEmpleado,
            CONVERT(BIT,0) esSocio,
            @bAsociacion esAsociacion,
            CONVERT(BIT,0) requiereConsultaExterna,
            @cTipoExterno tipoDocumentoConsultaExterna,
            @cDocExterno numeroDocumentoConsultaExterna,
            @cClave claveConsulta,
            @cEstadoPrevio estadoConsultaPrevia,
            @dReintento reintentoDesdeUtc,
            @dBloqueo bloqueoHastaUtc
        FROM [org].[Empresa] E
        LEFT JOIN [geo].[Ubicacion] U
               ON U.ubicacion_id = E.ubicacion_id
        LEFT JOIN [geo].[Distrito] D
               ON D.distrito_codigo = U.distrito_codigo
        LEFT JOIN [geo].[Provincia] PR
               ON PR.provincia_codigo = D.provincia_codigo
        LEFT JOIN [geo].[Departamento] DEP
               ON DEP.departamento_codigo = PR.departamento_codigo
        LEFT JOIN [geo].[CentroPoblado] CP
               ON CP.centro_poblado_id = U.centro_poblado_id
        WHERE E.empresa_id=@nEntidadId;
    END
    ELSE
    BEGIN
        SELECT
            CONVERT(BIT,0) encontradoLocal,
            @cEntidad entidadObjetivo,
            CAST(NULL AS BIGINT) entidadId,
            @cTipoPersona tipoPersona,
            @cTipo tipoDocumento,
            @cDoc numeroDocumento,
            CAST(NULL AS NVARCHAR(100)) nombres,
            CAST(NULL AS NVARCHAR(80)) apellidoPaterno,
            CAST(NULL AS NVARCHAR(80)) apellidoMaterno,
            CAST(NULL AS VARCHAR(30)) telefono,
            CAST(NULL AS VARCHAR(180)) correo,
            CAST(NULL AS NVARCHAR(200)) razonSocial,
            CAST(NULL AS DATE) fechaNacimiento,
            CAST(NULL AS VARCHAR(20)) sexo,
            CAST(NULL AS BIGINT) ubicacionId,
            CAST(NULL AS VARCHAR(2)) departamentoCodigo,
            CAST(NULL AS NVARCHAR(100)) departamentoNombre,
            CAST(NULL AS VARCHAR(4)) provinciaCodigo,
            CAST(NULL AS NVARCHAR(100)) provinciaNombre,
            CAST(NULL AS VARCHAR(6)) distritoCodigo,
            CAST(NULL AS NVARCHAR(100)) distritoNombre,
            CAST(NULL AS BIGINT) centroPobladoId,
            CAST(NULL AS NVARCHAR(150)) centroPobladoNombre,
            CAST(NULL AS NVARCHAR(300)) referenciaUbicacion,
            CAST(NULL AS BIT) estadoEntidad,
            CONVERT(BIT,0) esEmpleado,
            CONVERT(BIT,0) esSocio,
            CONVERT(BIT,0) esAsociacion,
            @bRequiereExterno requiereConsultaExterna,
            @cTipoExterno tipoDocumentoConsultaExterna,
            @cDocExterno numeroDocumentoConsultaExterna,
            @cClave claveConsulta,
            @cEstadoPrevio estadoConsultaPrevia,
            @dReintento reintentoDesdeUtc,
            @dBloqueo bloqueoHastaUtc;
    END;

    SET @bResultado=1;
    SET @cMensaje=CASE WHEN @nEntidadId IS NOT NULL
                       THEN N'La información ya se encuentra registrada.'
                       WHEN @bRequiereExterno=1
                       THEN N'La información no existe localmente y puede validarse automáticamente.'
                       ELSE N'La validación automática no está disponible en este momento. Puede continuar con carga manual.' END;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'integracion.PA_Identidad_Sel_ResolverDocumento',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'integracion.PA_Identidad_Sel_ResolverDocumento',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'integracion.PA_Identidad_Sel_ResolverDocumento',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- integracion.PA_Identidad_Upd_ResultadoConsultaExterna
CREATE OR ALTER PROCEDURE [integracion].[PA_Identidad_Upd_ResultadoConsultaExterna]
(
    @cJson NVARCHAR(MAX),
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @nUsuario BIGINT,
        @nSesion BIGINT,
        @nDisp BIGINT,
        @nEmp BIGINT,
        @nModulo INT,
        @gCorr UNIQUEIDENTIFIER,
        @gSol UNIQUEIDENTIFIER,
        @cIp VARCHAR(64),
        @cEnd NVARCHAR(250),
        @bCtx BIT,
        @cMsg NVARCHAR(300),
        @nAud BIGINT,
        @nTrans BIGINT;

    DECLARE
        @cEntidad VARCHAR(10),
        @cTipo VARCHAR(15),
        @cDoc VARCHAR(30),
        @cTipoExt VARCHAR(15),
        @cDocExt VARCHAR(30),
        @cClave VARCHAR(60),
        @bExito BIT = 0,
        @bEncontrado BIT = 0,
        @cCodigoError VARCHAR(60),
        @cDatosJson NVARCHAR(MAX),
        @cNombres NVARCHAR(100),
        @cAP NVARCHAR(80),
        @cAM NVARCHAR(80),
        @dNac DATE,
        @cRazon NVARCHAR(200),
        @cDireccion NVARCHAR(300),
        @cDireccionCompleta NVARCHAR(300),
        @cSexo VARCHAR(20),
        @cDepartamento NVARCHAR(100),
        @cProvincia NVARCHAR(100),
        @cDistrito NVARCHAR(100),
        @cDepartamentoCodigo CHAR(2),
        @cProvinciaCodigo CHAR(4),
        @cDistritoCodigo CHAR(6),
        @cCentroPoblado NVARCHAR(150),
        @cCentroPobladoCodigo VARCHAR(20),
        @cTipoContribuyente NVARCHAR(120),
        @cEstadoContribuyente VARCHAR(50),
        @cCondicionContribuyente VARCHAR(50),
        @nEntidadId BIGINT = NULL,
        @nCoin INT,
        @bBusca BIT,
        @cMsgBusca NVARCHAR(300),
        @cIdent NVARCHAR(200),
        @cAccion VARCHAR(20),
        @cPosterior NVARCHAR(MAX),
        @cNombreEntidadAuditoria SYSNAME,
        @bInsertado BIT = 0,
        @nUbicacionId BIGINT = NULL,
        @nCentroPobladoId BIGINT = NULL,
        @bGeo BIT = 0,
        @cMsgGeo NVARCHAR(300),
        @bTieneGeografiaCompleta BIT = 0;

    SELECT
        @bResultado = 0,
        @cMensaje = N'No fue posible completar la validación.';

    EXEC [seg].[PA_Operacion_Sel_ContextoAutorizado]
         @cJson = @cJson,
         @cCodigoPermiso = 'VALIDACIONIDENTIDAD_IMPORTAR',
         @nUsuarioId = @nUsuario OUTPUT,
         @nSesionUsuarioId = @nSesion OUTPUT,
         @nDispositivoUsuarioId = @nDisp OUTPUT,
         @nEmpleadoId = @nEmp OUTPUT,
         @nModuloId = @nModulo OUTPUT,
         @gCorrelacionId = @gCorr OUTPUT,
         @gSolicitudId = @gSol OUTPUT,
         @cIp = @cIp OUTPUT,
         @cEndpoint = @cEnd OUTPUT,
         @bResultado = @bCtx OUTPUT,
         @cMensaje = @cMsg OUTPUT;

    IF @bCtx = 0
    BEGIN
        SET @cMensaje = N'No tiene acceso a esta opción.';
        GOTO __DESCO_Salida;
    END;

    SELECT
        @cEntidad =
            UPPER(NULLIF(LTRIM(RTRIM(entidadObjetivo)), '')),
        @cTipo =
            UPPER(NULLIF(LTRIM(RTRIM(tipoDocumento)), '')),
        @cDoc =
            NULLIF(LTRIM(RTRIM(numeroDocumento)), '')
    FROM OPENJSON(@cJson, '$.consulta')
    WITH
    (
        entidadObjetivo VARCHAR(10) '$.entidadObjetivo',
        tipoDocumento VARCHAR(15) '$.tipoDocumento',
        numeroDocumento VARCHAR(30) '$.numeroDocumento'
    );

    SELECT
        @bExito = ISNULL(exito, 0),
        @bEncontrado = ISNULL(encontrado, 0),
        @cCodigoError =
            NULLIF(LTRIM(RTRIM(codigoError)), '')
    FROM OPENJSON(@cJson, '$.resultado')
    WITH
    (
        exito BIT '$.exito',
        encontrado BIT '$.encontrado',
        codigoError VARCHAR(60) '$.codigoError'
    );

    /*
     * Compatibilidad con ambos payloads:
     *   $.datos
     *   $.resultado.datos
     */
    SET @cDatosJson =
        COALESCE
        (
            JSON_QUERY(@cJson, '$.datos'),
            JSON_QUERY(@cJson, '$.resultado.datos')
        );

    SELECT
        @cNombres =
            NULLIF(LTRIM(RTRIM(nombres)), N''),
        @cAP =
            NULLIF(LTRIM(RTRIM(apellidoPaterno)), N''),
        @cAM =
            NULLIF(LTRIM(RTRIM(apellidoMaterno)), N''),
        @dNac =
            fechaNacimiento,
        @cRazon =
            NULLIF(LTRIM(RTRIM(razonSocial)), N''),
        @cDireccion =
            NULLIF(LTRIM(RTRIM(direccionFiscal)), N''),
        @cDireccionCompleta =
            NULLIF(LTRIM(RTRIM(direccionCompleta)), N''),
        @cSexo =
            UPPER(NULLIF(LTRIM(RTRIM(sexo)), '')),
        @cDepartamento =
            UPPER(NULLIF(LTRIM(RTRIM(departamento)), N'')),
        @cProvincia =
            UPPER(NULLIF(LTRIM(RTRIM(provincia)), N'')),
        @cDistrito =
            UPPER(NULLIF(LTRIM(RTRIM(distrito)), N'')),
        @cDepartamentoCodigo =
            NULLIF(LTRIM(RTRIM(departamentoCodigo)), ''),
        @cProvinciaCodigo =
            NULLIF(LTRIM(RTRIM(provinciaCodigo)), ''),
        @cDistritoCodigo =
            NULLIF(LTRIM(RTRIM(distritoCodigo)), ''),
        @cCentroPoblado =
            UPPER(NULLIF(LTRIM(RTRIM(centroPoblado)), N'')),
        @cCentroPobladoCodigo =
            UPPER(NULLIF(LTRIM(RTRIM(centroPobladoCodigo)), '')),
        @cTipoContribuyente =
            UPPER(NULLIF(LTRIM(RTRIM(tipoContribuyente)), N'')),
        @cEstadoContribuyente =
            UPPER(NULLIF(LTRIM(RTRIM(estadoContribuyente)), '')),
        @cCondicionContribuyente =
            UPPER(NULLIF(LTRIM(RTRIM(condicionContribuyente)), ''))
    FROM OPENJSON(@cDatosJson)
    WITH
    (
        nombres NVARCHAR(100) '$.nombres',
        apellidoPaterno NVARCHAR(80) '$.apellidoPaterno',
        apellidoMaterno NVARCHAR(80) '$.apellidoMaterno',
        fechaNacimiento DATE '$.fechaNacimiento',
        razonSocial NVARCHAR(200) '$.razonSocial',
        direccionFiscal NVARCHAR(300) '$.direccionFiscal',
        direccionCompleta NVARCHAR(300) '$.direccionCompleta',
        sexo VARCHAR(20) '$.sexo',
        departamento NVARCHAR(100) '$.departamento',
        provincia NVARCHAR(100) '$.provincia',
        distrito NVARCHAR(100) '$.distrito',
        departamentoCodigo VARCHAR(2) '$.departamentoCodigo',
        provinciaCodigo VARCHAR(4) '$.provinciaCodigo',
        distritoCodigo VARCHAR(6) '$.distritoCodigo',
        centroPoblado NVARCHAR(150) '$.centroPoblado',
        centroPobladoCodigo VARCHAR(20) '$.centroPobladoCodigo',
        tipoContribuyente NVARCHAR(120) '$.tipoContribuyente',
        estadoContribuyente VARCHAR(50) '$.estadoContribuyente',
        condicionContribuyente VARCHAR(50) '$.condicionContribuyente'
    );

    /*
     * La fecha de nacimiento no es requisito mínimo.
     * Si el proveedor entrega una fecha futura o inconsistente, se ignora
     * y el usuario podrá completarla posteriormente.
     */
    IF @dNac > CONVERT(DATE, SYSUTCDATETIME())
    BEGIN
        SET @dNac = NULL;
    END;

    SET @cDireccion =
        LEFT(
            COALESCE(
                @cDireccion,
                @cDireccionCompleta
            ),
            300
        );

    IF @cDistritoCodigo IS NOT NULL
       AND LEN(@cDistritoCodigo) = 6
       AND @cDistritoCodigo NOT LIKE '%[^0-9]%'
    BEGIN
        IF @cProvinciaCodigo IS NULL
           OR LEFT(@cDistritoCodigo, 4) <> @cProvinciaCodigo
        BEGIN
            SET @cProvinciaCodigo =
                LEFT(@cDistritoCodigo, 4);
        END;

        IF @cDepartamentoCodigo IS NULL
           OR LEFT(@cDistritoCodigo, 2) <> @cDepartamentoCodigo
        BEGIN
            SET @cDepartamentoCodigo =
                LEFT(@cDistritoCodigo, 2);
        END;
    END;

    SET @bTieneGeografiaCompleta =
        CASE
            WHEN @cDepartamentoCodigo IS NOT NULL
             AND @cProvinciaCodigo IS NOT NULL
             AND @cDistritoCodigo IS NOT NULL
             AND @cDepartamento IS NOT NULL
             AND @cProvincia IS NOT NULL
             AND @cDistrito IS NOT NULL
            THEN 1
            ELSE 0
        END;

    IF @cEntidad NOT IN ('PERSONA', 'EMPRESA')
       OR @cTipo NOT IN ('DNI', 'RUC')
       OR [org].[FN_Documento_EsValido]
          (
              @cTipo,
              @cDoc
          ) = 0
    BEGIN
        SET @cMensaje =
            N'El documento ingresado no es válido.';
        GOTO __DESCO_Salida;
    END;

    IF @cEntidad = 'EMPRESA'
    BEGIN
        IF @cTipo <> 'RUC'
           OR [org].[FN_Ruc_Naturaleza](@cDoc) <> 'JURIDICA'
        BEGIN
            SET @cMensaje =
                N'El documento ingresado no corresponde a una empresa.';
            GOTO __DESCO_Salida;
        END;

        SET @cTipoExt = 'RUC';
        SET @cDocExt = @cDoc;
        SET @cClave = 'RUC:' + @cDoc;
    END
    ELSE
    BEGIN
        IF @cTipo = 'RUC'
           AND [org].[FN_Ruc_Naturaleza](@cDoc) = 'JURIDICA'
        BEGIN
            SET @cMensaje =
                N'El documento ingresado corresponde a una empresa.';
            GOTO __DESCO_Salida;
        END;

        IF @cTipo = 'RUC'
           AND LEFT(@cDoc, 2) = '10'
        BEGIN
            SET @cTipoExt = 'DNI';
            SET @cDocExt = SUBSTRING(@cDoc, 3, 8);
            SET @cClave = 'DNI:' + @cDocExt;
        END
        ELSE IF @cTipo = 'DNI'
        BEGIN
            SET @cTipoExt = 'DNI';
            SET @cDocExt = @cDoc;
            SET @cClave = 'DNI:' + @cDoc;
        END
        ELSE
        BEGIN
            SET @cTipoExt = 'RUC';
            SET @cDocExt = @cDoc;
            SET @cClave = 'RUC:' + @cDoc;
        END;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [integracion].[ConsultaDocumento]
        WHERE entidad_objetivo = @cEntidad
          AND clave_documento = @cClave
          AND estado = 1
    )
    BEGIN
        SET @cMensaje =
            N'No fue posible completar la validación. Intente nuevamente.';
        GOTO __DESCO_Salida;
    END;

    /*
     * Fallo técnico del proveedor:
     * no insertar entidad parcial.
     * La respuesta HTTP al usuario seguirá siendo funcional y genérica.
     */
    IF @bExito = 0
    BEGIN
        UPDATE [integracion].[ConsultaDocumento]
           SET proveedor = 'FACTILIZA',
               estado_consulta = 'ERROR',
               bloqueo_hasta_utc = NULL,
               reintento_desde_utc =
                    DATEADD(
                        SECOND,
                        60,
                        SYSUTCDATETIME()
                    ),
               ultimo_codigo_error =
                    COALESCE(
                        @cCodigoError,
                        'ERROR_PROVEEDOR'
                    ),
               fecha_ultimo_intento_utc =
                    SYSUTCDATETIME()
         WHERE entidad_objetivo = @cEntidad
           AND clave_documento = @cClave;

        SELECT
            CONVERT(BIT, 0) insertado,
            CONVERT(BIT, 1) permiteCargaManual,
            CAST(NULL AS BIGINT) entidadId,
            'ERROR' estadoConsulta;

        SET @bResultado = 1;
        SET @cMensaje =
            N'No fue posible completar todos los datos automáticamente. Puede continuar con carga manual.';
        GOTO __DESCO_Salida;
    END;

    IF @bEncontrado = 0
    BEGIN
        UPDATE [integracion].[ConsultaDocumento]
           SET proveedor = 'FACTILIZA',
               estado_consulta = 'NO_ENCONTRADO',
               bloqueo_hasta_utc = NULL,
               reintento_desde_utc =
                    DATEADD(
                        MINUTE,
                        15,
                        SYSUTCDATETIME()
                    ),
               ultimo_codigo_error =
                    COALESCE(
                        @cCodigoError,
                        'NO_ENCONTRADO'
                    ),
               fecha_ultimo_intento_utc =
                    SYSUTCDATETIME()
         WHERE entidad_objetivo = @cEntidad
           AND clave_documento = @cClave;

        SELECT
            CONVERT(BIT, 0) insertado,
            CONVERT(BIT, 1) permiteCargaManual,
            CAST(NULL AS BIGINT) entidadId,
            'NO_ENCONTRADO' estadoConsulta;

        SET @bResultado = 1;
        SET @cMensaje =
            N'No se encontraron datos para completar el registro. Puede ingresar la información manualmente.';
        GOTO __DESCO_Salida;
    END;

    /*
     * Mínimos:
     * PERSONA: nombres + apellido paterno.
     * EMPRESA: razón social.
     *
     * Todo lo demás es opcional y puede completarse manualmente luego.
     */
    IF (@cEntidad = 'PERSONA'
        AND (@cNombres IS NULL OR @cAP IS NULL))
       OR (@cEntidad = 'EMPRESA'
           AND @cRazon IS NULL)
    BEGIN
        UPDATE [integracion].[ConsultaDocumento]
           SET proveedor = 'FACTILIZA',
               estado_consulta = 'DATOS_INSUFICIENTES',
               bloqueo_hasta_utc = NULL,
               reintento_desde_utc = NULL,
               ultimo_codigo_error =
                    'DATOS_INSUFICIENTES',
               fecha_ultimo_intento_utc =
                    SYSUTCDATETIME()
         WHERE entidad_objetivo = @cEntidad
           AND clave_documento = @cClave;

        SELECT
            CONVERT(BIT, 0) insertado,
            CONVERT(BIT, 1) permiteCargaManual,
            CAST(NULL AS BIGINT) entidadId,
            'DATOS_INSUFICIENTES' estadoConsulta;

        SET @bResultado = 1;
        SET @cMensaje =
            N'No fue posible completar todos los datos automáticamente. Puede continuar con carga manual.';
        GOTO __DESCO_Salida;
    END;

    BEGIN TRY
        BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

        /*
         * La entidad se vuelve a buscar dentro de la transacción para cubrir
         * carreras entre solicitudes concurrentes.
         */
        IF @cEntidad = 'PERSONA'
        BEGIN
            EXEC [org].[PA_Persona_Sel_IdPorDocumentoInterno]
                 @cTipoDocumento = @cTipo,
                 @cNumeroDocumento = @cDoc,
                 @nExcluirPersonaId = NULL,
                 @nPersonaId = @nEntidadId OUTPUT,
                 @nCoincidencias = @nCoin OUTPUT,
                 @bResultado = @bBusca OUTPUT,
                 @cMensaje = @cMsgBusca OUTPUT;

            IF @bBusca = 0
            BEGIN
                BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
                SET @cMensaje =
                    N'No fue posible completar la validación. Intente nuevamente.';
                GOTO __DESCO_Salida;
            END;

            IF @nEntidadId IS NULL
            BEGIN
                /*
                 * La ubicación es enriquecimiento opcional.
                 * Si la geografía no puede normalizarse de forma segura, la
                 * Persona se inserta sin ubicación y podrá completarse manualmente.
                 */
                IF @bTieneGeografiaCompleta = 1
                BEGIN
                    EXEC [geo].[PA_Catalogo_Ins_AsegurarUbigeoFactilizaInterno]
                         @cDepartamentoCodigo = @cDepartamentoCodigo,
                         @cDepartamentoNombre = @cDepartamento,
                         @cProvinciaCodigo = @cProvinciaCodigo,
                         @cProvinciaNombre = @cProvincia,
                         @cDistritoCodigo = @cDistritoCodigo,
                         @cDistritoNombre = @cDistrito,
                         @cCentroPobladoNombre = @cCentroPoblado,
                         @cCentroPobladoCodigo = @cCentroPobladoCodigo,
                         @nCentroPobladoId = @nCentroPobladoId OUTPUT,
                         @bResultado = @bGeo OUTPUT,
                         @cMensaje = @cMsgGeo OUTPUT;

                    IF @bGeo = 1
                    BEGIN
                        INSERT INTO [geo].[Ubicacion]
                        (
                            distrito_codigo,
                            centro_poblado_id,
                            referencia,
                            posicion,
                            altitud_m,
                            estado
                        )
                        VALUES
                        (
                            @cDistritoCodigo,
                            @nCentroPobladoId,
                            @cDireccion,
                            NULL,
                            NULL,
                            1
                        );

                        SET @nUbicacionId =
                            CONVERT(
                                BIGINT,
                                SCOPE_IDENTITY()
                            );
                    END;
                END;

                INSERT INTO [org].[Persona]
                (
                    tipo_persona,
                    tipo_documento,
                    numero_documento,
                    nombres,
                    apellido_paterno,
                    apellido_materno,
                    telefono,
                    correo,
                    fecha_nacimiento,
                    ubicacion_id,
                    estado,
                    fecha_creacion,
                    sexo
                )
                VALUES
                (
                    'NATURAL',
                    @cTipo,
                    @cDoc,
                    @cNombres,
                    @cAP,
                    @cAM,
                    NULL,
                    NULL,
                    @dNac,
                    @nUbicacionId,
                    1,
                    SYSUTCDATETIME(),
                    @cSexo
                );

                SET @nEntidadId =
                    CONVERT(
                        BIGINT,
                        SCOPE_IDENTITY()
                    );

                SET @bInsertado = 1;
            END;
        END
        ELSE
        BEGIN
            SELECT
                @nEntidadId = empresa_id
            FROM [org].[Empresa]
                 WITH (UPDLOCK, HOLDLOCK)
            WHERE ruc = @cDoc;

            IF @nEntidadId IS NULL
            BEGIN
                IF @bTieneGeografiaCompleta = 1
                BEGIN
                    EXEC [geo].[PA_Catalogo_Ins_AsegurarUbigeoFactilizaInterno]
                         @cDepartamentoCodigo = @cDepartamentoCodigo,
                         @cDepartamentoNombre = @cDepartamento,
                         @cProvinciaCodigo = @cProvinciaCodigo,
                         @cProvinciaNombre = @cProvincia,
                         @cDistritoCodigo = @cDistritoCodigo,
                         @cDistritoNombre = @cDistrito,
                         @cCentroPobladoNombre = @cCentroPoblado,
                         @cCentroPobladoCodigo = @cCentroPobladoCodigo,
                         @nCentroPobladoId = @nCentroPobladoId OUTPUT,
                         @bResultado = @bGeo OUTPUT,
                         @cMensaje = @cMsgGeo OUTPUT;

                    IF @bGeo = 1
                    BEGIN
                        INSERT INTO [geo].[Ubicacion]
                        (
                            distrito_codigo,
                            centro_poblado_id,
                            referencia,
                            posicion,
                            altitud_m,
                            estado
                        )
                        VALUES
                        (
                            @cDistritoCodigo,
                            @nCentroPobladoId,
                            @cDireccion,
                            NULL,
                            NULL,
                            1
                        );

                        SET @nUbicacionId =
                            CONVERT(
                                BIGINT,
                                SCOPE_IDENTITY()
                            );
                    END;
                END;

                INSERT INTO [org].[Empresa]
                (
                    ruc,
                    razon_social,
                    nombre_comercial,
                    telefono,
                    correo,
                    ubicacion_id,
                    fecha_creacion,
                    estado,
                    tipo_contribuyente,
                    estado_sunat,
                    condicion_sunat
                )
                VALUES
                (
                    @cDoc,
                    @cRazon,
                    NULL,
                    NULL,
                    NULL,
                    @nUbicacionId,
                    SYSUTCDATETIME(),
                    1,
                    @cTipoContribuyente,
                    @cEstadoContribuyente,
                    @cCondicionContribuyente
                );

                SET @nEntidadId =
                    CONVERT(
                        BIGINT,
                        SCOPE_IDENTITY()
                    );

                SET @bInsertado = 1;
            END;
        END;

        UPDATE [integracion].[ConsultaDocumento]
           SET proveedor = 'FACTILIZA',
               estado_consulta = 'EXITO',
               bloqueo_hasta_utc = NULL,
               reintento_desde_utc = NULL,
               fecha_ultimo_exito_utc =
                    SYSUTCDATETIME(),
               ultimo_codigo_error = NULL,
               fecha_ultimo_intento_utc =
                    SYSUTCDATETIME()
         WHERE entidad_objetivo = @cEntidad
           AND clave_documento = @cClave;

        IF @bInsertado = 1
        BEGIN
            SET @cIdent =
                CONVERT(
                    NVARCHAR(200),
                    @nEntidadId
                );

            SET @cAccion = 'CREAR';

            SET @cNombreEntidadAuditoria =
                CASE
                    WHEN @cEntidad = 'PERSONA'
                    THEN N'Persona'
                    ELSE N'Empresa'
                END;

            SELECT @cPosterior =
            (
                SELECT
                    @cEntidad AS entidadObjetivo,
                    @cTipo AS tipoDocumento,
                    @cDoc AS numeroDocumento,
                    'FACTILIZA' AS proveedor,
                    @nUbicacionId AS ubicacionId,
                    @cDistritoCodigo AS distritoCodigo,
                    @dNac AS fechaNacimiento
                FOR JSON PATH,
                    WITHOUT_ARRAY_WRAPPER
            );

            EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio]
                 @nUsuario,
                 @nSesion,
                 @nDisp,
                 @nModulo,
                 @cAccion,
                 'org',
                 @cNombreEntidadAuditoria,
                 @cIdent,
                 NULL,
                 @cPosterior,
                 NULL,
                 NULL,
                 NULL,
                 NULL,
                 @cIp,
                 @gCorr,
                 @gSol,
                 @cEnd,
                 @nAud OUTPUT,
                 @nTrans OUTPUT;
        END;

        BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
    END TRY
    BEGIN CATCH
SET @bResultado = 0;

        IF XACT_STATE() <> 0
        BEGIN
            BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
        END;

        UPDATE [integracion].[ConsultaDocumento]
           SET proveedor = 'FACTILIZA',
               estado_consulta = 'ERROR',
               bloqueo_hasta_utc = NULL,
               reintento_desde_utc =
                    DATEADD(
                        SECOND,
                        60,
                        SYSUTCDATETIME()
                    ),
               ultimo_codigo_error =
                    'ERROR_PERSISTENCIA',
               fecha_ultimo_intento_utc =
                    SYSUTCDATETIME()
         WHERE entidad_objetivo = @cEntidad
           AND clave_documento = @cClave;

        SET @cMensaje =
            N'No fue posible completar la validación. Intente nuevamente.';
        
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'integracion.PA_Identidad_Upd_ResultadoConsultaExterna',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
GOTO __DESCO_Salida;
    
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'integracion.PA_Identidad_Upd_ResultadoConsultaExterna',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;

    SELECT
        @bInsertado AS insertado,
        CONVERT(BIT, 0) AS permiteCargaManual,
        @nEntidadId AS entidadId,
        'EXITO' AS estadoConsulta;

    SET @bResultado = 1;

    SET @cMensaje =
        CASE
            WHEN @bInsertado = 1
            THEN N'Los datos disponibles fueron validados y guardados correctamente.'
            ELSE N'La información ya se encuentra registrada.'
        END;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'integracion.PA_Identidad_Upd_ResultadoConsultaExterna',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'integracion.PA_Identidad_Upd_ResultadoConsultaExterna',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'integracion.PA_Identidad_Upd_ResultadoConsultaExterna',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* --------------------------------------------------------------------------
   2. Almacén
   -------------------------------------------------------------------------- */
CREATE OR ALTER PROCEDURE [logistica].[PA_Almacen_Ins_Registro]
    @nUsuarioId BIGINT,
    @nUotId BIGINT,
    @nUbicacionId BIGINT = NULL,
    @cCodigo VARCHAR(40),
    @cNombre NVARCHAR(160),
    @cDescripcion NVARCHAR(400) = NULL,
    @nAlmacenId BIGINT OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SELECT
        @nAlmacenId = NULL,
        @bResultado = 0,
        @cMensaje = N'No se pudo registrar el almacén.';

    SET @cCodigo = UPPER(NULLIF(LTRIM(RTRIM(@cCodigo)), ''));
    SET @cNombre = NULLIF(LTRIM(RTRIM(@cNombre)), N'');
    SET @cDescripcion = NULLIF(LTRIM(RTRIM(@cDescripcion)), N'');

    IF @nUsuarioId IS NULL OR @nUotId IS NULL
    BEGIN
        SET @cMensaje = N'Seleccione una UOT válida.';
        RETURN 1;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [org].[UOT]
        WHERE uot_id = @nUotId
          AND estado = 1
    )
    BEGIN
        SET @cMensaje = N'La UOT seleccionada no está disponible.';
        RETURN 1;
    END;

    IF [seg].[FN_Usuario_TienePermisoUOT]
       (@nUsuarioId, @nUotId, 'ALMACENES_CREAR') = 0
    BEGIN
        SET @cMensaje = N'No tiene permiso para registrar almacenes en esta UOT.';
        RETURN 1;
    END;

    IF @cCodigo IS NULL OR @cNombre IS NULL
    BEGIN
        SET @cMensaje = N'Complete correctamente los datos del almacén.';
        RETURN 1;
    END;

    IF @nUbicacionId IS NOT NULL
       AND NOT EXISTS
       (
           SELECT 1
           FROM [geo].[Ubicacion]
           WHERE ubicacion_id = @nUbicacionId
             AND estado = 1
       )
    BEGIN
        SET @cMensaje = N'La ubicación seleccionada no está disponible.';
        RETURN 1;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM [logistica].[Almacen]
        WHERE uot_propietaria_id = @nUotId
          AND codigo = @cCodigo
    )
    BEGIN
        SET @cMensaje = N'El código de almacén ya está registrado en esta UOT.';
        RETURN 1;
    END;

    BEGIN TRY
        BEGIN TRANSACTION;

        INSERT INTO [logistica].[Almacen]
        (
            uot_propietaria_id,
            ubicacion_id,
            codigo,
            nombre,
            descripcion,
            estado
        )
        VALUES
        (
            @nUotId,
            @nUbicacionId,
            @cCodigo,
            @cNombre,
            @cDescripcion,
            1
        );

        SET @nAlmacenId = CONVERT(BIGINT, SCOPE_IDENTITY());

        INSERT INTO [logistica].[AlmacenUOT]
        (
            almacen_id,
            uot_id,
            tipo_acceso,
            permite_entrada,
            permite_salida,
            estado
        )
        VALUES
        (
            @nAlmacenId,
            @nUotId,
            'PROPIETARIO',
            1,
            1,
            1
        );

        COMMIT TRANSACTION;

        SELECT
            @bResultado = 1,
            @cMensaje = N'Almacén registrado correctamente.';

        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        SET @nAlmacenId = NULL;
        SET @bResultado = 0;

        IF ERROR_NUMBER() IN (2601, 2627)
            SET @cMensaje = N'El código de almacén ya está registrado en esta UOT.';
        ELSE
            SET @cMensaje = N'No se pudo registrar el almacén. Revise los datos e intente nuevamente.';

        RETURN 1;
    END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [logistica].[PA_AlmacenProducto_Ins_StockInicial]
    @nUsuarioId BIGINT,
    @nSesionUsuarioId BIGINT,
    @nUotId BIGINT,
    @nAlmacenId BIGINT,
    @nProductoId BIGINT,
    @nStockInicial DECIMAL(19,3) = 0,
    @nStockMinimo DECIMAL(19,3) = 0,
    @nCostoUnitario DECIMAL(19,4) = NULL,
    @cMoneda CHAR(3) = NULL,
    @cLote VARCHAR(80) = NULL,
    @dFechaVencimiento DATE = NULL,
    @gClaveIdempotencia UNIQUEIDENTIFIER,
    @nArchivoSustentoId BIGINT = NULL,
    @cDocumento NVARCHAR(120) = NULL,
    @cObservacion NVARCHAR(500) = NULL,
    @nMovimientoId BIGINT OUTPUT,
    @nStockActual DECIMAL(19,3) OUTPUT,
    @nStockMinimoFinal DECIMAL(19,3) OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60) = NULL OUTPUT,
    @nHttpRespuesta SMALLINT = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SELECT
        @nMovimientoId = NULL,
        @nStockActual = NULL,
        @nStockMinimoFinal = NULL,
        @bResultado = 0,
        @cMensaje = N'No se pudo configurar el producto en el almacén.',
        @cCodigoRespuesta = 'STOCK_INICIAL_NO_REGISTRADO',
        @nHttpRespuesta = 400;

    SET @nStockInicial = COALESCE(@nStockInicial, 0);
    SET @nStockMinimo = COALESCE(@nStockMinimo, 0);
    SET @cLote = NULLIF(LTRIM(RTRIM(@cLote)), '');
    SET @cMoneda = UPPER(NULLIF(LTRIM(RTRIM(@cMoneda)), ''));
    SET @cDocumento = NULLIF(LTRIM(RTRIM(@cDocumento)), N'');
    SET @cObservacion = NULLIF(LTRIM(RTRIM(@cObservacion)), N'');

    IF @nStockInicial < 0 OR @nStockMinimo < 0
    BEGIN
        SET @cMensaje = N'El stock inicial y el stock mínimo no pueden ser negativos.';
        RETURN 1;
    END;

    IF @gClaveIdempotencia IS NULL
    BEGIN
        SET @cMensaje = N'La solicitud no contiene una clave válida.';
        RETURN 1;
    END;

    IF @nCostoUnitario IS NOT NULL AND @nCostoUnitario < 0
    BEGIN
        SET @cMensaje = N'El costo unitario no puede ser negativo.';
        RETURN 1;
    END;

    IF @dFechaVencimiento IS NOT NULL
       AND @dFechaVencimiento < CONVERT(date, SYSDATETIME())
    BEGIN
        SET @cMensaje = N'La fecha de vencimiento no puede ser anterior a hoy.';
        RETURN 1;
    END;

    IF @nArchivoSustentoId IS NOT NULL
       AND @nStockInicial <= 0
    BEGIN
        SET @cMensaje = N'El documento de sustento solo corresponde cuando se registra stock inicial.';
        RETURN 1;
    END;

    IF @nCostoUnitario IS NOT NULL AND @cMoneda IS NULL
        SET @cMoneda = 'PEN';

    IF @cMoneda IS NOT NULL
       AND (LEN(@cMoneda) <> 3 OR @cMoneda LIKE '%[^A-Z]%')
    BEGIN
        SET @cMensaje = N'La moneda seleccionada no es válida.';
        RETURN 1;
    END;

    DECLARE
        @nUotResuelta BIGINT = @nUotId,
        @bModoGeneral BIT,
        @bOk BIT,
        @cMsg NVARCHAR(300);

    EXEC [seg].[PA_UOT_Sel_ResolverContextoSesion]
        @nUsuarioId = @nUsuarioId,
        @nSesionUsuarioId = @nSesionUsuarioId,
        @nUotSolicitada = @nUotResuelta,
        @cCodigoPermiso = 'ALMACENES_MOVIMIENTO',
        @bRequiereUot = 1,
        @nUotId = @nUotResuelta OUTPUT,
        @bModoGeneral = @bModoGeneral OUTPUT,
        @bResultado = @bOk OUTPUT,
        @cMensaje = @cMsg OUTPUT;

    IF ISNULL(@bOk, 0) = 0
    BEGIN
        SET @cMensaje = COALESCE(NULLIF(@cMsg, N''), @cMensaje);
        RETURN 1;
    END;

    IF @nArchivoSustentoId IS NOT NULL
    BEGIN
        SELECT
            @cDocumento = LEFT(A.nombre_original, 120)
        FROM [archivo].[Archivo] A
        WHERE A.archivo_id = @nArchivoSustentoId
          AND A.uot_id = @nUotResuelta
          AND A.estado = 1;

        IF @cDocumento IS NULL
        BEGIN
            SET @cMensaje = N'El documento de sustento seleccionado no está disponible.';
            RETURN 1;
        END;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [logistica].[Almacen] A
        INNER JOIN [logistica].[AlmacenUOT] AU
            ON AU.almacen_id = A.almacen_id
           AND AU.uot_id = @nUotResuelta
           AND AU.estado = 1
           AND AU.fecha_hasta IS NULL
           AND AU.permite_entrada = 1
        WHERE A.almacen_id = @nAlmacenId
          AND A.estado = 1
    )
    BEGIN
        SET @cMensaje = N'El almacén seleccionado no permite registrar entradas para esta UOT.';
        RETURN 1;
    END;

    DECLARE
        @bRequiereLote BIT,
        @bControlaVencimiento BIT;

    SELECT
        @bRequiereLote = P.requiere_lote,
        @bControlaVencimiento = P.controla_vencimiento
    FROM [logistica].[Producto] P
    WHERE P.producto_id = @nProductoId
      AND P.estado = 1;

    IF @bRequiereLote IS NULL
    BEGIN
        SET @cMensaje = N'El producto seleccionado no está disponible.';
        RETURN 1;
    END;

    IF @bRequiereLote = 1 AND @cLote IS NULL
    BEGIN
        SET @cMensaje = N'El producto requiere indicar un lote.';
        RETURN 1;
    END;

    IF @bControlaVencimiento = 1 AND @dFechaVencimiento IS NULL
    BEGIN
        SET @cMensaje = N'El producto requiere indicar una fecha de vencimiento.';
        RETURN 1;
    END;

    /* Repetición idempotente de un stock inicial con movimiento. */
    IF EXISTS
    (
        SELECT 1
        FROM [logistica].[MovimientoInventario] M
        WHERE M.clave_idempotencia = @gClaveIdempotencia
    )
    BEGIN
        SELECT TOP (1)
            @nMovimientoId = M.movimiento_inventario_id
        FROM [logistica].[MovimientoInventario] M
        INNER JOIN [logistica].[DetalleMovimientoInventario] D
            ON D.movimiento_inventario_id = M.movimiento_inventario_id
           AND D.producto_id = @nProductoId
        WHERE M.clave_idempotencia = @gClaveIdempotencia
          AND M.almacen_id = @nAlmacenId
          AND M.uot_id = @nUotResuelta
          AND M.estado = 1;

        IF @nMovimientoId IS NULL
        BEGIN
            SET @cMensaje = N'La clave de solicitud ya fue utilizada en otra operación.';
            SET @cCodigoRespuesta = 'CLAVE_IDEMPOTENCIA_REUTILIZADA';
            SET @nHttpRespuesta = 409;
            RETURN 1;
        END;

        SELECT
            @nStockActual = S.stock_actual,
            @nStockMinimoFinal = S.stock_minimo
        FROM [logistica].[AlmacenProductoStock] S
        WHERE S.almacen_id = @nAlmacenId
          AND S.producto_id = @nProductoId;

        IF @nArchivoSustentoId IS NOT NULL
           AND NOT EXISTS
           (
               SELECT 1
               FROM [archivo].[ArchivoVinculo] AV
               WHERE AV.archivo_id = @nArchivoSustentoId
                 AND AV.movimiento_inventario_id = @nMovimientoId
                 AND AV.estado = 1
           )
        BEGIN
            INSERT INTO [archivo].[ArchivoVinculo]
            (
                archivo_id,
                movimiento_inventario_id,
                estado
            )
            VALUES
            (
                @nArchivoSustentoId,
                @nMovimientoId,
                1
            );
        END;

        SELECT
            @bResultado = 1,
            @cMensaje = N'El producto ya fue configurado correctamente.',
            @cCodigoRespuesta = 'STOCK_INICIAL_REGISTRADO',
            @nHttpRespuesta = 200;

        RETURN 0;
    END;

    IF @nStockInicial > 0
       AND EXISTS
       (
           SELECT 1
           FROM [logistica].[AlmacenProductoStock]
           WHERE almacen_id = @nAlmacenId
             AND producto_id = @nProductoId
             AND (stock_actual <> 0 OR stock_reservado <> 0)
       )
    BEGIN
        SET @cMensaje = N'El producto ya tiene stock en el almacén. Registre un movimiento de inventario.';
        SET @cCodigoRespuesta = 'PRODUCTO_YA_TIENE_STOCK';
        SET @nHttpRespuesta = 409;
        RETURN 1;
    END;

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @nStockInicial > 0
        BEGIN
            DECLARE
                @cDetalleJson NVARCHAR(MAX),
                @bMovimiento BIT,
                @cMensajeMovimiento NVARCHAR(300);

            SELECT @cDetalleJson =
            (
                SELECT
                    @nProductoId AS productoId,
                    @nStockInicial AS cantidad,
                    @nCostoUnitario AS costoUnitario,
                    @cMoneda AS moneda,
                    @cLote AS lote,
                    @dFechaVencimiento AS fechaVencimiento
                FOR JSON PATH
            );

            EXEC [logistica].[PA_MovimientoInventario_Ins_Registrar]
                @nUsuarioId = @nUsuarioId,
                @nUotId = @nUotResuelta,
                @nAlmacenId = @nAlmacenId,
                @cTipo = 'AJUSTE',
                @cNaturaleza = 'E',
                @gClaveIdempotencia = @gClaveIdempotencia,
                @cDetalleJson = @cDetalleJson,
                @nProveedorPersonaId = NULL,
                @nProveedorEmpresaId = NULL,
                @cDocumento = @cDocumento,
                @cObservacion = @cObservacion,
                @nMovimientoId = @nMovimientoId OUTPUT,
                @bResultado = @bMovimiento OUTPUT,
                @cMensaje = @cMensajeMovimiento OUTPUT;

            IF ISNULL(@bMovimiento, 0) = 0
            BEGIN
                SET @cMensaje = COALESCE(
                    NULLIF(@cMensajeMovimiento, N''),
                    N'No se pudo registrar el stock inicial.'
                );
                THROW 51070, N'DESCO_STOCK_INICIAL_NO_REGISTRADO', 1;
            END;

            IF @nArchivoSustentoId IS NOT NULL
            BEGIN
                INSERT INTO [archivo].[ArchivoVinculo]
                (
                    archivo_id,
                    movimiento_inventario_id,
                    estado
                )
                VALUES
                (
                    @nArchivoSustentoId,
                    @nMovimientoId,
                    1
                );
            END;
        END
        ELSE
        BEGIN
            IF NOT EXISTS
            (
                SELECT 1
                FROM [logistica].[AlmacenProductoStock] WITH (UPDLOCK, HOLDLOCK)
                WHERE almacen_id = @nAlmacenId
                  AND producto_id = @nProductoId
            )
            BEGIN
                INSERT INTO [logistica].[AlmacenProductoStock]
                (
                    almacen_id,
                    producto_id,
                    stock_actual,
                    stock_reservado,
                    stock_minimo,
                    fecha_actualizacion
                )
                VALUES
                (
                    @nAlmacenId,
                    @nProductoId,
                    0,
                    0,
                    @nStockMinimo,
                    SYSUTCDATETIME()
                );
            END;
        END;

        UPDATE [logistica].[AlmacenProductoStock]
        SET
            stock_minimo = @nStockMinimo,
            fecha_actualizacion = SYSUTCDATETIME()
        WHERE almacen_id = @nAlmacenId
          AND producto_id = @nProductoId;

        SELECT
            @nStockActual = S.stock_actual,
            @nStockMinimoFinal = S.stock_minimo
        FROM [logistica].[AlmacenProductoStock] S
        WHERE S.almacen_id = @nAlmacenId
          AND S.producto_id = @nProductoId;

        COMMIT TRANSACTION;

        SELECT
            @bResultado = 1,
            @cMensaje = N'Producto configurado en el almacén.',
            @cCodigoRespuesta = 'STOCK_INICIAL_REGISTRADO',
            @nHttpRespuesta = 201;

        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        SET @nMovimientoId = NULL;
        SET @nStockActual = NULL;
        SET @nStockMinimoFinal = NULL;
        SET @bResultado = 0;

        IF @cMensaje IS NULL
           OR @cMensaje = N'No se pudo configurar el producto en el almacén.'
            SET @cMensaje = N'No se pudo configurar el producto en el almacén.';

        RETURN 1;
    END CATCH;
END;


GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [logistica].[PA_BienInventario_Ins_CambioEstado]
    @nUsuarioId BIGINT,
    @nBienInventarioId BIGINT,
    @cEstadoBien VARCHAR(20),
    @cMotivo NVARCHAR(500) = NULL,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SELECT
        @bResultado = 0,
        @cMensaje = N'No se pudo cambiar el estado del recurso.';

    SELECT
        @cEstadoBien = UPPER(NULLIF(LTRIM(RTRIM(@cEstadoBien)), '')),
        @cMotivo = NULLIF(LTRIM(RTRIM(@cMotivo)), N'');

    IF @cEstadoBien NOT IN
       (
           'DISPONIBLE',
           'ASIGNADO',
           'MANTENIMIENTO',
           'AVERIADO',
           'INACTIVO',
           'BAJA',
           'NO_DISPONIBLE'
       )
    BEGIN
        SET @cMensaje = N'El estado del recurso no es válido.';
        RETURN 1;
    END;

    IF @cMotivo IS NULL
    BEGIN
        SET @cMensaje = N'Indique el motivo del cambio de estado.';
        RETURN 1;
    END;

    DECLARE
        @nUotId BIGINT,
        @cEstadoActual VARCHAR(20),
        @bActivo BIT,
        @nTranEntrada INT = @@TRANCOUNT,
        @dAhora DATETIME2(0) = SYSUTCDATETIME();

    SELECT
        @nUotId = uot_id,
        @cEstadoActual = estado_bien,
        @bActivo = estado
    FROM [logistica].[BienInventario]
    WHERE bien_inventario_id = @nBienInventarioId;

    IF @nUotId IS NULL
    BEGIN
        SET @cMensaje = N'El recurso no está disponible.';
        RETURN 1;
    END;

    IF [seg].[FN_Usuario_TienePermisoUOT]
       (
           @nUsuarioId,
           @nUotId,
           'INVENTARIO_EDITAR'
       ) = 0
    BEGIN
        SET @cMensaje = N'No tiene permiso para modificar este recurso.';
        RETURN 1;
    END;

    IF @cEstadoBien = 'ASIGNADO'
       AND EXISTS
       (
           SELECT 1
           FROM [logistica].[BienIncidente]
           WHERE bien_inventario_id = @nBienInventarioId
             AND estado = 1
             AND estado_incidente IN ('ABIERTO', 'EN_ATENCION')
       )
    BEGIN
        SET @cMensaje = N'No puede asignar un bien con incidencias abiertas.';
        RETURN 1;
    END;

    IF ISNULL(@bActivo, 0) = 0
       AND @cEstadoActual <> 'BAJA'
    BEGIN
        SET @cMensaje = N'El recurso no está disponible para cambiar de estado.';
        RETURN 1;
    END;

    BEGIN TRY
        IF @nTranEntrada = 0
            BEGIN TRANSACTION;
        ELSE
            SAVE TRANSACTION BIEN_STATE_SAVE;

        IF @cEstadoActual <> @cEstadoBien
        BEGIN
            UPDATE [logistica].[BienEstadoHistorial]
               SET fecha_hasta = COALESCE(fecha_hasta, @dAhora),
                   estado = 0
             WHERE bien_inventario_id = @nBienInventarioId
               AND estado = 1
               AND fecha_hasta IS NULL;

            INSERT [logistica].[BienEstadoHistorial]
            (
                bien_inventario_id,
                estado_bien,
                fecha_desde,
                motivo,
                usuario_id,
                estado
            )
            VALUES
            (
                @nBienInventarioId,
                @cEstadoBien,
                @dAhora,
                @cMotivo,
                @nUsuarioId,
                1
            );

            UPDATE [logistica].[BienInventario]
               SET estado_bien = @cEstadoBien,
                   estado =
                       CASE
                           WHEN @cEstadoBien = 'BAJA' THEN 0
                           ELSE 1
                       END
             WHERE bien_inventario_id = @nBienInventarioId;
        END;

        /*
         * MANTENIMIENTO es una situación operativa, no solo una etiqueta:
         * abre o pone en atención una incidencia de mantenimiento.
         */
        IF @cEstadoBien = 'MANTENIMIENTO'
        BEGIN
            UPDATE [logistica].[BienIncidente]
               SET estado_incidente = 'EN_ATENCION'
             WHERE bien_inventario_id = @nBienInventarioId
               AND estado = 1
               AND estado_incidente = 'ABIERTO'
               AND tipo_incidente IN
                   ('AVERIA', 'ACCIDENTE', 'MANTENIMIENTO');

            IF NOT EXISTS
            (
                SELECT 1
                FROM [logistica].[BienIncidente]
                WHERE bien_inventario_id = @nBienInventarioId
                  AND tipo_incidente = 'MANTENIMIENTO'
                  AND estado = 1
                  AND estado_incidente IN ('ABIERTO', 'EN_ATENCION')
            )
            BEGIN
                INSERT [logistica].[BienIncidente]
                (
                    bien_inventario_id,
                    tipo_incidente,
                    fecha_hora,
                    descripcion,
                    costo_estimado,
                    estado_incidente,
                    usuario_reporte_id,
                    estado
                )
                VALUES
                (
                    @nBienInventarioId,
                    'MANTENIMIENTO',
                    @dAhora,
                    @cMotivo,
                    NULL,
                    'EN_ATENCION',
                    @nUsuarioId,
                    1
                );
            END;
        END;

        /*
         * Si se marca AVERIADO manualmente y no existe una incidencia
         * operativa, se crea una para conservar trazabilidad.
         */
        IF @cEstadoBien = 'AVERIADO'
           AND NOT EXISTS
           (
               SELECT 1
               FROM [logistica].[BienIncidente]
               WHERE bien_inventario_id = @nBienInventarioId
                 AND tipo_incidente IN ('AVERIA', 'ACCIDENTE')
                 AND estado = 1
                 AND estado_incidente IN ('ABIERTO', 'EN_ATENCION')
           )
        BEGIN
            INSERT [logistica].[BienIncidente]
            (
                bien_inventario_id,
                tipo_incidente,
                fecha_hora,
                descripcion,
                costo_estimado,
                estado_incidente,
                usuario_reporte_id,
                estado
            )
            VALUES
            (
                @nBienInventarioId,
                'AVERIA',
                @dAhora,
                @cMotivo,
                NULL,
                'ABIERTO',
                @nUsuarioId,
                1
            );
        END;

        /*
         * Volver a DISPONIBLE significa que el evento operativo terminó.
         */
        IF @cEstadoBien = 'DISPONIBLE'
        BEGIN
            UPDATE [logistica].[BienIncidente]
               SET estado_incidente = 'RESUELTO',
                   fecha_cierre = COALESCE(fecha_cierre, @dAhora),
                   usuario_cierre_id =
                       COALESCE(usuario_cierre_id, @nUsuarioId),
                   solucion =
                       COALESCE(NULLIF(solucion, N''), @cMotivo)
             WHERE bien_inventario_id = @nBienInventarioId
               AND estado = 1
               AND estado_incidente IN ('ABIERTO', 'EN_ATENCION');
        END;

        /*
         * La BAJA cierra definitivamente cualquier incidencia pendiente.
         */
        IF @cEstadoBien = 'BAJA'
        BEGIN
            UPDATE [logistica].[BienIncidente]
               SET estado_incidente = 'CERRADO',
                   fecha_cierre = COALESCE(fecha_cierre, @dAhora),
                   usuario_cierre_id =
                       COALESCE(usuario_cierre_id, @nUsuarioId),
                   solucion =
                       COALESCE(
                           NULLIF(solucion, N''),
                           N'Incidencia cerrada por baja del bien. '
                           + @cMotivo
                       )
             WHERE bien_inventario_id = @nBienInventarioId
               AND estado = 1
               AND estado_incidente IN ('ABIERTO', 'EN_ATENCION');
        END;

        IF @nTranEntrada = 0
            COMMIT TRANSACTION;

        SELECT
            @bResultado = 1,
            @cMensaje =
                CASE
                    WHEN @cEstadoActual = @cEstadoBien
                        THEN N'El recurso ya se encuentra en el estado indicado.'
                    ELSE N'Estado del recurso actualizado correctamente.'
                END;

        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
        BEGIN
            IF @nTranEntrada = 0
                ROLLBACK TRANSACTION;
            ELSE IF XACT_STATE() = 1
                ROLLBACK TRANSACTION BIEN_STATE_SAVE;
        END;

        SET @bResultado = 0;
        SET @cMensaje =
            N'No se pudo cambiar el estado del recurso. Intente nuevamente.';

        RETURN 1;
    END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [logistica].[PA_BienInventario_Ins_Incidente]
    @nUsuarioId BIGINT,
    @nBienInventarioId BIGINT,
    @cTipo VARCHAR(30),
    @dFechaHora DATETIME2(0),
    @cDescripcion NVARCHAR(700),
    @nCostoEstimado DECIMAL(19,4) = NULL,
    @nBienIncidenteId BIGINT OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SELECT
        @nBienIncidenteId = NULL,
        @bResultado = 0,
        @cMensaje = N'No se pudo registrar el incidente.';

    SELECT
        @cTipo = UPPER(NULLIF(LTRIM(RTRIM(@cTipo)), '')),
        @cDescripcion = NULLIF(LTRIM(RTRIM(@cDescripcion)), N'');

    DECLARE
        @nUotId BIGINT,
        @cEstadoObjetivo VARCHAR(20),
        @bCambioEstado BIT,
        @cMensajeEstado NVARCHAR(300),
        @nTranEntrada INT = @@TRANCOUNT;

    SELECT @nUotId = uot_id
    FROM [logistica].[BienInventario]
    WHERE bien_inventario_id = @nBienInventarioId
      AND estado = 1
      AND estado_bien <> 'BAJA';

    IF @nUotId IS NULL
    BEGIN
        SET @cMensaje = N'El recurso no está disponible.';
        RETURN 1;
    END;

    IF [seg].[FN_Usuario_TienePermisoUOT]
       (
           @nUsuarioId,
           @nUotId,
           'INVENTARIO_EDITAR'
       ) = 0
    BEGIN
        SET @cMensaje =
            N'No tiene permiso para registrar incidentes en este recurso.';
        RETURN 1;
    END;

    IF @dFechaHora IS NULL
       OR @dFechaHora > SYSUTCDATETIME()
    BEGIN
        SET @cMensaje = N'La fecha del incidente no es válida.';
        RETURN 1;
    END;

    IF @cTipo NOT IN
       ('AVERIA', 'ACCIDENTE', 'PERDIDA', 'ROBO', 'MANTENIMIENTO', 'OTRO')
       OR @cDescripcion IS NULL
       OR (@nCostoEstimado IS NOT NULL AND @nCostoEstimado < 0)
    BEGIN
        SET @cMensaje = N'Complete correctamente los datos del incidente.';
        RETURN 1;
    END;

    SET @cEstadoObjetivo =
        CASE
            WHEN @cTipo IN ('AVERIA', 'ACCIDENTE') THEN 'AVERIADO'
            WHEN @cTipo IN ('PERDIDA', 'ROBO') THEN 'NO_DISPONIBLE'
            WHEN @cTipo = 'MANTENIMIENTO' THEN 'MANTENIMIENTO'
            ELSE NULL
        END;

    BEGIN TRY
        IF @nTranEntrada = 0
            BEGIN TRANSACTION;
        ELSE
            SAVE TRANSACTION BIEN_INCIDENT_SAVE;

        INSERT [logistica].[BienIncidente]
        (
            bien_inventario_id,
            tipo_incidente,
            fecha_hora,
            descripcion,
            costo_estimado,
            estado_incidente,
            usuario_reporte_id,
            estado
        )
        VALUES
        (
            @nBienInventarioId,
            @cTipo,
            @dFechaHora,
            @cDescripcion,
            @nCostoEstimado,
            CASE
                WHEN @cTipo = 'MANTENIMIENTO' THEN 'EN_ATENCION'
                ELSE 'ABIERTO'
            END,
            @nUsuarioId,
            1
        );

        SET @nBienIncidenteId =
            CONVERT(BIGINT, SCOPE_IDENTITY());

        /*
         * El tipo de incidencia gobierna el estado operativo del bien.
         */
        IF @cEstadoObjetivo IS NOT NULL
        BEGIN
            EXEC [logistica].[PA_BienInventario_Ins_CambioEstado]
                @nUsuarioId = @nUsuarioId,
                @nBienInventarioId = @nBienInventarioId,
                @cEstadoBien = @cEstadoObjetivo,
                @cMotivo = @cDescripcion,
                @bResultado = @bCambioEstado OUTPUT,
                @cMensaje = @cMensajeEstado OUTPUT;

            IF ISNULL(@bCambioEstado, 0) = 0
                THROW 51070,
                      N'No se pudo sincronizar el estado del bien.',
                      1;
        END;

        IF @nTranEntrada = 0
            COMMIT TRANSACTION;

        SELECT
            @bResultado = 1,
            @cMensaje = N'Incidente registrado correctamente.';

        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
        BEGIN
            IF @nTranEntrada = 0
                ROLLBACK TRANSACTION;
            ELSE IF XACT_STATE() = 1
                ROLLBACK TRANSACTION BIEN_INCIDENT_SAVE;
        END;

        SET @nBienIncidenteId = NULL;
        SET @bResultado = 0;
        SET @cMensaje =
            COALESCE(
                NULLIF(@cMensajeEstado, N''),
                N'No se pudo registrar el incidente. Intente nuevamente.'
            );

        RETURN 1;
    END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [logistica].[PA_BienInventario_Ins_Registro]
    @cJson NVARCHAR(MAX),
    @nBienInventarioId BIGINT OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60) = NULL OUTPUT,
    @nHttpRespuesta SMALLINT = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SELECT
        @nBienInventarioId = NULL,
        @bResultado = 0,
        @cMensaje = N'No se pudo registrar el bien.',
        @cCodigoRespuesta = 'BIEN_NO_CREADO',
        @nHttpRespuesta = 400;

    DECLARE
        @nUsuario BIGINT,
        @nSesion BIGINT,
        @nDisp BIGINT,
        @nEmp BIGINT,
        @nModulo INT,
        @gCorr UNIQUEIDENTIFIER,
        @gSol UNIQUEIDENTIFIER,
        @cIp VARCHAR(64),
        @cEnd NVARCHAR(250),
        @nOp BIGINT,
        @bRep BIT,
        @cEstadoOp VARCHAR(20),
        @cIdRes NVARCHAR(200),
        @cCodRes VARCHAR(40),
        @bIni BIT,
        @cMsg NVARCHAR(300),
        @bFin BIT,
        @cMsgFin NVARCHAR(300),
        @nAud BIGINT,
        @nTrans BIGINT,
        @nUotId BIGINT,
        @nEmpresaId BIGINT,
        @nTipoBienId SMALLINT,
        @cCodigoPatrimonial VARCHAR(60),
        @cNombre NVARCHAR(150),
        @cMarca NVARCHAR(80),
        @cModelo NVARCHAR(80),
        @cSerie NVARCHAR(100),
        @dFechaAdquisicion DATE,
        @nMontoAdquisicion DECIMAL(19,4),
        @cMoneda CHAR(3),
        @nProveedorPersonaId BIGINT,
        @nProveedorEmpresaId BIGINT,
        @cObservacion NVARCHAR(500),
        @nTranEntrada INT,
        @bTranAbierta BIT = 0,
        @cIdent NVARCHAR(200);

    /* Conserva validación de sesión, permiso, correlación y contexto técnico. */
    EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente]
        @cJson = @cJson,
        @cCodigoPermiso = 'INVENTARIO_CREAR',
        @cAmbito = 'BIEN_CREAR_SQL',
        @nUsuarioId = @nUsuario OUTPUT,
        @nSesionUsuarioId = @nSesion OUTPUT,
        @nDispositivoUsuarioId = @nDisp OUTPUT,
        @nEmpleadoId = @nEmp OUTPUT,
        @nModuloId = @nModulo OUTPUT,
        @gCorrelacionId = @gCorr OUTPUT,
        @gSolicitudId = @gSol OUTPUT,
        @cIp = @cIp OUTPUT,
        @cEndpoint = @cEnd OUTPUT,
        @nOperacionIdempotenteId = @nOp OUTPUT,
        @bEsRepetida = @bRep OUTPUT,
        @cEstadoOperacion = @cEstadoOp OUTPUT,
        @cIdentificadorResultado = @cIdRes OUTPUT,
        @cCodigoResultado = @cCodRes OUTPUT,
        @bResultado = @bIni OUTPUT,
        @cMensaje = @cMsg OUTPUT;

    IF ISNULL(@bIni, 0) = 0 AND ISNULL(@bRep, 0) = 0
    BEGIN
        SET @cMensaje = COALESCE(NULLIF(@cMsg, N''), @cMensaje);
        SET @cCodigoRespuesta = 'BIEN_NO_CREADO';
        SET @nHttpRespuesta = 400;
        RETURN 1;
    END;

    IF ISNULL(@bRep, 0) = 1
    BEGIN
        IF @cEstadoOp = 'COMPLETADA'
        BEGIN
            SET @nBienInventarioId = TRY_CONVERT(BIGINT, @cIdRes);
            SET @bResultado = CASE WHEN @nBienInventarioId IS NULL THEN 0 ELSE 1 END;
            SET @cMensaje = CASE WHEN @bResultado = 1
                THEN N'La solicitud ya fue procesada correctamente.'
                ELSE N'No se pudo recuperar el resultado anterior.' END;
            SET @cCodigoRespuesta = CASE WHEN @bResultado = 1 THEN 'BIEN_CREADO' ELSE 'BIEN_NO_CREADO' END;
            SET @nHttpRespuesta = CASE WHEN @bResultado = 1 THEN 201 ELSE 503 END;
            RETURN CASE WHEN @bResultado = 1 THEN 0 ELSE 1 END;
        END;

        SELECT @cMensaje = COALESCE(
            NULLIF(mensaje_resultado, N''),
            CASE WHEN estado_operacion = 'FALLIDA'
                 THEN N'La solicitud anterior no se completó. Corrija los datos y envíe una nueva solicitud.'
                 ELSE N'La solicitud todavía se está procesando. Intente nuevamente.' END)
        FROM [auditoria].[OperacionIdempotente]
        WHERE operacion_idempotente_id = @nOp;

        SET @cCodigoRespuesta = CASE WHEN @cEstadoOp = 'EN_PROCESO'
                                     THEN 'OPERACION_EN_PROCESO'
                                     ELSE 'BIEN_NO_CREADO' END;
        SET @nHttpRespuesta = CASE WHEN @cEstadoOp = 'EN_PROCESO' THEN 409 ELSE 400 END;
        RETURN 1;
    END;

    /* Se admiten nombres del contrato HTTP actual y alias internos en inglés. */
    SELECT
        @nUotId = COALESCE(
            TRY_CONVERT(BIGINT, JSON_VALUE(@cJson, '$.bien.uotId')),
            TRY_CONVERT(BIGINT, JSON_VALUE(@cJson, '$.bien.uotContextoId')),
            TRY_CONVERT(BIGINT, JSON_VALUE(@cJson, '$.bien.contextUotId')),
            TRY_CONVERT(BIGINT, JSON_VALUE(@cJson, '$.contexto.uotId')),
            TRY_CONVERT(BIGINT, JSON_VALUE(@cJson, '$.uotId'))
        ),
        @nTipoBienId = COALESCE(
            TRY_CONVERT(SMALLINT, JSON_VALUE(@cJson, '$.bien.tipoBienId')),
            TRY_CONVERT(SMALLINT, JSON_VALUE(@cJson, '$.bien.assetTypeId'))
        ),
        @cCodigoPatrimonial = UPPER(NULLIF(LTRIM(RTRIM(COALESCE(
            JSON_VALUE(@cJson, '$.bien.codigoPatrimonial'),
            JSON_VALUE(@cJson, '$.bien.patrimonialCode')
        ))), '')),
        @cNombre = NULLIF(LTRIM(RTRIM(COALESCE(
            JSON_VALUE(@cJson, '$.bien.nombre'),
            JSON_VALUE(@cJson, '$.bien.name')
        ))), N''),
        @cMarca = NULLIF(LTRIM(RTRIM(COALESCE(
            JSON_VALUE(@cJson, '$.bien.marca'),
            JSON_VALUE(@cJson, '$.bien.brand')
        ))), N''),
        @cModelo = NULLIF(LTRIM(RTRIM(COALESCE(
            JSON_VALUE(@cJson, '$.bien.modelo'),
            JSON_VALUE(@cJson, '$.bien.model')
        ))), N''),
        @cSerie = NULLIF(LTRIM(RTRIM(COALESCE(
            JSON_VALUE(@cJson, '$.bien.serie'),
            JSON_VALUE(@cJson, '$.bien.serial')
        ))), N''),
        @dFechaAdquisicion = COALESCE(
            TRY_CONVERT(DATE, JSON_VALUE(@cJson, '$.bien.fechaAdquisicion')),
            TRY_CONVERT(DATE, JSON_VALUE(@cJson, '$.bien.acquisitionDate'))
        ),
        @nMontoAdquisicion = COALESCE(
            TRY_CONVERT(DECIMAL(19,4), JSON_VALUE(@cJson, '$.bien.montoAdquisicion')),
            TRY_CONVERT(DECIMAL(19,4), JSON_VALUE(@cJson, '$.bien.acquisitionAmount'))
        ),
        @cMoneda = UPPER(NULLIF(LTRIM(RTRIM(COALESCE(
            JSON_VALUE(@cJson, '$.bien.moneda'),
            JSON_VALUE(@cJson, '$.bien.currency')
        ))), '')),
        @nProveedorPersonaId = COALESCE(
            TRY_CONVERT(BIGINT, JSON_VALUE(@cJson, '$.bien.proveedorPersonaId')),
            TRY_CONVERT(BIGINT, JSON_VALUE(@cJson, '$.bien.providerPersonId'))
        ),
        @nProveedorEmpresaId = COALESCE(
            TRY_CONVERT(BIGINT, JSON_VALUE(@cJson, '$.bien.proveedorEmpresaId')),
            TRY_CONVERT(BIGINT, JSON_VALUE(@cJson, '$.bien.providerCompanyId'))
        ),
        @cObservacion = NULLIF(LTRIM(RTRIM(COALESCE(
            JSON_VALUE(@cJson, '$.bien.observacion'),
            JSON_VALUE(@cJson, '$.bien.observation')
        ))), N'');

    IF @nMontoAdquisicion IS NOT NULL AND @cMoneda IS NULL
        SET @cMoneda = 'PEN';

    IF @nUotId IS NULL OR @nTipoBienId IS NULL OR @cNombre IS NULL
    BEGIN
        SET @cMensaje = N'Complete correctamente los datos requeridos del bien.';
        GOTO Fallar;
    END;

    SELECT @nEmpresaId = U.empresa_legacy_id
    FROM [org].[UOT] U
    WHERE U.uot_id = @nUotId
      AND U.estado = 1;

    IF @nEmpresaId IS NULL
       OR NOT EXISTS (SELECT 1 FROM [org].[Empresa] WHERE empresa_id = @nEmpresaId AND estado = 1)
    BEGIN
        SET @cMensaje = N'La UOT seleccionada no tiene una organización operativa válida.';
        GOTO Fallar;
    END;

    IF [seg].[FN_Usuario_TienePermisoUOT](@nUsuario, @nUotId, 'INVENTARIO_CREAR') = 0
    BEGIN
        SET @cMensaje = N'No tiene permiso para registrar bienes en esta UOT.';
        SET @nHttpRespuesta = 403;
        GOTO Fallar;
    END;

    IF NOT EXISTS (SELECT 1 FROM [logistica].[TipoBien] WHERE tipo_bien_id = @nTipoBienId AND estado = 1)
    BEGIN
        SET @cMensaje = N'El tipo de bien seleccionado no está disponible.';
        GOTO Fallar;
    END;

    /* El código definitivo depende del ID, por eso el INSERT usa un valor temporal único. */
    SET @cCodigoPatrimonial =
        CONCAT(
            'TMP-B-',
            REPLACE(CONVERT(VARCHAR(36), NEWID()), '-', '')
        );

    IF EXISTS (SELECT 1 FROM [logistica].[BienInventario] WHERE codigo_patrimonial = @cCodigoPatrimonial)
    BEGIN
        SET @cMensaje = N'El código patrimonial ya se encuentra registrado.';
        SET @cCodigoRespuesta = 'CODIGO_PATRIMONIAL_DUPLICADO';
        SET @nHttpRespuesta = 409;
        GOTO Fallar;
    END;

    IF @nMontoAdquisicion IS NOT NULL AND @nMontoAdquisicion < 0
    BEGIN
        SET @cMensaje = N'El monto de adquisición no es válido.';
        GOTO Fallar;
    END;

    IF @cMoneda IS NOT NULL AND (@cMoneda NOT LIKE '[A-Z][A-Z][A-Z]' OR LEN(@cMoneda) <> 3)
    BEGIN
        SET @cMensaje = N'La moneda seleccionada no es válida.';
        GOTO Fallar;
    END;

    IF @nProveedorPersonaId IS NOT NULL AND @nProveedorEmpresaId IS NOT NULL
    BEGIN
        SET @cMensaje = N'Seleccione solo una persona o una empresa como proveedor.';
        GOTO Fallar;
    END;

    IF @nProveedorPersonaId IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM [org].[Persona] WHERE persona_id = @nProveedorPersonaId AND estado = 1)
    BEGIN
        SET @cMensaje = N'El proveedor seleccionado no está disponible.';
        GOTO Fallar;
    END;

    IF @nProveedorEmpresaId IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM [org].[Empresa] WHERE empresa_id = @nProveedorEmpresaId AND estado = 1)
    BEGIN
        SET @cMensaje = N'El proveedor seleccionado no está disponible.';
        GOTO Fallar;
    END;

    SET @nTranEntrada = @@TRANCOUNT;

    BEGIN TRY
        IF @nTranEntrada = 0
            BEGIN TRANSACTION;
        ELSE
            SAVE TRANSACTION BIEN_CREATE_SAVE;
        SET @bTranAbierta = 1;

        INSERT INTO [logistica].[BienInventario]
        (
            empresa_id,
            tipo_bien_id,
            codigo_patrimonial,
            nombre,
            marca,
            modelo,
            serie,
            estado_bien,
            estado,
            uot_id,
            fecha_adquisicion,
            monto_adquisicion,
            moneda_adquisicion,
            proveedor_persona_id,
            proveedor_empresa_id,
            observacion
        )
        VALUES
        (
            @nEmpresaId,
            @nTipoBienId,
            @cCodigoPatrimonial,
            @cNombre,
            @cMarca,
            @cModelo,
            @cSerie,
            'DISPONIBLE',
            1,
            @nUotId,
            @dFechaAdquisicion,
            @nMontoAdquisicion,
            @cMoneda,
            @nProveedorPersonaId,
            @nProveedorEmpresaId,
            @cObservacion
        );

        SET @nBienInventarioId = CONVERT(BIGINT, SCOPE_IDENTITY());

        SET @cCodigoPatrimonial =
            [logistica].[FN_CodigoRecursoUOT]
            (
                @nUotId,
                @cNombre,
                @nBienInventarioId
            );

        UPDATE [logistica].[BienInventario]
           SET codigo_patrimonial = @cCodigoPatrimonial
         WHERE bien_inventario_id = @nBienInventarioId;

        SET @cIdent = CONVERT(NVARCHAR(200), @nBienInventarioId);

        /* El historial nace junto con el bien, evitando un detalle sin estado inicial. */
        INSERT INTO [logistica].[BienEstadoHistorial]
        (
            bien_inventario_id,
            estado_bien,
            fecha_desde,
            motivo,
            usuario_id,
            estado
        )
        VALUES
        (
            @nBienInventarioId,
            'DISPONIBLE',
            SYSUTCDATETIME(),
            N'Registro inicial del bien.',
            @nUsuario,
            1
        );

        EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio]
            @nUsuario, @nSesion, @nDisp, @nModulo,
            'CREAR', 'logistica', 'BienInventario', @cIdent,
            NULL, NULL, NULL, 'estado_bien', NULL, 'DISPONIBLE',
            @cIp, @gCorr, @gSol, @cEnd,
            @nAud OUTPUT, @nTrans OUTPUT;

        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
            @nOperacionIdempotenteId = @nOp,
            @cEstadoOperacion = 'COMPLETADA',
            @cEsquemaEntidad = 'logistica',
            @cNombreEntidad = 'BienInventario',
            @cIdentificadorResultado = @cIdent,
            @cCodigoResultado = 'BIEN_CREADO',
            @bResultado = @bFin OUTPUT,
            @cMensaje = @cMsgFin OUTPUT;

        IF ISNULL(@bFin, 0) = 0
            THROW 51003, 'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;

        IF @nTranEntrada = 0
            COMMIT TRANSACTION;
        SET @bTranAbierta = 0;

        SELECT
            @bResultado = 1,
            @cMensaje = N'Bien registrado correctamente.',
            @cCodigoRespuesta = 'BIEN_CREADO',
            @nHttpRespuesta = 201;

        RETURN 0;
    END TRY
    BEGIN CATCH
        IF @bTranAbierta = 1 AND XACT_STATE() <> 0
        BEGIN
            IF @nTranEntrada = 0
                ROLLBACK TRANSACTION;
            ELSE IF XACT_STATE() = 1
                ROLLBACK TRANSACTION BIEN_CREATE_SAVE;
        END;
        SET @bTranAbierta = 0;
        SET @nBienInventarioId = NULL;
        SET @bResultado = 0;
        SET @cCodigoRespuesta = 'BIEN_NO_CREADO';
        SET @nHttpRespuesta = 400;

        IF ERROR_NUMBER() IN (2601, 2627)
            SET @cMensaje = N'El código patrimonial ya se encuentra registrado.';
        ELSE
            SET @cMensaje = N'No se pudo registrar el bien. Intente nuevamente.';

        GOTO Fallar;
    END CATCH;

Fallar:
    IF @nOp IS NOT NULL AND ISNULL(@bRep, 0) = 0 AND XACT_STATE() <> -1
    BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                @nOperacionIdempotenteId = @nOp,
                @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
            /* El fallo secundario de auditoría no reemplaza el motivo funcional. */
        END CATCH;
    END;

    IF @nHttpRespuesta IS NULL SET @nHttpRespuesta = 400;
    IF @cCodigoRespuesta IS NULL SET @cCodigoRespuesta = 'BIEN_NO_CREADO';
    SET @bResultado = 0;
    SET @nBienInventarioId = NULL;
    RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- logistica.PA_BienInventario_Sel_Detalle
CREATE OR ALTER PROCEDURE [logistica].[PA_BienInventario_Sel_Detalle](@cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;

    BEGIN TRY
  SET NOCOUNT ON;
DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@bCtx BIT,@cMsg NVARCHAR(300);
SELECT @bResultado=0,@cMensaje=N'No se pudo consultar el bien.';
EXEC seg.PA_Operacion_Sel_ContextoAutorizado @cJson=@cJson,@cCodigoPermiso='INVENTARIO_VER',@nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@bResultado=@bCtx OUTPUT,@cMensaje=@cMsg OUTPUT;
IF @bCtx=0 BEGIN SET @cMensaje=@cMsg;
GOTO __DESCO_Salida;
END;
 DECLARE @nId BIGINT;
SELECT @nId=bienInventarioId FROM OPENJSON(@cJson,'$.bien') WITH(bienInventarioId BIGINT '$.bienInventarioId');
IF NOT EXISTS(SELECT 1 FROM logistica.BienInventario WHERE bien_inventario_id=@nId AND estado=1) BEGIN SET @cMensaje=N'El bien seleccionado no está disponible.';
GOTO __DESCO_Salida;
END;
SELECT B.*,E.razon_social empresa,T.nombre tipoBien,V.placa,V.tipo_vehiculo tipoVehiculo,V.kilometraje_km kilometrajeKm FROM logistica.BienInventario B INNER JOIN org.Empresa E ON E.empresa_id=B.empresa_id INNER JOIN logistica.TipoBien T ON T.tipo_bien_id=B.tipo_bien_id LEFT JOIN logistica.Vehiculo V ON V.vehiculo_id=B.bien_inventario_id AND V.estado=1 WHERE B.bien_inventario_id=@nId;
SELECT R.recurso_programado_id recursoProgramadoId,R.estado_proceso estadoProceso,R.cantidad_programada cantidadProgramada,R.fecha_programacion fechaProgramacion,R.campania_venta_id campaniaVentaId,R.operativo_venta_id operativoVentaId,R.salida_campo_id salidaCampoId FROM logistica.RecursoProgramado R WHERE R.bien_inventario_id=@nId AND R.estado=1 ORDER BY R.fecha_programacion DESC;
SELECT M.recurso_movimiento_id recursoMovimientoId,M.tipo_movimiento tipoMovimiento,M.cantidad,M.fecha_hora fechaHora,M.observacion FROM logistica.RecursoMovimiento M INNER JOIN logistica.RecursoProgramado R ON R.recurso_programado_id=M.recurso_programado_id WHERE R.bien_inventario_id=@nId AND M.estado=1 ORDER BY M.fecha_hora DESC;
SET @bResultado=1;
SET @cMensaje=N'Bien consultado correctamente.';
    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'logistica.PA_BienInventario_Sel_Detalle',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

