CREATE OR ALTER PROCEDURE [logistica].[PA_BienInventario_Sel_ListadoPaginado]
 @nUsuarioId BIGINT,@nSesionUsuarioId BIGINT,@nUotId BIGINT=NULL,@cBuscar NVARCHAR(150)=NULL,@nTipoBienId INT=NULL,@cEstado VARCHAR(20)=NULL,@nPagina INT=1,@nTamano INT=20,
 @bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,@cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SELECT @bResultado=0,@cMensaje=N'No se pudo consultar el inventario.',@cCodigoRespuesta='BIENES_NO_LISTADOS',@nHttpRespuesta=400;
 SET @cBuscar=NULLIF(LTRIM(RTRIM(@cBuscar)),N''); SET @cEstado=UPPER(NULLIF(LTRIM(RTRIM(@cEstado)),''));
 SET @nPagina=CASE WHEN ISNULL(@nPagina,0)<1 THEN 1 ELSE @nPagina END; SET @nTamano=CASE WHEN ISNULL(@nTamano,0)<1 THEN 20 WHEN @nTamano>100 THEN 100 ELSE @nTamano END;
 DECLARE @Uot BIGINT=@nUotId,@General BIT,@Ok BIT,@Msg NVARCHAR(300);
 EXEC seg.PA_UOT_Sel_ResolverContextoSesion @nUsuarioId,@nSesionUsuarioId,@Uot,'INVENTARIO_LISTAR',0,@Uot OUTPUT,@General OUTPUT,@Ok OUTPUT,@Msg OUTPUT;
 IF @Ok=0 BEGIN SET @cMensaje=@Msg; RETURN 1; END;
 ;WITH B AS(
   SELECT BI.bien_inventario_id bienInventarioId,BI.uot_id uotId,U.codigo uotCodigo,U.nombre uotNombre,BI.tipo_bien_id tipoBienId,T.codigo tipoBienCodigo,T.nombre tipoBien,
          BI.codigo_patrimonial codigoPatrimonial,BI.nombre,BI.marca,BI.modelo,BI.serie,BI.estado_bien estadoBien,BI.fecha_adquisicion fechaAdquisicion,BI.monto_adquisicion montoAdquisicion,BI.moneda_adquisicion monedaAdquisicion,
          BI.proveedor_persona_id proveedorPersonaId,BI.proveedor_empresa_id proveedorEmpresaId,
          COALESCE(Emp.nombre_comercial,Emp.razon_social,CONCAT(Per.nombres,N' ',Per.apellido_paterno,CASE WHEN Per.apellido_materno IS NULL THEN N'' ELSE N' '+Per.apellido_materno END)) proveedorNombre,
          BI.observacion,V.placa,V.tipo_vehiculo tipoVehiculo,V.kilometraje_km kilometrajeKm,
          Img.archivo_id archivoPrincipalId,ISNULL(Inc.total,0) incidentesAbiertos,BI.estado
   FROM logistica.BienInventario BI JOIN org.UOT U ON U.uot_id=BI.uot_id AND U.estado=1 JOIN logistica.TipoBien T ON T.tipo_bien_id=BI.tipo_bien_id
   LEFT JOIN logistica.Vehiculo V ON V.vehiculo_id=BI.bien_inventario_id AND V.estado=1
   LEFT JOIN org.Empresa Emp ON Emp.empresa_id=BI.proveedor_empresa_id LEFT JOIN org.Persona Per ON Per.persona_id=BI.proveedor_persona_id
   OUTER APPLY(SELECT TOP(1) X.archivo_id FROM logistica.BienImagen X WHERE X.bien_inventario_id=BI.bien_inventario_id AND X.estado=1 ORDER BY X.es_principal DESC,X.orden,X.bien_imagen_id) Img
   OUTER APPLY(SELECT COUNT(*) total FROM logistica.BienIncidente X WHERE X.bien_inventario_id=BI.bien_inventario_id AND X.estado=1 AND X.estado_incidente IN('ABIERTO','EN_ATENCION')) Inc
   WHERE ((@General=0 AND BI.uot_id=@Uot) OR (@General=1 AND (@Uot IS NULL OR BI.uot_id=@Uot) AND seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,BI.uot_id,'INVENTARIO_LISTAR')=1))
     AND (@nTipoBienId IS NULL OR BI.tipo_bien_id=@nTipoBienId) AND (@cEstado IS NULL OR BI.estado_bien=@cEstado)
     AND (@cBuscar IS NULL OR BI.codigo_patrimonial LIKE N'%'+@cBuscar+N'%' OR BI.nombre LIKE N'%'+@cBuscar+N'%' OR BI.marca LIKE N'%'+@cBuscar+N'%' OR BI.modelo LIKE N'%'+@cBuscar+N'%' OR BI.serie LIKE N'%'+@cBuscar+N'%')
 )
 SELECT *,COUNT_BIG(*) OVER() totalRegistros FROM B ORDER BY uotNombre,nombre,bienInventarioId OFFSET(@nPagina-1)*@nTamano ROWS FETCH NEXT @nTamano ROWS ONLY;
 SELECT @bResultado=1,@cMensaje=N'Inventario consultado.',@cCodigoRespuesta='BIENES_LISTADOS',@nHttpRespuesta=200; RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* ----------------------------------------------------------------------------
   8. Corrección de inventario GENERAL: ya no depende del permiso legacy
      UOT_MODO_GENERAL; cada fila se autoriza por INVENTARIO_LISTAR en su UOT.
   ---------------------------------------------------------------------------- */
CREATE OR ALTER PROCEDURE [logistica].[PA_BienInventario_Sel_ListadoUOT]
    @nUsuarioId BIGINT,
    @nUotId BIGINT = NULL,
    @bModoGeneral BIT = 0,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        @bResultado = 0,
        @cMensaje = N'No se pudo consultar el inventario.';

    IF @bModoGeneral = 0
       AND
       (
           @nUotId IS NULL
           OR [seg].[FN_Usuario_TienePermisoUOT](
               @nUsuarioId,
               @nUotId,
               'INVENTARIO_LISTAR'
           ) = 0
       )
    BEGIN
        SET @cMensaje = N'Seleccione una UOT autorizada.';
        RETURN;
    END;

    SELECT
        B.bien_inventario_id,
        B.uot_id,
        U.codigo AS uot_codigo,
        U.nombre AS uot_nombre,
        B.tipo_bien_id,
        T.codigo AS tipo_codigo,
        T.nombre AS tipo_bien,
        B.codigo_patrimonial,
        B.nombre,
        B.marca,
        B.modelo,
        B.serie,
        B.estado_bien,
        B.fecha_adquisicion,
        B.monto_adquisicion,
        B.moneda_adquisicion,
        B.estado
    FROM [logistica].[BienInventario] B
    INNER JOIN [org].[UOT] U
        ON U.uot_id = B.uot_id
       AND U.estado = 1
    INNER JOIN [logistica].[TipoBien] T
        ON T.tipo_bien_id = B.tipo_bien_id
    WHERE
        (
            (@bModoGeneral = 0 AND B.uot_id = @nUotId)
            OR
            (
                @bModoGeneral = 1
                AND [seg].[FN_Usuario_TienePermisoUOT](
                    @nUsuarioId,
                    B.uot_id,
                    'INVENTARIO_LISTAR'
                ) = 1
            )
        )
    ORDER BY U.nombre, B.nombre, B.bien_inventario_id;

    SELECT
        @bResultado = 1,
        @cMensaje = N'Inventario consultado correctamente.';
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- logistica.PA_BienInventario_Upd_Baja
CREATE OR ALTER PROCEDURE [logistica].[PA_BienInventario_Upd_Baja](@cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY
  SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),@nAud BIGINT,@nTrans BIGINT,@nId BIGINT,@cMotivo NVARCHAR(500),@cAnt VARCHAR(20),@cIdent NVARCHAR(200);
SELECT @bResultado=0,@cMensaje=N'No se pudo dar de baja el bien.';
EXEC seg.PA_Operacion_Ins_IniciarIdempotente @cJson=@cJson,@cCodigoPermiso='INVENTARIO_RETIRAR',@cAmbito='BIEN_BAJA',@nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@nOperacionIdempotenteId=@nOp OUTPUT,@bEsRepetida=@bRep OUTPUT,@cEstadoOperacion=@cEstadoOp OUTPUT,@cIdentificadorResultado=@cIdRes OUTPUT,@cCodigoResultado=@cCodRes OUTPUT,@bResultado=@bIni OUTPUT,@cMensaje=@cMsg OUTPUT;
IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
GOTO __DESCO_Salida;
END;
IF @bRep=1 BEGIN SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
SET @cMensaje=CASE WHEN @cEstadoOp='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.' ELSE N'La solicitud ya se encuentra en proceso.' END;
GOTO __DESCO_Salida;
END;
 SELECT @nId=bienInventarioId,@cMotivo=NULLIF(LTRIM(RTRIM(motivo)),N'') FROM OPENJSON(@cJson,'$.bien') WITH(bienInventarioId BIGINT '$.bienInventarioId',motivo NVARCHAR(500) '$.motivo');
SELECT @cAnt=estado_bien FROM logistica.BienInventario WHERE bien_inventario_id=@nId AND estado=1;
IF @cAnt IS NULL OR @cAnt='BAJA' OR @cMotivo IS NULL BEGIN SET @cMensaje=N'El bien no está disponible para baja o falta indicar el motivo.';
GOTO Fallar;
END;
IF EXISTS(SELECT 1 FROM logistica.RecursoProgramado WHERE bien_inventario_id=@nId AND estado=1 AND estado_proceso IN('PROGRAMADO','EN_EJECUCION')) BEGIN SET @cMensaje=N'El bien tiene una programación pendiente. Cancele o complete esa programación antes de darlo de baja.';
GOTO Fallar;
END;
BEGIN TRY BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;
UPDATE logistica.BienInventario SET estado_bien='BAJA' WHERE bien_inventario_id=@nId;
SET @cIdent=CONVERT(NVARCHAR(200),@nId);
EXEC auditoria.PA_Operacion_Ins_RegistrarCambio @nUsuario,@nSesion,@nDisp,@nModulo,'BAJA','logistica','BienInventario',@cIdent,NULL,NULL,@cMotivo,'estado_bien',@cAnt,'BAJA',@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
/* Confirmar datos e idempotencia juntos. */EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='COMPLETADA',@cEsquemaEntidad='logistica',@cNombreEntidad='BienInventario',@cIdentificadorResultado=@cIdent,@cCodigoResultado='BIEN_BAJA',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado=1;
SET @cMensaje=N'Bien dado de baja correctamente.';
GOTO __DESCO_Salida;
 END TRY BEGIN CATCH
SET @bResultado = 0;
 IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @cMensaje=N'No se pudo dar de baja el bien. Intente nuevamente.';
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'logistica.PA_BienInventario_Upd_Baja',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;
Fallar: IF @nOp IS NOT NULL AND @bResultado=0 EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='FALLIDA',@cEsquemaEntidad=NULL,@cNombreEntidad=NULL,@cIdentificadorResultado=NULL,@cCodigoResultado='NO_PROCESADO',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
 
    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'logistica.PA_BienInventario_Upd_Baja',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

    IF @bResultado = 0 AND @nOp IS NOT NULL AND XACT_STATE() <> -1
    BEGIN
        IF ISNULL(@bRep,0) = 0
        BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                 @nOperacionIdempotenteId = @nOp, @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
            -- No sustituir el motivo funcional por un fallo de registro secundario.
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'logistica.PA_BienInventario_Upd_Baja',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
        END CATCH;
        END
        ELSE
        BEGIN
            SELECT @cMensaje = COALESCE(mensaje_resultado,
                CASE WHEN estado_operacion = 'FALLIDA'
                     THEN N'La solicitud anterior no se completó. Corrija los datos y envíe una nueva solicitud.'
                     ELSE N'La solicitud todavía se está procesando. Consulte el resultado antes de repetirla.' END)
            FROM [auditoria].[OperacionIdempotente]
            WHERE operacion_idempotente_id = @nOp;
        END;
    END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'logistica.PA_BienInventario_Upd_Baja',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'logistica.PA_BienInventario_Upd_Baja',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* ============================================================================
   2. EDITAR BIEN
   - Alineado con ResourceAssetUpdateRequest.
   - Ya no exige estadoBien: el estado se modifica en PA_BienInventario_Ins_CambioEstado.
   ============================================================================ */
CREATE OR ALTER PROCEDURE [logistica].[PA_BienInventario_Upd_Registro]
    @cJson NVARCHAR(MAX),
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60) = NULL OUTPUT,
    @nHttpRespuesta SMALLINT = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SELECT
        @bResultado = 0,
        @cMensaje = N'No se pudo actualizar el bien.',
        @cCodigoRespuesta = 'BIEN_NO_ACTUALIZADO',
        @nHttpRespuesta = 400;

    DECLARE
        @nUsuario BIGINT,
        @nSesion BIGINT,
        @nDisp BIGINT,
        @nEmp BIGINT,
        @nModulo INT,
        @gCorr UNIQUEIDENTIFIER,
        @gSol UNIQUEIDENTIFIER,
        @cIp VARCHAR(64),
        @cEnd NVARCHAR(250),
        @nOp BIGINT,
        @bRep BIT,
        @cEstadoOp VARCHAR(20),
        @cIdRes NVARCHAR(200),
        @cCodRes VARCHAR(40),
        @bIni BIT,
        @cMsg NVARCHAR(300),
        @bFin BIT,
        @cMsgFin NVARCHAR(300),
        @nAud BIGINT,
        @nTrans BIGINT,
        @nId BIGINT,
        @nUotId BIGINT,
        @nTipoBienId SMALLINT,
        @cNombre NVARCHAR(150),
        @cMarca NVARCHAR(80),
        @cModelo NVARCHAR(80),
        @cSerie NVARCHAR(100),
        @dFechaAdquisicion DATE,
        @nMontoAdquisicion DECIMAL(19,4),
        @cMoneda CHAR(3),
        @nProveedorPersonaId BIGINT,
        @nProveedorEmpresaId BIGINT,
        @cObservacion NVARCHAR(500),
        @nTranEntrada INT,
        @bTranAbierta BIT = 0,
        @cIdent NVARCHAR(200);

    EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente]
        @cJson = @cJson,
        @cCodigoPermiso = 'INVENTARIO_EDITAR',
        @cAmbito = 'BIEN_EDITAR_SQL',
        @nUsuarioId = @nUsuario OUTPUT,
        @nSesionUsuarioId = @nSesion OUTPUT,
        @nDispositivoUsuarioId = @nDisp OUTPUT,
        @nEmpleadoId = @nEmp OUTPUT,
        @nModuloId = @nModulo OUTPUT,
        @gCorrelacionId = @gCorr OUTPUT,
        @gSolicitudId = @gSol OUTPUT,
        @cIp = @cIp OUTPUT,
        @cEndpoint = @cEnd OUTPUT,
        @nOperacionIdempotenteId = @nOp OUTPUT,
        @bEsRepetida = @bRep OUTPUT,
        @cEstadoOperacion = @cEstadoOp OUTPUT,
        @cIdentificadorResultado = @cIdRes OUTPUT,
        @cCodigoResultado = @cCodRes OUTPUT,
        @bResultado = @bIni OUTPUT,
        @cMensaje = @cMsg OUTPUT;

    IF ISNULL(@bIni, 0) = 0 AND ISNULL(@bRep, 0) = 0
    BEGIN
        SET @cMensaje = COALESCE(NULLIF(@cMsg, N''), @cMensaje);
        RETURN 1;
    END;

    IF ISNULL(@bRep, 0) = 1
    BEGIN
        IF @cEstadoOp = 'COMPLETADA'
        BEGIN
            SELECT
                @bResultado = 1,
                @cMensaje = N'La solicitud ya fue procesada correctamente.',
                @cCodigoRespuesta = 'BIEN_ACTUALIZADO',
                @nHttpRespuesta = 200;
            RETURN 0;
        END;

        SELECT @cMensaje = COALESCE(
            NULLIF(mensaje_resultado, N''),
            N'La solicitud anterior no se completó o todavía se está procesando.')
        FROM [auditoria].[OperacionIdempotente]
        WHERE operacion_idempotente_id = @nOp;
        SET @nHttpRespuesta = CASE WHEN @cEstadoOp = 'EN_PROCESO' THEN 409 ELSE 400 END;
        RETURN 1;
    END;

    SELECT
        @nId = COALESCE(
            TRY_CONVERT(BIGINT, JSON_VALUE(@cJson, '$.bien.bienInventarioId')),
            TRY_CONVERT(BIGINT, JSON_VALUE(@cJson, '$.bien.assetId'))
        ),
        @nTipoBienId = COALESCE(
            TRY_CONVERT(SMALLINT, JSON_VALUE(@cJson, '$.bien.tipoBienId')),
            TRY_CONVERT(SMALLINT, JSON_VALUE(@cJson, '$.bien.assetTypeId'))
        ),
        @cNombre = NULLIF(LTRIM(RTRIM(COALESCE(
            JSON_VALUE(@cJson, '$.bien.nombre'),
            JSON_VALUE(@cJson, '$.bien.name')
        ))), N''),
        @cMarca = NULLIF(LTRIM(RTRIM(COALESCE(JSON_VALUE(@cJson, '$.bien.marca'), JSON_VALUE(@cJson, '$.bien.brand')))), N''),
        @cModelo = NULLIF(LTRIM(RTRIM(COALESCE(JSON_VALUE(@cJson, '$.bien.modelo'), JSON_VALUE(@cJson, '$.bien.model')))), N''),
        @cSerie = NULLIF(LTRIM(RTRIM(COALESCE(JSON_VALUE(@cJson, '$.bien.serie'), JSON_VALUE(@cJson, '$.bien.serial')))), N''),
        @dFechaAdquisicion = COALESCE(
            TRY_CONVERT(DATE, JSON_VALUE(@cJson, '$.bien.fechaAdquisicion')),
            TRY_CONVERT(DATE, JSON_VALUE(@cJson, '$.bien.acquisitionDate'))
        ),
        @nMontoAdquisicion = COALESCE(
            TRY_CONVERT(DECIMAL(19,4), JSON_VALUE(@cJson, '$.bien.montoAdquisicion')),
            TRY_CONVERT(DECIMAL(19,4), JSON_VALUE(@cJson, '$.bien.acquisitionAmount'))
        ),
        @cMoneda = UPPER(NULLIF(LTRIM(RTRIM(COALESCE(JSON_VALUE(@cJson, '$.bien.moneda'), JSON_VALUE(@cJson, '$.bien.currency')))), '')),
        @nProveedorPersonaId = COALESCE(
            TRY_CONVERT(BIGINT, JSON_VALUE(@cJson, '$.bien.proveedorPersonaId')),
            TRY_CONVERT(BIGINT, JSON_VALUE(@cJson, '$.bien.providerPersonId'))
        ),
        @nProveedorEmpresaId = COALESCE(
            TRY_CONVERT(BIGINT, JSON_VALUE(@cJson, '$.bien.proveedorEmpresaId')),
            TRY_CONVERT(BIGINT, JSON_VALUE(@cJson, '$.bien.providerCompanyId'))
        ),
        @cObservacion = NULLIF(LTRIM(RTRIM(COALESCE(JSON_VALUE(@cJson, '$.bien.observacion'), JSON_VALUE(@cJson, '$.bien.observation')))), N'');

    IF @nMontoAdquisicion IS NOT NULL AND @cMoneda IS NULL
        SET @cMoneda = 'PEN';

    IF @nId IS NULL OR @nTipoBienId IS NULL OR @cNombre IS NULL
    BEGIN
        SET @cMensaje = N'Complete correctamente los datos del bien.';
        GOTO Fallar;
    END;

    SELECT @nUotId = uot_id
    FROM [logistica].[BienInventario]
    WHERE bien_inventario_id = @nId
      AND estado = 1
      AND estado_bien <> 'BAJA';

    IF @nUotId IS NULL
    BEGIN
        SET @cMensaje = N'El bien seleccionado no está disponible.';
        SET @nHttpRespuesta = 404;
        GOTO Fallar;
    END;

    IF [seg].[FN_Usuario_TienePermisoUOT](@nUsuario, @nUotId, 'INVENTARIO_EDITAR') = 0
    BEGIN
        SET @cMensaje = N'No tiene permiso para modificar este bien.';
        SET @nHttpRespuesta = 403;
        GOTO Fallar;
    END;

    IF NOT EXISTS (SELECT 1 FROM [logistica].[TipoBien] WHERE tipo_bien_id = @nTipoBienId AND estado = 1)
    BEGIN
        SET @cMensaje = N'El tipo de bien seleccionado no está disponible.';
        GOTO Fallar;
    END;

    IF @nProveedorPersonaId IS NOT NULL AND @nProveedorEmpresaId IS NOT NULL
    BEGIN
        SET @cMensaje = N'Seleccione solo una persona o una empresa como proveedor.';
        GOTO Fallar;
    END;

    IF @nProveedorPersonaId IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM [org].[Persona] WHERE persona_id = @nProveedorPersonaId AND estado = 1)
    BEGIN
        SET @cMensaje = N'El proveedor seleccionado no está disponible.';
        GOTO Fallar;
    END;

    IF @nProveedorEmpresaId IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM [org].[Empresa] WHERE empresa_id = @nProveedorEmpresaId AND estado = 1)
    BEGIN
        SET @cMensaje = N'El proveedor seleccionado no está disponible.';
        GOTO Fallar;
    END;

    IF @cMoneda IS NOT NULL AND (@cMoneda NOT LIKE '[A-Z][A-Z][A-Z]' OR LEN(@cMoneda) <> 3)
    BEGIN
        SET @cMensaje = N'La moneda seleccionada no es válida.';
        GOTO Fallar;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM [logistica].[RecursoProgramado]
        WHERE bien_inventario_id = @nId
          AND estado = 1
          AND estado_proceso = 'EN_EJECUCION'
    )
    BEGIN
        SET @cMensaje = N'El bien está asignado actualmente y no puede editarse desde esta opción.';
        SET @nHttpRespuesta = 409;
        GOTO Fallar;
    END;

    SET @nTranEntrada = @@TRANCOUNT;

    BEGIN TRY
        IF @nTranEntrada = 0
            BEGIN TRANSACTION;
        ELSE
            SAVE TRANSACTION BIEN_UPDATE_SAVE;
        SET @bTranAbierta = 1;

        UPDATE [logistica].[BienInventario]
        SET
            tipo_bien_id = @nTipoBienId,
            nombre = @cNombre,
            marca = @cMarca,
            modelo = @cModelo,
            serie = @cSerie,
            fecha_adquisicion = @dFechaAdquisicion,
            monto_adquisicion = @nMontoAdquisicion,
            moneda_adquisicion = @cMoneda,
            proveedor_persona_id = @nProveedorPersonaId,
            proveedor_empresa_id = @nProveedorEmpresaId,
            observacion = @cObservacion
        WHERE bien_inventario_id = @nId
          AND estado = 1
          AND estado_bien <> 'BAJA';

        IF @@ROWCOUNT = 0
            THROW 51004, 'DESCO_BIEN_NO_DISPONIBLE', 1;

        SET @cIdent = CONVERT(NVARCHAR(200), @nId);

        EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio]
            @nUsuario, @nSesion, @nDisp, @nModulo,
            'EDITAR', 'logistica', 'BienInventario', @cIdent,
            NULL, NULL, NULL, NULL, NULL, NULL,
            @cIp, @gCorr, @gSol, @cEnd,
            @nAud OUTPUT, @nTrans OUTPUT;

        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
            @nOperacionIdempotenteId = @nOp,
            @cEstadoOperacion = 'COMPLETADA',
            @cEsquemaEntidad = 'logistica',
            @cNombreEntidad = 'BienInventario',
            @cIdentificadorResultado = @cIdent,
            @cCodigoResultado = 'BIEN_ACTUALIZADO',
            @bResultado = @bFin OUTPUT,
            @cMensaje = @cMsgFin OUTPUT;

        IF ISNULL(@bFin, 0) = 0
            THROW 51003, 'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;

        IF @nTranEntrada = 0
            COMMIT TRANSACTION;
        SET @bTranAbierta = 0;

        SELECT
            @bResultado = 1,
            @cMensaje = N'Bien actualizado correctamente.',
            @cCodigoRespuesta = 'BIEN_ACTUALIZADO',
            @nHttpRespuesta = 200;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF @bTranAbierta = 1 AND XACT_STATE() <> 0
        BEGIN
            IF @nTranEntrada = 0
                ROLLBACK TRANSACTION;
            ELSE IF XACT_STATE() = 1
                ROLLBACK TRANSACTION BIEN_UPDATE_SAVE;
        END;
        SET @bTranAbierta = 0;
        SET @bResultado = 0;
        SET @cMensaje = N'No se pudo actualizar el bien. Intente nuevamente.';
        GOTO Fallar;
    END CATCH;

Fallar:
    IF @nOp IS NOT NULL AND ISNULL(@bRep, 0) = 0 AND XACT_STATE() <> -1
    BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                @nOperacionIdempotenteId = @nOp,
                @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
        END CATCH;
    END;

    IF @cCodigoRespuesta IS NULL SET @cCodigoRespuesta = 'BIEN_NO_ACTUALIZADO';
    IF @nHttpRespuesta IS NULL SET @nHttpRespuesta = 400;
    SET @bResultado = 0;
    RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* --------------------------------------------------------------------------
   10. Registrar entrega técnica + salida de stock + Kardex CONSUMO
   -------------------------------------------------------------------------- */
CREATE OR ALTER PROCEDURE logistica.PA_EntregaTecnica_Ins_Registrar
 @nUsuarioId BIGINT,@nUotId BIGINT,@nAlmacenId BIGINT,@nEmpleadoId BIGINT,
 @gClaveIdempotencia UNIQUEIDENTIFIER,@cDetalleJson NVARCHAR(MAX),@cMotivo NVARCHAR(300),@cObservacion NVARCHAR(500)=NULL,
 @nEntregaTecnicaId BIGINT OUTPUT,@nMovimientoInventarioId BIGINT OUTPUT,
 @bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,@cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 SELECT @nEntregaTecnicaId=NULL,@nMovimientoInventarioId=NULL,@bResultado=0,@cMensaje=N'No se pudo registrar la entrega técnica.',
        @cCodigoRespuesta='ENTREGA_TECNICA_NO_REGISTRADA',@nHttpRespuesta=400;
 SET @cMotivo=NULLIF(LTRIM(RTRIM(@cMotivo)),N''); SET @cObservacion=NULLIF(LTRIM(RTRIM(@cObservacion)),N'');
 IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotId,'VENTAS_ENTREGA_TECNICA')=0
 BEGIN SET @cMensaje=N'No tiene permiso para registrar entregas técnicas.'; SET @cCodigoRespuesta='NO_AUTORIZADO'; SET @nHttpRespuesta=403; RETURN 1; END;
 IF @gClaveIdempotencia IS NULL OR @cMotivo IS NULL OR ISJSON(@cDetalleJson)<>1 OR NOT EXISTS(SELECT 1 FROM OPENJSON(@cDetalleJson))
 BEGIN SET @cMensaje=N'La entrega debe incluir empleado, motivo y productos válidos.'; RETURN 1; END;
 IF NOT EXISTS(SELECT 1 FROM logistica.AlmacenUOT WHERE almacen_id=@nAlmacenId AND uot_id=@nUotId AND estado=1 AND fecha_hasta IS NULL AND permite_salida=1)
 BEGIN SET @cMensaje=N'La UOT no puede retirar productos del almacén seleccionado.'; RETURN 1; END;
 IF NOT EXISTS(SELECT 1 FROM org.Empleado E JOIN org.EmpleadoUOT EU ON EU.empleado_id=E.empleado_id AND EU.uot_id=@nUotId AND EU.estado=1 AND EU.fecha_desde<=CONVERT(DATE,SYSUTCDATETIME()) AND (EU.fecha_hasta IS NULL OR EU.fecha_hasta>=CONVERT(DATE,SYSUTCDATETIME())) WHERE E.empleado_id=@nEmpleadoId AND E.estado=1 AND (E.fecha_cese IS NULL OR E.fecha_cese>=CONVERT(DATE,SYSUTCDATETIME())))
 BEGIN SET @cMensaje=N'El empleado seleccionado no está habilitado en la UOT.'; RETURN 1; END;

 SELECT @nEntregaTecnicaId=entrega_tecnica_id,@nMovimientoInventarioId=movimiento_inventario_id
 FROM logistica.EntregaTecnica WHERE clave_idempotencia=@gClaveIdempotencia;
 IF @nEntregaTecnicaId IS NOT NULL
 BEGIN SELECT @bResultado=1,@cMensaje=N'La entrega técnica ya fue registrada correctamente.',@cCodigoRespuesta='ENTREGA_TECNICA_REGISTRADA',@nHttpRespuesta=200; RETURN 0; END;

 BEGIN TRY
   SET TRANSACTION ISOLATION LEVEL SERIALIZABLE; BEGIN TRAN;
   DECLARE @Detalle TABLE(producto_id BIGINT PRIMARY KEY,cantidad DECIMAL(19,3),costo DECIMAL(19,4) NULL,moneda CHAR(3) NULL);
   ;WITH Raw AS(
      SELECT productoId,cantidad FROM OPENJSON(@cDetalleJson) WITH(productoId BIGINT '$.productoId',cantidad DECIMAL(19,3) '$.cantidad')
   ), Agrupado AS(
      SELECT productoId,SUM(cantidad) cantidad FROM Raw GROUP BY productoId
   )
   INSERT @Detalle(producto_id,cantidad,costo,moneda)
   SELECT D.productoId,D.cantidad,PP.precio_inicial,PP.moneda
   FROM Agrupado D
   LEFT JOIN logistica.Producto P ON P.producto_id=D.productoId AND P.estado=1
   OUTER APPLY(SELECT TOP(1) X.precio_inicial,X.moneda FROM logistica.ProductoPrecio X
               WHERE X.producto_id=D.productoId AND X.estado=1 AND X.fecha_hasta IS NULL AND (X.uot_id=@nUotId OR X.uot_id IS NULL)
               ORDER BY CASE WHEN X.uot_id=@nUotId THEN 0 ELSE 1 END,X.version DESC,X.producto_precio_id DESC) PP
   WHERE P.producto_id IS NOT NULL;

   IF EXISTS(SELECT 1 FROM OPENJSON(@cDetalleJson) WITH(productoId BIGINT '$.productoId',cantidad DECIMAL(19,3) '$.cantidad') WHERE productoId IS NULL OR cantidad IS NULL OR cantidad<=0)
      OR (SELECT COUNT(DISTINCT productoId) FROM OPENJSON(@cDetalleJson) WITH(productoId BIGINT '$.productoId'))<>(SELECT COUNT(*) FROM @Detalle)
      THROW 51080,N'ENTREGA_TECNICA_DETALLE_INVALIDO',1;

   IF EXISTS(SELECT 1 FROM @Detalle D LEFT JOIN logistica.AlmacenProductoStock S WITH(UPDLOCK,HOLDLOCK)
             ON S.almacen_id=@nAlmacenId AND S.producto_id=D.producto_id WHERE ISNULL(S.stock_disponible,0)<D.cantidad)
      THROW 51081,N'ENTREGA_TECNICA_STOCK_INSUFICIENTE',1;

   INSERT logistica.EntregaTecnica(uot_id,almacen_id,empleado_id,usuario_entrega_id,clave_idempotencia,motivo,observacion,estado)
   VALUES(@nUotId,@nAlmacenId,@nEmpleadoId,@nUsuarioId,@gClaveIdempotencia,@cMotivo,@cObservacion,1);
   SET @nEntregaTecnicaId=SCOPE_IDENTITY();

   INSERT logistica.EntregaTecnicaDetalle(entrega_tecnica_id,producto_id,cantidad,estado)
   SELECT @nEntregaTecnicaId,producto_id,cantidad,1 FROM @Detalle;

   INSERT logistica.MovimientoInventario(almacen_id,uot_id,tipo_movimiento,naturaleza,documento_referencia,clave_idempotencia,usuario_id,observacion,estado)
   VALUES(@nAlmacenId,@nUotId,'CONSUMO','S',CONCAT(N'ENTREGA-TECNICA-',@nEntregaTecnicaId),@gClaveIdempotencia,@nUsuarioId,
          CONCAT(N'Entrega técnica a empleado ',@nEmpleadoId,N'. ',COALESCE(@cObservacion,N'')),1);
   SET @nMovimientoInventarioId=SCOPE_IDENTITY();

   INSERT logistica.DetalleMovimientoInventario(movimiento_inventario_id,producto_id,cantidad,costo_unitario,moneda)
   SELECT @nMovimientoInventarioId,producto_id,cantidad,costo,moneda FROM @Detalle;

   UPDATE S SET stock_actual=S.stock_actual-D.cantidad,fecha_actualizacion=SYSUTCDATETIME()
   FROM logistica.AlmacenProductoStock S JOIN @Detalle D ON D.producto_id=S.producto_id
   WHERE S.almacen_id=@nAlmacenId;

   UPDATE logistica.EntregaTecnica SET movimiento_inventario_id=@nMovimientoInventarioId
   WHERE entrega_tecnica_id=@nEntregaTecnicaId;

   COMMIT;
   SELECT @bResultado=1,@cMensaje=N'Entrega técnica registrada correctamente.',@cCodigoRespuesta='ENTREGA_TECNICA_REGISTRADA',@nHttpRespuesta=201;
   RETURN 0;
 END TRY
 BEGIN CATCH
   IF XACT_STATE()<>0 ROLLBACK;
   SELECT @nEntregaTecnicaId=NULL,@nMovimientoInventarioId=NULL;
   SET @cMensaje=CASE
      WHEN ERROR_MESSAGE() LIKE '%ENTREGA_TECNICA_STOCK_INSUFICIENTE%' THEN N'No hay stock suficiente para completar la entrega técnica.'
      WHEN ERROR_MESSAGE() LIKE '%ENTREGA_TECNICA_DETALLE_INVALIDO%' THEN N'Uno o más productos de la entrega no son válidos.'
      WHEN ERROR_NUMBER() IN(2601,2627) THEN N'La entrega ya fue procesada o contiene datos duplicados.'
      ELSE N'No se pudo registrar la entrega técnica.' END;
   RETURN 1;
 END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* --------------------------------------------------------------------------
   9. Selector de empleados para entrega técnica
   -------------------------------------------------------------------------- */
CREATE OR ALTER PROCEDURE logistica.PA_EntregaTecnica_Sel_Empleados
 @nUsuarioId BIGINT,@nUotId BIGINT,
 @bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,@cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON;
 SELECT @bResultado=0,@cMensaje=N'No se pudieron consultar los empleados.',@cCodigoRespuesta='EMPLEADOS_NO_LISTADOS',@nHttpRespuesta=400;
 IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotId,'VENTAS_ENTREGA_TECNICA')=0
 BEGIN SET @cMensaje=N'No tiene permiso para registrar entregas técnicas.'; SET @cCodigoRespuesta='NO_AUTORIZADO'; SET @nHttpRespuesta=403; RETURN 1; END;
 SELECT E.empleado_id empleadoId,COALESCE(EU.codigo_empleado,E.codigo_empleado) codigoEmpleado,
        LTRIM(RTRIM(CONCAT(P.nombres,N' ',P.apellido_paterno,N' ',COALESCE(P.apellido_materno,N'')))) empleado
 FROM org.Empleado E
 JOIN org.Persona P ON P.persona_id=E.empleado_id AND P.estado=1
 JOIN org.EmpleadoUOT EU ON EU.empleado_id=E.empleado_id AND EU.uot_id=@nUotId AND EU.estado=1
   AND EU.fecha_desde<=CONVERT(DATE,SYSUTCDATETIME()) AND (EU.fecha_hasta IS NULL OR EU.fecha_hasta>=CONVERT(DATE,SYSUTCDATETIME()))
 WHERE E.estado=1 AND (E.fecha_cese IS NULL OR E.fecha_cese>=CONVERT(DATE,SYSUTCDATETIME()))
 ORDER BY empleado;
 SELECT @bResultado=1,@cMensaje=N'Empleados consultados.',@cCodigoRespuesta='EMPLEADOS_LISTADOS',@nHttpRespuesta=200;
 RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE logistica.PA_EntregaTecnica_Sel_Listado
 @nUsuarioId BIGINT,@nUotId BIGINT,@nEmpleadoId BIGINT=NULL,
 @bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,@cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON;
 SELECT @bResultado=0,@cMensaje=N'No se pudieron consultar las entregas técnicas.',@cCodigoRespuesta='ENTREGAS_TECNICAS_NO_LISTADAS',@nHttpRespuesta=400;
 IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotId,'VENTAS_ENTREGA_TECNICA')=0
 BEGIN SET @cMensaje=N'No tiene permiso para consultar entregas técnicas.'; SET @cCodigoRespuesta='NO_AUTORIZADO'; SET @nHttpRespuesta=403; RETURN 1; END;
 SELECT ET.entrega_tecnica_id entregaTecnicaId,ET.uot_id uotId,U.nombre uotNombre,ET.almacen_id almacenId,A.nombre almacen,
        ET.empleado_id empleadoId,LTRIM(RTRIM(CONCAT(P.nombres,N' ',P.apellido_paterno,N' ',COALESCE(P.apellido_materno,N'')))) empleado,
        ET.fecha_hora fechaHora,ET.motivo,ET.observacion,ET.movimiento_inventario_id movimientoInventarioId,
        ET.usuario_entrega_id usuarioEntregaId,US.nombre_usuario usuarioEntrega
 FROM logistica.EntregaTecnica ET
 JOIN org.UOT U ON U.uot_id=ET.uot_id
 JOIN logistica.Almacen A ON A.almacen_id=ET.almacen_id
 JOIN org.Persona P ON P.persona_id=ET.empleado_id
 JOIN seg.Usuario US ON US.usuario_id=ET.usuario_entrega_id
 WHERE ET.uot_id=@nUotId AND ET.estado=1 AND (@nEmpleadoId IS NULL OR ET.empleado_id=@nEmpleadoId)
 ORDER BY ET.fecha_hora DESC,ET.entrega_tecnica_id DESC;
 SELECT @bResultado=1,@cMensaje=N'Entregas técnicas consultadas.',@cCodigoRespuesta='ENTREGAS_TECNICAS_LISTADAS',@nHttpRespuesta=200;
 RETURN 0;
END;

