GO

CREATE OR ALTER PROCEDURE logistica.PA_MovimientoInventario_Ins_Registrar
 @nUsuarioId BIGINT,@nUotId BIGINT,@nAlmacenId BIGINT,@cTipo VARCHAR(25),@cNaturaleza CHAR(1),@gClaveIdempotencia UNIQUEIDENTIFIER,
 @cDetalleJson NVARCHAR(MAX),@nProveedorPersonaId BIGINT=NULL,@nProveedorEmpresaId BIGINT=NULL,@cDocumento NVARCHAR(120)=NULL,@cObservacion NVARCHAR(500)=NULL,
 @nMovimientoId BIGINT OUTPUT,@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON; SET @nMovimientoId=NULL; SET @bResultado=0; SET @cMensaje=N'No se pudo registrar el movimiento de inventario.';
 IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotId,'ALMACENES_MOVIMIENTO')=0 BEGIN SET @cMensaje=N'No tiene permiso para registrar movimientos de inventario.'; RETURN; END;
 IF NOT EXISTS(SELECT 1 FROM logistica.AlmacenUOT AU WHERE AU.almacen_id=@nAlmacenId AND AU.uot_id=@nUotId AND AU.estado=1 AND AU.fecha_hasta IS NULL AND ((@cNaturaleza='E' AND AU.permite_entrada=1) OR (@cNaturaleza='S' AND AU.permite_salida=1))) BEGIN SET @cMensaje=N'La UOT no puede operar sobre el almacén seleccionado.'; RETURN; END;
 SET @cTipo=UPPER(NULLIF(LTRIM(RTRIM(@cTipo)),'')); SET @cNaturaleza=UPPER(@cNaturaleza);
 IF @cNaturaleza NOT IN('E','S') OR @cTipo NOT IN('COMPRA','DONACION','DEVOLUCION','VENTA','CONSUMO','TRANSFERENCIA','AJUSTE','MERMA','OTRO') BEGIN SET @cMensaje=N'El tipo de movimiento no es válido.'; RETURN; END;
 IF @gClaveIdempotencia IS NULL BEGIN SET @cMensaje=N'La clave de idempotencia es obligatoria.'; RETURN; END;
 SELECT @nMovimientoId=movimiento_inventario_id FROM logistica.MovimientoInventario WHERE clave_idempotencia=@gClaveIdempotencia;
 IF @nMovimientoId IS NOT NULL BEGIN SET @bResultado=1; SET @cMensaje=N'El movimiento ya fue registrado correctamente.'; RETURN; END;
 IF ISJSON(@cDetalleJson)<>1 OR NOT EXISTS(SELECT 1 FROM OPENJSON(@cDetalleJson)) BEGIN SET @cMensaje=N'El movimiento debe incluir al menos un producto.'; RETURN; END;
 IF EXISTS(SELECT 1 FROM OPENJSON(@cDetalleJson) WITH(productoId BIGINT '$.productoId',cantidad DECIMAL(19,3) '$.cantidad') D WHERE D.productoId IS NULL OR D.cantidad IS NULL OR D.cantidad<=0) BEGIN SET @cMensaje=N'El detalle del movimiento contiene datos inválidos.'; RETURN; END;
 IF EXISTS(
     SELECT 1
     FROM OPENJSON(@cDetalleJson)
     WITH(fechaVencimiento DATE '$.fechaVencimiento') D
     WHERE D.fechaVencimiento IS NOT NULL
       AND D.fechaVencimiento < CONVERT(date, SYSDATETIME())
 ) BEGIN SET @cMensaje=N'La fecha de vencimiento no puede ser anterior a hoy.'; RETURN; END;
 BEGIN TRY
  SET TRANSACTION ISOLATION LEVEL SERIALIZABLE; BEGIN TRAN;
  IF @cNaturaleza='S' AND EXISTS(SELECT 1 FROM OPENJSON(@cDetalleJson) WITH(productoId BIGINT '$.productoId',cantidad DECIMAL(19,3) '$.cantidad') D LEFT JOIN logistica.AlmacenProductoStock S WITH(UPDLOCK,HOLDLOCK) ON S.almacen_id=@nAlmacenId AND S.producto_id=D.productoId WHERE ISNULL(S.stock_disponible,0)<D.cantidad) THROW 51050,N'STOCK_INSUFICIENTE',1;
  INSERT logistica.MovimientoInventario(almacen_id,uot_id,tipo_movimiento,naturaleza,proveedor_persona_id,proveedor_empresa_id,documento_referencia,clave_idempotencia,usuario_id,observacion,estado)
  VALUES(@nAlmacenId,@nUotId,UPPER(@cTipo),UPPER(@cNaturaleza),@nProveedorPersonaId,@nProveedorEmpresaId,@cDocumento,@gClaveIdempotencia,@nUsuarioId,@cObservacion,1);
  SET @nMovimientoId=SCOPE_IDENTITY();
  INSERT logistica.DetalleMovimientoInventario(movimiento_inventario_id,producto_id,cantidad,costo_unitario,moneda,lote,fecha_vencimiento)
  SELECT @nMovimientoId,productoId,cantidad,costoUnitario,UPPER(moneda),lote,fechaVencimiento
  FROM OPENJSON(@cDetalleJson) WITH(productoId BIGINT '$.productoId',cantidad DECIMAL(19,3) '$.cantidad',costoUnitario DECIMAL(19,4) '$.costoUnitario',moneda CHAR(3) '$.moneda',lote VARCHAR(80) '$.lote',fechaVencimiento DATE '$.fechaVencimiento');

  MERGE logistica.AlmacenProductoStock WITH(HOLDLOCK) AS T
  USING(SELECT producto_id,SUM(cantidad) cantidad FROM logistica.DetalleMovimientoInventario WHERE movimiento_inventario_id=@nMovimientoId GROUP BY producto_id) S
  ON T.almacen_id=@nAlmacenId AND T.producto_id=S.producto_id
  WHEN NOT MATCHED AND @cNaturaleza='E' THEN INSERT(almacen_id,producto_id,stock_actual,stock_reservado,stock_minimo,fecha_actualizacion) VALUES(@nAlmacenId,S.producto_id,S.cantidad,0,0,SYSUTCDATETIME())
  WHEN MATCHED THEN UPDATE SET stock_actual=T.stock_actual+CASE WHEN @cNaturaleza='E' THEN S.cantidad ELSE -S.cantidad END,fecha_actualizacion=SYSUTCDATETIME();

  IF EXISTS(SELECT 1 FROM logistica.AlmacenProductoStock WHERE almacen_id=@nAlmacenId AND (stock_actual<0 OR stock_reservado>stock_actual)) THROW 51050,N'STOCK_INSUFICIENTE',1;
  COMMIT; SET @bResultado=1; SET @cMensaje=N'Movimiento de inventario registrado correctamente.';
 END TRY
 BEGIN CATCH
  IF XACT_STATE()<>0 ROLLBACK; SET @nMovimientoId=NULL;
  SET @cMensaje=CASE WHEN ERROR_MESSAGE() LIKE '%STOCK_INSUFICIENTE%' THEN N'No hay stock suficiente para completar el movimiento.' ELSE N'No se pudo registrar el movimiento de inventario.' END;
 END CATCH;
END;


GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE logistica.PA_Producto_Del_Registro
    @nUsuarioId BIGINT,
    @nUotId BIGINT,
    @nProductoId BIGINT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60) = NULL OUTPUT,
    @nHttpRespuesta SMALLINT = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SELECT @bResultado = 0,
           @cMensaje = N'No se pudo desactivar el producto.',
           @cCodigoRespuesta = 'PRODUCTO_NO_DESACTIVADO',
           @nHttpRespuesta = 400;

    IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId, @nUotId, 'PRODUCTOS_EDITAR') = 0
    BEGIN
        SELECT @cMensaje = N'No tiene permiso para desactivar productos en esta UOT.',
               @cCodigoRespuesta = 'NO_AUTORIZADO', @nHttpRespuesta = 403;
        RETURN 1;
    END;

    IF NOT EXISTS (SELECT 1 FROM logistica.Producto WHERE producto_id = @nProductoId)
    BEGIN
        SELECT @cMensaje = N'El producto no está disponible.',
               @cCodigoRespuesta = 'PRODUCTO_NO_DISPONIBLE', @nHttpRespuesta = 404;
        RETURN 1;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM logistica.AlmacenProductoStock
        WHERE producto_id = @nProductoId
          AND (stock_actual > 0 OR stock_reservado > 0)
    )
    BEGIN
        SELECT @cMensaje = N'No se puede desactivar un producto que todavía tiene stock o reservas.',
               @cCodigoRespuesta = 'PRODUCTO_CON_STOCK', @nHttpRespuesta = 409;
        RETURN 1;
    END;

    UPDATE logistica.Producto
       SET estado = 0
     WHERE producto_id = @nProductoId
       AND estado = 1;

    SELECT @bResultado = 1,
           @cMensaje = CASE WHEN @@ROWCOUNT = 0 THEN N'El producto ya se encontraba desactivado.' ELSE N'Producto desactivado correctamente.' END,
           @cCodigoRespuesta = 'PRODUCTO_DESACTIVADO',
           @nHttpRespuesta = 200;
    RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* --------------------------------------------------------------------------
   1. Producto
   -------------------------------------------------------------------------- */
CREATE OR ALTER PROCEDURE [logistica].[PA_Producto_Ins_Registro]
    @nUsuarioId BIGINT,
    @nUotId BIGINT,
    @cCodigo VARCHAR(50),
    @cNombre NVARCHAR(180),
    @cDescripcion NVARCHAR(700) = NULL,
    @cUnidad VARCHAR(20),
    @cCategoria NVARCHAR(100) = NULL,
    @nProductoId BIGINT OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SELECT
        @nProductoId = NULL,
        @bResultado = 0,
        @cMensaje = N'No se pudo registrar el producto.';

    SET @cCodigo = UPPER(NULLIF(LTRIM(RTRIM(@cCodigo)), ''));
    SET @cNombre = NULLIF(LTRIM(RTRIM(@cNombre)), N'');
    SET @cDescripcion = NULLIF(LTRIM(RTRIM(@cDescripcion)), N'');
    SET @cUnidad = UPPER(NULLIF(LTRIM(RTRIM(@cUnidad)), ''));
    SET @cCategoria = UPPER(NULLIF(LTRIM(RTRIM(@cCategoria)), N''));

    IF @nUsuarioId IS NULL OR @nUotId IS NULL
    BEGIN
        SET @cMensaje = N'Seleccione una UOT válida.';
        RETURN 1;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [org].[UOT]
        WHERE uot_id = @nUotId
          AND estado = 1
    )
    BEGIN
        SET @cMensaje = N'La UOT seleccionada no está disponible.';
        RETURN 1;
    END;

    IF [seg].[FN_Usuario_TienePermisoUOT]
       (@nUsuarioId, @nUotId, 'PRODUCTOS_CREAR') = 0
    BEGIN
        SET @cMensaje = N'No tiene permiso para registrar productos en esta UOT.';
        RETURN 1;
    END;

    IF @cCodigo IS NULL OR @cNombre IS NULL OR @cUnidad IS NULL
    BEGIN
        SET @cMensaje = N'Complete correctamente los datos del producto.';
        RETURN 1;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [config].[CatalogoRecursoValor]
        WHERE catalogo = 'UNIDAD_MEDIDA'
          AND codigo = @cUnidad
          AND estado = 1
    )
    BEGIN
        SET @cMensaje = N'La unidad de medida seleccionada no está disponible.';
        RETURN 1;
    END;

    IF @cCategoria IS NOT NULL
       AND NOT EXISTS
       (
           SELECT 1
           FROM [config].[CatalogoRecursoValor]
           WHERE catalogo = 'CATEGORIA_PRODUCTO'
             AND CONVERT(NVARCHAR(100), codigo) = @cCategoria
             AND estado = 1
       )
    BEGIN
        SET @cMensaje = N'La categoría seleccionada no está disponible.';
        RETURN 1;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM [logistica].[Producto]
        WHERE codigo = @cCodigo
    )
    BEGIN
        SET @cMensaje = N'El código del producto ya está registrado.';
        RETURN 1;
    END;

    BEGIN TRY
        INSERT INTO [logistica].[Producto]
        (
            codigo,
            nombre,
            descripcion,
            unidad_medida,
            categoria,
            estado
        )
        VALUES
        (
            @cCodigo,
            @cNombre,
            @cDescripcion,
            @cUnidad,
            @cCategoria,
            1
        );

        SET @nProductoId = CONVERT(BIGINT, SCOPE_IDENTITY());

        IF @nProductoId IS NULL
        BEGIN
            SET @cMensaje = N'No se pudo obtener el producto registrado.';
            RETURN 1;
        END;

        SELECT
            @bResultado = 1,
            @cMensaje = N'Producto registrado correctamente.';

        RETURN 0;
    END TRY
    BEGIN CATCH
        SET @nProductoId = NULL;
        SET @bResultado = 0;

        IF ERROR_NUMBER() IN (2601, 2627)
            SET @cMensaje = N'El código del producto ya está registrado.';
        ELSE
            SET @cMensaje = N'No se pudo registrar el producto. Revise los datos e intente nuevamente.';

        RETURN 1;
    END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* --------------------------------------------------------------------------
   4. Producto: alta comercial atómica (producto + precio inicial + venta)
      Se crea un PA nuevo para no romper el contrato legacy de PA_Producto_Ins_Registro.
   -------------------------------------------------------------------------- */
CREATE OR ALTER PROCEDURE logistica.PA_Producto_Ins_RegistroComercial
    @nUsuarioId BIGINT,
    @nUotId BIGINT,
    @cCodigo VARCHAR(50),
    @cNombre NVARCHAR(180),
    @cDescripcion NVARCHAR(700)=NULL,
    @cUnidad VARCHAR(20),
    @cCategoria NVARCHAR(100)=NULL,
    @nPrecioInicial DECIMAL(19,4),
    @nPrecioVenta DECIMAL(19,4),
    @cMoneda CHAR(3)='PEN',
    @gClaveIdempotencia UNIQUEIDENTIFIER,
    @nProductoId BIGINT OUTPUT,
    @nProductoPrecioId BIGINT OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    SELECT @nProductoId=NULL,@nProductoPrecioId=NULL,@bResultado=0,
           @cMensaje=N'No se pudo registrar el producto.',@cCodigoRespuesta='PRODUCTO_NO_CREADO',@nHttpRespuesta=400;

    SELECT @cCodigo=UPPER(NULLIF(LTRIM(RTRIM(@cCodigo)),'')),
           @cNombre=NULLIF(LTRIM(RTRIM(@cNombre)),N''),
           @cDescripcion=NULLIF(LTRIM(RTRIM(@cDescripcion)),N''),
           @cUnidad=UPPER(NULLIF(LTRIM(RTRIM(@cUnidad)),'')),
           @cCategoria=UPPER(NULLIF(LTRIM(RTRIM(@cCategoria)),N'')),
           @cMoneda=UPPER(NULLIF(LTRIM(RTRIM(@cMoneda)),''));

    IF @nUsuarioId IS NULL OR @nUotId IS NULL OR @gClaveIdempotencia IS NULL
    BEGIN SET @cMensaje=N'Complete correctamente los datos del producto.'; RETURN 1; END;

    SELECT @nProductoId=P.producto_id
    FROM logistica.Producto P
    WHERE P.clave_idempotencia=@gClaveIdempotencia;

    IF @nProductoId IS NOT NULL
    BEGIN
        SELECT TOP(1) @nProductoPrecioId=producto_precio_id
        FROM logistica.ProductoPrecio
        WHERE producto_id=@nProductoId AND uot_id=@nUotId
        ORDER BY version DESC,producto_precio_id DESC;
        SELECT @bResultado=1,@cMensaje=N'El producto ya fue registrado correctamente.',
               @cCodigoRespuesta='PRODUCTO_CREADO',@nHttpRespuesta=200;
        RETURN 0;
    END;

    IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotId,'PRODUCTOS_CREAR')=0
       OR seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotId,'PRODUCTOS_PRECIO')=0
    BEGIN SET @cMensaje=N'No tiene permiso para registrar productos y precios en esta UOT.'; SET @cCodigoRespuesta='NO_AUTORIZADO'; SET @nHttpRespuesta=403; RETURN 1; END;

    IF NOT EXISTS(SELECT 1 FROM org.UOT WHERE uot_id=@nUotId AND estado=1)
    BEGIN SET @cMensaje=N'La UOT seleccionada no está disponible.'; RETURN 1; END;
    IF @cCodigo IS NULL OR @cNombre IS NULL OR @cUnidad IS NULL
    BEGIN SET @cMensaje=N'Complete correctamente los datos del producto.'; RETURN 1; END;
    IF @nPrecioInicial IS NULL OR @nPrecioInicial<0 OR @nPrecioVenta IS NULL OR @nPrecioVenta<=0
    BEGIN SET @cMensaje=N'Ingrese precios válidos para el producto.'; RETURN 1; END;
    IF NOT EXISTS(SELECT 1 FROM config.CatalogoRecursoValor WHERE catalogo='UNIDAD_MEDIDA' AND codigo=@cUnidad AND estado=1)
    BEGIN SET @cMensaje=N'La unidad de medida seleccionada no está disponible.'; RETURN 1; END;
    IF @cCategoria IS NOT NULL AND NOT EXISTS(SELECT 1 FROM config.CatalogoRecursoValor WHERE catalogo='CATEGORIA_PRODUCTO' AND codigo=@cCategoria AND estado=1)
    BEGIN SET @cMensaje=N'La categoría seleccionada no está disponible.'; RETURN 1; END;
    IF NOT EXISTS(SELECT 1 FROM config.CatalogoRecursoValor WHERE catalogo='MONEDA' AND codigo=@cMoneda AND estado=1)
    BEGIN SET @cMensaje=N'La moneda seleccionada no está disponible.'; RETURN 1; END;

    BEGIN TRY
        SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
        BEGIN TRAN;

        IF EXISTS(SELECT 1 FROM logistica.Producto WITH(UPDLOCK,HOLDLOCK) WHERE codigo=@cCodigo)
            THROW 51070,N'PRODUCTO_CODIGO_DUPLICADO',1;

        INSERT logistica.Producto(codigo,nombre,descripcion,unidad_medida,categoria,estado,clave_idempotencia)
        VALUES(@cCodigo,@cNombre,@cDescripcion,@cUnidad,@cCategoria,1,@gClaveIdempotencia);
        SET @nProductoId=CONVERT(BIGINT,SCOPE_IDENTITY());

        INSERT logistica.ProductoPrecio(producto_id,uot_id,precio_inicial,precio_venta,moneda,version,fecha_desde,fecha_hasta,estado,usuario_id,clave_idempotencia)
        VALUES(@nProductoId,@nUotId,@nPrecioInicial,@nPrecioVenta,@cMoneda,1,SYSUTCDATETIME(),NULL,1,@nUsuarioId,@gClaveIdempotencia);
        SET @nProductoPrecioId=CONVERT(BIGINT,SCOPE_IDENTITY());

        COMMIT;
        SELECT @bResultado=1,@cMensaje=N'Producto y precio registrados correctamente.',
               @cCodigoRespuesta='PRODUCTO_CREADO',@nHttpRespuesta=201;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK;
        SELECT @nProductoId=NULL,@nProductoPrecioId=NULL,@bResultado=0;
        IF ERROR_MESSAGE() LIKE '%PRODUCTO_CODIGO_DUPLICADO%'
        BEGIN SET @cMensaje=N'El código del producto ya está registrado.'; SET @cCodigoRespuesta='PRODUCTO_CODIGO_DUPLICADO'; SET @nHttpRespuesta=409; END
        ELSE IF ERROR_NUMBER() IN(2601,2627)
        BEGIN SET @cMensaje=N'El producto o la solicitud ya están registrados.'; SET @cCodigoRespuesta='PRODUCTO_DUPLICADO'; SET @nHttpRespuesta=409; END
        ELSE
        BEGIN SET @cMensaje=N'No se pudo registrar el producto. Revise los datos e intente nuevamente.'; END;
        RETURN 1;
    END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* --------------------------------------------------------------------------
   6. Lecturas de producto con ambos precios
   -------------------------------------------------------------------------- */
CREATE OR ALTER PROCEDURE logistica.PA_Producto_Sel_DetalleUOT
 @nUsuarioId BIGINT,@nSesionUsuarioId BIGINT,@nUotId BIGINT,@nProductoId BIGINT,
 @bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,@cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SELECT @bResultado=0,@cMensaje=N'No se pudo consultar el producto.',@cCodigoRespuesta='PRODUCTO_NO_DISPONIBLE',@nHttpRespuesta=404;
 DECLARE @Uot BIGINT=@nUotId,@General BIT,@Ok BIT,@Msg NVARCHAR(300);
 EXEC seg.PA_UOT_Sel_ResolverContextoSesion @nUsuarioId,@nSesionUsuarioId,@Uot,'PRODUCTOS_VER',1,@Uot OUTPUT,@General OUTPUT,@Ok OUTPUT,@Msg OUTPUT;
 IF @Ok=0 BEGIN SET @cMensaje=@Msg; SET @cCodigoRespuesta='NO_AUTORIZADO'; SET @nHttpRespuesta=403; RETURN 1; END;
 SELECT P.producto_id productoId,@Uot uotId,U.codigo uotCodigo,U.nombre uotNombre,P.codigo,P.nombre,P.descripcion,
        P.unidad_medida unidadMedidaCodigo,COALESCE(UM.nombre,P.unidad_medida) unidadMedidaNombre,
        CONVERT(VARCHAR(100),P.categoria) categoriaCodigo,COALESCE(CAT.nombre,CONVERT(NVARCHAR(100),P.categoria)) categoriaNombre,
        P.requiere_lote requiereLote,P.controla_vencimiento controlaVencimiento,
        Pr.precio_inicial precioInicial,Pr.precio_venta precioVenta,Pr.moneda,Pr.producto_precio_id productoPrecioId,Pr.version precioVersion,
        Img.archivo_id archivoPrincipalId,P.estado
 FROM logistica.Producto P JOIN org.UOT U ON U.uot_id=@Uot AND U.estado=1
 LEFT JOIN config.CatalogoRecursoValor UM ON UM.catalogo='UNIDAD_MEDIDA' AND UM.codigo=UPPER(P.unidad_medida) AND UM.estado=1
 LEFT JOIN config.CatalogoRecursoValor CAT ON CAT.catalogo='CATEGORIA_PRODUCTO' AND CAT.codigo=UPPER(CONVERT(VARCHAR(100),P.categoria)) AND CAT.estado=1
 OUTER APPLY(SELECT TOP(1) PP.* FROM logistica.ProductoPrecio PP WHERE PP.producto_id=P.producto_id AND PP.estado=1 AND PP.fecha_hasta IS NULL AND (PP.uot_id=@Uot OR PP.uot_id IS NULL) ORDER BY CASE WHEN PP.uot_id=@Uot THEN 0 ELSE 1 END,PP.version DESC,PP.producto_precio_id DESC) Pr
 OUTER APPLY(SELECT TOP(1) PI.archivo_id FROM logistica.ProductoImagen PI JOIN archivo.Archivo A ON A.archivo_id=PI.archivo_id AND A.estado=1 AND A.uot_id=@Uot WHERE PI.producto_id=P.producto_id AND PI.estado=1 ORDER BY PI.es_principal DESC,PI.orden,PI.producto_imagen_id) Img
 WHERE P.producto_id=@nProductoId;
 IF @@ROWCOUNT=0 RETURN 1;
 SELECT @bResultado=1,@cMensaje=N'Producto consultado.',@cCodigoRespuesta='PRODUCTO_OBTENIDO',@nHttpRespuesta=200; RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE logistica.PA_Producto_Sel_ListadoPaginado
 @nUsuarioId BIGINT,@nSesionUsuarioId BIGINT,@nUotId BIGINT=NULL,@cBuscar NVARCHAR(180)=NULL,@cCategoria VARCHAR(40)=NULL,@bEstado BIT=NULL,@nPagina INT=1,@nTamano INT=20,
 @bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,@cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SELECT @bResultado=0,@cMensaje=N'No se pudieron consultar los productos.',@cCodigoRespuesta='PRODUCTOS_NO_LISTADOS',@nHttpRespuesta=400;
 SELECT @cBuscar=NULLIF(LTRIM(RTRIM(@cBuscar)),N''),@cCategoria=UPPER(NULLIF(LTRIM(RTRIM(@cCategoria)),''));
 SET @nPagina=CASE WHEN ISNULL(@nPagina,0)<1 THEN 1 ELSE @nPagina END; SET @nTamano=CASE WHEN ISNULL(@nTamano,0)<1 THEN 20 WHEN @nTamano>100 THEN 100 ELSE @nTamano END;
 DECLARE @Uot BIGINT=@nUotId,@General BIT,@Ok BIT,@Msg NVARCHAR(300);
 EXEC seg.PA_UOT_Sel_ResolverContextoSesion @nUsuarioId,@nSesionUsuarioId,@Uot,'PRODUCTOS_LISTAR',0,@Uot OUTPUT,@General OUTPUT,@Ok OUTPUT,@Msg OUTPUT;
 IF @Ok=0 BEGIN SET @cMensaje=@Msg; RETURN 1; END;
 ;WITH Uots AS(
   SELECT U.uot_id,U.codigo,U.nombre FROM org.UOT U WHERE U.estado=1 AND ((@General=0 AND U.uot_id=@Uot) OR (@General=1 AND (@Uot IS NULL OR U.uot_id=@Uot) AND seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,U.uot_id,'PRODUCTOS_LISTAR')=1))
 ), Base AS(
   SELECT P.producto_id productoId,U.uot_id uotId,U.codigo uotCodigo,U.nombre uotNombre,P.codigo,P.nombre,P.descripcion,
          P.unidad_medida unidadMedidaCodigo,COALESCE(UM.nombre,P.unidad_medida) unidadMedidaNombre,
          CONVERT(VARCHAR(100),P.categoria) categoriaCodigo,COALESCE(CAT.nombre,CONVERT(NVARCHAR(100),P.categoria)) categoriaNombre,
          P.requiere_lote requiereLote,P.controla_vencimiento controlaVencimiento,
          Pr.precio_inicial precioInicial,Pr.precio_venta precioVenta,Pr.moneda,Pr.producto_precio_id productoPrecioId,Pr.version precioVersion,
          Img.archivo_id archivoPrincipalId,P.estado
   FROM logistica.Producto P CROSS JOIN Uots U
   LEFT JOIN config.CatalogoRecursoValor UM ON UM.catalogo='UNIDAD_MEDIDA' AND UM.codigo=UPPER(P.unidad_medida) AND UM.estado=1
   LEFT JOIN config.CatalogoRecursoValor CAT ON CAT.catalogo='CATEGORIA_PRODUCTO' AND CAT.codigo=UPPER(CONVERT(VARCHAR(100),P.categoria)) AND CAT.estado=1
   OUTER APPLY(SELECT TOP(1) PP.* FROM logistica.ProductoPrecio PP WHERE PP.producto_id=P.producto_id AND PP.estado=1 AND PP.fecha_hasta IS NULL AND (PP.uot_id=U.uot_id OR PP.uot_id IS NULL) ORDER BY CASE WHEN PP.uot_id=U.uot_id THEN 0 ELSE 1 END,PP.version DESC,PP.producto_precio_id DESC) Pr
   OUTER APPLY(SELECT TOP(1) PI.archivo_id FROM logistica.ProductoImagen PI JOIN archivo.Archivo A ON A.archivo_id=PI.archivo_id AND A.estado=1 AND A.uot_id=U.uot_id WHERE PI.producto_id=P.producto_id AND PI.estado=1 ORDER BY PI.es_principal DESC,PI.orden,PI.producto_imagen_id) Img
   WHERE (@bEstado IS NULL OR P.estado=@bEstado) AND (@cCategoria IS NULL OR UPPER(CONVERT(VARCHAR(100),P.categoria))=@cCategoria)
     AND (@cBuscar IS NULL OR P.codigo LIKE N'%'+@cBuscar+N'%' OR P.nombre LIKE N'%'+@cBuscar+N'%' OR P.descripcion LIKE N'%'+@cBuscar+N'%')
 )
 SELECT *,COUNT_BIG(*) OVER() totalRegistros FROM Base ORDER BY uotNombre,nombre,productoId OFFSET(@nPagina-1)*@nTamano ROWS FETCH NEXT @nTamano ROWS ONLY;
 SELECT @bResultado=1,@cMensaje=N'Productos consultados.',@cCodigoRespuesta='PRODUCTOS_LISTADOS',@nHttpRespuesta=200; RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE logistica.PA_Producto_Upd_Estado
    @nUsuarioId BIGINT,
    @nUotId BIGINT,
    @nProductoId BIGINT,
    @bEstado BIT,
    @cMotivo NVARCHAR(500),
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    SELECT @bResultado=0,@cMensaje=N'No se pudo cambiar el estado del producto.',@cCodigoRespuesta='PRODUCTO_ESTADO_NO_ACTUALIZADO',@nHttpRespuesta=400;
    SET @cMotivo=NULLIF(LTRIM(RTRIM(@cMotivo)),N'');
    IF @nUsuarioId IS NULL OR @nUotId IS NULL OR @nProductoId IS NULL OR @bEstado IS NULL OR @cMotivo IS NULL
    BEGIN SET @cMensaje=N'Indique el motivo del cambio de estado.'; RETURN 1; END;
    IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotId,'PRODUCTOS_DESACTIVAR')=0
    BEGIN SET @cMensaje=N'No tiene permiso para cambiar el estado de productos en esta UOT.'; SET @cCodigoRespuesta='NO_AUTORIZADO'; SET @nHttpRespuesta=403; RETURN 1; END;
    IF NOT EXISTS(SELECT 1 FROM logistica.Producto WHERE producto_id=@nProductoId)
    BEGIN SET @cMensaje=N'El producto no está disponible.'; SET @cCodigoRespuesta='PRODUCTO_NO_DISPONIBLE'; SET @nHttpRespuesta=404; RETURN 1; END;
    IF @bEstado=0 AND EXISTS(SELECT 1 FROM logistica.AlmacenProductoStock WHERE producto_id=@nProductoId AND (stock_actual>0 OR stock_reservado>0))
    BEGIN SET @cMensaje=N'No puede desactivar un producto que mantiene stock actual o reservado.'; SET @cCodigoRespuesta='PRODUCTO_CON_STOCK'; SET @nHttpRespuesta=409; RETURN 1; END;

    UPDATE logistica.Producto SET estado=@bEstado WHERE producto_id=@nProductoId;
    SELECT @bResultado=1,
           @cMensaje=CASE WHEN @bEstado=1 THEN N'Producto reactivado correctamente.' ELSE N'Producto desactivado correctamente.' END,
           @cCodigoRespuesta=CASE WHEN @bEstado=1 THEN 'PRODUCTO_ACTIVADO' ELSE 'PRODUCTO_DESACTIVADO' END,
           @nHttpRespuesta=200;
    RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE logistica.PA_Producto_Upd_Reactivar
    @nUsuarioId BIGINT,
    @nUotId BIGINT,
    @nProductoId BIGINT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60) = NULL OUTPUT,
    @nHttpRespuesta SMALLINT = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SELECT @bResultado = 0,
           @cMensaje = N'No se pudo reactivar el producto.',
           @cCodigoRespuesta = 'PRODUCTO_NO_REACTIVADO',
           @nHttpRespuesta = 400;

    IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId, @nUotId, 'PRODUCTOS_EDITAR') = 0
    BEGIN
        SELECT @cMensaje = N'No tiene permiso para reactivar productos en esta UOT.',
               @cCodigoRespuesta = 'NO_AUTORIZADO', @nHttpRespuesta = 403;
        RETURN 1;
    END;

    IF NOT EXISTS (SELECT 1 FROM logistica.Producto WHERE producto_id = @nProductoId)
    BEGIN
        SELECT @cMensaje = N'El producto no está disponible.',
               @cCodigoRespuesta = 'PRODUCTO_NO_DISPONIBLE', @nHttpRespuesta = 404;
        RETURN 1;
    END;

    UPDATE logistica.Producto
       SET estado = 1
     WHERE producto_id = @nProductoId
       AND estado = 0;

    SELECT @bResultado = 1,
           @cMensaje = CASE WHEN @@ROWCOUNT = 0 THEN N'El producto ya se encontraba activo.' ELSE N'Producto reactivado correctamente.' END,
           @cCodigoRespuesta = 'PRODUCTO_REACTIVADO',
           @nHttpRespuesta = 200;
    RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE logistica.PA_Producto_Upd_Registro
    @nUsuarioId BIGINT,
    @nUotId BIGINT,
    @nProductoId BIGINT,
    @cNombre NVARCHAR(180),
    @cDescripcion NVARCHAR(700) = NULL,
    @cUnidad VARCHAR(20),
    @cCategoria VARCHAR(40) = NULL,
    @bRequiereLote BIT,
    @bControlaVencimiento BIT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60) = NULL OUTPUT,
    @nHttpRespuesta SMALLINT = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SELECT
        @bResultado = 0,
        @cMensaje = N'No se pudo actualizar el producto.',
        @cCodigoRespuesta = 'PRODUCTO_NO_ACTUALIZADO',
        @nHttpRespuesta = 400;

    SELECT
        @cNombre = NULLIF(LTRIM(RTRIM(@cNombre)), N''),
        @cDescripcion = NULLIF(LTRIM(RTRIM(@cDescripcion)), N''),
        @cUnidad = UPPER(NULLIF(LTRIM(RTRIM(@cUnidad)), '')),
        @cCategoria = UPPER(NULLIF(LTRIM(RTRIM(@cCategoria)), ''));

    IF @nUsuarioId IS NULL OR @nUotId IS NULL OR @nProductoId IS NULL
       OR @cNombre IS NULL OR @cUnidad IS NULL
    BEGIN
        SET @cMensaje = N'Complete correctamente los datos del producto.';
        RETURN 1;
    END;

    IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId, @nUotId, 'PRODUCTOS_EDITAR') = 0
    BEGIN
        SELECT @cMensaje = N'No tiene permiso para editar productos en esta UOT.',
               @cCodigoRespuesta = 'NO_AUTORIZADO', @nHttpRespuesta = 403;
        RETURN 1;
    END;

    IF NOT EXISTS (SELECT 1 FROM logistica.Producto WHERE producto_id = @nProductoId AND estado = 1)
    BEGIN
        SELECT @cMensaje = N'El producto no está disponible.',
               @cCodigoRespuesta = 'PRODUCTO_NO_DISPONIBLE', @nHttpRespuesta = 404;
        RETURN 1;
    END;

    IF NOT EXISTS
    (
        SELECT 1 FROM config.CatalogoRecursoValor
        WHERE catalogo = 'UNIDAD_MEDIDA' AND codigo = @cUnidad AND estado = 1
    )
    BEGIN
        SET @cMensaje = N'La unidad de medida seleccionada no está disponible.';
        RETURN 1;
    END;

    IF @cCategoria IS NOT NULL AND NOT EXISTS
    (
        SELECT 1 FROM config.CatalogoRecursoValor
        WHERE catalogo = 'CATEGORIA_PRODUCTO' AND codigo = @cCategoria AND estado = 1
    )
    BEGIN
        SET @cMensaje = N'La categoría seleccionada no está disponible.';
        RETURN 1;
    END;

    BEGIN TRY
        UPDATE logistica.Producto
           SET nombre = @cNombre,
               descripcion = @cDescripcion,
               unidad_medida = @cUnidad,
               categoria = @cCategoria,
               requiere_lote = @bRequiereLote,
               controla_vencimiento = @bControlaVencimiento
         WHERE producto_id = @nProductoId
           AND estado = 1;

        IF @@ROWCOUNT = 0
        BEGIN
            SELECT @cMensaje = N'El producto no está disponible.',
                   @cCodigoRespuesta = 'PRODUCTO_NO_DISPONIBLE', @nHttpRespuesta = 404;
            RETURN 1;
        END;

        SELECT @bResultado = 1,
               @cMensaje = N'Producto actualizado correctamente.',
               @cCodigoRespuesta = 'PRODUCTO_ACTUALIZADO',
               @nHttpRespuesta = 200;
        RETURN 0;
    END TRY
    BEGIN CATCH
        SET @cMensaje = N'No se pudo actualizar el producto.';
        RETURN 1;
    END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* Reactivar copia ambos precios, nunca modifica la fila histórica. */
CREATE OR ALTER PROCEDURE logistica.PA_ProductoPrecio_Ins_ReactivarVersion
    @nUsuarioId BIGINT,@nUotId BIGINT,@nProductoId BIGINT,@nPrecioOrigenId BIGINT,@gClaveIdempotencia UNIQUEIDENTIFIER,
    @nProductoPrecioId BIGINT OUTPUT,@nVersionNueva INT OUTPUT,@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 SELECT @nProductoPrecioId=NULL,@nVersionNueva=NULL,@bResultado=0,@cMensaje=N'No se pudo reactivar el precio.',@cCodigoRespuesta='PRECIO_NO_REACTIVADO',@nHttpRespuesta=400;
 IF @nUotId IS NULL OR @nProductoId IS NULL OR @nPrecioOrigenId IS NULL OR @gClaveIdempotencia IS NULL BEGIN SET @cMensaje=N'Complete correctamente los datos del precio.'; RETURN 1; END;
 IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotId,'PRODUCTOS_PRECIO')=0 OR seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotId,'PRODUCTOS_PRECIO_HISTORIAL')=0 BEGIN SET @cMensaje=N'No tiene permiso para reactivar precios históricos.'; SET @cCodigoRespuesta='NO_AUTORIZADO'; SET @nHttpRespuesta=403; RETURN 1; END;
 SELECT @nProductoPrecioId=producto_precio_id,@nVersionNueva=version FROM logistica.ProductoPrecio WHERE clave_idempotencia=@gClaveIdempotencia;
 IF @nProductoPrecioId IS NOT NULL BEGIN SELECT @bResultado=1,@cMensaje=N'El precio ya fue reactivado.',@cCodigoRespuesta='PRECIO_REACTIVADO',@nHttpRespuesta=200; RETURN 0; END;
 DECLARE @nPrecioInicial DECIMAL(19,4),@nPrecioVenta DECIMAL(19,4),@cMoneda CHAR(3),@bOrigenVigente BIT;
 SELECT @nPrecioInicial=precio_inicial,@nPrecioVenta=precio_venta,@cMoneda=moneda,@bOrigenVigente=CONVERT(BIT,CASE WHEN estado=1 AND fecha_hasta IS NULL THEN 1 ELSE 0 END)
 FROM logistica.ProductoPrecio WHERE producto_precio_id=@nPrecioOrigenId AND producto_id=@nProductoId AND uot_id=@nUotId;
 IF @nPrecioVenta IS NULL BEGIN SET @cMensaje=N'La versión de precio seleccionada no está disponible.'; SET @cCodigoRespuesta='PRECIO_ORIGEN_NO_DISPONIBLE'; SET @nHttpRespuesta=404; RETURN 1; END;
 IF @bOrigenVigente=1 BEGIN SET @cMensaje=N'La versión seleccionada ya es el precio vigente.'; SET @cCodigoRespuesta='PRECIO_YA_VIGENTE'; SET @nHttpRespuesta=409; RETURN 1; END;
 BEGIN TRY
   BEGIN TRAN;
   UPDATE logistica.ProductoPrecio SET estado=0,fecha_hasta=COALESCE(fecha_hasta,SYSUTCDATETIME()) WHERE producto_id=@nProductoId AND uot_id=@nUotId AND estado=1 AND fecha_hasta IS NULL;
   SELECT @nVersionNueva=ISNULL(MAX(version),0)+1 FROM logistica.ProductoPrecio WITH(UPDLOCK,HOLDLOCK) WHERE producto_id=@nProductoId AND uot_id=@nUotId;
   INSERT logistica.ProductoPrecio(producto_id,uot_id,precio_inicial,precio_venta,moneda,version,fecha_desde,fecha_hasta,estado,usuario_id,producto_precio_origen_id,clave_idempotencia)
   VALUES(@nProductoId,@nUotId,@nPrecioInicial,@nPrecioVenta,@cMoneda,@nVersionNueva,SYSUTCDATETIME(),NULL,1,@nUsuarioId,@nPrecioOrigenId,@gClaveIdempotencia);
   SET @nProductoPrecioId=SCOPE_IDENTITY();
   COMMIT;
   SELECT @bResultado=1,@cMensaje=N'Precio reactivado como nueva versión vigente.',@cCodigoRespuesta='PRECIO_REACTIVADO',@nHttpRespuesta=201; RETURN 0;
 END TRY BEGIN CATCH
   IF XACT_STATE()<>0 ROLLBACK;
   SET @nProductoPrecioId=NULL; SET @nVersionNueva=NULL; SET @cMensaje=N'No se pudo reactivar el precio.'; RETURN 1;
 END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* --------------------------------------------------------------------------
   3. Versión de precio
   -------------------------------------------------------------------------- */
CREATE OR ALTER PROCEDURE [logistica].[PA_ProductoPrecio_Ins_Version]
    @nUsuarioId BIGINT,
    @nUotIdContexto BIGINT,
    @nProductoId BIGINT,
    @nUotPrecioId BIGINT = NULL,
    @nPrecio DECIMAL(19,4),
    @cMoneda CHAR(3) = 'PEN',
    @nProductoPrecioId BIGINT OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60) = NULL OUTPUT,
    @nHttpRespuesta SMALLINT = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SELECT
        @nProductoPrecioId = NULL,
        @bResultado = 0,
        @cMensaje = N'No se pudo registrar el precio.',
        @cCodigoRespuesta = 'PRECIO_NO_REGISTRADO',
        @nHttpRespuesta = 400;

    SET @cMoneda = UPPER(NULLIF(LTRIM(RTRIM(@cMoneda)), ''));
    IF @cMoneda IS NULL SET @cMoneda = 'PEN';

    IF @nUotIdContexto IS NULL
    BEGIN
        SET @cMensaje = N'Seleccione una UOT.';
        RETURN 1;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [org].[UOT]
        WHERE uot_id = @nUotIdContexto
          AND estado = 1
    )
    BEGIN
        SET @cMensaje = N'La UOT seleccionada no está disponible.';
        RETURN 1;
    END;

    IF @nUotPrecioId IS NOT NULL
       AND @nUotPrecioId <> @nUotIdContexto
    BEGIN
        SET @cMensaje = N'El precio debe pertenecer a la UOT seleccionada.';
        RETURN 1;
    END;

    SET @nUotPrecioId = @nUotIdContexto;

    IF [seg].[FN_Usuario_TienePermisoUOT]
       (@nUsuarioId, @nUotIdContexto, 'PRODUCTOS_PRECIO') = 0
    BEGIN
        SET @cMensaje = N'No tiene permiso para modificar precios en esta UOT.';
        RETURN 1;
    END;

    IF @nPrecio IS NULL OR @nPrecio <= 0
    BEGIN
        SET @cMensaje = N'Ingrese un precio válido.';
        RETURN 1;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [logistica].[Producto]
        WHERE producto_id = @nProductoId
          AND estado = 1
    )
    BEGIN
        SET @cMensaje = N'El producto no está disponible.';
        RETURN 1;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [config].[CatalogoRecursoValor]
        WHERE catalogo = 'MONEDA'
          AND codigo = @cMoneda
          AND estado = 1
    )
    BEGIN
        SET @cMensaje = N'La moneda seleccionada no está disponible.';
        RETURN 1;
    END;

    BEGIN TRY
        BEGIN TRANSACTION;

        /* Serializa la numeración por producto/UOT. */
        DECLARE @nBloqueoPrecioId BIGINT;

        SELECT TOP (1)
            @nBloqueoPrecioId = producto_precio_id
        FROM [logistica].[ProductoPrecio] WITH (UPDLOCK, HOLDLOCK)
        WHERE producto_id = @nProductoId
          AND uot_id = @nUotPrecioId
        ORDER BY producto_precio_id DESC;

        UPDATE [logistica].[ProductoPrecio]
        SET
            estado = 0,
            fecha_hasta = COALESCE(fecha_hasta, SYSUTCDATETIME())
        WHERE producto_id = @nProductoId
          AND uot_id = @nUotPrecioId
          AND estado = 1
          AND fecha_hasta IS NULL;

        DECLARE @nVersion INT;

        SELECT @nVersion = ISNULL(MAX(version), 0) + 1
        FROM [logistica].[ProductoPrecio]
        WHERE producto_id = @nProductoId
          AND uot_id = @nUotPrecioId;

        INSERT INTO [logistica].[ProductoPrecio]
        (
            producto_id,
            uot_id,
            precio_venta,
            moneda,
            version,
            fecha_desde,
            estado,
            usuario_id
        )
        VALUES
        (
            @nProductoId,
            @nUotPrecioId,
            @nPrecio,
            @cMoneda,
            @nVersion,
            SYSUTCDATETIME(),
            1,
            @nUsuarioId
        );

        SET @nProductoPrecioId = CONVERT(BIGINT, SCOPE_IDENTITY());

        COMMIT TRANSACTION;

        SELECT
            @bResultado = 1,
            @cMensaje = N'Precio registrado correctamente.',
            @cCodigoRespuesta = 'PRECIO_REGISTRADO',
            @nHttpRespuesta = 201;

        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        SELECT
            @nProductoPrecioId = NULL,
            @bResultado = 0,
            @cMensaje = N'No se pudo registrar el precio. Revise los datos e intente nuevamente.',
            @cCodigoRespuesta = 'PRECIO_NO_REGISTRADO',
            @nHttpRespuesta = 400;

        RETURN 1;
    END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* --------------------------------------------------------------------------
   5. Nueva versión comercial de precio
      PA nuevo para mantener intacto el contrato legacy PA_ProductoPrecio_Ins_Version.
   -------------------------------------------------------------------------- */
CREATE OR ALTER PROCEDURE logistica.PA_ProductoPrecio_Ins_VersionComercial
    @nUsuarioId BIGINT,
    @nUotIdContexto BIGINT,
    @nProductoId BIGINT,
    @nUotPrecioId BIGINT,
    @nPrecioInicial DECIMAL(19,4),
    @nPrecioVenta DECIMAL(19,4),
    @cMoneda CHAR(3)='PEN',
    @gClaveIdempotencia UNIQUEIDENTIFIER,
    @nProductoPrecioId BIGINT OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    SELECT @nProductoPrecioId=NULL,@bResultado=0,@cMensaje=N'No se pudo registrar el precio.',
           @cCodigoRespuesta='PRECIO_NO_REGISTRADO',@nHttpRespuesta=400;
    SET @cMoneda=UPPER(NULLIF(LTRIM(RTRIM(@cMoneda)),''));

    IF @nUotIdContexto IS NULL OR @nProductoId IS NULL OR @nUotPrecioId IS NULL OR @gClaveIdempotencia IS NULL
    BEGIN SET @cMensaje=N'Complete correctamente los datos del precio.'; RETURN 1; END;
    IF @nUotPrecioId<>@nUotIdContexto
    BEGIN SET @cMensaje=N'El precio debe pertenecer a la UOT seleccionada.'; RETURN 1; END;
    IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotIdContexto,'PRODUCTOS_PRECIO')=0
    BEGIN SET @cMensaje=N'No tiene permiso para modificar precios en esta UOT.'; SET @cCodigoRespuesta='NO_AUTORIZADO'; SET @nHttpRespuesta=403; RETURN 1; END;
    IF @nPrecioInicial IS NULL OR @nPrecioInicial<0 OR @nPrecioVenta IS NULL OR @nPrecioVenta<=0
    BEGIN SET @cMensaje=N'Ingrese precios válidos.'; RETURN 1; END;
    IF NOT EXISTS(SELECT 1 FROM logistica.Producto WHERE producto_id=@nProductoId AND estado=1)
    BEGIN SET @cMensaje=N'El producto no está disponible.'; SET @cCodigoRespuesta='PRODUCTO_NO_DISPONIBLE'; SET @nHttpRespuesta=404; RETURN 1; END;
    IF NOT EXISTS(SELECT 1 FROM config.CatalogoRecursoValor WHERE catalogo='MONEDA' AND codigo=@cMoneda AND estado=1)
    BEGIN SET @cMensaje=N'La moneda seleccionada no está disponible.'; RETURN 1; END;

    SELECT @nProductoPrecioId=producto_precio_id
    FROM logistica.ProductoPrecio WHERE clave_idempotencia=@gClaveIdempotencia;
    IF @nProductoPrecioId IS NOT NULL
    BEGIN SELECT @bResultado=1,@cMensaje=N'El precio ya fue registrado correctamente.',@cCodigoRespuesta='PRECIO_REGISTRADO',@nHttpRespuesta=200; RETURN 0; END;

    BEGIN TRY
        SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
        BEGIN TRAN;
        UPDATE logistica.ProductoPrecio
        SET estado=0,fecha_hasta=COALESCE(fecha_hasta,SYSUTCDATETIME())
        WHERE producto_id=@nProductoId AND uot_id=@nUotPrecioId AND estado=1 AND fecha_hasta IS NULL;

        DECLARE @Version INT;
        SELECT @Version=ISNULL(MAX(version),0)+1
        FROM logistica.ProductoPrecio WITH(UPDLOCK,HOLDLOCK)
        WHERE producto_id=@nProductoId AND uot_id=@nUotPrecioId;

        INSERT logistica.ProductoPrecio(producto_id,uot_id,precio_inicial,precio_venta,moneda,version,fecha_desde,fecha_hasta,estado,usuario_id,clave_idempotencia)
        VALUES(@nProductoId,@nUotPrecioId,@nPrecioInicial,@nPrecioVenta,@cMoneda,@Version,SYSUTCDATETIME(),NULL,1,@nUsuarioId,@gClaveIdempotencia);
        SET @nProductoPrecioId=CONVERT(BIGINT,SCOPE_IDENTITY());
        COMMIT;
        SELECT @bResultado=1,@cMensaje=N'Precio registrado correctamente.',@cCodigoRespuesta='PRECIO_REGISTRADO',@nHttpRespuesta=201;
        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK;
        SET @nProductoPrecioId=NULL;
        IF ERROR_NUMBER() IN(2601,2627)
        BEGIN SET @cMensaje=N'La versión de precio ya fue registrada.'; SET @cCodigoRespuesta='PRECIO_DUPLICADO'; SET @nHttpRespuesta=409; END
        ELSE SET @cMensaje=N'No se pudo registrar el precio. Revise los datos e intente nuevamente.';
        RETURN 1;
    END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE logistica.PA_ProductoPrecio_Sel_Historial
    @nUsuarioId BIGINT,@nUotId BIGINT,@nProductoId BIGINT,
    @bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,@cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SELECT @bResultado=0,@cMensaje=N'No se pudo consultar el historial de precios.',@cCodigoRespuesta='HISTORIAL_PRECIOS_NO_LISTADO',@nHttpRespuesta=400;
 IF @nUotId IS NULL OR @nProductoId IS NULL BEGIN SET @cMensaje=N'Seleccione una UOT y un producto.'; RETURN 1; END;
 IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotId,'PRODUCTOS_PRECIO_HISTORIAL')=0 BEGIN SET @cMensaje=N'No tiene permiso para consultar el historial de precios.'; SET @cCodigoRespuesta='NO_AUTORIZADO'; SET @nHttpRespuesta=403; RETURN 1; END;
 IF NOT EXISTS(SELECT 1 FROM logistica.Producto WHERE producto_id=@nProductoId) BEGIN SET @cMensaje=N'El producto no está disponible.'; SET @cCodigoRespuesta='PRODUCTO_NO_DISPONIBLE'; SET @nHttpRespuesta=404; RETURN 1; END;
 SELECT PP.producto_precio_id productoPrecioId,PP.producto_id productoId,P.codigo productoCodigo,P.nombre producto,
        PP.uot_id uotId,U.codigo uotCodigo,U.nombre uotNombre,PP.precio_inicial precioInicial,PP.precio_venta precioVenta,PP.moneda,PP.version,
        PP.fecha_desde fechaDesde,PP.fecha_hasta fechaHasta,CONVERT(BIT,CASE WHEN PP.estado=1 AND PP.fecha_hasta IS NULL THEN 1 ELSE 0 END) vigente,
        PP.usuario_id usuarioId,US.nombre_usuario nombreUsuario,PP.producto_precio_origen_id precioOrigenId,PO.version precioOrigenVersion
 FROM logistica.ProductoPrecio PP JOIN logistica.Producto P ON P.producto_id=PP.producto_id
 JOIN org.UOT U ON U.uot_id=PP.uot_id LEFT JOIN seg.Usuario US ON US.usuario_id=PP.usuario_id
 LEFT JOIN logistica.ProductoPrecio PO ON PO.producto_precio_id=PP.producto_precio_origen_id
 WHERE PP.producto_id=@nProductoId AND PP.uot_id=@nUotId
 ORDER BY PP.version DESC,PP.fecha_desde DESC,PP.producto_precio_id DESC;
 SELECT @bResultado=1,@cMensaje=N'Historial de precios consultado.',@cCodigoRespuesta='HISTORIAL_PRECIOS_LISTADO',@nHttpRespuesta=200; RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [logistica].[PA_Recurso_Sel_CodigoSugerido]
    @nUsuarioId BIGINT,
    @nSesionUsuarioId BIGINT,
    @nUotId BIGINT,
    @cTipo VARCHAR(20),
    @cCodigo VARCHAR(60) OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60) = NULL OUTPUT,
    @nHttpRespuesta SMALLINT = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        @cCodigo = NULL,
        @bResultado = 0,
        @cMensaje = N'No se pudo generar el código.',
        @cCodigoRespuesta = 'CODIGO_NO_GENERADO',
        @nHttpRespuesta = 400;

    SET @cTipo = UPPER(NULLIF(LTRIM(RTRIM(@cTipo)), ''));

    IF @cTipo NOT IN ('BIEN', 'PRODUCTO', 'ALMACEN', 'SUMINISTRO')
    BEGIN
        SET @cMensaje = N'El tipo de recurso no es válido.';
        RETURN 1;
    END;

    DECLARE
        @cPermiso VARCHAR(40) =
            CASE @cTipo
                WHEN 'BIEN' THEN 'INVENTARIO_CREAR'
                WHEN 'SUMINISTRO' THEN 'INVENTARIO_CREAR'
                WHEN 'PRODUCTO' THEN 'PRODUCTOS_CREAR'
                WHEN 'ALMACEN' THEN 'ALMACENES_CREAR'
            END,
        @nUotResuelta BIGINT = @nUotId,
        @bModoGeneral BIT,
        @bOk BIT,
        @cMsg NVARCHAR(300);

    EXEC [seg].[PA_UOT_Sel_ResolverContextoSesion]
        @nUsuarioId = @nUsuarioId,
        @nSesionUsuarioId = @nSesionUsuarioId,
        @nUotSolicitada = @nUotResuelta,
        @cCodigoPermiso = @cPermiso,
        @bRequiereUot = 1,
        @nUotId = @nUotResuelta OUTPUT,
        @bModoGeneral = @bModoGeneral OUTPUT,
        @bResultado = @bOk OUTPUT,
        @cMensaje = @cMsg OUTPUT;

    IF ISNULL(@bOk, 0) = 0
    BEGIN
        SET @cMensaje = COALESCE(NULLIF(@cMsg, N''), @cMensaje);
        RETURN 1;
    END;

    DECLARE
        @cUot VARCHAR(12),
        @cPrefijo VARCHAR(3),
        @nSecuencia BIGINT,
        @bExiste BIT = 1;

    SELECT
        @cUot = LEFT(
            REPLACE(REPLACE(UPPER(U.codigo), ' ', ''), '-', ''),
            12
        )
    FROM [org].[UOT] U
    WHERE U.uot_id = @nUotResuelta
      AND U.estado = 1;

    IF NULLIF(@cUot, '') IS NULL
    BEGIN
        SET @cMensaje = N'La UOT seleccionada no está disponible.';
        RETURN 1;
    END;

    SET @cPrefijo =
        CASE @cTipo
            WHEN 'BIEN' THEN 'BIE'
            WHEN 'PRODUCTO' THEN 'PRO'
            WHEN 'ALMACEN' THEN 'ALM'
            WHEN 'SUMINISTRO' THEN 'SUM'
        END;

    WHILE @bExiste = 1
    BEGIN
        SELECT @nSecuencia = NEXT VALUE FOR [logistica].[SEQ_CodigoAutomatico];

        SET @cCodigo =
            CONCAT(
                @cPrefijo,
                '-',
                @cUot,
                '-',
                RIGHT(
                    REPLICATE('0', 10) + CONVERT(VARCHAR(20), @nSecuencia),
                    10
                )
            );

        SET @bExiste =
            CASE @cTipo
                WHEN 'BIEN' THEN
                    CASE WHEN EXISTS
                    (
                        SELECT 1
                        FROM [logistica].[BienInventario]
                        WHERE codigo_patrimonial = @cCodigo
                    ) THEN 1 ELSE 0 END
                WHEN 'PRODUCTO' THEN
                    CASE WHEN EXISTS
                    (
                        SELECT 1
                        FROM [logistica].[Producto]
                        WHERE codigo = @cCodigo
                    ) THEN 1 ELSE 0 END
                WHEN 'ALMACEN' THEN
                    CASE WHEN EXISTS
                    (
                        SELECT 1
                        FROM [logistica].[Almacen]
                        WHERE uot_propietaria_id = @nUotResuelta
                          AND codigo = @cCodigo
                    ) THEN 1 ELSE 0 END
                WHEN 'SUMINISTRO' THEN
                    CASE WHEN EXISTS
                    (
                        SELECT 1
                        FROM [logistica].[Suministro]
                        WHERE uot_id = @nUotResuelta
                          AND codigo = @cCodigo
                    ) THEN 1 ELSE 0 END
                ELSE 0
            END;
    END;

    SELECT
        @bResultado = 1,
        @cMensaje = N'Código sugerido generado.',
        @cCodigoRespuesta = 'CODIGO_SUGERIDO',
        @nHttpRespuesta = 200;

    RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- logistica.PA_RecursoProgramado_Ins_Asignar
CREATE OR ALTER PROCEDURE [logistica].[PA_RecursoProgramado_Ins_Asignar]
(
    @cJson NVARCHAR(MAX),
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

 SET NOCOUNT ON;
 SET XACT_ABORT ON;
 DECLARE @vUsuario BIGINT,@vSesion BIGINT,@vDisp BIGINT,@vEmpleado BIGINT,@vModulo INT,
 @vCorr UNIQUEIDENTIFIER,@vSol UNIQUEIDENTIFIER,@vIp VARCHAR(64),@vEndpoint NVARCHAR(250),
 @vOperacion BIGINT,@vRepetida BIT=0,@vEstado VARCHAR(20),@vId NVARCHAR(200),@vCodigo VARCHAR(40),
 @vOk BIT,@vMsg NVARCHAR(300),@vAud BIGINT,@vTrans BIGINT,
 @vTranEntrada INT=@@TRANCOUNT,@vTranAbierta BIT=0,
 @vSave VARCHAR(32)=REPLACE(CONVERT(VARCHAR(36),NEWID()),'-','');
 SELECT @bResultado=0,@cMensaje=N'No se pudo completar la acción.';
 
 BEGIN TRY
  EXEC seg.PA_Operacion_Ins_IniciarIdempotente
   @cJson=@cJson,@cCodigoPermiso=N'RECURSOS_CREAR',@cAmbito=N'RECURSO_ASIGNAR',
   @nUsuarioId=@vUsuario OUTPUT,@nSesionUsuarioId=@vSesion OUTPUT,@nDispositivoUsuarioId=@vDisp OUTPUT,
   @nEmpleadoId=@vEmpleado OUTPUT,@nModuloId=@vModulo OUTPUT,@gCorrelacionId=@vCorr OUTPUT,
   @gSolicitudId=@vSol OUTPUT,@cIp=@vIp OUTPUT,@cEndpoint=@vEndpoint OUTPUT,
   @nOperacionIdempotenteId=@vOperacion OUTPUT,@bEsRepetida=@vRepetida OUTPUT,
   @cEstadoOperacion=@vEstado OUTPUT,@cIdentificadorResultado=@vId OUTPUT,
   @cCodigoResultado=@vCodigo OUTPUT,@bResultado=@vOk OUTPUT,@cMensaje=@vMsg OUTPUT;
  IF ISNULL(@vOk,0)=0 AND ISNULL(@vRepetida,0)=0
  BEGIN SET @cMensaje=@vMsg; GOTO Salida; END;
  IF @vRepetida=1
  BEGIN
   
   SET @bResultado=CASE WHEN @vEstado='COMPLETADA' THEN 1 ELSE 0 END;
   SET @cMensaje=CASE WHEN @vEstado='COMPLETADA' THEN N'Recurso entregado.' ELSE N'La acción está en proceso.' END;
   IF @vEstado='FALLIDA'
    SELECT @cMensaje=COALESCE(mensaje_resultado,N'La acción anterior no se completó.')
    FROM auditoria.OperacionIdempotente WHERE operacion_idempotente_id=@vOperacion;
   GOTO Salida;
  END;
  IF @vTranEntrada=0 BEGIN TRANSACTION; ELSE SAVE TRANSACTION @vSave;
  SET @vTranAbierta=1;

  DECLARE @id BIGINT=TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.recurso.recursoProgramadoId')),
   @bien BIGINT,@sum BIGINT,@cantidad DECIMAL(14,3),@camp BIGINT,@op BIGINT,@salida BIGINT,@valido BIT,@msg NVARCHAR(300);
  SELECT @bien=bien_inventario_id,@sum=suministro_id,@cantidad=cantidad_programada,
   @camp=campania_venta_id,@op=operativo_venta_id,@salida=salida_campo_id
  FROM logistica.RecursoProgramado WITH(UPDLOCK,HOLDLOCK)
  WHERE recurso_programado_id=@id AND estado=1 AND estado_proceso='PROGRAMADO';
  IF @cantidad IS NULL THROW 51100,N'DESCO_RECURSO_NO_DISPONIBLE',1;
  EXEC logistica.PA_RecursoProgramado_Sel_ValidarDestinoInterno @camp,@op,@salida,'ASIGNAR',@valido OUTPUT,@msg OUTPUT;
  IF ISNULL(@valido,0)=0 THROW 51000,@msg,1;
  IF @bien IS NOT NULL
  BEGIN
   UPDATE logistica.BienInventario SET estado_bien='ASIGNADO'
   WHERE bien_inventario_id=@bien AND estado=1 AND estado_bien='DISPONIBLE';
   IF @@ROWCOUNT<>1 THROW 51100,N'DESCO_RECURSO_NO_DISPONIBLE',1;
  END;
  -- Se libera primero la reserva dentro de esta misma transacción.
  UPDATE logistica.RecursoProgramado SET estado_proceso='EN_EJECUCION' WHERE recurso_programado_id=@id AND estado_proceso='PROGRAMADO';
  IF @@ROWCOUNT<>1 THROW 51100,N'DESCO_RECURSO_NO_DISPONIBLE',1;
  INSERT logistica.RecursoMovimiento(recurso_programado_id,tipo_movimiento,cantidad,fecha_hora,usuario_id,observacion,estado)
  VALUES(@id,CASE WHEN @bien IS NOT NULL THEN 'ASIGNACION' ELSE 'ENTREGA' END,@cantidad,SYSUTCDATETIME(),@vUsuario,N'Recurso entregado.',1);
  SET @vId=CONVERT(NVARCHAR(200),@id);

  EXEC auditoria.PA_Operacion_Ins_RegistrarCambio
   @nUsuarioId=@vUsuario,@nSesionUsuarioId=@vSesion,@nDispositivoUsuarioId=@vDisp,@nModuloId=@vModulo,
   @cAccion=N'RECURSO_ASIGNAR',@cEsquemaEntidad=N'logistica',@cNombreEntidad=N'RecursoProgramado',@cIdentificador=@vId,
   @cIp=@vIp,@gCorrelacionId=@vCorr,@gSolicitudId=@vSol,@cEndpoint=@vEndpoint,
   @nAuditoriaEventoId=@vAud OUTPUT,@nTransicionEstadoId=@vTrans OUTPUT;
  EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar
   @nOperacionIdempotenteId=@vOperacion,@cEstadoOperacion='COMPLETADA',
   @cEsquemaEntidad=N'logistica',@cNombreEntidad=N'RecursoProgramado',@cIdentificadorResultado=@vId,
   @cCodigoResultado=N'RECURSO_ASIGNAR',@bResultado=@vOk OUTPUT,@cMensaje=@vMsg OUTPUT;
  IF ISNULL(@vOk,0)=0 THROW 51003,N'DESCO_IDEMPOTENCIA_NO_CERRADA',1;
  IF @vTranEntrada=0 COMMIT TRANSACTION;
  SET @vTranAbierta=0;
  SELECT @bResultado=1,@cMensaje=N'Recurso entregado.';
 END TRY
 BEGIN CATCH
  IF @vTranAbierta=1
  BEGIN
   IF @vTranEntrada=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
   ELSE IF @vTranEntrada>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION @vSave;
   SET @vTranAbierta=0;
  END;
  SET @bResultado=0;
  EXEC config.PA_Respuesta_ResolverError @cProcedimiento=N'logistica.PA_RecursoProgramado_Ins_Asignar',@cMensaje=@cMensaje OUTPUT,@cJson=@cJson;
 END CATCH;
Salida:
 IF @bResultado=0 AND @vOperacion IS NOT NULL AND ISNULL(@vRepetida,0)=0 AND XACT_STATE()<>-1
 BEGIN TRY
  EXEC auditoria.PA_OperacionIdempotente_Upd_MensajeFallido @vOperacion,@cMensaje;
 END TRY
 BEGIN CATCH
  SET @bResultado=0;
 END CATCH;
 
 SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'logistica.PA_RecursoProgramado_Ins_Asignar',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- logistica.PA_RecursoProgramado_Ins_Consumo
CREATE OR ALTER PROCEDURE [logistica].[PA_RecursoProgramado_Ins_Consumo]
(@cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

 SET NOCOUNT ON;
 SET XACT_ABORT ON;
 DECLARE @vUsuario BIGINT,@vSesion BIGINT,@vDisp BIGINT,@vEmpleado BIGINT,@vModulo INT,
 @vCorr UNIQUEIDENTIFIER,@vSol UNIQUEIDENTIFIER,@vIp VARCHAR(64),@vEndpoint NVARCHAR(250),
 @vOperacion BIGINT,@vRepetida BIT=0,@vEstado VARCHAR(20),@vId NVARCHAR(200),@vCodigo VARCHAR(40),
 @vOk BIT,@vMsg NVARCHAR(300),@vAud BIGINT,@vTrans BIGINT,
 @vTranEntrada INT=@@TRANCOUNT,@vTranAbierta BIT=0,
 @vSave VARCHAR(32)=REPLACE(CONVERT(VARCHAR(36),NEWID()),'-','');
 SELECT @bResultado=0,@cMensaje=N'No se pudo completar la acción.';
 
 BEGIN TRY
  EXEC seg.PA_Operacion_Ins_IniciarIdempotente
   @cJson=@cJson,@cCodigoPermiso=N'RECURSOS_CREAR',@cAmbito=N'RECURSO_CONSUMO',
   @nUsuarioId=@vUsuario OUTPUT,@nSesionUsuarioId=@vSesion OUTPUT,@nDispositivoUsuarioId=@vDisp OUTPUT,
   @nEmpleadoId=@vEmpleado OUTPUT,@nModuloId=@vModulo OUTPUT,@gCorrelacionId=@vCorr OUTPUT,
   @gSolicitudId=@vSol OUTPUT,@cIp=@vIp OUTPUT,@cEndpoint=@vEndpoint OUTPUT,
   @nOperacionIdempotenteId=@vOperacion OUTPUT,@bEsRepetida=@vRepetida OUTPUT,
   @cEstadoOperacion=@vEstado OUTPUT,@cIdentificadorResultado=@vId OUTPUT,
   @cCodigoResultado=@vCodigo OUTPUT,@bResultado=@vOk OUTPUT,@cMensaje=@vMsg OUTPUT;
  IF ISNULL(@vOk,0)=0 AND ISNULL(@vRepetida,0)=0
  BEGIN SET @cMensaje=@vMsg; GOTO Salida; END;
  IF @vRepetida=1
  BEGIN
   
   SET @bResultado=CASE WHEN @vEstado='COMPLETADA' THEN 1 ELSE 0 END;
   SET @cMensaje=CASE WHEN @vEstado='COMPLETADA' THEN N'Consumo registrado.' ELSE N'La acción está en proceso.' END;
   IF @vEstado='FALLIDA'
    SELECT @cMensaje=COALESCE(mensaje_resultado,N'La acción anterior no se completó.')
    FROM auditoria.OperacionIdempotente WHERE operacion_idempotente_id=@vOperacion;
   GOTO Salida;
  END;
  IF @vTranEntrada=0 BEGIN TRANSACTION; ELSE SAVE TRANSACTION @vSave;
  SET @vTranAbierta=1;

  DECLARE @id BIGINT=TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.recurso.recursoProgramadoId')),
   @cantidad DECIMAL(14,3)=TRY_CONVERT(DECIMAL(14,3),JSON_VALUE(@cJson,'$.recurso.cantidadConsumida')),
   @pendiente DECIMAL(19,3),@obs NVARCHAR(300)=JSON_VALUE(@cJson,'$.recurso.observacion');
  SELECT @pendiente=cantidad_pendiente FROM logistica.RecursoProgramado WITH(UPDLOCK,HOLDLOCK)
  WHERE recurso_programado_id=@id AND suministro_id IS NOT NULL AND estado=1 AND estado_proceso='EN_EJECUCION';
  IF @pendiente IS NULL THROW 51100,N'DESCO_RECURSO_NO_DISPONIBLE',1;
  SET @cantidad=COALESCE(@cantidad,@pendiente);
  IF @cantidad<=0 OR @cantidad>@pendiente THROW 51100,N'DESCO_RECURSO_EXCESO',1;
  INSERT logistica.RecursoMovimiento(recurso_programado_id,tipo_movimiento,cantidad,fecha_hora,usuario_id,observacion,estado)
  VALUES(@id,'CONSUMO',@cantidad,SYSUTCDATETIME(),@vUsuario,@obs,1);
  SET @vId=CONVERT(NVARCHAR(200),@id);

  EXEC auditoria.PA_Operacion_Ins_RegistrarCambio
   @nUsuarioId=@vUsuario,@nSesionUsuarioId=@vSesion,@nDispositivoUsuarioId=@vDisp,@nModuloId=@vModulo,
   @cAccion=N'RECURSO_CONSUMO',@cEsquemaEntidad=N'logistica',@cNombreEntidad=N'RecursoProgramado',@cIdentificador=@vId,
   @cIp=@vIp,@gCorrelacionId=@vCorr,@gSolicitudId=@vSol,@cEndpoint=@vEndpoint,
   @nAuditoriaEventoId=@vAud OUTPUT,@nTransicionEstadoId=@vTrans OUTPUT;
  EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar
   @nOperacionIdempotenteId=@vOperacion,@cEstadoOperacion='COMPLETADA',
   @cEsquemaEntidad=N'logistica',@cNombreEntidad=N'RecursoProgramado',@cIdentificadorResultado=@vId,
   @cCodigoResultado=N'RECURSO_CONSUMO',@bResultado=@vOk OUTPUT,@cMensaje=@vMsg OUTPUT;
  IF ISNULL(@vOk,0)=0 THROW 51003,N'DESCO_IDEMPOTENCIA_NO_CERRADA',1;
  IF @vTranEntrada=0 COMMIT TRANSACTION;
  SET @vTranAbierta=0;
  SELECT @bResultado=1,@cMensaje=N'Consumo registrado.';
 END TRY
 BEGIN CATCH
  IF @vTranAbierta=1
  BEGIN
   IF @vTranEntrada=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
   ELSE IF @vTranEntrada>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION @vSave;
   SET @vTranAbierta=0;
  END;
  SET @bResultado=0;
  EXEC config.PA_Respuesta_ResolverError @cProcedimiento=N'logistica.PA_RecursoProgramado_Ins_Consumo',@cMensaje=@cMensaje OUTPUT,@cJson=@cJson;
 END CATCH;
Salida:
 IF @bResultado=0 AND @vOperacion IS NOT NULL AND ISNULL(@vRepetida,0)=0 AND XACT_STATE()<>-1
 BEGIN TRY
  EXEC auditoria.PA_OperacionIdempotente_Upd_MensajeFallido @vOperacion,@cMensaje;
 END TRY
 BEGIN CATCH
  SET @bResultado=0;
 END CATCH;
 
 SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'logistica.PA_RecursoProgramado_Ins_Consumo',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- logistica.PA_RecursoProgramado_Ins_Devolucion
CREATE OR ALTER PROCEDURE [logistica].[PA_RecursoProgramado_Ins_Devolucion](@cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

 SET NOCOUNT ON;
 SET XACT_ABORT ON;
 DECLARE @vUsuario BIGINT,@vSesion BIGINT,@vDisp BIGINT,@vEmpleado BIGINT,@vModulo INT,
 @vCorr UNIQUEIDENTIFIER,@vSol UNIQUEIDENTIFIER,@vIp VARCHAR(64),@vEndpoint NVARCHAR(250),
 @vOperacion BIGINT,@vRepetida BIT=0,@vEstado VARCHAR(20),@vId NVARCHAR(200),@vCodigo VARCHAR(40),
 @vOk BIT,@vMsg NVARCHAR(300),@vAud BIGINT,@vTrans BIGINT,
 @vTranEntrada INT=@@TRANCOUNT,@vTranAbierta BIT=0,
 @vSave VARCHAR(32)=REPLACE(CONVERT(VARCHAR(36),NEWID()),'-','');
 SELECT @bResultado=0,@cMensaje=N'No se pudo completar la acción.';
 
 BEGIN TRY
  EXEC seg.PA_Operacion_Ins_IniciarIdempotente
   @cJson=@cJson,@cCodigoPermiso=N'RECURSOS_CREAR',@cAmbito=N'RECURSO_DEVOLVER',
   @nUsuarioId=@vUsuario OUTPUT,@nSesionUsuarioId=@vSesion OUTPUT,@nDispositivoUsuarioId=@vDisp OUTPUT,
   @nEmpleadoId=@vEmpleado OUTPUT,@nModuloId=@vModulo OUTPUT,@gCorrelacionId=@vCorr OUTPUT,
   @gSolicitudId=@vSol OUTPUT,@cIp=@vIp OUTPUT,@cEndpoint=@vEndpoint OUTPUT,
   @nOperacionIdempotenteId=@vOperacion OUTPUT,@bEsRepetida=@vRepetida OUTPUT,
   @cEstadoOperacion=@vEstado OUTPUT,@cIdentificadorResultado=@vId OUTPUT,
   @cCodigoResultado=@vCodigo OUTPUT,@bResultado=@vOk OUTPUT,@cMensaje=@vMsg OUTPUT;
  IF ISNULL(@vOk,0)=0 AND ISNULL(@vRepetida,0)=0
  BEGIN SET @cMensaje=@vMsg; GOTO Salida; END;
  IF @vRepetida=1
  BEGIN
   
   SET @bResultado=CASE WHEN @vEstado='COMPLETADA' THEN 1 ELSE 0 END;
   SET @cMensaje=CASE WHEN @vEstado='COMPLETADA' THEN N'Devolución registrada.' ELSE N'La acción está en proceso.' END;
   IF @vEstado='FALLIDA'
    SELECT @cMensaje=COALESCE(mensaje_resultado,N'La acción anterior no se completó.')
    FROM auditoria.OperacionIdempotente WHERE operacion_idempotente_id=@vOperacion;
   GOTO Salida;
  END;
  IF @vTranEntrada=0 BEGIN TRANSACTION; ELSE SAVE TRANSACTION @vSave;
  SET @vTranAbierta=1;

  DECLARE @id BIGINT=TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.recurso.recursoProgramadoId')),
   @cantidad DECIMAL(14,3)=TRY_CONVERT(DECIMAL(14,3),JSON_VALUE(@cJson,'$.recurso.cantidadDevuelta')),
   @cerrar BIT=COALESCE(TRY_CONVERT(BIT,JSON_VALUE(@cJson,'$.recurso.finalizar')),0),
   @bien BIGINT,@pendiente DECIMAL(19,3),@obs NVARCHAR(300)=JSON_VALUE(@cJson,'$.recurso.observacion');
  SELECT @bien=bien_inventario_id,@pendiente=cantidad_pendiente FROM logistica.RecursoProgramado WITH(UPDLOCK,HOLDLOCK)
  WHERE recurso_programado_id=@id AND estado=1 AND estado_proceso='EN_EJECUCION';
  IF @pendiente IS NULL THROW 51100,N'DESCO_RECURSO_NO_DISPONIBLE',1;
  IF @bien IS NOT NULL SET @cantidad=1;
  IF @cantidad IS NULL OR @cantidad<0 OR (@cantidad=0 AND @cerrar=0) OR @cantidad>@pendiente
   THROW 51100,N'DESCO_RECURSO_EXCESO',1;
  IF @cantidad>0
   INSERT logistica.RecursoMovimiento(recurso_programado_id,tipo_movimiento,cantidad,fecha_hora,usuario_id,observacion,estado)
   VALUES(@id,'DEVOLUCION',@cantidad,SYSUTCDATETIME(),@vUsuario,@obs,1);
  IF @cerrar=1 AND @bien IS NULL AND @pendiente>@cantidad
   INSERT logistica.RecursoMovimiento(recurso_programado_id,tipo_movimiento,cantidad,fecha_hora,usuario_id,observacion,estado)
   VALUES(@id,'CONSUMO',@pendiente-@cantidad,SYSUTCDATETIME(),@vUsuario,N'Consumo registrado al finalizar la actividad.',1);
  SET @vId=CONVERT(NVARCHAR(200),@id);

  EXEC auditoria.PA_Operacion_Ins_RegistrarCambio
   @nUsuarioId=@vUsuario,@nSesionUsuarioId=@vSesion,@nDispositivoUsuarioId=@vDisp,@nModuloId=@vModulo,
   @cAccion=N'RECURSO_DEVOLVER',@cEsquemaEntidad=N'logistica',@cNombreEntidad=N'RecursoProgramado',@cIdentificador=@vId,
   @cIp=@vIp,@gCorrelacionId=@vCorr,@gSolicitudId=@vSol,@cEndpoint=@vEndpoint,
   @nAuditoriaEventoId=@vAud OUTPUT,@nTransicionEstadoId=@vTrans OUTPUT;
  EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar
   @nOperacionIdempotenteId=@vOperacion,@cEstadoOperacion='COMPLETADA',
   @cEsquemaEntidad=N'logistica',@cNombreEntidad=N'RecursoProgramado',@cIdentificadorResultado=@vId,
   @cCodigoResultado=N'RECURSO_DEVOLVER',@bResultado=@vOk OUTPUT,@cMensaje=@vMsg OUTPUT;
  IF ISNULL(@vOk,0)=0 THROW 51003,N'DESCO_IDEMPOTENCIA_NO_CERRADA',1;
  IF @vTranEntrada=0 COMMIT TRANSACTION;
  SET @vTranAbierta=0;
  SELECT @bResultado=1,@cMensaje=N'Devolución registrada.';
 END TRY
 BEGIN CATCH
  IF @vTranAbierta=1
  BEGIN
   IF @vTranEntrada=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
   ELSE IF @vTranEntrada>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION @vSave;
   SET @vTranAbierta=0;
  END;
  SET @bResultado=0;
  EXEC config.PA_Respuesta_ResolverError @cProcedimiento=N'logistica.PA_RecursoProgramado_Ins_Devolucion',@cMensaje=@cMensaje OUTPUT,@cJson=@cJson;
 END CATCH;
Salida:
 IF @bResultado=0 AND @vOperacion IS NOT NULL AND ISNULL(@vRepetida,0)=0 AND XACT_STATE()<>-1
 BEGIN TRY
  EXEC auditoria.PA_OperacionIdempotente_Upd_MensajeFallido @vOperacion,@cMensaje;
 END TRY
 BEGIN CATCH
  SET @bResultado=0;
 END CATCH;
 
 SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'logistica.PA_RecursoProgramado_Ins_Devolucion',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- logistica.PA_RecursoProgramado_Ins_Programar
CREATE OR ALTER PROCEDURE [logistica].[PA_RecursoProgramado_Ins_Programar]
(
    @cJson NVARCHAR(MAX),
    @nRecursoProgramadoId BIGINT OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,
        @gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),
        @nOperacion BIGINT,@bRepetida BIT,@cEstadoOperacion VARCHAR(20),@cIdResultado NVARCHAR(200),
        @cCodigoResultado VARCHAR(40),@bInicio BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),
        @nAud BIGINT,@nTrans BIGINT,
        @nCampania BIGINT,@nOperativo BIGINT,@nSalida BIGINT,@nBien BIGINT,@nSuministro BIGINT,
        @nCantidad DECIMAL(14,3),@cObservacion NVARCHAR(300),@nStock DECIMAL(19,3),
        @bDestinoValido BIT,@cMensajeDestino NVARCHAR(300),@cIdentificador NVARCHAR(200);

    SELECT @nRecursoProgramadoId=NULL,@bResultado=0,@cMensaje=N'No se pudo programar el recurso.';

    EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente]
        @cJson=@cJson,
        @cCodigoPermiso='RECURSOS_CREAR',
        @cAmbito='RECURSO_PROGRAMAR',
        @nUsuarioId=@nUsuario OUTPUT,
        @nSesionUsuarioId=@nSesion OUTPUT,
        @nDispositivoUsuarioId=@nDisp OUTPUT,
        @nEmpleadoId=@nEmp OUTPUT,
        @nModuloId=@nModulo OUTPUT,
        @gCorrelacionId=@gCorr OUTPUT,
        @gSolicitudId=@gSol OUTPUT,
        @cIp=@cIp OUTPUT,
        @cEndpoint=@cEnd OUTPUT,
        @nOperacionIdempotenteId=@nOperacion OUTPUT,
        @bEsRepetida=@bRepetida OUTPUT,
        @cEstadoOperacion=@cEstadoOperacion OUTPUT,
        @cIdentificadorResultado=@cIdResultado OUTPUT,
        @cCodigoResultado=@cCodigoResultado OUTPUT,
        @bResultado=@bInicio OUTPUT,
        @cMensaje=@cMsg OUTPUT;

    IF @bInicio=0 AND @bRepetida=0
    BEGIN
        SET @cMensaje=@cMsg;
        GOTO __DESCO_Salida;
    END;

    IF @bRepetida=1
    BEGIN
        IF @cEstadoOperacion='COMPLETADA'
        BEGIN
            SET @nRecursoProgramadoId=TRY_CONVERT(BIGINT,@cIdResultado);
            SET @bResultado=1;
            SET @cMensaje=N'La solicitud ya fue procesada correctamente.';
        END
        ELSE
            SET @cMensaje=N'La solicitud ya se encuentra en proceso.';
        GOTO __DESCO_Salida;
    END;

    SELECT
        @nCampania=campaniaVentaId,
        @nOperativo=operativoVentaId,
        @nSalida=salidaCampoId,
        @nBien=bienInventarioId,
        @nSuministro=suministroId,
        @nCantidad=cantidadProgramada,
        @cObservacion=NULLIF(LTRIM(RTRIM(observacion)),N'')
    FROM OPENJSON(@cJson,'$.recurso')
    WITH
    (
        campaniaVentaId BIGINT '$.campaniaVentaId',
        operativoVentaId BIGINT '$.operativoVentaId',
        salidaCampoId BIGINT '$.salidaCampoId',
        bienInventarioId BIGINT '$.bienInventarioId',
        suministroId BIGINT '$.suministroId',
        cantidadProgramada DECIMAL(14,3) '$.cantidadProgramada',
        observacion NVARCHAR(300) '$.observacion'
    );

    IF (CASE WHEN @nBien IS NULL THEN 0 ELSE 1 END)+(CASE WHEN @nSuministro IS NULL THEN 0 ELSE 1 END)<>1
       OR @nCantidad IS NULL OR @nCantidad<=0
    BEGIN
        SET @cMensaje=N'Seleccione un recurso y una cantidad válida.';
        GOTO Fallar;
    END;

    EXEC [logistica].[PA_RecursoProgramado_Sel_ValidarDestinoInterno]
        @nCampaniaVentaId=@nCampania,
        @nOperativoVentaId=@nOperativo,
        @nSalidaCampoId=@nSalida,
        @cMomento='PROGRAMAR',
        @bValido=@bDestinoValido OUTPUT,
        @cMensaje=@cMensajeDestino OUTPUT;

    IF @bDestinoValido=0
    BEGIN
        SET @cMensaje=@cMensajeDestino;
        GOTO Fallar;
    END;

    IF @nBien IS NOT NULL
    BEGIN
        IF @nCantidad<>1
           OR NOT EXISTS
              (
                  SELECT 1 FROM [logistica].[BienInventario]
                  WHERE bien_inventario_id=@nBien AND estado=1 AND estado_bien='DISPONIBLE'
              )
           OR EXISTS
              (
                  SELECT 1 FROM [logistica].[RecursoProgramado]
                  WHERE bien_inventario_id=@nBien AND estado=1 AND estado_proceso IN('PROGRAMADO','EN_EJECUCION')
              )
        BEGIN
            SET @cMensaje=N'El bien seleccionado no está disponible para programación.';
            GOTO Fallar;
        END;
    END
    ELSE
    BEGIN
        EXEC [logistica].[PA_Suministro_Sel_StockInterno]
            @nSuministroId=@nSuministro,
            @nStock=NULL,@nDisponible=@nStock OUTPUT;

        IF NOT EXISTS(SELECT 1 FROM [logistica].[Suministro] WHERE suministro_id=@nSuministro AND estado=1)
           OR @nCantidad>@nStock
        BEGIN
            SET @cMensaje=N'El suministro no tiene stock suficiente para esta programación.';
            GOTO Fallar;
        END;
    END;

    BEGIN TRY
        BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

        INSERT INTO [logistica].[RecursoProgramado]
        (
            campania_venta_id,operativo_venta_id,salida_campo_id,bien_inventario_id,suministro_id,
            cantidad_programada,observacion,estado,estado_proceso,usuario_programacion_id,fecha_programacion
        )
        VALUES
        (
            @nCampania,@nOperativo,@nSalida,@nBien,@nSuministro,
            @nCantidad,@cObservacion,1,'PROGRAMADO',@nUsuario,SYSUTCDATETIME()
        );

        SET @nRecursoProgramadoId=CONVERT(BIGINT,SCOPE_IDENTITY());
        SET @cIdentificador=CONVERT(NVARCHAR(200),@nRecursoProgramadoId);

        EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio]
            @nUsuarioId=@nUsuario,
            @nSesionUsuarioId=@nSesion,
            @nDispositivoUsuarioId=@nDisp,
            @nModuloId=@nModulo,
            @cAccion='PROGRAMAR',
            @cEsquemaEntidad='logistica',
            @cNombreEntidad='RecursoProgramado',
            @cIdentificador=@cIdentificador,
            @cDatosAnteriores=NULL,
            @cDatosPosteriores=NULL,
            @cMotivo=NULL,
            @cCampoEstado='estado_proceso',
            @cEstadoAnterior=NULL,
            @cEstadoNuevo='PROGRAMADO',
            @cIp=@cIp,
            @gCorrelacionId=@gCorr,
            @gSolicitudId=@gSol,
            @cEndpoint=@cEnd,
            @nAuditoriaEventoId=@nAud OUTPUT,
            @nTransicionEstadoId=@nTrans OUTPUT;

        /* Confirmar datos e idempotencia juntos. */

        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
            @nOperacionIdempotenteId=@nOperacion,
            @cEstadoOperacion='COMPLETADA',
            @cEsquemaEntidad='logistica',
            @cNombreEntidad='RecursoProgramado',
            @cIdentificadorResultado=@cIdentificador,
            @cCodigoResultado='RECURSO_PROGRAMADO',
            @bResultado=@bFin OUTPUT,
            @cMensaje=@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;

        SET @bResultado=1;
        SET @cMensaje=N'Recurso programado correctamente.';
        GOTO __DESCO_Salida;
    END TRY
    BEGIN CATCH
SET @bResultado = 0;

        IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
        SET @cMensaje=N'No se pudo programar el recurso. Intente nuevamente.';
    
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'logistica.PA_RecursoProgramado_Ins_Programar',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;

Fallar:
    IF @nOperacion IS NOT NULL AND @bResultado=0
        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
            @nOperacionIdempotenteId=@nOperacion,
            @cEstadoOperacion='FALLIDA',
            @cEsquemaEntidad=NULL,
            @cNombreEntidad=NULL,
