SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* ----------------------------------------------------------------------------
   6. Disponibilidad UOT-aware para el selector de recursos.
   ---------------------------------------------------------------------------- */
CREATE OR ALTER PROCEDURE [logistica].[PA_RecursoProgramado_Sel_DisponibilidadUOT]
    @nUsuarioId BIGINT,
    @nSesionUsuarioId BIGINT,
    @nUotId BIGINT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60) = NULL OUTPUT,
    @nHttpRespuesta SMALLINT = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        @bResultado = 0,
        @cMensaje = N'No se pudo consultar la disponibilidad.',
        @cCodigoRespuesta = 'DISPONIBILIDAD_NO_LISTADA',
        @nHttpRespuesta = 400;

    DECLARE
        @nUotResuelta BIGINT = @nUotId,
        @bModoGeneral BIT,
        @bOk BIT,
        @cMsg NVARCHAR(300);

    EXEC [seg].[PA_UOT_Sel_ResolverContextoSesion]
        @nUsuarioId = @nUsuarioId,
        @nSesionUsuarioId = @nSesionUsuarioId,
        @nUotSolicitada = @nUotResuelta,
        @cCodigoPermiso = 'RECURSOS_VER',
        @bRequiereUot = 1,
        @nUotId = @nUotResuelta OUTPUT,
        @bModoGeneral = @bModoGeneral OUTPUT,
        @bResultado = @bOk OUTPUT,
        @cMensaje = @cMsg OUTPUT;

    IF ISNULL(@bOk, 0) = 0
    BEGIN
        SET @cMensaje = COALESCE(NULLIF(@cMsg, N''), @cMensaje);
        RETURN 1;
    END;

    SELECT
        B.bien_inventario_id AS bienInventarioId,
        B.uot_id AS uotId,
        U.codigo AS uotCodigo,
        U.nombre AS uotNombre,
        B.codigo_patrimonial AS codigoPatrimonial,
        B.nombre,
        B.estado_bien AS estadoBien,
        CONVERT(
            BIT,
            CASE
                WHEN B.estado_bien = 'DISPONIBLE'
                 AND NOT EXISTS
                 (
                     SELECT 1
                     FROM [logistica].[RecursoProgramado] R
                     WHERE R.bien_inventario_id = B.bien_inventario_id
                       AND R.estado = 1
                       AND R.estado_proceso IN ('PROGRAMADO', 'EN_EJECUCION')
                 )
                THEN 1
                ELSE 0
            END
        ) AS disponible
    FROM [logistica].[BienInventario] B
    INNER JOIN [org].[UOT] U
        ON U.uot_id = B.uot_id
       AND U.estado = 1
    WHERE B.uot_id = @nUotResuelta
      AND B.estado = 1
      AND B.estado_bien <> 'BAJA'
    ORDER BY B.nombre, B.bien_inventario_id;

    SELECT
        S.suministro_id AS suministroId,
        S.uot_id AS uotId,
        U.codigo AS uotCodigo,
        U.nombre AS uotNombre,
        S.codigo,
        S.nombre,
        S.unidad_medida AS unidadMedida,
        COALESCE(K.stock_actual, 0) AS stockActual,
        COALESCE(K.stock_reservado, 0) AS stockReservado,
        COALESCE(K.stock_disponible, 0) AS stockDisponible,
        S.stock_minimo AS stockMinimo,
        CONVERT(
            BIT,
            CASE
                WHEN COALESCE(K.stock_disponible, 0) <= S.stock_minimo THEN 1
                ELSE 0
            END
        ) AS requiereReposicion
    FROM [logistica].[Suministro] S
    INNER JOIN [org].[UOT] U
        ON U.uot_id = S.uot_id
       AND U.estado = 1
    LEFT JOIN [logistica].[SuministroSaldo] K
        ON K.suministro_id = S.suministro_id
    WHERE S.uot_id = @nUotResuelta
      AND S.estado = 1
    ORDER BY S.nombre, S.suministro_id;

    SELECT
        @bResultado = 1,
        @cMensaje = N'Disponibilidad consultada.',
        @cCodigoRespuesta = 'DISPONIBILIDAD_LISTADA',
        @nHttpRespuesta = 200;

    RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- logistica.PA_RecursoProgramado_Sel_Listado
CREATE OR ALTER PROCEDURE [logistica].[PA_RecursoProgramado_Sel_Listado](@cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;

    BEGIN TRY
  SET NOCOUNT ON;
    DECLARE @nPaginaListado INT, @nTamanoListado INT, @nOffsetListado BIGINT;
    EXEC [seg].[PA_Consulta_Sel_ResolverPaginacion]
         @cJson = @cJson,
         @nPagina = @nPaginaListado OUTPUT,
         @nTamanoPagina = @nTamanoListado OUTPUT,
         @nOffset = @nOffsetListado OUTPUT;
DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@bCtx BIT,@cMsg NVARCHAR(300);
SELECT @bResultado=0,@cMensaje=N'No se pudieron consultar los recursos programados.';
EXEC seg.PA_Operacion_Sel_ContextoAutorizado @cJson=@cJson,@cCodigoPermiso='RECURSOS_LISTAR',@nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@bResultado=@bCtx OUTPUT,@cMensaje=@cMsg OUTPUT;
IF @bCtx=0 BEGIN SET @cMensaje=@cMsg;
GOTO __DESCO_Salida;
END;
 DECLARE @cEstado VARCHAR(20),@nCamp BIGINT,@nOpVenta BIGINT,@nSalida BIGINT;
SELECT @cEstado=UPPER(NULLIF(LTRIM(RTRIM(estadoProceso)),'')),@nCamp=campaniaVentaId,@nOpVenta=operativoVentaId,@nSalida=salidaCampoId FROM OPENJSON(@cJson,'$.filtros') WITH(estadoProceso VARCHAR(20) '$.estadoProceso',campaniaVentaId BIGINT '$.campaniaVentaId',operativoVentaId BIGINT '$.operativoVentaId',salidaCampoId BIGINT '$.salidaCampoId');
SELECT R.recurso_programado_id recursoProgramadoId,R.campania_venta_id campaniaVentaId,R.operativo_venta_id operativoVentaId,R.salida_campo_id salidaCampoId,R.bien_inventario_id bienInventarioId,B.nombre bien,R.suministro_id suministroId,S.nombre suministro,R.cantidad_programada cantidadProgramada,R.cantidad_entregada cantidadEntregada,R.cantidad_devuelta cantidadDevuelta,R.cantidad_consumida cantidadConsumida,R.cantidad_pendiente cantidadPendiente,R.estado_proceso estadoProceso,R.fecha_programacion fechaProgramacion,R.observacion,COALESCE((SELECT SUM(M.cantidad) FROM logistica.RecursoMovimiento M WHERE M.recurso_programado_id=R.recurso_programado_id AND M.estado=1 AND M.tipo_movimiento IN('ASIGNACION','ENTREGA','CONSUMO')),0) cantidadEjecutada,COALESCE((SELECT SUM(M.cantidad) FROM logistica.RecursoMovimiento M WHERE M.recurso_programado_id=R.recurso_programado_id AND M.estado=1 AND M.tipo_movimiento='DEVOLUCION'),0) cantidadDevuelta , COUNT_BIG(*) OVER() AS totalRegistros FROM logistica.RecursoProgramado R LEFT JOIN logistica.BienInventario B ON B.bien_inventario_id=R.bien_inventario_id LEFT JOIN logistica.Suministro S ON S.suministro_id=R.suministro_id WHERE R.estado=1 AND (@cEstado IS NULL OR R.estado_proceso=@cEstado) AND (@nCamp IS NULL OR R.campania_venta_id=@nCamp) AND (@nOpVenta IS NULL OR R.operativo_venta_id=@nOpVenta) AND (@nSalida IS NULL OR R.salida_campo_id=@nSalida) ORDER BY R.fecha_programacion DESC,R.recurso_programado_id DESC OFFSET @nOffsetListado ROWS FETCH NEXT @nTamanoListado ROWS ONLY;
SET @bResultado=1;
SET @cMensaje=N'Recursos consultados correctamente.';
    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
