/* ----------------------------------------------------------------------------
   7. Validar que el destino programado pertenece al contexto UOT real de la
   sesión. GENERAL no fusiona roles; ESPECIFICA no puede cruzar UOT.
   ---------------------------------------------------------------------------- */
CREATE OR ALTER PROCEDURE [logistica].[PA_RecursoProgramado_Sel_ValidarDestinoContexto]
    @nUsuarioId BIGINT,
    @nSesionUsuarioId BIGINT,
    @nCampaniaVentaId BIGINT = NULL,
    @nOperativoVentaId BIGINT = NULL,
    @nSalidaCampoId BIGINT = NULL,
    @nUotDestino BIGINT OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60) = NULL OUTPUT,
    @nHttpRespuesta SMALLINT = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        @nUotDestino = NULL,
        @bResultado = 0,
        @cMensaje = N'El destino seleccionado no está disponible.',
        @cCodigoRespuesta = 'DESTINO_NO_VALIDO',
        @nHttpRespuesta = 400;

    DECLARE @nCantidadDestinos TINYINT =
        (CASE WHEN @nCampaniaVentaId IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN @nOperativoVentaId IS NULL THEN 0 ELSE 1 END)
        + (CASE WHEN @nSalidaCampoId IS NULL THEN 0 ELSE 1 END);

    IF @nCantidadDestinos <> 1
    BEGIN
        SET @cMensaje = N'Seleccione un único destino.';
        RETURN 1;
    END;

    IF @nCampaniaVentaId IS NOT NULL
    BEGIN
        SELECT @nUotDestino = C.uot_id
        FROM [comercial].[CampaniaVenta] C
        WHERE C.campania_venta_id = @nCampaniaVentaId
          AND C.estado = 1
          AND C.estado_proceso IN ('PLANIFICACION', 'ACTIVA');
    END
    ELSE IF @nOperativoVentaId IS NOT NULL
    BEGIN
        SELECT @nUotDestino = C.uot_id
        FROM [comercial].[OperativoVenta] O
        INNER JOIN [comercial].[CampaniaVenta] C
            ON C.campania_venta_id = O.campania_venta_id
           AND C.estado = 1
           AND C.estado_proceso IN ('PLANIFICACION', 'ACTIVA')
        WHERE O.operativo_venta_id = @nOperativoVentaId
          AND O.estado = 1
          AND O.estado_proceso IN ('PLANIFICADO', 'EN_RECEPCION');
    END
    ELSE
    BEGIN
        SELECT @nUotDestino = S.uot_id
        FROM [campo].[SalidaCampo] S
        WHERE S.salida_campo_id = @nSalidaCampoId
          AND S.estado = 1
          AND S.estado_proceso IN ('BORRADOR', 'PROGRAMADA');
    END;

    IF @nUotDestino IS NULL
    BEGIN
        SET @cMensaje = N'El destino seleccionado ya no está disponible para programar recursos.';
        RETURN 1;
    END;

    DECLARE
        @nUotResuelta BIGINT = @nUotDestino,
        @bModoGeneral BIT,
        @bOk BIT,
        @cMsg NVARCHAR(300);

    EXEC [seg].[PA_UOT_Sel_ResolverContextoSesion]
        @nUsuarioId = @nUsuarioId,
        @nSesionUsuarioId = @nSesionUsuarioId,
        @nUotSolicitada = @nUotResuelta,
        @cCodigoPermiso = 'RECURSOS_CREAR',
        @bRequiereUot = 1,
        @nUotId = @nUotResuelta OUTPUT,
        @bModoGeneral = @bModoGeneral OUTPUT,
        @bResultado = @bOk OUTPUT,
        @cMensaje = @cMsg OUTPUT;

    IF ISNULL(@bOk, 0) = 0
    BEGIN
        SET @cMensaje = COALESCE(NULLIF(@cMsg, N''), @cMensaje);
        SET @nUotDestino = NULL;
        RETURN 1;
    END;

    SELECT
        @nUotDestino = @nUotResuelta,
        @bResultado = 1,
        @cMensaje = N'Destino validado.',
        @cCodigoRespuesta = 'DESTINO_VALIDO',
        @nHttpRespuesta = 200;

    RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- logistica.PA_RecursoProgramado_Sel_ValidarDestinoInterno
CREATE OR ALTER PROCEDURE [logistica].[PA_RecursoProgramado_Sel_ValidarDestinoInterno]
(
    @nCampaniaVentaId BIGINT = NULL,
    @nOperativoVentaId BIGINT = NULL,
    @nSalidaCampoId BIGINT = NULL,
    @cMomento VARCHAR(20),
    @bValido BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @bResultado BIT=NULL OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bValido = 0;

    SET @bResultado=0;
BEGIN TRY

    SET NOCOUNT ON;

    DECLARE @nDestinos TINYINT =
        (CASE WHEN @nCampaniaVentaId IS NULL THEN 0 ELSE 1 END) +
        (CASE WHEN @nOperativoVentaId IS NULL THEN 0 ELSE 1 END) +
        (CASE WHEN @nSalidaCampoId IS NULL THEN 0 ELSE 1 END);

    SET @bValido=0;
    SET @cMensaje=N'La actividad seleccionada no está disponible para esta operación.';
    SET @cMomento=UPPER(NULLIF(LTRIM(RTRIM(@cMomento)),''));

    IF @nDestinos<>1 OR @cMomento IS NULL OR @cMomento NOT IN('PROGRAMAR','EDITAR','ASIGNAR')
    BEGIN
        SET @cMensaje=N'Seleccione una actividad válida para el recurso.';
        GOTO __DESCO_Salida;
    END;

    IF @nCampaniaVentaId IS NOT NULL
    BEGIN
        IF @cMomento IN('PROGRAMAR','EDITAR')
           AND EXISTS
           (
               SELECT 1 FROM [comercial].[CampaniaVenta]
               WHERE campania_venta_id=@nCampaniaVentaId
                 AND estado=1
                 AND estado_proceso IN('PLANIFICACION','ACTIVA')
           )
        BEGIN
            SET @bValido=1;
            SET @cMensaje=N'Campaña disponible para programación de recursos.';
            GOTO __DESCO_Salida;
        END;

        IF @cMomento='ASIGNAR'
           AND EXISTS
           (
               SELECT 1 FROM [comercial].[CampaniaVenta]
               WHERE campania_venta_id=@nCampaniaVentaId
                 AND estado=1
                 AND estado_proceso='ACTIVA'
           )
        BEGIN
            SET @bValido=1;
            SET @cMensaje=N'Campaña disponible para asignación de recursos.';
            GOTO __DESCO_Salida;
        END;

        SET @cMensaje=N'La campaña ya no permite programar o asignar recursos.';
        GOTO __DESCO_Salida;
    END;

    IF @nOperativoVentaId IS NOT NULL
    BEGIN
        IF @cMomento IN('PROGRAMAR','EDITAR')
           AND EXISTS
           (
               SELECT 1
               FROM [comercial].[OperativoVenta] O
               INNER JOIN [comercial].[CampaniaVenta] C
                   ON C.campania_venta_id=O.campania_venta_id
                  AND C.estado=1
                  AND C.estado_proceso IN('PLANIFICACION','ACTIVA')
               WHERE O.operativo_venta_id=@nOperativoVentaId
                 AND O.estado=1
                 AND O.estado_proceso IN('PLANIFICADO','EN_RECEPCION')
           )
        BEGIN
            SET @bValido=1;
            SET @cMensaje=N'Operativo disponible para programación de recursos.';
            GOTO __DESCO_Salida;
        END;

        IF @cMomento='ASIGNAR'
           AND EXISTS
           (
               SELECT 1
               FROM [comercial].[OperativoVenta] O
               INNER JOIN [comercial].[CampaniaVenta] C
                   ON C.campania_venta_id=O.campania_venta_id
                  AND C.estado=1
                  AND C.estado_proceso='ACTIVA'
               WHERE O.operativo_venta_id=@nOperativoVentaId
                 AND O.estado=1
                 AND O.estado_proceso IN('PLANIFICADO','EN_RECEPCION')
           )
        BEGIN
            SET @bValido=1;
            SET @cMensaje=N'Operativo disponible para asignación de recursos.';
            GOTO __DESCO_Salida;
        END;

        SET @cMensaje=N'El operativo ya no permite programar o asignar recursos.';
        GOTO __DESCO_Salida;
    END;

    IF @nSalidaCampoId IS NOT NULL
    BEGIN
        IF @cMomento IN('PROGRAMAR','EDITAR')
           AND EXISTS
           (
               SELECT 1 FROM [campo].[SalidaCampo]
               WHERE salida_campo_id=@nSalidaCampoId
                 AND estado=1
                 AND estado_proceso IN('BORRADOR','PROGRAMADA')
           )
        BEGIN
            SET @bValido=1;
            SET @cMensaje=N'Salida disponible para programación de recursos.';
            GOTO __DESCO_Salida;
        END;

        IF @cMomento='ASIGNAR'
           AND EXISTS
           (
               SELECT 1 FROM [campo].[SalidaCampo]
               WHERE salida_campo_id=@nSalidaCampoId
                 AND estado=1
                 AND estado_proceso IN('PROGRAMADA','EN_CURSO')
           )
        BEGIN
            SET @bValido=1;
            SET @cMensaje=N'Salida disponible para asignación de recursos.';
            GOTO __DESCO_Salida;
        END;

        SET @cMensaje=N'La salida ya no permite programar o asignar recursos.';
        GOTO __DESCO_Salida;
    END;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bValido = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'logistica.PA_RecursoProgramado_Sel_ValidarDestinoInterno',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bValido,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bValido = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bValido = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'logistica.PA_RecursoProgramado_Sel_ValidarDestinoInterno',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bValido,0) = 1
BEGIN
SET @bValido = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=CASE WHEN @__DbError=0 THEN ISNULL(@bValido,0) ELSE 0 END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'logistica.PA_RecursoProgramado_Sel_ValidarDestinoInterno',@bResultado,@cMensaje) R;
IF @__DbError=1 AND @@NESTLEVEL>1 THROW 51000,@cMensaje,1;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- logistica.PA_RecursoProgramado_Upd_Cancelar
CREATE OR ALTER PROCEDURE [logistica].[PA_RecursoProgramado_Upd_Cancelar](@cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY
  SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),@nAud BIGINT,@nTrans BIGINT,@nId BIGINT,@cMotivo NVARCHAR(300),@cIdent NVARCHAR(200);
SELECT @bResultado=0,@cMensaje=N'No se pudo cancelar la programación.';
EXEC seg.PA_Operacion_Ins_IniciarIdempotente @cJson=@cJson,@cCodigoPermiso='RECURSOS_RETIRAR',@cAmbito='RECURSO_CANCELAR',@nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@nOperacionIdempotenteId=@nOp OUTPUT,@bEsRepetida=@bRep OUTPUT,@cEstadoOperacion=@cEstadoOp OUTPUT,@cIdentificadorResultado=@cIdRes OUTPUT,@cCodigoResultado=@cCodRes OUTPUT,@bResultado=@bIni OUTPUT,@cMensaje=@cMsg OUTPUT;
IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
GOTO __DESCO_Salida;
END;
IF @bRep=1 BEGIN SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
SET @cMensaje=CASE WHEN @cEstadoOp='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.' ELSE N'La solicitud ya se encuentra en proceso.' END;
GOTO __DESCO_Salida;
END;
 SELECT @nId=recursoProgramadoId,@cMotivo=NULLIF(LTRIM(RTRIM(motivo)),N'') FROM OPENJSON(@cJson,'$.recurso') WITH(recursoProgramadoId BIGINT '$.recursoProgramadoId',motivo NVARCHAR(300) '$.motivo');
IF @cMotivo IS NULL OR NOT EXISTS(SELECT 1 FROM logistica.RecursoProgramado WHERE recurso_programado_id=@nId AND estado=1 AND estado_proceso='PROGRAMADO') BEGIN SET @cMensaje=N'La programación no está disponible para cancelación o falta indicar el motivo.';
GOTO Fallar;
END;
BEGIN TRY BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;
UPDATE logistica.RecursoProgramado SET estado_proceso='CANCELADO',fecha_cancelacion=SYSUTCDATETIME(),usuario_cancelacion_id=@nUsuario,motivo_cancelacion=@cMotivo WHERE recurso_programado_id=@nId;
SET @cIdent=CONVERT(NVARCHAR(200),@nId);
EXEC auditoria.PA_Operacion_Ins_RegistrarCambio @nUsuario,@nSesion,@nDisp,@nModulo,'CANCELAR','logistica','RecursoProgramado',@cIdent,NULL,NULL,@cMotivo,'estado_proceso','PROGRAMADO','CANCELADO',@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
/* Confirmar datos e idempotencia juntos. */EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='COMPLETADA',@cEsquemaEntidad='logistica',@cNombreEntidad='RecursoProgramado',@cIdentificadorResultado=@cIdent,@cCodigoResultado='RECURSO_CANCELADO',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado=1;
SET @cMensaje=N'Programación cancelada correctamente.';
GOTO __DESCO_Salida;
 END TRY BEGIN CATCH
SET @bResultado = 0;
 IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @cMensaje=N'No se pudo cancelar la programación. Intente nuevamente.';
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'logistica.PA_RecursoProgramado_Upd_Cancelar',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;
Fallar: IF @nOp IS NOT NULL AND @bResultado=0 EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='FALLIDA',@cEsquemaEntidad=NULL,@cNombreEntidad=NULL,@cIdentificadorResultado=NULL,@cCodigoResultado='NO_PROCESADO',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
 
    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'logistica.PA_RecursoProgramado_Upd_Cancelar',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

    IF @bResultado = 0 AND @nOp IS NOT NULL AND XACT_STATE() <> -1
    BEGIN
        IF ISNULL(@bRep,0) = 0
        BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                 @nOperacionIdempotenteId = @nOp, @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
            -- No sustituir el motivo funcional por un fallo de registro secundario.
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'logistica.PA_RecursoProgramado_Upd_Cancelar',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
        END CATCH;
        END
        ELSE
        BEGIN
            SELECT @cMensaje = COALESCE(mensaje_resultado,
                CASE WHEN estado_operacion = 'FALLIDA'
                     THEN N'La solicitud anterior no se completó. Corrija los datos y envíe una nueva solicitud.'
                     ELSE N'La solicitud todavía se está procesando. Consulte el resultado antes de repetirla.' END)
            FROM [auditoria].[OperacionIdempotente]
            WHERE operacion_idempotente_id = @nOp;
        END;
    END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'logistica.PA_RecursoProgramado_Upd_Cancelar',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'logistica.PA_RecursoProgramado_Upd_Cancelar',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- logistica.PA_RecursoProgramado_Upd_Registro
CREATE OR ALTER PROCEDURE [logistica].[PA_RecursoProgramado_Upd_Registro]
(
    @cJson NVARCHAR(MAX),
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,
        @gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),
        @nOperacion BIGINT,@bRepetida BIT,@cEstadoOperacion VARCHAR(20),@cIdResultado NVARCHAR(200),
        @cCodigoResultado VARCHAR(40),@bInicio BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),
        @nAud BIGINT,@nTrans BIGINT,
        @nId BIGINT,@nCantidad DECIMAL(14,3),@cObservacion NVARCHAR(300),
        @nCampania BIGINT,@nOperativo BIGINT,@nSalida BIGINT,@nBien BIGINT,@nSuministro BIGINT,
        @nStock DECIMAL(19,3),@bDestinoValido BIT,@cMensajeDestino NVARCHAR(300),@cIdentificador NVARCHAR(200);

    SELECT @bResultado=0,@cMensaje=N'No se pudo actualizar la programación.';

    EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente]
        @cJson=@cJson,@cCodigoPermiso='RECURSOS_EDITAR',@cAmbito='RECURSO_EDITAR',
        @nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,
        @nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,
        @gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,
        @nOperacionIdempotenteId=@nOperacion OUTPUT,@bEsRepetida=@bRepetida OUTPUT,
        @cEstadoOperacion=@cEstadoOperacion OUTPUT,@cIdentificadorResultado=@cIdResultado OUTPUT,
        @cCodigoResultado=@cCodigoResultado OUTPUT,@bResultado=@bInicio OUTPUT,@cMensaje=@cMsg OUTPUT;

    IF @bInicio=0 AND @bRepetida=0 BEGIN SET @cMensaje=@cMsg;
 GOTO __DESCO_Salida;
 END;
    IF @bRepetida=1
    BEGIN
        SET @bResultado=CASE WHEN @cEstadoOperacion='COMPLETADA' THEN 1 ELSE 0 END;
        SET @cMensaje=CASE WHEN @cEstadoOperacion='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.' ELSE N'La solicitud ya se encuentra en proceso.' END;
        GOTO __DESCO_Salida;
    END;

    SELECT
        @nId=recursoProgramadoId,
        @nCantidad=cantidadProgramada,
        @cObservacion=NULLIF(LTRIM(RTRIM(observacion)),N'')
    FROM OPENJSON(@cJson,'$.recurso')
    WITH
    (
        recursoProgramadoId BIGINT '$.recursoProgramadoId',
        cantidadProgramada DECIMAL(14,3) '$.cantidadProgramada',
        observacion NVARCHAR(300) '$.observacion'
    );

    SELECT
        @nCampania=campania_venta_id,@nOperativo=operativo_venta_id,@nSalida=salida_campo_id,
        @nBien=bien_inventario_id,@nSuministro=suministro_id
    FROM [logistica].[RecursoProgramado]
    WHERE recurso_programado_id=@nId AND estado=1 AND estado_proceso='PROGRAMADO';

    IF (@nBien IS NULL AND @nSuministro IS NULL)
       OR @nCantidad IS NULL OR @nCantidad<=0
       OR (@nBien IS NOT NULL AND @nCantidad<>1)
    BEGIN
        SET @cMensaje=N'La programación seleccionada no está disponible o la cantidad no es válida.';
        GOTO Fallar;
    END;

    EXEC [logistica].[PA_RecursoProgramado_Sel_ValidarDestinoInterno]
        @nCampaniaVentaId=@nCampania,
        @nOperativoVentaId=@nOperativo,
        @nSalidaCampoId=@nSalida,
        @cMomento='EDITAR',
        @bValido=@bDestinoValido OUTPUT,
        @cMensaje=@cMensajeDestino OUTPUT;

    IF @bDestinoValido=0
    BEGIN
        SET @cMensaje=N'La actividad asociada ya no permite modificar la programación.';
        GOTO Fallar;
    END;

    IF @nSuministro IS NOT NULL
    BEGIN
        EXEC [logistica].[PA_Suministro_Sel_StockInterno]
            @nSuministroId=@nSuministro,
            @nStock=NULL,@nDisponible=@nStock OUTPUT;
        SELECT @nStock=@nStock+CASE WHEN suministro_id=@nSuministro AND estado_proceso='PROGRAMADO' AND estado=1 THEN cantidad_programada ELSE 0 END FROM logistica.RecursoProgramado WHERE recurso_programado_id=@nId;
        IF @nCantidad>@nStock
        BEGIN
            SET @cMensaje=N'El suministro no tiene stock suficiente para la cantidad programada.';
            GOTO Fallar;
        END;
    END;

    BEGIN TRY
        BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

        UPDATE [logistica].[RecursoProgramado]
        SET cantidad_programada=@nCantidad,
            observacion=@cObservacion
        WHERE recurso_programado_id=@nId AND estado=1 AND estado_proceso='PROGRAMADO';

        IF @@ROWCOUNT<>1
        BEGIN
            BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
            SET @cMensaje=N'La programación cambió antes de completar la actualización.';
            GOTO Fallar;
        END;

        SET @cIdentificador=CONVERT(NVARCHAR(200),@nId);
        EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio]
            @nUsuarioId=@nUsuario,@nSesionUsuarioId=@nSesion,@nDispositivoUsuarioId=@nDisp,@nModuloId=@nModulo,
            @cAccion='EDITAR',@cEsquemaEntidad='logistica',@cNombreEntidad='RecursoProgramado',
            @cIdentificador=@cIdentificador,@cDatosAnteriores=NULL,@cDatosPosteriores=NULL,@cMotivo=NULL,
            @cCampoEstado=NULL,@cEstadoAnterior=NULL,@cEstadoNuevo=NULL,@cIp=@cIp,
            @gCorrelacionId=@gCorr,@gSolicitudId=@gSol,@cEndpoint=@cEnd,
            @nAuditoriaEventoId=@nAud OUTPUT,@nTransicionEstadoId=@nTrans OUTPUT;

        /* Confirmar datos e idempotencia juntos. */

        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
            @nOperacionIdempotenteId=@nOperacion,@cEstadoOperacion='COMPLETADA',
            @cEsquemaEntidad='logistica',@cNombreEntidad='RecursoProgramado',
            @cIdentificadorResultado=@cIdentificador,@cCodigoResultado='RECURSO_ACTUALIZADO',
            @bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;

        SET @bResultado=1;
        SET @cMensaje=N'Programación actualizada correctamente.';
        GOTO __DESCO_Salida;
    END TRY
    BEGIN CATCH
SET @bResultado = 0;

        IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
        SET @cMensaje=N'No se pudo actualizar la programación. Intente nuevamente.';
    
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'logistica.PA_RecursoProgramado_Upd_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;

Fallar:
    IF @nOperacion IS NOT NULL AND @bResultado=0
        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
            @nOperacionIdempotenteId=@nOperacion,@cEstadoOperacion='FALLIDA',
            @cEsquemaEntidad=NULL,@cNombreEntidad=NULL,@cIdentificadorResultado=NULL,
            @cCodigoResultado='NO_PROCESADO',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'logistica.PA_RecursoProgramado_Upd_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'logistica.PA_RecursoProgramado_Upd_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'logistica.PA_RecursoProgramado_Upd_Registro',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- logistica.PA_Suministro_Ins_Registro
CREATE OR ALTER PROCEDURE [logistica].[PA_Suministro_Ins_Registro](@cJson NVARCHAR(MAX),@nSuministroId BIGINT OUTPUT,@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY
  SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),@nAud BIGINT,@nTrans BIGINT,@cCodigo VARCHAR(40),@cNombre NVARCHAR(150),@cUnidad VARCHAR(20),@nStockInicial DECIMAL(14,3),@cIdent NVARCHAR(200);
SELECT @bResultado=0,@cMensaje=N'No se pudo registrar el suministro.';
EXEC seg.PA_Operacion_Ins_IniciarIdempotente @cJson=@cJson,@cCodigoPermiso='INVENTARIO_CREAR',@cAmbito='SUMINISTRO_CREAR',@nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@nOperacionIdempotenteId=@nOp OUTPUT,@bEsRepetida=@bRep OUTPUT,@cEstadoOperacion=@cEstadoOp OUTPUT,@cIdentificadorResultado=@cIdRes OUTPUT,@cCodigoResultado=@cCodRes OUTPUT,@bResultado=@bIni OUTPUT,@cMensaje=@cMsg OUTPUT;
IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
GOTO __DESCO_Salida;
END;
IF @bRep=1 BEGIN SET @nSuministroId=CASE WHEN @cEstadoOp='COMPLETADA' THEN TRY_CONVERT(BIGINT,@cIdRes) ELSE NULL END;
 SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
SET @cMensaje=CASE WHEN @cEstadoOp='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.' ELSE N'La solicitud ya se encuentra en proceso.' END;
GOTO __DESCO_Salida;
END;
 SET @nSuministroId=NULL;
SELECT @cCodigo=UPPER(NULLIF(LTRIM(RTRIM(codigo)),'')),@cNombre=NULLIF(LTRIM(RTRIM(nombre)),N''),@cUnidad=UPPER(NULLIF(LTRIM(RTRIM(unidadMedida)),'')),@nStockInicial=COALESCE(stockInicial,0) FROM OPENJSON(@cJson,'$.suministro') WITH(codigo VARCHAR(40) '$.codigo',nombre NVARCHAR(150) '$.nombre',unidadMedida VARCHAR(20) '$.unidadMedida',stockInicial DECIMAL(14,3) '$.stockInicial');
IF @cCodigo IS NULL
BEGIN
 DECLARE @auto BIGINT; SELECT @auto=NEXT VALUE FOR logistica.SEQ_CodigoAutomatico;
 SET @cCodigo='SUM-AUTO-'+CONVERT(VARCHAR(20),@auto);
END;
IF @cCodigo IS NULL OR @cNombre IS NULL OR @cUnidad IS NULL OR @nStockInicial<0 BEGIN SET @cMensaje=N'Complete correctamente los datos del suministro.';
GOTO Fallar;
END;
IF EXISTS(SELECT 1 FROM logistica.Suministro WHERE codigo=@cCodigo) BEGIN SET @cMensaje=N'El código de suministro ya se encuentra registrado.';
GOTO Fallar;
END;
BEGIN TRY BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;
INSERT logistica.Suministro(codigo,nombre,unidad_medida,estado) VALUES(@cCodigo,@cNombre,@cUnidad,1);
SET @nSuministroId=SCOPE_IDENTITY();
UPDATE logistica.Suministro SET stock_minimo=COALESCE(TRY_CONVERT(DECIMAL(19,3),JSON_VALUE(@cJson,'$.suministro.stockMinimo')),0) WHERE suministro_id=@nSuministroId;
IF @nStockInicial>0 INSERT logistica.SuministroMovimiento(suministro_id,recurso_programado_id,tipo_movimiento,cantidad,fecha_hora,usuario_id,documento_referencia,observacion,estado) VALUES(@nSuministroId,NULL,'ENTRADA',@nStockInicial,SYSUTCDATETIME(),@nUsuario,'STOCK_INICIAL',N'Stock inicial registrado con el suministro.',1);
SET @cIdent=CONVERT(NVARCHAR(200),@nSuministroId);
EXEC auditoria.PA_Operacion_Ins_RegistrarCambio @nUsuario,@nSesion,@nDisp,@nModulo,'CREAR','logistica','Suministro',@cIdent,NULL,NULL,NULL,NULL,NULL,NULL,@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
/* Confirmar datos e idempotencia juntos. */EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='COMPLETADA',@cEsquemaEntidad='logistica',@cNombreEntidad='Suministro',@cIdentificadorResultado=@cIdent,@cCodigoResultado='SUMINISTRO_CREADO',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado=1;
SET @cMensaje=N'Suministro registrado correctamente.';
GOTO __DESCO_Salida;
 END TRY BEGIN CATCH
SET @bResultado = 0;
 IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
