-- logistica.PA_SuministroMovimiento_Sel_Kardex
CREATE OR ALTER PROCEDURE [logistica].[PA_SuministroMovimiento_Sel_Kardex](@cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

 SET NOCOUNT ON;
 SELECT @bResultado=0,@cMensaje=N'No se pudo consultar la información.';
 BEGIN TRY
  DECLARE @vUsuario BIGINT,@vSesion BIGINT,@vDisp BIGINT,@vEmp BIGINT,@vModulo INT,
        @vCorr UNIQUEIDENTIFIER,@vSol UNIQUEIDENTIFIER,@vIp VARCHAR(64),@vEnd NVARCHAR(250),@vOk BIT,@vMsg NVARCHAR(300);
        EXEC seg.PA_Operacion_Sel_ContextoAutorizado @cJson=@cJson,@cCodigoPermiso=N'INVENTARIO_VER',
        @nUsuarioId=@vUsuario OUTPUT,@nSesionUsuarioId=@vSesion OUTPUT,@nDispositivoUsuarioId=@vDisp OUTPUT,
        @nEmpleadoId=@vEmp OUTPUT,@nModuloId=@vModulo OUTPUT,@gCorrelacionId=@vCorr OUTPUT,
        @gSolicitudId=@vSol OUTPUT,@cIp=@vIp OUTPUT,@cEndpoint=@vEnd OUTPUT,@bResultado=@vOk OUTPUT,@cMensaje=@vMsg OUTPUT;
        IF ISNULL(@vOk,0)=0 BEGIN SET @cMensaje=@vMsg; GOTO Salida; END;
  
  DECLARE @id BIGINT=TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.filtros.suministroId')),
   @desde DATETIME2(0)=TRY_CONVERT(DATETIME2(0),JSON_VALUE(@cJson,'$.filtros.fechaDesde')),
   @hasta DATE=TRY_CONVERT(DATE,JSON_VALUE(@cJson,'$.filtros.fechaHasta'));
  ;WITH K AS(
   SELECT M.*,SUM(CONVERT(DECIMAL(19,3),CASE WHEN M.tipo_movimiento IN('ENTRADA','DEVOLUCION','AJUSTE_ENTRADA') THEN M.cantidad ELSE -M.cantidad END))
    OVER(PARTITION BY M.suministro_id ORDER BY M.fecha_hora,M.suministro_movimiento_id ROWS UNBOUNDED PRECEDING) saldo,
    CASE WHEN M.tipo_movimiento IN('ENTRADA','DEVOLUCION','AJUSTE_ENTRADA') THEN M.cantidad ELSE CONVERT(DECIMAL(14,3),0) END entrada,
    CASE WHEN M.tipo_movimiento IN('SALIDA','AJUSTE_SALIDA') THEN M.cantidad ELSE CONVERT(DECIMAL(14,3),0) END salida
   FROM logistica.SuministroMovimiento M WHERE M.estado=1 AND (@id IS NULL OR M.suministro_id=@id))
  SELECT K.suministro_movimiento_id suministroMovimientoId,K.suministro_id suministroId,S.codigo,S.nombre,S.unidad_medida unidadMedida,
   K.recurso_programado_id recursoProgramadoId,K.tipo_movimiento tipoMovimiento,K.cantidad,K.fecha_hora fechaHora,
   K.documento_referencia documentoReferencia,K.observacion,U.nombre_usuario usuario,
   K.entrada,K.salida,K.saldo-K.entrada+K.salida saldoAnterior,K.saldo saldoAcumulado,
   K.movimiento_origen_id movimientoOrigenId,K.recurso_movimiento_id recursoMovimientoId,
   COUNT_BIG(*) OVER() totalRegistros
  FROM K JOIN logistica.Suministro S ON S.suministro_id=K.suministro_id
  LEFT JOIN seg.Usuario U ON U.usuario_id=K.usuario_id
  WHERE (@desde IS NULL OR K.fecha_hora>=@desde) AND (@hasta IS NULL OR K.fecha_hora<DATEADD(DAY,1,CONVERT(DATETIME2,@hasta)))
  ORDER BY K.fecha_hora DESC,K.suministro_movimiento_id DESC;

  SELECT @bResultado=1,@cMensaje=N'Kardex consultado.';
 END TRY
 BEGIN CATCH
  SET @bResultado=0;
  EXEC config.PA_Respuesta_ResolverError @cProcedimiento=N'logistica.PA_SuministroMovimiento_Sel_Kardex',@cMensaje=@cMensaje OUTPUT,@cJson=@cJson;
 END CATCH;
Salida:
 SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'logistica.PA_SuministroMovimiento_Sel_Kardex',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- logistica.PA_SuministroMovimiento_Upd_Anular
CREATE OR ALTER PROCEDURE [logistica].[PA_SuministroMovimiento_Upd_Anular]
(@cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

 SET NOCOUNT ON;
 SET XACT_ABORT ON;
 DECLARE @vUsuario BIGINT,@vSesion BIGINT,@vDisp BIGINT,@vEmpleado BIGINT,@vModulo INT,
 @vCorr UNIQUEIDENTIFIER,@vSol UNIQUEIDENTIFIER,@vIp VARCHAR(64),@vEndpoint NVARCHAR(250),
 @vOperacion BIGINT,@vRepetida BIT=0,@vEstado VARCHAR(20),@vId NVARCHAR(200),@vCodigo VARCHAR(40),
 @vOk BIT,@vMsg NVARCHAR(300),@vAud BIGINT,@vTrans BIGINT,
 @vTranEntrada INT=@@TRANCOUNT,@vTranAbierta BIT=0,
 @vSave VARCHAR(32)=REPLACE(CONVERT(VARCHAR(36),NEWID()),'-','');
 SELECT @bResultado=0,@cMensaje=N'No se pudo completar la acción.';
 
 BEGIN TRY
  EXEC seg.PA_Operacion_Ins_IniciarIdempotente
   @cJson=@cJson,@cCodigoPermiso=N'INVENTARIO_EDITAR',@cAmbito=N'SUMINISTRO_ANULAR',
   @nUsuarioId=@vUsuario OUTPUT,@nSesionUsuarioId=@vSesion OUTPUT,@nDispositivoUsuarioId=@vDisp OUTPUT,
   @nEmpleadoId=@vEmpleado OUTPUT,@nModuloId=@vModulo OUTPUT,@gCorrelacionId=@vCorr OUTPUT,
   @gSolicitudId=@vSol OUTPUT,@cIp=@vIp OUTPUT,@cEndpoint=@vEndpoint OUTPUT,
   @nOperacionIdempotenteId=@vOperacion OUTPUT,@bEsRepetida=@vRepetida OUTPUT,
   @cEstadoOperacion=@vEstado OUTPUT,@cIdentificadorResultado=@vId OUTPUT,
   @cCodigoResultado=@vCodigo OUTPUT,@bResultado=@vOk OUTPUT,@cMensaje=@vMsg OUTPUT;
  IF ISNULL(@vOk,0)=0 AND ISNULL(@vRepetida,0)=0
  BEGIN SET @cMensaje=@vMsg; GOTO Salida; END;
  IF @vRepetida=1
  BEGIN
   
   SET @bResultado=CASE WHEN @vEstado='COMPLETADA' THEN 1 ELSE 0 END;
   SET @cMensaje=CASE WHEN @vEstado='COMPLETADA' THEN N'Movimiento anulado.' ELSE N'La acción está en proceso.' END;
   IF @vEstado='FALLIDA'
    SELECT @cMensaje=COALESCE(mensaje_resultado,N'La acción anterior no se completó.')
    FROM auditoria.OperacionIdempotente WHERE operacion_idempotente_id=@vOperacion;
   GOTO Salida;
  END;
  IF @vTranEntrada=0 BEGIN TRANSACTION; ELSE SAVE TRANSACTION @vSave;
  SET @vTranAbierta=1;

  DECLARE @id BIGINT=TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.movimiento.suministroMovimientoId')),
   @sum BIGINT,@cantidad DECIMAL(14,3),@tipo VARCHAR(20),@origen BIGINT,@recurso BIGINT,
   @motivo NVARCHAR(300)=NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.movimiento.motivo'))),N'');
  IF @motivo IS NULL THROW 51000,N'Indique el motivo de la anulación.',1;
  SELECT @sum=suministro_id,@cantidad=cantidad,@tipo=tipo_movimiento,@origen=movimiento_origen_id,@recurso=recurso_programado_id
  FROM logistica.SuministroMovimiento WITH(UPDLOCK,HOLDLOCK) WHERE suministro_movimiento_id=@id AND estado=1;
  IF @sum IS NULL OR @origen IS NOT NULL OR @recurso IS NOT NULL
   THROW 51100,N'DESCO_REVERSION_NO_VALIDA',1;
  IF EXISTS(SELECT 1 FROM logistica.SuministroMovimiento WITH(UPDLOCK,HOLDLOCK) WHERE movimiento_origen_id=@id)
   THROW 51000,N'El movimiento ya fue anulado.',1;
  INSERT logistica.SuministroMovimiento(suministro_id,movimiento_origen_id,tipo_movimiento,cantidad,fecha_hora,usuario_id,observacion,estado)
  VALUES(@sum,@id,CASE WHEN @tipo IN('ENTRADA','DEVOLUCION','AJUSTE_ENTRADA') THEN 'AJUSTE_SALIDA' ELSE 'AJUSTE_ENTRADA' END,
   @cantidad,SYSUTCDATETIME(),@vUsuario,@motivo,1);
  SET @vId=CONVERT(NVARCHAR(200),@id);

  EXEC auditoria.PA_Operacion_Ins_RegistrarCambio
   @nUsuarioId=@vUsuario,@nSesionUsuarioId=@vSesion,@nDispositivoUsuarioId=@vDisp,@nModuloId=@vModulo,
   @cAccion=N'SUMINISTRO_ANULAR',@cEsquemaEntidad=N'logistica',@cNombreEntidad=N'SuministroMovimiento',@cIdentificador=@vId,
   @cIp=@vIp,@gCorrelacionId=@vCorr,@gSolicitudId=@vSol,@cEndpoint=@vEndpoint,
   @nAuditoriaEventoId=@vAud OUTPUT,@nTransicionEstadoId=@vTrans OUTPUT;
  EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar
   @nOperacionIdempotenteId=@vOperacion,@cEstadoOperacion='COMPLETADA',
   @cEsquemaEntidad=N'logistica',@cNombreEntidad=N'SuministroMovimiento',@cIdentificadorResultado=@vId,
   @cCodigoResultado=N'SUMINISTRO_ANULAR',@bResultado=@vOk OUTPUT,@cMensaje=@vMsg OUTPUT;
  IF ISNULL(@vOk,0)=0 THROW 51003,N'DESCO_IDEMPOTENCIA_NO_CERRADA',1;
  IF @vTranEntrada=0 COMMIT TRANSACTION;
  SET @vTranAbierta=0;
  SELECT @bResultado=1,@cMensaje=N'Movimiento anulado.';
 END TRY
 BEGIN CATCH
  IF @vTranAbierta=1
  BEGIN
   IF @vTranEntrada=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
   ELSE IF @vTranEntrada>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION @vSave;
   SET @vTranAbierta=0;
  END;
  SET @bResultado=0;
  EXEC config.PA_Respuesta_ResolverError @cProcedimiento=N'logistica.PA_SuministroMovimiento_Upd_Anular',@cMensaje=@cMensaje OUTPUT,@cJson=@cJson;
 END CATCH;
Salida:
 IF @bResultado=0 AND @vOperacion IS NOT NULL AND ISNULL(@vRepetida,0)=0 AND XACT_STATE()<>-1
 BEGIN TRY
  EXEC auditoria.PA_OperacionIdempotente_Upd_MensajeFallido @vOperacion,@cMensaje;
 END TRY
 BEGIN CATCH
  SET @bResultado=0;
 END CATCH;
 
 SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'logistica.PA_SuministroMovimiento_Upd_Anular',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE logistica.PA_SuministroUOT_Ins_Movimiento
 @nUsuarioId BIGINT,@nSesionUsuarioId BIGINT,@nUotId BIGINT,@nSuministroId BIGINT,@cTipo VARCHAR(30),@nCantidad DECIMAL(19,3),@cDocumento NVARCHAR(120)=NULL,@cObservacion NVARCHAR(300)=NULL,
 @nMovimientoId BIGINT OUTPUT,@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,@cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON; SELECT @nMovimientoId=NULL,@bResultado=0,@cMensaje=N'No se pudo registrar el movimiento.',@cCodigoRespuesta='SUMINISTRO_MOVIMIENTO_NO_CREADO',@nHttpRespuesta=400;
 DECLARE @Uot BIGINT=@nUotId,@General BIT,@Ok BIT,@Msg NVARCHAR(300); EXEC seg.PA_UOT_Sel_ResolverContextoSesion @nUsuarioId,@nSesionUsuarioId,@Uot,'INVENTARIO_EDITAR',1,@Uot OUTPUT,@General OUTPUT,@Ok OUTPUT,@Msg OUTPUT;
 IF @Ok=0 BEGIN SET @cMensaje=@Msg; RETURN 1; END;
 SET @cTipo=UPPER(NULLIF(LTRIM(RTRIM(@cTipo)),''));
 IF @cTipo NOT IN('ENTRADA','AJUSTE_ENTRADA','AJUSTE_SALIDA') OR @nCantidad IS NULL OR @nCantidad<=0 BEGIN SET @cMensaje=N'El movimiento no es valido.'; RETURN 1; END;
 IF NOT EXISTS(SELECT 1 FROM logistica.Suministro WHERE suministro_id=@nSuministroId AND uot_id=@Uot AND estado=1) BEGIN SET @cMensaje=N'El suministro no esta disponible en la UOT.'; SET @nHttpRespuesta=404; RETURN 1; END;
 DECLARE @Disponible DECIMAL(19,3)=COALESCE((SELECT stock_disponible FROM logistica.SuministroSaldo WHERE suministro_id=@nSuministroId),0);
 IF @cTipo='AJUSTE_SALIDA' AND @nCantidad>@Disponible BEGIN SET @cMensaje=N'La cantidad supera el stock disponible.'; SET @cCodigoRespuesta='STOCK_INSUFICIENTE'; SET @nHttpRespuesta=409; RETURN 1; END;
 BEGIN TRY
  INSERT logistica.SuministroMovimiento(suministro_id,uot_id,recurso_programado_id,tipo_movimiento,cantidad,fecha_hora,usuario_id,documento_referencia,observacion,estado)
  VALUES(@nSuministroId,@Uot,NULL,@cTipo,@nCantidad,SYSUTCDATETIME(),@nUsuarioId,NULLIF(LTRIM(RTRIM(@cDocumento)),N''),NULLIF(LTRIM(RTRIM(@cObservacion)),N''),1);
  SET @nMovimientoId=SCOPE_IDENTITY(); SELECT @bResultado=1,@cMensaje=N'Movimiento registrado.',@cCodigoRespuesta='SUMINISTRO_MOVIMIENTO_CREADO',@nHttpRespuesta=201; RETURN 0;
 END TRY BEGIN CATCH SET @nMovimientoId=NULL; SET @cMensaje=N'No se pudo registrar el movimiento.'; RETURN 1; END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [logistica].[PA_SuministroUOT_Ins_Registro]
    @nUsuarioId BIGINT,
    @nSesionUsuarioId BIGINT,
    @nUotId BIGINT,
    @cCodigo VARCHAR(40),
    @cNombre NVARCHAR(150),
    @cUnidad VARCHAR(20),
    @nStockInicial DECIMAL(19,3) = 0,
    @nStockMinimo DECIMAL(19,3) = 0,
    @nSuministroId BIGINT OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60) = NULL OUTPUT,
    @nHttpRespuesta SMALLINT = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SELECT
        @nSuministroId = NULL,
        @bResultado = 0,
        @cMensaje = N'No se pudo registrar el suministro.',
        @cCodigoRespuesta = 'SUMINISTRO_NO_CREADO',
        @nHttpRespuesta = 400;

    DECLARE
        @nUotResuelta BIGINT = @nUotId,
        @bModoGeneral BIT,
        @bContextoOk BIT,
        @cMensajeContexto NVARCHAR(300);

    EXEC [seg].[PA_UOT_Sel_ResolverContextoSesion]
        @nUsuarioId = @nUsuarioId,
        @nSesionUsuarioId = @nSesionUsuarioId,
        @nUotSolicitada = @nUotResuelta,
        @cCodigoPermiso = 'INVENTARIO_CREAR',
        @bRequiereUot = 1,
        @nUotId = @nUotResuelta OUTPUT,
        @bModoGeneral = @bModoGeneral OUTPUT,
        @bResultado = @bContextoOk OUTPUT,
        @cMensaje = @cMensajeContexto OUTPUT;

    IF ISNULL(@bContextoOk, 0) = 0
    BEGIN
        SET @cMensaje = COALESCE(NULLIF(@cMensajeContexto, N''), @cMensaje);
        RETURN 1;
    END;

    SET @cCodigo = UPPER(NULLIF(LTRIM(RTRIM(@cCodigo)), ''));
    SET @cNombre = NULLIF(LTRIM(RTRIM(@cNombre)), N'');
    SET @cUnidad = UPPER(NULLIF(LTRIM(RTRIM(@cUnidad)), ''));
    SET @nStockInicial = COALESCE(@nStockInicial, 0);
    SET @nStockMinimo = COALESCE(@nStockMinimo, 0);

    /* El código definitivo depende del ID. */
    SET @cCodigo =
        CONCAT(
            'TMP-S-',
            REPLACE(CONVERT(VARCHAR(36), NEWID()), '-', '')
        );

    IF @cNombre IS NULL OR @cUnidad IS NULL
       OR @nStockInicial < 0 OR @nStockMinimo < 0
    BEGIN
        SET @cMensaje = N'Complete correctamente los datos del suministro.';
        RETURN 1;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [config].[CatalogoRecursoValor]
        WHERE catalogo = 'UNIDAD_MEDIDA'
          AND codigo = @cUnidad
          AND estado = 1
    )
    BEGIN
        SET @cMensaje = N'La unidad de medida seleccionada no está disponible.';
        RETURN 1;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM [logistica].[Suministro]
        WHERE uot_id = @nUotResuelta
          AND codigo = @cCodigo
    )
    BEGIN
        SELECT
            @cMensaje = N'El código del suministro ya está registrado en esta UOT.',
            @cCodigoRespuesta = 'SUMINISTRO_DUPLICADO',
            @nHttpRespuesta = 409;
        RETURN 1;
    END;

    BEGIN TRY
        BEGIN TRANSACTION;

        INSERT INTO [logistica].[Suministro]
        (
            uot_id,
            codigo,
            nombre,
            unidad_medida,
            estado,
            stock_minimo
        )
        VALUES
        (
            @nUotResuelta,
            @cCodigo,
            @cNombre,
            @cUnidad,
            1,
            @nStockMinimo
        );

        SET @nSuministroId = CONVERT(BIGINT, SCOPE_IDENTITY());

        SET @cCodigo =
            [logistica].[FN_CodigoRecursoUOT]
            (
                @nUotResuelta,
                @cNombre,
                @nSuministroId
            );

        UPDATE [logistica].[Suministro]
           SET codigo = @cCodigo
         WHERE suministro_id = @nSuministroId;


        IF @nStockInicial > 0
        BEGIN
            INSERT INTO [logistica].[SuministroMovimiento]
            (
                suministro_id,
                uot_id,
                recurso_programado_id,
                tipo_movimiento,
                cantidad,
                fecha_hora,
                usuario_id,
                documento_referencia,
                observacion,
                estado
            )
            VALUES
            (
                @nSuministroId,
                @nUotResuelta,
                NULL,
                'ENTRADA',
                @nStockInicial,
                SYSUTCDATETIME(),
                @nUsuarioId,
                N'STOCK_INICIAL',
                N'Stock inicial.',
                1
            );
        END
        ELSE IF NOT EXISTS
        (
            SELECT 1
            FROM [logistica].[SuministroSaldo]
            WHERE suministro_id = @nSuministroId
        )
        BEGIN
            INSERT INTO [logistica].[SuministroSaldo]
            (
                suministro_id,
                stock_actual,
                stock_reservado,
                fecha_actualizacion
            )
            VALUES
            (
                @nSuministroId,
                0,
                0,
                SYSUTCDATETIME()
            );
        END;

        COMMIT TRANSACTION;

        SELECT
            @bResultado = 1,
            @cMensaje = N'Suministro registrado correctamente.',
            @cCodigoRespuesta = 'SUMINISTRO_CREADO',
            @nHttpRespuesta = 201;

        RETURN 0;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        SET @nSuministroId = NULL;
        SET @bResultado = 0;

        IF ERROR_NUMBER() IN (2601, 2627)
        BEGIN
            SELECT
                @cMensaje = N'El código del suministro ya está registrado en esta UOT.',
                @cCodigoRespuesta = 'SUMINISTRO_DUPLICADO',
                @nHttpRespuesta = 409;
        END
        ELSE
        BEGIN
            SELECT
                @cMensaje = N'No se pudo registrar el suministro. Revise los datos e intente nuevamente.',
                @cCodigoRespuesta = 'SUMINISTRO_NO_CREADO',
                @nHttpRespuesta = 400;
        END;

        RETURN 1;
    END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE logistica.PA_SuministroUOT_Sel_Kardex
 @nUsuarioId BIGINT,@nSesionUsuarioId BIGINT,@nUotId BIGINT=NULL,@nSuministroId BIGINT=NULL,
 @bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,@cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SELECT @bResultado=0,@cMensaje=N'No se pudo consultar el Kardex.',@cCodigoRespuesta='KARDEX_NO_DISPONIBLE',@nHttpRespuesta=400;
 DECLARE @Uot BIGINT=@nUotId,@General BIT,@Ok BIT,@Msg NVARCHAR(300); EXEC seg.PA_UOT_Sel_ResolverContextoSesion @nUsuarioId,@nSesionUsuarioId,@Uot,'INVENTARIO_VER',0,@Uot OUTPUT,@General OUTPUT,@Ok OUTPUT,@Msg OUTPUT;
 IF @Ok=0 BEGIN SET @cMensaje=@Msg; RETURN 1; END;
 ;WITH K AS(
  SELECT M.*,SUM(CONVERT(DECIMAL(19,3),CASE WHEN M.estado=1 THEN CASE WHEN M.tipo_movimiento IN('ENTRADA','DEVOLUCION','AJUSTE_ENTRADA','TRANSFERENCIA_ENTRADA') THEN M.cantidad ELSE -M.cantidad END ELSE 0 END))
   OVER(PARTITION BY M.suministro_id ORDER BY M.fecha_hora,M.suministro_movimiento_id ROWS UNBOUNDED PRECEDING) saldo
  FROM logistica.SuministroMovimiento M
 )
 SELECT K.suministro_movimiento_id suministroMovimientoId,K.suministro_id suministroId,K.uot_id uotId,U.codigo uotCodigo,U.nombre uotNombre,
        S.codigo,S.nombre,S.unidad_medida unidadMedida,K.recurso_programado_id recursoProgramadoId,K.tipo_movimiento tipoMovimiento,K.cantidad,K.fecha_hora fechaHora,
        K.documento_referencia documentoReferencia,K.observacion,US.nombre_usuario usuario,K.saldo
 FROM K JOIN logistica.Suministro S ON S.suministro_id=K.suministro_id JOIN org.UOT U ON U.uot_id=K.uot_id LEFT JOIN seg.Usuario US ON US.usuario_id=K.usuario_id
 WHERE K.estado=1 AND (@nSuministroId IS NULL OR K.suministro_id=@nSuministroId)
   AND ((@General=0 AND K.uot_id=@Uot) OR (@General=1 AND (@Uot IS NULL OR K.uot_id=@Uot) AND seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,K.uot_id,'INVENTARIO_VER')=1))
 ORDER BY K.fecha_hora DESC,K.suministro_movimiento_id DESC;
 SELECT @bResultado=1,@cMensaje=N'Kardex consultado.',@cCodigoRespuesta='KARDEX_CONSULTADO',@nHttpRespuesta=200; RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* ----------------------------------------------------------------------------
   1. Paginación de suministros
   El frontend consulta listAll con 200 registros. El límite contractual queda
   alineado en 500 para evitar que Bean Validation y SQL discrepen.
   ---------------------------------------------------------------------------- */
CREATE OR ALTER PROCEDURE [logistica].[PA_SuministroUOT_Sel_Listado]
    @nUsuarioId BIGINT,
    @nSesionUsuarioId BIGINT,
    @nUotId BIGINT = NULL,
    @nPagina INT = 1,
    @nTamano INT = 20,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60) = NULL OUTPUT,
    @nHttpRespuesta SMALLINT = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        @bResultado = 0,
        @cMensaje = N'No se pudieron consultar los suministros.',
        @cCodigoRespuesta = 'SUMINISTROS_NO_LISTADOS',
        @nHttpRespuesta = 400;

    SET @nPagina = CASE WHEN ISNULL(@nPagina, 0) < 1 THEN 1 ELSE @nPagina END;
    SET @nTamano = CASE
        WHEN ISNULL(@nTamano, 0) < 1 THEN 20
        WHEN @nTamano > 500 THEN 500
        ELSE @nTamano
    END;

    DECLARE
        @nUotResuelta BIGINT = @nUotId,
        @bModoGeneral BIT,
        @bOk BIT,
        @cMsg NVARCHAR(300);

    EXEC [seg].[PA_UOT_Sel_ResolverContextoSesion]
        @nUsuarioId = @nUsuarioId,
        @nSesionUsuarioId = @nSesionUsuarioId,
        @nUotSolicitada = @nUotResuelta,
        @cCodigoPermiso = 'INVENTARIO_LISTAR',
        @bRequiereUot = 0,
        @nUotId = @nUotResuelta OUTPUT,
        @bModoGeneral = @bModoGeneral OUTPUT,
        @bResultado = @bOk OUTPUT,
        @cMensaje = @cMsg OUTPUT;

    IF ISNULL(@bOk, 0) = 0
    BEGIN
        SET @cMensaje = COALESCE(NULLIF(@cMsg, N''), @cMensaje);
        RETURN 1;
    END;

    SELECT
        S.suministro_id AS suministroId,
        S.uot_id AS uotId,
        U.codigo AS uotCodigo,
        U.nombre AS uotNombre,
        S.codigo,
        S.nombre,
        S.unidad_medida AS unidadMedida,
        S.estado,
        COALESCE(K.stock_actual, 0) AS stock,
        COALESCE(K.stock_actual, 0) AS stockActual,
        COALESCE(K.stock_reservado, 0) AS stockReservado,
        COALESCE(K.stock_disponible, 0) AS stockDisponible,
        S.stock_minimo AS stockMinimo,
        CONVERT(
            BIT,
            CASE
                WHEN COALESCE(K.stock_disponible, 0) <= S.stock_minimo THEN 1
                ELSE 0
            END
        ) AS requiereReposicion,
        COUNT_BIG(*) OVER() AS totalRegistros
    FROM [logistica].[Suministro] S
    INNER JOIN [org].[UOT] U
        ON U.uot_id = S.uot_id
    LEFT JOIN [logistica].[SuministroSaldo] K
        ON K.suministro_id = S.suministro_id
    WHERE
        S.estado = 1
        AND U.estado = 1
        AND
        (
            (@bModoGeneral = 0 AND S.uot_id = @nUotResuelta)
            OR
            (
                @bModoGeneral = 1
                AND (@nUotResuelta IS NULL OR S.uot_id = @nUotResuelta)
                AND [seg].[FN_Usuario_TienePermisoUOT](
                    @nUsuarioId,
                    S.uot_id,
                    'INVENTARIO_LISTAR'
                ) = 1
            )
        )
    ORDER BY U.nombre, S.nombre, S.suministro_id
    OFFSET (@nPagina - 1) * @nTamano ROWS
    FETCH NEXT @nTamano ROWS ONLY;

    SELECT
        @bResultado = 1,
        @cMensaje = N'Suministros consultados.',
        @cCodigoRespuesta = 'SUMINISTROS_LISTADOS',
        @nHttpRespuesta = 200;

    RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE logistica.PA_SuministroUOT_Upd_AnularMovimiento
 @nUsuarioId BIGINT,@nSesionUsuarioId BIGINT,@nUotId BIGINT,@nMovimientoId BIGINT,@cMotivo NVARCHAR(300),
 @bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,@cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SELECT @bResultado=0,@cMensaje=N'No se pudo anular el movimiento.',@cCodigoRespuesta='SUMINISTRO_MOVIMIENTO_NO_ANULADO',@nHttpRespuesta=400;
 DECLARE @Uot BIGINT=@nUotId,@General BIT,@Ok BIT,@Msg NVARCHAR(300); EXEC seg.PA_UOT_Sel_ResolverContextoSesion @nUsuarioId,@nSesionUsuarioId,@Uot,'INVENTARIO_EDITAR',1,@Uot OUTPUT,@General OUTPUT,@Ok OUTPUT,@Msg OUTPUT;
 IF @Ok=0 BEGIN SET @cMensaje=@Msg; RETURN 1; END;
 SET @cMotivo=NULLIF(LTRIM(RTRIM(@cMotivo)),N''); IF @cMotivo IS NULL BEGIN SET @cMensaje=N'Indique el motivo de anulacion.'; RETURN 1; END;
 IF NOT EXISTS(SELECT 1 FROM logistica.SuministroMovimiento WHERE suministro_movimiento_id=@nMovimientoId AND uot_id=@Uot AND estado=1 AND recurso_programado_id IS NULL AND tipo_movimiento NOT IN('TRANSFERENCIA_ENTRADA','TRANSFERENCIA_SALIDA'))
 BEGIN SET @cMensaje=N'El movimiento no esta disponible para anulacion.'; SET @nHttpRespuesta=404; RETURN 1; END;
 UPDATE logistica.SuministroMovimiento SET estado=0,observacion=CONCAT(COALESCE(observacion,N''),CASE WHEN observacion IS NULL THEN N'' ELSE N' | ' END,N'ANULADO: ',@cMotivo) WHERE suministro_movimiento_id=@nMovimientoId;
 SELECT @bResultado=1,@cMensaje=N'Movimiento anulado.',@cCodigoRespuesta='SUMINISTRO_MOVIMIENTO_ANULADO',@nHttpRespuesta=200; RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE logistica.PA_SuministroUOT_Upd_Registro
 @nUsuarioId BIGINT,@nSesionUsuarioId BIGINT,@nUotId BIGINT,@nSuministroId BIGINT,@cNombre NVARCHAR(150),@cUnidad VARCHAR(20),@nStockMinimo DECIMAL(19,3)=NULL,
 @bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,@cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SELECT @bResultado=0,@cMensaje=N'No se pudo actualizar el suministro.',@cCodigoRespuesta='SUMINISTRO_NO_ACTUALIZADO',@nHttpRespuesta=400;
 DECLARE @Uot BIGINT=@nUotId,@General BIT,@Ok BIT,@Msg NVARCHAR(300); EXEC seg.PA_UOT_Sel_ResolverContextoSesion @nUsuarioId,@nSesionUsuarioId,@Uot,'INVENTARIO_EDITAR',1,@Uot OUTPUT,@General OUTPUT,@Ok OUTPUT,@Msg OUTPUT;
 IF @Ok=0 BEGIN SET @cMensaje=@Msg; RETURN 1; END;
 SET @cNombre=NULLIF(LTRIM(RTRIM(@cNombre)),N''); SET @cUnidad=UPPER(NULLIF(LTRIM(RTRIM(@cUnidad)),''));
 IF @cNombre IS NULL OR @cUnidad IS NULL OR (@nStockMinimo IS NOT NULL AND @nStockMinimo<0) BEGIN SET @cMensaje=N'Complete correctamente los datos del suministro.'; RETURN 1; END;
 UPDATE logistica.Suministro SET nombre=@cNombre,unidad_medida=@cUnidad,stock_minimo=COALESCE(@nStockMinimo,stock_minimo) WHERE suministro_id=@nSuministroId AND uot_id=@Uot AND estado=1;
 IF @@ROWCOUNT=0 BEGIN SET @cMensaje=N'El suministro no esta disponible en la UOT.'; SET @nHttpRespuesta=404; RETURN 1; END;
 SELECT @bResultado=1,@cMensaje=N'Suministro actualizado.',@cCodigoRespuesta='SUMINISTRO_ACTUALIZADO',@nHttpRespuesta=200; RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE logistica.PA_UOT_Ins_TransferirRecursos
 @nUsuarioId BIGINT,@nUotOrigenId BIGINT,@nUotDestinoId BIGINT,@nAlmacenOrigenId BIGINT=NULL,@nAlmacenDestinoId BIGINT=NULL,
 @bTransferirStock BIT=0,@cBienesJson NVARCHAR(MAX)=N'[]',@cSuministrosJson NVARCHAR(MAX)=N'[]',@gClaveIdempotencia UNIQUEIDENTIFIER,@cMotivo NVARCHAR(500),
 @nMovimientoSalidaId BIGINT OUTPUT,@nMovimientoEntradaId BIGINT OUTPUT,@nProductosTransferidos INT OUTPUT,@nBienesTransferidos INT OUTPUT,@nSuministrosTransferidos INT OUTPUT,
 @bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,@cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 SELECT @nMovimientoSalidaId=NULL,@nMovimientoEntradaId=NULL,@nProductosTransferidos=0,@nBienesTransferidos=0,@nSuministrosTransferidos=0,@bResultado=0,@cMensaje=N'No se pudieron transferir los recursos.',@cCodigoRespuesta='UOT_RECURSOS_NO_TRANSFERIDOS',@nHttpRespuesta=400;
 SET @cMotivo=NULLIF(LTRIM(RTRIM(@cMotivo)),N'');
 IF @nUotOrigenId=@nUotDestinoId BEGIN SET @cMensaje=N'Seleccione una UOT de destino diferente.'; RETURN 1; END;
 IF @cMotivo IS NULL OR @gClaveIdempotencia IS NULL BEGIN SET @cMensaje=N'Complete los datos de la transferencia.'; RETURN 1; END;
 IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotOrigenId,'UOT_RETIRAR')=0 OR seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotDestinoId,'UOT_EDITAR')=0 BEGIN SET @cMensaje=N'No tiene permiso para transferir entre estas UOT.'; RETURN 1; END;
 IF NOT EXISTS(SELECT 1 FROM org.UOT WHERE uot_id=@nUotDestinoId AND estado=1) BEGIN SET @cMensaje=N'La UOT de destino no esta disponible.'; RETURN 1; END;
 SET @cBienesJson=COALESCE(@cBienesJson,N'[]'); SET @cSuministrosJson=COALESCE(@cSuministrosJson,N'[]');
 IF ISJSON(@cBienesJson)<>1 OR ISJSON(@cSuministrosJson)<>1 BEGIN SET @cMensaje=N'La seleccion de recursos no es valida.'; RETURN 1; END;
 IF @bTransferirStock=1
 BEGIN
   IF @nAlmacenOrigenId IS NULL OR @nAlmacenDestinoId IS NULL BEGIN SET @cMensaje=N'Seleccione los almacenes para transferir stock.'; RETURN 1; END;
   IF NOT EXISTS(SELECT 1 FROM logistica.Almacen WHERE almacen_id=@nAlmacenOrigenId AND uot_propietaria_id=@nUotOrigenId AND estado=1) OR NOT EXISTS(SELECT 1 FROM logistica.Almacen WHERE almacen_id=@nAlmacenDestinoId AND uot_propietaria_id=@nUotDestinoId AND estado=1) BEGIN SET @cMensaje=N'Los almacenes no corresponden a las UOT seleccionadas.'; RETURN 1; END;
   IF EXISTS(SELECT 1 FROM logistica.AlmacenProductoStock WHERE almacen_id=@nAlmacenOrigenId AND stock_reservado<>0) BEGIN SET @cMensaje=N'Libere las reservas de stock antes de transferir.'; RETURN 1; END;
 END;
 DECLARE @Bienes TABLE(id BIGINT PRIMARY KEY); INSERT @Bienes SELECT DISTINCT TRY_CONVERT(BIGINT,[value]) FROM OPENJSON(@cBienesJson) WHERE TRY_CONVERT(BIGINT,[value]) IS NOT NULL;
 DECLARE @Suministros TABLE(id BIGINT PRIMARY KEY); INSERT @Suministros SELECT DISTINCT TRY_CONVERT(BIGINT,[value]) FROM OPENJSON(@cSuministrosJson) WHERE TRY_CONVERT(BIGINT,[value]) IS NOT NULL;
 IF @bTransferirStock=0 AND NOT EXISTS(SELECT 1 FROM @Bienes) AND NOT EXISTS(SELECT 1 FROM @Suministros) BEGIN SET @cMensaje=N'Seleccione recursos para transferir.'; RETURN 1; END;
 IF EXISTS(SELECT 1 FROM @Bienes X LEFT JOIN logistica.BienInventario B ON B.bien_inventario_id=X.id AND B.uot_id=@nUotOrigenId AND B.estado=1 WHERE B.bien_inventario_id IS NULL) BEGIN SET @cMensaje=N'Uno de los bienes no pertenece a la UOT de origen.'; RETURN 1; END;
 IF EXISTS(SELECT 1 FROM @Bienes X JOIN logistica.RecursoProgramado RP ON RP.bien_inventario_id=X.id AND RP.estado=1 AND RP.estado_proceso NOT IN('COMPLETADO','CANCELADO')) BEGIN SET @cMensaje=N'Hay bienes asignados a actividades pendientes.'; RETURN 1; END;
 IF EXISTS(SELECT 1 FROM @Suministros X LEFT JOIN logistica.Suministro S ON S.suministro_id=X.id AND S.uot_id=@nUotOrigenId AND S.estado=1 WHERE S.suministro_id IS NULL) BEGIN SET @cMensaje=N'Uno de los suministros no pertenece a la UOT de origen.'; RETURN 1; END;
 IF EXISTS(SELECT 1 FROM @Suministros X JOIN logistica.SuministroSaldo K ON K.suministro_id=X.id WHERE K.stock_reservado<>0) BEGIN SET @cMensaje=N'Libere las reservas de suministros antes de transferir.'; RETURN 1; END;
 IF EXISTS(SELECT 1 FROM @Suministros X JOIN logistica.RecursoProgramado RP ON RP.suministro_id=X.id AND RP.estado=1 AND RP.estado_proceso NOT IN('COMPLETADO','CANCELADO')) BEGIN SET @cMensaje=N'Hay suministros asignados a actividades pendientes.'; RETURN 1; END;
 BEGIN TRY
  SET TRANSACTION ISOLATION LEVEL SERIALIZABLE; BEGIN TRAN;
  IF @bTransferirStock=1 AND EXISTS(SELECT 1 FROM logistica.AlmacenProductoStock WHERE almacen_id=@nAlmacenOrigenId AND stock_actual>0)
  BEGIN
    DECLARE @gEntrada UNIQUEIDENTIFIER=NEWID(),@Ahora DATETIME2(0)=SYSUTCDATETIME();
    INSERT logistica.MovimientoInventario(almacen_id,uot_id,tipo_movimiento,naturaleza,documento_referencia,clave_idempotencia,fecha_hora,usuario_id,observacion,estado)
    VALUES(@nAlmacenOrigenId,@nUotOrigenId,'TRANSFERENCIA','S',CONCAT('UOT-',@nUotOrigenId,'-',@nUotDestinoId),@gClaveIdempotencia,@Ahora,@nUsuarioId,@cMotivo,1);
    SET @nMovimientoSalidaId=SCOPE_IDENTITY();
    INSERT logistica.MovimientoInventario(almacen_id,uot_id,tipo_movimiento,naturaleza,movimiento_relacionado_id,documento_referencia,clave_idempotencia,fecha_hora,usuario_id,observacion,estado)
    VALUES(@nAlmacenDestinoId,@nUotDestinoId,'TRANSFERENCIA','E',@nMovimientoSalidaId,CONCAT('UOT-',@nUotOrigenId,'-',@nUotDestinoId),@gEntrada,@Ahora,@nUsuarioId,@cMotivo,1);
    SET @nMovimientoEntradaId=SCOPE_IDENTITY(); UPDATE logistica.MovimientoInventario SET movimiento_relacionado_id=@nMovimientoEntradaId WHERE movimiento_inventario_id=@nMovimientoSalidaId;
    DECLARE @Stock TABLE(producto_id BIGINT PRIMARY KEY,cantidad DECIMAL(19,3),stock_minimo DECIMAL(19,3)); INSERT @Stock SELECT producto_id,stock_actual,stock_minimo FROM logistica.AlmacenProductoStock WHERE almacen_id=@nAlmacenOrigenId AND stock_actual>0;
    INSERT logistica.DetalleMovimientoInventario(movimiento_inventario_id,producto_id,cantidad) SELECT @nMovimientoSalidaId,producto_id,cantidad FROM @Stock;
    INSERT logistica.DetalleMovimientoInventario(movimiento_inventario_id,producto_id,cantidad) SELECT @nMovimientoEntradaId,producto_id,cantidad FROM @Stock;
    SELECT @nProductosTransferidos=COUNT(*) FROM @Stock;
    MERGE logistica.AlmacenProductoStock T USING @Stock S ON T.almacen_id=@nAlmacenDestinoId AND T.producto_id=S.producto_id
    WHEN MATCHED THEN UPDATE SET stock_actual=T.stock_actual+S.cantidad,fecha_actualizacion=SYSUTCDATETIME()
    WHEN NOT MATCHED THEN INSERT(almacen_id,producto_id,stock_actual,stock_reservado,stock_minimo,fecha_actualizacion) VALUES(@nAlmacenDestinoId,S.producto_id,S.cantidad,0,S.stock_minimo,SYSUTCDATETIME());
    UPDATE APS SET stock_actual=0,fecha_actualizacion=SYSUTCDATETIME() FROM logistica.AlmacenProductoStock APS JOIN @Stock S ON S.producto_id=APS.producto_id WHERE APS.almacen_id=@nAlmacenOrigenId;
  END;
  UPDATE B SET uot_id=@nUotDestinoId,empresa_id=COALESCE(U.empresa_legacy_id,B.empresa_id) FROM logistica.BienInventario B JOIN @Bienes X ON X.id=B.bien_inventario_id CROSS JOIN org.UOT U WHERE U.uot_id=@nUotDestinoId;
  SET @nBienesTransferidos=@@ROWCOUNT;

  DECLARE @Sid BIGINT,@Codigo VARCHAR(40),@Nombre NVARCHAR(150),@Unidad VARCHAR(20),@Min DECIMAL(19,3),@Cant DECIMAL(19,3),@Target BIGINT,@MovOut BIGINT;
  DECLARE C CURSOR LOCAL FAST_FORWARD FOR SELECT S.suministro_id,S.codigo,S.nombre,S.unidad_medida,S.stock_minimo,COALESCE(K.stock_actual,0) FROM logistica.Suministro S JOIN @Suministros X ON X.id=S.suministro_id LEFT JOIN logistica.SuministroSaldo K ON K.suministro_id=S.suministro_id;
  OPEN C; FETCH NEXT FROM C INTO @Sid,@Codigo,@Nombre,@Unidad,@Min,@Cant;
  WHILE @@FETCH_STATUS=0
  BEGIN
    SELECT @Target=NULL; SELECT @Target=suministro_id FROM logistica.Suministro WHERE uot_id=@nUotDestinoId AND codigo=@Codigo AND estado=1;
    IF @Target IS NULL BEGIN INSERT logistica.Suministro(uot_id,codigo,nombre,unidad_medida,estado,stock_minimo) VALUES(@nUotDestinoId,@Codigo,@Nombre,@Unidad,1,@Min); SET @Target=SCOPE_IDENTITY(); INSERT logistica.SuministroSaldo(suministro_id,stock_actual,stock_reservado,fecha_actualizacion) VALUES(@Target,0,0,SYSUTCDATETIME()); END;
    IF @Cant>0
    BEGIN
      INSERT logistica.SuministroMovimiento(suministro_id,uot_id,tipo_movimiento,cantidad,fecha_hora,usuario_id,documento_referencia,observacion,estado) VALUES(@Sid,@nUotOrigenId,'TRANSFERENCIA_SALIDA',@Cant,SYSUTCDATETIME(),@nUsuarioId,CONCAT('UOT-',@nUotOrigenId,'-',@nUotDestinoId),@cMotivo,1);
      SET @MovOut=SCOPE_IDENTITY();
      INSERT logistica.SuministroMovimiento(suministro_id,uot_id,tipo_movimiento,cantidad,fecha_hora,usuario_id,documento_referencia,observacion,estado,movimiento_origen_id) VALUES(@Target,@nUotDestinoId,'TRANSFERENCIA_ENTRADA',@Cant,SYSUTCDATETIME(),@nUsuarioId,CONCAT('UOT-',@nUotOrigenId,'-',@nUotDestinoId),@cMotivo,1,@MovOut);
    END;
    SET @nSuministrosTransferidos=@nSuministrosTransferidos+1; FETCH NEXT FROM C INTO @Sid,@Codigo,@Nombre,@Unidad,@Min,@Cant;
  END; CLOSE C; DEALLOCATE C;
  COMMIT; SELECT @bResultado=1,@cMensaje=N'Recursos transferidos.',@cCodigoRespuesta='UOT_RECURSOS_TRANSFERIDOS',@nHttpRespuesta=200; RETURN 0;
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SET @cMensaje=N'No se pudieron transferir los recursos.'; RETURN 1; END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [logistica].[PA_Vehiculo_Ins_Registro](@cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY
  SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),@nAud BIGINT,@nTrans BIGINT,@nBien BIGINT,@cPlaca VARCHAR(12),@cTipo VARCHAR(30),@nKm DECIMAL(12,1),@cIdent NVARCHAR(200);
SELECT @bResultado=0,@cMensaje=N'No se pudo registrar el vehículo.';
EXEC seg.PA_Operacion_Ins_IniciarIdempotente @cJson=@cJson,@cCodigoPermiso='INVENTARIO_CREAR',@cAmbito='VEHICULO_CREAR',@nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@nOperacionIdempotenteId=@nOp OUTPUT,@bEsRepetida=@bRep OUTPUT,@cEstadoOperacion=@cEstadoOp OUTPUT,@cIdentificadorResultado=@cIdRes OUTPUT,@cCodigoResultado=@cCodRes OUTPUT,@bResultado=@bIni OUTPUT,@cMensaje=@cMsg OUTPUT;
IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
GOTO __DESCO_Salida;
END;
IF @bRep=1 BEGIN SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
SET @cMensaje=CASE WHEN @cEstadoOp='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.' ELSE N'La solicitud ya se encuentra en proceso.' END;
GOTO __DESCO_Salida;
END;
 SELECT @nBien=bienInventarioId,@cPlaca=UPPER(NULLIF(LTRIM(RTRIM(placa)),'')),@cTipo=UPPER(NULLIF(LTRIM(RTRIM(tipoVehiculo)),'')),@nKm=COALESCE(kilometrajeKm,0) FROM OPENJSON(@cJson,'$.vehiculo') WITH(bienInventarioId BIGINT '$.bienInventarioId',placa VARCHAR(12) '$.placa',tipoVehiculo VARCHAR(30) '$.tipoVehiculo',kilometrajeKm DECIMAL(12,1) '$.kilometrajeKm');
IF NOT EXISTS
(
    SELECT 1
    FROM logistica.BienInventario B
    JOIN logistica.TipoBien T
      ON T.tipo_bien_id=B.tipo_bien_id
     AND T.estado=1
    WHERE B.bien_inventario_id=@nBien
      AND B.estado=1
      AND B.estado_bien<>'BAJA'
      AND UPPER(T.nombre) COLLATE Modern_Spanish_CI_AI
          = N'VEHICULO' COLLATE Modern_Spanish_CI_AI
)
BEGIN
    SET @cMensaje=
        N'Solo un bien clasificado como Vehículo puede registrar datos vehiculares.';
    GOTO Fallar;
END;
IF @cPlaca IS NULL OR @cTipo IS NULL OR @nKm<0
BEGIN
    SET @cMensaje=N'Complete correctamente los datos del vehículo.';
    GOTO Fallar;
END;
IF EXISTS(SELECT 1 FROM logistica.Vehiculo WHERE vehiculo_id=@nBien OR placa=@cPlaca) BEGIN SET @cMensaje=N'El bien o la placa ya se encuentra registrado como vehículo.';
GOTO Fallar;
END;
BEGIN TRY BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;
INSERT logistica.Vehiculo(vehiculo_id,placa,tipo_vehiculo,kilometraje_km,estado) VALUES(@nBien,@cPlaca,@cTipo,@nKm,1);
SET @cIdent=CONVERT(NVARCHAR(200),@nBien);
EXEC auditoria.PA_Operacion_Ins_RegistrarCambio @nUsuario,@nSesion,@nDisp,@nModulo,'REGISTRAR_VEHICULO','logistica','Vehiculo',@cIdent,NULL,NULL,NULL,NULL,NULL,NULL,@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
/* Confirmar datos e idempotencia juntos. */EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='COMPLETADA',@cEsquemaEntidad='logistica',@cNombreEntidad='Vehiculo',@cIdentificadorResultado=@cIdent,@cCodigoResultado='VEHICULO_CREADO',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado=1;
SET @cMensaje=N'Vehículo registrado correctamente.';
GOTO __DESCO_Salida;
 END TRY BEGIN CATCH
SET @bResultado = 0;
 IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @cMensaje=N'No se pudo registrar el vehículo. Intente nuevamente.';
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'logistica.PA_Vehiculo_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;
Fallar: IF @nOp IS NOT NULL AND @bResultado=0 EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='FALLIDA',@cEsquemaEntidad=NULL,@cNombreEntidad=NULL,@cIdentificadorResultado=NULL,@cCodigoResultado='NO_PROCESADO',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
 
    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'logistica.PA_Vehiculo_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

    IF @bResultado = 0 AND @nOp IS NOT NULL AND XACT_STATE() <> -1
    BEGIN
        IF ISNULL(@bRep,0) = 0
        BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                 @nOperacionIdempotenteId = @nOp, @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
            -- No sustituir el motivo funcional por un fallo de registro secundario.
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'logistica.PA_Vehiculo_Ins_Registro',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
        END CATCH;
        END
        ELSE
        BEGIN
            SELECT @cMensaje = COALESCE(mensaje_resultado,
                CASE WHEN estado_operacion = 'FALLIDA'
                     THEN N'La solicitud anterior no se completó. Corrija los datos y envíe una nueva solicitud.'
                     ELSE N'La solicitud todavía se está procesando. Consulte el resultado antes de repetirla.' END)
            FROM [auditoria].[OperacionIdempotente]
            WHERE operacion_idempotente_id = @nOp;
        END;
    END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'logistica.PA_Vehiculo_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'logistica.PA_Vehiculo_Ins_Registro',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

