END;
 SELECT @nId=vehiculoId,@nKm=kilometrajeKm FROM OPENJSON(@cJson,'$.vehiculo') WITH(vehiculoId BIGINT '$.vehiculoId',kilometrajeKm DECIMAL(12,1) '$.kilometrajeKm');
SELECT @nAnterior=COALESCE(kilometraje_km,0) FROM logistica.Vehiculo WHERE vehiculo_id=@nId AND estado=1;
IF @nAnterior IS NULL OR @nKm IS NULL OR @nKm<@nAnterior BEGIN SET @cMensaje=N'El kilometraje debe ser igual o mayor al último registrado.';
