GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [org].[PA_Asociacion_Ins_Registro]
    @cJson NVARCHAR(MAX),@nAsociacionId BIGINT OUTPUT,@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    SET @nAsociacionId=NULL; SET @bResultado=0; SET @cMensaje=N'No se pudo registrar la asociación.'; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;
    DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),@nAud BIGINT,@nTrans BIGINT,
            @nUotSolicitada BIGINT,@nUot BIGINT,@bGeneral BIT,@bUot BIT,@cUotMsg NVARCHAR(300),@cRuc VARCHAR(30),@cRazon NVARCHAR(200),@cNombre NVARCHAR(160),@cTel VARCHAR(30),@cCorreo VARCHAR(180),@dConst DATE,@cPartida VARCHAR(50),@cDistrito CHAR(6),@nCentro BIGINT,@cReferencia NVARCHAR(300),@bExistia BIT,@bBase BIT,@cMsgBase NVARCHAR(300),@cIdent NVARCHAR(200);
    BEGIN TRY
        EXEC seg.PA_Operacion_Ins_IniciarIdempotente @cJson,'ORGANIZACIONES_CREAR','ASOCIACION_CREAR',@nUsuario OUTPUT,@nSesion OUTPUT,@nDisp OUTPUT,@nEmp OUTPUT,@nModulo OUTPUT,@gCorr OUTPUT,@gSol OUTPUT,@cIp OUTPUT,@cEnd OUTPUT,@nOp OUTPUT,@bRep OUTPUT,@cEstadoOp OUTPUT,@cIdRes OUTPUT,@cCodRes OUTPUT,@bIni OUTPUT,@cMsg OUTPUT;
        IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg; GOTO Salida; END;
        IF @bRep=1 BEGIN SET @nAsociacionId=CASE WHEN @cEstadoOp='COMPLETADA' THEN TRY_CONVERT(BIGINT,@cIdRes) END; SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END; SET @cMensaje=CASE WHEN @bResultado=1 THEN N'La solicitud ya fue procesada.' ELSE N'La solicitud está en proceso.' END; GOTO Salida; END;
        SELECT @nUotSolicitada=uotId,@cRuc=NULLIF(LTRIM(RTRIM(ruc)),''),@cRazon=NULLIF(LTRIM(RTRIM(razonSocial)),N''),@cNombre=NULLIF(LTRIM(RTRIM(nombreComercial)),N''),@cTel=NULLIF(LTRIM(RTRIM(telefono)),''),@cCorreo=NULLIF(LTRIM(RTRIM(correo)),''),@dConst=fechaConstitucion,@cPartida=NULLIF(LTRIM(RTRIM(numeroPartida)),'')
        FROM OPENJSON(@cJson,'$.asociacion') WITH(uotId BIGINT '$.uotId',ruc VARCHAR(30) '$.ruc',razonSocial NVARCHAR(200) '$.razonSocial',nombreComercial NVARCHAR(160) '$.nombreComercial',telefono VARCHAR(30) '$.telefono',correo VARCHAR(180) '$.correo',fechaConstitucion DATE '$.fechaConstitucion',numeroPartida VARCHAR(50) '$.numeroPartida');
        SELECT @cDistrito=COALESCE(NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.asociacion.ubicacion.distritoCodigo'))),''),NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.ubicacion.distritoCodigo'))),'')),@nCentro=TRY_CONVERT(BIGINT,COALESCE(JSON_VALUE(@cJson,'$.asociacion.ubicacion.centroPobladoId'),JSON_VALUE(@cJson,'$.ubicacion.centroPobladoId'))),@cReferencia=COALESCE(NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.asociacion.ubicacion.referencia'))),N''),NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.ubicacion.referencia'))),N''));
        EXEC seg.PA_UOT_Sel_ResolverContextoSesion @nUsuario,@nSesion,@nUotSolicitada,'ORGANIZACIONES_CREAR',1,@nUot OUTPUT,@bGeneral OUTPUT,@bUot OUTPUT,@cUotMsg OUTPUT;
        IF @bUot=0 BEGIN SET @cMensaje=@cUotMsg; GOTO Fallar; END;
        IF @cRuc IS NULL OR @cRazon IS NULL OR @cDistrito IS NULL BEGIN SET @cMensaje=N'Complete los datos obligatorios.'; GOTO Fallar; END;
        BEGIN TRANSACTION;
        EXEC org.PA_Empresa_InsOUpd_DesdeFormulario @cRuc,@cRazon,@cNombre,@cTel,@cCorreo,@cDistrito,@nCentro,@cReferencia,@nAsociacionId OUTPUT,@bExistia OUTPUT,@bBase OUTPUT,@cMsgBase OUTPUT;
        IF @bBase=0 BEGIN ROLLBACK; SET @cMensaje=@cMsgBase; GOTO Fallar; END;
        IF EXISTS(SELECT 1 FROM org.Asociacion WHERE asociacion_id=@nAsociacionId) BEGIN ROLLBACK; SET @cMensaje=N'La asociación ya está registrada.'; GOTO Fallar; END;
        IF EXISTS(SELECT 1 FROM org.ConvenioUOTOrganizacion WHERE empresa_id=@nAsociacionId AND tipo_vinculo='EMPRESA' AND estado=1 AND fecha_fin IS NULL) BEGIN ROLLBACK; SET @cMensaje=N'La organización ya está registrada como empresa.'; GOTO Fallar; END;
        INSERT org.Asociacion(asociacion_id,fecha_constitucion,numero_partida,estado,uot_id) VALUES(@nAsociacionId,@dConst,@cPartida,1,@nUot);
        INSERT org.ConvenioUOTOrganizacion(uot_id,empresa_id,tipo_vinculo,numero_convenio,fecha_inicio,fecha_fin,descripcion,estado,fecha_creacion)
        VALUES(@nUot,@nAsociacionId,'ASOCIACION',NULL,CONVERT(date,SYSUTCDATETIME()),NULL,N'Contrato directo con la UOT.',1,SYSUTCDATETIME());
        SET @cIdent=CONVERT(NVARCHAR(200),@nAsociacionId);
        EXEC auditoria.PA_Operacion_Ins_RegistrarCambio @nUsuario,@nSesion,@nDisp,@nModulo,'CREAR','org','Asociacion',@cIdent,NULL,NULL,NULL,NULL,NULL,NULL,@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
        EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOp,'COMPLETADA','org','Asociacion',@cIdent,'ASOCIACION_CREADA',@bFin OUTPUT,@cMsgFin OUTPUT;
        IF ISNULL(@bFin,0)=0 THROW 51031,N'No se pudo confirmar la operación.',1;
        COMMIT; SET @bResultado=1; SET @cMensaje=N'Asociación registrada en la UOT.'; GOTO Salida;
Fallar:
        IF @nOp IS NOT NULL AND @bResultado=0 EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOp,'FALLIDA',NULL,NULL,NULL,'NO_PROCESADO',@bFin OUTPUT,@cMsgFin OUTPUT;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK; SET @nAsociacionId=NULL; SET @bResultado=0; SET @cMensaje=N'No se pudo registrar la asociación.';
        IF @nOp IS NOT NULL BEGIN TRY EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOp,'FALLIDA',NULL,NULL,NULL,'NO_PROCESADO',@bFin OUTPUT,@cMsgFin OUTPUT; END TRY BEGIN CATCH END CATCH;
    END CATCH
Salida:
    SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido FROM config.FN_RespuestaUsuario(N'org.PA_Asociacion_Ins_Registro',@bResultado,@cMensaje) R;
    RETURN CASE WHEN @bResultado=1 THEN 0 ELSE 1 END;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [org].[PA_Asociacion_Sel_ListadoUOT]
    @nUsuarioId BIGINT,@nUotId BIGINT,@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT
AS
BEGIN
    SET NOCOUNT ON; SET @bResultado=0; SET @cMensaje=N'No se pudieron consultar las asociaciones.';
    IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotId,'ORGANIZACIONES_LISTAR')=0 BEGIN SET @cMensaje=N'No tiene permiso para consultar esta UOT.'; RETURN 1; END;
    SELECT E.empresa_id asociacionId,E.ruc,E.razon_social razonSocial,E.nombre_comercial nombreComercial,A.fecha_constitucion fechaConstitucion,A.numero_partida numeroPartida,A.uot_id uotId,U.codigo uotCodigo,U.nombre uotNombre
    FROM org.Asociacion A JOIN org.Empresa E ON E.empresa_id=A.asociacion_id JOIN org.UOT U ON U.uot_id=A.uot_id JOIN org.ConvenioUOTOrganizacion C ON C.empresa_id=A.asociacion_id AND C.uot_id=A.uot_id AND C.tipo_vinculo='ASOCIACION' AND C.estado=1 AND C.fecha_fin IS NULL
    WHERE A.uot_id=@nUotId AND A.estado=1 AND E.estado=1 ORDER BY E.razon_social;
    SET @bResultado=1; SET @cMensaje=N'Asociaciones consultadas.'; RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [org].[PA_Asociacion_Upd_Registro]
    @cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON; SET @bResultado=0; SET @cMensaje=N'No se pudo actualizar la asociación.'; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;
    DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),@nAud BIGINT,@nTrans BIGINT,
            @nId BIGINT,@nUotSolicitada BIGINT,@nUot BIGINT,@bGeneral BIT,@bUot BIT,@cUotMsg NVARCHAR(300),@cRazon NVARCHAR(200),@cNombre NVARCHAR(160),@cTel VARCHAR(30),@cCorreo VARCHAR(180),@dConst DATE,@cPartida VARCHAR(50),@cDistrito CHAR(6),@nCentro BIGINT,@cReferencia NVARCHAR(300),@nUbicacion BIGINT,@bUbi BIT,@cMsgUbi NVARCHAR(300),@cIdent NVARCHAR(200);
    BEGIN TRY
        EXEC seg.PA_Operacion_Ins_IniciarIdempotente @cJson,'ORGANIZACIONES_EDITAR','ASOCIACION_EDITAR',@nUsuario OUTPUT,@nSesion OUTPUT,@nDisp OUTPUT,@nEmp OUTPUT,@nModulo OUTPUT,@gCorr OUTPUT,@gSol OUTPUT,@cIp OUTPUT,@cEnd OUTPUT,@nOp OUTPUT,@bRep OUTPUT,@cEstadoOp OUTPUT,@cIdRes OUTPUT,@cCodRes OUTPUT,@bIni OUTPUT,@cMsg OUTPUT;
        IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg; GOTO Salida; END;
        IF @bRep=1 BEGIN SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END; SET @cMensaje=CASE WHEN @bResultado=1 THEN N'La solicitud ya fue procesada.' ELSE N'La solicitud está en proceso.' END; GOTO Salida; END;
        SELECT @nId=asociacionId,@nUotSolicitada=uotId,@cRazon=NULLIF(LTRIM(RTRIM(razonSocial)),N''),@cNombre=NULLIF(LTRIM(RTRIM(nombreComercial)),N''),@cTel=NULLIF(LTRIM(RTRIM(telefono)),''),@cCorreo=NULLIF(LTRIM(RTRIM(correo)),''),@dConst=fechaConstitucion,@cPartida=NULLIF(LTRIM(RTRIM(numeroPartida)),'') FROM OPENJSON(@cJson,'$.asociacion') WITH(asociacionId BIGINT '$.asociacionId',uotId BIGINT '$.uotId',razonSocial NVARCHAR(200) '$.razonSocial',nombreComercial NVARCHAR(160) '$.nombreComercial',telefono VARCHAR(30) '$.telefono',correo VARCHAR(180) '$.correo',fechaConstitucion DATE '$.fechaConstitucion',numeroPartida VARCHAR(50) '$.numeroPartida');
        SELECT @cDistrito=NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.asociacion.ubicacion.distritoCodigo'))),''),@nCentro=TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.asociacion.ubicacion.centroPobladoId')),@cReferencia=NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.asociacion.ubicacion.referencia'))),N'');
        EXEC seg.PA_UOT_Sel_ResolverContextoSesion @nUsuario,@nSesion,@nUotSolicitada,'ORGANIZACIONES_EDITAR',1,@nUot OUTPUT,@bGeneral OUTPUT,@bUot OUTPUT,@cUotMsg OUTPUT;
        IF @bUot=0 BEGIN SET @cMensaje=@cUotMsg; GOTO Fallar; END;
        IF @nId IS NULL OR @cRazon IS NULL OR @cDistrito IS NULL OR NOT EXISTS(SELECT 1 FROM org.Asociacion A JOIN org.ConvenioUOTOrganizacion C ON C.empresa_id=A.asociacion_id WHERE A.asociacion_id=@nId AND A.uot_id=@nUot AND A.estado=1 AND C.uot_id=@nUot AND C.tipo_vinculo='ASOCIACION' AND C.estado=1 AND C.fecha_fin IS NULL) BEGIN SET @cMensaje=N'La asociación no está disponible en esta UOT.'; GOTO Fallar; END;
        SELECT @nUbicacion=ubicacion_id FROM org.Empresa WHERE empresa_id=@nId AND estado=1;
        BEGIN TRANSACTION;
        IF @nUbicacion IS NULL EXEC geo.PA_Ubicacion_Ins_Interna @cDistrito,@nCentro,@cReferencia,NULL,NULL,NULL,@nUbicacion OUTPUT,@bUbi OUTPUT,@cMsgUbi OUTPUT;
        ELSE EXEC geo.PA_Ubicacion_Upd_Interna @nUbicacion,@cDistrito,@nCentro,@cReferencia,@bUbi OUTPUT,@cMsgUbi OUTPUT;
        IF ISNULL(@bUbi,0)=0 BEGIN ROLLBACK; SET @cMensaje=COALESCE(@cMsgUbi,N'La ubicación no es válida.'); GOTO Fallar; END;
        UPDATE org.Empresa SET razon_social=@cRazon,nombre_comercial=@cNombre,telefono=@cTel,correo=@cCorreo,ubicacion_id=@nUbicacion WHERE empresa_id=@nId;
        UPDATE org.Asociacion SET fecha_constitucion=@dConst,numero_partida=@cPartida WHERE asociacion_id=@nId AND uot_id=@nUot;
        SET @cIdent=CONVERT(NVARCHAR(200),@nId);
        EXEC auditoria.PA_Operacion_Ins_RegistrarCambio @nUsuario,@nSesion,@nDisp,@nModulo,'EDITAR','org','Asociacion',@cIdent,NULL,NULL,NULL,NULL,NULL,NULL,@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
        EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOp,'COMPLETADA','org','Asociacion',@cIdent,'ASOCIACION_ACTUALIZADA',@bFin OUTPUT,@cMsgFin OUTPUT;
        IF ISNULL(@bFin,0)=0 THROW 51033,N'No se pudo confirmar la operación.',1;
        COMMIT; SET @bResultado=1; SET @cMensaje=N'Asociación actualizada.'; GOTO Salida;
Fallar:
        IF @nOp IS NOT NULL AND @bResultado=0 EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOp,'FALLIDA',NULL,NULL,NULL,'NO_PROCESADO',@bFin OUTPUT,@cMsgFin OUTPUT;
    END TRY
    BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SET @bResultado=0; SET @cMensaje=N'No se pudo actualizar la asociación.'; END CATCH
Salida:
    SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido FROM config.FN_RespuestaUsuario(N'org.PA_Asociacion_Upd_Registro',@bResultado,@cMensaje) R;
    RETURN CASE WHEN @bResultado=1 THEN 0 ELSE 1 END;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE org.PA_Asociacion_Upd_UOT
 @nUsuarioId BIGINT,@nAsociacionId BIGINT,@nUotId BIGINT,@cNumeroConvenio VARCHAR(80)=NULL,@dFechaInicio DATE=NULL,@dFechaFin DATE=NULL,
 @bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON; SET @bResultado=0; SET @cMensaje=N'No se pudo asignar la asociación a la UOT.';
 IF seg.FN_Usuario_TieneAccesoUOT(@nUsuarioId,@nUotId)=0 BEGIN SET @cMensaje=N'No tiene acceso a la UOT seleccionada.'; RETURN; END;
 IF NOT EXISTS(SELECT 1 FROM org.Asociacion WHERE asociacion_id=@nAsociacionId AND estado=1) BEGIN SET @cMensaje=N'La asociación no está disponible.'; RETURN; END;
 IF @dFechaFin IS NOT NULL AND @dFechaInicio IS NOT NULL AND @dFechaFin<@dFechaInicio BEGIN SET @cMensaje=N'La fecha final del convenio no puede ser anterior a la fecha inicial.'; RETURN; END;
 BEGIN TRY BEGIN TRAN;
 UPDATE org.ConvenioUOTOrganizacion SET estado=0,fecha_fin=COALESCE(fecha_fin,CONVERT(date,SYSUTCDATETIME())) WHERE empresa_id=@nAsociacionId AND tipo_vinculo='ASOCIACION' AND estado=1 AND fecha_fin IS NULL;
 UPDATE org.Asociacion SET uot_id=@nUotId WHERE asociacion_id=@nAsociacionId;
 INSERT org.ConvenioUOTOrganizacion(uot_id,empresa_id,tipo_vinculo,numero_convenio,fecha_inicio,fecha_fin,descripcion,estado)
 VALUES(@nUotId,@nAsociacionId,'ASOCIACION',@cNumeroConvenio,COALESCE(@dFechaInicio,CONVERT(date,SYSUTCDATETIME())),@dFechaFin,N'Convenio de asociación con UOT.',1);
 COMMIT; SET @bResultado=1; SET @cMensaje=N'Asociación asignada a la UOT correctamente.';
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SET @cMensaje=N'No se pudo asignar la asociación a la UOT.'; END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- org.PA_Empleado_Del_Registro
CREATE OR ALTER PROCEDURE [org].[PA_Empleado_Del_Registro]
(
    @cJson NVARCHAR(MAX),
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;

    BEGIN TRY

    SET NOCOUNT ON;

    IF @cJson IS NULL OR ISJSON(@cJson)<>1
    BEGIN
        SELECT @bResultado=0,@cMensaje=N'No se pudo procesar la solicitud.';
        GOTO __DESCO_Salida;
    END;

    DECLARE @cNormalizado NVARCHAR(MAX)=@cJson;

    IF JSON_QUERY(@cNormalizado,'$.empleado') IS NULL
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado',JSON_QUERY('{}'));

    IF JSON_QUERY(@cNormalizado,'$.contexto') IS NULL
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.contexto',JSON_QUERY('{}'));

    SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.empleadoId',JSON_VALUE(@cJson,'$.empleadoId'));
    SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.fechaCese',JSON_VALUE(@cJson,'$.fechaCese'));
    SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.motivo',JSON_VALUE(@cJson,'$.motivo'));

    IF JSON_VALUE(@cNormalizado,'$.contexto.sesionPublicaId') IS NULL
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.contexto.sesionPublicaId',JSON_VALUE(@cJson,'$.sesionPublicaId'));
    IF JSON_VALUE(@cNormalizado,'$.contexto.correlacionId') IS NULL
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.contexto.correlacionId',JSON_VALUE(@cJson,'$.correlacionId'));
    IF JSON_VALUE(@cNormalizado,'$.contexto.claveIdempotencia') IS NULL
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.contexto.claveIdempotencia',COALESCE(JSON_VALUE(@cJson,'$.claveIdempotencia'),JSON_VALUE(@cJson,'$.correlacionId')));
    IF JSON_VALUE(@cNormalizado,'$.contexto.ip') IS NULL
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.contexto.ip',JSON_VALUE(@cJson,'$.ip'));

    EXEC [org].[PA_Empleado_Upd_RetirarAdministracion]
         @cJson=@cNormalizado,
         @bResultado=@bResultado OUTPUT,
         @cMensaje=@cMensaje OUTPUT;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Empleado_Del_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Empleado_Del_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'org.PA_Empleado_Del_Registro',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- org.PA_Empleado_Ins_Registro
CREATE OR ALTER PROCEDURE [org].[PA_Empleado_Ins_Registro]
(
    @cJson NVARCHAR(MAX),
    @nEmpleadoId BIGINT OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;

    BEGIN TRY

    SET NOCOUNT ON;

    IF @cJson IS NULL OR ISJSON(@cJson)<>1
    BEGIN
        SELECT @nEmpleadoId=NULL,@bResultado=0,@cMensaje=N'No se pudo procesar la solicitud.';
        GOTO __DESCO_Salida;
    END;

    DECLARE @cNormalizado NVARCHAR(MAX)=@cJson;

    IF JSON_QUERY(@cNormalizado,'$.empleado') IS NULL
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado',JSON_QUERY('{}'));

    IF JSON_QUERY(@cJson,'$.persona') IS NOT NULL
    BEGIN
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.tipoDocumento',JSON_VALUE(@cJson,'$.persona.tipoDocumento'));
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.numeroDocumento',JSON_VALUE(@cJson,'$.persona.numeroDocumento'));
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.nombres',JSON_VALUE(@cJson,'$.persona.nombres'));
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.apellidoPaterno',JSON_VALUE(@cJson,'$.persona.apellidoPaterno'));
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.apellidoMaterno',JSON_VALUE(@cJson,'$.persona.apellidoMaterno'));
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.telefono',JSON_VALUE(@cJson,'$.persona.telefono'));
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.correo',JSON_VALUE(@cJson,'$.persona.correo'));
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.fechaNacimiento',JSON_VALUE(@cJson,'$.persona.fechaNacimiento'));
    END;

    /*
       Compatibilidad de ubicación personal:
       - contrato canónico: $.empleado.ubicacion
       - contrato legado:   $.persona.ubicacion
       - contrato simple:   $.ubicacion
    */
    IF JSON_QUERY(@cNormalizado,'$.empleado.ubicacion') IS NULL
    BEGIN
        IF JSON_QUERY(@cJson,'$.persona.ubicacion') IS NOT NULL
            SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.ubicacion',JSON_QUERY(@cJson,'$.persona.ubicacion'));
        ELSE IF JSON_QUERY(@cJson,'$.ubicacion') IS NOT NULL
            SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.ubicacion',JSON_QUERY(@cJson,'$.ubicacion'));
    END;

    EXEC [org].[PA_Empleado_Ins_RegistroAdministracion]
         @cJson=@cNormalizado,
         @nEmpleadoId=@nEmpleadoId OUTPUT,
         @bResultado=@bResultado OUTPUT,
         @cMensaje=@cMensaje OUTPUT;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Empleado_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Empleado_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'org.PA_Empleado_Ins_Registro',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/*
REGLAS DEFINITIVAS DE EMPLEADOS

1. La Persona es única. DNI y RUC10 son identificadores equivalentes.
2. Un empleado es una Persona; no se crea otro Empleado por usar el identificador equivalente.
3. El mismo Empleado puede pertenecer a distintas UOT mediante EmpleadoUOT.
4. No puede existir dos veces activo en la misma UOT.
5. Tipo/número de documento, UOT, código de empleado y fecha de ingreso son inmutables en edición.
6. La fecha de ingreso se fija al alta de la UOT y debe ser hoy o posterior.
7. Área/cargo sí pueden cambiar y mantienen historial.
8. RUC de empleado nuevo: solo RUC10, porque puede resolverse de forma segura contra DNI.
*/

CREATE OR ALTER PROCEDURE [org].[PA_Empleado_Ins_RegistroAdministracion]
(
    @cJson NVARCHAR(MAX),
    @nEmpleadoId BIGINT OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,
            @gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),
            @nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),
            @bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),
            @nAud BIGINT,@nTrans BIGINT,@cTipo VARCHAR(15),@cDoc VARCHAR(30),
            @cNom NVARCHAR(100),@cAP NVARCHAR(80),@cAM NVARCHAR(80),@cTel VARCHAR(30),
            @cCorreo VARCHAR(180),@dNac DATE,@nEmpresa BIGINT,@nUotSolicitada BIGINT,@nUot BIGINT,@bModoGeneral BIT,@bUot BIT,@cUotMsg NVARCHAR(300),@cCodigo VARCHAR(30),
            @dIngreso DATE,@nArea BIGINT,@cCargo NVARCHAR(120),@cDistrito CHAR(6),
            @nCentro BIGINT,@cReferencia NVARCHAR(300),@bPersonaExistia BIT,@bPersona BIT,
            @cMsgPersona NVARCHAR(300),@cIdent NVARCHAR(200),
            @bPuedeEditarIdentidad BIT=0,@nPersonaExistente BIGINT=NULL,@nCoinPersona INT=0,
            @bBuscaPersona BIT=0,@cMsgBuscaPersona NVARCHAR(300),
            @cTipoActual VARCHAR(15),@cDocActual VARCHAR(30),@cNomActual NVARCHAR(100),
            @cAPActual NVARCHAR(80),@cAMActual NVARCHAR(80),@cTelActual VARCHAR(30),
            @cCorreoActual VARCHAR(180),@dNacActual DATE,@cDistritoActual CHAR(6),
            @cReferenciaActual NVARCHAR(300);

    SELECT @nEmpleadoId=NULL,@bResultado=0,@cMensaje=N'No se pudo registrar el empleado.';

    EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente]
         @cJson=@cJson,@cCodigoPermiso='EMPLEADOS_CREAR',@cAmbito='EMPLEADO_CREAR',
         @nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,
         @nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,
         @gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,
         @nOperacionIdempotenteId=@nOp OUTPUT,@bEsRepetida=@bRep OUTPUT,@cEstadoOperacion=@cEstadoOp OUTPUT,
         @cIdentificadorResultado=@cIdRes OUTPUT,@cCodigoResultado=@cCodRes OUTPUT,
         @bResultado=@bIni OUTPUT,@cMensaje=@cMsg OUTPUT;

    IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
 GOTO __DESCO_Salida;
 END;
    IF @bRep=1
    BEGIN
        IF @cEstadoOp='COMPLETADA' SET @nEmpleadoId=TRY_CONVERT(BIGINT,@cIdRes);
        SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
        SET @cMensaje=CASE WHEN @cEstadoOp='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.' ELSE N'La solicitud ya se encuentra en proceso.' END;
        GOTO __DESCO_Salida;
    END;

    SELECT @cTipo=UPPER(NULLIF(LTRIM(RTRIM(tipoDocumento)),'')),@cDoc=NULLIF(LTRIM(RTRIM(numeroDocumento)),''),
           @cNom=NULLIF(LTRIM(RTRIM(nombres)),N''),@cAP=NULLIF(LTRIM(RTRIM(apellidoPaterno)),N''),
           @cAM=NULLIF(LTRIM(RTRIM(apellidoMaterno)),N''),@cTel=NULLIF(LTRIM(RTRIM(telefono)),''),
           @cCorreo=NULLIF(LTRIM(RTRIM(correo)),''),@dNac=fechaNacimiento,@nUotSolicitada=uotId,
           @cCodigo=UPPER(NULLIF(LTRIM(RTRIM(codigoEmpleado)),'')),@dIngreso=fechaIngreso,
           @nArea=areaId,@cCargo=NULLIF(LTRIM(RTRIM(cargo)),N'')
    FROM OPENJSON(@cJson,'$.empleado')
    WITH(tipoDocumento VARCHAR(15) '$.tipoDocumento',numeroDocumento VARCHAR(30) '$.numeroDocumento',
         nombres NVARCHAR(100) '$.nombres',apellidoPaterno NVARCHAR(80) '$.apellidoPaterno',
         apellidoMaterno NVARCHAR(80) '$.apellidoMaterno',telefono VARCHAR(30) '$.telefono',
         correo VARCHAR(180) '$.correo',fechaNacimiento DATE '$.fechaNacimiento',uotId BIGINT '$.uotId',
         codigoEmpleado VARCHAR(30) '$.codigoEmpleado',fechaIngreso DATE '$.fechaIngreso',areaId BIGINT '$.areaId',cargo NVARCHAR(120) '$.cargo');

    SELECT @cDistrito=COALESCE(NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.empleado.ubicacion.distritoCodigo'))),''),NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.persona.ubicacion.distritoCodigo'))),''),NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.ubicacion.distritoCodigo'))),'')),
           @nCentro=TRY_CONVERT(BIGINT,COALESCE(JSON_VALUE(@cJson,'$.empleado.ubicacion.centroPobladoId'),JSON_VALUE(@cJson,'$.persona.ubicacion.centroPobladoId'),JSON_VALUE(@cJson,'$.ubicacion.centroPobladoId'))),
           @cReferencia=COALESCE(NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.empleado.ubicacion.referencia'))),N''),NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.persona.ubicacion.referencia'))),N''),NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.ubicacion.referencia'))),N''));

    EXEC [seg].[PA_UOT_Sel_ResolverContextoSesion]
         @nUsuarioId=@nUsuario,@nSesionUsuarioId=@nSesion,@nUotSolicitada=@nUotSolicitada,
         @cCodigoPermiso='EMPLEADOS_CREAR',@bRequiereUot=1,@nUotId=@nUot OUTPUT,
         @bModoGeneral=@bModoGeneral OUTPUT,@bResultado=@bUot OUTPUT,@cMensaje=@cUotMsg OUTPUT;
    IF @bUot=0 BEGIN SET @cMensaje=@cUotMsg; GOTO Fallar; END;

    SELECT @nEmpresa=empresa_legacy_id FROM [org].[UOT] WHERE uot_id=@nUot AND estado=1;

    IF @cTipo NOT IN('DNI','RUC','CE','PASAPORTE','OTRO') OR @cDoc IS NULL OR @cNom IS NULL OR @cAP IS NULL
       OR @nUot IS NULL OR @cCodigo IS NULL OR @dIngreso IS NULL OR @cDistrito IS NULL
    BEGIN SET @cMensaje=N'Complete correctamente los datos requeridos del empleado.';
 GOTO Fallar;
 END;

    IF @cTipo='RUC' AND LEFT(@cDoc,2)<>'10'
    BEGIN
        SET @cMensaje=N'Para empleados se admite DNI o RUC10.';
        GOTO Fallar;
    END;

    IF @dIngreso<CONVERT(DATE,SYSUTCDATETIME())
    BEGIN
        SET @cMensaje=N'La fecha de ingreso debe ser hoy o posterior.';
        GOTO Fallar;
    END;

    IF @dNac IS NOT NULL
       AND DATEADD(YEAR,18,@dNac)>@dIngreso
    BEGIN
        SET @cMensaje=N'La persona debe ser mayor de edad en la fecha de ingreso.';
        GOTO Fallar;
    END;

    IF @nArea IS NOT NULL AND NOT EXISTS(SELECT 1 FROM [org].[Area] WHERE area_id=@nArea AND uot_id=@nUot AND estado=1)
    BEGIN SET @cMensaje=N'El área seleccionada no corresponde a la UOT.';
 GOTO Fallar;
 END;
    IF @nArea IS NOT NULL AND @cCargo IS NULL
    BEGIN SET @cMensaje=N'Ingrese el cargo del empleado para el área seleccionada.';
 GOTO Fallar;
 END;

    IF @nArea IS NOT NULL
       AND NOT EXISTS
       (
           SELECT 1
           FROM [config].[CatalogoRecursoValor] C
           WHERE C.catalogo='CARGO_EMPLEADO'
             AND C.estado=1
             AND C.nombre=@cCargo
       )
    BEGIN
        SET @cMensaje=N'El cargo seleccionado no está disponible.';
        GOTO Fallar;
    END;


    EXEC [org].[PA_Persona_Sel_IdPorDocumentoInterno]
         @cTipoDocumento=@cTipo,@cNumeroDocumento=@cDoc,@nExcluirPersonaId=NULL,
         @nPersonaId=@nPersonaExistente OUTPUT,@nCoincidencias=@nCoinPersona OUTPUT,
         @bResultado=@bBuscaPersona OUTPUT,@cMensaje=@cMsgBuscaPersona OUTPUT;

    IF @bBuscaPersona=0
    BEGIN SET @cMensaje=@cMsgBuscaPersona;
 GOTO Fallar;
 END;

    IF @nPersonaExistente IS NOT NULL
    BEGIN
        SELECT @cTipoActual=P.tipo_documento,@cDocActual=P.numero_documento,
               @cNomActual=P.nombres,@cAPActual=P.apellido_paterno,@cAMActual=P.apellido_materno,
               @cTelActual=P.telefono,@cCorreoActual=P.correo,@dNacActual=P.fecha_nacimiento,
               @cDistritoActual=U.distrito_codigo,@cReferenciaActual=U.referencia
        FROM [org].[Persona] P
        LEFT JOIN [geo].[Ubicacion] U ON U.ubicacion_id=P.ubicacion_id
        WHERE P.persona_id=@nPersonaExistente AND P.estado=1;


        /* El documento de una persona existente nunca se modifica desde Empleados. */
        SET @cTipo=@cTipoActual;
        SET @cDoc=@cDocActual;
    END;

    /* DNI y RUC10 representan la misma persona natural. */
    IF @nPersonaExistente IS NOT NULL
       AND EXISTS
       (
           SELECT 1
           FROM [org].[EmpleadoUOT]
           WHERE empleado_id=@nPersonaExistente
             AND uot_id=@nUot
             AND estado=1
             AND fecha_hasta IS NULL
       )
    BEGIN
        SET @cMensaje=N'El empleado ya pertenece a la UOT seleccionada.';
        GOTO Fallar;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM [org].[Empleado] E
        JOIN [org].[EmpleadoUOT] EU
          ON EU.empleado_id=E.empleado_id
         AND EU.estado=1
         AND EU.fecha_hasta IS NULL
        WHERE EU.uot_id=@nUot
          AND COALESCE(EU.codigo_empleado,E.codigo_empleado)=@cCodigo
          AND (
              @nPersonaExistente IS NULL
              OR E.empleado_id<>@nPersonaExistente
          )
          AND E.estado=1
    )
    BEGIN
        SET @cMensaje=N'El código de empleado ya está registrado en la UOT.';
        GOTO Fallar;
    END;

    BEGIN TRY
        BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

        EXEC [org].[PA_Persona_InsOUpd_DesdeFormulario]
             @cTipoDocumento=@cTipo,@cNumeroDocumento=@cDoc,@cNombres=@cNom,
             @cApellidoPaterno=@cAP,@cApellidoMaterno=@cAM,@cTelefono=@cTel,
             @cCorreo=@cCorreo,@dFechaNacimiento=@dNac,@cDistritoCodigo=@cDistrito,
             @nCentroPobladoId=@nCentro,@cReferencia=@cReferencia,@nPersonaEsperadaId=@nPersonaExistente,
             @nPersonaId=@nEmpleadoId OUTPUT,@bPersonaExistia=@bPersonaExistia OUTPUT,
             @bResultado=@bPersona OUTPUT,@cMensaje=@cMsgPersona OUTPUT;

        IF @bPersona=0 BEGIN BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
 SET @cMensaje=@cMsgPersona;
 GOTO Fallar;
 END;


        IF EXISTS(SELECT 1 FROM [org].[Empleado] WHERE empleado_id=@nEmpleadoId)
        BEGIN
            IF EXISTS(
                SELECT 1 FROM [org].[EmpleadoUOT]
                WHERE empleado_id=@nEmpleadoId AND uot_id=@nUot AND estado=1 AND fecha_hasta IS NULL
            )
            BEGIN
                BEGIN
                    IF @__DbTranAbierta = 1
                    BEGIN
                        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
                        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1 ROLLBACK TRANSACTION @__DbSavepoint;
                        SET @__DbTranAbierta = 0;
                    END;
                END;
                SET @cMensaje=N'El empleado ya pertenece a la UOT seleccionada.';
                GOTO Fallar;
            END;
            UPDATE [org].[Empleado]
               SET estado=1, fecha_cese=NULL
             WHERE empleado_id=@nEmpleadoId;
        END
        ELSE
        BEGIN
            INSERT [org].[Empleado](empleado_id,empresa_id,codigo_empleado,fecha_ingreso,fecha_cese,estado)
            VALUES(@nEmpleadoId,@nEmpresa,@cCodigo,@dIngreso,NULL,1);
        END;

        DECLARE @bPrincipal BIT = CASE WHEN EXISTS(
            SELECT 1 FROM [org].[EmpleadoUOT]
            WHERE empleado_id=@nEmpleadoId AND estado=1 AND fecha_hasta IS NULL
        ) THEN 0 ELSE 1 END;

        INSERT [org].[EmpleadoUOT](empleado_id,uot_id,es_principal,fecha_desde,fecha_hasta,estado,codigo_empleado,fecha_ingreso,fecha_cese)
        VALUES(@nEmpleadoId,@nUot,@bPrincipal,@dIngreso,NULL,1,@cCodigo,@dIngreso,NULL);

        IF @nArea IS NOT NULL
            INSERT [org].[EmpleadoArea](empleado_id,area_id,cargo,fecha_desde,fecha_hasta,estado)
            VALUES(@nEmpleadoId,@nArea,@cCargo,@dIngreso,NULL,1);

        SET @cIdent=CONVERT(NVARCHAR(200),@nEmpleadoId);
        EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio]
             @nUsuario,@nSesion,@nDisp,@nModulo,'CREAR','org','Empleado',@cIdent,
             NULL,NULL,NULL,NULL,NULL,NULL,@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;

        /* Confirmar datos e idempotencia juntos. */

        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
             @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='COMPLETADA',
             @cEsquemaEntidad='org',@cNombreEntidad='Empleado',@cIdentificadorResultado=@cIdent,
             @cCodigoResultado='EMPLEADO_CREADO',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;

        SET @bResultado=1;
        SET @cMensaje=CASE WHEN @bPersonaExistia=1
                           THEN N'Empleado registrado en la UOT.'
                           ELSE N'Empleado registrado en la UOT.' END;
        GOTO __DESCO_Salida;
    END TRY
    BEGIN CATCH
SET @bResultado = 0;

        IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
        SET @cMensaje=N'No se pudo registrar el empleado. Intente nuevamente.';

IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Empleado_Ins_RegistroAdministracion',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;

Fallar:
    IF @nOp IS NOT NULL AND @bResultado=0
        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
             @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='FALLIDA',@cEsquemaEntidad=NULL,
             @cNombreEntidad=NULL,@cIdentificadorResultado=NULL,@cCodigoResultado='NO_PROCESADO',
             @bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Empleado_Ins_RegistroAdministracion',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

    IF @bResultado = 0 AND @nOp IS NOT NULL AND XACT_STATE() <> -1
    BEGIN
        IF ISNULL(@bRep,0) = 0
        BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                 @nOperacionIdempotenteId = @nOp, @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
            -- No sustituir el motivo funcional por un fallo de registro secundario.
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Empleado_Ins_RegistroAdministracion',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
        END CATCH;
        END
        ELSE
        BEGIN
            SELECT @cMensaje = COALESCE(mensaje_resultado,
                CASE WHEN estado_operacion = 'FALLIDA'
                     THEN N'La solicitud anterior no se completó. Corrija los datos y envíe una nueva solicitud.'
                     ELSE N'La solicitud todavía se está procesando. Consulte el resultado antes de repetirla.' END)
            FROM [auditoria].[OperacionIdempotente]
            WHERE operacion_idempotente_id = @nOp;
        END;
    END;
IF @bResultado = 0
    SELECT @nEmpleadoId = NULL;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Empleado_Ins_RegistroAdministracion',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'org.PA_Empleado_Ins_RegistroAdministracion',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/*
CORRECCIÓN DEL DETALLE DE EMPLEADO

El PA estaba produciendo cuatro resultsets:
1. detalle;
2. historial de áreas;
3. usuario;
4. roles.

La información básica de usuario ya estaba incluida en el detalle.
Se completa allí mismo con último acceso y segundo factor, se elimina
el resultset redundante de usuario y Roles pasa a ser el tercer
resultset del detalle.

Además:
- los roles normales proceden de UsuarioUOTRol para la UOT consultada;
- ADMINISTRADOR global se considera efectivo porque la autorización
  del sistema ya lo trata como superadministrador global;
- se eliminan duplicados si ADMINISTRADOR existe en ambos ámbitos.
*/

CREATE OR ALTER PROCEDURE [org].[PA_Empleado_Sel_Detalle]
    @cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON; SET @bResultado=0; SET @cMensaje=N'No se pudo consultar el empleado.'; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;
    BEGIN TRY
        DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@bCtx BIT,@cMsg NVARCHAR(300),@nId BIGINT,@nUotSolicitada BIGINT,@nUot BIGINT,@bGeneral BIT,@bUot BIT,@cUotMsg NVARCHAR(300);
        SELECT @nId=COALESCE(TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.empleado.empleadoId')),TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.empleadoId')),TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.filtros.empleadoId'))),@nUotSolicitada=TRY_CONVERT(BIGINT,COALESCE(JSON_VALUE(@cJson,'$.empleado.uotId'),JSON_VALUE(@cJson,'$.filtros.uotId'),JSON_VALUE(@cJson,'$.uotId')));
        EXEC seg.PA_Operacion_Sel_ContextoAutorizado @cJson,'EMPLEADOS_VER',@nUsuario OUTPUT,@nSesion OUTPUT,@nDisp OUTPUT,@nEmp OUTPUT,@nModulo OUTPUT,@gCorr OUTPUT,@gSol OUTPUT,@cIp OUTPUT,@cEnd OUTPUT,@bCtx OUTPUT,@cMsg OUTPUT;
        IF @bCtx=0 BEGIN SET @cMensaje=@cMsg; GOTO Salida; END;
        EXEC seg.PA_UOT_Sel_ResolverContextoSesion @nUsuario,@nSesion,@nUotSolicitada,'EMPLEADOS_VER',1,@nUot OUTPUT,@bGeneral OUTPUT,@bUot OUTPUT,@cUotMsg OUTPUT;
        IF @bUot=0 BEGIN SET @cMensaje=@cUotMsg; GOTO Salida; END;
        IF NOT EXISTS(SELECT 1 FROM org.EmpleadoUOT WHERE empleado_id=@nId AND uot_id=@nUot AND estado=1 AND fecha_hasta IS NULL) BEGIN SET @cMensaje=N'El empleado no está disponible en esta UOT.'; GOTO Salida; END;
        SELECT E.empleado_id empleadoId,EU.uot_id uotId,UO.codigo uotCodigo,UO.nombre uotNombre,EU.uot_id empresaId,UO.nombre empresa,COALESCE(EU.codigo_empleado,E.codigo_empleado) codigoEmpleado,
               COALESCE(EU.fecha_ingreso,E.fecha_ingreso) fechaIngreso,EU.fecha_cese fechaCese,EU.estado,
               P.tipo_documento tipoDocumento,P.numero_documento numeroDocumento,P.nombres,P.apellido_paterno apellidoPaterno,P.apellido_materno apellidoMaterno,P.telefono,P.correo,P.fecha_nacimiento fechaNacimiento,
               UB.distrito_codigo distritoCodigo,D.nombre distritoNombre,UB.centro_poblado_id centroPobladoId,CP.nombre centroPobladoNombre,UB.referencia referencia,
               EA.area_id areaId,EA.area area,EA.cargo,
               US.usuario_id usuarioId,
               US.nombre_usuario nombreUsuario,
               US.estado_cuenta estadoCuenta,
               US.ultimo_acceso_correcto ultimoAccesoCorrecto,
               US.segundo_factor_habilitado segundoFactorHabilitado
        FROM org.Empleado E JOIN org.Persona P ON P.persona_id=E.empleado_id JOIN org.EmpleadoUOT EU ON EU.empleado_id=E.empleado_id AND EU.uot_id=@nUot AND EU.estado=1 AND EU.fecha_hasta IS NULL
        JOIN org.UOT UO ON UO.uot_id=EU.uot_id LEFT JOIN geo.Ubicacion UB ON UB.ubicacion_id=P.ubicacion_id LEFT JOIN geo.Distrito D ON D.distrito_codigo=UB.distrito_codigo LEFT JOIN geo.CentroPoblado CP ON CP.centro_poblado_id=UB.centro_poblado_id AND CP.distrito_codigo=UB.distrito_codigo OUTER APPLY(SELECT TOP(1) EA0.area_id,A0.nombre area,EA0.cargo FROM org.EmpleadoArea EA0 JOIN org.Area A0 ON A0.area_id=EA0.area_id AND A0.uot_id=@nUot WHERE EA0.empleado_id=E.empleado_id AND EA0.estado=1 AND EA0.fecha_hasta IS NULL ORDER BY EA0.fecha_desde DESC,EA0.empleado_area_id DESC) EA LEFT JOIN seg.Usuario US ON US.persona_id=E.empleado_id WHERE E.empleado_id=@nId;
        SELECT EA.empleado_area_id empleadoAreaId,EA.area_id areaId,A.nombre area,EA.cargo,EA.fecha_desde fechaDesde,EA.fecha_hasta fechaHasta,EA.estado FROM org.EmpleadoArea EA JOIN org.Area A ON A.area_id=EA.area_id AND A.uot_id=@nUot WHERE EA.empleado_id=@nId ORDER BY EA.fecha_desde DESC;
        ;WITH RolesEfectivos AS
        (
            SELECT
                R.rol_id rolId,
                R.codigo,
                R.nombre,
                UUR.fecha_desde fechaDesde,
                UUR.fecha_hasta fechaHasta,
                CAST(1 AS BIT) estado,
                1 prioridad
            FROM seg.Usuario U
            JOIN seg.UsuarioUOT UU
              ON UU.usuario_id=U.usuario_id
             AND UU.uot_id=@nUot
             AND UU.estado=1
             AND UU.fecha_desde<=SYSUTCDATETIME()
             AND (
                    UU.fecha_hasta IS NULL
                    OR UU.fecha_hasta>SYSUTCDATETIME()
                 )
            JOIN seg.UsuarioUOTRol UUR
              ON UUR.usuario_uot_id=UU.usuario_uot_id
             AND UUR.estado=1
             AND UUR.fecha_desde<=SYSUTCDATETIME()
             AND (
                    UUR.fecha_hasta IS NULL
                    OR UUR.fecha_hasta>SYSUTCDATETIME()
                 )
            JOIN seg.Rol R
              ON R.rol_id=UUR.rol_id
             AND R.estado=1
            WHERE U.persona_id=@nId
              AND U.estado=1
              AND U.estado_cuenta='ACTIVA'

            UNION ALL

            SELECT
                R.rol_id,
                R.codigo,
                R.nombre,
                UR.fecha_desde,
                UR.fecha_hasta,
                CAST(1 AS BIT),
                2
            FROM seg.Usuario U
            JOIN seg.UsuarioRol UR
              ON UR.usuario_id=U.usuario_id
             AND UR.estado=1
             AND UR.fecha_desde<=SYSUTCDATETIME()
             AND (
                    UR.fecha_hasta IS NULL
                    OR UR.fecha_hasta>SYSUTCDATETIME()
                 )
            JOIN seg.Rol R
              ON R.rol_id=UR.rol_id
             AND R.estado=1
             AND R.codigo='ADMINISTRADOR'
            WHERE U.persona_id=@nId
              AND U.estado=1
              AND U.estado_cuenta='ACTIVA'
        ),
        RolesUnicos AS
        (
            SELECT
                rolId,
                codigo,
                nombre,
                fechaDesde,
                fechaHasta,
                estado,
                ROW_NUMBER() OVER
                (
                    PARTITION BY rolId
                    ORDER BY prioridad,fechaDesde DESC
                ) fila
            FROM RolesEfectivos
        )
        SELECT
            rolId,
            codigo,
            nombre,
            fechaDesde,
            fechaHasta,
            estado
        FROM RolesUnicos
        WHERE fila=1
        ORDER BY nombre;
        SET @bResultado=1; SET @cMensaje=N'Empleado consultado.';
    END TRY BEGIN CATCH SET @bResultado=0; SET @cMensaje=N'No se pudo consultar el empleado.'; END CATCH
Salida:
    SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido FROM config.FN_RespuestaUsuario(N'org.PA_Empleado_Sel_Detalle',@bResultado,@cMensaje) R;
    RETURN CASE WHEN @bResultado=1 THEN 0 ELSE 1 END;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [org].[PA_Empleado_Sel_Listado]
    @cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON; SET @bResultado=0; SET @cMensaje=N'No se pudieron consultar los empleados.'; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;
    BEGIN TRY
        DECLARE @nPagina INT,@nTamano INT,@nOffset BIGINT; EXEC seg.PA_Consulta_Sel_ResolverPaginacion @cJson,@nPagina OUTPUT,@nTamano OUTPUT,@nOffset OUTPUT;
        DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@bCtx BIT,@cMsg NVARCHAR(300),@nUotSolicitada BIGINT,@nUot BIGINT,@bGeneral BIT,@bUot BIT,@cUotMsg NVARCHAR(300),@nArea BIGINT,@bActivo BIT;
        SELECT @nUotSolicitada=uotId,@nArea=areaId,@bActivo=activo FROM OPENJSON(@cJson,'$.filtros') WITH(uotId BIGINT '$.uotId',areaId BIGINT '$.areaId',activo BIT '$.activo');
        EXEC seg.PA_Operacion_Sel_ContextoAutorizado @cJson,'EMPLEADOS_LISTAR',@nUsuario OUTPUT,@nSesion OUTPUT,@nDisp OUTPUT,@nEmp OUTPUT,@nModulo OUTPUT,@gCorr OUTPUT,@gSol OUTPUT,@cIp OUTPUT,@cEnd OUTPUT,@bCtx OUTPUT,@cMsg OUTPUT;
        IF @bCtx=0 BEGIN SET @cMensaje=@cMsg; GOTO Salida; END;
        EXEC seg.PA_UOT_Sel_ResolverContextoSesion @nUsuario,@nSesion,@nUotSolicitada,'EMPLEADOS_LISTAR',0,@nUot OUTPUT,@bGeneral OUTPUT,@bUot OUTPUT,@cUotMsg OUTPUT;
        IF @bUot=0 BEGIN SET @cMensaje=@cUotMsg; GOTO Salida; END;
        SELECT E.empleado_id empleadoId,EU.uot_id uotId,UO.codigo uotCodigo,UO.nombre uotNombre,EU.uot_id empresaId,UO.nombre empresa,COALESCE(EU.codigo_empleado,E.codigo_empleado) codigoEmpleado,
               COALESCE(EU.fecha_ingreso,E.fecha_ingreso) fechaIngreso,EU.fecha_cese fechaCese,EU.estado,
               P.tipo_documento tipoDocumento,P.numero_documento numeroDocumento,P.nombres,P.apellido_paterno apellidoPaterno,P.apellido_materno apellidoMaterno,P.telefono,P.correo,
               EA.area_id areaId,EA.area area,EA.cargo,US.usuario_id usuarioId,US.nombre_usuario nombreUsuario,US.estado_cuenta estadoCuenta,COUNT_BIG(*) OVER() totalRegistros
        FROM org.Empleado E
        JOIN org.Persona P ON P.persona_id=E.empleado_id
        JOIN org.EmpleadoUOT EU ON EU.empleado_id=E.empleado_id AND EU.estado=1 AND EU.fecha_hasta IS NULL 
        JOIN org.UOT UO ON UO.uot_id=EU.uot_id AND UO.estado=1
        OUTER APPLY(
            SELECT TOP(1) EA0.area_id,A0.nombre area,EA0.cargo
            FROM org.EmpleadoArea EA0
            JOIN org.Area A0 ON A0.area_id=EA0.area_id AND A0.uot_id=EU.uot_id
            WHERE EA0.empleado_id=E.empleado_id AND EA0.estado=1 AND EA0.fecha_hasta IS NULL
            ORDER BY EA0.fecha_desde DESC,EA0.empleado_area_id DESC
        ) EA
        LEFT JOIN seg.Usuario US ON US.persona_id=E.empleado_id
        WHERE (@nUot IS NULL OR EU.uot_id=@nUot)
          AND seg.FN_Usuario_TienePermisoUOT(@nUsuario,EU.uot_id,'EMPLEADOS_LISTAR')=1
          AND (@nArea IS NULL OR EA.area_id=@nArea)
          AND (@bActivo IS NULL OR E.estado=@bActivo)
        ORDER BY UO.nombre,P.apellido_paterno,P.nombres,E.empleado_id OFFSET @nOffset ROWS FETCH NEXT @nTamano ROWS ONLY;
        SET @bResultado=1; SET @cMensaje=N'Empleados consultados.';
    END TRY BEGIN CATCH SET @bResultado=0; SET @cMensaje=N'No se pudieron consultar los empleados.'; END CATCH
Salida:
    SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido FROM config.FN_RespuestaUsuario(N'org.PA_Empleado_Sel_Listado',@bResultado,@cMensaje) R;
    RETURN CASE WHEN @bResultado=1 THEN 0 ELSE 1 END;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [org].[PA_Empleado_Sel_ListadoUOT]
    @nUsuarioId BIGINT,@nUotId BIGINT,@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT
AS
BEGIN
    SET NOCOUNT ON; SET @bResultado=0; SET @cMensaje=N'No se pudieron consultar los empleados.';
    IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotId,'EMPLEADOS_LISTAR')=0 BEGIN SET @cMensaje=N'No tiene permiso para consultar esta UOT.'; RETURN 1; END;
    SELECT E.empleado_id empleadoId,EU.uot_id uotId,U.codigo uotCodigo,U.nombre uotNombre,E.codigo_empleado codigoEmpleado,P.tipo_documento tipoDocumento,P.numero_documento numeroDocumento,P.nombres,P.apellido_paterno apellidoPaterno,P.apellido_materno apellidoMaterno,E.estado
    FROM org.EmpleadoUOT EU JOIN org.Empleado E ON E.empleado_id=EU.empleado_id JOIN org.Persona P ON P.persona_id=E.empleado_id JOIN org.UOT U ON U.uot_id=EU.uot_id
    WHERE EU.uot_id=@nUotId AND EU.estado=1 AND EU.fecha_hasta IS NULL AND E.estado=1 ORDER BY P.apellido_paterno,P.nombres;
    SET @bResultado=1; SET @cMensaje=N'Empleados consultados.'; RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- org.PA_Empleado_Upd_Registro
CREATE OR ALTER PROCEDURE [org].[PA_Empleado_Upd_Registro]
(
    @cJson NVARCHAR(MAX),
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;

    BEGIN TRY

    SET NOCOUNT ON;

    IF @cJson IS NULL OR ISJSON(@cJson)<>1
    BEGIN
        SELECT @bResultado=0,@cMensaje=N'No se pudo procesar la solicitud.';
        GOTO __DESCO_Salida;
    END;

    DECLARE @cNormalizado NVARCHAR(MAX)=@cJson;

    IF JSON_QUERY(@cNormalizado,'$.empleado') IS NULL
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado',JSON_QUERY('{}'));

    IF JSON_VALUE(@cJson,'$.empleadoId') IS NOT NULL
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.empleadoId',JSON_VALUE(@cJson,'$.empleadoId'));
    IF JSON_QUERY(@cJson,'$.persona') IS NOT NULL
    BEGIN
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.tipoDocumento',JSON_VALUE(@cJson,'$.persona.tipoDocumento'));
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.numeroDocumento',JSON_VALUE(@cJson,'$.persona.numeroDocumento'));
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.nombres',JSON_VALUE(@cJson,'$.persona.nombres'));
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.apellidoPaterno',JSON_VALUE(@cJson,'$.persona.apellidoPaterno'));
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.apellidoMaterno',JSON_VALUE(@cJson,'$.persona.apellidoMaterno'));
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.telefono',JSON_VALUE(@cJson,'$.persona.telefono'));
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.correo',JSON_VALUE(@cJson,'$.persona.correo'));
        SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.fechaNacimiento',JSON_VALUE(@cJson,'$.persona.fechaNacimiento'));
    END;

    /*
       Compatibilidad de ubicación personal:
       - contrato canónico: $.empleado.ubicacion
       - contrato legado:   $.persona.ubicacion
       - contrato simple:   $.ubicacion
    */
    IF JSON_QUERY(@cNormalizado,'$.empleado.ubicacion') IS NULL
    BEGIN
        IF JSON_QUERY(@cJson,'$.persona.ubicacion') IS NOT NULL
            SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.ubicacion',JSON_QUERY(@cJson,'$.persona.ubicacion'));
        ELSE IF JSON_QUERY(@cJson,'$.ubicacion') IS NOT NULL
            SET @cNormalizado=JSON_MODIFY(@cNormalizado,'$.empleado.ubicacion',JSON_QUERY(@cJson,'$.ubicacion'));
    END;

    EXEC [org].[PA_Empleado_Upd_RegistroAdministracion]
         @cJson=@cNormalizado,
         @bResultado=@bResultado OUTPUT,
         @cMensaje=@cMensaje OUTPUT;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Empleado_Upd_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Empleado_Upd_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'org.PA_Empleado_Upd_Registro',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/*
Regla:
- La fecha de asignación vigente es histórica y no se edita.
- Solo se registra una nueva fecha cuando cambia el área o el cargo.
- Cambiar a "Sin área asignada" también requiere fecha efectiva.
*/

CREATE OR ALTER PROCEDURE [org].[PA_Empleado_Upd_RegistroAdministracion]
(
    @cJson NVARCHAR(MAX),
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,
        @gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),
        @nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),
        @bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),
        @nAud BIGINT,@nTrans BIGINT,@nId BIGINT,@cIdent NVARCHAR(200),
        @cTipoIn VARCHAR(15),@cDocIn VARCHAR(30),@cNomIn NVARCHAR(100),@cAPIn NVARCHAR(80),
        @cAMIn NVARCHAR(80),@cTelIn VARCHAR(30),@cCorreoIn VARCHAR(180),@dNacIn DATE,
        @nUotIn BIGINT,@cCodigoIn VARCHAR(30),@dIngresoIn DATE,@nAreaIn BIGINT,
        @cCargoIn NVARCHAR(120),@dFechaAreaIn DATE,
        @cTipo VARCHAR(15),@cDoc VARCHAR(30),@cNom NVARCHAR(100),@cAP NVARCHAR(80),
        @cAM NVARCHAR(80),@cTel VARCHAR(30),@cCorreo VARCHAR(180),@dNac DATE,
        @nEmpresa BIGINT,@nUotActual BIGINT,@nUot BIGINT,@bModoGeneral BIT,@bUot BIT,@cUotMsg NVARCHAR(300),@cCodigo VARCHAR(30),@dIngreso DATE,
        @nAreaActual BIGINT,@cCargoActual NVARCHAR(120),@dAreaActual DATE,
        @nAreaObjetivo BIGINT,@cCargoObjetivo NVARCHAR(120),@dFechaArea DATE,
        @cDistrito CHAR(6),@nCentroPoblado BIGINT,@cReferencia NVARCHAR(300),
        @nUbicacionActual BIGINT,@bPuedeEditarIdentidad BIT=0,
        @cTipoActual VARCHAR(15),@cDocActual VARCHAR(30),@cNomActual NVARCHAR(100),
        @cAPActual NVARCHAR(80),@cAMActual NVARCHAR(80),@cTelActual VARCHAR(30),
        @cCorreoActual VARCHAR(180),@dNacActual DATE,@cDistritoActual CHAR(6),
        @cReferenciaActual NVARCHAR(300);

    SELECT @bResultado=0,@cMensaje=N'No se pudo actualizar el empleado.';

    EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente]
         @cJson=@cJson,@cCodigoPermiso='EMPLEADOS_EDITAR',@cAmbito='EMPLEADO_EDITAR',
         @nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,
         @nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,
         @nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,
         @gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,
         @nOperacionIdempotenteId=@nOp OUTPUT,@bEsRepetida=@bRep OUTPUT,
         @cEstadoOperacion=@cEstadoOp OUTPUT,@cIdentificadorResultado=@cIdRes OUTPUT,
         @cCodigoResultado=@cCodRes OUTPUT,@bResultado=@bIni OUTPUT,@cMensaje=@cMsg OUTPUT;

    IF @bIni=0 AND @bRep=0
    BEGIN
        SET @cMensaje=@cMsg;
        GOTO __DESCO_Salida;
    END;

    IF @bRep=1
    BEGIN
        SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
        SET @cMensaje=CASE WHEN @cEstadoOp='COMPLETADA'
                           THEN N'La solicitud ya fue procesada correctamente.'
                           ELSE N'La solicitud ya se encuentra en proceso.' END;
        GOTO __DESCO_Salida;
    END;

    SELECT
        @nId=empleadoId,
        @cTipoIn=UPPER(NULLIF(LTRIM(RTRIM(tipoDocumento)),'')),
        @cDocIn=NULLIF(LTRIM(RTRIM(numeroDocumento)),''),
        @cNomIn=NULLIF(LTRIM(RTRIM(nombres)),N''),
        @cAPIn=NULLIF(LTRIM(RTRIM(apellidoPaterno)),N''),
        @cAMIn=NULLIF(LTRIM(RTRIM(apellidoMaterno)),N''),
        @cTelIn=NULLIF(LTRIM(RTRIM(telefono)),''),
        @cCorreoIn=NULLIF(LTRIM(RTRIM(correo)),''),
        @dNacIn=fechaNacimiento,
        @nUotIn=uotId,
        @cCodigoIn=UPPER(NULLIF(LTRIM(RTRIM(codigoEmpleado)),'')),
        @dIngresoIn=fechaIngreso,
        @nAreaIn=areaId,
        @cCargoIn=NULLIF(LTRIM(RTRIM(cargo)),N''),
        @dFechaAreaIn=fechaAsignacionArea
    FROM OPENJSON(@cJson,'$.empleado')
    WITH
    (
        empleadoId BIGINT '$.empleadoId',
        tipoDocumento VARCHAR(15) '$.tipoDocumento',
        numeroDocumento VARCHAR(30) '$.numeroDocumento',
        nombres NVARCHAR(100) '$.nombres',
        apellidoPaterno NVARCHAR(80) '$.apellidoPaterno',
        apellidoMaterno NVARCHAR(80) '$.apellidoMaterno',
        telefono VARCHAR(30) '$.telefono',
        correo VARCHAR(180) '$.correo',
        fechaNacimiento DATE '$.fechaNacimiento',
        uotId BIGINT '$.uotId',
        codigoEmpleado VARCHAR(30) '$.codigoEmpleado',
        fechaIngreso DATE '$.fechaIngreso',
        areaId BIGINT '$.areaId',
        cargo NVARCHAR(120) '$.cargo',
        fechaAsignacionArea DATE '$.fechaAsignacionArea'
    );

    SELECT
        @cTipo=P.tipo_documento,@cDoc=P.numero_documento,@cNom=P.nombres,
        @cAP=P.apellido_paterno,@cAM=P.apellido_materno,@cTel=P.telefono,
        @cCorreo=P.correo,@dNac=P.fecha_nacimiento,@nUbicacionActual=P.ubicacion_id,
        @nEmpresa=E.empresa_id,@cCodigo=E.codigo_empleado,@dIngreso=E.fecha_ingreso
    FROM [org].[Empleado] E
    INNER JOIN [org].[Persona] P ON P.persona_id=E.empleado_id
    WHERE E.empleado_id=@nId AND E.estado=1 AND P.estado=1;

    IF @cTipo IS NULL
    BEGIN
        SET @cMensaje=N'El empleado seleccionado no está disponible.';
        GOTO Fallar;
    END;

    SET @nUot=@nUotIn;
    EXEC [seg].[PA_UOT_Sel_ResolverContextoSesion]
         @nUsuarioId=@nUsuario,@nSesionUsuarioId=@nSesion,@nUotSolicitada=@nUot,
         @cCodigoPermiso='EMPLEADOS_EDITAR',@bRequiereUot=1,@nUotId=@nUot OUTPUT,
         @bModoGeneral=@bModoGeneral OUTPUT,@bResultado=@bUot OUTPUT,@cMensaje=@cUotMsg OUTPUT;
    IF @bUot=0 BEGIN SET @cMensaje=@cUotMsg; GOTO Fallar; END;
    IF NOT EXISTS(SELECT 1 FROM [org].[EmpleadoUOT] WHERE empleado_id=@nId AND uot_id=@nUot AND estado=1 AND fecha_hasta IS NULL)
    BEGIN SET @cMensaje=N'El empleado no pertenece a la UOT seleccionada.'; GOTO Fallar; END;
    SELECT @nEmpresa=U.empresa_legacy_id,
           @cCodigo=COALESCE(EU.codigo_empleado,E.codigo_empleado),
           @dIngreso=COALESCE(EU.fecha_ingreso,E.fecha_ingreso)
    FROM [org].[EmpleadoUOT] EU
    JOIN [org].[Empleado] E ON E.empleado_id=EU.empleado_id
    JOIN [org].[UOT] U ON U.uot_id=EU.uot_id AND U.estado=1
    WHERE EU.empleado_id=@nId AND EU.uot_id=@nUot AND EU.estado=1 AND EU.fecha_hasta IS NULL;

    SELECT @cTipoActual=@cTipo,@cDocActual=@cDoc,@cNomActual=@cNom,@cAPActual=@cAP,
           @cAMActual=@cAM,@cTelActual=@cTel,@cCorreoActual=@cCorreo,@dNacActual=@dNac;

    SELECT @cDistritoActual=U.distrito_codigo,@cReferenciaActual=U.referencia
    FROM [geo].[Ubicacion] U
    WHERE U.ubicacion_id=@nUbicacionActual;

    IF (@cTipoIn IS NOT NULL AND @cTipoIn<>@cTipoActual)
       OR (@cDocIn IS NOT NULL AND @cDocIn<>@cDocActual)
    BEGIN
        SET @cMensaje=N'El documento de la persona no puede modificarse.';
        GOTO Fallar;
    END;


    IF @dIngresoIn IS NOT NULL
       AND @dIngresoIn<>@dIngreso
    BEGIN
        SET @cMensaje=N'La fecha de ingreso no puede modificarse.';
        GOTO Fallar;
    END;

    IF @cCodigoIn IS NOT NULL
       AND @cCodigoIn<>@cCodigo
    BEGIN
        SET @cMensaje=N'El código de empleado no puede modificarse.';
        GOTO Fallar;
    END;


    SELECT TOP(1)
        @nAreaActual=EA.area_id,@cCargoActual=EA.cargo,@dAreaActual=EA.fecha_desde
    FROM [org].[EmpleadoArea] EA
    JOIN [org].[Area] AX ON AX.area_id=EA.area_id AND AX.uot_id=@nUot
    WHERE EA.empleado_id=@nId AND EA.estado=1 AND EA.fecha_hasta IS NULL
    ORDER BY EA.fecha_desde DESC,EA.empleado_area_id DESC;

    SELECT
        @cTipo=COALESCE(@cTipoIn,@cTipo),
        @cDoc=COALESCE(@cDocIn,@cDoc),
        @cNom=COALESCE(@cNomIn,@cNom),
        @cAP=COALESCE(@cAPIn,@cAP),
        @cAM=COALESCE(@cAMIn,@cAM),
        @cTel=COALESCE(@cTelIn,@cTel),
        @cCorreo=COALESCE(@cCorreoIn,@cCorreo),
        @dNac=COALESCE(@dNacIn,@dNac),
        @nAreaObjetivo=@nAreaIn,
        @cCargoObjetivo=CASE
            WHEN @nAreaIn IS NULL THEN NULL
            ELSE @cCargoIn
        END,
        @dFechaArea=@dFechaAreaIn;

    SELECT
        @cDistrito=COALESCE(
            NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.empleado.ubicacion.distritoCodigo'))),''),
            NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.persona.ubicacion.distritoCodigo'))),''),
            NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.ubicacion.distritoCodigo'))),'')
        ),
        @nCentroPoblado=TRY_CONVERT(BIGINT,COALESCE(
            JSON_VALUE(@cJson,'$.empleado.ubicacion.centroPobladoId'),
            JSON_VALUE(@cJson,'$.persona.ubicacion.centroPobladoId'),
            JSON_VALUE(@cJson,'$.ubicacion.centroPobladoId')
        )),
        @cReferencia=COALESCE(
            NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.empleado.ubicacion.referencia'))),N''),
            NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.persona.ubicacion.referencia'))),N''),
            NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.ubicacion.referencia'))),N'')
        );


    /* Documento inmutable incluso para usuarios con permiso de edición de identidad. */
    SET @cTipo=@cTipoActual;
    SET @cDoc=@cDocActual;

    IF @cTipo NOT IN('DNI','RUC','CE','PASAPORTE','OTRO')
       OR @cDoc IS NULL OR @cNom IS NULL OR @cAP IS NULL
       OR @nUot IS NULL OR @cCodigo IS NULL OR @dIngreso IS NULL
       OR @cDistrito IS NULL
    BEGIN
        SET @cMensaje=N'Complete correctamente los datos del empleado.';
        GOTO Fallar;
    END;

    IF @cTipo IN('DNI','RUC') AND [org].[FN_Documento_EsValido](@cTipo,@cDoc)=0
    BEGIN
        SET @cMensaje=N'El DNI o RUC no supera la validación de integridad.';
        GOTO Fallar;
    END;

    IF @cTipo='RUC' AND [org].[FN_Ruc_Naturaleza](@cDoc)<>'NATURAL'
    BEGIN
        SET @cMensaje=N'El RUC corresponde a una persona jurídica. No puede asignarse a un empleado.';
        GOTO Fallar;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [geo].[Distrito]
        WHERE distrito_codigo=@cDistrito AND estado=1
    )
    BEGIN
        SET @cMensaje=N'El distrito seleccionado no está disponible.';
        GOTO Fallar;
    END;

    IF @nCentroPoblado IS NOT NULL
       AND NOT EXISTS
       (
           SELECT 1
           FROM [geo].[CentroPoblado]
           WHERE centro_poblado_id=@nCentroPoblado
             AND distrito_codigo=@cDistrito
             AND estado=1
       )
    BEGIN
        SET @cMensaje=N'El centro poblado no corresponde al distrito seleccionado.';
        GOTO Fallar;
    END;

    IF @dNac IS NOT NULL AND @dNac>CONVERT(DATE,SYSUTCDATETIME())
    BEGIN
        SET @cMensaje=N'Ingrese una fecha de nacimiento válida.';
        GOTO Fallar;
    END;

    IF @dNacIn IS NOT NULL
       AND ISNULL(@dNacIn,CONVERT(DATE,'19000101'))
           <>ISNULL(@dNacActual,CONVERT(DATE,'19000101'))
       AND DATEADD(YEAR,18,@dNac)>@dIngreso
    BEGIN
        SET @cMensaje=N'La persona debe ser mayor de edad en la fecha de ingreso.';
        GOTO Fallar;
    END;

    IF @cCorreo IS NOT NULL AND @cCorreo NOT LIKE '%_@_%._%'
    BEGIN
        SET @cMensaje=N'Ingrese un correo válido.';
        GOTO Fallar;
    END;

    DECLARE @nConflictoPersona BIGINT,@nCoinDocumento INT,@bBuscaDocumento BIT,@cMsgDocumento NVARCHAR(300);
    EXEC [org].[PA_Persona_Sel_IdPorDocumentoInterno]
         @cTipoDocumento=@cTipo,@cNumeroDocumento=@cDoc,@nExcluirPersonaId=@nId,
         @nPersonaId=@nConflictoPersona OUTPUT,@nCoincidencias=@nCoinDocumento OUTPUT,
         @bResultado=@bBuscaDocumento OUTPUT,@cMensaje=@cMsgDocumento OUTPUT;
    IF @bBuscaDocumento=0 OR @nCoinDocumento>0
    BEGIN
        SET @cMensaje=CASE WHEN @bBuscaDocumento=0 THEN @cMsgDocumento ELSE N'El documento pertenece a otra persona registrada.' END;
        GOTO Fallar;
    END;

    IF EXISTS
    (
        SELECT 1 FROM [org].[Empleado] E
        JOIN [org].[EmpleadoUOT] EU ON EU.empleado_id=E.empleado_id AND EU.estado=1 AND EU.fecha_hasta IS NULL
        WHERE EU.uot_id=@nUot AND COALESCE(EU.codigo_empleado,E.codigo_empleado)=@cCodigo AND E.empleado_id<>@nId AND E.estado=1
    )
    BEGIN
        SET @cMensaje=N'El código de empleado ya está registrado en la UOT.';
        GOTO Fallar;
    END;

    IF @nAreaObjetivo IS NOT NULL
       AND NOT EXISTS
       (
           SELECT 1 FROM [org].[Area]
           WHERE area_id=@nAreaObjetivo AND uot_id=@nUot AND estado=1
       )
    BEGIN
        SET @cMensaje=N'El área seleccionada no corresponde a la UOT.';
        GOTO Fallar;
    END;

    IF @nAreaObjetivo IS NOT NULL AND @cCargoObjetivo IS NULL
    BEGIN
        SET @cMensaje=N'Ingrese el cargo del empleado.';
        GOTO Fallar;
    END;

    IF @nAreaObjetivo IS NOT NULL
       AND COALESCE(@cCargoObjetivo,N'')<>COALESCE(@cCargoActual,N'')
       AND NOT EXISTS
       (
           SELECT 1
           FROM [config].[CatalogoRecursoValor] C
           WHERE C.catalogo='CARGO_EMPLEADO'
             AND C.estado=1
             AND C.nombre=@cCargoObjetivo
       )
    BEGIN
        SET @cMensaje=N'El cargo seleccionado no está disponible.';
        GOTO Fallar;
    END;

    DECLARE @bCambioAsignacion BIT =
        CASE
            WHEN COALESCE(@nAreaObjetivo,-1)
                 <>COALESCE(@nAreaActual,-1)
              OR COALESCE(@cCargoObjetivo,N'')
                 <>COALESCE(@cCargoActual,N'')
            THEN 1
            ELSE 0
        END;

    IF @bCambioAsignacion=1
       AND @dFechaArea IS NULL
    BEGIN
        SET @cMensaje=N'Indique la fecha efectiva del cambio de área o cargo.';
        GOTO Fallar;
    END;

    IF @bCambioAsignacion=1
       AND @dFechaArea<@dIngreso
    BEGIN
        SET @cMensaje=N'La fecha efectiva del cambio no puede ser anterior al ingreso del empleado.';
        GOTO Fallar;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM [org].[EmpleadoArea] EAH
        JOIN [org].[Area] AH ON AH.area_id=EAH.area_id AND AH.uot_id=@nUot
        WHERE EAH.empleado_id=@nId
          AND EAH.fecha_desde<@dIngreso
    )
    BEGIN
        SET @cMensaje=N'La fecha de ingreso no puede quedar después de una asignación de área ya registrada.';
        GOTO Fallar;
    END;

    IF @bCambioAsignacion=1
       AND @dAreaActual IS NOT NULL
       AND @dFechaArea<@dAreaActual
    BEGIN
        SET @cMensaje=N'La nueva asignación de área no puede iniciar antes de la asignación vigente.';
        GOTO Fallar;
    END;

    BEGIN TRY
        BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

        IF @nUbicacionActual IS NULL
        BEGIN
            INSERT [geo].[Ubicacion]
            (
                distrito_codigo,centro_poblado_id,referencia,estado
            )
            VALUES
            (
                @cDistrito,@nCentroPoblado,@cReferencia,1
            );

            SET @nUbicacionActual=CONVERT(BIGINT,SCOPE_IDENTITY());
        END
        ELSE
        BEGIN
            UPDATE [geo].[Ubicacion]
            SET distrito_codigo=@cDistrito,
                centro_poblado_id=@nCentroPoblado,
                referencia=@cReferencia,
                estado=1
            WHERE ubicacion_id=@nUbicacionActual;
        END;

        UPDATE [org].[Persona]
        SET tipo_persona='NATURAL',
            tipo_documento=@cTipo,
            numero_documento=@cDoc,
            nombres=@cNom,
            apellido_paterno=@cAP,
            apellido_materno=@cAM,
            telefono=@cTel,
            correo=@cCorreo,
            fecha_nacimiento=@dNac,
            ubicacion_id=@nUbicacionActual
        WHERE persona_id=@nId;

        UPDATE [org].[EmpleadoUOT]
           SET fecha_cese=NULL
         WHERE empleado_id=@nId
           AND uot_id=@nUot
           AND estado=1
           AND fecha_hasta IS NULL;

        IF EXISTS
        (
            SELECT 1
            FROM [org].[EmpleadoUOT]
            WHERE empleado_id=@nId
              AND uot_id=@nUot
              AND es_principal=1
              AND estado=1
              AND fecha_hasta IS NULL
        )
        BEGIN
            UPDATE [org].[Empleado]
               SET empresa_id=COALESCE(@nEmpresa,empresa_id),
                   fecha_cese=NULL
             WHERE empleado_id=@nId;
        END;

        IF @bCambioAsignacion=1
        BEGIN
            UPDATE EA
               SET fecha_hasta=@dFechaArea,
                   estado=0
            FROM [org].[EmpleadoArea] EA
            JOIN [org].[Area] AX ON AX.area_id=EA.area_id AND AX.uot_id=@nUot
            WHERE EA.empleado_id=@nId AND EA.estado=1 AND EA.fecha_hasta IS NULL;

            IF @nAreaObjetivo IS NOT NULL
            BEGIN
                INSERT [org].[EmpleadoArea]
                (
                    empleado_id,area_id,cargo,fecha_desde,fecha_hasta,estado
                )
                VALUES
                (
                    @nId,@nAreaObjetivo,@cCargoObjetivo,@dFechaArea,NULL,1
                );
            END;
        END;

        SET @cIdent=CONVERT(NVARCHAR(200),@nId);

        EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio]
             @nUsuario,@nSesion,@nDisp,@nModulo,'EDITAR','org','Empleado',@cIdent,
             NULL,NULL,NULL,NULL,NULL,NULL,@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;

        /* Confirmar datos e idempotencia juntos. */

        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
             @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='COMPLETADA',
             @cEsquemaEntidad='org',@cNombreEntidad='Empleado',
             @cIdentificadorResultado=@cIdent,@cCodigoResultado='EMPLEADO_ACTUALIZADO',
             @bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;

        SET @bResultado=1;
        SET @cMensaje=N'Empleado actualizado.';
        GOTO __DESCO_Salida;
    END TRY
    BEGIN CATCH
SET @bResultado = 0;

        IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
        SET @cMensaje=N'No se pudo actualizar el empleado. Intente nuevamente.';

IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Empleado_Upd_RegistroAdministracion',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;

Fallar:
    IF @nOp IS NOT NULL AND @bResultado=0
        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
             @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='FALLIDA',
             @cEsquemaEntidad=NULL,@cNombreEntidad=NULL,@cIdentificadorResultado=NULL,
             @cCodigoResultado='NO_PROCESADO',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Empleado_Upd_RegistroAdministracion',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

    IF @bResultado = 0 AND @nOp IS NOT NULL AND XACT_STATE() <> -1
    BEGIN
        IF ISNULL(@bRep,0) = 0
        BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                 @nOperacionIdempotenteId = @nOp, @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
            -- No sustituir el motivo funcional por un fallo de registro secundario.
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Empleado_Upd_RegistroAdministracion',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
        END CATCH;
        END
        ELSE
        BEGIN
            SELECT @cMensaje = COALESCE(mensaje_resultado,
                CASE WHEN estado_operacion = 'FALLIDA'
                     THEN N'La solicitud anterior no se completó. Corrija los datos y envíe una nueva solicitud.'
                     ELSE N'La solicitud todavía se está procesando. Consulte el resultado antes de repetirla.' END)
            FROM [auditoria].[OperacionIdempotente]
            WHERE operacion_idempotente_id = @nOp;
        END;
    END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Empleado_Upd_RegistroAdministracion',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'org.PA_Empleado_Upd_RegistroAdministracion',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [org].[PA_Empleado_Upd_RetirarAdministracion]
    @cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON; SET @bResultado=0; SET @cMensaje=N'No se pudo retirar al empleado.'; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;
    DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmpSesion BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),@nAud BIGINT,@nTrans BIGINT,
            @nId BIGINT,@nUotSolicitada BIGINT,@nUot BIGINT,@bGeneral BIT,@bUot BIT,@cUotMsg NVARCHAR(300),@dCese DATE,@cMotivo NVARCHAR(500),@nUsuarioObjetivo BIGINT,@cIdent NVARCHAR(200),@dAhora DATETIME2(0)=SYSUTCDATETIME();
    BEGIN TRY
        EXEC seg.PA_Operacion_Ins_IniciarIdempotente @cJson,'EMPLEADOS_RETIRAR','EMPLEADO_RETIRAR',@nUsuario OUTPUT,@nSesion OUTPUT,@nDisp OUTPUT,@nEmpSesion OUTPUT,@nModulo OUTPUT,@gCorr OUTPUT,@gSol OUTPUT,@cIp OUTPUT,@cEnd OUTPUT,@nOp OUTPUT,@bRep OUTPUT,@cEstadoOp OUTPUT,@cIdRes OUTPUT,@cCodRes OUTPUT,@bIni OUTPUT,@cMsg OUTPUT;
        IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg; GOTO Salida; END;
        IF @bRep=1 BEGIN SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END; SET @cMensaje=CASE WHEN @bResultado=1 THEN N'La solicitud ya fue procesada.' ELSE N'La solicitud está en proceso.' END; GOTO Salida; END;
        SELECT @nId=empleadoId,@nUotSolicitada=uotId,@dCese=fechaCese,@cMotivo=NULLIF(LTRIM(RTRIM(motivo)),N'') FROM OPENJSON(@cJson,'$.empleado') WITH(empleadoId BIGINT '$.empleadoId',uotId BIGINT '$.uotId',fechaCese DATE '$.fechaCese',motivo NVARCHAR(500) '$.motivo');
        SET @dCese=COALESCE(@dCese,CONVERT(date,@dAhora));
        EXEC seg.PA_UOT_Sel_ResolverContextoSesion @nUsuario,@nSesion,@nUotSolicitada,'EMPLEADOS_RETIRAR',1,@nUot OUTPUT,@bGeneral OUTPUT,@bUot OUTPUT,@cUotMsg OUTPUT;
        IF @bUot=0 BEGIN SET @cMensaje=@cUotMsg; GOTO Fallar; END;
        IF @nId=@nEmpSesion BEGIN SET @cMensaje=N'No puede retirar su propio registro.'; GOTO Fallar; END;
        IF @cMotivo IS NULL OR NOT EXISTS(SELECT 1 FROM org.EmpleadoUOT WHERE empleado_id=@nId AND uot_id=@nUot AND estado=1 AND fecha_hasta IS NULL) BEGIN SET @cMensaje=N'El empleado no está disponible o falta el motivo.'; GOTO Fallar; END;
        SELECT @nUsuarioObjetivo=usuario_id FROM seg.Usuario WHERE persona_id=@nId;
        BEGIN TRANSACTION;
        UPDATE EA SET estado=0,fecha_hasta=COALESCE(EA.fecha_hasta,@dCese) FROM org.EmpleadoArea EA JOIN org.Area A ON A.area_id=EA.area_id AND A.uot_id=@nUot WHERE EA.empleado_id=@nId AND EA.estado=1 AND EA.fecha_hasta IS NULL;
        UPDATE org.EmpleadoUOT SET estado=0,fecha_hasta=COALESCE(fecha_hasta,@dCese),fecha_cese=COALESCE(fecha_cese,@dCese),es_principal=0 WHERE empleado_id=@nId AND uot_id=@nUot AND estado=1 AND fecha_hasta IS NULL;
        IF NOT EXISTS(SELECT 1 FROM org.EmpleadoUOT WHERE empleado_id=@nId AND estado=1 AND fecha_hasta IS NULL AND es_principal=1)
           AND EXISTS(SELECT 1 FROM org.EmpleadoUOT WHERE empleado_id=@nId AND estado=1 AND fecha_hasta IS NULL)
        BEGIN
            UPDATE org.EmpleadoUOT SET es_principal=1
            WHERE empleado_uot_id=(SELECT TOP(1) empleado_uot_id FROM org.EmpleadoUOT WHERE empleado_id=@nId AND estado=1 AND fecha_hasta IS NULL ORDER BY fecha_desde,empleado_uot_id);
        END;
        IF @nUsuarioObjetivo IS NOT NULL
        BEGIN
            DECLARE @UU TABLE(id BIGINT PRIMARY KEY); INSERT @UU SELECT usuario_uot_id FROM seg.UsuarioUOT WHERE usuario_id=@nUsuarioObjetivo AND uot_id=@nUot AND estado=1 AND fecha_hasta IS NULL;
            UPDATE P SET estado=0,fecha_hasta=COALESCE(P.fecha_hasta,@dAhora) FROM seg.UsuarioUOTPermiso P JOIN @UU X ON X.id=P.usuario_uot_id WHERE P.estado=1 AND P.fecha_hasta IS NULL;
            UPDATE R SET estado=0,fecha_hasta=COALESCE(R.fecha_hasta,@dAhora) FROM seg.UsuarioUOTRol R JOIN @UU X ON X.id=R.usuario_uot_id WHERE R.estado=1 AND R.fecha_hasta IS NULL;
            UPDATE seg.UsuarioUOT SET estado=0,fecha_hasta=COALESCE(fecha_hasta,@dAhora),es_predeterminada=0 WHERE usuario_id=@nUsuarioObjetivo AND uot_id=@nUot AND estado=1 AND fecha_hasta IS NULL;
            DECLARE @nUotAlterna BIGINT=(SELECT TOP(1) UU.uot_id FROM seg.UsuarioUOT UU JOIN org.UOT U ON U.uot_id=UU.uot_id AND U.estado=1 WHERE UU.usuario_id=@nUsuarioObjetivo AND UU.estado=1 AND UU.fecha_hasta IS NULL ORDER BY UU.es_predeterminada DESC,UU.usuario_uot_id);
            IF @nUotAlterna IS NOT NULL
                UPDATE seg.SesionUsuario SET modo_uot='ESPECIFICA',uot_contexto_id=@nUotAlterna,fecha_ultima_actividad=@dAhora WHERE usuario_id=@nUsuarioObjetivo AND estado=1 AND fecha_revocacion IS NULL AND uot_contexto_id=@nUot;
        END;
        IF NOT EXISTS(SELECT 1 FROM org.EmpleadoUOT WHERE empleado_id=@nId AND estado=1 AND fecha_hasta IS NULL)
        BEGIN
            UPDATE org.Empleado SET estado=0,fecha_cese=@dCese WHERE empleado_id=@nId;
            IF @nUsuarioObjetivo IS NOT NULL
            BEGIN
                UPDATE seg.SesionUsuario SET estado=0,fecha_revocacion=COALESCE(fecha_revocacion,@dAhora),motivo_revocacion=@cMotivo WHERE usuario_id=@nUsuarioObjetivo AND estado=1;
                UPDATE seg.Usuario SET estado=0,estado_cuenta='RETIRADA',token_version=token_version+1,bloqueado_hasta=NULL WHERE usuario_id=@nUsuarioObjetivo;
                UPDATE seg.UsuarioRol SET estado=0,fecha_hasta=COALESCE(fecha_hasta,@dAhora),retirado_por_usuario_id=@nUsuario,motivo_retiro=@cMotivo WHERE usuario_id=@nUsuarioObjetivo AND estado=1 AND fecha_hasta IS NULL;
            END;
        END;
        SET @cIdent=CONVERT(NVARCHAR(200),@nId);
        EXEC auditoria.PA_Operacion_Ins_RegistrarCambio @nUsuario,@nSesion,@nDisp,@nModulo,'RETIRAR','org','EmpleadoUOT',@cIdent,NULL,NULL,@cMotivo,NULL,NULL,NULL,@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
        EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOp,'COMPLETADA','org','EmpleadoUOT',@cIdent,'EMPLEADO_RETIRADO_UOT',@bFin OUTPUT,@cMsgFin OUTPUT;
        IF ISNULL(@bFin,0)=0 THROW 51038,N'No se pudo confirmar la operación.',1;
        COMMIT; SET @bResultado=1; SET @cMensaje=N'Empleado retirado de la UOT.'; GOTO Salida;
Fallar:
        IF @nOp IS NOT NULL AND @bResultado=0 EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOp,'FALLIDA',NULL,NULL,NULL,'NO_PROCESADO',@bFin OUTPUT,@cMsgFin OUTPUT;
    END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SET @bResultado=0; SET @cMensaje=N'No se pudo retirar al empleado.'; END CATCH
Salida:
    SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido FROM config.FN_RespuestaUsuario(N'org.PA_Empleado_Upd_RetirarAdministracion',@bResultado,@cMensaje) R;
    RETURN CASE WHEN @bResultado=1 THEN 0 ELSE 1 END;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO


CREATE OR ALTER PROCEDURE [org].[PA_Empresa_Ins_Registro]
    @cJson NVARCHAR(MAX),@nEmpresaId BIGINT OUTPUT,@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    SET @nEmpresaId=NULL; SET @bResultado=0; SET @cMensaje=N'No se pudo registrar la empresa.';
    SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;
    DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),
            @nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),
            @nAud BIGINT,@nTrans BIGINT,@cRuc VARCHAR(30),@cRazon NVARCHAR(200),@cNombre NVARCHAR(160),@cTel VARCHAR(30),@cCorreo VARCHAR(180),
            @cDistrito CHAR(6),@nCentro BIGINT,@cReferencia NVARCHAR(300),@bExistia BIT,@bBase BIT,@cMsgBase NVARCHAR(300),@cIdent NVARCHAR(200),
            @nUotSolicitada BIGINT,@nUot BIGINT,@bGeneral BIT,@bUot BIT,@cUotMsg NVARCHAR(300);
    BEGIN TRY
        EXEC seg.PA_Operacion_Ins_IniciarIdempotente @cJson,'ORGANIZACIONES_CREAR','EMPRESA_CREAR',@nUsuario OUTPUT,@nSesion OUTPUT,@nDisp OUTPUT,@nEmp OUTPUT,@nModulo OUTPUT,@gCorr OUTPUT,@gSol OUTPUT,@cIp OUTPUT,@cEnd OUTPUT,@nOp OUTPUT,@bRep OUTPUT,@cEstadoOp OUTPUT,@cIdRes OUTPUT,@cCodRes OUTPUT,@bIni OUTPUT,@cMsg OUTPUT;
        IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg; GOTO Salida; END;
        IF @bRep=1 BEGIN SET @nEmpresaId=CASE WHEN @cEstadoOp='COMPLETADA' THEN TRY_CONVERT(BIGINT,@cIdRes) END; SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END; SET @cMensaje=CASE WHEN @bResultado=1 THEN N'La solicitud ya fue procesada.' ELSE N'La solicitud está en proceso.' END; GOTO Salida; END;

        SELECT @nUotSolicitada=uotId,@cRuc=NULLIF(LTRIM(RTRIM(ruc)),''),@cRazon=NULLIF(LTRIM(RTRIM(razonSocial)),N''),@cNombre=NULLIF(LTRIM(RTRIM(nombreComercial)),N''),@cTel=NULLIF(LTRIM(RTRIM(telefono)),''),@cCorreo=NULLIF(LTRIM(RTRIM(correo)),'')
        FROM OPENJSON(@cJson,'$.empresa') WITH(uotId BIGINT '$.uotId',ruc VARCHAR(30) '$.ruc',razonSocial NVARCHAR(200) '$.razonSocial',nombreComercial NVARCHAR(160) '$.nombreComercial',telefono VARCHAR(30) '$.telefono',correo VARCHAR(180) '$.correo');
        SELECT @cDistrito=COALESCE(NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.empresa.ubicacion.distritoCodigo'))),''),NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.ubicacion.distritoCodigo'))),'')),
               @nCentro=TRY_CONVERT(BIGINT,COALESCE(JSON_VALUE(@cJson,'$.empresa.ubicacion.centroPobladoId'),JSON_VALUE(@cJson,'$.ubicacion.centroPobladoId'))),
               @cReferencia=COALESCE(NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.empresa.ubicacion.referencia'))),N''),NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.ubicacion.referencia'))),N''));
        EXEC seg.PA_UOT_Sel_ResolverContextoSesion @nUsuario,@nSesion,@nUotSolicitada,'ORGANIZACIONES_CREAR',1,@nUot OUTPUT,@bGeneral OUTPUT,@bUot OUTPUT,@cUotMsg OUTPUT;
        IF @bUot=0 BEGIN SET @cMensaje=@cUotMsg; GOTO Fallar; END;
        IF @cRuc IS NULL OR @cRazon IS NULL OR @cDistrito IS NULL BEGIN SET @cMensaje=N'Complete los datos obligatorios.'; GOTO Fallar; END;

        BEGIN TRANSACTION;
        EXEC org.PA_Empresa_InsOUpd_DesdeFormulario @cRuc,@cRazon,@cNombre,@cTel,@cCorreo,@cDistrito,@nCentro,@cReferencia,@nEmpresaId OUTPUT,@bExistia OUTPUT,@bBase OUTPUT,@cMsgBase OUTPUT;
        IF @bBase=0 BEGIN ROLLBACK; SET @cMensaje=@cMsgBase; GOTO Fallar; END;
        IF EXISTS(SELECT 1 FROM org.Asociacion WHERE asociacion_id=@nEmpresaId AND estado=1) BEGIN ROLLBACK; SET @cMensaje=N'La organización ya está registrada como asociación.'; GOTO Fallar; END;
        IF EXISTS(SELECT 1 FROM org.ConvenioUOTOrganizacion WHERE uot_id=@nUot AND empresa_id=@nEmpresaId AND estado=1 AND fecha_fin IS NULL) BEGIN ROLLBACK; SET @cMensaje=N'La organización ya está vinculada a esta UOT.'; GOTO Fallar; END;
        INSERT org.ConvenioUOTOrganizacion(uot_id,empresa_id,tipo_vinculo,numero_convenio,fecha_inicio,fecha_fin,descripcion,estado,fecha_creacion)
        VALUES(@nUot,@nEmpresaId,'EMPRESA',NULL,CONVERT(date,SYSUTCDATETIME()),NULL,N'Contrato directo con la UOT.',1,SYSUTCDATETIME());
        SET @cIdent=CONVERT(NVARCHAR(200),@nEmpresaId);
        EXEC auditoria.PA_Operacion_Ins_RegistrarCambio @nUsuario,@nSesion,@nDisp,@nModulo,'CREAR','org','ConvenioUOTOrganizacion',@cIdent,NULL,NULL,NULL,NULL,NULL,NULL,@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
        EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOp,'COMPLETADA','org','Empresa',@cIdent,'EMPRESA_CREADA',@bFin OUTPUT,@cMsgFin OUTPUT;
        IF ISNULL(@bFin,0)=0 THROW 51030,N'No se pudo confirmar la operación.',1;
        COMMIT;
        SET @bResultado=1; SET @cMensaje=N'Empresa registrada en la UOT.'; GOTO Salida;
Fallar:
        IF @nOp IS NOT NULL AND @bResultado=0 EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOp,'FALLIDA',NULL,NULL,NULL,'NO_PROCESADO',@bFin OUTPUT,@cMsgFin OUTPUT;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK;
        SET @nEmpresaId=NULL; SET @bResultado=0; SET @cMensaje=N'No se pudo registrar la empresa.';
        IF @nOp IS NOT NULL BEGIN TRY EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOp,'FALLIDA',NULL,NULL,NULL,'NO_PROCESADO',@bFin OUTPUT,@cMsgFin OUTPUT; END TRY BEGIN CATCH END CATCH;
    END CATCH
Salida:
    SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido FROM config.FN_RespuestaUsuario(N'org.PA_Empresa_Ins_Registro',@bResultado,@cMensaje) R;
    RETURN CASE WHEN @bResultado=1 THEN 0 ELSE 1 END;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [org].[PA_Empresa_InsOUpd_DesdeFormulario]
(
    @cRuc VARCHAR(30),
    @cRazonSocial NVARCHAR(200),
    @cNombreComercial NVARCHAR(160)=NULL,
    @cTelefono VARCHAR(30)=NULL,
    @cCorreo VARCHAR(180)=NULL,
    @cDistritoCodigo CHAR(6),
    @nCentroPobladoId BIGINT=NULL,
    @cReferencia NVARCHAR(300)=NULL,
    @nEmpresaId BIGINT OUTPUT,
    @bEmpresaExistia BIT OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY
BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

    SET NOCOUNT ON;

    DECLARE @cR VARCHAR(30)=NULLIF(LTRIM(RTRIM(@cRuc)),'');
    DECLARE @cRazon NVARCHAR(200)=NULLIF(LTRIM(RTRIM(@cRazonSocial)),N'');
    DECLARE @cNombre NVARCHAR(160)=NULLIF(LTRIM(RTRIM(@cNombreComercial)),N'');
    DECLARE @cTel VARCHAR(30)=NULLIF(LTRIM(RTRIM(@cTelefono)),'');
    DECLARE @cMail VARCHAR(180)=NULLIF(LTRIM(RTRIM(@cCorreo)),'');
    DECLARE @cDistrito CHAR(6)=NULLIF(LTRIM(RTRIM(@cDistritoCodigo)),'');
    DECLARE @cRef NVARCHAR(300)=NULLIF(LTRIM(RTRIM(@cReferencia)),N'');
    DECLARE @nUbicacionId BIGINT=NULL;
    DECLARE @bUbi BIT,@cMsgUbi NVARCHAR(300);

    SELECT @nEmpresaId=NULL,@bEmpresaExistia=0,@bResultado=0,
           @cMensaje=N'No se pudo completar la empresa.';

    IF @cR IS NULL
       OR LEN(@cR)<>11
       OR @cR LIKE '%[^0-9]%'
    BEGIN
        SET @cMensaje=N'El RUC debe tener 11 dígitos.';
        GOTO __DESCO_Salida;
    END;

    IF @cRazon IS NULL OR @cDistrito IS NULL
    BEGIN
        SET @cMensaje=N'Complete razón social y distrito.';
        GOTO __DESCO_Salida;
    END;

    IF @cMail IS NOT NULL AND @cMail NOT LIKE '%_@_%._%'
    BEGIN
        SET @cMensaje=N'Ingrese un correo válido.';
        GOTO __DESCO_Salida;
    END;

    IF NOT EXISTS(SELECT 1 FROM [geo].[Distrito] WHERE distrito_codigo=@cDistrito AND estado=1)
    BEGIN
        SET @cMensaje=N'El distrito seleccionado no está disponible.';
        GOTO __DESCO_Salida;
    END;

    IF @nCentroPobladoId IS NOT NULL
       AND NOT EXISTS
       (
           SELECT 1 FROM [geo].[CentroPoblado]
           WHERE centro_poblado_id=@nCentroPobladoId
             AND distrito_codigo=@cDistrito
             AND estado=1
       )
    BEGIN
        SET @cMensaje=N'El centro poblado no corresponde al distrito seleccionado.';
        GOTO __DESCO_Salida;
    END;

    SELECT @nEmpresaId=empresa_id,@nUbicacionId=ubicacion_id
    FROM [org].[Empresa] WITH (UPDLOCK,HOLDLOCK)
    WHERE ruc=@cR;

    SET @bEmpresaExistia=CASE WHEN @nEmpresaId IS NULL THEN 0 ELSE 1 END;
    IF @cMail IS NOT NULL AND EXISTS
    (
        SELECT 1 FROM [org].[Empresa] WITH (UPDLOCK, HOLDLOCK)
        WHERE correo_clave_desco = LOWER(LTRIM(RTRIM(@cMail))) COLLATE Latin1_General_100_CI_AS
          AND (@nEmpresaId IS NULL OR empresa_id <> @nEmpresaId)
    )
    BEGIN
        SET @cMensaje = N'El correo electrónico ya pertenece a otra organización registrada.';
        GOTO __DESCO_Salida;
    END;

    IF @nEmpresaId IS NULL
    BEGIN
        EXEC [geo].[PA_Ubicacion_Ins_Interna]
             @cDistritoCodigo=@cDistrito,
             @nCentroPobladoId=@nCentroPobladoId,
             @cReferencia=@cRef,
             @nLatitud=NULL,@nLongitud=NULL,@nAltitudM=NULL,
             @nUbicacionId=@nUbicacionId OUTPUT,
             @bResultado=@bUbi OUTPUT,
             @cMensaje=@cMsgUbi OUTPUT;

        IF @bUbi=0
        BEGIN
            SET @cMensaje=@cMsgUbi;
            GOTO __DESCO_Salida;
        END;

        INSERT [org].[Empresa]
        (ruc,razon_social,nombre_comercial,telefono,correo,ubicacion_id,fecha_creacion,estado)
        VALUES
        (@cR,@cRazon,@cNombre,@cTel,@cMail,@nUbicacionId,SYSUTCDATETIME(),1);

        SET @nEmpresaId=CONVERT(BIGINT,SCOPE_IDENTITY());
    END
    ELSE
    BEGIN
        IF @nUbicacionId IS NULL
        BEGIN
            EXEC [geo].[PA_Ubicacion_Ins_Interna]
                 @cDistritoCodigo=@cDistrito,
                 @nCentroPobladoId=@nCentroPobladoId,
                 @cReferencia=@cRef,
                 @nLatitud=NULL,@nLongitud=NULL,@nAltitudM=NULL,
                 @nUbicacionId=@nUbicacionId OUTPUT,
                 @bResultado=@bUbi OUTPUT,
                 @cMensaje=@cMsgUbi OUTPUT;
        END
        ELSE
        BEGIN
            EXEC [geo].[PA_Ubicacion_Upd_Interna]
                 @nUbicacionId=@nUbicacionId,
                 @cDistritoCodigo=@cDistrito,
                 @nCentroPobladoId=@nCentroPobladoId,
                 @cReferencia=@cRef,
                 @bResultado=@bUbi OUTPUT,
                 @cMensaje=@cMsgUbi OUTPUT;
        END;

        IF @bUbi=0
        BEGIN
            SET @cMensaje=@cMsgUbi;
            GOTO __DESCO_Salida;
        END;

        UPDATE [org].[Empresa]
           SET razon_social=@cRazon,
               nombre_comercial=@cNombre,
               telefono=@cTel,
               correo=@cMail,
               ubicacion_id=@nUbicacionId,
               estado=1
         WHERE empresa_id=@nEmpresaId;
    END;

    SET @bResultado=1;
    SET @cMensaje=CASE WHEN @bEmpresaExistia=1
                       THEN N'Empresa existente completada correctamente.'
                       ELSE N'Empresa registrada correctamente.' END;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Empresa_InsOUpd_DesdeFormulario',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
    IF @__DbError = 0 AND @bResultado = 1 AND XACT_STATE() = 1
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
    ELSE
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Empresa_InsOUpd_DesdeFormulario',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
IF ISNULL(@bResultado,0) = 0 SELECT @nEmpresaId=NULL;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'org.PA_Empresa_InsOUpd_DesdeFormulario',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/*
    Parche organizaciones / UOT

    Objetivo:
    - mantener la vista general multi-UOT ya soportada por los PA actuales;
    - hacer que la clasificación Empresa/Asociación salga del vínculo vigente
      ConvenioUOTOrganizacion.tipo_vinculo, que es el contexto contractual de la UOT;
    - conservar exactamente el contrato de columnas actual para no forzar cambios
      de Swagger ni del cliente Angular en esta fase.

    No se modifica PA_Area_Sel_Listado porque ya devuelve uotId, uotCodigo y
    uotNombre y ya admite vista general cuando no se filtra una UOT concreta.
*/

CREATE OR ALTER PROCEDURE [org].[PA_Empresa_Sel_Detalle]
    @cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON; SET @bResultado=0; SET @cMensaje=N'No se pudo consultar la organización.';
    SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;
    BEGIN TRY
        DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@bCtx BIT,@cMsg NVARCHAR(300);
        EXEC seg.PA_Operacion_Sel_ContextoAutorizado @cJson,'ORGANIZACIONES_VER',@nUsuario OUTPUT,@nSesion OUTPUT,@nDisp OUTPUT,@nEmp OUTPUT,@nModulo OUTPUT,@gCorr OUTPUT,@gSol OUTPUT,@cIp OUTPUT,@cEnd OUTPUT,@bCtx OUTPUT,@cMsg OUTPUT;
        IF @bCtx=0 BEGIN SET @cMensaje=@cMsg; GOTO Salida; END;
        DECLARE @nId BIGINT=COALESCE(TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.organizacion.empresaId')),TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.empresa.empresaId')),TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.empresaId')),TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.filtros.empresaId'))),
                @nUotSolicitada BIGINT=TRY_CONVERT(BIGINT,COALESCE(JSON_VALUE(@cJson,'$.organizacion.uotId'),JSON_VALUE(@cJson,'$.filtros.uotId'),JSON_VALUE(@cJson,'$.uotId'))),
                @nUot BIGINT,@bGeneral BIT,@bUot BIT,@cUotMsg NVARCHAR(300);
        EXEC seg.PA_UOT_Sel_ResolverContextoSesion @nUsuario,@nSesion,@nUotSolicitada,'ORGANIZACIONES_VER',1,@nUot OUTPUT,@bGeneral OUTPUT,@bUot OUTPUT,@cUotMsg OUTPUT;
        IF @bUot=0 BEGIN SET @cMensaje=@cUotMsg; GOTO Salida; END;
        IF NOT EXISTS(SELECT 1 FROM org.ConvenioUOTOrganizacion WHERE empresa_id=@nId AND uot_id=@nUot AND estado=1 AND fecha_fin IS NULL)
        BEGIN SET @cMensaje=N'La organización no está disponible en esta UOT.'; GOTO Salida; END;

        SELECT C.convenio_uot_organizacion_id convenioUotOrganizacionId,C.uot_id uotId,UO.codigo uotCodigo,UO.nombre uotNombre,C.tipo_vinculo tipoVinculo,
               E.empresa_id empresaId,E.ruc,E.razon_social razonSocial,E.nombre_comercial nombreComercial,E.telefono,E.correo,E.fecha_creacion fechaCreacion,E.estado,
               CONVERT(BIT,CASE WHEN C.tipo_vinculo='ASOCIACION' THEN 1 ELSE 0 END) esAsociacion,A.fecha_constitucion fechaConstitucion,A.numero_partida numeroPartida,
               UB.distrito_codigo distritoCodigo,D.nombre distritoNombre,UB.centro_poblado_id centroPobladoId,CP.nombre centroPobladoNombre,UB.referencia referencia,
               UB.altitud_m altitudM,CASE WHEN UB.posicion IS NULL THEN NULL ELSE UB.posicion.STAsText() END posicionWkt,
               CASE WHEN UB.posicion IS NULL THEN NULL ELSE UB.posicion.STSrid END posicionSrid
        FROM org.ConvenioUOTOrganizacion C
        JOIN org.UOT UO ON UO.uot_id=C.uot_id
        JOIN org.Empresa E ON E.empresa_id=C.empresa_id
        LEFT JOIN org.Asociacion A ON A.asociacion_id=E.empresa_id AND A.estado=1 AND C.tipo_vinculo='ASOCIACION'
        LEFT JOIN geo.Ubicacion UB ON UB.ubicacion_id=E.ubicacion_id
        LEFT JOIN geo.Distrito D ON D.distrito_codigo=UB.distrito_codigo
        LEFT JOIN geo.CentroPoblado CP ON CP.centro_poblado_id=UB.centro_poblado_id AND CP.distrito_codigo=UB.distrito_codigo
        WHERE C.empresa_id=@nId AND C.uot_id=@nUot AND C.estado=1 AND C.fecha_fin IS NULL;

        /* Compatibilidad temporal: resultados secundarios vacíos; Area/Empleado ya no son hijos de Empresa. */
        SELECT TOP(0) CAST(NULL AS BIGINT) areaId,CAST(NULL AS BIGINT) uotId,CAST(NULL AS NVARCHAR(160)) uotNombre,CAST(NULL AS BIGINT) areaPadreId,CAST(NULL AS NVARCHAR(120)) areaPadre,CAST(NULL AS VARCHAR(30)) codigo,CAST(NULL AS NVARCHAR(120)) nombre,CAST(NULL AS BIT) estado;
        SELECT TOP(0) CAST(NULL AS BIGINT) empleadoId,CAST(NULL AS VARCHAR(30)) codigoEmpleado,CAST(NULL AS VARCHAR(30)) numeroDocumento,CAST(NULL AS NVARCHAR(300)) empleado;

        SET @bResultado=1; SET @cMensaje=N'Organización consultada.';
    END TRY
    BEGIN CATCH SET @bResultado=0; SET @cMensaje=N'No se pudo consultar la organización.'; END CATCH
Salida:
    SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
    FROM config.FN_RespuestaUsuario(N'org.PA_Empresa_Sel_Detalle',@bResultado,@cMensaje) R;
    RETURN CASE WHEN @bResultado=1 THEN 0 ELSE 1 END;
END;


GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [org].[PA_Empresa_Sel_Listado]
    @cJson NVARCHAR(MAX),
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @bResultado=0; SET @cMensaje=N'No se pudieron consultar las organizaciones.';
    SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;
    BEGIN TRY
        DECLARE @nPagina INT,@nTamano INT,@nOffset BIGINT;
        EXEC seg.PA_Consulta_Sel_ResolverPaginacion @cJson,@nPagina OUTPUT,@nTamano OUTPUT,@nOffset OUTPUT;
        DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@bCtx BIT,@cMsg NVARCHAR(300);
        EXEC seg.PA_Operacion_Sel_ContextoAutorizado @cJson,'ORGANIZACIONES_LISTAR',@nUsuario OUTPUT,@nSesion OUTPUT,@nDisp OUTPUT,@nEmp OUTPUT,@nModulo OUTPUT,@gCorr OUTPUT,@gSol OUTPUT,@cIp OUTPUT,@cEnd OUTPUT,@bCtx OUTPUT,@cMsg OUTPUT;
        IF @bCtx=0 BEGIN SET @cMensaje=@cMsg; GOTO Salida; END;

        DECLARE @nUotSolicitada BIGINT=TRY_CONVERT(BIGINT,COALESCE(JSON_VALUE(@cJson,'$.filtros.uotId'),JSON_VALUE(@cJson,'$.uotId'))),
                @nUot BIGINT,@bGeneral BIT,@bUot BIT,@cUotMsg NVARCHAR(300);
        EXEC seg.PA_UOT_Sel_ResolverContextoSesion @nUsuario,@nSesion,@nUotSolicitada,'ORGANIZACIONES_LISTAR',0,@nUot OUTPUT,@bGeneral OUTPUT,@bUot OUTPUT,@cUotMsg OUTPUT;
        IF @bUot=0 BEGIN SET @cMensaje=@cUotMsg; GOTO Salida; END;

        SELECT C.convenio_uot_organizacion_id convenioUotOrganizacionId,
               C.uot_id uotId,U.codigo uotCodigo,U.nombre uotNombre,C.tipo_vinculo tipoVinculo,
               E.empresa_id empresaId,E.ruc,E.razon_social razonSocial,E.nombre_comercial nombreComercial,
               E.telefono,E.correo,E.fecha_creacion fechaCreacion,E.estado,
               CONVERT(BIT,CASE WHEN C.tipo_vinculo='ASOCIACION' THEN 1 ELSE 0 END) esAsociacion,
               A.fecha_constitucion fechaConstitucion,A.numero_partida numeroPartida,
               COUNT_BIG(*) OVER() totalRegistros
        FROM org.ConvenioUOTOrganizacion C
        JOIN org.UOT U ON U.uot_id=C.uot_id AND U.estado=1
        JOIN org.Empresa E ON E.empresa_id=C.empresa_id AND E.estado=1
        LEFT JOIN org.Asociacion A ON A.asociacion_id=E.empresa_id AND A.estado=1 AND C.tipo_vinculo='ASOCIACION'
        WHERE C.estado=1 AND C.fecha_fin IS NULL
          AND (@nUot IS NULL OR C.uot_id=@nUot)
          AND seg.FN_Usuario_TienePermisoUOT(@nUsuario,C.uot_id,'ORGANIZACIONES_LISTAR')=1
        ORDER BY U.nombre,E.razon_social,E.empresa_id
        OFFSET @nOffset ROWS FETCH NEXT @nTamano ROWS ONLY;

        SET @bResultado=1; SET @cMensaje=N'Organizaciones consultadas.';
    END TRY
    BEGIN CATCH
        SET @bResultado=0; SET @cMensaje=N'No se pudieron consultar las organizaciones.';
    END CATCH
Salida:
    SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
    FROM config.FN_RespuestaUsuario(N'org.PA_Empresa_Sel_Listado',@bResultado,@cMensaje) R;
    RETURN CASE WHEN @bResultado=1 THEN 0 ELSE 1 END;
END;


GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO


CREATE OR ALTER PROCEDURE [org].[PA_Empresa_Upd_DeshabilitarAdministracion]
    @cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON; SET @bResultado=0; SET @cMensaje=N'No se pudo retirar la organización de la UOT.'; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;
    DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),@nAud BIGINT,@nTrans BIGINT,
            @nId BIGINT,@nUotSolicitada BIGINT,@nUot BIGINT,@bGeneral BIT,@bUot BIT,@cUotMsg NVARCHAR(300),@cMotivo NVARCHAR(500),@cIdent NVARCHAR(200),@cTipo VARCHAR(20);
    BEGIN TRY
        EXEC seg.PA_Operacion_Ins_IniciarIdempotente @cJson,'ORGANIZACIONES_RETIRAR','ORGANIZACION_DESHABILITAR',@nUsuario OUTPUT,@nSesion OUTPUT,@nDisp OUTPUT,@nEmp OUTPUT,@nModulo OUTPUT,@gCorr OUTPUT,@gSol OUTPUT,@cIp OUTPUT,@cEnd OUTPUT,@nOp OUTPUT,@bRep OUTPUT,@cEstadoOp OUTPUT,@cIdRes OUTPUT,@cCodRes OUTPUT,@bIni OUTPUT,@cMsg OUTPUT;
        IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg; GOTO Salida; END;
        IF @bRep=1 BEGIN SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END; SET @cMensaje=CASE WHEN @bResultado=1 THEN N'La solicitud ya fue procesada.' ELSE N'La solicitud está en proceso.' END; GOTO Salida; END;
        SELECT @nId=COALESCE(TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.organizacion.empresaId')),TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.empresaId'))),@nUotSolicitada=TRY_CONVERT(BIGINT,COALESCE(JSON_VALUE(@cJson,'$.organizacion.uotId'),JSON_VALUE(@cJson,'$.uotId'))),@cMotivo=NULLIF(LTRIM(RTRIM(COALESCE(JSON_VALUE(@cJson,'$.organizacion.motivo'),JSON_VALUE(@cJson,'$.motivo')))),N'');
        EXEC seg.PA_UOT_Sel_ResolverContextoSesion @nUsuario,@nSesion,@nUotSolicitada,'ORGANIZACIONES_RETIRAR',1,@nUot OUTPUT,@bGeneral OUTPUT,@bUot OUTPUT,@cUotMsg OUTPUT;
        IF @bUot=0 BEGIN SET @cMensaje=@cUotMsg; GOTO Fallar; END;
        SELECT TOP(1) @cTipo=tipo_vinculo FROM org.ConvenioUOTOrganizacion WHERE empresa_id=@nId AND uot_id=@nUot AND estado=1 AND fecha_fin IS NULL;
        IF @cTipo IS NULL OR @cMotivo IS NULL BEGIN SET @cMensaje=N'La organización no está disponible o falta el motivo.'; GOTO Fallar; END;
        BEGIN TRANSACTION;
        UPDATE org.ConvenioUOTOrganizacion SET estado=0,fecha_fin=COALESCE(fecha_fin,CONVERT(date,SYSUTCDATETIME())),descripcion=COALESCE(descripcion+N' ',N'')+N'Retiro: '+@cMotivo WHERE empresa_id=@nId AND uot_id=@nUot AND estado=1 AND fecha_fin IS NULL;
        IF @cTipo='ASOCIACION' UPDATE org.Asociacion SET estado=0 WHERE asociacion_id=@nId AND uot_id=@nUot;
        IF NOT EXISTS(SELECT 1 FROM org.ConvenioUOTOrganizacion WHERE empresa_id=@nId AND estado=1 AND fecha_fin IS NULL)
           AND NOT EXISTS(SELECT 1 FROM org.UOT WHERE empresa_legacy_id=@nId AND estado=1)
            UPDATE org.Empresa SET estado=0 WHERE empresa_id=@nId;
        SET @cIdent=CONVERT(NVARCHAR(200),@nId);
        EXEC auditoria.PA_Operacion_Ins_RegistrarCambio @nUsuario,@nSesion,@nDisp,@nModulo,'RETIRAR','org','ConvenioUOTOrganizacion',@cIdent,NULL,NULL,@cMotivo,NULL,NULL,NULL,@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
        EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOp,'COMPLETADA','org','ConvenioUOTOrganizacion',@cIdent,'ORGANIZACION_RETIRADA_UOT',@bFin OUTPUT,@cMsgFin OUTPUT;
        IF ISNULL(@bFin,0)=0 THROW 51034,N'No se pudo confirmar la operación.',1;
        COMMIT; SET @bResultado=1; SET @cMensaje=N'Organización retirada de la UOT.'; GOTO Salida;
Fallar:
        IF @nOp IS NOT NULL AND @bResultado=0 EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOp,'FALLIDA',NULL,NULL,NULL,'NO_PROCESADO',@bFin OUTPUT,@cMsgFin OUTPUT;
    END TRY
    BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SET @bResultado=0; SET @cMensaje=N'No se pudo retirar la organización de la UOT.'; END CATCH
Salida:
    SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido FROM config.FN_RespuestaUsuario(N'org.PA_Empresa_Upd_DeshabilitarAdministracion',@bResultado,@cMensaje) R;
    RETURN CASE WHEN @bResultado=1 THEN 0 ELSE 1 END;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO


CREATE OR ALTER PROCEDURE [org].[PA_Empresa_Upd_Registro]
    @cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON; SET @bResultado=0; SET @cMensaje=N'No se pudo actualizar la empresa.'; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;
    DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),@nAud BIGINT,@nTrans BIGINT,
            @nId BIGINT,@nUotSolicitada BIGINT,@nUot BIGINT,@bGeneral BIT,@bUot BIT,@cUotMsg NVARCHAR(300),@cRazon NVARCHAR(200),@cNombre NVARCHAR(160),@cTel VARCHAR(30),@cCorreo VARCHAR(180),@cDistrito CHAR(6),@nCentro BIGINT,@cReferencia NVARCHAR(300),@nUbicacion BIGINT,@bUbi BIT,@cMsgUbi NVARCHAR(300),@cIdent NVARCHAR(200);
    BEGIN TRY
        EXEC seg.PA_Operacion_Ins_IniciarIdempotente @cJson,'ORGANIZACIONES_EDITAR','EMPRESA_EDITAR',@nUsuario OUTPUT,@nSesion OUTPUT,@nDisp OUTPUT,@nEmp OUTPUT,@nModulo OUTPUT,@gCorr OUTPUT,@gSol OUTPUT,@cIp OUTPUT,@cEnd OUTPUT,@nOp OUTPUT,@bRep OUTPUT,@cEstadoOp OUTPUT,@cIdRes OUTPUT,@cCodRes OUTPUT,@bIni OUTPUT,@cMsg OUTPUT;
        IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg; GOTO Salida; END;
        IF @bRep=1 BEGIN SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END; SET @cMensaje=CASE WHEN @bResultado=1 THEN N'La solicitud ya fue procesada.' ELSE N'La solicitud está en proceso.' END; GOTO Salida; END;
        SELECT @nId=empresaId,@nUotSolicitada=uotId,@cRazon=NULLIF(LTRIM(RTRIM(razonSocial)),N''),@cNombre=NULLIF(LTRIM(RTRIM(nombreComercial)),N''),@cTel=NULLIF(LTRIM(RTRIM(telefono)),''),@cCorreo=NULLIF(LTRIM(RTRIM(correo)),'') FROM OPENJSON(@cJson,'$.empresa') WITH(empresaId BIGINT '$.empresaId',uotId BIGINT '$.uotId',razonSocial NVARCHAR(200) '$.razonSocial',nombreComercial NVARCHAR(160) '$.nombreComercial',telefono VARCHAR(30) '$.telefono',correo VARCHAR(180) '$.correo');
        SELECT @cDistrito=NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.empresa.ubicacion.distritoCodigo'))),''),@nCentro=TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.empresa.ubicacion.centroPobladoId')),@cReferencia=NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.empresa.ubicacion.referencia'))),N'');
        EXEC seg.PA_UOT_Sel_ResolverContextoSesion @nUsuario,@nSesion,@nUotSolicitada,'ORGANIZACIONES_EDITAR',1,@nUot OUTPUT,@bGeneral OUTPUT,@bUot OUTPUT,@cUotMsg OUTPUT;
        IF @bUot=0 BEGIN SET @cMensaje=@cUotMsg; GOTO Fallar; END;
        IF @nId IS NULL OR @cRazon IS NULL OR @cDistrito IS NULL OR NOT EXISTS(SELECT 1 FROM org.ConvenioUOTOrganizacion WHERE uot_id=@nUot AND empresa_id=@nId AND tipo_vinculo='EMPRESA' AND estado=1 AND fecha_fin IS NULL) BEGIN SET @cMensaje=N'La empresa no está disponible en esta UOT.'; GOTO Fallar; END;
        SELECT @nUbicacion=ubicacion_id FROM org.Empresa WHERE empresa_id=@nId AND estado=1;
        BEGIN TRANSACTION;
        IF @nUbicacion IS NULL EXEC geo.PA_Ubicacion_Ins_Interna @cDistrito,@nCentro,@cReferencia,NULL,NULL,NULL,@nUbicacion OUTPUT,@bUbi OUTPUT,@cMsgUbi OUTPUT;
        ELSE EXEC geo.PA_Ubicacion_Upd_Interna @nUbicacion,@cDistrito,@nCentro,@cReferencia,@bUbi OUTPUT,@cMsgUbi OUTPUT;
        IF ISNULL(@bUbi,0)=0 BEGIN ROLLBACK; SET @cMensaje=COALESCE(@cMsgUbi,N'La ubicación no es válida.'); GOTO Fallar; END;
        UPDATE org.Empresa SET razon_social=@cRazon,nombre_comercial=@cNombre,telefono=@cTel,correo=@cCorreo,ubicacion_id=@nUbicacion WHERE empresa_id=@nId;
        SET @cIdent=CONVERT(NVARCHAR(200),@nId);
        EXEC auditoria.PA_Operacion_Ins_RegistrarCambio @nUsuario,@nSesion,@nDisp,@nModulo,'EDITAR','org','Empresa',@cIdent,NULL,NULL,NULL,NULL,NULL,NULL,@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
        EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOp,'COMPLETADA','org','Empresa',@cIdent,'EMPRESA_ACTUALIZADA',@bFin OUTPUT,@cMsgFin OUTPUT;
        IF ISNULL(@bFin,0)=0 THROW 51032,N'No se pudo confirmar la operación.',1;
        COMMIT; SET @bResultado=1; SET @cMensaje=N'Empresa actualizada.'; GOTO Salida;
Fallar:
        IF @nOp IS NOT NULL AND @bResultado=0 EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOp,'FALLIDA',NULL,NULL,NULL,'NO_PROCESADO',@bFin OUTPUT,@cMsgFin OUTPUT;
    END TRY
    BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SET @bResultado=0; SET @cMensaje=N'No se pudo actualizar la empresa.'; END CATCH
Salida:
    SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido FROM config.FN_RespuestaUsuario(N'org.PA_Empresa_Upd_Registro',@bResultado,@cMensaje) R;
    RETURN CASE WHEN @bResultado=1 THEN 0 ELSE 1 END;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- org.PA_Persona_InsOUpd_DesdeFormulario
CREATE OR ALTER PROCEDURE [org].[PA_Persona_InsOUpd_DesdeFormulario]
(
    @cTipoDocumento VARCHAR(15),
    @cNumeroDocumento VARCHAR(30),
    @cNombres NVARCHAR(100),
    @cApellidoPaterno NVARCHAR(80),
    @cApellidoMaterno NVARCHAR(80)=NULL,
    @cTelefono VARCHAR(30)=NULL,
    @cCorreo VARCHAR(180)=NULL,
    @dFechaNacimiento DATE=NULL,
    @cDistritoCodigo CHAR(6),
    @nCentroPobladoId BIGINT=NULL,
    @cReferencia NVARCHAR(300)=NULL,
    @nPersonaEsperadaId BIGINT=NULL,
    @nPersonaId BIGINT OUTPUT,
    @bPersonaExistia BIT OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY
BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

    SET NOCOUNT ON;

    DECLARE @cTipo VARCHAR(15)=UPPER(NULLIF(LTRIM(RTRIM(@cTipoDocumento)),''));
    DECLARE @cDoc VARCHAR(30)=NULLIF(LTRIM(RTRIM(@cNumeroDocumento)),'');
    DECLARE @cNom NVARCHAR(100)=NULLIF(LTRIM(RTRIM(@cNombres)),N'');
    DECLARE @cAP NVARCHAR(80)=NULLIF(LTRIM(RTRIM(@cApellidoPaterno)),N'');
    DECLARE @cAM NVARCHAR(80)=NULLIF(LTRIM(RTRIM(@cApellidoMaterno)),N'');
    DECLARE @cTel VARCHAR(30)=NULLIF(LTRIM(RTRIM(@cTelefono)),'');
    DECLARE @cMail VARCHAR(180)=NULLIF(LTRIM(RTRIM(@cCorreo)),'');
    DECLARE @cDistrito CHAR(6)=NULLIF(LTRIM(RTRIM(@cDistritoCodigo)),'');
    DECLARE @cRef NVARCHAR(300)=NULLIF(LTRIM(RTRIM(@cReferencia)),N'');
    DECLARE @nCoincidencias INT,@bBusca BIT,@cMsgBusca NVARCHAR(300);
    DECLARE @nOtroPersonaId BIGINT=NULL;
    DECLARE @nUbicacionId BIGINT=NULL;
    DECLARE @bUbi BIT,@cMsgUbi NVARCHAR(300);

    SELECT @nPersonaId=NULL,@bPersonaExistia=0,@bResultado=0,
           @cMensaje=N'No se pudo completar la persona.';

    IF @cTipo NOT IN('DNI','RUC','CE','PASAPORTE','OTRO')
       OR @cDoc IS NULL OR @cNom IS NULL OR @cAP IS NULL OR @cDistrito IS NULL
    BEGIN
        SET @cMensaje=N'Complete correctamente los datos obligatorios de la persona.';
        GOTO __DESCO_Salida;
    END;

    IF @cTipo IN ('DNI','RUC') AND [org].[FN_Documento_EsValido](@cTipo,@cDoc)=0
    BEGIN
        SET @cMensaje=N'El DNI o RUC no supera la validación de integridad.';
        GOTO __DESCO_Salida;
    END;

    IF @cTipo='RUC' AND [org].[FN_Ruc_Naturaleza](@cDoc)<>'NATURAL'
    BEGIN
        SET @cMensaje=N'El RUC corresponde a una persona jurídica. Regístrelo como empresa, no como empleado/socio.';
        GOTO __DESCO_Salida;
    END;

    IF @dFechaNacimiento IS NOT NULL AND @dFechaNacimiento>CONVERT(DATE,SYSUTCDATETIME())
    BEGIN
        SET @cMensaje=N'Ingrese una fecha de nacimiento válida.';
        GOTO __DESCO_Salida;
    END;

    IF @cMail IS NOT NULL AND @cMail NOT LIKE '%_@_%._%'
    BEGIN
        SET @cMensaje=N'Ingrese un correo válido.';
        GOTO __DESCO_Salida;
    END;

    IF NOT EXISTS(SELECT 1 FROM [geo].[Distrito] WHERE distrito_codigo=@cDistrito AND estado=1)
    BEGIN
        SET @cMensaje=N'El distrito seleccionado no está disponible.';
        GOTO __DESCO_Salida;
    END;

    IF @nCentroPobladoId IS NOT NULL
       AND NOT EXISTS
       (
           SELECT 1 FROM [geo].[CentroPoblado]
           WHERE centro_poblado_id=@nCentroPobladoId
             AND distrito_codigo=@cDistrito
             AND estado=1
       )
    BEGIN
        SET @cMensaje=N'El centro poblado no corresponde al distrito seleccionado.';
        GOTO __DESCO_Salida;
    END;

    IF @nPersonaEsperadaId IS NOT NULL
    BEGIN
        IF NOT EXISTS(SELECT 1 FROM [org].[Persona] WHERE persona_id=@nPersonaEsperadaId)
        BEGIN
            SET @cMensaje=N'La persona seleccionada no está disponible.';
            GOTO __DESCO_Salida;
        END;

        EXEC [org].[PA_Persona_Sel_IdPorDocumentoInterno]
             @cTipoDocumento=@cTipo,
             @cNumeroDocumento=@cDoc,
             @nExcluirPersonaId=@nPersonaEsperadaId,
             @nPersonaId=@nOtroPersonaId OUTPUT,
             @nCoincidencias=@nCoincidencias OUTPUT,
             @bResultado=@bBusca OUTPUT,
             @cMensaje=@cMsgBusca OUTPUT;

        IF @bBusca=0 OR @nCoincidencias>0
        BEGIN
            SET @cMensaje=CASE WHEN @bBusca=0 THEN @cMsgBusca
                               ELSE N'El documento pertenece a otra persona registrada.' END;
            GOTO __DESCO_Salida;
        END;

        SET @nPersonaId=@nPersonaEsperadaId;
        SET @bPersonaExistia=1;
    END
    ELSE
    BEGIN
        EXEC [org].[PA_Persona_Sel_IdPorDocumentoInterno]
             @cTipoDocumento=@cTipo,
             @cNumeroDocumento=@cDoc,
             @nExcluirPersonaId=NULL,
             @nPersonaId=@nPersonaId OUTPUT,
             @nCoincidencias=@nCoincidencias OUTPUT,
             @bResultado=@bBusca OUTPUT,
             @cMensaje=@cMsgBusca OUTPUT;

        IF @bBusca=0
        BEGIN
            SET @cMensaje=@cMsgBusca;
            GOTO __DESCO_Salida;
        END;

        SET @bPersonaExistia=CASE WHEN @nPersonaId IS NULL THEN 0 ELSE 1 END;
    END;

    -- Un correo puede repetirse para la misma persona, no para otra identidad.
    IF @cMail IS NOT NULL AND EXISTS
    (
        SELECT 1 FROM [org].[Persona] WITH (UPDLOCK, HOLDLOCK)
        WHERE correo_clave_desco = LOWER(LTRIM(RTRIM(@cMail))) COLLATE Latin1_General_100_CI_AS
          AND (@nPersonaId IS NULL OR persona_id <> @nPersonaId)
    )
    BEGIN
        SET @cMensaje = N'El correo electrónico ya pertenece a otra persona registrada.';
        GOTO __DESCO_Salida;
    END;

    IF @nPersonaId IS NOT NULL
    BEGIN
        IF EXISTS
        (
            SELECT 1 FROM [org].[Persona]
            WHERE persona_id=@nPersonaId AND tipo_persona<>'NATURAL'
        )
        BEGIN
            SET @cMensaje=N'La identidad encontrada no es una persona natural.';
            GOTO __DESCO_Salida;
        END;

        SELECT @nUbicacionId=ubicacion_id
        FROM [org].[Persona]
        WHERE persona_id=@nPersonaId;

        IF @nUbicacionId IS NULL
        BEGIN
            EXEC [geo].[PA_Ubicacion_Ins_Interna]
                 @cDistritoCodigo=@cDistrito,
                 @nCentroPobladoId=@nCentroPobladoId,
                 @cReferencia=@cRef,
                 @nLatitud=NULL,@nLongitud=NULL,@nAltitudM=NULL,
                 @nUbicacionId=@nUbicacionId OUTPUT,
                 @bResultado=@bUbi OUTPUT,
                 @cMensaje=@cMsgUbi OUTPUT;
        END
        ELSE
        BEGIN
            EXEC [geo].[PA_Ubicacion_Upd_Interna]
                 @nUbicacionId=@nUbicacionId,
                 @cDistritoCodigo=@cDistrito,
                 @nCentroPobladoId=@nCentroPobladoId,
                 @cReferencia=@cRef,
                 @bResultado=@bUbi OUTPUT,
                 @cMensaje=@cMsgUbi OUTPUT;
        END;

        IF @bUbi=0
        BEGIN
            SET @cMensaje=@cMsgUbi;
            GOTO __DESCO_Salida;
        END;

        UPDATE [org].[Persona]
           SET tipo_documento=CASE WHEN @nPersonaEsperadaId IS NULL THEN tipo_documento ELSE @cTipo END,
               numero_documento=CASE WHEN @nPersonaEsperadaId IS NULL THEN numero_documento ELSE @cDoc END,
               tipo_persona='NATURAL',
               nombres=@cNom,
               apellido_paterno=@cAP,
               apellido_materno=@cAM,
               telefono=@cTel,
               correo=@cMail,
               fecha_nacimiento=@dFechaNacimiento,
               ubicacion_id=@nUbicacionId,
               estado=1
         WHERE persona_id=@nPersonaId;
    END
    ELSE
    BEGIN
        EXEC [geo].[PA_Ubicacion_Ins_Interna]
             @cDistritoCodigo=@cDistrito,
             @nCentroPobladoId=@nCentroPobladoId,
             @cReferencia=@cRef,
             @nLatitud=NULL,@nLongitud=NULL,@nAltitudM=NULL,
             @nUbicacionId=@nUbicacionId OUTPUT,
             @bResultado=@bUbi OUTPUT,
             @cMensaje=@cMsgUbi OUTPUT;

        IF @bUbi=0
        BEGIN
            SET @cMensaje=@cMsgUbi;
            GOTO __DESCO_Salida;
        END;

        INSERT [org].[Persona]
        (
            tipo_persona,tipo_documento,numero_documento,nombres,
            apellido_paterno,apellido_materno,telefono,correo,
            fecha_nacimiento,ubicacion_id,estado,fecha_creacion
        )
        VALUES
        (
            'NATURAL',@cTipo,@cDoc,@cNom,@cAP,@cAM,@cTel,@cMail,
            @dFechaNacimiento,@nUbicacionId,1,SYSUTCDATETIME()
        );

        SET @nPersonaId=CONVERT(BIGINT,SCOPE_IDENTITY());
        SET @bPersonaExistia=0;
    END;

    SET @bResultado=1;
    SET @cMensaje=CASE WHEN @bPersonaExistia=1
                       THEN N'Persona existente completada correctamente.'
                       ELSE N'Persona registrada correctamente.' END;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Persona_InsOUpd_DesdeFormulario',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
    IF @__DbError = 0 AND @bResultado = 1 AND XACT_STATE() = 1
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
    ELSE
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Persona_InsOUpd_DesdeFormulario',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
IF ISNULL(@bResultado,0) = 0 SELECT @nPersonaId=NULL;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'org.PA_Persona_InsOUpd_DesdeFormulario',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- org.PA_Persona_Sel_IdPorDocumentoInterno
CREATE OR ALTER PROCEDURE [org].[PA_Persona_Sel_IdPorDocumentoInterno]
(
    @cTipoDocumento VARCHAR(15),
    @cNumeroDocumento VARCHAR(30),
    @nExcluirPersonaId BIGINT = NULL,
    @nPersonaId BIGINT OUTPUT,
    @nCoincidencias INT OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;

    DECLARE @cTipo VARCHAR(15)=UPPER(NULLIF(LTRIM(RTRIM(@cTipoDocumento)),''));
    DECLARE @cDoc VARCHAR(30)=NULLIF(LTRIM(RTRIM(@cNumeroDocumento)),'');
    DECLARE @cDniEquivalente VARCHAR(8)=NULL;
    DECLARE @cRucEquivalente VARCHAR(11)=NULL;

    SELECT @nPersonaId=NULL,@nCoincidencias=0,@bResultado=0,
           @cMensaje=N'No se pudo resolver la identidad personal.';

    IF [org].[FN_Documento_EsValido](@cTipo,@cDoc)=0
       AND @cTipo IN ('DNI','RUC')
    BEGIN
        SET @cMensaje=N'El DNI o RUC no supera la validación de integridad.';
        GOTO __DESCO_Salida;
    END;

    IF @cTipo='DNI'
        SET @cRucEquivalente=[org].[FN_Ruc_DesdeDni](@cDoc);
    ELSE IF @cTipo='RUC' AND LEFT(@cDoc,2)='10'
        SET @cDniEquivalente=SUBSTRING(@cDoc,3,8);

    DECLARE @T TABLE(persona_id BIGINT PRIMARY KEY);

    INSERT @T(persona_id)
    SELECT P.persona_id
    FROM [org].[Persona] P WITH (UPDLOCK,HOLDLOCK)
    WHERE (@nExcluirPersonaId IS NULL OR P.persona_id<>@nExcluirPersonaId)
      AND
      (
          (P.tipo_documento=@cTipo AND P.numero_documento=@cDoc)
          OR
          (@cTipo='DNI' AND @cRucEquivalente IS NOT NULL
             AND P.tipo_documento='RUC' AND P.numero_documento=@cRucEquivalente)
          OR
          (@cTipo='RUC' AND @cDniEquivalente IS NOT NULL
             AND P.tipo_documento='DNI' AND P.numero_documento=@cDniEquivalente)
      );

    SELECT @nCoincidencias=COUNT(*),@nPersonaId=MIN(persona_id) FROM @T;

    IF @nCoincidencias>1
    BEGIN
        SET @nPersonaId=NULL;
        SET @cMensaje=N'Existen identidades duplicadas equivalentes (DNI/RUC10). Deben depurarse antes de continuar.';
        GOTO __DESCO_Salida;
    END;

    SET @bResultado=1;
    SET @cMensaje=N'Identidad resuelta correctamente.';

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Persona_Sel_IdPorDocumentoInterno',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Persona_Sel_IdPorDocumentoInterno',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'org.PA_Persona_Sel_IdPorDocumentoInterno',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- org.PA_Socio_Del_Registro
CREATE OR ALTER PROCEDURE [org].[PA_Socio_Del_Registro]
(
    @cJson NVARCHAR(MAX), @bResultado BIT OUTPUT, @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;
 SET XACT_ABORT ON;
    DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),
            @nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),
            @nSocio BIGINT,@dRetiro DATE,@cMotivo NVARCHAR(500),@cAnterior NVARCHAR(MAX),@cPosterior NVARCHAR(MAX),@cIdent NVARCHAR(200),@nAud BIGINT,@nTrans BIGINT;
    SELECT @bResultado=0,@cMensaje=N'No se pudo retirar el socio.';
    EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente] @cJson,'PRODUCTORES_RETIRAR','SOCIO_RETIRAR',@nUsuario OUTPUT,@nSesion OUTPUT,@nDisp OUTPUT,@nEmp OUTPUT,@nModulo OUTPUT,@gCorr OUTPUT,@gSol OUTPUT,@cIp OUTPUT,@cEnd OUTPUT,@nOp OUTPUT,@bRep OUTPUT,@cEstadoOp OUTPUT,@cIdRes OUTPUT,@cCodRes OUTPUT,@bIni OUTPUT,@cMsg OUTPUT;
    IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
 GOTO __DESCO_Salida;
 END;
    IF @bRep=1 BEGIN IF @cEstadoOp='COMPLETADA' BEGIN SET @bResultado=1;
 SET @cMensaje=N'La solicitud ya fue procesada correctamente.';
 END ELSE SET @cMensaje=N'La solicitud ya se encuentra en proceso.';
 GOTO __DESCO_Salida;
 END;
    SELECT @nSocio=socioId,@dRetiro=fechaRetiro,@cMotivo=NULLIF(LTRIM(RTRIM(motivo)),N'') FROM OPENJSON(@cJson,'$.socio') WITH (socioId BIGINT '$.socioId',fechaRetiro DATE '$.fechaRetiro',motivo NVARCHAR(500) '$.motivo');
    IF @nSocio IS NULL OR @dRetiro IS NULL OR @cMotivo IS NULL BEGIN SET @cMensaje=N'Complete la fecha y el motivo del retiro.';
 GOTO Fallar;
 END;
    IF NOT EXISTS(SELECT 1 FROM [org].[Socio] WHERE socio_id=@nSocio AND estado=1) BEGIN SET @cMensaje=N'El socio seleccionado no está disponible.';
 GOTO Fallar;
 END;
    IF EXISTS(SELECT 1 FROM [org].[Socio] WHERE socio_id=@nSocio AND @dRetiro<fecha_alta) BEGIN SET @cMensaje=N'La fecha de retiro no es válida.';
 GOTO Fallar;
 END;
    IF EXISTS
    (
      SELECT 1 FROM [org].[SocioAsociacion] SA
      INNER JOIN [comercial].[ParticipacionCampaniaSocio] PCS ON PCS.socio_asociacion_id=SA.socio_asociacion_id
      INNER JOIN [comercial].[CampaniaVenta] C ON C.campania_venta_id=PCS.campania_venta_id
      WHERE SA.socio_id=@nSocio AND PCS.estado=1 AND PCS.estado_participacion='ACTIVO' AND C.estado=1 AND C.estado_proceso IN('PLANIFICACION','ACTIVA')
    ) BEGIN SET @cMensaje=N'El socio tiene participación vigente en una campaña. Retírelo primero de la campaña correspondiente.';
 GOTO Fallar;
 END;
    BEGIN TRY
      BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;
      SELECT @cAnterior=(SELECT S.socio_id,S.fecha_alta,S.estado,(SELECT SA.socio_asociacion_id,SA.asociacion_id,SA.codigo_socio,SA.fecha_desde,SA.fecha_hasta,SA.situacion_membresia,SA.estado FROM [org].[SocioAsociacion] SA WHERE SA.socio_id=S.socio_id FOR JSON PATH) membresias FROM [org].[Socio] S WHERE S.socio_id=@nSocio FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
      UPDATE [org].[SocioAsociacion] SET fecha_hasta=CASE WHEN fecha_hasta IS NULL THEN @dRetiro ELSE fecha_hasta END,situacion_membresia='RETIRADO',estado=0 WHERE socio_id=@nSocio AND estado=1;
      UPDATE [org].[Socio] SET estado=0 WHERE socio_id=@nSocio AND estado=1;
      SELECT @cPosterior=(SELECT socio_id,fecha_alta,estado FROM [org].[Socio] WHERE socio_id=@nSocio FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
      SET @cIdent=CONVERT(NVARCHAR(200),@nSocio);
      EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio] @nUsuario,@nSesion,@nDisp,@nModulo,'RETIRAR','org','Socio',@cIdent,@cAnterior,@cPosterior,@cMotivo,'estado','1','0',@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
      /* Confirmar datos e idempotencia juntos. */
      EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar] @nOp,'COMPLETADA','org','Socio',@cIdent,'SOCIO_RETIRADO',@bFin OUTPUT,@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;

      SET @bResultado=1;
 SET @cMensaje=N'Socio retirado correctamente.';
 GOTO __DESCO_Salida;
    END TRY
    BEGIN CATCH
SET @bResultado = 0;
 IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
 SET @cMensaje=N'No se pudo retirar el socio. Intente nuevamente.';
 
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Socio_Del_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;
Fallar:
    IF @nOp IS NOT NULL AND @bResultado=0 EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar] @nOp,'FALLIDA',NULL,NULL,NULL,'NO_PROCESADO',@bFin OUTPUT,@cMsgFin OUTPUT;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Socio_Del_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

    IF @bResultado = 0 AND @nOp IS NOT NULL AND XACT_STATE() <> -1
    BEGIN
        IF ISNULL(@bRep,0) = 0
        BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                 @nOperacionIdempotenteId = @nOp, @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
            -- No sustituir el motivo funcional por un fallo de registro secundario.
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Socio_Del_Registro',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
        END CATCH;
        END
        ELSE
        BEGIN
            SELECT @cMensaje = COALESCE(mensaje_resultado,
                CASE WHEN estado_operacion = 'FALLIDA'
                     THEN N'La solicitud anterior no se completó. Corrija los datos y envíe una nueva solicitud.'
                     ELSE N'La solicitud todavía se está procesando. Consulte el resultado antes de repetirla.' END)
            FROM [auditoria].[OperacionIdempotente]
            WHERE operacion_idempotente_id = @nOp;
        END;
    END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Socio_Del_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'org.PA_Socio_Del_Registro',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* ===== org.PA_Socio_Ins_Registro ===== */
CREATE OR ALTER PROCEDURE [org].[PA_Socio_Ins_Registro]
(
    @cJson NVARCHAR(MAX),
    @nSocioId BIGINT OUTPUT,
    @nSocioAsociacionId BIGINT OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,
            @gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),
            @nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),
            @bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),
            @cTipo VARCHAR(15),@cDoc VARCHAR(30),@cNom NVARCHAR(100),@cAP NVARCHAR(80),
            @cAM NVARCHAR(80),@cTel VARCHAR(30),@cCorreo VARCHAR(180),@dNac DATE,
            @dAlta DATE,@nAsoc BIGINT,@cCodigo VARCHAR(30),@nCodigoConsecutivo BIGINT,@dDesde DATE,@cSituacion VARCHAR(20),
            @cDistrito CHAR(6),@nCentro BIGINT,@cReferencia NVARCHAR(300),
            @bPersonaExistia BIT,@bPersona BIT,@cMsgPersona NVARCHAR(300),
            @cPosterior NVARCHAR(MAX),@cIdent NVARCHAR(200),@nAud BIGINT,@nTrans BIGINT,
            @bPuedeEditarIdentidad BIT=0,@nPersonaExistente BIGINT=NULL,@nCoinPersona INT=0,
            @bBuscaPersona BIT=0,@cMsgBuscaPersona NVARCHAR(300),
            @cTipoActual VARCHAR(15),@cDocActual VARCHAR(30),@cNomActual NVARCHAR(100),
            @cAPActual NVARCHAR(80),@cAMActual NVARCHAR(80),@cTelActual VARCHAR(30),
            @cCorreoActual VARCHAR(180),@dNacActual DATE,@cDistritoActual CHAR(6),
            @cReferenciaActual NVARCHAR(300);

    SELECT @nSocioId=NULL,@nSocioAsociacionId=NULL,@bResultado=0,@cMensaje=N'No se pudo registrar el socio.';

    EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente]
         @cJson=@cJson,@cCodigoPermiso='PRODUCTORES_CREAR',@cAmbito='SOCIO_CREAR',
         @nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,
         @nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,
         @gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,
         @nOperacionIdempotenteId=@nOp OUTPUT,@bEsRepetida=@bRep OUTPUT,@cEstadoOperacion=@cEstadoOp OUTPUT,
         @cIdentificadorResultado=@cIdRes OUTPUT,@cCodigoResultado=@cCodRes OUTPUT,
         @bResultado=@bIni OUTPUT,@cMensaje=@cMsg OUTPUT;

    IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
 GOTO __DESCO_Salida;
 END;
    IF @bRep=1
    BEGIN
        IF @cEstadoOp='COMPLETADA'
        BEGIN
            SET @nSocioId=TRY_CONVERT(BIGINT,@cIdRes);
            SELECT TOP(1) @nSocioAsociacionId=socio_asociacion_id
            FROM [org].[SocioAsociacion]
            WHERE socio_id=@nSocioId
            ORDER BY CASE WHEN estado=1 AND fecha_hasta IS NULL THEN 0 ELSE 1 END,fecha_desde DESC,socio_asociacion_id DESC;
            SET @bResultado=1;
 SET @cMensaje=N'La solicitud ya fue procesada correctamente.';
        END
        ELSE SET @cMensaje=N'La solicitud ya se encuentra en proceso.';
        GOTO __DESCO_Salida;
    END;

    SELECT @cTipo=UPPER(NULLIF(LTRIM(RTRIM(tipoDocumento)),'')),@cDoc=NULLIF(LTRIM(RTRIM(numeroDocumento)),''),
           @cNom=NULLIF(LTRIM(RTRIM(nombres)),N''),@cAP=NULLIF(LTRIM(RTRIM(apellidoPaterno)),N''),
           @cAM=NULLIF(LTRIM(RTRIM(apellidoMaterno)),N''),@cTel=NULLIF(LTRIM(RTRIM(telefono)),''),
           @cCorreo=NULLIF(LTRIM(RTRIM(correo)),''),@dNac=fechaNacimiento
    FROM OPENJSON(@cJson,'$.persona')
    WITH(tipoDocumento VARCHAR(15) '$.tipoDocumento',numeroDocumento VARCHAR(30) '$.numeroDocumento',
         nombres NVARCHAR(100) '$.nombres',apellidoPaterno NVARCHAR(80) '$.apellidoPaterno',
         apellidoMaterno NVARCHAR(80) '$.apellidoMaterno',telefono VARCHAR(30) '$.telefono',
         correo VARCHAR(180) '$.correo',fechaNacimiento DATE '$.fechaNacimiento');

    SELECT @dAlta=fechaAlta,@nAsoc=asociacionId,
           @dDesde=fechaDesde,@cSituacion=UPPER(NULLIF(LTRIM(RTRIM(situacionMembresia)),''))
    FROM OPENJSON(@cJson,'$.socio')
    WITH(fechaAlta DATE '$.fechaAlta',asociacionId BIGINT '$.asociacionId',
         fechaDesde DATE '$.fechaDesde',situacionMembresia VARCHAR(20) '$.situacionMembresia');

    SELECT @cDistrito=COALESCE(NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.persona.ubicacion.distritoCodigo'))),''),NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.socio.ubicacion.distritoCodigo'))),''),NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.ubicacion.distritoCodigo'))),'')),
           @nCentro=TRY_CONVERT(BIGINT,COALESCE(JSON_VALUE(@cJson,'$.persona.ubicacion.centroPobladoId'),JSON_VALUE(@cJson,'$.socio.ubicacion.centroPobladoId'),JSON_VALUE(@cJson,'$.ubicacion.centroPobladoId'))),
           @cReferencia=COALESCE(NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.persona.ubicacion.referencia'))),N''),NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.socio.ubicacion.referencia'))),N''),NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.ubicacion.referencia'))),N''));

    IF @dDesde IS NULL SET @dDesde=@dAlta;
    IF @cSituacion IS NULL SET @cSituacion='ACTIVO';

    IF @cTipo NOT IN('DNI','RUC','CE','PASAPORTE','OTRO') OR @cDoc IS NULL OR @cNom IS NULL OR @cAP IS NULL OR @cDistrito IS NULL
       OR @dAlta IS NULL OR @nAsoc IS NULL OR @dDesde IS NULL
       OR @cSituacion NOT IN('ACTIVO','SUSPENDIDO') OR @dDesde<@dAlta
    BEGIN SET @cMensaje=N'Complete correctamente los datos obligatorios y de afiliación del socio.';
 GOTO Fallar;
 END;

    IF NOT EXISTS(SELECT 1 FROM [org].[Asociacion] A INNER JOIN [org].[Empresa] E ON E.empresa_id=A.asociacion_id WHERE A.asociacion_id=@nAsoc AND A.estado=1 AND E.estado=1)
    BEGIN SET @cMensaje=N'La asociación seleccionada no está disponible.';
 GOTO Fallar;
 END;

    SET @bPuedeEditarIdentidad = CASE WHEN EXISTS(
            SELECT 1
            FROM [seg].[UsuarioRol] UR
            INNER JOIN [seg].[Rol] R
                    ON R.rol_id=UR.rol_id
                   AND R.estado=1
            INNER JOIN [seg].[RolPermiso] RP
                    ON RP.rol_id=UR.rol_id
                   AND RP.estado=1
            INNER JOIN [seg].[Permiso] PM
                    ON PM.permiso_id=RP.permiso_id
                   AND PM.estado=1
            WHERE UR.usuario_id=@nUsuario
              AND UR.estado=1
              AND UR.fecha_desde<=SYSUTCDATETIME()
              AND (UR.fecha_hasta IS NULL OR UR.fecha_hasta>SYSUTCDATETIME())
              AND PM.codigo='VALIDACIONIDENTIDAD_EDITAR'
        ) THEN 1 ELSE 0 END;

    EXEC [org].[PA_Persona_Sel_IdPorDocumentoInterno]
         @cTipoDocumento=@cTipo,@cNumeroDocumento=@cDoc,@nExcluirPersonaId=NULL,
         @nPersonaId=@nPersonaExistente OUTPUT,@nCoincidencias=@nCoinPersona OUTPUT,
         @bResultado=@bBuscaPersona OUTPUT,@cMensaje=@cMsgBuscaPersona OUTPUT;

    IF @bBuscaPersona=0
    BEGIN SET @cMensaje=@cMsgBuscaPersona;
 GOTO Fallar;
 END;

    IF @nPersonaExistente IS NOT NULL
    BEGIN
        SELECT @cTipoActual=P.tipo_documento,@cDocActual=P.numero_documento,
               @cNomActual=P.nombres,@cAPActual=P.apellido_paterno,@cAMActual=P.apellido_materno,
               @cTelActual=P.telefono,@cCorreoActual=P.correo,@dNacActual=P.fecha_nacimiento,
               @cDistritoActual=U.distrito_codigo,@cReferenciaActual=U.referencia
        FROM [org].[Persona] P
        LEFT JOIN [geo].[Ubicacion] U ON U.ubicacion_id=P.ubicacion_id
        WHERE P.persona_id=@nPersonaExistente AND P.estado=1;

        IF @bPuedeEditarIdentidad=0 AND
        (
            ISNULL(@cNom,N'') COLLATE Latin1_General_100_CI_AI <> ISNULL(@cNomActual,N'') COLLATE Latin1_General_100_CI_AI OR
            ISNULL(@cAP,N'') COLLATE Latin1_General_100_CI_AI <> ISNULL(@cAPActual,N'') COLLATE Latin1_General_100_CI_AI OR
            ISNULL(@cAM,N'') COLLATE Latin1_General_100_CI_AI <> ISNULL(@cAMActual,N'') COLLATE Latin1_General_100_CI_AI OR
            ISNULL(@cTel,'') COLLATE Latin1_General_100_CI_AI <> ISNULL(@cTelActual,'') COLLATE Latin1_General_100_CI_AI OR
            ISNULL(@cCorreo,'') COLLATE Latin1_General_100_CI_AI <> ISNULL(@cCorreoActual,'') COLLATE Latin1_General_100_CI_AI OR
            ISNULL(@dNac,CONVERT(DATE,'19000101')) <> ISNULL(@dNacActual,CONVERT(DATE,'19000101')) OR
            ISNULL(@cDistrito,'') <> ISNULL(@cDistritoActual,'') OR
            ISNULL(@cReferencia,N'') COLLATE Latin1_General_100_CI_AI <> ISNULL(@cReferenciaActual,N'') COLLATE Latin1_General_100_CI_AI
        )
        BEGIN
            SET @cMensaje=N'No puede modificar los datos de la persona con su acceso actual.';
            GOTO Fallar;
        END;

        /* El documento de una persona existente nunca se modifica desde Productores / socios. */
        SET @cTipo=@cTipoActual;
        SET @cDoc=@cDocActual;
    END;

    BEGIN TRY
        BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

        EXEC [org].[PA_Persona_InsOUpd_DesdeFormulario]
             @cTipoDocumento=@cTipo,@cNumeroDocumento=@cDoc,@cNombres=@cNom,
             @cApellidoPaterno=@cAP,@cApellidoMaterno=@cAM,@cTelefono=@cTel,
             @cCorreo=@cCorreo,@dFechaNacimiento=@dNac,@cDistritoCodigo=@cDistrito,
             @nCentroPobladoId=@nCentro,@cReferencia=@cReferencia,@nPersonaEsperadaId=NULL,
             @nPersonaId=@nSocioId OUTPUT,@bPersonaExistia=@bPersonaExistia OUTPUT,
             @bResultado=@bPersona OUTPUT,@cMensaje=@cMsgPersona OUTPUT;

        IF @bPersona=0 BEGIN BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
 SET @cMensaje=@cMsgPersona;
 GOTO Fallar;
 END;

        IF EXISTS(SELECT 1 FROM [org].[Socio] WHERE socio_id=@nSocioId)
        BEGIN BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
 SET @cMensaje=N'La persona ya se encuentra registrada como socio.';
 GOTO Fallar;
 END;

        INSERT [org].[Socio](socio_id,fecha_alta,estado) VALUES(@nSocioId,@dAlta,1);

        /* Código de socio generado por el sistema. */
        WHILE 1=1
        BEGIN
            SET @nCodigoConsecutivo = NEXT VALUE FOR [org].[SQ_CodigoSocio];
            SET @cCodigo = 'SOC-' + RIGHT(REPLICATE('0',12) + CONVERT(VARCHAR(20),@nCodigoConsecutivo),12);
            IF NOT EXISTS
            (
                SELECT 1
                FROM [org].[SocioAsociacion]
                WHERE asociacion_id=@nAsoc AND codigo_socio=@cCodigo
            ) BREAK;
        END;

        INSERT [org].[SocioAsociacion](socio_id,asociacion_id,codigo_socio,fecha_desde,fecha_hasta,situacion_membresia,estado)
        VALUES(@nSocioId,@nAsoc,@cCodigo,@dDesde,NULL,@cSituacion,1);
        SET @nSocioAsociacionId=CONVERT(BIGINT,SCOPE_IDENTITY());

        SELECT @cPosterior=(SELECT @nSocioId socioId,@cTipo tipoDocumento,@cDoc numeroDocumento,
                                   @nAsoc asociacionId,@cCodigo codigoSocio,@cSituacion situacionMembresia
                            FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
        SET @cIdent=CONVERT(NVARCHAR(200),@nSocioId);
        EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio]
             @nUsuario,@nSesion,@nDisp,@nModulo,'CREAR','org','Socio',@cIdent,
             NULL,@cPosterior,NULL,'estado',NULL,'1',@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;

        /* Confirmar datos e idempotencia juntos. */

        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
             @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='COMPLETADA',
             @cEsquemaEntidad='org',@cNombreEntidad='Socio',@cIdentificadorResultado=@cIdent,
             @cCodigoResultado='SOCIO_CREADO',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;

        SET @bResultado=1;
        SET @cMensaje=CASE WHEN @bPersonaExistia=1
                           THEN N'Socio registrado reutilizando la persona existente.'
                           ELSE N'Socio registrado correctamente.' END;
        GOTO __DESCO_Salida;
    END TRY
    BEGIN CATCH
SET @bResultado = 0;

        IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
        SET @cMensaje=N'No se pudo registrar el socio. Intente nuevamente.';
    
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Socio_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;

Fallar:
    IF @nOp IS NOT NULL AND @bResultado=0
        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
             @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='FALLIDA',@cEsquemaEntidad=NULL,
             @cNombreEntidad=NULL,@cIdentificadorResultado=NULL,@cCodigoResultado='NO_PROCESADO',
             @bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Socio_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

    IF @bResultado = 0 AND @nOp IS NOT NULL AND XACT_STATE() <> -1
    BEGIN
        IF ISNULL(@bRep,0) = 0
        BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                 @nOperacionIdempotenteId = @nOp, @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
            -- No sustituir el motivo funcional por un fallo de registro secundario.
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Socio_Ins_Registro',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
        END CATCH;
        END
        ELSE
        BEGIN
            SELECT @cMensaje = COALESCE(mensaje_resultado,
                CASE WHEN estado_operacion = 'FALLIDA'
                     THEN N'La solicitud anterior no se completó. Corrija los datos y envíe una nueva solicitud.'
                     ELSE N'La solicitud todavía se está procesando. Consulte el resultado antes de repetirla.' END)
            FROM [auditoria].[OperacionIdempotente]
            WHERE operacion_idempotente_id = @nOp;
        END;
    END;
IF @bResultado = 0
    SELECT @nSocioId = NULL, @nSocioAsociacionId = NULL;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Socio_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'org.PA_Socio_Ins_Registro',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

