GO

/* ===== org.PA_Socio_Upd_Registro ===== */
CREATE OR ALTER PROCEDURE [org].[PA_Socio_Upd_Registro]
(
    @cJson NVARCHAR(MAX), @bResultado BIT OUTPUT, @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;
 SET XACT_ABORT ON;
    DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),
            @nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),
            @nSocio BIGINT,@cTipoDoc VARCHAR(15),@cNumDoc VARCHAR(30),@cNombres NVARCHAR(100),@cApePat NVARCHAR(80),@cApeMat NVARCHAR(80),@cTel VARCHAR(30),@cCorreo VARCHAR(180),@dNac DATE,
            @dAlta DATE,@nAsoc BIGINT,@cCodigo VARCHAR(30),@nCodigoConsecutivo BIGINT,@dDesde DATE,@cSituacion VARCHAR(20),@nSA BIGINT,@nAsocActual BIGINT,@dDesdeActual DATE,
            @cAnterior NVARCHAR(MAX),@cPosterior NVARCHAR(MAX),@cIdent NVARCHAR(200),@nAud BIGINT,@nTrans BIGINT,
            @cDistrito CHAR(6),@nCentroPoblado BIGINT,@cReferencia NVARCHAR(300),@nUbicacionActual BIGINT,
            @bPuedeEditarIdentidad BIT=0,@cTipoActual VARCHAR(15),@cDocActual VARCHAR(30),
            @cNomActual NVARCHAR(100),@cAPActual NVARCHAR(80),@cAMActual NVARCHAR(80),
            @cTelActual VARCHAR(30),@cCorreoActual VARCHAR(180),@dNacActual DATE,
            @cDistritoActual CHAR(6),@cReferenciaActual NVARCHAR(300);
    SELECT @bResultado=0,@cMensaje=N'No se pudo actualizar el socio.';
    EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente] @cJson,'PRODUCTORES_EDITAR','SOCIO_EDITAR',@nUsuario OUTPUT,@nSesion OUTPUT,@nDisp OUTPUT,@nEmp OUTPUT,@nModulo OUTPUT,@gCorr OUTPUT,@gSol OUTPUT,@cIp OUTPUT,@cEnd OUTPUT,@nOp OUTPUT,@bRep OUTPUT,@cEstadoOp OUTPUT,@cIdRes OUTPUT,@cCodRes OUTPUT,@bIni OUTPUT,@cMsg OUTPUT;
    IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
 GOTO __DESCO_Salida;
 END;
    IF @bRep=1 BEGIN IF @cEstadoOp='COMPLETADA' BEGIN SET @bResultado=1;
 SET @cMensaje=N'La solicitud ya fue procesada correctamente.';
 END ELSE SET @cMensaje=N'La solicitud ya se encuentra en proceso.';
 GOTO __DESCO_Salida;
 END;

    SELECT @nSocio=socioId,@cTipoDoc=UPPER(NULLIF(LTRIM(RTRIM(tipoDocumento)),'')),@cNumDoc=NULLIF(LTRIM(RTRIM(numeroDocumento)),''),@cNombres=NULLIF(LTRIM(RTRIM(nombres)),N''),@cApePat=NULLIF(LTRIM(RTRIM(apellidoPaterno)),N''),@cApeMat=NULLIF(LTRIM(RTRIM(apellidoMaterno)),N''),@cTel=NULLIF(LTRIM(RTRIM(telefono)),''),@cCorreo=NULLIF(LTRIM(RTRIM(correo)),''),@dNac=fechaNacimiento
    FROM OPENJSON(@cJson,'$.persona') WITH (socioId BIGINT '$.socioId',tipoDocumento VARCHAR(15) '$.tipoDocumento',numeroDocumento VARCHAR(30) '$.numeroDocumento',nombres NVARCHAR(100) '$.nombres',apellidoPaterno NVARCHAR(80) '$.apellidoPaterno',apellidoMaterno NVARCHAR(80) '$.apellidoMaterno',telefono VARCHAR(30) '$.telefono',correo VARCHAR(180) '$.correo',fechaNacimiento DATE '$.fechaNacimiento');
    IF @nSocio IS NULL SELECT @nSocio=socioId FROM OPENJSON(@cJson,'$.socio') WITH (socioId BIGINT '$.socioId');
    SELECT @nAsoc=asociacionId,@dDesde=fechaDesde,@cSituacion=UPPER(NULLIF(LTRIM(RTRIM(situacionMembresia)),''))
    FROM OPENJSON(@cJson,'$.socio') WITH (asociacionId BIGINT '$.asociacionId',fechaDesde DATE '$.fechaDesde',situacionMembresia VARCHAR(20) '$.situacionMembresia');

    SELECT
        @cDistrito=COALESCE(
            NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.persona.ubicacion.distritoCodigo'))),''),
            NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.socio.ubicacion.distritoCodigo'))),''),
            NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.ubicacion.distritoCodigo'))),'')
        ),
        @nCentroPoblado=TRY_CONVERT(BIGINT,COALESCE(
            JSON_VALUE(@cJson,'$.persona.ubicacion.centroPobladoId'),
            JSON_VALUE(@cJson,'$.socio.ubicacion.centroPobladoId'),
            JSON_VALUE(@cJson,'$.ubicacion.centroPobladoId')
        )),
        @cReferencia=COALESCE(
            NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.persona.ubicacion.referencia'))),N''),
            NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.socio.ubicacion.referencia'))),N''),
            NULLIF(LTRIM(RTRIM(JSON_VALUE(@cJson,'$.ubicacion.referencia'))),N'')
        );
    IF @nSocio IS NULL OR @cTipoDoc IS NULL OR @cTipoDoc NOT IN('DNI','RUC','CE','PASAPORTE','OTRO') OR @cNumDoc IS NULL OR @cNombres IS NULL OR @cApePat IS NULL OR @nAsoc IS NULL OR @dDesde IS NULL OR @cSituacion IS NULL OR @cSituacion NOT IN('ACTIVO','SUSPENDIDO') OR @cDistrito IS NULL BEGIN SET @cMensaje=N'Complete correctamente los datos del socio, incluido el distrito.';
 GOTO Fallar;
 END;
    IF @cTipoDoc IN('DNI','RUC') AND [org].[FN_Documento_EsValido](@cTipoDoc,@cNumDoc)=0 BEGIN SET @cMensaje=N'El DNI o RUC no supera la validación de integridad.';
 GOTO Fallar;
 END;
    IF @cTipoDoc='RUC' AND [org].[FN_Ruc_Naturaleza](@cNumDoc)<>'NATURAL' BEGIN SET @cMensaje=N'El RUC corresponde a una persona jurídica. No puede asignarse a un socio.';
 GOTO Fallar;
 END;
    IF NOT EXISTS(SELECT 1 FROM [geo].[Distrito] WHERE distrito_codigo=@cDistrito AND estado=1) BEGIN SET @cMensaje=N'El distrito seleccionado no está disponible.';
 GOTO Fallar;
 END;
    IF @nCentroPoblado IS NOT NULL AND NOT EXISTS(SELECT 1 FROM [geo].[CentroPoblado] WHERE centro_poblado_id=@nCentroPoblado AND distrito_codigo=@cDistrito AND estado=1) BEGIN SET @cMensaje=N'El centro poblado no corresponde al distrito seleccionado.';
 GOTO Fallar;
 END;
    SELECT @cTipoActual=P.tipo_documento,@cDocActual=P.numero_documento,
           @cNomActual=P.nombres,@cAPActual=P.apellido_paterno,@cAMActual=P.apellido_materno,
           @cTelActual=P.telefono,@cCorreoActual=P.correo,@dNacActual=P.fecha_nacimiento,
           @dAlta=S.fecha_alta,
           @nUbicacionActual=P.ubicacion_id,@cDistritoActual=U.distrito_codigo,@cReferenciaActual=U.referencia
    FROM [org].[Socio] S
    INNER JOIN [org].[Persona] P ON P.persona_id=S.socio_id
    LEFT JOIN [geo].[Ubicacion] U ON U.ubicacion_id=P.ubicacion_id
    WHERE S.socio_id=@nSocio AND S.estado=1 AND P.estado=1;

    IF @cTipoActual IS NULL BEGIN SET @cMensaje=N'El socio seleccionado no está disponible.';
 GOTO Fallar;
 END;

    IF @dNac>CONVERT(DATE,SYSUTCDATETIME()) OR @dDesde<@dAlta BEGIN SET @cMensaje=N'Las fechas ingresadas no son válidas.';
 GOTO Fallar;
 END;

    IF @cTipoDoc<>@cTipoActual OR @cNumDoc<>@cDocActual
    BEGIN SET @cMensaje=N'El documento de la persona no puede modificarse.';
 GOTO Fallar;
 END;

    SET @bPuedeEditarIdentidad = CASE WHEN EXISTS(
            SELECT 1
            FROM [seg].[UsuarioRol] UR
            INNER JOIN [seg].[Rol] R
                    ON R.rol_id=UR.rol_id
                   AND R.estado=1
            INNER JOIN [seg].[RolPermiso] RP
                    ON RP.rol_id=UR.rol_id
                   AND RP.estado=1
            INNER JOIN [seg].[Permiso] PM
                    ON PM.permiso_id=RP.permiso_id
                   AND PM.estado=1
            WHERE UR.usuario_id=@nUsuario
              AND UR.estado=1
              AND UR.fecha_desde<=SYSUTCDATETIME()
              AND (UR.fecha_hasta IS NULL OR UR.fecha_hasta>SYSUTCDATETIME())
              AND PM.codigo='VALIDACIONIDENTIDAD_EDITAR'
        ) THEN 1 ELSE 0 END;

    IF @bPuedeEditarIdentidad=0 AND
    (
        ISNULL(@cNombres,N'') COLLATE Latin1_General_100_CI_AI <> ISNULL(@cNomActual,N'') COLLATE Latin1_General_100_CI_AI OR
        ISNULL(@cApePat,N'') COLLATE Latin1_General_100_CI_AI <> ISNULL(@cAPActual,N'') COLLATE Latin1_General_100_CI_AI OR
        ISNULL(@cApeMat,N'') COLLATE Latin1_General_100_CI_AI <> ISNULL(@cAMActual,N'') COLLATE Latin1_General_100_CI_AI OR
        ISNULL(@cTel,'') COLLATE Latin1_General_100_CI_AI <> ISNULL(@cTelActual,'') COLLATE Latin1_General_100_CI_AI OR
        ISNULL(@cCorreo,'') COLLATE Latin1_General_100_CI_AI <> ISNULL(@cCorreoActual,'') COLLATE Latin1_General_100_CI_AI OR
        ISNULL(@dNac,CONVERT(DATE,'19000101')) <> ISNULL(@dNacActual,CONVERT(DATE,'19000101')) OR
        ISNULL(@cDistrito,'') <> ISNULL(@cDistritoActual,'') OR
        ISNULL(@cReferencia,N'') COLLATE Latin1_General_100_CI_AI <> ISNULL(@cReferenciaActual,N'') COLLATE Latin1_General_100_CI_AI
    )
    BEGIN SET @cMensaje=N'No puede modificar los datos de la persona con su acceso actual.';
 GOTO Fallar;
 END;
    DECLARE @nConflictoPersona BIGINT,@nCoinDocumento INT,@bBuscaDocumento BIT,@cMsgDocumento NVARCHAR(300);
    EXEC [org].[PA_Persona_Sel_IdPorDocumentoInterno] @cTipoDocumento=@cTipoDoc,@cNumeroDocumento=@cNumDoc,@nExcluirPersonaId=@nSocio,@nPersonaId=@nConflictoPersona OUTPUT,@nCoincidencias=@nCoinDocumento OUTPUT,@bResultado=@bBuscaDocumento OUTPUT,@cMensaje=@cMsgDocumento OUTPUT;
    IF @bBuscaDocumento=0 OR @nCoinDocumento>0 BEGIN SET @cMensaje=CASE WHEN @bBuscaDocumento=0 THEN @cMsgDocumento ELSE N'El documento pertenece a otra persona registrada.' END;
 GOTO Fallar;
 END;
    IF NOT EXISTS(SELECT 1 FROM [org].[Asociacion] A INNER JOIN [org].[Empresa] E ON E.empresa_id=A.asociacion_id WHERE A.asociacion_id=@nAsoc AND A.estado=1 AND E.estado=1) BEGIN SET @cMensaje=N'La asociación seleccionada no está disponible.';
 GOTO Fallar;
 END;
    SELECT TOP(1) @nSA=socio_asociacion_id,@nAsocActual=asociacion_id,@cCodigo=codigo_socio,@dDesdeActual=fecha_desde FROM [org].[SocioAsociacion] WHERE socio_id=@nSocio AND estado=1 AND fecha_hasta IS NULL ORDER BY fecha_desde DESC;
    IF @nSA IS NULL BEGIN SET @cMensaje=N'El socio no cuenta con una afiliación vigente.';
 GOTO Fallar;
 END;
    IF @nAsocActual<>@nAsoc AND @dDesde<=@dDesdeActual BEGIN SET @cMensaje=N'La nueva afiliación debe iniciar después de la afiliación actual.';
 GOTO Fallar;
 END;

    BEGIN TRY
      BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;
      SELECT @cAnterior=(SELECT S.socio_id,P.tipo_documento,P.numero_documento,P.nombres,P.apellido_paterno,P.apellido_materno,P.telefono,P.correo,P.fecha_nacimiento,S.fecha_alta,SA.asociacion_id,SA.codigo_socio,SA.fecha_desde,SA.situacion_membresia FROM [org].[Socio] S INNER JOIN [org].[Persona] P ON P.persona_id=S.socio_id LEFT JOIN [org].[SocioAsociacion] SA ON SA.socio_asociacion_id=@nSA WHERE S.socio_id=@nSocio FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
      IF @nUbicacionActual IS NULL
      BEGIN
        INSERT [geo].[Ubicacion](distrito_codigo,centro_poblado_id,referencia,estado) VALUES(@cDistrito,@nCentroPoblado,@cReferencia,1);
        SET @nUbicacionActual=CONVERT(BIGINT,SCOPE_IDENTITY());
      END
      ELSE
      BEGIN
        UPDATE [geo].[Ubicacion] SET distrito_codigo=@cDistrito,centro_poblado_id=@nCentroPoblado,referencia=@cReferencia,estado=1 WHERE ubicacion_id=@nUbicacionActual;
      END;
      UPDATE [org].[Persona] SET tipo_persona='NATURAL',tipo_documento=@cTipoDoc,numero_documento=@cNumDoc,nombres=@cNombres,apellido_paterno=@cApePat,apellido_materno=@cApeMat,telefono=@cTel,correo=@cCorreo,fecha_nacimiento=@dNac,ubicacion_id=@nUbicacionActual WHERE persona_id=@nSocio AND estado=1;
      IF @nAsocActual=@nAsoc
        UPDATE [org].[SocioAsociacion] SET fecha_desde=@dDesde,situacion_membresia=@cSituacion WHERE socio_asociacion_id=@nSA AND estado=1;
      ELSE
      BEGIN
        UPDATE [org].[SocioAsociacion] SET fecha_hasta=DATEADD(DAY,-1,@dDesde),situacion_membresia='RETIRADO',estado=0 WHERE socio_asociacion_id=@nSA;

        /* Una nueva afiliación recibe un nuevo código de socio. */
        WHILE 1=1
        BEGIN
            SET @nCodigoConsecutivo = NEXT VALUE FOR [org].[SQ_CodigoSocio];
            SET @cCodigo = 'SOC-' + RIGHT(REPLICATE('0',12) + CONVERT(VARCHAR(20),@nCodigoConsecutivo),12);
            IF NOT EXISTS
            (
                SELECT 1
                FROM [org].[SocioAsociacion]
                WHERE asociacion_id=@nAsoc AND codigo_socio=@cCodigo
            ) BREAK;
        END;

        INSERT [org].[SocioAsociacion](socio_id,asociacion_id,codigo_socio,fecha_desde,fecha_hasta,situacion_membresia) VALUES(@nSocio,@nAsoc,@cCodigo,@dDesde,NULL,@cSituacion);
      END;
      SELECT @cPosterior=(SELECT S.socio_id,P.tipo_documento,P.numero_documento,P.nombres,P.apellido_paterno,P.apellido_materno,P.telefono,P.correo,P.fecha_nacimiento,S.fecha_alta,SA.asociacion_id,SA.codigo_socio,SA.fecha_desde,SA.situacion_membresia FROM [org].[Socio] S INNER JOIN [org].[Persona] P ON P.persona_id=S.socio_id OUTER APPLY(SELECT TOP(1) X.* FROM [org].[SocioAsociacion] X WHERE X.socio_id=S.socio_id AND X.estado=1 AND X.fecha_hasta IS NULL ORDER BY X.fecha_desde DESC) SA WHERE S.socio_id=@nSocio FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
      SET @cIdent=CONVERT(NVARCHAR(200),@nSocio);
      EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio] @nUsuario,@nSesion,@nDisp,@nModulo,'EDITAR','org','Socio',@cIdent,@cAnterior,@cPosterior,NULL,NULL,NULL,NULL,@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
      /* Confirmar datos e idempotencia juntos. */
      EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar] @nOp,'COMPLETADA','org','Socio',@cIdent,'SOCIO_ACTUALIZADO',@bFin OUTPUT,@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;

      SET @bResultado=1;
 SET @cMensaje=N'Socio actualizado correctamente.';
 GOTO __DESCO_Salida;
    END TRY
    BEGIN CATCH
SET @bResultado = 0;
 IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
 SET @cMensaje=N'No se pudo actualizar el socio. Intente nuevamente.';
 
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Socio_Upd_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;
Fallar:
    IF @nOp IS NOT NULL AND @bResultado=0 EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar] @nOp,'FALLIDA',NULL,NULL,NULL,'NO_PROCESADO',@bFin OUTPUT,@cMsgFin OUTPUT;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Socio_Upd_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

    IF @bResultado = 0 AND @nOp IS NOT NULL AND XACT_STATE() <> -1
    BEGIN
        IF ISNULL(@bRep,0) = 0
        BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                 @nOperacionIdempotenteId = @nOp, @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
            -- No sustituir el motivo funcional por un fallo de registro secundario.
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Socio_Upd_Registro',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
        END CATCH;
        END
        ELSE
        BEGIN
            SELECT @cMensaje = COALESCE(mensaje_resultado,
                CASE WHEN estado_operacion = 'FALLIDA'
                     THEN N'La solicitud anterior no se completó. Corrija los datos y envíe una nueva solicitud.'
                     ELSE N'La solicitud todavía se está procesando. Consulte el resultado antes de repetirla.' END)
            FROM [auditoria].[OperacionIdempotente]
            WHERE operacion_idempotente_id = @nOp;
        END;
    END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'org.PA_Socio_Upd_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'org.PA_Socio_Upd_Registro',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* --------------------------------------------------------------------------
   C. CREACION/LISTADO UOT y administradores futuros.
   -------------------------------------------------------------------------- */
CREATE OR ALTER PROCEDURE org.PA_UOT_Ins_Registro
    @nUsuarioId BIGINT,@nUotPadreId BIGINT,@nUbicacionId BIGINT=NULL,@cCodigo VARCHAR(40),@cNombre NVARCHAR(160),@cDescripcion NVARCHAR(400)=NULL,
    @nUotId BIGINT OUTPUT,@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    SELECT @nUotId=NULL,@bResultado=0,@cMensaje=N'No se pudo registrar la UOT.';
    SET @cCodigo=UPPER(NULLIF(LTRIM(RTRIM(@cCodigo)),'')); SET @cNombre=NULLIF(LTRIM(RTRIM(@cNombre)),N'');
    IF @cCodigo IS NULL OR @cNombre IS NULL BEGIN SET @cMensaje=N'Complete correctamente los datos de la UOT.'; RETURN 1; END;
    IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotPadreId,'UOT_CREAR')=0 BEGIN SET @cMensaje=N'No tiene permiso para crear una UOT.'; RETURN 1; END;
    IF NOT EXISTS(SELECT 1 FROM org.UOT WHERE uot_id=@nUotPadreId AND estado=1) BEGIN SET @cMensaje=N'La UOT superior no esta disponible.'; RETURN 1; END;
    IF @nUbicacionId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM geo.Ubicacion WHERE ubicacion_id=@nUbicacionId) BEGIN SET @cMensaje=N'La ubicacion no es valida.'; RETURN 1; END;
    IF EXISTS(SELECT 1 FROM org.UOT WHERE codigo=@cCodigo) BEGIN SET @cMensaje=N'El codigo de UOT ya esta registrado.'; RETURN 1; END;
    BEGIN TRY
      BEGIN TRAN;
      INSERT org.UOT(uot_padre_id,ubicacion_id,codigo,nombre,descripcion,es_raiz,fecha_inicio,estado)
      VALUES(@nUotPadreId,@nUbicacionId,@cCodigo,@cNombre,@cDescripcion,0,CONVERT(date,SYSUTCDATETIME()),1);
      SET @nUotId=SCOPE_IDENTITY();
      DECLARE @RolAdmin BIGINT=(SELECT TOP(1) rol_id FROM seg.Rol WHERE codigo='ADMINISTRADOR' AND estado=1);
      DECLARE @Admins TABLE(usuario_id BIGINT PRIMARY KEY);
      INSERT @Admins SELECT DISTINCT UR.usuario_id FROM seg.UsuarioRol UR WHERE UR.rol_id=@RolAdmin AND UR.estado=1 AND (UR.fecha_hasta IS NULL OR UR.fecha_hasta>SYSUTCDATETIME());
      INSERT seg.UsuarioUOT(usuario_id,uot_id,es_predeterminada,fecha_desde,estado,asignado_por_usuario_id)
      SELECT A.usuario_id,@nUotId,0,SYSUTCDATETIME(),1,@nUsuarioId FROM @Admins A
      WHERE NOT EXISTS(SELECT 1 FROM seg.UsuarioUOT X WHERE X.usuario_id=A.usuario_id AND X.uot_id=@nUotId AND X.estado=1 AND X.fecha_hasta IS NULL);
      INSERT seg.UsuarioUOTRol(usuario_uot_id,rol_id,fecha_desde,estado,asignado_por_usuario_id)
      SELECT UU.usuario_uot_id,@RolAdmin,SYSUTCDATETIME(),1,@nUsuarioId
      FROM seg.UsuarioUOT UU JOIN @Admins A ON A.usuario_id=UU.usuario_id
      WHERE UU.uot_id=@nUotId AND UU.estado=1 AND UU.fecha_hasta IS NULL
        AND NOT EXISTS(SELECT 1 FROM seg.UsuarioUOTRol X WHERE X.usuario_uot_id=UU.usuario_uot_id AND X.rol_id=@RolAdmin AND X.estado=1 AND X.fecha_hasta IS NULL);
      COMMIT; SET @bResultado=1; SET @cMensaje=N'UOT registrada.'; RETURN 0;
    END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SET @nUotId=NULL; SET @cMensaje=N'No se pudo registrar la UOT.'; RETURN 1; END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* --------------------------------------------------------------------------
   G. IMPACTO, TRANSFERENCIA Y BAJA UOT incluyendo suministros.
   -------------------------------------------------------------------------- */
CREATE OR ALTER PROCEDURE org.PA_UOT_Sel_ImpactoBaja
 @nUsuarioId BIGINT,@nUotId BIGINT,
 @nUotIncluidas INT OUTPUT,@nUsuariosActivos INT OUTPUT,@nUsuariosExclusivos INT OUTPUT,@nEmpleadosActivos INT OUTPUT,
 @nAreasActivas INT OUTPUT,@nOrganizacionesActivas INT OUTPUT,@nPrediosActivos INT OUTPUT,@nAlmacenesActivos INT OUTPUT,
 @nProductosConStock INT OUTPUT,@nStockReservado INT OUTPUT,@nSuministrosConStock INT OUTPUT,@nSuministrosReservados INT OUTPUT,
 @nBienesActivos INT OUTPUT,@nVentasAbiertas INT OUTPUT,@nCampaniasAbiertas INT OUTPUT,@nOperativosAbiertos INT OUTPUT,@nSalidasAbiertas INT OUTPUT,@nRecursosAbiertos INT OUTPUT,
 @bPuedeDeshabilitar BIT OUTPUT,@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,@cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON;
 SELECT @nUotIncluidas=0,@nUsuariosActivos=0,@nUsuariosExclusivos=0,@nEmpleadosActivos=0,@nAreasActivas=0,@nOrganizacionesActivas=0,@nPrediosActivos=0,@nAlmacenesActivos=0,
        @nProductosConStock=0,@nStockReservado=0,@nSuministrosConStock=0,@nSuministrosReservados=0,@nBienesActivos=0,@nVentasAbiertas=0,@nCampaniasAbiertas=0,@nOperativosAbiertos=0,@nSalidasAbiertas=0,@nRecursosAbiertos=0,
        @bPuedeDeshabilitar=0,@bResultado=0,@cMensaje=N'No se pudo revisar la UOT.',@cCodigoRespuesta='UOT_IMPACTO_NO_DISPONIBLE',@nHttpRespuesta=400;
 IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotId,'UOT_RETIRAR')=0 BEGIN SET @cMensaje=N'No tiene permiso para retirar esta UOT.'; RETURN 1; END;
 IF NOT EXISTS(SELECT 1 FROM org.UOT WHERE uot_id=@nUotId AND estado=1) BEGIN SET @cMensaje=N'La UOT no esta disponible.'; RETURN 1; END;
 DECLARE @Rama TABLE(uot_id BIGINT PRIMARY KEY);
 ;WITH R AS(SELECT uot_id FROM org.UOT WHERE uot_id=@nUotId AND estado=1 UNION ALL SELECT U.uot_id FROM org.UOT U JOIN R ON U.uot_padre_id=R.uot_id WHERE U.estado=1)
 INSERT @Rama SELECT uot_id FROM R OPTION(MAXRECURSION 100);
 SELECT @nUotIncluidas=COUNT(*) FROM @Rama;
 SELECT @nUsuariosActivos=COUNT(DISTINCT UU.usuario_id) FROM seg.UsuarioUOT UU JOIN @Rama R ON R.uot_id=UU.uot_id WHERE UU.estado=1 AND UU.fecha_hasta IS NULL;
 SELECT @nUsuariosExclusivos=COUNT(*) FROM(SELECT UU.usuario_id FROM seg.UsuarioUOT UU JOIN @Rama R ON R.uot_id=UU.uot_id WHERE UU.estado=1 AND UU.fecha_hasta IS NULL GROUP BY UU.usuario_id HAVING NOT EXISTS(SELECT 1 FROM seg.UsuarioUOT X JOIN org.UOT UX ON UX.uot_id=X.uot_id AND UX.estado=1 WHERE X.usuario_id=UU.usuario_id AND X.estado=1 AND X.fecha_hasta IS NULL AND NOT EXISTS(SELECT 1 FROM @Rama RR WHERE RR.uot_id=X.uot_id))) Q;
 SELECT @nEmpleadosActivos=COUNT(DISTINCT EU.empleado_id) FROM org.EmpleadoUOT EU JOIN @Rama R ON R.uot_id=EU.uot_id WHERE EU.estado=1 AND EU.fecha_hasta IS NULL;
 SELECT @nAreasActivas=COUNT(*) FROM org.Area A JOIN @Rama R ON R.uot_id=A.uot_id WHERE A.estado=1;
 SELECT @nOrganizacionesActivas=COUNT(*) FROM org.ConvenioUOTOrganizacion C JOIN @Rama R ON R.uot_id=C.uot_id WHERE C.estado=1 AND C.fecha_fin IS NULL;
 SELECT @nPrediosActivos=COUNT(*) FROM prod.Predio P JOIN @Rama R ON R.uot_id=P.uot_id WHERE P.estado=1;
 SELECT @nAlmacenesActivos=COUNT(*) FROM logistica.Almacen A JOIN @Rama R ON R.uot_id=A.uot_propietaria_id WHERE A.estado=1;
 SELECT @nProductosConStock=COUNT(*) FROM logistica.AlmacenProductoStock S JOIN logistica.Almacen A ON A.almacen_id=S.almacen_id JOIN @Rama R ON R.uot_id=A.uot_propietaria_id WHERE S.stock_actual<>0;
 SELECT @nStockReservado=COUNT(*) FROM logistica.AlmacenProductoStock S JOIN logistica.Almacen A ON A.almacen_id=S.almacen_id JOIN @Rama R ON R.uot_id=A.uot_propietaria_id WHERE S.stock_reservado<>0;
 SELECT @nSuministrosConStock=COUNT(*) FROM logistica.Suministro S JOIN @Rama R ON R.uot_id=S.uot_id JOIN logistica.SuministroSaldo K ON K.suministro_id=S.suministro_id WHERE S.estado=1 AND K.stock_actual<>0;
 SELECT @nSuministrosReservados=COUNT(*) FROM logistica.Suministro S JOIN @Rama R ON R.uot_id=S.uot_id JOIN logistica.SuministroSaldo K ON K.suministro_id=S.suministro_id WHERE S.estado=1 AND K.stock_reservado<>0;
 SELECT @nBienesActivos=COUNT(*) FROM logistica.BienInventario B JOIN @Rama R ON R.uot_id=B.uot_id WHERE B.estado=1 AND B.estado_bien<>'BAJA';
 SELECT @nVentasAbiertas=COUNT(*) FROM comercial.Venta V JOIN @Rama R ON R.uot_id=V.uot_id WHERE V.estado=1 AND V.estado_venta NOT IN('ENTREGADA','ANULADA');
 SELECT @nCampaniasAbiertas=COUNT(*) FROM comercial.CampaniaVenta C JOIN @Rama R ON R.uot_id=C.uot_id WHERE C.estado=1 AND C.estado_proceso NOT IN('CERRADA','CANCELADA');
 SELECT @nOperativosAbiertos=COUNT(*) FROM comercial.OperativoVenta O JOIN comercial.CampaniaVenta C ON C.campania_venta_id=O.campania_venta_id JOIN @Rama R ON R.uot_id=C.uot_id WHERE O.estado=1 AND O.estado_proceso NOT IN('CERRADO','CANCELADO');
 SELECT @nSalidasAbiertas=COUNT(*) FROM campo.SalidaCampo S JOIN @Rama R ON R.uot_id=S.uot_id WHERE S.estado=1 AND S.estado_proceso NOT IN('FINALIZADA','CANCELADA');
 SELECT @nRecursosAbiertos=COUNT(*) FROM logistica.RecursoProgramado RP WHERE RP.estado=1 AND RP.estado_proceso NOT IN('COMPLETADO','CANCELADO') AND(EXISTS(SELECT 1 FROM comercial.CampaniaVenta C JOIN @Rama R ON R.uot_id=C.uot_id WHERE C.campania_venta_id=RP.campania_venta_id) OR EXISTS(SELECT 1 FROM comercial.OperativoVenta O JOIN comercial.CampaniaVenta C ON C.campania_venta_id=O.campania_venta_id JOIN @Rama R ON R.uot_id=C.uot_id WHERE O.operativo_venta_id=RP.operativo_venta_id) OR EXISTS(SELECT 1 FROM campo.SalidaCampo S JOIN @Rama R ON R.uot_id=S.uot_id WHERE S.salida_campo_id=RP.salida_campo_id));
 SET @bPuedeDeshabilitar=CASE WHEN @nProductosConStock=0 AND @nStockReservado=0 AND @nSuministrosConStock=0 AND @nSuministrosReservados=0 AND @nBienesActivos=0 AND @nVentasAbiertas=0 AND @nCampaniasAbiertas=0 AND @nOperativosAbiertos=0 AND @nSalidasAbiertas=0 AND @nRecursosAbiertos=0 THEN 1 ELSE 0 END;
 SELECT @bResultado=1,@cMensaje=CASE WHEN @bPuedeDeshabilitar=1 THEN N'La UOT puede retirarse.' ELSE N'La UOT tiene recursos u operaciones pendientes.' END,@cCodigoRespuesta='UOT_IMPACTO_CONSULTADO',@nHttpRespuesta=200; RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE org.PA_UOT_Sel_Listado
    @nUsuarioId BIGINT,@nUotId BIGINT=NULL,@bIncluirInactivas BIT=0,
    @bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SELECT @bResultado=0,@cMensaje=N'No se pudo consultar las UOT.';
 DECLARE @EsAdmin BIT=CASE WHEN EXISTS(SELECT 1 FROM seg.UsuarioRol UR JOIN seg.Rol R ON R.rol_id=UR.rol_id AND R.codigo='ADMINISTRADOR' AND R.estado=1 WHERE UR.usuario_id=@nUsuarioId AND UR.estado=1 AND (UR.fecha_hasta IS NULL OR UR.fecha_hasta>SYSUTCDATETIME())) THEN 1 ELSE 0 END;
 IF @bIncluirInactivas=1 AND @EsAdmin=0 BEGIN SET @cMensaje=N'No tiene permiso para consultar UOT inactivas.'; RETURN 1; END;
 SELECT U.uot_id,U.uot_padre_id,U.codigo,U.nombre,U.descripcion,U.ubicacion_id,U.es_raiz,U.fecha_inicio,U.fecha_fin,U.estado,
        CONVERT(BIT,CASE WHEN A.usuario_uot_id IS NULL THEN 0 ELSE 1 END) asignada,ISNULL(A.es_predeterminada,0) es_predeterminada
 FROM org.UOT U
 LEFT JOIN seg.UsuarioUOT A ON A.uot_id=U.uot_id AND A.usuario_id=@nUsuarioId AND A.estado=1 AND A.fecha_hasta IS NULL
 WHERE (@bIncluirInactivas=1 OR U.estado=1) AND (@nUotId IS NULL OR U.uot_id=@nUotId)
   AND (@EsAdmin=1 OR A.usuario_uot_id IS NOT NULL)
 ORDER BY U.es_raiz DESC,U.nombre;
 SET @bResultado=1; SET @cMensaje=N'UOT consultadas.'; RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE org.PA_UOT_Upd_Deshabilitar
 @nUsuarioId BIGINT,@nUotId BIGINT,@cMotivo NVARCHAR(500),
 @bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,@cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,@nHttpRespuesta SMALLINT=NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON; SELECT @bResultado=0,@cMensaje=N'No se pudo retirar la UOT.',@cCodigoRespuesta='UOT_NO_RETIRADA',@nHttpRespuesta=409;
 SET @cMotivo=NULLIF(LTRIM(RTRIM(@cMotivo)),N''); IF @cMotivo IS NULL BEGIN SET @cMensaje=N'Indique el motivo de la baja.'; RETURN 1; END;
 IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotId,'UOT_RETIRAR')=0 BEGIN SET @cMensaje=N'No tiene permiso para retirar esta UOT.'; RETURN 1; END;
 IF EXISTS(SELECT 1 FROM org.UOT WHERE uot_id=@nUotId AND es_raiz=1) BEGIN SET @cMensaje=N'La UOT raiz no puede retirarse.'; RETURN 1; END;
 DECLARE @Rama TABLE(uot_id BIGINT PRIMARY KEY); ;WITH R AS(SELECT uot_id FROM org.UOT WHERE uot_id=@nUotId AND estado=1 UNION ALL SELECT U.uot_id FROM org.UOT U JOIN R ON U.uot_padre_id=R.uot_id WHERE U.estado=1) INSERT @Rama SELECT uot_id FROM R OPTION(MAXRECURSION 100);
 IF NOT EXISTS(SELECT 1 FROM @Rama) BEGIN SET @cMensaje=N'La UOT ya no esta disponible.'; RETURN 1; END;
 IF EXISTS(SELECT 1 FROM logistica.AlmacenProductoStock S JOIN logistica.Almacen A ON A.almacen_id=S.almacen_id JOIN @Rama R ON R.uot_id=A.uot_propietaria_id WHERE S.stock_actual<>0 OR S.stock_reservado<>0) BEGIN SET @cMensaje=N'Transfiera o regularice el stock antes de retirar la UOT.'; RETURN 1; END;
 IF EXISTS(SELECT 1 FROM logistica.Suministro S JOIN @Rama R ON R.uot_id=S.uot_id JOIN logistica.SuministroSaldo K ON K.suministro_id=S.suministro_id WHERE S.estado=1 AND (K.stock_actual<>0 OR K.stock_reservado<>0)) BEGIN SET @cMensaje=N'Transfiera o regularice los suministros antes de retirar la UOT.'; RETURN 1; END;
 IF EXISTS(SELECT 1 FROM logistica.BienInventario B JOIN @Rama R ON R.uot_id=B.uot_id WHERE B.estado=1 AND B.estado_bien<>'BAJA') BEGIN SET @cMensaje=N'Transfiera o retire los bienes antes de retirar la UOT.'; RETURN 1; END;
 IF EXISTS(SELECT 1 FROM comercial.Venta V JOIN @Rama R ON R.uot_id=V.uot_id WHERE V.estado=1 AND V.estado_venta NOT IN('ENTREGADA','ANULADA')) BEGIN SET @cMensaje=N'Cierre o anule las ventas pendientes.'; RETURN 1; END;
 IF EXISTS(SELECT 1 FROM comercial.CampaniaVenta C JOIN @Rama R ON R.uot_id=C.uot_id WHERE C.estado=1 AND C.estado_proceso NOT IN('CERRADA','CANCELADA')) BEGIN SET @cMensaje=N'Cierre o cancele las campanias pendientes.'; RETURN 1; END;
 IF EXISTS(SELECT 1 FROM campo.SalidaCampo S JOIN @Rama R ON R.uot_id=S.uot_id WHERE S.estado=1 AND S.estado_proceso NOT IN('FINALIZADA','CANCELADA')) BEGIN SET @cMensaje=N'Finalice o cancele las salidas pendientes.'; RETURN 1; END;
 IF EXISTS(SELECT 1 FROM logistica.RecursoProgramado RP WHERE RP.estado=1 AND RP.estado_proceso NOT IN('COMPLETADO','CANCELADO') AND(EXISTS(SELECT 1 FROM comercial.CampaniaVenta C JOIN @Rama R ON R.uot_id=C.uot_id WHERE C.campania_venta_id=RP.campania_venta_id) OR EXISTS(SELECT 1 FROM comercial.OperativoVenta O JOIN comercial.CampaniaVenta C ON C.campania_venta_id=O.campania_venta_id JOIN @Rama R ON R.uot_id=C.uot_id WHERE O.operativo_venta_id=RP.operativo_venta_id) OR EXISTS(SELECT 1 FROM campo.SalidaCampo S JOIN @Rama R ON R.uot_id=S.uot_id WHERE S.salida_campo_id=RP.salida_campo_id))) BEGIN SET @cMensaje=N'Cierre los recursos programados pendientes.'; RETURN 1; END;
 BEGIN TRY BEGIN TRAN;
  DECLARE @Ahora DATETIME2(0)=SYSUTCDATETIME(),@Hoy DATE=CONVERT(DATE,SYSUTCDATETIME());
  UPDATE PP SET estado=0,fecha_hasta=COALESCE(PP.fecha_hasta,@Ahora) FROM logistica.ProductoPrecio PP JOIN @Rama R ON R.uot_id=PP.uot_id WHERE PP.estado=1 AND PP.fecha_hasta IS NULL;
  UPDATE C SET estado=0,fecha_fin=COALESCE(C.fecha_fin,@Hoy) FROM org.ConvenioUOTOrganizacion C JOIN @Rama R ON R.uot_id=C.uot_id WHERE C.estado=1;
  UPDATE A SET estado=0 FROM org.Asociacion A JOIN @Rama R ON R.uot_id=A.uot_id WHERE A.estado=1;
  UPDATE EA SET estado=0,fecha_hasta=COALESCE(EA.fecha_hasta,@Hoy) FROM org.EmpleadoArea EA JOIN org.Area A ON A.area_id=EA.area_id JOIN @Rama R ON R.uot_id=A.uot_id WHERE EA.estado=1 AND EA.fecha_hasta IS NULL;
  UPDATE A SET estado=0 FROM org.Area A JOIN @Rama R ON R.uot_id=A.uot_id WHERE A.estado=1;
  UPDATE S SET estado=0 FROM logistica.Suministro S JOIN @Rama R ON R.uot_id=S.uot_id WHERE S.estado=1;
  UPDATE PC SET estado=0 FROM prod.ParcelaCultivo PC JOIN prod.Parcela P ON P.parcela_id=PC.parcela_id JOIN prod.Predio PR ON PR.predio_id=P.predio_id JOIN @Rama R ON R.uot_id=PR.uot_id WHERE PC.estado=1;
  UPDATE P SET estado=0 FROM prod.Parcela P JOIN prod.Predio PR ON PR.predio_id=P.predio_id JOIN @Rama R ON R.uot_id=PR.uot_id WHERE P.estado=1;
  UPDATE PR SET estado=0 FROM prod.Predio PR JOIN @Rama R ON R.uot_id=PR.uot_id WHERE PR.estado=1;
  UPDATE AU SET estado=0,fecha_hasta=COALESCE(AU.fecha_hasta,@Ahora) FROM logistica.AlmacenUOT AU JOIN @Rama R ON R.uot_id=AU.uot_id WHERE AU.estado=1 AND AU.fecha_hasta IS NULL;
  UPDATE A SET estado=0 FROM logistica.Almacen A JOIN @Rama R ON R.uot_id=A.uot_propietaria_id WHERE A.estado=1;
  DECLARE @Empleados TABLE(empleado_id BIGINT PRIMARY KEY); INSERT @Empleados SELECT DISTINCT EU.empleado_id FROM org.EmpleadoUOT EU JOIN @Rama R ON R.uot_id=EU.uot_id WHERE EU.estado=1 AND EU.fecha_hasta IS NULL;
  UPDATE EU SET estado=0,fecha_hasta=COALESCE(EU.fecha_hasta,@Hoy),fecha_cese=COALESCE(EU.fecha_cese,@Hoy),es_principal=0 FROM org.EmpleadoUOT EU JOIN @Rama R ON R.uot_id=EU.uot_id WHERE EU.estado=1 AND EU.fecha_hasta IS NULL;
  UPDATE E SET estado=0,fecha_cese=COALESCE(E.fecha_cese,@Hoy) FROM org.Empleado E JOIN @Empleados X ON X.empleado_id=E.empleado_id WHERE NOT EXISTS(SELECT 1 FROM org.EmpleadoUOT EU WHERE EU.empleado_id=E.empleado_id AND EU.estado=1 AND EU.fecha_hasta IS NULL);
  UPDATE EU SET es_principal=1 FROM org.EmpleadoUOT EU JOIN @Empleados X ON X.empleado_id=EU.empleado_id WHERE EU.estado=1 AND EU.fecha_hasta IS NULL AND NOT EXISTS(SELECT 1 FROM org.EmpleadoUOT P WHERE P.empleado_id=EU.empleado_id AND P.estado=1 AND P.fecha_hasta IS NULL AND P.es_principal=1) AND EU.empleado_uot_id=(SELECT TOP(1) Z.empleado_uot_id FROM org.EmpleadoUOT Z WHERE Z.empleado_id=EU.empleado_id AND Z.estado=1 AND Z.fecha_hasta IS NULL ORDER BY Z.fecha_desde,Z.empleado_uot_id);
  DECLARE @Usuarios TABLE(usuario_id BIGINT PRIMARY KEY); INSERT @Usuarios SELECT DISTINCT UU.usuario_id FROM seg.UsuarioUOT UU JOIN @Rama R ON R.uot_id=UU.uot_id WHERE UU.estado=1 AND UU.fecha_hasta IS NULL;
  UPDATE P SET estado=0,fecha_hasta=COALESCE(P.fecha_hasta,@Ahora) FROM seg.UsuarioUOTPermiso P JOIN seg.UsuarioUOT UU ON UU.usuario_uot_id=P.usuario_uot_id JOIN @Rama R ON R.uot_id=UU.uot_id WHERE P.estado=1 AND P.fecha_hasta IS NULL;
  UPDATE UR SET estado=0,fecha_hasta=COALESCE(UR.fecha_hasta,@Ahora) FROM seg.UsuarioUOTRol UR JOIN seg.UsuarioUOT UU ON UU.usuario_uot_id=UR.usuario_uot_id JOIN @Rama R ON R.uot_id=UU.uot_id WHERE UR.estado=1 AND UR.fecha_hasta IS NULL;
  UPDATE UU SET estado=0,fecha_hasta=COALESCE(UU.fecha_hasta,@Ahora),es_predeterminada=0 FROM seg.UsuarioUOT UU JOIN @Rama R ON R.uot_id=UU.uot_id WHERE UU.estado=1 AND UU.fecha_hasta IS NULL;
  UPDATE U SET estado=0,estado_cuenta='DESHABILITADA',token_version=token_version+1,bloqueado_hasta=NULL FROM seg.Usuario U JOIN @Usuarios X ON X.usuario_id=U.usuario_id WHERE NOT EXISTS(SELECT 1 FROM seg.UsuarioUOT UU JOIN org.UOT OU ON OU.uot_id=UU.uot_id AND OU.estado=1 WHERE UU.usuario_id=U.usuario_id AND UU.estado=1 AND UU.fecha_hasta IS NULL);
  UPDATE S SET estado=0,fecha_revocacion=COALESCE(S.fecha_revocacion,@Ahora),motivo_revocacion=N'UOT retirada' FROM seg.SesionUsuario S JOIN @Usuarios X ON X.usuario_id=S.usuario_id WHERE S.estado=1 AND NOT EXISTS(SELECT 1 FROM seg.UsuarioUOT UU JOIN org.UOT OU ON OU.uot_id=UU.uot_id AND OU.estado=1 WHERE UU.usuario_id=S.usuario_id AND UU.estado=1 AND UU.fecha_hasta IS NULL);
  UPDATE S SET modo_uot='ESPECIFICA',uot_contexto_id=F.uot_id,fecha_ultima_actividad=@Ahora FROM seg.SesionUsuario S JOIN @Usuarios X ON X.usuario_id=S.usuario_id CROSS APPLY(SELECT TOP(1) UU.uot_id FROM seg.UsuarioUOT UU JOIN org.UOT OU ON OU.uot_id=UU.uot_id AND OU.estado=1 WHERE UU.usuario_id=S.usuario_id AND UU.estado=1 AND UU.fecha_hasta IS NULL ORDER BY UU.es_predeterminada DESC,UU.usuario_uot_id) F WHERE S.estado=1 AND S.fecha_revocacion IS NULL AND (EXISTS(SELECT 1 FROM @Rama R WHERE R.uot_id=S.uot_contexto_id) OR (S.modo_uot='GENERAL' AND (SELECT COUNT(*) FROM seg.UsuarioUOT UU2 JOIN org.UOT U2 ON U2.uot_id=UU2.uot_id AND U2.estado=1 WHERE UU2.usuario_id=S.usuario_id AND UU2.estado=1 AND UU2.fecha_hasta IS NULL)<2));
  UPDATE U SET estado=0,fecha_fin=COALESCE(U.fecha_fin,@Hoy) FROM org.UOT U JOIN @Rama R ON R.uot_id=U.uot_id;
  COMMIT; SELECT @bResultado=1,@cMensaje=N'UOT retirada.',@cCodigoRespuesta='UOT_RETIRADA',@nHttpRespuesta=200; RETURN 0;
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SET @cMensaje=N'No se pudo retirar la UOT.'; RETURN 1; END CATCH;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* 5. Edicion de UOT no cambia estado. La baja usa un PA dedicado. */
CREATE OR ALTER PROCEDURE org.PA_UOT_Upd_Registro
    @nUsuarioId BIGINT,@nUotId BIGINT,@nUotPadreId BIGINT=NULL,@nUbicacionId BIGINT=NULL,
    @cNombre NVARCHAR(160),@cDescripcion NVARCHAR(400)=NULL,@bEstado BIT=1,
    @bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SET @bResultado=0; SET @cMensaje=N'No se pudo actualizar la UOT.';
 SET @cNombre=NULLIF(LTRIM(RTRIM(@cNombre)),N'');
 IF seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotId,'UOT_EDITAR')=0 BEGIN SET @cMensaje=N'No tiene permiso para editar esta UOT.'; RETURN 1; END;
 IF NOT EXISTS(SELECT 1 FROM org.UOT WHERE uot_id=@nUotId AND estado=1) BEGIN SET @cMensaje=N'La UOT no esta disponible.'; RETURN 1; END;
 IF @cNombre IS NULL BEGIN SET @cMensaje=N'Ingrese el nombre de la UOT.'; RETURN 1; END;
 IF EXISTS(SELECT 1 FROM org.UOT WHERE uot_id=@nUotId AND es_raiz=1) AND @nUotPadreId IS NOT NULL BEGIN SET @cMensaje=N'La UOT raiz no puede depender de otra.'; RETURN 1; END;
 IF @nUotPadreId=@nUotId BEGIN SET @cMensaje=N'La UOT no puede depender de si misma.'; RETURN 1; END;
 IF @nUotPadreId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM org.UOT WHERE uot_id=@nUotPadreId AND estado=1) BEGIN SET @cMensaje=N'La UOT superior no esta disponible.'; RETURN 1; END;
 IF @nUbicacionId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM geo.Ubicacion WHERE ubicacion_id=@nUbicacionId) BEGIN SET @cMensaje=N'La ubicacion no es valida.'; RETURN 1; END;
 UPDATE org.UOT SET uot_padre_id=@nUotPadreId,ubicacion_id=@nUbicacionId,nombre=@cNombre,descripcion=@cDescripcion WHERE uot_id=@nUotId AND estado=1;
 SET @bResultado=1; SET @cMensaje=N'UOT actualizada.'; RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- prod.PA_CensoPlantas_Ins_Registro
CREATE OR ALTER PROCEDURE [prod].[PA_CensoPlantas_Ins_Registro]
(
    @cJson NVARCHAR(MAX), @nCensoPlantasId BIGINT OUTPUT, @bResultado BIT OUTPUT, @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

     SET NOCOUNT ON;
 SET XACT_ABORT ON;
    DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),
            @nCultivo BIGINT,@dFecha DATE,@nTot INT,@nProd INT,@nNoProd INT,@nNuevas INT,@nMuertas INT,@nAfect INT,@cObs NVARCHAR(300),@cPost NVARCHAR(MAX),@cIdent NVARCHAR(200),@nAud BIGINT,@nTrans BIGINT;
    SELECT @nCensoPlantasId=NULL,@bResultado=0,@cMensaje=N'No se pudo registrar el censo.';
    EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente] @cJson,'CENSOS_CREAR','CENSO_CREAR',@nUsuario OUTPUT,@nSesion OUTPUT,@nDisp OUTPUT,@nEmp OUTPUT,@nModulo OUTPUT,@gCorr OUTPUT,@gSol OUTPUT,@cIp OUTPUT,@cEnd OUTPUT,@nOp OUTPUT,@bRep OUTPUT,@cEstadoOp OUTPUT,@cIdRes OUTPUT,@cCodRes OUTPUT,@bIni OUTPUT,@cMsg OUTPUT;
    IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
 GOTO __DESCO_Salida;
 END;
 IF @bRep=1 BEGIN IF @cEstadoOp='COMPLETADA' BEGIN SET @nCensoPlantasId=TRY_CONVERT(BIGINT,@cIdRes);
 SET @bResultado=1;
 SET @cMensaje=N'La solicitud ya fue procesada correctamente.';
 END ELSE SET @cMensaje=N'La solicitud ya se encuentra en proceso.';
 GOTO __DESCO_Salida;
 END;
    SELECT @nCultivo=parcelaCultivoId,@dFecha=fechaCenso,@nTot=plantasTotales,@nProd=plantasProductivas,@nNoProd=plantasNoProductivas,@nNuevas=ISNULL(plantasNuevas,0),@nMuertas=ISNULL(plantasMuertas,0),@nAfect=ISNULL(plantasAfectadas,0),@cObs=NULLIF(LTRIM(RTRIM(observacion)),N'') FROM OPENJSON(@cJson,'$.censo') WITH (parcelaCultivoId BIGINT '$.parcelaCultivoId',fechaCenso DATE '$.fechaCenso',plantasTotales INT '$.plantasTotales',plantasProductivas INT '$.plantasProductivas',plantasNoProductivas INT '$.plantasNoProductivas',plantasNuevas INT '$.plantasNuevas',plantasMuertas INT '$.plantasMuertas',plantasAfectadas INT '$.plantasAfectadas',observacion NVARCHAR(300) '$.observacion');
    IF @nCultivo IS NULL OR @dFecha IS NULL OR @nTot IS NULL OR @nProd IS NULL OR @nNoProd IS NULL OR @nTot<0 OR @nProd<0 OR @nNoProd<0 OR @nNuevas<0 OR @nMuertas<0 OR @nAfect<0 OR @nProd+@nNoProd>@nTot OR @nAfect>@nTot BEGIN SET @cMensaje=N'Revise las cantidades del censo.';
 GOTO Fallar;
 END;
    IF NOT EXISTS(SELECT 1 FROM [prod].[ParcelaCultivo] WHERE parcela_cultivo_id=@nCultivo AND estado=1 AND situacion_cultivo='ACTIVO') BEGIN SET @cMensaje=N'El cultivo seleccionado no está disponible para registrar un censo.';
 GOTO Fallar;
 END;
    IF EXISTS(SELECT 1 FROM [prod].[ParcelaCultivo] WHERE parcela_cultivo_id=@nCultivo AND @dFecha<fecha_inicio) OR @dFecha>CONVERT(DATE,SYSUTCDATETIME()) BEGIN SET @cMensaje=N'La fecha del censo no es válida para el cultivo seleccionado.';
 GOTO Fallar;
 END;
    IF EXISTS(SELECT 1 FROM [prod].[CensoPlantas] WHERE parcela_cultivo_id=@nCultivo AND fecha_censo=@dFecha) BEGIN SET @cMensaje=N'Ya existe un censo registrado para esa fecha.';
 GOTO Fallar;
 END;
    BEGIN TRY BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;
      INSERT [prod].[CensoPlantas](parcela_cultivo_id,fecha_censo,plantas_totales,plantas_productivas,plantas_no_productivas,plantas_nuevas,plantas_muertas,plantas_afectadas,observacion) VALUES(@nCultivo,@dFecha,@nTot,@nProd,@nNoProd,@nNuevas,@nMuertas,@nAfect,@cObs);
 SET @nCensoPlantasId=CONVERT(BIGINT,SCOPE_IDENTITY());
      SELECT @cPost=(SELECT * FROM [prod].[CensoPlantas] WHERE censo_plantas_id=@nCensoPlantasId FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
 SET @cIdent=CONVERT(NVARCHAR(200),@nCensoPlantasId);
      EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio] @nUsuario,@nSesion,@nDisp,@nModulo,'CREAR','prod','CensoPlantas',@cIdent,NULL,@cPost,NULL,'estado',NULL,'1',@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
      /* Confirmar datos e idempotencia juntos. */ EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar] @nOp,'COMPLETADA','prod','CensoPlantas',@cIdent,'CENSO_CREADO',@bFin OUTPUT,@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;

      SET @bResultado=1;
 SET @cMensaje=N'Censo registrado correctamente.';
 GOTO __DESCO_Salida;
    END TRY BEGIN CATCH
SET @bResultado = 0;
 IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
 SET @cMensaje=N'No se pudo registrar el censo. Intente nuevamente.';
 
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'prod.PA_CensoPlantas_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;
Fallar: IF @nOp IS NOT NULL AND @bResultado=0 EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar] @nOp,'FALLIDA',NULL,NULL,NULL,'NO_PROCESADO',@bFin OUTPUT,@cMsgFin OUTPUT;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'prod.PA_CensoPlantas_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

    IF @bResultado = 0 AND @nOp IS NOT NULL AND XACT_STATE() <> -1
    BEGIN
        IF ISNULL(@bRep,0) = 0
        BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                 @nOperacionIdempotenteId = @nOp, @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
            -- No sustituir el motivo funcional por un fallo de registro secundario.
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'prod.PA_CensoPlantas_Ins_Registro',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
        END CATCH;
        END
        ELSE
        BEGIN
            SELECT @cMensaje = COALESCE(mensaje_resultado,
                CASE WHEN estado_operacion = 'FALLIDA'
                     THEN N'La solicitud anterior no se completó. Corrija los datos y envíe una nueva solicitud.'
                     ELSE N'La solicitud todavía se está procesando. Consulte el resultado antes de repetirla.' END)
            FROM [auditoria].[OperacionIdempotente]
            WHERE operacion_idempotente_id = @nOp;
        END;
    END;
IF @bResultado = 0
    SELECT @nCensoPlantasId = NULL;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'prod.PA_CensoPlantas_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'prod.PA_CensoPlantas_Ins_Registro',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* ===== prod.PA_CensoPlantas_Sel_Historial ===== */
CREATE OR ALTER PROCEDURE [prod].[PA_CensoPlantas_Sel_Historial]
(
    @cJson NVARCHAR(MAX), @bResultado BIT OUTPUT, @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;

    BEGIN TRY

     SET NOCOUNT ON;
    DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@bOk BIT,@cMsg NVARCHAR(300),@nCultivo BIGINT,@nParcela BIGINT,@dDesde DATE,@dHasta DATE,@nPagina INT=1,@nTam INT=30;
    SET @bResultado=0;
 SET @cMensaje=N'No se pudo cargar los censos.';
    EXEC [seg].[PA_Operacion_Sel_ContextoAutorizado] @cJson,'CENSOS_LISTAR',@nUsuario OUTPUT,@nSesion OUTPUT,@nDisp OUTPUT,@nEmp OUTPUT,@nModulo OUTPUT,@gCorr OUTPUT,@gSol OUTPUT,@cIp OUTPUT,@cEnd OUTPUT,@bOk OUTPUT,@cMsg OUTPUT;
    IF @bOk=0 BEGIN SET @cMensaje=@cMsg;
 GOTO __DESCO_Salida;
 END;
    SELECT @nCultivo=parcelaCultivoId,@nParcela=parcelaId,@dDesde=fechaDesde,@dHasta=fechaHasta,@nPagina=ISNULL(pagina,1),@nTam=ISNULL(tamanoPagina,30) FROM OPENJSON(@cJson,'$.filtros') WITH (parcelaCultivoId BIGINT '$.parcelaCultivoId',parcelaId BIGINT '$.parcelaId',fechaDesde DATE '$.fechaDesde',fechaHasta DATE '$.fechaHasta',pagina INT '$.pagina',tamanoPagina INT '$.tamanoPagina');
    IF @nPagina<1 SET @nPagina=1;
 IF @nTam<1 SET @nTam=30;
 IF @nTam>200 SET @nTam=200;
    ;
WITH Q AS
    (
      SELECT C.censo_plantas_id,C.parcela_cultivo_id,PC.parcela_id,PA.codigo parcelaCodigo,PA.nombre parcelaNombre,VP.nombre variedad,C.fecha_censo,C.plantas_totales,C.plantas_productivas,C.plantas_no_productivas,C.plantas_nuevas,C.plantas_muertas,C.plantas_afectadas,C.observacion,C.estado,COUNT_BIG(*) OVER() totalRegistros
      FROM [prod].[CensoPlantas] C INNER JOIN [prod].[ParcelaCultivo] PC ON PC.parcela_cultivo_id=C.parcela_cultivo_id INNER JOIN [prod].[Parcela] PA ON PA.parcela_id=PC.parcela_id INNER JOIN [prod].[VariedadPalta] VP ON VP.variedad_palta_id=PC.variedad_palta_id
      WHERE (@nCultivo IS NULL OR C.parcela_cultivo_id=@nCultivo) AND (@nParcela IS NULL OR PC.parcela_id=@nParcela) AND (@dDesde IS NULL OR C.fecha_censo>=@dDesde) AND (@dHasta IS NULL OR C.fecha_censo<=@dHasta)
    )
    SELECT * FROM Q ORDER BY fecha_censo DESC,censo_plantas_id DESC OFFSET (@nPagina-1)*@nTam ROWS FETCH NEXT @nTam ROWS ONLY;
    SET @bResultado=1;
 SET @cMensaje=N'Censos cargados correctamente.';

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'prod.PA_CensoPlantas_Sel_Historial',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'prod.PA_CensoPlantas_Sel_Historial',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'prod.PA_CensoPlantas_Sel_Historial',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- prod.PA_CensoPlantas_Upd_Registro
CREATE OR ALTER PROCEDURE [prod].[PA_CensoPlantas_Upd_Registro]
(
    @cJson NVARCHAR(MAX), @bResultado BIT OUTPUT, @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

     SET NOCOUNT ON;
 SET XACT_ABORT ON;
    DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),
            @nCenso BIGINT,@nCultivo BIGINT,@dFecha DATE,@nTot INT,@nProd INT,@nNoProd INT,@nNuevas INT,@nMuertas INT,@nAfect INT,@cObs NVARCHAR(300),@cAnt NVARCHAR(MAX),@cPost NVARCHAR(MAX),@cIdent NVARCHAR(200),@nAud BIGINT,@nTrans BIGINT;
    SET @bResultado=0;
 SET @cMensaje=N'No se pudo actualizar el censo.';
    EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente] @cJson,'CENSOS_EDITAR','CENSO_EDITAR',@nUsuario OUTPUT,@nSesion OUTPUT,@nDisp OUTPUT,@nEmp OUTPUT,@nModulo OUTPUT,@gCorr OUTPUT,@gSol OUTPUT,@cIp OUTPUT,@cEnd OUTPUT,@nOp OUTPUT,@bRep OUTPUT,@cEstadoOp OUTPUT,@cIdRes OUTPUT,@cCodRes OUTPUT,@bIni OUTPUT,@cMsg OUTPUT;
    IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
 GOTO __DESCO_Salida;
 END;
 IF @bRep=1 BEGIN IF @cEstadoOp='COMPLETADA' BEGIN SET @bResultado=1;
 SET @cMensaje=N'La solicitud ya fue procesada correctamente.';
 END ELSE SET @cMensaje=N'La solicitud ya se encuentra en proceso.';
 GOTO __DESCO_Salida;
 END;
    SELECT @nCenso=censoPlantasId,@dFecha=fechaCenso,@nTot=plantasTotales,@nProd=plantasProductivas,@nNoProd=plantasNoProductivas,@nNuevas=ISNULL(plantasNuevas,0),@nMuertas=ISNULL(plantasMuertas,0),@nAfect=ISNULL(plantasAfectadas,0),@cObs=NULLIF(LTRIM(RTRIM(observacion)),N'') FROM OPENJSON(@cJson,'$.censo') WITH (censoPlantasId BIGINT '$.censoPlantasId',fechaCenso DATE '$.fechaCenso',plantasTotales INT '$.plantasTotales',plantasProductivas INT '$.plantasProductivas',plantasNoProductivas INT '$.plantasNoProductivas',plantasNuevas INT '$.plantasNuevas',plantasMuertas INT '$.plantasMuertas',plantasAfectadas INT '$.plantasAfectadas',observacion NVARCHAR(300) '$.observacion');
    SELECT @nCultivo=parcela_cultivo_id FROM [prod].[CensoPlantas] WHERE censo_plantas_id=@nCenso AND estado=1;
    IF @nCultivo IS NULL OR NOT EXISTS(SELECT 1 FROM [prod].[ParcelaCultivo] WHERE parcela_cultivo_id=@nCultivo AND estado=1 AND situacion_cultivo='ACTIVO') BEGIN SET @cMensaje=N'El censo seleccionado ya no está disponible para edición.';
 GOTO Fallar;
 END;
    IF EXISTS(SELECT 1 FROM [prod].[ParcelaCultivo] WHERE parcela_cultivo_id=@nCultivo AND @dFecha<fecha_inicio) OR @dFecha>CONVERT(DATE,SYSUTCDATETIME()) BEGIN SET @cMensaje=N'La fecha del censo no es válida para el cultivo seleccionado.';
 GOTO Fallar;
 END;
    IF @dFecha IS NULL OR @nTot IS NULL OR @nProd IS NULL OR @nNoProd IS NULL OR @nTot<0 OR @nProd<0 OR @nNoProd<0 OR @nNuevas<0 OR @nMuertas<0 OR @nAfect<0 OR @nProd+@nNoProd>@nTot OR @nAfect>@nTot BEGIN SET @cMensaje=N'Revise las cantidades del censo.';
 GOTO Fallar;
 END;
    IF @dFecha>CONVERT(DATE,SYSUTCDATETIME()) BEGIN SET @cMensaje=N'La fecha del censo no puede ser posterior a hoy.';
 GOTO Fallar;
 END;
    IF EXISTS(SELECT 1 FROM [prod].[CensoPlantas] WHERE parcela_cultivo_id=@nCultivo AND fecha_censo=@dFecha AND censo_plantas_id<>@nCenso) BEGIN SET @cMensaje=N'Ya existe un censo registrado para esa fecha.';
 GOTO Fallar;
 END;
    BEGIN TRY BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;
      SELECT @cAnt=(SELECT * FROM [prod].[CensoPlantas] WHERE censo_plantas_id=@nCenso FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
      UPDATE [prod].[CensoPlantas] SET fecha_censo=@dFecha,plantas_totales=@nTot,plantas_productivas=@nProd,plantas_no_productivas=@nNoProd,plantas_nuevas=@nNuevas,plantas_muertas=@nMuertas,plantas_afectadas=@nAfect,observacion=@cObs WHERE censo_plantas_id=@nCenso AND estado=1;
      SELECT @cPost=(SELECT * FROM [prod].[CensoPlantas] WHERE censo_plantas_id=@nCenso FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
 SET @cIdent=CONVERT(NVARCHAR(200),@nCenso);
      EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio] @nUsuario,@nSesion,@nDisp,@nModulo,'EDITAR','prod','CensoPlantas',@cIdent,@cAnt,@cPost,NULL,NULL,NULL,NULL,@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
      /* Confirmar datos e idempotencia juntos. */ EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar] @nOp,'COMPLETADA','prod','CensoPlantas',@cIdent,'CENSO_ACTUALIZADO',@bFin OUTPUT,@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;

      SET @bResultado=1;
 SET @cMensaje=N'Censo actualizado correctamente.';
 GOTO __DESCO_Salida;
    END TRY BEGIN CATCH
SET @bResultado = 0;
 IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
 SET @cMensaje=N'No se pudo actualizar el censo. Intente nuevamente.';
 
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'prod.PA_CensoPlantas_Upd_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;
Fallar: IF @nOp IS NOT NULL AND @bResultado=0 EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar] @nOp,'FALLIDA',NULL,NULL,NULL,'NO_PROCESADO',@bFin OUTPUT,@cMsgFin OUTPUT;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'prod.PA_CensoPlantas_Upd_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

    IF @bResultado = 0 AND @nOp IS NOT NULL AND XACT_STATE() <> -1
    BEGIN
        IF ISNULL(@bRep,0) = 0
        BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                 @nOperacionIdempotenteId = @nOp, @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
            -- No sustituir el motivo funcional por un fallo de registro secundario.
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'prod.PA_CensoPlantas_Upd_Registro',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
        END CATCH;
        END
        ELSE
        BEGIN
            SELECT @cMensaje = COALESCE(mensaje_resultado,
                CASE WHEN estado_operacion = 'FALLIDA'
                     THEN N'La solicitud anterior no se completó. Corrija los datos y envíe una nueva solicitud.'
                     ELSE N'La solicitud todavía se está procesando. Consulte el resultado antes de repetirla.' END)
            FROM [auditoria].[OperacionIdempotente]
            WHERE operacion_idempotente_id = @nOp;
        END;
    END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'prod.PA_CensoPlantas_Upd_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'prod.PA_CensoPlantas_Upd_Registro',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

