SET XACT_ABORT ON;
DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),@nId BIGINT,@dDesde DATE,@dHasta DATE,@nKg DECIMAL(14,3),@cObs NVARCHAR(400),@cAnt NVARCHAR(MAX),@cPost NVARCHAR(MAX),@cIdent NVARCHAR(200),@nAud BIGINT,@nTrans BIGINT;
SELECT @bResultado=0,@cMensaje=N'No se pudo actualizar la estimación.';
EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente] @cJson,'PRODUCCION_EDITAR','PRODUCCION_EDITAR',@nUsuario OUTPUT,@nSesion OUTPUT,@nDisp OUTPUT,@nEmp OUTPUT,@nModulo OUTPUT,@gCorr OUTPUT,@gSol OUTPUT,@cIp OUTPUT,@cEnd OUTPUT,@nOp OUTPUT,@bRep OUTPUT,@cEstadoOp OUTPUT,@cIdRes OUTPUT,@cCodRes OUTPUT,@bIni OUTPUT,@cMsg OUTPUT;
IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
GOTO __DESCO_Salida;
END;
IF @bRep=1 BEGIN SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
SET @cMensaje=CASE WHEN @cEstadoOp='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.' ELSE N'La solicitud ya se encuentra en proceso.' END;
GOTO __DESCO_Salida;
END;
SELECT @nId=disponibilidadProduccionId,@dDesde=disponibleDesde,@dHasta=disponibleHasta,@nKg=cantidadEstimadaKg,@cObs=NULLIF(LTRIM(RTRIM(observacion)),N'') FROM OPENJSON(@cJson,'$.produccion') WITH(disponibilidadProduccionId BIGINT '$.disponibilidadProduccionId',disponibleDesde DATE '$.disponibleDesde',disponibleHasta DATE '$.disponibleHasta',cantidadEstimadaKg DECIMAL(14,3) '$.cantidadEstimadaKg',observacion NVARCHAR(400) '$.observacion');
IF @nId IS NULL OR @dDesde IS NULL OR @nKg IS NULL OR @nKg<0 OR (@dHasta IS NOT NULL AND @dHasta<@dDesde) BEGIN SET @cMensaje=N'Complete correctamente los datos de la estimación.';
GOTO Fallar;
END;
IF NOT EXISTS(SELECT 1 FROM [prod].[DisponibilidadProduccion] WHERE disponibilidad_produccion_id=@nId AND estado=1 AND estado_estimacion='ESTIMADA') BEGIN SET @cMensaje=N'Solo una estimación pendiente puede modificarse.';
GOTO Fallar;
END;
    BEGIN TRY BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;
SELECT @cAnt=(SELECT disponibilidad_produccion_id,disponible_desde,disponible_hasta,cantidad_estimada_kg,estado_estimacion,observacion FROM [prod].[DisponibilidadProduccion] WHERE disponibilidad_produccion_id=@nId FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
UPDATE [prod].[DisponibilidadProduccion] SET disponible_desde=@dDesde,disponible_hasta=@dHasta,cantidad_estimada_kg=@nKg,observacion=@cObs WHERE disponibilidad_produccion_id=@nId;
SELECT @cPost=(SELECT disponibilidad_produccion_id,disponible_desde,disponible_hasta,cantidad_estimada_kg,estado_estimacion,observacion FROM [prod].[DisponibilidadProduccion] WHERE disponibilidad_produccion_id=@nId FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
SET @cIdent=CONVERT(NVARCHAR(200),@nId);
EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio] @nUsuario,@nSesion,@nDisp,@nModulo,'EDITAR','prod','DisponibilidadProduccion',@cIdent,@cAnt,@cPost,NULL,NULL,NULL,NULL,@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
/* Confirmar datos e idempotencia juntos. */EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar] @nOp,'COMPLETADA','prod','DisponibilidadProduccion',@cIdent,'PRODUCCION_ACTUALIZADA',@bFin OUTPUT,@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado=1;
SET @cMensaje=N'Estimación actualizada correctamente.';
GOTO __DESCO_Salida;
END TRY BEGIN CATCH
SET @bResultado = 0;
 IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @cMensaje=N'No se pudo actualizar la estimación. Intente nuevamente.';
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'prod.PA_DisponibilidadProduccion_Upd_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;
Fallar:IF @nOp IS NOT NULL AND @bResultado=0 EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar] @nOp,'FALLIDA',NULL,NULL,NULL,'NO_PROCESADO',@bFin OUTPUT,@cMsgFin OUTPUT;

    END TRY
    BEGIN CATCH

