SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'prod.PA_DisponibilidadProduccion_Upd_Registro',@bResultado,@cMensaje) R;
