-- sanidad.PA_CasoFitosanitario_Upd_Estado
CREATE OR ALTER PROCEDURE [sanidad].[PA_CasoFitosanitario_Upd_Estado]
(
    @cJson NVARCHAR(MAX),
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,
        @gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),
        @nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),
        @bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),
        @nCaso BIGINT,@cAnt VARCHAR(20),@cNuevo VARCHAR(20),@cMotivo NVARCHAR(500),
        @cUltimoResultado VARCHAR(20),@cIdent NVARCHAR(200),@nAud BIGINT,@nTrans BIGINT;

    SELECT @bResultado=0,@cMensaje=N'No se pudo actualizar el estado del caso.';

    EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente]
        @cJson=@cJson,
        @cCodigoPermiso='SANIDAD_EDITAR',
        @cAmbito='SANIDAD_CASO_ESTADO',
        @nUsuarioId=@nUsuario OUTPUT,
        @nSesionUsuarioId=@nSesion OUTPUT,
        @nDispositivoUsuarioId=@nDisp OUTPUT,
        @nEmpleadoId=@nEmp OUTPUT,
        @nModuloId=@nModulo OUTPUT,
        @gCorrelacionId=@gCorr OUTPUT,
        @gSolicitudId=@gSol OUTPUT,
        @cIp=@cIp OUTPUT,
        @cEndpoint=@cEnd OUTPUT,
        @nOperacionIdempotenteId=@nOp OUTPUT,
        @bEsRepetida=@bRep OUTPUT,
        @cEstadoOperacion=@cEstadoOp OUTPUT,
        @cIdentificadorResultado=@cIdRes OUTPUT,
        @cCodigoResultado=@cCodRes OUTPUT,
        @bResultado=@bIni OUTPUT,
        @cMensaje=@cMsg OUTPUT;

    IF @bIni=0 AND @bRep=0
    BEGIN
        SET @cMensaje=@cMsg;
        GOTO __DESCO_Salida;
    END;

    IF @bRep=1
    BEGIN
        SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
        SET @cMensaje=CASE WHEN @cEstadoOp='COMPLETADA'
                           THEN N'La solicitud ya fue procesada correctamente.'
                           ELSE N'La solicitud ya se encuentra en proceso.' END;
        GOTO __DESCO_Salida;
    END;

    SELECT
        @nCaso=casoFitosanitarioId,
        @cNuevo=UPPER(NULLIF(LTRIM(RTRIM(nuevoEstado)),'')),
        @cMotivo=NULLIF(LTRIM(RTRIM(motivo)),N'')
    FROM OPENJSON(@cJson,'$.caso')
    WITH
    (
        casoFitosanitarioId BIGINT '$.casoFitosanitarioId',
        nuevoEstado VARCHAR(20) '$.nuevoEstado',
        motivo NVARCHAR(500) '$.motivo'
    );

    SELECT @cAnt=estado_caso
    FROM [sanidad].[CasoFitosanitario]
    WHERE caso_fitosanitario_id=@nCaso
      AND estado=1;

    IF @cAnt IS NULL
    BEGIN
        SET @cMensaje=N'El caso sanitario seleccionado no está disponible.';
        GOTO Fallar;
    END;

    IF @cNuevo IS NULL OR @cNuevo='CERRADO'
    BEGIN
        SET @cMensaje=N'Seleccione un estado válido. Para finalizar utilice la acción Cerrar caso.';
        GOTO Fallar;
    END;

    IF @cAnt IN('RECUPERADO','NO_RECUPERADO','CERRADO')
    BEGIN
        SET @cMensaje=N'El caso ya se encuentra en una etapa final y no admite este cambio.';
        GOTO Fallar;
    END;

    SELECT TOP(1) @cUltimoResultado=S.resultado
    FROM [sanidad].[SeguimientoFitosanitario] S
    WHERE S.caso_fitosanitario_id=@nCaso
      AND S.estado=1
    ORDER BY S.fecha_hora DESC,S.seguimiento_fitosanitario_id DESC;

    IF NOT
    (
        (
            @cAnt='DETECTADO'
            AND @cNuevo='EN_TRATAMIENTO'
            AND EXISTS
            (
                SELECT 1
                FROM [sanidad].[TratamientoFitosanitario] T
                WHERE T.caso_fitosanitario_id=@nCaso
                  AND T.estado=1
            )
        )
        OR
        (
            @cAnt='EN_TRATAMIENTO'
            AND @cNuevo='EN_SEGUIMIENTO'
            AND EXISTS
            (
                SELECT 1
                FROM [sanidad].[SeguimientoFitosanitario] S
                WHERE S.caso_fitosanitario_id=@nCaso
                  AND S.estado=1
            )
        )
        OR
        (
            @cAnt='EN_SEGUIMIENTO'
            AND @cNuevo='CONTROLADO'
            AND @cUltimoResultado='CONTROLADO'
        )
        OR
        (
            @cAnt IN('EN_TRATAMIENTO','EN_SEGUIMIENTO','CONTROLADO')
            AND @cNuevo='NO_RECUPERADO'
            AND @cUltimoResultado='NO_RECUPERADO'
        )
        OR
        (
            @cAnt='CONTROLADO'
            AND @cNuevo='RECUPERADO'
            AND @cUltimoResultado='RECUPERADO'
        )
    )
    BEGIN
        SET @cMensaje=N'El cambio de estado no corresponde al avance registrado del caso.';
        GOTO Fallar;
    END;

    BEGIN TRY
        BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

        UPDATE [sanidad].[CasoFitosanitario]
        SET estado_caso=@cNuevo
        WHERE caso_fitosanitario_id=@nCaso
          AND estado=1
          AND estado_caso=@cAnt;

        IF @@ROWCOUNT<>1
            THROW 54701,N'ESTADO_CAMBIO_CONCURRENTE',1;

        SET @cIdent=CONVERT(NVARCHAR(200),@nCaso);

        EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio]
            @nUsuarioId=@nUsuario,
            @nSesionUsuarioId=@nSesion,
            @nDispositivoUsuarioId=@nDisp,
            @nModuloId=@nModulo,
            @cAccion='CAMBIAR_ESTADO',
            @cEsquemaEntidad='sanidad',
            @cNombreEntidad='CasoFitosanitario',
            @cIdentificador=@cIdent,
            @cDatosAnteriores=NULL,
            @cDatosPosteriores=NULL,
            @cMotivo=@cMotivo,
            @cCampoEstado='estado_caso',
            @cEstadoAnterior=@cAnt,
            @cEstadoNuevo=@cNuevo,
            @cIp=@cIp,
            @gCorrelacionId=@gCorr,
            @gSolicitudId=@gSol,
            @cEndpoint=@cEnd,
            @nAuditoriaEventoId=@nAud OUTPUT,
            @nTransicionEstadoId=@nTrans OUTPUT;

        /* Confirmar datos e idempotencia juntos. */

        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
            @nOperacionIdempotenteId=@nOp,
            @cEstadoOperacion='COMPLETADA',
            @cEsquemaEntidad='sanidad',
            @cNombreEntidad='CasoFitosanitario',
            @cIdentificadorResultado=@cIdent,
            @cCodigoResultado='ESTADO_ACTUALIZADO',
            @bResultado=@bFin OUTPUT,
            @cMensaje=@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;

        SET @bResultado=1;
        SET @cMensaje=N'Estado del caso actualizado correctamente.';
        GOTO __DESCO_Salida;
    END TRY
    BEGIN CATCH
SET @bResultado = 0;

        IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
        IF ERROR_MESSAGE()=N'ESTADO_CAMBIO_CONCURRENTE'
            SET @cMensaje=N'El caso cambió mientras se procesaba la solicitud. Actualice la información e intente nuevamente.';
        ELSE
            SET @cMensaje=N'No se pudo actualizar el estado del caso. Intente nuevamente.';
    
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'sanidad.PA_CasoFitosanitario_Upd_Estado',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;

Fallar:
    IF @nOp IS NOT NULL AND @bResultado=0
        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
            @nOperacionIdempotenteId=@nOp,
            @cEstadoOperacion='FALLIDA',
            @cEsquemaEntidad=NULL,
            @cNombreEntidad=NULL,
            @cIdentificadorResultado=NULL,
            @cCodigoResultado='NO_PROCESADO',
            @bResultado=@bFin OUTPUT,
            @cMensaje=@cMsgFin OUTPUT;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'sanidad.PA_CasoFitosanitario_Upd_Estado',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

    IF @bResultado = 0 AND @nOp IS NOT NULL AND XACT_STATE() <> -1
    BEGIN
        IF ISNULL(@bRep,0) = 0
        BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                 @nOperacionIdempotenteId = @nOp, @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
            -- No sustituir el motivo funcional por un fallo de registro secundario.
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'sanidad.PA_CasoFitosanitario_Upd_Estado',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
        END CATCH;
        END
        ELSE
        BEGIN
            SELECT @cMensaje = COALESCE(mensaje_resultado,
                CASE WHEN estado_operacion = 'FALLIDA'
                     THEN N'La solicitud anterior no se completó. Corrija los datos y envíe una nueva solicitud.'
                     ELSE N'La solicitud todavía se está procesando. Consulte el resultado antes de repetirla.' END)
            FROM [auditoria].[OperacionIdempotente]
            WHERE operacion_idempotente_id = @nOp;
        END;
    END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'sanidad.PA_CasoFitosanitario_Upd_Estado',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'sanidad.PA_CasoFitosanitario_Upd_Estado',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- sanidad.PA_CasoFitosanitario_Upd_Registro
CREATE OR ALTER PROCEDURE [sanidad].[PA_CasoFitosanitario_Upd_Registro]
(
    @cJson NVARCHAR(MAX), @bResultado BIT OUTPUT, @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;
 SET XACT_ABORT ON;
    DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),
            @nCaso BIGINT,@nTipo SMALLINT,@nPlantas INT,@bEst BIT,@cSev VARCHAR(10),@cObs NVARCHAR(500),@cEstado VARCHAR(20),@cAnt NVARCHAR(MAX),@cPost NVARCHAR(MAX),@cIdent NVARCHAR(200),@nAud BIGINT,@nTrans BIGINT;
    SELECT @bResultado=0,@cMensaje=N'No se pudo actualizar el caso sanitario.';
    EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente] @cJson=@cJson,@cCodigoPermiso='SANIDAD_EDITAR',@cAmbito='SANIDAD_CASO_EDITAR',@nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@nOperacionIdempotenteId=@nOp OUTPUT,@bEsRepetida=@bRep OUTPUT,@cEstadoOperacion=@cEstadoOp OUTPUT,@cIdentificadorResultado=@cIdRes OUTPUT,@cCodigoResultado=@cCodRes OUTPUT,@bResultado=@bIni OUTPUT,@cMensaje=@cMsg OUTPUT;
    IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
GOTO __DESCO_Salida;
END;
 IF @bRep=1 BEGIN SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
SET @cMensaje=CASE WHEN @cEstadoOp='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.' ELSE N'La solicitud ya se encuentra en proceso.' END;
GOTO __DESCO_Salida;
END;
    SELECT @nCaso=casoFitosanitarioId,@nTipo=tipoProblemaId,@nPlantas=plantasAfectadas,@bEst=cantidadEstimada,@cSev=UPPER(NULLIF(LTRIM(RTRIM(severidad)),'')),@cObs=NULLIF(LTRIM(RTRIM(observacion)),N'') FROM OPENJSON(@cJson,'$.caso') WITH(casoFitosanitarioId BIGINT '$.casoFitosanitarioId',tipoProblemaId SMALLINT '$.tipoProblemaId',plantasAfectadas INT '$.plantasAfectadas',cantidadEstimada BIT '$.cantidadEstimada',severidad VARCHAR(10) '$.severidad',observacion NVARCHAR(500) '$.observacion');
    SELECT @cEstado=estado_caso FROM [sanidad].[CasoFitosanitario] WHERE caso_fitosanitario_id=@nCaso AND estado=1;
    IF @cEstado IS NULL BEGIN SET @cMensaje=N'El caso sanitario seleccionado no está disponible.';
GOTO Fallar;
END;
    IF @cEstado IN('RECUPERADO','NO_RECUPERADO','CERRADO') BEGIN SET @cMensaje=N'El caso ya se encuentra en una etapa cerrada y no puede editarse como registro preliminar.';
GOTO Fallar;
END;
    IF @nTipo IS NULL OR @cSev NOT IN('BAJA','MEDIA','ALTA') OR (@nPlantas IS NOT NULL AND @nPlantas<0) BEGIN SET @cMensaje=N'Complete correctamente los datos del caso sanitario.';
GOTO Fallar;
END;
    IF NOT EXISTS(SELECT 1 FROM [sanidad].[TipoProblemaFitosanitario] WHERE tipo_problema_fitosanitario_id=@nTipo AND estado=1) BEGIN SET @cMensaje=N'El problema sanitario seleccionado no está disponible.';
GOTO Fallar;
END;
    IF @nPlantas IS NULL SET @bEst=NULL;
    BEGIN TRY BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;
      SELECT @cAnt=(SELECT caso_fitosanitario_id,tipo_problema_fitosanitario_id,plantas_afectadas,cantidad_estimada,severidad,estado_caso,observacion FROM [sanidad].[CasoFitosanitario] WHERE caso_fitosanitario_id=@nCaso FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
      UPDATE [sanidad].[CasoFitosanitario] SET tipo_problema_fitosanitario_id=@nTipo,plantas_afectadas=@nPlantas,cantidad_estimada=@bEst,severidad=@cSev,observacion=@cObs WHERE caso_fitosanitario_id=@nCaso AND estado=1;
      SELECT @cPost=(SELECT caso_fitosanitario_id,tipo_problema_fitosanitario_id,plantas_afectadas,cantidad_estimada,severidad,estado_caso,observacion FROM [sanidad].[CasoFitosanitario] WHERE caso_fitosanitario_id=@nCaso FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
 SET @cIdent=CONVERT(NVARCHAR(200),@nCaso);
      EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio] @nUsuario,@nSesion,@nDisp,@nModulo,'EDITAR','sanidad','CasoFitosanitario',@cIdent,@cAnt,@cPost,NULL,NULL,NULL,NULL,@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
      /* Confirmar datos e idempotencia juntos. */ EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar] @nOp,'COMPLETADA','sanidad','CasoFitosanitario',@cIdent,'CASO_ACTUALIZADO',@bFin OUTPUT,@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
 SET @bResultado=1;
SET @cMensaje=N'Caso sanitario actualizado correctamente.';
GOTO __DESCO_Salida;
    END TRY BEGIN CATCH
SET @bResultado = 0;
 IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @cMensaje=N'No se pudo actualizar el caso sanitario. Intente nuevamente.';
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'sanidad.PA_CasoFitosanitario_Upd_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;
Fallar: IF @nOp IS NOT NULL AND @bResultado=0 EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar] @nOp,'FALLIDA',NULL,NULL,NULL,'NO_PROCESADO',@bFin OUTPUT,@cMsgFin OUTPUT;

    END TRY
    BEGIN CATCH

