-- sanidad.PA_TratamientoFitosanitario_Ins_Registro
CREATE OR ALTER PROCEDURE [sanidad].[PA_TratamientoFitosanitario_Ins_Registro]
(
    @cJson NVARCHAR(MAX),
    @nTratamientoId BIGINT OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,
        @gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),
        @nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),
        @bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),
        @nCaso BIGINT,@nVisita BIGINT,@nResp BIGINT,@dFecha DATETIME2(0),@cTrat NVARCHAR(300),
        @cProd NVARCHAR(160),@nDosis DECIMAL(12,4),@cUnidad VARCHAR(30),@cObs NVARCHAR(400),
        @cEstado VARCHAR(20),@nPredioCaso BIGINT,@nPredioVisita BIGINT,@dInicioVisita DATETIME2(0),
        @cPost NVARCHAR(MAX),@cIdent NVARCHAR(200),@nAud BIGINT,@nTrans BIGINT,
        @nAudCaso BIGINT,@nTransCaso BIGINT;

    SELECT
        @nTratamientoId=NULL,
        @bResultado=0,
        @cMensaje=N'No se pudo registrar el tratamiento.';

    EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente]
        @cJson,'SANIDAD_CREAR','SANIDAD_TRATAMIENTO_CREAR',
        @nUsuario OUTPUT,@nSesion OUTPUT,@nDisp OUTPUT,@nEmp OUTPUT,@nModulo OUTPUT,
        @gCorr OUTPUT,@gSol OUTPUT,@cIp OUTPUT,@cEnd OUTPUT,@nOp OUTPUT,@bRep OUTPUT,
        @cEstadoOp OUTPUT,@cIdRes OUTPUT,@cCodRes OUTPUT,@bIni OUTPUT,@cMsg OUTPUT;

    IF @bIni=0 AND @bRep=0
    BEGIN
        SET @cMensaje=@cMsg;
        GOTO __DESCO_Salida;
    END;

    IF @bRep=1
    BEGIN
        IF @cEstadoOp='COMPLETADA'
        BEGIN
            SET @nTratamientoId=TRY_CONVERT(BIGINT,@cIdRes);
            SET @bResultado=1;
            SET @cMensaje=N'La solicitud ya fue procesada correctamente.';
        END
        ELSE
            SET @cMensaje=N'La solicitud ya se encuentra en proceso.';
        GOTO __DESCO_Salida;
    END;

    SELECT
        @nCaso=casoFitosanitarioId,
        @nVisita=visitaTecnicaId,
        @nResp=responsableEmpleadoId,
        @dFecha=fechaHora,
        @cTrat=NULLIF(LTRIM(RTRIM(tratamiento)),N''),
        @cProd=NULLIF(LTRIM(RTRIM(producto)),N''),
        @nDosis=dosis,
        @cUnidad=NULLIF(LTRIM(RTRIM(unidadDosis)),''),
        @cObs=NULLIF(LTRIM(RTRIM(observacion)),N'')
    FROM OPENJSON(@cJson,'$.tratamiento')
    WITH
    (
        casoFitosanitarioId BIGINT '$.casoFitosanitarioId',
        visitaTecnicaId BIGINT '$.visitaTecnicaId',
        responsableEmpleadoId BIGINT '$.responsableEmpleadoId',
        fechaHora DATETIME2(0) '$.fechaHora',
        tratamiento NVARCHAR(300) '$.tratamiento',
        producto NVARCHAR(160) '$.producto',
        dosis DECIMAL(12,4) '$.dosis',
        unidadDosis VARCHAR(30) '$.unidadDosis',
        observacion NVARCHAR(400) '$.observacion'
    );

    IF @nResp IS NULL SET @nResp=@nEmp;
    IF @dFecha IS NULL SET @dFecha=SYSUTCDATETIME();

    SELECT
        @cEstado=CF.estado_caso,
        @nPredioCaso=P.predio_id
    FROM [sanidad].[CasoFitosanitario] CF
    INNER JOIN [prod].[ParcelaCultivo] PC
        ON PC.parcela_cultivo_id=CF.parcela_cultivo_id
    INNER JOIN [prod].[Parcela] P
        ON P.parcela_id=PC.parcela_id
    WHERE CF.caso_fitosanitario_id=@nCaso
      AND CF.estado=1;

    IF @cEstado IS NULL
    BEGIN
        SET @cMensaje=N'El caso sanitario seleccionado no está disponible.';
        GOTO Fallar;
    END;

    IF @cEstado IN('CONTROLADO','RECUPERADO','NO_RECUPERADO','CERRADO')
    BEGIN
        SET @cMensaje=N'El caso ya no admite nuevos tratamientos en su estado actual.';
        GOTO Fallar;
    END;

    IF @dFecha>SYSUTCDATETIME()
    BEGIN
        SET @cMensaje=N'La fecha del tratamiento no puede estar en el futuro.';
        GOTO Fallar;
    END;

    IF @cTrat IS NULL OR (@nDosis IS NOT NULL AND @nDosis<=0)
    BEGIN
        SET @cMensaje=N'Complete correctamente los datos del tratamiento.';
        GOTO Fallar;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [org].[Empleado]
        WHERE empleado_id=@nResp
          AND estado=1
    )
    BEGIN
        SET @cMensaje=N'El responsable seleccionado no está disponible.';
        GOTO Fallar;
    END;

    IF @nVisita IS NOT NULL
    BEGIN
        SELECT
            @nPredioVisita=predio_id,
            @dInicioVisita=fecha_hora_inicio
        FROM [campo].[VisitaTecnica]
        WHERE visita_tecnica_id=@nVisita
          AND estado=1
          AND estado_proceso='INICIADA';

        IF @nPredioVisita IS NULL
        BEGIN
            SET @cMensaje=N'La visita seleccionada debe encontrarse en curso.';
            GOTO Fallar;
        END;

        IF @nPredioVisita<>@nPredioCaso
        BEGIN
            SET @cMensaje=N'La visita seleccionada no corresponde al predio del caso sanitario.';
            GOTO Fallar;
        END;

        IF @dFecha<@dInicioVisita
        BEGIN
            SET @cMensaje=N'La fecha del tratamiento no corresponde al periodo de la visita.';
            GOTO Fallar;
        END;
    END;

    BEGIN TRY
        BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

        INSERT [sanidad].[TratamientoFitosanitario]
        (
            caso_fitosanitario_id,visita_tecnica_id,responsable_empleado_id,fecha_hora,
            tratamiento,producto,dosis,unidad_dosis,observacion,estado
        )
        VALUES
        (
            @nCaso,@nVisita,@nResp,@dFecha,@cTrat,@cProd,@nDosis,@cUnidad,@cObs,1
        );

        SET @nTratamientoId=CONVERT(BIGINT,SCOPE_IDENTITY());
        SET @cIdent=CONVERT(NVARCHAR(200),@nTratamientoId);

        SELECT @cPost=
        (
            SELECT
                @nTratamientoId tratamientoId,
                @nCaso casoFitosanitarioId,
                @nVisita visitaTecnicaId,
                @nResp responsableEmpleadoId,
                @dFecha fechaHora,
                @cTrat tratamiento,
                @cProd producto,
                @nDosis dosis,
                @cUnidad unidadDosis
            FOR JSON PATH,WITHOUT_ARRAY_WRAPPER
        );

        EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio]
            @nUsuario,@nSesion,@nDisp,@nModulo,'CREAR','sanidad','TratamientoFitosanitario',
            @cIdent,NULL,@cPost,NULL,NULL,NULL,NULL,@cIp,@gCorr,@gSol,@cEnd,
            @nAud OUTPUT,@nTrans OUTPUT;

        IF @cEstado='DETECTADO'
        BEGIN
            UPDATE [sanidad].[CasoFitosanitario]
            SET estado_caso='EN_TRATAMIENTO'
            WHERE caso_fitosanitario_id=@nCaso;

            SET @cIdent=CONVERT(NVARCHAR(200),@nCaso);

            EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio]
                @nUsuario,@nSesion,@nDisp,@nModulo,'CAMBIAR_ESTADO','sanidad','CasoFitosanitario',
                @cIdent,NULL,NULL,N'Inicio de tratamiento.','estado_caso','DETECTADO','EN_TRATAMIENTO',
                @cIp,@gCorr,@gSol,@cEnd,@nAudCaso OUTPUT,@nTransCaso OUTPUT;
        END;

        /* Confirmar datos e idempotencia juntos. */

        SET @cIdent=CONVERT(NVARCHAR(200),@nTratamientoId);

        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
            @nOp,'COMPLETADA','sanidad','TratamientoFitosanitario',@cIdent,
            'TRATAMIENTO_CREADO',@bFin OUTPUT,@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;

        SET @bResultado=1;
        SET @cMensaje=N'Tratamiento registrado correctamente.';
        GOTO __DESCO_Salida;
    END TRY
    BEGIN CATCH
SET @bResultado = 0;

        IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
        SET @cMensaje=N'No se pudo registrar el tratamiento. Intente nuevamente.';
    
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'sanidad.PA_TratamientoFitosanitario_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;

Fallar:
    IF @nOp IS NOT NULL AND @bResultado=0
        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
            @nOp,'FALLIDA',NULL,NULL,NULL,'NO_PROCESADO',@bFin OUTPUT,@cMsgFin OUTPUT;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'sanidad.PA_TratamientoFitosanitario_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

    IF @bResultado = 0 AND @nOp IS NOT NULL AND XACT_STATE() <> -1
    BEGIN
        IF ISNULL(@bRep,0) = 0
        BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                 @nOperacionIdempotenteId = @nOp, @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
            -- No sustituir el motivo funcional por un fallo de registro secundario.
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'sanidad.PA_TratamientoFitosanitario_Ins_Registro',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
        END CATCH;
        END
        ELSE
        BEGIN
            SELECT @cMensaje = COALESCE(mensaje_resultado,
                CASE WHEN estado_operacion = 'FALLIDA'
                     THEN N'La solicitud anterior no se completó. Corrija los datos y envíe una nueva solicitud.'
                     ELSE N'La solicitud todavía se está procesando. Consulte el resultado antes de repetirla.' END)
            FROM [auditoria].[OperacionIdempotente]
            WHERE operacion_idempotente_id = @nOp;
        END;
    END;
IF @bResultado = 0
    SELECT @nTratamientoId = NULL;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'sanidad.PA_TratamientoFitosanitario_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'sanidad.PA_TratamientoFitosanitario_Ins_Registro',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- seg.PA_Autorizacion_Sel_ValidarDelegacionRoles
CREATE OR ALTER PROCEDURE [seg].[PA_Autorizacion_Sel_ValidarDelegacionRoles]
(
    @nUsuarioActorId BIGINT,
    @cRolesJson NVARCHAR(MAX),
    @bRequerirAlMenosUno BIT = 1,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;

    DECLARE @dAhora DATETIME2(0) = SYSUTCDATETIME();
    DECLARE @Roles TABLE (rol_id BIGINT PRIMARY KEY);

    SELECT
        @bResultado = 0,
        @cMensaje = N'No se pudieron validar los roles seleccionados.';

    IF @nUsuarioActorId IS NULL
       OR @cRolesJson IS NULL
       OR ISJSON(@cRolesJson) <> 1
    BEGIN
        SET @cMensaje = N'No se pudieron validar los roles seleccionados.';
        GOTO __DESCO_Salida;
    END;

    INSERT INTO @Roles(rol_id)
    SELECT DISTINCT J.rolId
    FROM OPENJSON(@cRolesJson)
    WITH (rolId BIGINT '$.rolId') J
    WHERE J.rolId IS NOT NULL;

    IF @bRequerirAlMenosUno = 1
       AND NOT EXISTS (SELECT 1 FROM @Roles)
    BEGIN
        SET @cMensaje = N'Seleccione al menos un rol.';
        GOTO __DESCO_Salida;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM @Roles X
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM [seg].[Rol] R
            WHERE R.rol_id = X.rol_id
              AND R.estado = 1
        )
    )
    BEGIN
        SET @cMensaje = N'Uno o más roles seleccionados no están disponibles.';
        GOTO __DESCO_Salida;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM @Roles X
        INNER JOIN [seg].[RolPermiso] RPObjetivo
            ON RPObjetivo.rol_id = X.rol_id
           AND RPObjetivo.estado = 1
        INNER JOIN [seg].[Permiso] PObjetivo
            ON PObjetivo.permiso_id = RPObjetivo.permiso_id
           AND PObjetivo.estado = 1
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM [seg].[UsuarioRol] URActor
            INNER JOIN [seg].[Rol] RActor
                ON RActor.rol_id = URActor.rol_id
               AND RActor.estado = 1
            INNER JOIN [seg].[RolPermiso] RPActor
                ON RPActor.rol_id = URActor.rol_id
               AND RPActor.permiso_id = RPObjetivo.permiso_id
               AND RPActor.estado = 1
            INNER JOIN [seg].[Permiso] PActor
                ON PActor.permiso_id = RPActor.permiso_id
               AND PActor.estado = 1
            WHERE URActor.usuario_id = @nUsuarioActorId
              AND URActor.estado = 1
              AND URActor.fecha_desde <= @dAhora
              AND (URActor.fecha_hasta IS NULL OR URActor.fecha_hasta >= @dAhora)
        )
    )
    BEGIN
        SET @cMensaje = N'Solo puede asignar roles cuyos permisos ya están dentro de sus propios permisos vigentes.';
        GOTO __DESCO_Salida;
    END;

    SET @bResultado = 1;
    SET @cMensaje = N'Roles autorizados para delegación.';

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Autorizacion_Sel_ValidarDelegacionRoles',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Autorizacion_Sel_ValidarDelegacionRoles',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'seg.PA_Autorizacion_Sel_ValidarDelegacionRoles',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* --------------------------------------------------------------------------
   B. AUTORIZACION: roles locales por UOT. GENERAL agrega visibilidad, no roles.
   ADMINISTRADOR global conserva bypass administrativo.
   -------------------------------------------------------------------------- */
CREATE OR ALTER PROCEDURE seg.PA_Autorizacion_Sel_ValidarPermiso
(
    @nUsuarioId BIGINT,
    @gSesionPublicaId UNIQUEIDENTIFIER,
    @cCodigoPermiso VARCHAR(400),
    @bAutorizado BIT OUTPUT,
    @bResultado BIT=NULL OUTPUT,
    @cMensaje NVARCHAR(300)=NULL OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT @bAutorizado=0,@bResultado=0,@cMensaje=N'No tiene acceso a esta opcion.',@cCodigoRespuesta='ACCESO_DENEGADO',@nHttpRespuesta=403;
    SET @cCodigoPermiso=UPPER(NULLIF(LTRIM(RTRIM(@cCodigoPermiso)),''));
    IF @nUsuarioId IS NULL OR @gSesionPublicaId IS NULL OR @cCodigoPermiso IS NULL RETURN 1;

    DECLARE @Ahora DATETIME2(0)=SYSUTCDATETIME(),@Modo VARCHAR(12),@Uot BIGINT;
    SELECT TOP(1) @Modo=S.modo_uot,@Uot=S.uot_contexto_id
    FROM seg.SesionUsuario S
    JOIN seg.Usuario U ON U.usuario_id=S.usuario_id
    JOIN org.Persona P ON P.persona_id=U.persona_id
    WHERE S.sesion_publica_id=@gSesionPublicaId AND S.usuario_id=@nUsuarioId
      AND S.estado=1 AND S.fecha_revocacion IS NULL AND S.fecha_expiracion_renovacion>@Ahora
      AND S.token_version=U.token_version AND U.estado=1 AND U.estado_cuenta='ACTIVA'
      AND (U.bloqueado_hasta IS NULL OR U.bloqueado_hasta<=@Ahora) AND P.estado=1;
    IF @Modo IS NULL RETURN 1;

    DECLARE @Permisos TABLE(codigo VARCHAR(40) PRIMARY KEY);
    INSERT @Permisos(codigo)
    SELECT DISTINCT CONVERT(VARCHAR(40),UPPER(LTRIM(RTRIM(value))))
    FROM STRING_SPLIT(@cCodigoPermiso,'|') WHERE NULLIF(LTRIM(RTRIM(value)),'') IS NOT NULL;
    IF NOT EXISTS(SELECT 1 FROM @Permisos) RETURN 1;

    /* El superadministrador global puede administrar la plataforma. */
    IF EXISTS(
        SELECT 1 FROM seg.UsuarioRol UR
        JOIN seg.Rol R ON R.rol_id=UR.rol_id AND R.codigo='ADMINISTRADOR' AND R.estado=1
        JOIN seg.RolPermiso RP ON RP.rol_id=R.rol_id AND RP.estado=1
        JOIN seg.Permiso P ON P.permiso_id=RP.permiso_id AND P.estado=1
        JOIN @Permisos Q ON Q.codigo=P.codigo
        WHERE UR.usuario_id=@nUsuarioId AND UR.estado=1 AND UR.fecha_desde<=@Ahora
          AND (UR.fecha_hasta IS NULL OR UR.fecha_hasta>@Ahora)
    ) SET @bAutorizado=1;

    IF @bAutorizado=0 AND @Modo='ESPECIFICA' AND @Uot IS NOT NULL
       AND EXISTS(SELECT 1 FROM @Permisos Q WHERE seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@Uot,Q.codigo)=1)
        SET @bAutorizado=1;

    IF @bAutorizado=0 AND @Modo='GENERAL'
       AND EXISTS(
           SELECT 1 FROM seg.UsuarioUOT UU
           JOIN org.UOT O ON O.uot_id=UU.uot_id AND O.estado=1
           CROSS JOIN @Permisos Q
           WHERE UU.usuario_id=@nUsuarioId AND UU.estado=1 AND UU.fecha_hasta IS NULL AND UU.fecha_desde<=@Ahora
             AND seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,UU.uot_id,Q.codigo)=1
       ) SET @bAutorizado=1;

    IF @bAutorizado=1
    BEGIN
        SELECT @bResultado=1,@cMensaje=N'Acceso validado.',@cCodigoRespuesta='ACCESO_VALIDADO',@nHttpRespuesta=200;
        RETURN 0;
    END;
    RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* ===== seg.PA_Consulta_Sel_ResolverPaginacion ===== */
CREATE OR ALTER PROCEDURE [seg].[PA_Consulta_Sel_ResolverPaginacion]
(
    @cJson NVARCHAR(MAX),
    @nPagina INT OUTPUT,
    @nTamanoPagina INT OUTPUT,
    @nOffset BIGINT OUTPUT,
    @bResultado BIT=NULL OUTPUT,
    @cMensaje NVARCHAR(300)=NULL OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;

    SET @bResultado=0;
BEGIN TRY

    SET NOCOUNT ON;

    DECLARE
        @nPaginaP INT,
        @nTamanoP INT,
        @nPaginaF INT,
        @nTamanoF INT;

    SELECT
        @nPagina = 1,
        @nTamanoPagina = 20,
        @nOffset = 0;

    IF @cJson IS NOT NULL AND ISJSON(@cJson) = 1
    BEGIN
        SELECT
            @nPaginaP = pagina,
            @nTamanoP = COALESCE(tamanoPagina, tamano)
        FROM OPENJSON(@cJson, '$.paginacion')
        WITH
        (
            pagina INT '$.pagina',
            tamanoPagina INT '$.tamanoPagina',
            tamano INT '$.tamano'
        );

        SELECT
            @nPaginaF = pagina,
            @nTamanoF = COALESCE(tamanoPagina, tamano)
        FROM OPENJSON(@cJson, '$.filtros')
        WITH
        (
            pagina INT '$.pagina',
            tamanoPagina INT '$.tamanoPagina',
            tamano INT '$.tamano'
        );

        SET @nPagina = COALESCE(@nPaginaP, @nPaginaF, 1);
        SET @nTamanoPagina = COALESCE(@nTamanoP, @nTamanoF, 20);
    END;

    IF @nPagina < 1 SET @nPagina = 1;
    IF @nTamanoPagina < 1 SET @nTamanoPagina = 20;
    IF @nTamanoPagina > 200 SET @nTamanoPagina = 200;

    SET @nOffset = (CONVERT(BIGINT, @nPagina) - 1) * CONVERT(BIGINT, @nTamanoPagina);

