    DECLARE @gClaveIdempotencia UNIQUEIDENTIFIER;
    DECLARE @cRequestHashHex VARCHAR(128);
    DECLARE @bContexto BIT = 0;
    DECLARE @cMensajeContexto NVARCHAR(300);

    SELECT
        @nOperacionIdempotenteId = NULL,
        @bEsRepetida = 0,
