CREATE OR ALTER PROCEDURE [seg].[PA_PoliticaSeguridad_Sel_Administracion]
(
    @cJson NVARCHAR(MAX),
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
    SET @bResultado=0;
    SET @cMensaje=N'No se pudo consultar la política de seguridad.';
    SET @cCodigoRespuesta=NULL;
    SET @nHttpRespuesta=NULL;

    DECLARE
        @nUsuarioId BIGINT,
        @nSesionUsuarioId BIGINT,
        @nDispositivoUsuarioId BIGINT,
        @nEmpleadoId BIGINT,
        @nModuloId INT,
        @gCorrelacionId UNIQUEIDENTIFIER,
        @gSolicitudId UNIQUEIDENTIFIER,
        @cIp VARCHAR(64),
        @cEndpoint NVARCHAR(250),
        @bContexto BIT,
        @cMensajeContexto NVARCHAR(300);

    BEGIN TRY
        IF @cJson IS NULL OR ISJSON(@cJson) <> 1
        BEGIN
            SET @cMensaje=N'La solicitud no es válida.';
            GOTO Salida;
        END;

        EXEC [seg].[PA_Operacion_Sel_ContextoAutorizado]
             @cJson=@cJson,
             @cCodigoPermiso='USUARIOS_ADMINISTRAR',
             @nUsuarioId=@nUsuarioId OUTPUT,
             @nSesionUsuarioId=@nSesionUsuarioId OUTPUT,
             @nDispositivoUsuarioId=@nDispositivoUsuarioId OUTPUT,
             @nEmpleadoId=@nEmpleadoId OUTPUT,
             @nModuloId=@nModuloId OUTPUT,
             @gCorrelacionId=@gCorrelacionId OUTPUT,
             @gSolicitudId=@gSolicitudId OUTPUT,
             @cIp=@cIp OUTPUT,
             @cEndpoint=@cEndpoint OUTPUT,
             @bResultado=@bContexto OUTPUT,
             @cMensaje=@cMensajeContexto OUTPUT;

        IF ISNULL(@bContexto,0)=0
        BEGIN
            SET @cMensaje=COALESCE(@cMensajeContexto,N'No tiene autorización para consultar esta configuración.');
            GOTO Salida;
        END;

        IF NOT EXISTS
        (
            SELECT 1
            FROM [seg].[PoliticaSeguridad]
            WHERE codigo='GENERAL'
              AND estado=1
              AND fecha_hasta IS NULL
              AND fecha_desde<=SYSUTCDATETIME()
        )
        BEGIN
            SET @cMensaje=N'La política de seguridad no está disponible.';
            GOTO Salida;
        END;

        SELECT TOP (1)
            PS.dias_dispositivo_reconocido AS diasDispositivoReconocido
        FROM [seg].[PoliticaSeguridad] PS
        WHERE PS.codigo='GENERAL'
          AND PS.estado=1
          AND PS.fecha_hasta IS NULL
          AND PS.fecha_desde<=SYSUTCDATETIME()
        ORDER BY PS.fecha_desde DESC, PS.politica_seguridad_id DESC;

        SET @bResultado=1;
        SET @cMensaje=N'Política de seguridad consultada.';
    END TRY
    BEGIN CATCH
        SET @bResultado=0;
        EXEC [config].[PA_Respuesta_ResolverError]
             @cProcedimiento=N'seg.PA_PoliticaSeguridad_Sel_Administracion',
             @cMensaje=@cMensaje OUTPUT,
             @cJson=@cJson,
             @bMensajePublicoGenerico=0;
    END CATCH;

Salida:
    SET @bResultado=ISNULL(@bResultado,0);
    SELECT
        @cMensaje=R.mensaje,
        @cCodigoRespuesta=R.codigo,
        @nHttpRespuesta=R.http_sugerido
    FROM config.FN_RespuestaUsuario(
        N'seg.PA_PoliticaSeguridad_Sel_Administracion',
        @bResultado,
        @cMensaje
    ) R;

    IF @bResultado=1 RETURN 0;
    RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [seg].[PA_PoliticaSeguridad_Upd_DispositivoReconocido]
(
    @cJson NVARCHAR(MAX),
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    SET @bResultado=0;
    SET @cMensaje=N'No se pudo actualizar la política de seguridad.';
    SET @cCodigoRespuesta=NULL;
    SET @nHttpRespuesta=NULL;

    DECLARE
        @nUsuarioId BIGINT,
        @nSesionUsuarioId BIGINT,
        @nDispositivoUsuarioId BIGINT,
        @nEmpleadoId BIGINT,
        @nModuloId INT,
        @gCorrelacionId UNIQUEIDENTIFIER,
        @gSolicitudId UNIQUEIDENTIFIER,
        @cIp VARCHAR(64),
        @cEndpoint NVARCHAR(250),
        @nOperacionIdempotenteId BIGINT,
        @bEsRepetida BIT,
        @cEstadoOperacion VARCHAR(20),
        @cIdentificadorResultado NVARCHAR(200),
        @cCodigoResultado VARCHAR(40),
        @bInicio BIT,
        @cMensajeInicio NVARCHAR(300),
        @bFin BIT,
        @cMensajeFin NVARCHAR(300),
        @nDias SMALLINT,
        @nDiasAnteriores SMALLINT,
        @nAuditoriaId BIGINT,
        @cAntes NVARCHAR(MAX),
        @cDespues NVARCHAR(MAX),
        @dAhora DATETIME2(0)=SYSUTCDATETIME(),
        @nTranEntrada INT=@@TRANCOUNT,
        @cSavepoint VARCHAR(32)=REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
        @bTranAbierta BIT=0;

    BEGIN TRY
        IF @cJson IS NULL OR ISJSON(@cJson) <> 1
        BEGIN
            SET @cMensaje=N'La solicitud no es válida.';
            GOTO Salida;
        END;

        EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente]
             @cJson=@cJson,
             @cCodigoPermiso='USUARIOS_ADMINISTRAR',
             @cAmbito='POLITICA_SEGURIDAD_DISPOSITIVO',
             @nUsuarioId=@nUsuarioId OUTPUT,
             @nSesionUsuarioId=@nSesionUsuarioId OUTPUT,
             @nDispositivoUsuarioId=@nDispositivoUsuarioId OUTPUT,
             @nEmpleadoId=@nEmpleadoId OUTPUT,
             @nModuloId=@nModuloId OUTPUT,
             @gCorrelacionId=@gCorrelacionId OUTPUT,
             @gSolicitudId=@gSolicitudId OUTPUT,
             @cIp=@cIp OUTPUT,
             @cEndpoint=@cEndpoint OUTPUT,
             @nOperacionIdempotenteId=@nOperacionIdempotenteId OUTPUT,
             @bEsRepetida=@bEsRepetida OUTPUT,
             @cEstadoOperacion=@cEstadoOperacion OUTPUT,
             @cIdentificadorResultado=@cIdentificadorResultado OUTPUT,
             @cCodigoResultado=@cCodigoResultado OUTPUT,
             @bResultado=@bInicio OUTPUT,
             @cMensaje=@cMensajeInicio OUTPUT;

        IF ISNULL(@bInicio,0)=0 AND ISNULL(@bEsRepetida,0)=0
        BEGIN
            SET @cMensaje=@cMensajeInicio;
            GOTO Salida;
        END;

        IF ISNULL(@bEsRepetida,0)=1
        BEGIN
            SET @bResultado=CASE WHEN @cEstadoOperacion='COMPLETADA' THEN 1 ELSE 0 END;
            SET @cMensaje=CASE
                WHEN @cEstadoOperacion='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.'
                ELSE N'La solicitud ya se encuentra en proceso.'
            END;
            GOTO Salida;
        END;

        SELECT @nDias=diasDispositivoReconocido
        FROM OPENJSON(@cJson)
        WITH (diasDispositivoReconocido SMALLINT '$.diasDispositivoReconocido');

        IF @nDias IS NULL OR @nDias<1 OR @nDias>365
        BEGIN
            SET @cMensaje=N'La vigencia debe estar entre 1 y 365 días.';
            GOTO Fallar;
        END;

        IF @nTranEntrada=0 BEGIN TRANSACTION;
        ELSE SAVE TRANSACTION @cSavepoint;
        SET @bTranAbierta=1;

        SELECT TOP (1)
            @nDiasAnteriores=PS.dias_dispositivo_reconocido
        FROM [seg].[PoliticaSeguridad] PS WITH (UPDLOCK,HOLDLOCK)
        WHERE PS.codigo='GENERAL'
          AND PS.estado=1
          AND PS.fecha_hasta IS NULL
          AND PS.fecha_desde<=@dAhora
        ORDER BY PS.fecha_desde DESC, PS.politica_seguridad_id DESC;

        IF @nDiasAnteriores IS NULL
            THROW 51020,N'POLITICA_SEGURIDAD_NO_DISPONIBLE',1;

        UPDATE [seg].[PoliticaSeguridad]
        SET dias_dispositivo_reconocido=@nDias
        WHERE codigo='GENERAL'
          AND estado=1
          AND fecha_hasta IS NULL
          AND fecha_desde<=@dAhora;

        /* El historial del dispositivo se conserva; solo caduca la confianza. */
        UPDATE D
        SET
            D.es_reconocido=0,
            D.fecha_retiro_reconocimiento=COALESCE(D.fecha_retiro_reconocimiento,@dAhora)
        FROM [seg].[DispositivoUsuario] D
        WHERE D.estado=1
          AND D.es_reconocido=1
          AND D.fecha_reconocimiento IS NOT NULL
          AND DATEADD(DAY,@nDias,D.fecha_reconocimiento)<=@dAhora;

        SELECT @cAntes=(SELECT @nDiasAnteriores AS diasDispositivoReconocido FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
        SELECT @cDespues=(SELECT @nDias AS diasDispositivoReconocido FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);

        EXEC [auditoria].[PA_Auditoria_Ins_Evento]
             @nUsuarioId=@nUsuarioId,
             @nSesionUsuarioId=@nSesionUsuarioId,
             @nDispositivoUsuarioId=@nDispositivoUsuarioId,
             @nModuloId=@nModuloId,
             @cAccion='EDITAR',
             @cEsquemaEntidad=N'seg',
             @cNombreEntidad=N'PoliticaSeguridad',
             @cIdentificador=N'GENERAL',
             @cDatosAnteriores=@cAntes,
             @cDatosPosteriores=@cDespues,
             @cMotivo=N'Actualización de vigencia de dispositivos reconocidos.',
             @cIp=@cIp,
             @cResultado='EXITOSO',
             @gCorrelacionId=@gCorrelacionId,
             @gSolicitudId=@gSolicitudId,
             @cEndpoint=@cEndpoint,
             @nAuditoriaEventoId=@nAuditoriaId OUTPUT;

        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
             @nOperacionIdempotenteId=@nOperacionIdempotenteId,
             @cEstadoOperacion='COMPLETADA',
             @cEsquemaEntidad='seg',
             @cNombreEntidad='PoliticaSeguridad',
             @cIdentificadorResultado='GENERAL',
             @cCodigoResultado='POLITICA_SEGURIDAD_ACTUALIZADA',
             @bResultado=@bFin OUTPUT,
             @cMensaje=@cMensajeFin OUTPUT;

        IF ISNULL(@bFin,0)=0
            THROW 51003,N'DESCO_IDEMPOTENCIA_NO_CERRADA',1;

        IF @bTranAbierta=1 AND @nTranEntrada=0 COMMIT TRANSACTION;
        SET @bTranAbierta=0;

        SET @bResultado=1;
        SET @cMensaje=N'Política de seguridad actualizada.';
        GOTO Salida;

Fallar:
        IF @nOperacionIdempotenteId IS NOT NULL
        BEGIN
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
                 @nOperacionIdempotenteId=@nOperacionIdempotenteId,
                 @cEstadoOperacion='FALLIDA',
                 @cEsquemaEntidad=NULL,
                 @cNombreEntidad=NULL,
                 @cIdentificadorResultado=NULL,
                 @cCodigoResultado='NO_PROCESADO',
                 @bResultado=@bFin OUTPUT,
                 @cMensaje=@cMensajeFin OUTPUT;
        END;
    END TRY
    BEGIN CATCH
        IF @bTranAbierta=1 AND XACT_STATE()<>0
        BEGIN
            IF @nTranEntrada=0 ROLLBACK TRANSACTION;
            ELSE IF XACT_STATE()=1 ROLLBACK TRANSACTION @cSavepoint;
        END;
        SET @bTranAbierta=0;
        SET @bResultado=0;

        IF @nOperacionIdempotenteId IS NOT NULL AND ISNULL(@bEsRepetida,0)=0 AND XACT_STATE()<>-1
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
                 @nOperacionIdempotenteId=@nOperacionIdempotenteId,
                 @cEstadoOperacion='FALLIDA',
                 @cEsquemaEntidad=NULL,
                 @cNombreEntidad=NULL,
                 @cIdentificadorResultado=NULL,
                 @cCodigoResultado='NO_PROCESADO',
                 @bResultado=@bFin OUTPUT,
                 @cMensaje=@cMensajeFin OUTPUT;
        END TRY
        BEGIN CATCH
        END CATCH;

        EXEC [config].[PA_Respuesta_ResolverError]
             @cProcedimiento=N'seg.PA_PoliticaSeguridad_Upd_DispositivoReconocido',
             @cMensaje=@cMensaje OUTPUT,
             @cJson=@cJson,
             @bMensajePublicoGenerico=0;
    END CATCH;

Salida:
    SET @bResultado=ISNULL(@bResultado,0);
    SELECT
        @cMensaje=R.mensaje,
        @cCodigoRespuesta=R.codigo,
        @nHttpRespuesta=R.http_sugerido
    FROM config.FN_RespuestaUsuario(
        N'seg.PA_PoliticaSeguridad_Upd_DispositivoReconocido',
        @bResultado,
        @cMensaje
    ) R;

    IF @bResultado=1 RETURN 0;
    RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- seg.PA_Rol_Ins_Registro
CREATE OR ALTER PROCEDURE [seg].[PA_Rol_Ins_Registro](@cJson NVARCHAR(MAX),@nRolId BIGINT OUTPUT,@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY
  SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),@nAud BIGINT,@nTrans BIGINT,@cCodigo VARCHAR(40),@cNombre NVARCHAR(100),@cDesc NVARCHAR(200),@b2FA BIT,@cIdent NVARCHAR(200);
SELECT @bResultado=0,@cMensaje=N'No se pudo crear el rol.';
EXEC seg.PA_Operacion_Ins_IniciarIdempotente @cJson=@cJson,@cCodigoPermiso='ROLESPERMISOS_CREAR',@cAmbito='ROL_CREAR',@nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@nOperacionIdempotenteId=@nOp OUTPUT,@bEsRepetida=@bRep OUTPUT,@cEstadoOperacion=@cEstadoOp OUTPUT,@cIdentificadorResultado=@cIdRes OUTPUT,@cCodigoResultado=@cCodRes OUTPUT,@bResultado=@bIni OUTPUT,@cMensaje=@cMsg OUTPUT;
IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
GOTO __DESCO_Salida;
END;
IF @bRep=1 BEGIN SET @nRolId=CASE WHEN @cEstadoOp='COMPLETADA' THEN TRY_CONVERT(BIGINT,@cIdRes) ELSE NULL END;
 SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
SET @cMensaje=CASE WHEN @cEstadoOp='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.' ELSE N'La solicitud ya se encuentra en proceso.' END;
GOTO __DESCO_Salida;
END;
 SET @nRolId=NULL;
SELECT @cCodigo=UPPER(NULLIF(LTRIM(RTRIM(codigo)),'')),@cNombre=NULLIF(LTRIM(RTRIM(nombre)),N''),@cDesc=NULLIF(LTRIM(RTRIM(descripcion)),N''),@b2FA=COALESCE(requiereSegundoFactor,CONVERT(BIT,0)) FROM OPENJSON(@cJson,'$.rol') WITH(codigo VARCHAR(40) '$.codigo',nombre NVARCHAR(100) '$.nombre',descripcion NVARCHAR(200) '$.descripcion',requiereSegundoFactor BIT '$.requiereSegundoFactor');
IF @cCodigo IS NULL OR @cNombre IS NULL OR EXISTS(SELECT 1 FROM seg.Rol WHERE codigo=@cCodigo) BEGIN SET @cMensaje=N'Complete correctamente los datos del rol o utilice otro código.';
GOTO Fallar;
END;
BEGIN TRY BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;
INSERT seg.Rol(codigo,nombre,descripcion,estado,requiere_segundo_factor,es_sistema) VALUES(@cCodigo,@cNombre,@cDesc,1,@b2FA,0);
SET @nRolId=SCOPE_IDENTITY();
SET @cIdent=CONVERT(NVARCHAR(200),@nRolId);
EXEC auditoria.PA_Operacion_Ins_RegistrarCambio @nUsuario,@nSesion,@nDisp,@nModulo,'CREAR','seg','Rol',@cIdent,NULL,NULL,NULL,NULL,NULL,NULL,@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
/* Confirmar datos e idempotencia juntos. */EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='COMPLETADA',@cEsquemaEntidad='seg',@cNombreEntidad='Rol',@cIdentificadorResultado=@cIdent,@cCodigoResultado='ROL_CREADO',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado=1;
SET @cMensaje=N'Rol creado correctamente.';
GOTO __DESCO_Salida;
 END TRY BEGIN CATCH
SET @bResultado = 0;
 IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @cMensaje=N'No se pudo crear el rol. Intente nuevamente.';
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Rol_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;
Fallar: IF @nOp IS NOT NULL AND @bResultado=0 EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='FALLIDA',@cEsquemaEntidad=NULL,@cNombreEntidad=NULL,@cIdentificadorResultado=NULL,@cCodigoResultado='NO_PROCESADO',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
 
    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Rol_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

    IF @bResultado = 0 AND @nOp IS NOT NULL AND XACT_STATE() <> -1
    BEGIN
        IF ISNULL(@bRep,0) = 0
        BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                 @nOperacionIdempotenteId = @nOp, @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
            -- No sustituir el motivo funcional por un fallo de registro secundario.
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Rol_Ins_Registro',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
        END CATCH;
        END
        ELSE
        BEGIN
            SELECT @cMensaje = COALESCE(mensaje_resultado,
                CASE WHEN estado_operacion = 'FALLIDA'
                     THEN N'La solicitud anterior no se completó. Corrija los datos y envíe una nueva solicitud.'
                     ELSE N'La solicitud todavía se está procesando. Consulte el resultado antes de repetirla.' END)
            FROM [auditoria].[OperacionIdempotente]
            WHERE operacion_idempotente_id = @nOp;
        END;
    END;
IF @bResultado = 0
    SELECT @nRolId = NULL;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Rol_Ins_Registro',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'seg.PA_Rol_Ins_Registro',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO


-- seg.PA_Rol_Sel_Detalle
CREATE OR ALTER PROCEDURE [seg].[PA_Rol_Sel_Detalle](@cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;

    BEGIN TRY
  SET NOCOUNT ON;
DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@bCtx BIT,@cMsg NVARCHAR(300);
SELECT @bResultado=0,@cMensaje=N'No se pudo consultar el rol.';
EXEC seg.PA_Operacion_Sel_ContextoAutorizado @cJson=@cJson,@cCodigoPermiso='ROLESPERMISOS_VER',@nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@bResultado=@bCtx OUTPUT,@cMensaje=@cMsg OUTPUT;
IF @bCtx=0 BEGIN SET @cMensaje=@cMsg;
GOTO __DESCO_Salida;
END;
 DECLARE @nRol BIGINT;
SELECT @nRol=COALESCE(TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.rol.rolId')),TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.rolId')),TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.filtros.rolId')));
IF NOT EXISTS(SELECT 1 FROM seg.Rol WHERE rol_id=@nRol) BEGIN SET @cMensaje=N'El rol seleccionado no está disponible.';
GOTO __DESCO_Salida;
END;
SELECT rol_id rolId,codigo,nombre,descripcion,requiere_segundo_factor requiereSegundoFactor,es_sistema esSistema,estado FROM seg.Rol WHERE rol_id=@nRol;
SELECT P.permiso_id permisoId,P.codigo,P.nombre,P.accion,P.es_sensible esSensible,P.requiere_motivo requiereMotivo,M.codigo moduloCodigo,M.nombre moduloNombre,RP.estado FROM seg.RolPermiso RP INNER JOIN seg.Permiso P ON P.permiso_id=RP.permiso_id INNER JOIN seg.Modulo M ON M.modulo_id=P.modulo_id WHERE RP.rol_id=@nRol ORDER BY M.orden,P.codigo;
SELECT U.usuario_id usuarioId,U.nombre_usuario nombreUsuario,P.numero_documento numeroDocumento,CONCAT(P.nombres,N' ',P.apellido_paterno,N' ',COALESCE(P.apellido_materno,N'')) empleado,UR.fecha_desde fechaDesde,UR.fecha_hasta fechaHasta,UR.estado FROM seg.UsuarioRol UR INNER JOIN seg.Usuario U ON U.usuario_id=UR.usuario_id INNER JOIN org.Persona P ON P.persona_id=U.persona_id WHERE UR.rol_id=@nRol ORDER BY empleado;
SET @bResultado=1;
SET @cMensaje=N'Rol consultado correctamente.';
    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Rol_Sel_Detalle',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Rol_Sel_Detalle',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'seg.PA_Rol_Sel_Detalle',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;


GO
