 SELECT @nRol=rolId,@cNombre=NULLIF(LTRIM(RTRIM(nombre)),N''),@cDesc=NULLIF(LTRIM(RTRIM(descripcion)),N''),@b2FA=COALESCE(requiereSegundoFactor,CONVERT(BIT,0)) FROM OPENJSON(@cJson,'$.rol') WITH(rolId BIGINT '$.rolId',nombre NVARCHAR(100) '$.nombre',descripcion NVARCHAR(200) '$.descripcion',requiereSegundoFactor BIT '$.requiereSegundoFactor');
IF NOT EXISTS(SELECT 1 FROM seg.Rol WHERE rol_id=@nRol AND estado=1 AND es_sistema=0) OR @cNombre IS NULL BEGIN SET @cMensaje=N'El rol seleccionado no puede modificarse desde esta opción.';
GOTO Fallar;
END;
BEGIN TRY BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
