-- seg.PA_RolPermiso_Upd_Asignaciones
CREATE OR ALTER PROCEDURE [seg].[PA_RolPermiso_Upd_Asignaciones](@cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY
  SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),@bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),@nAud BIGINT,@nTrans BIGINT,@nRol BIGINT,@cMotivo NVARCHAR(300),@cIdent NVARCHAR(200);
SELECT @bResultado=0,@cMensaje=N'No se pudieron actualizar los permisos del rol.';
EXEC seg.PA_Operacion_Ins_IniciarIdempotente @cJson=@cJson,@cCodigoPermiso='ROLESPERMISOS_CREAR',@cAmbito='ROL_PERMISOS',@nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@nOperacionIdempotenteId=@nOp OUTPUT,@bEsRepetida=@bRep OUTPUT,@cEstadoOperacion=@cEstadoOp OUTPUT,@cIdentificadorResultado=@cIdRes OUTPUT,@cCodigoResultado=@cCodRes OUTPUT,@bResultado=@bIni OUTPUT,@cMensaje=@cMsg OUTPUT;
IF @bIni=0 AND @bRep=0 BEGIN SET @cMensaje=@cMsg;
GOTO __DESCO_Salida;
END;
IF @bRep=1 BEGIN SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
SET @cMensaje=CASE WHEN @cEstadoOp='COMPLETADA' THEN N'La solicitud ya fue procesada correctamente.' ELSE N'La solicitud ya se encuentra en proceso.' END;
GOTO __DESCO_Salida;
END;
 SELECT @nRol=rolId,@cMotivo=NULLIF(LTRIM(RTRIM(motivo)),N'') FROM OPENJSON(@cJson,'$.rol') WITH(rolId BIGINT '$.rolId',motivo NVARCHAR(300) '$.motivo');
IF NOT EXISTS(SELECT 1 FROM seg.Rol WHERE rol_id=@nRol AND estado=1 AND es_sistema=0) BEGIN SET @cMensaje=N'El rol seleccionado no permite modificar sus permisos desde esta opción.';
GOTO Fallar;
END;
IF EXISTS(SELECT 1 FROM OPENJSON(@cJson,'$.permisos') WITH(permisoId BIGINT '$.permisoId') J WHERE NOT EXISTS(SELECT 1 FROM seg.Permiso P WHERE P.permiso_id=J.permisoId AND P.estado=1) OR NOT EXISTS(SELECT 1 FROM seg.UsuarioRol UR INNER JOIN seg.RolPermiso RP ON RP.rol_id=UR.rol_id AND RP.permiso_id=J.permisoId AND RP.estado=1 WHERE UR.usuario_id=@nUsuario AND UR.estado=1 AND UR.fecha_desde<=SYSUTCDATETIME() AND (UR.fecha_hasta IS NULL OR UR.fecha_hasta>=SYSUTCDATETIME()))) BEGIN SET @cMensaje=N'Solo puede asignar permisos que usted mismo tiene autorizados.';
GOTO Fallar;
END;
BEGIN TRY BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;
UPDATE seg.RolPermiso SET estado=0,fecha_retiro=SYSUTCDATETIME(),retirado_por_usuario_id=@nUsuario,motivo_retiro=COALESCE(@cMotivo,N'Actualización de permisos del rol.') WHERE rol_id=@nRol AND estado=1 AND permiso_id NOT IN(SELECT permisoId FROM OPENJSON(@cJson,'$.permisos') WITH(permisoId BIGINT '$.permisoId'));
MERGE seg.RolPermiso T USING(SELECT DISTINCT permisoId FROM OPENJSON(@cJson,'$.permisos') WITH(permisoId BIGINT '$.permisoId')) S ON T.rol_id=@nRol AND T.permiso_id=S.permisoId WHEN MATCHED THEN UPDATE SET estado=1,fecha_retiro=NULL,retirado_por_usuario_id=NULL,motivo_retiro=NULL,fecha_asignacion=COALESCE(T.fecha_asignacion,SYSUTCDATETIME()),asignado_por_usuario_id=COALESCE(T.asignado_por_usuario_id,@nUsuario) WHEN NOT MATCHED THEN INSERT(rol_id,permiso_id,estado,fecha_asignacion,asignado_por_usuario_id) VALUES(@nRol,S.permisoId,1,SYSUTCDATETIME(),@nUsuario);
SET @cIdent=CONVERT(NVARCHAR(200),@nRol);
EXEC auditoria.PA_Operacion_Ins_RegistrarCambio @nUsuario,@nSesion,@nDisp,@nModulo,'ASIGNAR_PERMISOS','seg','Rol',@cIdent,NULL,NULL,@cMotivo,NULL,NULL,NULL,@cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;
/* Confirmar datos e idempotencia juntos. */EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='COMPLETADA',@cEsquemaEntidad='seg',@cNombreEntidad='Rol',@cIdentificadorResultado=@cIdent,@cCodigoResultado='ROL_PERMISOS_ACTUALIZADOS',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado=1;
SET @cMensaje=N'Permisos del rol actualizados correctamente.';
GOTO __DESCO_Salida;
 END TRY BEGIN CATCH
SET @bResultado = 0;
 IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @cMensaje=N'No se pudieron actualizar los permisos. Intente nuevamente.';
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_RolPermiso_Upd_Asignaciones',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;
Fallar: IF @nOp IS NOT NULL AND @bResultado=0 EXEC auditoria.PA_OperacionIdempotente_Upd_Finalizar @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='FALLIDA',@cEsquemaEntidad=NULL,@cNombreEntidad=NULL,@cIdentificadorResultado=NULL,@cCodigoResultado='NO_PROCESADO',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
 
    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_RolPermiso_Upd_Asignaciones',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

    IF @bResultado = 0 AND @nOp IS NOT NULL AND XACT_STATE() <> -1
    BEGIN
        IF ISNULL(@bRep,0) = 0
        BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                 @nOperacionIdempotenteId = @nOp, @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
            -- No sustituir el motivo funcional por un fallo de registro secundario.
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_RolPermiso_Upd_Asignaciones',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
        END CATCH;
        END
        ELSE
        BEGIN
            SELECT @cMensaje = COALESCE(mensaje_resultado,
                CASE WHEN estado_operacion = 'FALLIDA'
                     THEN N'La solicitud anterior no se completó. Corrija los datos y envíe una nueva solicitud.'
                     ELSE N'La solicitud todavía se está procesando. Consulte el resultado antes de repetirla.' END)
            FROM [auditoria].[OperacionIdempotente]
            WHERE operacion_idempotente_id = @nOp;
        END;
    END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_RolPermiso_Upd_Asignaciones',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'seg.PA_RolPermiso_Upd_Asignaciones',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- seg.PA_Seguridad_Ins_CodigoUnSoloUso
CREATE OR ALTER PROCEDURE [seg].[PA_Seguridad_Ins_CodigoUnSoloUso]
(
    @nUsuarioId                   BIGINT,
    @cProposito                   VARCHAR(35),
    @binCodigoHmac                VARBINARY(64),
    @nDispositivoUsuarioId        BIGINT = NULL,
    @nUsuarioCorreoSeguridadId    BIGINT = NULL,
    @cIp                          VARCHAR(64) = NULL,
    @gCorrelacionId               UNIQUEIDENTIFIER = NULL,
    @nCodigoUnSoloUsoId           BIGINT OUTPUT,
    @nNotificacionSeguridadId     BIGINT OUTPUT,
    @cCorreoDestino               NVARCHAR(320) OUTPUT,
    @bDebeEnviar                  BIT OUTPUT,
    @bResultado                   BIT OUTPUT,
    @cMensaje                     NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY
BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

    /* DESCO_SEGURIDAD_V2_20260825 */
    SET NOCOUNT ON;

    DECLARE
        @dAhora DATETIME2(0) = SYSUTCDATETIME(),
        @nMaxIntentos SMALLINT,
        @nSegundosReenvio SMALLINT,
        @nMinutosExpiracion SMALLINT,
        @dUltimaCreacion DATETIME2(0),
        @nCorreoId BIGINT,
        @bCorreoVerificado BIT,
        @nAuditoriaId BIGINT;

    SET @nCodigoUnSoloUsoId = NULL;
    SET @nNotificacionSeguridadId = NULL;
    SET @cCorreoDestino = NULL;
    SET @bDebeEnviar = 0;
    SET @bResultado = 0;
    SET @cMensaje = N'No se pudo generar el codigo de seguridad.';

    SET @cProposito = UPPER(NULLIF(LTRIM(RTRIM(@cProposito)), ''));
    IF @gCorrelacionId IS NULL SET @gCorrelacionId = NEWID();

    IF @nUsuarioId IS NULL
       OR @binCodigoHmac IS NULL
       OR @cProposito NOT IN
          ('VALIDACION_CORREO','RECUPERACION_PASSWORD','SEGUNDO_FACTOR','CAMBIO_CORREO')
    BEGIN
        SET @cMensaje = N'La solicitud no es valida.';
        GOTO __DESCO_Salida;
    END;

    SELECT TOP (1)
        @nMaxIntentos = PS.max_intentos_codigo,
        @nSegundosReenvio = PS.segundos_minimos_reenvio,
        @nMinutosExpiracion =
            CASE @cProposito
                WHEN 'VALIDACION_CORREO' THEN PS.minutos_expiracion_validacion
                WHEN 'RECUPERACION_PASSWORD' THEN PS.minutos_expiracion_recuperacion
                WHEN 'SEGUNDO_FACTOR' THEN PS.minutos_expiracion_segundo_factor
                WHEN 'CAMBIO_CORREO' THEN PS.minutos_expiracion_validacion
            END
    FROM [seg].[PoliticaSeguridad] PS
    WHERE PS.codigo = 'GENERAL'
      AND PS.estado = 1
      AND PS.fecha_hasta IS NULL
      AND PS.fecha_desde <= @dAhora
    ORDER BY PS.fecha_desde DESC;

    IF @nMaxIntentos IS NULL
    BEGIN
        SET @cMensaje = N'La politica de seguridad no esta disponible.';
        GOTO __DESCO_Salida;
    END;

    IF @cProposito = 'CAMBIO_CORREO'
       AND @nUsuarioCorreoSeguridadId IS NOT NULL
    BEGIN
        SELECT
            @nCorreoId = UCS.usuario_correo_seguridad_id,
            @cCorreoDestino = UCS.correo,
            @bCorreoVerificado = UCS.es_verificado
        FROM [seg].[UsuarioCorreoSeguridad] UCS
        WHERE UCS.usuario_correo_seguridad_id = @nUsuarioCorreoSeguridadId
          AND UCS.usuario_id = @nUsuarioId
          AND UCS.estado = 1;
    END
    ELSE
    BEGIN
        SELECT TOP (1)
            @nCorreoId = UCS.usuario_correo_seguridad_id,
            @cCorreoDestino = UCS.correo,
            @bCorreoVerificado = UCS.es_verificado
        FROM [seg].[UsuarioCorreoSeguridad] UCS
        WHERE UCS.usuario_id = @nUsuarioId
          AND UCS.estado = 1
          AND UCS.es_principal = 1
          AND UCS.fecha_hasta IS NULL
        ORDER BY UCS.fecha_desde DESC;
    END;

    IF @nCorreoId IS NULL OR @cCorreoDestino IS NULL
    BEGIN
        SET @cMensaje = N'No hay un correo de seguridad disponible.';
        GOTO __DESCO_Salida;
    END;

    IF @cProposito IN ('RECUPERACION_PASSWORD','SEGUNDO_FACTOR')
       AND ISNULL(@bCorreoVerificado, 0) = 0
    BEGIN
        SET @cMensaje = N'El correo de seguridad aun no ha sido validado.';
        GOTO __DESCO_Salida;
    END;

    SELECT TOP (1)
        @dUltimaCreacion = C.fecha_creacion
    FROM [seg].[CodigoUnSoloUso] C WITH (UPDLOCK, HOLDLOCK)
    WHERE C.usuario_id = @nUsuarioId
      AND C.proposito = @cProposito
      AND C.estado = 1
      AND C.fecha_uso IS NULL
      AND C.fecha_invalidacion IS NULL
    ORDER BY C.fecha_creacion DESC, C.codigo_un_solo_uso_id DESC;

    IF @dUltimaCreacion IS NOT NULL
       AND DATEDIFF(SECOND, @dUltimaCreacion, @dAhora) < @nSegundosReenvio
    BEGIN
        SET @cMensaje = N'Espere unos segundos antes de solicitar un nuevo codigo.';
        GOTO __DESCO_Salida;
    END;

    /* Solicitar uno nuevo invalida todos los anteriores del mismo proposito. */
    UPDATE [seg].[CodigoUnSoloUso]
    SET
        fecha_invalidacion = COALESCE(fecha_invalidacion, @dAhora),
        estado = 0
    WHERE usuario_id = @nUsuarioId
      AND proposito = @cProposito
      AND estado = 1
      AND fecha_uso IS NULL
      AND fecha_invalidacion IS NULL;

    INSERT INTO [seg].[CodigoUnSoloUso]
    (
        usuario_id,
        usuario_correo_seguridad_id,
        dispositivo_usuario_id,
        proposito,
        canal,
        codigo_hmac,
        correo_destino,
        fecha_creacion,
        fecha_expiracion,
        intentos_fallidos,
        maximo_intentos,
        ip_solicitud,
        grupo_solicitud,
        estado
    )
    VALUES
    (
        @nUsuarioId,
        @nCorreoId,
        @nDispositivoUsuarioId,
        @cProposito,
        'EMAIL',
        @binCodigoHmac,
        @cCorreoDestino,
        @dAhora,
        DATEADD(MINUTE, @nMinutosExpiracion, @dAhora),
        0,
        @nMaxIntentos,
        NULLIF(LTRIM(RTRIM(@cIp)), ''),
        @gCorrelacionId,
        1
    );

    SET @nCodigoUnSoloUsoId = CONVERT(BIGINT, SCOPE_IDENTITY());

    EXEC [seg].[PA_Seguridad_Ins_Notificacion]
         @nUsuarioId = @nUsuarioId,
         @cTipoNotificacion = @cProposito,
         @cCorreoDestino = @cCorreoDestino,
         @cMetadata = NULL,
         @gCorrelacionId = @gCorrelacionId,
         @nNotificacionSeguridadId = @nNotificacionSeguridadId OUTPUT;

    /*
       Se audita la EMISION, nunca el HMAC ni el OTP. El PA de auditoria
       elimina defensivamente cualquier payload de CodigoUnSoloUso.
    */
    EXEC [auditoria].[PA_Auditoria_Ins_Evento]
         @nUsuarioId = @nUsuarioId,
         @nDispositivoUsuarioId = @nDispositivoUsuarioId,
         @cAccion = 'EMITIR_CODIGO_SEGURIDAD',
         @cEsquemaEntidad = N'seg',
         @cNombreEntidad = N'CodigoUnSoloUso',
         @cIdentificador = @nCodigoUnSoloUsoId,
         @cMotivo = @cProposito,
         @cIp = @cIp,
         @cResultado = 'EXITOSO',
         @gCorrelacionId = @gCorrelacionId,
         @nAuditoriaEventoId = @nAuditoriaId OUTPUT;

    SET @bDebeEnviar = 1;
    SET @bResultado = 1;
    SET @cMensaje = N'Codigo de seguridad generado correctamente.';

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Seguridad_Ins_CodigoUnSoloUso',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
    IF @__DbError = 0 AND @bResultado = 1 AND XACT_STATE() = 1
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
    ELSE
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Seguridad_Ins_CodigoUnSoloUso',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
IF ISNULL(@bResultado,0) = 0 SELECT @nCodigoUnSoloUsoId=NULL, @nNotificacionSeguridadId=NULL;
IF ISNULL(@bResultado,0) = 0 SELECT @bDebeEnviar=0,@cCorreoDestino=NULL;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'seg.PA_Seguridad_Ins_CodigoUnSoloUso',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [seg].[PA_Seguridad_Ins_CrearSesionInterna]
(
    @nUsuarioId                   BIGINT,
    @binDispositivoHash           VARBINARY(64),
    @cNavegador                   NVARCHAR(120) = NULL,
    @cSistemaOperativo            NVARCHAR(120) = NULL,
    @cUserAgent                   NVARCHAR(600) = NULL,
    @cIp                          VARCHAR(64) = NULL,
    @binRefreshTokenHash          VARBINARY(64),
    @bSegundoFactorValidado       BIT = 0,
    @gCorrelacionId               UNIQUEIDENTIFIER = NULL,
    @nSesionUsuarioId             BIGINT OUTPUT,
    @gSesionPublicaId             UNIQUEIDENTIFIER OUTPUT,
    @nDispositivoUsuarioId        BIGINT OUTPUT,
    @dExpiracionRenovacion        DATETIME2(0) OUTPUT,
    @bNuevoDispositivo            BIT OUTPUT,
    @bResultado                   BIT OUTPUT,
    @cMensaje                     NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY
BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

    /* DESCO_SEGURIDAD_2FA_DISPOSITIVO_V3_20260904 */
    SET NOCOUNT ON;

    DECLARE
        @dAhora DATETIME2(0) = SYSUTCDATETIME(),
        @nDiasRefresh SMALLINT,
        @nDiasReconocido SMALLINT,
        @nTokenVersion INT,
        @cNombreUsuario VARCHAR(80),
        @binIdentificadorHash VARBINARY(64),
        @bRequiereSegundoFactor BIT = 0,
        @bDispositivoReconocidoVigente BIT = 0,
        @nAuditoriaId BIGINT,
        @bDispositivoExistia BIT = 0,
        @bDispositivoEstadoAnterior BIT = 0;

    SET @nSesionUsuarioId = NULL;
    SET @gSesionPublicaId = NULL;
    SET @nDispositivoUsuarioId = NULL;
    SET @dExpiracionRenovacion = NULL;
    SET @bNuevoDispositivo = 0;
    SET @bResultado = 0;
    SET @cMensaje = N'No se pudo iniciar la sesion.';

    IF @nUsuarioId IS NULL
       OR @binDispositivoHash IS NULL
       OR @binRefreshTokenHash IS NULL
    BEGIN
        SET @cMensaje = N'La solicitud no es valida.';
        GOTO __DESCO_Salida;
    END;

    SELECT
        @nTokenVersion = U.token_version,
        @cNombreUsuario = U.nombre_usuario,
        @bRequiereSegundoFactor =
            CASE
                WHEN U.segundo_factor_habilitado = 1 THEN 1
                WHEN EXISTS
                (
                    SELECT 1
                    FROM [seg].[UsuarioRol] UR
                    INNER JOIN [seg].[Rol] R
                        ON R.rol_id = UR.rol_id
                    WHERE UR.usuario_id = U.usuario_id
                      AND UR.estado = 1
                      AND UR.fecha_desde <= @dAhora
                      AND (UR.fecha_hasta IS NULL OR UR.fecha_hasta >= @dAhora)
                      AND R.estado = 1
                      AND R.requiere_segundo_factor = 1
                ) THEN 1
                ELSE 0
            END
    FROM [seg].[Usuario] U
    INNER JOIN [org].[Empleado] E
        ON E.empleado_id = U.persona_id
    INNER JOIN [org].[Persona] P
        ON P.persona_id = U.persona_id
    WHERE U.usuario_id = @nUsuarioId
      AND U.estado = 1
      AND U.estado_cuenta = 'ACTIVA'
      AND (U.bloqueado_hasta IS NULL OR U.bloqueado_hasta <= @dAhora)
      AND E.estado = 1
      AND P.estado = 1
      AND EXISTS
      (
          SELECT 1
          FROM [seg].[UsuarioCorreoSeguridad] UCS
          WHERE UCS.usuario_id = U.usuario_id
            AND UCS.estado = 1
            AND UCS.es_principal = 1
            AND UCS.es_verificado = 1
            AND UCS.fecha_hasta IS NULL
      );

    IF @nTokenVersion IS NULL
    BEGIN
        SET @cMensaje = N'La cuenta no esta disponible para iniciar sesion.';
        GOTO __DESCO_Salida;
    END;

    SELECT TOP (1)
        @nDiasRefresh = PS.dias_refresh_token,
        @nDiasReconocido = PS.dias_dispositivo_reconocido
    FROM [seg].[PoliticaSeguridad] PS
    WHERE PS.codigo = 'GENERAL'
      AND PS.estado = 1
      AND PS.fecha_hasta IS NULL
      AND PS.fecha_desde <= @dAhora
    ORDER BY PS.fecha_desde DESC;

    IF @nDiasRefresh IS NULL OR @nDiasReconocido IS NULL
    BEGIN
        SET @cMensaje = N'La politica de seguridad no esta disponible.';
        GOTO __DESCO_Salida;
    END;

    /*
       Resolver el dispositivo ANTES de exigir nuevamente 2FA.
       Este paso es imprescindible: el flujo anterior rechazaba la creacion
       de sesion por 2FA antes de consultar si el dispositivo ya era confiable.
    */
    SELECT
        @nDispositivoUsuarioId = D.dispositivo_usuario_id,
        @bDispositivoExistia = 1,
        @bDispositivoEstadoAnterior = D.estado,
        @bDispositivoReconocidoVigente =
            CASE
                WHEN D.estado = 1
                 AND D.es_reconocido = 1
                 AND D.fecha_reconocimiento IS NOT NULL
                 AND DATEADD(DAY, @nDiasReconocido, D.fecha_reconocimiento) > @dAhora
                    THEN 1
                ELSE 0
            END
    FROM [seg].[DispositivoUsuario] D WITH (UPDLOCK, HOLDLOCK)
    WHERE D.usuario_id = @nUsuarioId
      AND D.identificador_logico_hash = @binDispositivoHash;

    IF ISNULL(@bSegundoFactorValidado, 0) = 0
       AND
       (
           ISNULL(@bRequiereSegundoFactor, 0) = 1
           OR ISNULL(@bDispositivoReconocidoVigente, 0) = 0
       )
    BEGIN
        SET @cMensaje = N'Se requiere una verificacion adicional de seguridad.';
        GOTO __DESCO_Salida;
    END;

    IF @nDispositivoUsuarioId IS NULL
    BEGIN
        INSERT INTO [seg].[DispositivoUsuario]
        (
            usuario_id,
            identificador_logico_hash,
            navegador,
            sistema_operativo,
            user_agent,
            fecha_primera_deteccion,
            fecha_ultima_actividad,
            es_reconocido,
            fecha_reconocimiento,
            fecha_retiro_reconocimiento,
            ultima_ip,
            estado
        )
        VALUES
        (
            @nUsuarioId,
            @binDispositivoHash,
            NULLIF(LTRIM(RTRIM(@cNavegador)), ''),
            NULLIF(LTRIM(RTRIM(@cSistemaOperativo)), ''),
            @cUserAgent,
            @dAhora,
            @dAhora,
            CASE WHEN ISNULL(@bSegundoFactorValidado, 0) = 1 THEN 1 ELSE 0 END,
            CASE WHEN ISNULL(@bSegundoFactorValidado, 0) = 1 THEN @dAhora ELSE NULL END,
            NULL,
            NULLIF(LTRIM(RTRIM(@cIp)), ''),
            1
        );

        SET @nDispositivoUsuarioId = SCOPE_IDENTITY();
        SET @bNuevoDispositivo = 1;
    END
    ELSE
    BEGIN
        /*
           Si el reconocimiento expiro, se retira automaticamente.
        */
        UPDATE [seg].[DispositivoUsuario]
        SET
            navegador = COALESCE(NULLIF(LTRIM(RTRIM(@cNavegador)), ''), navegador),
            sistema_operativo = COALESCE(NULLIF(LTRIM(RTRIM(@cSistemaOperativo)), ''), sistema_operativo),
            user_agent = COALESCE(@cUserAgent, user_agent),
            fecha_ultima_actividad = @dAhora,
            ultima_ip = COALESCE(NULLIF(LTRIM(RTRIM(@cIp)), ''), ultima_ip),
            es_reconocido =
                CASE
                    WHEN ISNULL(@bSegundoFactorValidado, 0) = 1
                        THEN 1
                    WHEN es_reconocido = 1
                     AND fecha_reconocimiento IS NOT NULL
                     AND DATEADD(DAY, @nDiasReconocido, fecha_reconocimiento) <= @dAhora
                        THEN 0
                    ELSE es_reconocido
                END,
            fecha_reconocimiento =
                CASE
                    WHEN ISNULL(@bSegundoFactorValidado, 0) = 1
                        THEN @dAhora
                    ELSE fecha_reconocimiento
                END,
            fecha_retiro_reconocimiento =
                CASE
                    WHEN ISNULL(@bSegundoFactorValidado, 0) = 1
                        THEN NULL
                    WHEN es_reconocido = 1
                     AND fecha_reconocimiento IS NOT NULL
                     AND DATEADD(DAY, @nDiasReconocido, fecha_reconocimiento) <= @dAhora
                        THEN COALESCE(fecha_retiro_reconocimiento, @dAhora)
                    ELSE fecha_retiro_reconocimiento
                END,
            estado = 1
        WHERE dispositivo_usuario_id = @nDispositivoUsuarioId;

        /*
           El aviso NUEVO_DISPOSITIVO se reserva exclusivamente para una
           huella lógica que nunca estuvo registrada. Reactivar o renovar el
           reconocimiento de un dispositivo existente no genera ese correo.
        */
        SET @bNuevoDispositivo = 0;
    END;

    SET @gSesionPublicaId = NEWID();
    SET @dExpiracionRenovacion = DATEADD(DAY, @nDiasRefresh, @dAhora);

    INSERT INTO [seg].[SesionUsuario]
    (
        sesion_publica_id,
        usuario_id,
        dispositivo_usuario_id,
        token_version,
        fecha_creacion,
        fecha_ultima_actividad,
        fecha_expiracion_renovacion,
        ip_creacion,
        ip_ultima_actividad,
        estado
    )
    VALUES
    (
        @gSesionPublicaId,
        @nUsuarioId,
        @nDispositivoUsuarioId,
        @nTokenVersion,
        @dAhora,
        @dAhora,
        @dExpiracionRenovacion,
        NULLIF(LTRIM(RTRIM(@cIp)), ''),
        NULLIF(LTRIM(RTRIM(@cIp)), ''),
        1
    );

    SET @nSesionUsuarioId = SCOPE_IDENTITY();

    INSERT INTO [seg].[RefreshTokenSesion]
    (
        sesion_usuario_id,
        token_hash,
        fecha_emision,
        fecha_expiracion,
        estado
    )
    VALUES
    (
        @nSesionUsuarioId,
        @binRefreshTokenHash,
        @dAhora,
        @dExpiracionRenovacion,
        1
    );

    UPDATE [seg].[Usuario]
    SET
        ultimo_acceso_correcto = @dAhora,
        intentos_fallidos = 0,
        fecha_ultimo_intento_fallido = NULL,
        bloqueado_hasta = NULL,
        estado_cuenta = 'ACTIVA'
    WHERE usuario_id = @nUsuarioId;

    SET @binIdentificadorHash =
        HASHBYTES('SHA2_256', CONVERT(VARBINARY(8000), LOWER(LTRIM(RTRIM(@cNombreUsuario)))));

    INSERT INTO [seg].[IntentoAutenticacion]
    (
        usuario_id,
        identificador_ingresado_hash,
        dispositivo_usuario_id,
        fecha_hora,
        resultado,
        ip,
        user_agent,
        estado
    )
    VALUES
    (
        @nUsuarioId,
        @binIdentificadorHash,
        @nDispositivoUsuarioId,
        @dAhora,
        'EXITOSO',
        NULLIF(LTRIM(RTRIM(@cIp)), ''),
        @cUserAgent,
        1
    );

    /*
       @bNuevoDispositivo informa al backend que la huella lógica se insertó
       por primera vez. El correo se registra y envía fuera de esta transacción,
       evitando dejar notificaciones PENDIENTES si el envío SMTP falla.
    */

    EXEC [auditoria].[PA_Auditoria_Ins_Evento]
         @nUsuarioId = @nUsuarioId,
         @nSesionUsuarioId = @nSesionUsuarioId,
         @nDispositivoUsuarioId = @nDispositivoUsuarioId,
         @cAccion = 'LOGIN',
         @cEsquemaEntidad = N'seg',
         @cNombreEntidad = N'Usuario',
         @cIdentificador = @nUsuarioId,
         @cMotivo = N'Inicio de sesion satisfactorio.',
         @cIp = @cIp,
         @cResultado = 'EXITOSO',
         @gCorrelacionId = @gCorrelacionId,
         @cEndpoint = N'/api/auth/login',
         @nAuditoriaEventoId = @nAuditoriaId OUTPUT;

    SET @bResultado = 1;
    SET @cMensaje = N'Sesion iniciada correctamente.';

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Seguridad_Ins_CrearSesionInterna',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
    IF @__DbError = 0 AND @bResultado = 1 AND XACT_STATE() = 1
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
    ELSE
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Seguridad_Ins_CrearSesionInterna',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
IF ISNULL(@bResultado,0) = 0 SELECT @nSesionUsuarioId=NULL, @gSesionPublicaId=NULL, @nDispositivoUsuarioId=NULL;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'seg.PA_Seguridad_Ins_CrearSesionInterna',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;


GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- seg.PA_Seguridad_Ins_Notificacion
CREATE OR ALTER PROCEDURE [seg].[PA_Seguridad_Ins_Notificacion]
(
    @nUsuarioId                 BIGINT,
    @cTipoNotificacion          VARCHAR(35),
    @cCorreoDestino             NVARCHAR(320),
    @cMetadata                  NVARCHAR(MAX) = NULL,
    @gCorrelacionId             UNIQUEIDENTIFIER = NULL,
    @nNotificacionSeguridadId   BIGINT OUTPUT,
    @bResultado BIT=NULL OUTPUT,
    @cMensaje NVARCHAR(300)=NULL OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    SET @bResultado=0;
BEGIN TRY

    /* DESCO_SEGURIDAD_V2_20260825 */
    SET NOCOUNT ON;

    SET @nNotificacionSeguridadId = NULL;

    SET @cTipoNotificacion = UPPER(NULLIF(LTRIM(RTRIM(@cTipoNotificacion)), ''));
    SET @cCorreoDestino = NULLIF(LTRIM(RTRIM(@cCorreoDestino)), '');

    IF @nUsuarioId IS NULL
       OR @cTipoNotificacion IS NULL
       OR @cCorreoDestino IS NULL
       OR @cTipoNotificacion NOT IN
       (
           'VALIDACION_CORREO',
           'RECUPERACION_PASSWORD',
           'SEGUNDO_FACTOR',
           'NUEVO_DISPOSITIVO',
           'CAMBIO_PASSWORD',
           'CAMBIO_CORREO'
       )
    BEGIN
        THROW 52200, N'No se pudo registrar la notificacion de seguridad.', 1;
    END;

    IF @cMetadata IS NOT NULL AND ISJSON(@cMetadata) <> 1
    BEGIN
        SET @cMetadata = NULL;
    END;

    /*
       Los tres tipos con codigo nunca guardan metadata que pueda terminar
       conteniendo el OTP por error. El codigo vive solo en memoria del backend.
    */
    IF @cTipoNotificacion IN
       ('VALIDACION_CORREO','RECUPERACION_PASSWORD','SEGUNDO_FACTOR')
    BEGIN
        SET @cMetadata = NULL;
    END;

    IF @gCorrelacionId IS NULL
        SET @gCorrelacionId = NEWID();

    INSERT INTO [seg].[NotificacionSeguridad]
    (
        usuario_id,
        tipo_notificacion,
        correo_destino,
        fecha_creacion,
        cantidad_intentos,
        estado_envio,
        correlacion_id,
        metadata,
        estado
    )
    VALUES
    (
        @nUsuarioId,
        @cTipoNotificacion,
        @cCorreoDestino,
        SYSUTCDATETIME(),
        0,
        'PENDIENTE',
        @gCorrelacionId,
        @cMetadata,
        1
    );

    SET @nNotificacionSeguridadId = SCOPE_IDENTITY();

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Seguridad_Ins_Notificacion',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
SET @bResultado=0; SET @cMensaje=@__DbMensaje;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Seguridad_Ins_Notificacion',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
SET @bResultado=0; SET @cMensaje=@__DbMensaje;
END CATCH;
SET @bResultado=CASE WHEN @__DbError=0 AND @nNotificacionSeguridadId IS NOT NULL THEN 1 ELSE 0 END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'seg.PA_Seguridad_Ins_Notificacion',@bResultado,@cMensaje) R;
IF @bResultado=0 AND @@NESTLEVEL>1 THROW 51000,@cMensaje,1;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- seg.PA_Seguridad_Sel_NotificacionesPendientes
CREATE OR ALTER PROCEDURE [seg].[PA_Seguridad_Sel_NotificacionesPendientes]
(
    @nCantidad INT = 50,
    @bResultado BIT=NULL OUTPUT,
    @cMensaje NVARCHAR(300)=NULL OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;

    SET @bResultado=0;
BEGIN TRY

    /* DESCO_SEGURIDAD_V2_20260825 */
    SET NOCOUNT ON;

    IF @nCantidad IS NULL OR @nCantidad < 1 SET @nCantidad = 50;
    IF @nCantidad > 500 SET @nCantidad = 500;

    SELECT TOP (@nCantidad)
        N.notificacion_seguridad_id AS notificacionSeguridadId,
        N.usuario_id AS usuarioId,
        N.tipo_notificacion AS tipoNotificacion,
        N.correo_destino AS correoDestino,
        N.fecha_creacion AS fechaCreacionUtc,
        N.cantidad_intentos AS cantidadIntentos,
        N.correlacion_id AS correlacionId,
        N.metadata
    FROM [seg].[NotificacionSeguridad] N
    WHERE N.estado = 1
      AND N.estado_envio IN ('PENDIENTE','FALLIDO')
      AND N.tipo_notificacion IN
          ('NUEVO_DISPOSITIVO','CAMBIO_PASSWORD','CAMBIO_CORREO')
      AND N.cantidad_intentos < 10
    ORDER BY
        N.fecha_creacion,
        N.notificacion_seguridad_id;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Seguridad_Sel_NotificacionesPendientes',
