-- seg.PA_Seguridad_Upd_ConsumirCodigoUnSoloUso
CREATE OR ALTER PROCEDURE [seg].[PA_Seguridad_Upd_ConsumirCodigoUnSoloUso]
(
    @nUsuarioId                   BIGINT,
    @cProposito                   VARCHAR(35),
    @binCodigoHmac                VARBINARY(64),
    @cIp                          VARCHAR(64) = NULL,
    @gCorrelacionId               UNIQUEIDENTIFIER = NULL,
    @nCodigoUnSoloUsoId           BIGINT OUTPUT,
    @nUsuarioCorreoSeguridadId    BIGINT OUTPUT,
    @bCodigoValido                BIT OUTPUT,
    @cMensaje                     NVARCHAR(300) OUTPUT,
    @bResultado BIT=NULL OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bCodigoValido = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    SET @bResultado=0;
BEGIN TRY
BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

    /* DESCO_SEGURIDAD_V2_20260825 */
    SET NOCOUNT ON;

    DECLARE
        @dAhora DATETIME2(0) = SYSUTCDATETIME(),
        @binHmacEsperado VARBINARY(64),
        @dExpiracion DATETIME2(0),
        @dUso DATETIME2(0),
        @dInvalidacion DATETIME2(0),
        @nIntentos SMALLINT,
        @nMaxIntentos SMALLINT,
        @gGrupoSolicitud UNIQUEIDENTIFIER,
        @nDispositivoUsuarioId BIGINT,
        @nAuditoriaId BIGINT;

    SET @nCodigoUnSoloUsoId = NULL;
    SET @nUsuarioCorreoSeguridadId = NULL;
    SET @bCodigoValido = 0;
    SET @cMensaje = N'El codigo ingresado no es valido o ha expirado.';

    SET @cProposito = UPPER(NULLIF(LTRIM(RTRIM(@cProposito)), ''));

    IF @nUsuarioId IS NULL
       OR @binCodigoHmac IS NULL
       OR @cProposito NOT IN
          ('VALIDACION_CORREO','RECUPERACION_PASSWORD','SEGUNDO_FACTOR','CAMBIO_CORREO')
    BEGIN
        GOTO __DESCO_Salida;
    END;

    SELECT TOP (1)
        @nCodigoUnSoloUsoId = C.codigo_un_solo_uso_id,
        @nUsuarioCorreoSeguridadId = C.usuario_correo_seguridad_id,
        @binHmacEsperado = C.codigo_hmac,
        @dExpiracion = C.fecha_expiracion,
        @dUso = C.fecha_uso,
        @dInvalidacion = C.fecha_invalidacion,
        @nIntentos = C.intentos_fallidos,
        @nMaxIntentos = C.maximo_intentos,
        @gGrupoSolicitud = C.grupo_solicitud,
        @nDispositivoUsuarioId = C.dispositivo_usuario_id
    FROM [seg].[CodigoUnSoloUso] C WITH (UPDLOCK, HOLDLOCK)
    WHERE C.usuario_id = @nUsuarioId
      AND C.proposito = @cProposito
      AND C.estado = 1
    ORDER BY C.fecha_creacion DESC, C.codigo_un_solo_uso_id DESC;

    SET @gCorrelacionId = COALESCE(@gCorrelacionId, @gGrupoSolicitud, NEWID());

    IF @nCodigoUnSoloUsoId IS NULL
    BEGIN
        EXEC [auditoria].[PA_Auditoria_Ins_Evento]
             @nUsuarioId = @nUsuarioId,
             @cAccion = 'VALIDAR_CODIGO_SEGURIDAD',
             @cEsquemaEntidad = N'seg',
             @cNombreEntidad = N'CodigoUnSoloUso',
             @cIdentificador = N'NO_DISPONIBLE',
             @cMotivo = @cProposito,
             @cIp = @cIp,
             @cResultado = 'RECHAZADO',
             @gCorrelacionId = @gCorrelacionId,
             @nAuditoriaEventoId = @nAuditoriaId OUTPUT;
        GOTO __DESCO_Salida;
    END;

    IF @dUso IS NOT NULL
       OR @dInvalidacion IS NOT NULL
       OR @dExpiracion <= @dAhora
       OR @nIntentos >= @nMaxIntentos
    BEGIN
        UPDATE [seg].[CodigoUnSoloUso]
        SET
            fecha_invalidacion =
                CASE WHEN fecha_uso IS NULL
                     THEN COALESCE(fecha_invalidacion, @dAhora)
                     ELSE fecha_invalidacion END,
            estado = 0
        WHERE codigo_un_solo_uso_id = @nCodigoUnSoloUsoId;

        EXEC [auditoria].[PA_Auditoria_Ins_Evento]
             @nUsuarioId = @nUsuarioId,
             @nDispositivoUsuarioId = @nDispositivoUsuarioId,
             @cAccion = 'VALIDAR_CODIGO_SEGURIDAD',
             @cEsquemaEntidad = N'seg',
             @cNombreEntidad = N'CodigoUnSoloUso',
             @cIdentificador = @nCodigoUnSoloUsoId,
             @cMotivo = @cProposito,
             @cIp = @cIp,
             @cResultado = 'RECHAZADO',
             @gCorrelacionId = @gCorrelacionId,
             @nAuditoriaEventoId = @nAuditoriaId OUTPUT;
        GOTO __DESCO_Salida;
    END;

    IF @binHmacEsperado <> @binCodigoHmac
    BEGIN
        UPDATE [seg].[CodigoUnSoloUso]
        SET
            intentos_fallidos =
                CASE
                    WHEN intentos_fallidos + 1 > maximo_intentos
                        THEN maximo_intentos
                    ELSE intentos_fallidos + 1
                END,
            fecha_invalidacion =
                CASE
                    WHEN intentos_fallidos + 1 >= maximo_intentos
                        THEN @dAhora
                    ELSE fecha_invalidacion
                END,
            estado =
                CASE
                    WHEN intentos_fallidos + 1 >= maximo_intentos
                        THEN 0
                    ELSE estado
                END
        WHERE codigo_un_solo_uso_id = @nCodigoUnSoloUsoId;

        EXEC [auditoria].[PA_Auditoria_Ins_Evento]
             @nUsuarioId = @nUsuarioId,
             @nDispositivoUsuarioId = @nDispositivoUsuarioId,
             @cAccion = 'VALIDAR_CODIGO_SEGURIDAD',
             @cEsquemaEntidad = N'seg',
             @cNombreEntidad = N'CodigoUnSoloUso',
             @cIdentificador = @nCodigoUnSoloUsoId,
             @cMotivo = @cProposito,
             @cIp = @cIp,
             @cResultado = 'RECHAZADO',
             @gCorrelacionId = @gCorrelacionId,
             @nAuditoriaEventoId = @nAuditoriaId OUTPUT;
        GOTO __DESCO_Salida;
    END;

    UPDATE [seg].[CodigoUnSoloUso]
    SET
        fecha_uso = @dAhora,
        estado = 0
    WHERE codigo_un_solo_uso_id = @nCodigoUnSoloUsoId
      AND estado = 1
      AND fecha_uso IS NULL
      AND fecha_invalidacion IS NULL
      AND fecha_expiracion > @dAhora;

    IF @@ROWCOUNT = 1
    BEGIN
        SET @bCodigoValido = 1;
        SET @cMensaje = N'Codigo validado correctamente.';

        EXEC [auditoria].[PA_Auditoria_Ins_Evento]
             @nUsuarioId = @nUsuarioId,
             @nDispositivoUsuarioId = @nDispositivoUsuarioId,
             @cAccion = 'VALIDAR_CODIGO_SEGURIDAD',
             @cEsquemaEntidad = N'seg',
             @cNombreEntidad = N'CodigoUnSoloUso',
             @cIdentificador = @nCodigoUnSoloUsoId,
             @cMotivo = @cProposito,
             @cIp = @cIp,
             @cResultado = 'EXITOSO',
             @gCorrelacionId = @gCorrelacionId,
             @nAuditoriaEventoId = @nAuditoriaId OUTPUT;
    END;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bCodigoValido = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Seguridad_Upd_ConsumirCodigoUnSoloUso',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
    IF @__DbError = 0 AND XACT_STATE() = 1
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
    ELSE
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bCodigoValido = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Seguridad_Upd_ConsumirCodigoUnSoloUso',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bCodigoValido,0) = 1
BEGIN
SET @bCodigoValido = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=CASE WHEN @__DbError=0 THEN ISNULL(@bCodigoValido,0) ELSE 0 END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'seg.PA_Seguridad_Upd_ConsumirCodigoUnSoloUso',@bResultado,@cMensaje) R;
IF @__DbError=1 AND @@NESTLEVEL>1 THROW 51000,@cMensaje,1;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- seg.PA_Seguridad_Upd_NotificacionResultado
CREATE OR ALTER PROCEDURE [seg].[PA_Seguridad_Upd_NotificacionResultado]
(
    @cJson       NVARCHAR(MAX),
    @bResultado  BIT OUTPUT,
    @cMensaje    NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    /* DESCO_SEGURIDAD_V2_20260825 */
    SET NOCOUNT ON;

    DECLARE @nNotificacionId BIGINT;
    DECLARE @cEstadoEnvio VARCHAR(20);
    DECLARE @cProveedorMensajeId NVARCHAR(200);

    SET @bResultado = 0;
    SET @cMensaje = N'No se pudo actualizar el envio.';

    IF @cJson IS NULL OR ISJSON(@cJson) <> 1
    BEGIN
        SET @cMensaje = N'La solicitud no es valida.';
        GOTO __DESCO_Salida;
    END;

    SELECT
        @nNotificacionId = notificacionSeguridadId,
        @cEstadoEnvio = UPPER(NULLIF(LTRIM(RTRIM(estadoEnvio)), '')),
        @cProveedorMensajeId = NULLIF(LTRIM(RTRIM(proveedorMensajeId)), '')
    FROM OPENJSON(@cJson)
    WITH
    (
        notificacionSeguridadId BIGINT '$.notificacionSeguridadId',
        estadoEnvio VARCHAR(20) '$.estadoEnvio',
        proveedorMensajeId NVARCHAR(200) '$.proveedorMensajeId'
    );

    IF @nNotificacionId IS NULL
       OR @cEstadoEnvio NOT IN ('ENVIADO','FALLIDO','CANCELADO')
    BEGIN
        SET @cMensaje = N'La solicitud no es valida.';
        GOTO __DESCO_Salida;
    END;

    UPDATE [seg].[NotificacionSeguridad]
    SET
        fecha_ultimo_intento = SYSUTCDATETIME(),
        fecha_envio = CASE WHEN @cEstadoEnvio = 'ENVIADO'
                           THEN SYSUTCDATETIME()
                           ELSE fecha_envio END,
        cantidad_intentos = cantidad_intentos + 1,
        estado_envio = @cEstadoEnvio,
        proveedor_mensaje_id =
            CASE WHEN @cEstadoEnvio = 'ENVIADO'
                 THEN @cProveedorMensajeId
                 ELSE proveedor_mensaje_id END
    WHERE notificacion_seguridad_id = @nNotificacionId
      AND estado = 1
      AND estado_envio <> 'CANCELADO';

    IF @@ROWCOUNT = 0
    BEGIN
        SET @cMensaje = N'La notificacion seleccionada no esta disponible.';
        GOTO __DESCO_Salida;
    END;

    SET @bResultado = 1;
    SET @cMensaje = N'Estado de envio actualizado correctamente.';

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Seguridad_Upd_NotificacionResultado',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Seguridad_Upd_NotificacionResultado',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'seg.PA_Seguridad_Upd_NotificacionResultado',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

