CREATE OR ALTER PROCEDURE [seg].[PA_Seguridad_Upd_RevocarSesionesUsuario]
(
    @nUsuarioId                   BIGINT,
    @cMotivo                      NVARCHAR(300),
    @nSesionExcluirId             BIGINT = NULL,
    @bIncrementarTokenVersion     BIT = 1,
    @nCantidadSesionesRevocadas   INT OUTPUT,
    @bResultado BIT=NULL OUTPUT,
    @cMensaje NVARCHAR(300)=NULL OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    SET @bResultado=0;
BEGIN TRY
BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

    /* DESCO_SEGURIDAD_2FA_DISPOSITIVO_V3_20260904 */
    SET NOCOUNT ON;

    DECLARE
        @dAhora DATETIME2(0) = SYSUTCDATETIME(),
        @nDispositivoExcluirId BIGINT;

    DECLARE @DispositivosRevocados TABLE
    (
        dispositivo_usuario_id BIGINT PRIMARY KEY
    );

    SET @nCantidadSesionesRevocadas = 0;
    SET @cMotivo = COALESCE(NULLIF(LTRIM(RTRIM(@cMotivo)), ''), N'Revocacion de seguridad.');

    IF @nUsuarioId IS NULL
    BEGIN
        THROW 52220, N'No se pudo revocar las sesiones.', 1;
    END;

    /*
       Si existe una sesion excluida ("cerrar las demas"), se conserva solo
       el dispositivo de esa sesion actual. Todos los demas dispositivos
       reconocidos del usuario pierden la confianza, incluso si en ese momento
       no tienen una sesion activa.

       Si no existe sesion excluida (revocacion total por seguridad, cambio de
       password, deshabilitacion, etc.), se elimina la confianza de TODOS los
       dispositivos del usuario.
    */
    IF @nSesionExcluirId IS NOT NULL
    BEGIN
        SELECT @nDispositivoExcluirId = S.dispositivo_usuario_id
        FROM [seg].[SesionUsuario] S
        WHERE S.sesion_usuario_id = @nSesionExcluirId
          AND S.usuario_id = @nUsuarioId;
    END;

    INSERT INTO @DispositivosRevocados(dispositivo_usuario_id)
    SELECT D.dispositivo_usuario_id
    FROM [seg].[DispositivoUsuario] D
    WHERE D.usuario_id = @nUsuarioId
      AND D.estado = 1
      AND D.es_reconocido = 1
      AND (
            @nDispositivoExcluirId IS NULL
            OR D.dispositivo_usuario_id <> @nDispositivoExcluirId
          );

    UPDATE S
    SET
        S.fecha_revocacion = COALESCE(S.fecha_revocacion, @dAhora),
        S.motivo_revocacion = COALESCE(S.motivo_revocacion, @cMotivo),
        S.estado = 0
    FROM [seg].[SesionUsuario] S
    WHERE S.usuario_id = @nUsuarioId
      AND S.estado = 1
      AND S.fecha_revocacion IS NULL
      AND (@nSesionExcluirId IS NULL OR S.sesion_usuario_id <> @nSesionExcluirId);

    SET @nCantidadSesionesRevocadas = @@ROWCOUNT;

    UPDATE RT
    SET
        RT.fecha_revocacion = COALESCE(RT.fecha_revocacion, @dAhora),
        RT.motivo_revocacion = COALESCE(RT.motivo_revocacion, @cMotivo),
        RT.estado = 0
    FROM [seg].[RefreshTokenSesion] RT
    INNER JOIN [seg].[SesionUsuario] S
        ON S.sesion_usuario_id = RT.sesion_usuario_id
    WHERE S.usuario_id = @nUsuarioId
      AND (@nSesionExcluirId IS NULL OR S.sesion_usuario_id <> @nSesionExcluirId)
      AND RT.estado = 1;

    UPDATE D
    SET
        D.es_reconocido = 0,
        D.fecha_retiro_reconocimiento =
            COALESCE(D.fecha_retiro_reconocimiento, @dAhora)
    FROM [seg].[DispositivoUsuario] D
    INNER JOIN @DispositivosRevocados X
        ON X.dispositivo_usuario_id = D.dispositivo_usuario_id
    WHERE D.usuario_id = @nUsuarioId
      AND D.estado = 1
      AND D.es_reconocido = 1;

    IF @bIncrementarTokenVersion = 1
    BEGIN
        UPDATE [seg].[Usuario]
        SET token_version = token_version + 1
        WHERE usuario_id = @nUsuarioId;
    END;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Seguridad_Upd_RevocarSesionesUsuario',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
SET @bResultado=0; SET @cMensaje=@__DbMensaje;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
    IF @__DbError = 0 AND XACT_STATE() = 1
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;
    ELSE
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Seguridad_Upd_RevocarSesionesUsuario',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = NULL,
    @bMensajePublicoGenerico = 0;
SET @bResultado=0; SET @cMensaje=@__DbMensaje;
END CATCH;
SET @bResultado=CASE WHEN @__DbError=0 THEN 1 ELSE 0 END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'seg.PA_Seguridad_Upd_RevocarSesionesUsuario',@bResultado,@cMensaje) R;
IF @bResultado=0 AND @@NESTLEVEL>1 THROW 51000,@cMensaje,1;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- seg.PA_Sesion_Ins_Crear
CREATE OR ALTER PROCEDURE [seg].[PA_Sesion_Ins_Crear]
(
    @cJson                   NVARCHAR(MAX),
    @nSesionUsuarioId        BIGINT OUTPUT,
    @gSesionPublicaId        UNIQUEIDENTIFIER OUTPUT,
    @dExpiracionRenovacion   DATETIME2(0) OUTPUT,
    @bNuevoDispositivo       BIT OUTPUT,
    @bResultado              BIT OUTPUT,
    @cMensaje                NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;

    BEGIN TRY

    /* DESCO_SEGURIDAD_V2_20260825 */
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @nUsuarioId BIGINT,
        @cDispositivoHashHex VARCHAR(128),
        @binDispositivoHash VARBINARY(64),
        @cRefreshTokenHashHex VARCHAR(128),
        @binRefreshTokenHash VARBINARY(64),
        @cNavegador NVARCHAR(120),
        @cSistemaOperativo NVARCHAR(120),
        @cUserAgent NVARCHAR(600),
        @cIp VARCHAR(64),
        @gCorrelacionId UNIQUEIDENTIFIER,
        @dAhora DATETIME2(0) = SYSUTCDATETIME(),
        @nMinutosPreAutenticacion SMALLINT,
        @nDispositivoId BIGINT,
        @bInterno BIT,
        @cMensajeInterno NVARCHAR(300),
        @nOperacionIdempotenteId BIGINT,
        @bEsRepetida BIT,
        @cEstadoOperacion VARCHAR(20),
        @cIdentificadorResultado NVARCHAR(200),
        @cCodigoResultado VARCHAR(40),
        @bIdempotencia BIT,
        @cMensajeIdempotencia NVARCHAR(300),
        @bFinalizacionIdempotencia BIT,
        @cMensajeFinalizacion NVARCHAR(300);

    SET @nSesionUsuarioId = NULL;
    SET @gSesionPublicaId = NULL;
    SET @dExpiracionRenovacion = NULL;
    SET @bNuevoDispositivo = 0;
    SET @bResultado = 0;
    SET @cMensaje = N'No se pudo iniciar la sesion.';

    IF @cJson IS NULL OR ISJSON(@cJson) <> 1
    BEGIN
        SET @cMensaje = N'La solicitud no es valida.';
        GOTO __DESCO_Salida;
    END;

    SELECT
        @nUsuarioId = usuarioId,
        @cDispositivoHashHex = NULLIF(LTRIM(RTRIM(dispositivoHashHex)), ''),
        @cRefreshTokenHashHex = NULLIF(LTRIM(RTRIM(refreshTokenHashHex)), ''),
        @cNavegador = NULLIF(LTRIM(RTRIM(navegador)), ''),
        @cSistemaOperativo = NULLIF(LTRIM(RTRIM(sistemaOperativo)), ''),
        @cUserAgent = userAgent,
        @cIp = NULLIF(LTRIM(RTRIM(ip)), ''),
        @gCorrelacionId = correlacionId
    FROM OPENJSON(@cJson)
    WITH
    (
        usuarioId BIGINT '$.usuarioId',
        dispositivoHashHex VARCHAR(128) '$.dispositivoHashHex',
        refreshTokenHashHex VARCHAR(128) '$.refreshTokenHashHex',
        navegador NVARCHAR(120) '$.navegador',
        sistemaOperativo NVARCHAR(120) '$.sistemaOperativo',
        userAgent NVARCHAR(600) '$.userAgent',
        ip VARCHAR(64) '$.ip',
        correlacionId UNIQUEIDENTIFIER '$.correlacionId'
    );

    SET @binDispositivoHash = TRY_CONVERT(VARBINARY(64), @cDispositivoHashHex, 2);
    SET @binRefreshTokenHash = TRY_CONVERT(VARBINARY(64), @cRefreshTokenHashHex, 2);

    IF @nUsuarioId IS NULL
       OR @binDispositivoHash IS NULL
       OR @binRefreshTokenHash IS NULL
       OR @gCorrelacionId IS NULL
    BEGIN
        SET @cMensaje = N'La solicitud no es valida.';
        GOTO __DESCO_Salida;
    END;

    SELECT TOP (1)
        @nMinutosPreAutenticacion = PS.minutos_expiracion_segundo_factor
    FROM [seg].[PoliticaSeguridad] PS
    WHERE PS.codigo = 'GENERAL'
      AND PS.estado = 1
      AND PS.fecha_hasta IS NULL
      AND PS.fecha_desde <= @dAhora
    ORDER BY PS.fecha_desde DESC;

    IF @nMinutosPreAutenticacion IS NULL
    BEGIN
        SET @cMensaje = N'No se pudo iniciar la sesion. Intente nuevamente.';
        GOTO __DESCO_Salida;
    END;

    /*
       No se admite crear una sesion directamente. Debe existir, para el mismo
       usuario y correlacion, la evidencia reciente de Argon2 validado registrada
       por PA_Usuario_Upd_ResultadoCredencialLogin.
    */
    IF NOT EXISTS
    (
        SELECT 1
        FROM [auditoria].[AuditoriaEvento] A
        WHERE A.usuario_id = @nUsuarioId
          AND A.accion = 'LOGIN_CREDENCIAL'
          AND A.resultado = 'EXITOSO'
          AND A.correlacion_id = @gCorrelacionId
          AND A.endpoint = N'/api/auth/login'
          AND A.estado = 1
          AND A.fecha_hora >= DATEADD(MINUTE, -@nMinutosPreAutenticacion, @dAhora)
    )
    BEGIN
        SET @cMensaje = N'La verificacion de acceso ya no esta disponible. Inicie sesion nuevamente.';
        GOTO __DESCO_Salida;
    END;

    /*
       Una correlacion de login solo puede materializar una sesion. La utilidad
       generica de idempotencia evita doble click/reintentos concurrentes.
    */
    EXEC [auditoria].[PA_OperacionIdempotente_Ins_Iniciar]
         @nUsuarioId = @nUsuarioId,
         @gClaveIdempotencia = @gCorrelacionId,
         @cAmbito = 'LOGIN_CREAR_SESION',
         @nMinutosVigencia = @nMinutosPreAutenticacion,
         @nOperacionIdempotenteId = @nOperacionIdempotenteId OUTPUT,
         @bEsRepetida = @bEsRepetida OUTPUT,
         @cEstadoOperacion = @cEstadoOperacion OUTPUT,
         @cIdentificadorResultado = @cIdentificadorResultado OUTPUT,
         @cCodigoResultado = @cCodigoResultado OUTPUT,
         @bResultado = @bIdempotencia OUTPUT,
         @cMensaje = @cMensajeIdempotencia OUTPUT;

    IF @bEsRepetida = 1
    BEGIN
        IF @cEstadoOperacion = 'COMPLETADA'
           AND TRY_CONVERT(UNIQUEIDENTIFIER, @cIdentificadorResultado) IS NOT NULL
        BEGIN
            SET @gSesionPublicaId = TRY_CONVERT(UNIQUEIDENTIFIER, @cIdentificadorResultado);

            SELECT
                @nSesionUsuarioId = S.sesion_usuario_id,
                @dExpiracionRenovacion = S.fecha_expiracion_renovacion
            FROM [seg].[SesionUsuario] S
            WHERE S.sesion_publica_id = @gSesionPublicaId
              AND S.usuario_id = @nUsuarioId;

            IF @nSesionUsuarioId IS NOT NULL
            BEGIN
                SET @bResultado = 1;
                SET @cMensaje = N'La sesion ya fue iniciada.';
                GOTO __DESCO_Salida;
            END;
        END;

        SET @cMensaje = N'La solicitud de inicio de sesion ya fue procesada. Inicie el acceso nuevamente.';
        GOTO __DESCO_Salida;
    END;

    IF @bIdempotencia = 0 OR @nOperacionIdempotenteId IS NULL
    BEGIN
        SET @cMensaje = N'No se pudo iniciar la sesion. Intente nuevamente.';
        GOTO __DESCO_Salida;
    END;

    BEGIN TRY
        BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

        EXEC [seg].[PA_Seguridad_Ins_CrearSesionInterna]
             @nUsuarioId = @nUsuarioId,
             @binDispositivoHash = @binDispositivoHash,
             @cNavegador = @cNavegador,
             @cSistemaOperativo = @cSistemaOperativo,
             @cUserAgent = @cUserAgent,
             @cIp = @cIp,
             @binRefreshTokenHash = @binRefreshTokenHash,
             @bSegundoFactorValidado = 0,
             @gCorrelacionId = @gCorrelacionId,
             @nSesionUsuarioId = @nSesionUsuarioId OUTPUT,
             @gSesionPublicaId = @gSesionPublicaId OUTPUT,
             @nDispositivoUsuarioId = @nDispositivoId OUTPUT,
             @dExpiracionRenovacion = @dExpiracionRenovacion OUTPUT,
             @bNuevoDispositivo = @bNuevoDispositivo OUTPUT,
             @bResultado = @bInterno OUTPUT,
             @cMensaje = @cMensajeInterno OUTPUT;

        IF @bInterno = 0
        BEGIN
            BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;

            EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
                 @nOperacionIdempotenteId = @nOperacionIdempotenteId,
                 @cEstadoOperacion = 'FALLIDA',
                 @cCodigoResultado = 'SESION_NO_CREADA',
                 @bResultado = @bFinalizacionIdempotencia OUTPUT,
                 @cMensaje = @cMensajeFinalizacion OUTPUT;

            SET @nSesionUsuarioId = NULL;
            SET @gSesionPublicaId = NULL;
            SET @dExpiracionRenovacion = NULL;
            SET @bNuevoDispositivo = 0;
            SET @cMensaje = @cMensajeInterno;
            GOTO __DESCO_Salida;
        END;

        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
             @nOperacionIdempotenteId = @nOperacionIdempotenteId,
             @cEstadoOperacion = 'COMPLETADA',
             @cEsquemaEntidad = N'seg',
             @cNombreEntidad = N'SesionUsuario',
             @cIdentificadorResultado = @gSesionPublicaId,
             @cCodigoResultado = 'SESION_CREADA',
             @bResultado = @bFinalizacionIdempotencia OUTPUT,
             @cMensaje = @cMensajeFinalizacion OUTPUT;
IF ISNULL(@bFinalizacionIdempotencia,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;

        IF @bFinalizacionIdempotencia = 0
        BEGIN
            THROW 52650, N'No se pudo consolidar el inicio de sesion.', 1;
        END;

        BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;

        SET @bResultado = 1;
        SET @cMensaje = N'Sesion iniciada correctamente.';
    END TRY
    BEGIN CATCH
SET @bResultado = 0;

        IF XACT_STATE() <> 0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;

        IF @nOperacionIdempotenteId IS NOT NULL
        BEGIN
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
                 @nOperacionIdempotenteId = @nOperacionIdempotenteId,
                 @cEstadoOperacion = 'FALLIDA',
                 @cCodigoResultado = 'ERROR_SESION',
                 @bResultado = @bFinalizacionIdempotencia OUTPUT,
                 @cMensaje = @cMensajeFinalizacion OUTPUT;
        END;

        SET @nSesionUsuarioId = NULL;
        SET @gSesionPublicaId = NULL;
        SET @dExpiracionRenovacion = NULL;
        SET @bNuevoDispositivo = 0;
        SET @bResultado = 0;
        SET @cMensaje = N'No se pudo iniciar la sesion. Intente nuevamente.';
    
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Sesion_Ins_Crear',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 1;
END;
END CATCH;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Sesion_Ins_Crear',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 1;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Sesion_Ins_Crear',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 1;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'seg.PA_Sesion_Ins_Crear',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- seg.PA_Sesion_Ins_RevocarAccessToken
CREATE OR ALTER PROCEDURE [seg].[PA_Sesion_Ins_RevocarAccessToken]
(
    @cJson       NVARCHAR(MAX),
    @bResultado  BIT OUTPUT,
    @cMensaje    NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    /* DESCO_SEGURIDAD_V2_20260825 */
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @nUsuarioId BIGINT,
        @gSesionPublicaId UNIQUEIDENTIFIER,
        @nSesionId BIGINT,
        @nDispositivoUsuarioId BIGINT,
        @cJtiHashHex VARCHAR(128),
        @binJtiHash VARBINARY(64),
        @dExpiracionToken DATETIME2(0),
        @cMotivo NVARCHAR(300),
        @cIp VARCHAR(64),
        @gCorrelacionId UNIQUEIDENTIFIER,
        @nTokenAccesoRevocadoId BIGINT,
        @nAuditoriaEventoId BIGINT,
        @dAhora DATETIME2(0) = SYSUTCDATETIME();

    SET @bResultado = 0;
    SET @cMensaje = N'No se pudo revocar el acceso.';

    IF @cJson IS NULL OR ISJSON(@cJson) <> 1
    BEGIN
        SET @cMensaje = N'La solicitud no es valida.';
        GOTO __DESCO_Salida;
    END;

    SELECT
        @nUsuarioId = usuarioId,
        @gSesionPublicaId = sesionPublicaId,
        @cJtiHashHex = NULLIF(LTRIM(RTRIM(jtiHashHex)), ''),
        @dExpiracionToken = fechaExpiracionTokenUtc,
        @cMotivo = NULLIF(LTRIM(RTRIM(motivo)), ''),
        @cIp = NULLIF(LTRIM(RTRIM(ip)), ''),
        @gCorrelacionId = correlacionId
    FROM OPENJSON(@cJson)
    WITH
    (
        usuarioId BIGINT '$.usuarioId',
        sesionPublicaId UNIQUEIDENTIFIER '$.sesionPublicaId',
        jtiHashHex VARCHAR(128) '$.jtiHashHex',
        fechaExpiracionTokenUtc DATETIME2(0) '$.fechaExpiracionTokenUtc',
        motivo NVARCHAR(300) '$.motivo',
        ip VARCHAR(64) '$.ip',
        correlacionId UNIQUEIDENTIFIER '$.correlacionId'
    );

    SET @binJtiHash = TRY_CONVERT(VARBINARY(64), @cJtiHashHex, 2);

    IF @nUsuarioId IS NULL
       OR @gSesionPublicaId IS NULL
       OR @binJtiHash IS NULL
       OR @dExpiracionToken IS NULL
       OR @dExpiracionToken <= @dAhora
    BEGIN
        SET @cMensaje = N'La solicitud no es valida.';
        GOTO __DESCO_Salida;
    END;

    /*
       Solo una sesion autentica y vigente puede revocar uno de sus access tokens.
       La validacion criptografica del JWT se realiza previamente en el backend.
    */
    SELECT
        @nSesionId = S.sesion_usuario_id,
        @nDispositivoUsuarioId = S.dispositivo_usuario_id
    FROM [seg].[SesionUsuario] S
    INNER JOIN [seg].[Usuario] U
            ON U.usuario_id = S.usuario_id
    WHERE S.sesion_publica_id = @gSesionPublicaId
      AND S.usuario_id = @nUsuarioId
      AND S.estado = 1
      AND S.fecha_revocacion IS NULL
      AND S.fecha_expiracion_renovacion > @dAhora
      AND S.token_version = U.token_version
      AND U.estado = 1
      AND U.estado_cuenta = 'ACTIVA';

    IF @nSesionId IS NULL
    BEGIN
        SET @cMensaje = N'La sesion no esta disponible.';
        GOTO __DESCO_Salida;
    END;

    BEGIN TRY
        BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

        SELECT
            @nTokenAccesoRevocadoId = TAR.token_acceso_revocado_id
        FROM [seg].[TokenAccesoRevocado] TAR WITH (UPDLOCK, HOLDLOCK)
        WHERE TAR.jti_hash = @binJtiHash;

        IF @nTokenAccesoRevocadoId IS NULL
        BEGIN
            INSERT INTO [seg].[TokenAccesoRevocado]
            (
                sesion_usuario_id,
                jti_hash,
                fecha_revocacion,
                fecha_expiracion_token,
                motivo,
                estado
            )
            VALUES
            (
                @nSesionId,
                @binJtiHash,
                @dAhora,
                @dExpiracionToken,
                COALESCE(@cMotivo, N'Revocacion puntual de token de acceso.'),
                1
            );

            SET @nTokenAccesoRevocadoId = CONVERT(BIGINT, SCOPE_IDENTITY());
        END;

        /*
           Se audita el acto de revocacion, no el JTI ni su hash.
           PA_Auditoria_Ins_Evento bloquea adicionalmente payloads sensibles.
        */
        EXEC [auditoria].[PA_Auditoria_Ins_Evento]
             @nUsuarioId = @nUsuarioId,
             @nSesionUsuarioId = @nSesionId,
             @nDispositivoUsuarioId = @nDispositivoUsuarioId,
             @cAccion = 'REVOCAR_ACCESS_TOKEN',
             @cEsquemaEntidad = N'seg',
             @cNombreEntidad = N'TokenAccesoRevocado',
             @cIdentificador = @nTokenAccesoRevocadoId,
             @cMotivo = @cMotivo,
             @cIp = @cIp,
             @cResultado = 'EXITOSO',
             @gCorrelacionId = @gCorrelacionId,
             @cEndpoint = N'/api/auth/logout-token',
             @nAuditoriaEventoId = @nAuditoriaEventoId OUTPUT;

        BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;

        SET @bResultado = 1;
        SET @cMensaje = N'Acceso revocado correctamente.';
    END TRY
    BEGIN CATCH
SET @bResultado = 0;

        IF XACT_STATE() <> 0
            BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;

        SET @bResultado = 0;
        SET @cMensaje = N'No se pudo revocar el acceso. Intente nuevamente.';
    
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Sesion_Ins_RevocarAccessToken',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 1;
END;
END CATCH;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Sesion_Ins_RevocarAccessToken',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 1;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
