-- seg.PA_Sesion_Upd_Cerrar
CREATE OR ALTER PROCEDURE [seg].[PA_Sesion_Upd_Cerrar]
(
    @cJson       NVARCHAR(MAX),
    @bResultado  BIT OUTPUT,
    @cMensaje    NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    /* DESCO_SEGURIDAD_2FA_DISPOSITIVO_V3_20260904 */
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @nUsuarioId BIGINT,
        @gSesionActor UNIQUEIDENTIFIER,
        @gSesionObjetivo UNIQUEIDENTIFIER,
        @nSesionActorId BIGINT,
        @nDispositivoActorId BIGINT,
        @nSesionObjetivoId BIGINT,
        @nDispositivoObjetivoId BIGINT,
        @cIp VARCHAR(64),
        @gCorrelacionId UNIQUEIDENTIFIER,
        @dAhora DATETIME2(0) = SYSUTCDATETIME(),
        @nAuditoriaId BIGINT;

    SET @bResultado = 0;
    SET @cMensaje = N'No se pudo cerrar la sesion.';

    IF @cJson IS NULL OR ISJSON(@cJson) <> 1
    BEGIN
        SET @cMensaje = N'La solicitud no es valida.';
        GOTO __DESCO_Salida;
    END;

    SELECT
        @nUsuarioId = usuarioId,
        @gSesionActor = sesionActualPublicaId,
        @gSesionObjetivo = sesionObjetivoPublicaId,
        @cIp = NULLIF(LTRIM(RTRIM(ip)), ''),
        @gCorrelacionId = correlacionId
    FROM OPENJSON(@cJson)
    WITH
    (
        usuarioId BIGINT '$.usuarioId',
        sesionActualPublicaId UNIQUEIDENTIFIER '$.sesionActualPublicaId',
        sesionObjetivoPublicaId UNIQUEIDENTIFIER '$.sesionObjetivoPublicaId',
        ip VARCHAR(64) '$.ip',
        correlacionId UNIQUEIDENTIFIER '$.correlacionId'
    );

    IF @nUsuarioId IS NULL
       OR @gSesionActor IS NULL
       OR @gSesionObjetivo IS NULL
    BEGIN
        SET @cMensaje = N'La solicitud no es valida.';
        GOTO __DESCO_Salida;
    END;

    SELECT
        @nSesionActorId = S.sesion_usuario_id,
        @nDispositivoActorId = S.dispositivo_usuario_id
    FROM [seg].[SesionUsuario] S
    INNER JOIN [seg].[Usuario] U ON U.usuario_id = S.usuario_id
    WHERE S.sesion_publica_id = @gSesionActor
      AND S.usuario_id = @nUsuarioId
      AND S.estado = 1
      AND S.fecha_revocacion IS NULL
      AND S.fecha_expiracion_renovacion > @dAhora
      AND S.token_version = U.token_version
      AND U.estado = 1
      AND U.estado_cuenta = 'ACTIVA';

    IF @nSesionActorId IS NULL
    BEGIN
        SET @cMensaje = N'La sesion actual no esta disponible.';
        GOTO __DESCO_Salida;
    END;

    SELECT
        @nSesionObjetivoId = S.sesion_usuario_id,
        @nDispositivoObjetivoId = S.dispositivo_usuario_id
    FROM [seg].[SesionUsuario] S
    WHERE S.sesion_publica_id = @gSesionObjetivo
      AND S.usuario_id = @nUsuarioId;

    IF @nSesionObjetivoId IS NULL
    BEGIN
        SET @cMensaje = N'La sesion seleccionada no esta disponible.';
        GOTO __DESCO_Salida;
    END;

    BEGIN TRY
        BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

        UPDATE [seg].[SesionUsuario]
        SET
            fecha_revocacion = COALESCE(fecha_revocacion, @dAhora),
            motivo_revocacion = COALESCE(motivo_revocacion, N'Cierre solicitado por el usuario.'),
            estado = 0
        WHERE sesion_usuario_id = @nSesionObjetivoId;

        UPDATE [seg].[RefreshTokenSesion]
        SET
            fecha_revocacion = COALESCE(fecha_revocacion, @dAhora),
            motivo_revocacion = COALESCE(motivo_revocacion, N'Cierre de sesion.'),
            estado = 0
        WHERE sesion_usuario_id = @nSesionObjetivoId
          AND estado = 1;

        /*
           Si el usuario cierra una sesion REMOTA, el dispositivo remoto deja
           de ser confiable. El logout de la sesion actual no elimina la
           confianza; de lo contrario el 2FA volveria a solicitarse despues de
           cada cierre normal de sesion dentro de los siete dias de vigencia.
        */
        IF @nSesionObjetivoId <> @nSesionActorId
           AND @nDispositivoObjetivoId IS NOT NULL
        BEGIN
            UPDATE [seg].[DispositivoUsuario]
            SET
                es_reconocido = 0,
                fecha_retiro_reconocimiento =
                    COALESCE(fecha_retiro_reconocimiento, @dAhora)
            WHERE dispositivo_usuario_id = @nDispositivoObjetivoId
              AND usuario_id = @nUsuarioId
              AND estado = 1
              AND es_reconocido = 1;
        END;

        EXEC [auditoria].[PA_Auditoria_Ins_Evento]
             @nUsuarioId = @nUsuarioId,
             @nSesionUsuarioId = @nSesionActorId,
             @nDispositivoUsuarioId = @nDispositivoActorId,
             @cAccion = 'CERRAR_SESION',
             @cEsquemaEntidad = N'seg',
             @cNombreEntidad = N'SesionUsuario',
             @cIdentificador = @gSesionObjetivo,
             @cMotivo = N'Sesion cerrada por el titular.',
             @cIp = @cIp,
             @cResultado = 'EXITOSO',
             @gCorrelacionId = @gCorrelacionId,
             @cEndpoint = N'/api/mi-cuenta/sesiones/cerrar',
             @nAuditoriaEventoId = @nAuditoriaId OUTPUT;

        BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;

        SET @bResultado = 1;
        SET @cMensaje = N'Sesion cerrada correctamente.';
    END TRY
    BEGIN CATCH
SET @bResultado = 0;

        IF XACT_STATE() <> 0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;

        SET @bResultado = 0;
        SET @cMensaje = N'No se pudo cerrar la sesion. Intente nuevamente.';
    
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Sesion_Upd_Cerrar',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 1;
END;
END CATCH;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Sesion_Upd_Cerrar',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 1;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Sesion_Upd_Cerrar',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 1;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'seg.PA_Sesion_Upd_Cerrar',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

