/* 3. Cambiar contexto es una comodidad de sesion, no un permiso de negocio. */
CREATE OR ALTER PROCEDURE seg.PA_Sesion_Upd_ContextoUOT
 @nUsuarioId BIGINT,@nSesionUsuarioId BIGINT,@cModo VARCHAR(12),@nUotId BIGINT=NULL,
 @bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SET @bResultado=0; SET @cMensaje=N'No se pudo cambiar el contexto de trabajo.';
 SET @cModo=UPPER(NULLIF(LTRIM(RTRIM(@cModo)),''));
 IF NOT EXISTS(SELECT 1 FROM seg.SesionUsuario WHERE sesion_usuario_id=@nSesionUsuarioId AND usuario_id=@nUsuarioId AND estado=1 AND fecha_revocacion IS NULL)
 BEGIN SET @cMensaje=N'La sesion ya no esta disponible.'; RETURN 1; END;
 IF @cModo='ESPECIFICA'
 BEGIN
   IF @nUotId IS NULL OR seg.FN_Usuario_TieneAccesoUOT(@nUsuarioId,@nUotId)=0
   BEGIN SET @cMensaje=N'No tiene acceso a la UOT seleccionada.'; RETURN 1; END;
 END
 ELSE IF @cModo='GENERAL'
 BEGIN
   IF @nUotId IS NOT NULL BEGIN SET @cMensaje=N'El modo general no utiliza una UOT especifica.'; RETURN 1; END;
   IF (SELECT COUNT(*) FROM seg.UsuarioUOT UU JOIN org.UOT U ON U.uot_id=UU.uot_id AND U.estado=1 WHERE UU.usuario_id=@nUsuarioId AND UU.estado=1 AND UU.fecha_hasta IS NULL AND UU.fecha_desde<=SYSUTCDATETIME())<2
   BEGIN SET @cMensaje=N'El modo general requiere acceso a mas de una UOT.'; RETURN 1; END;
 END
 ELSE BEGIN SET @cMensaje=N'El modo de trabajo no es valido.'; RETURN 1; END;
 UPDATE seg.SesionUsuario
    SET modo_uot=@cModo,uot_contexto_id=CASE WHEN @cModo='ESPECIFICA' THEN @nUotId ELSE NULL END,fecha_ultima_actividad=SYSUTCDATETIME()
 WHERE sesion_usuario_id=@nSesionUsuarioId;
 SET @bResultado=1; SET @cMensaje=N'Contexto actualizado.'; RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- seg.PA_Sesion_Upd_RotarRefreshToken
CREATE OR ALTER PROCEDURE [seg].[PA_Sesion_Upd_RotarRefreshToken]
(
    @cJson                   NVARCHAR(MAX),
    @nUsuarioId              BIGINT OUTPUT,
    @nTokenVersion           INT OUTPUT,
    @dExpiracionRenovacion   DATETIME2(0) OUTPUT,
    @bResultado              BIT OUTPUT,
    @cMensaje                NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    /* DESCO_SEGURIDAD_V2_20260825 */
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @gSesionPublicaId UNIQUEIDENTIFIER,
        @cTokenActualHashHex VARCHAR(128),
        @binTokenActualHash VARBINARY(64),
        @cTokenNuevoHashHex VARCHAR(128),
        @binTokenNuevoHash VARBINARY(64),
        @cIp VARCHAR(64),
        @gCorrelacionId UNIQUEIDENTIFIER,
        @dAhora DATETIME2(0) = SYSUTCDATETIME(),
        @nSesionId BIGINT,
        @nRefreshActualId BIGINT,
        @nRefreshNuevoId BIGINT,
        @bTokenActualActivo BIT,
        @nDispositivoId BIGINT,
        @nAuditoriaId BIGINT;

    SET @nUsuarioId = NULL;
    SET @nTokenVersion = NULL;
    SET @dExpiracionRenovacion = NULL;
    SET @bResultado = 0;
    SET @cMensaje = N'La sesion ya no esta disponible. Inicie sesion nuevamente.';

    IF @cJson IS NULL OR ISJSON(@cJson) <> 1
    BEGIN
        GOTO __DESCO_Salida;
    END;

    SELECT
        @gSesionPublicaId = sesionPublicaId,
        @cTokenActualHashHex = NULLIF(LTRIM(RTRIM(refreshTokenActualHashHex)), ''),
        @cTokenNuevoHashHex = NULLIF(LTRIM(RTRIM(refreshTokenNuevoHashHex)), ''),
        @cIp = NULLIF(LTRIM(RTRIM(ip)), ''),
        @gCorrelacionId = correlacionId
    FROM OPENJSON(@cJson)
    WITH
    (
        sesionPublicaId UNIQUEIDENTIFIER '$.sesionPublicaId',
        refreshTokenActualHashHex VARCHAR(128) '$.refreshTokenActualHashHex',
        refreshTokenNuevoHashHex VARCHAR(128) '$.refreshTokenNuevoHashHex',
        ip VARCHAR(64) '$.ip',
        correlacionId UNIQUEIDENTIFIER '$.correlacionId'
    );

    SET @binTokenActualHash = TRY_CONVERT(VARBINARY(64), @cTokenActualHashHex, 2);
    SET @binTokenNuevoHash = TRY_CONVERT(VARBINARY(64), @cTokenNuevoHashHex, 2);

    IF @gSesionPublicaId IS NULL
       OR @binTokenActualHash IS NULL
       OR @binTokenNuevoHash IS NULL
       OR @binTokenActualHash = @binTokenNuevoHash
    BEGIN
        GOTO __DESCO_Salida;
    END;

    BEGIN TRY
        BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

        SELECT
            @nSesionId = S.sesion_usuario_id,
            @nUsuarioId = S.usuario_id,
            @nTokenVersion = U.token_version,
            @dExpiracionRenovacion = S.fecha_expiracion_renovacion,
            @nDispositivoId = S.dispositivo_usuario_id
        FROM [seg].[SesionUsuario] S WITH (UPDLOCK, HOLDLOCK)
        INNER JOIN [seg].[Usuario] U
            ON U.usuario_id = S.usuario_id
        INNER JOIN [org].[Empleado] E
            ON E.empleado_id = U.persona_id
        WHERE S.sesion_publica_id = @gSesionPublicaId
          AND S.estado = 1
          AND S.fecha_revocacion IS NULL
          AND S.fecha_expiracion_renovacion > @dAhora
          AND S.token_version = U.token_version
          AND U.estado = 1
          AND U.estado_cuenta = 'ACTIVA'
          AND (U.bloqueado_hasta IS NULL OR U.bloqueado_hasta <= @dAhora)
          AND E.estado = 1;

        IF @nSesionId IS NULL
        BEGIN
            BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
            SET @nUsuarioId = NULL;
            SET @nTokenVersion = NULL;
            SET @dExpiracionRenovacion = NULL;
            GOTO __DESCO_Salida;
        END;

        SELECT
            @nRefreshActualId = RT.refresh_token_sesion_id,
            @bTokenActualActivo =
                CASE
                    WHEN RT.estado = 1
                     AND RT.fecha_uso IS NULL
                     AND RT.fecha_revocacion IS NULL
                     AND RT.fecha_expiracion > @dAhora
                    THEN 1 ELSE 0
                END
        FROM [seg].[RefreshTokenSesion] RT WITH (UPDLOCK, HOLDLOCK)
        WHERE RT.sesion_usuario_id = @nSesionId
          AND RT.token_hash = @binTokenActualHash;

        IF @nRefreshActualId IS NULL OR ISNULL(@bTokenActualActivo, 0) = 0
        BEGIN
            /*
               El token no corresponde o ya fue usado: se trata como posible
               replay y se revoca la sesion completa.
            */
            UPDATE [seg].[SesionUsuario]
            SET
                fecha_revocacion = COALESCE(fecha_revocacion, @dAhora),
                motivo_revocacion = COALESCE(motivo_revocacion, N'Reutilizacion o token de renovacion no valido.'),
                estado = 0
            WHERE sesion_usuario_id = @nSesionId;

            UPDATE [seg].[RefreshTokenSesion]
            SET
                fecha_revocacion = COALESCE(fecha_revocacion, @dAhora),
                motivo_revocacion = COALESCE(motivo_revocacion, N'Reutilizacion o token de renovacion no valido.'),
                estado = 0
            WHERE sesion_usuario_id = @nSesionId
              AND estado = 1;

            EXEC [auditoria].[PA_Auditoria_Ins_Evento]
                 @nUsuarioId = @nUsuarioId,
                 @nSesionUsuarioId = @nSesionId,
                 @nDispositivoUsuarioId = @nDispositivoId,
                 @cAccion = 'REFRESH_TOKEN_RECHAZADO',
                 @cEsquemaEntidad = N'seg',
                 @cNombreEntidad = N'SesionUsuario',
                 @cIdentificador = @gSesionPublicaId,
                 @cMotivo = N'Se revoco la sesion por un token de renovacion no valido o reutilizado.',
                 @cIp = @cIp,
                 @cResultado = 'RECHAZADO',
                 @gCorrelacionId = @gCorrelacionId,
                 @cEndpoint = N'/api/auth/refresh',
                 @nAuditoriaEventoId = @nAuditoriaId OUTPUT;

            BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;

            SET @nUsuarioId = NULL;
            SET @nTokenVersion = NULL;
            SET @dExpiracionRenovacion = NULL;
            SET @cMensaje = N'La sesion ya no esta disponible. Inicie sesion nuevamente.';
            GOTO __DESCO_Salida;
        END;

        IF EXISTS
        (
            SELECT 1
            FROM [seg].[RefreshTokenSesion]
            WHERE token_hash = @binTokenNuevoHash
        )
        BEGIN
            BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;

            SET @nUsuarioId = NULL;
            SET @nTokenVersion = NULL;
            SET @dExpiracionRenovacion = NULL;
            SET @cMensaje = N'No se pudo renovar la sesion. Intente nuevamente.';
            GOTO __DESCO_Salida;
        END;

        INSERT INTO [seg].[RefreshTokenSesion]
        (
            sesion_usuario_id,
            token_hash,
            token_padre_id,
            fecha_emision,
            fecha_expiracion,
            estado
        )
        VALUES
        (
            @nSesionId,
            @binTokenNuevoHash,
            @nRefreshActualId,
            @dAhora,
            @dExpiracionRenovacion,
            1
        );

        SET @nRefreshNuevoId = SCOPE_IDENTITY();

        UPDATE [seg].[RefreshTokenSesion]
        SET
            fecha_uso = @dAhora,
            token_reemplazo_id = @nRefreshNuevoId,
            estado = 0
        WHERE refresh_token_sesion_id = @nRefreshActualId
          AND estado = 1
          AND fecha_uso IS NULL
          AND fecha_revocacion IS NULL;

        IF @@ROWCOUNT <> 1
        BEGIN
            BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;

            SET @nUsuarioId = NULL;
            SET @nTokenVersion = NULL;
            SET @dExpiracionRenovacion = NULL;
            SET @cMensaje = N'La sesion ya no esta disponible. Inicie sesion nuevamente.';
            GOTO __DESCO_Salida;
        END;

        UPDATE [seg].[SesionUsuario]
        SET
            fecha_ultima_actividad = @dAhora,
            ip_ultima_actividad = COALESCE(@cIp, ip_ultima_actividad)
        WHERE sesion_usuario_id = @nSesionId;

        IF @nDispositivoId IS NOT NULL
        BEGIN
            UPDATE [seg].[DispositivoUsuario]
            SET
                fecha_ultima_actividad = @dAhora,
                ultima_ip = COALESCE(@cIp, ultima_ip)
            WHERE dispositivo_usuario_id = @nDispositivoId;
        END;

        BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;

        SET @bResultado = 1;
        SET @cMensaje = N'Sesion renovada correctamente.';
    END TRY
    BEGIN CATCH
SET @bResultado = 0;

        IF XACT_STATE() <> 0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;

        SET @nUsuarioId = NULL;
        SET @nTokenVersion = NULL;
        SET @dExpiracionRenovacion = NULL;
        SET @bResultado = 0;
        SET @cMensaje = N'No se pudo renovar la sesion. Intente nuevamente.';
    
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Sesion_Upd_RotarRefreshToken',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 1;
END;
END CATCH;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Sesion_Upd_RotarRefreshToken',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 1;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Sesion_Upd_RotarRefreshToken',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 1;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'seg.PA_Sesion_Upd_RotarRefreshToken',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

/* 4. Resolver contexto. GENERAL nunca otorga permiso: solo agrega UOT autorizadas. */
CREATE OR ALTER PROCEDURE seg.PA_UOT_Sel_ResolverContextoSesion
    @nUsuarioId BIGINT,@nSesionUsuarioId BIGINT,@nUotSolicitada BIGINT=NULL,
    @cCodigoPermiso VARCHAR(40)=NULL,@bRequiereUot BIT=1,
    @nUotId BIGINT OUTPUT,@bModoGeneral BIT OUTPUT,@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SELECT @nUotId=NULL,@bModoGeneral=0,@bResultado=0,@cMensaje=N'No se pudo validar la UOT.';
 DECLARE @Modo VARCHAR(12),@UotSesion BIGINT;
 SELECT @Modo=modo_uot,@UotSesion=uot_contexto_id FROM seg.SesionUsuario
 WHERE sesion_usuario_id=@nSesionUsuarioId AND usuario_id=@nUsuarioId AND estado=1 AND fecha_revocacion IS NULL;
 IF @Modo IS NULL BEGIN SET @cMensaje=N'La sesion ya no esta disponible.'; RETURN 1; END;
 IF @Modo='GENERAL'
 BEGIN
   SET @bModoGeneral=1; SET @nUotId=@nUotSolicitada;
   IF @bRequiereUot=1 AND @nUotId IS NULL BEGIN SET @cMensaje=N'Seleccione una UOT.'; RETURN 1; END;
 END
 ELSE
 BEGIN
   SET @nUotId=@UotSesion;
   IF @nUotId IS NULL BEGIN SET @cMensaje=N'Seleccione una UOT.'; RETURN 1; END;
   IF @nUotSolicitada IS NOT NULL AND @nUotSolicitada<>@nUotId BEGIN SET @cMensaje=N'La UOT no corresponde al contexto actual.'; RETURN 1; END;
 END;
 IF @nUotId IS NOT NULL
 BEGIN
   IF seg.FN_Usuario_TieneAccesoUOT(@nUsuarioId,@nUotId)=0 BEGIN SET @cMensaje=N'No tiene acceso a la UOT.'; RETURN 1; END;
   IF NULLIF(@cCodigoPermiso,'') IS NOT NULL AND seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,@nUotId,@cCodigoPermiso)=0
   BEGIN SET @cMensaje=N'No tiene permiso para esta accion en la UOT.'; RETURN 1; END;
 END
 ELSE IF NOT EXISTS(
   SELECT 1 FROM seg.UsuarioUOT UU JOIN org.UOT U ON U.uot_id=UU.uot_id AND U.estado=1
   WHERE UU.usuario_id=@nUsuarioId AND UU.estado=1 AND UU.fecha_hasta IS NULL AND UU.fecha_desde<=SYSUTCDATETIME()
     AND (NULLIF(@cCodigoPermiso,'') IS NULL OR seg.FN_Usuario_TienePermisoUOT(@nUsuarioId,UU.uot_id,@cCodigoPermiso)=1)
 )
 BEGIN SET @cMensaje=N'No tiene UOT disponibles para esta accion.'; RETURN 1; END;
 SET @bResultado=1; SET @cMensaje=N'UOT validada.'; RETURN 0;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- seg.PA_Usuario_Ins_CrearCuenta
CREATE OR ALTER PROCEDURE [seg].[PA_Usuario_Ins_CrearCuenta]
(
    @cJson       NVARCHAR(MAX),
    @nUsuarioId  BIGINT OUTPUT,
    @bResultado  BIT OUTPUT,
    @cMensaje    NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    /* DESCO_SEGURIDAD_V2_20260825 */
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @nUsuarioActorId BIGINT,
        @gSesionPublicaId UNIQUEIDENTIFIER,
        @nEmpleadoId BIGINT,
        @cNombreUsuario VARCHAR(80),
        @cPasswordHash VARCHAR(512),
        @cCorreoSeguridad NVARCHAR(320),
        @cCorreoNormalizado NVARCHAR(320),
        @bRequiereCambioPassword BIT = 1,
        @cIp VARCHAR(64),
        @gCorrelacionId UNIQUEIDENTIFIER,
        @bAutorizado BIT,
        @nSesionActorId BIGINT,
        @nDispositivoActorId BIGINT,
        @nCorreoId BIGINT,
        @nAuditoriaId BIGINT,
        @dAhora DATETIME2(0) = SYSUTCDATETIME();

    SET @nUsuarioId = NULL;
    SET @bResultado = 0;
    SET @cMensaje = N'No se pudo crear la cuenta. Intente nuevamente.';

    IF @cJson IS NULL OR ISJSON(@cJson) <> 1
    BEGIN
        SET @cMensaje = N'La solicitud no es valida.';
        GOTO __DESCO_Salida;
    END;

    SELECT
        @nUsuarioActorId = usuarioActorId,
        @gSesionPublicaId = sesionPublicaId,
        @nEmpleadoId = empleadoId,
        @cNombreUsuario = LOWER(NULLIF(LTRIM(RTRIM(nombreUsuario)), '')),
        @cPasswordHash = NULLIF(LTRIM(RTRIM(passwordHash)), ''),
        @cCorreoSeguridad = NULLIF(LTRIM(RTRIM(correoSeguridad)), N''),
        @bRequiereCambioPassword = COALESCE(requiereCambioPassword, CONVERT(BIT,1)),
        @cIp = NULLIF(LTRIM(RTRIM(ip)), ''),
        @gCorrelacionId = correlacionId
    FROM OPENJSON(@cJson)
    WITH
    (
        usuarioActorId BIGINT '$.usuarioActorId',
        sesionPublicaId UNIQUEIDENTIFIER '$.sesionPublicaId',
        empleadoId BIGINT '$.empleadoId',
        nombreUsuario VARCHAR(80) '$.nombreUsuario',
        passwordHash VARCHAR(512) '$.passwordHash',
        correoSeguridad NVARCHAR(320) '$.correoSeguridad',
        requiereCambioPassword BIT '$.requiereCambioPassword',
        ip VARCHAR(64) '$.ip',
        correlacionId UNIQUEIDENTIFIER '$.correlacionId'
    );

    IF @nUsuarioActorId IS NULL
       OR @gSesionPublicaId IS NULL
       OR @nEmpleadoId IS NULL
       OR @cNombreUsuario IS NULL
       OR @cPasswordHash IS NULL
       OR @cCorreoSeguridad IS NULL
    BEGIN
        SET @cMensaje = N'Complete los datos requeridos para crear la cuenta.';
        GOTO __DESCO_Salida;
    END;

    IF LEN(@cNombreUsuario) < 3
    BEGIN
        SET @cMensaje = N'Ingrese un nombre de usuario valido.';
        GOTO __DESCO_Salida;
    END;

    /*
       Validacion minima del formato PHC. La fortaleza/parametros de Argon2id
       se validan en el backend, que es donde vive la libreria criptografica.
    */
    IF LEFT(@cPasswordHash, 10) <> '$argon2id$'
    BEGIN
        SET @cMensaje = N'No se pudo procesar la credencial de la cuenta.';
        GOTO __DESCO_Salida;
    END;

    IF @cCorreoSeguridad NOT LIKE N'%_@_%._%'
    BEGIN
        SET @cMensaje = N'Ingrese un correo de seguridad valido.';
        GOTO __DESCO_Salida;
    END;

    SET @cCorreoNormalizado = LOWER(LTRIM(RTRIM(@cCorreoSeguridad)));
    IF @gCorrelacionId IS NULL SET @gCorrelacionId = NEWID();

    EXEC [seg].[PA_Autorizacion_Sel_ValidarPermiso]
         @nUsuarioId = @nUsuarioActorId,
         @gSesionPublicaId = @gSesionPublicaId,
         @cCodigoPermiso = 'USUARIOS_CREAR',
         @bAutorizado = @bAutorizado OUTPUT;

    IF ISNULL(@bAutorizado, 0) = 0
    BEGIN
        SET @cMensaje = N'No cuenta con permiso para crear cuentas de usuario.';
        GOTO __DESCO_Salida;
    END;

    SELECT
        @nSesionActorId = S.sesion_usuario_id,
        @nDispositivoActorId = S.dispositivo_usuario_id
    FROM [seg].[SesionUsuario] S
    WHERE S.sesion_publica_id = @gSesionPublicaId
      AND S.usuario_id = @nUsuarioActorId;

    IF NOT EXISTS
    (
        SELECT 1
        FROM [org].[Empleado] E
        INNER JOIN [org].[Persona] P ON P.persona_id = E.empleado_id
        WHERE E.empleado_id = @nEmpleadoId
          AND E.estado = 1
          AND P.estado = 1
          AND E.fecha_cese IS NULL
    )
    BEGIN
        SET @cMensaje = N'El empleado seleccionado no esta disponible para crear una cuenta.';
        GOTO __DESCO_Salida;
    END;

    IF EXISTS
    (
        SELECT 1 FROM [seg].[Usuario] U
        WHERE U.persona_id = @nEmpleadoId
    )
    BEGIN
        SET @cMensaje = N'El empleado seleccionado ya tiene una cuenta registrada.';
        GOTO __DESCO_Salida;
    END;

    IF EXISTS
    (
        SELECT 1 FROM [seg].[Usuario] U
        WHERE LOWER(U.nombre_usuario) = @cNombreUsuario
    )
    BEGIN
        SET @cMensaje = N'El nombre de usuario ya se encuentra registrado.';
        GOTO __DESCO_Salida;
    END;

    BEGIN TRY
        BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

        INSERT INTO [seg].[Usuario]
        (
            persona_id,
            nombre_usuario,
            password_hash,
            estado,
            fecha_creacion,
            estado_cuenta,
            intentos_fallidos,
            fecha_ultimo_intento_fallido,
            bloqueado_hasta,
            ultimo_acceso_correcto,
            fecha_cambio_password,
            requiere_cambio_password,
            segundo_factor_habilitado,
            token_version
        )
        VALUES
        (
            @nEmpleadoId,
            @cNombreUsuario,
            @cPasswordHash,
            1,
            @dAhora,
            'PENDIENTE_VALIDACION',
            0,
            NULL,
            NULL,
            NULL,
            @dAhora,
            @bRequiereCambioPassword,
            0,
            1
        );

        SET @nUsuarioId = CONVERT(BIGINT, SCOPE_IDENTITY());

        INSERT INTO [seg].[UsuarioCorreoSeguridad]
        (
            usuario_id,
            correo,
            correo_normalizado,
            es_principal,
            es_verificado,
            fecha_desde,
            creado_por_usuario_id,
            motivo_cambio,
            estado
        )
        VALUES
        (
            @nUsuarioId,
            @cCorreoSeguridad,
            @cCorreoNormalizado,
            1,
            0,
            @dAhora,
            @nUsuarioActorId,
            N'Correo inicial de seguridad.',
            1
        );

        SET @nCorreoId = CONVERT(BIGINT, SCOPE_IDENTITY());

        /*
           Se crea historial desde el primer hash para que las futuras politicas
           de no reutilizacion puedan consultar una sola fuente historica.
        */
        INSERT INTO [seg].[HistorialPassword]
        (
            usuario_id,
            password_hash,
            fecha_desde,
            cambiado_por_usuario_id,
            motivo,
            estado
        )
        VALUES
        (
            @nUsuarioId,
            @cPasswordHash,
            @dAhora,
            @nUsuarioActorId,
            N'Credencial inicial de la cuenta.',
            1
        );

        EXEC [auditoria].[PA_Auditoria_Ins_Evento]
             @nUsuarioId = @nUsuarioActorId,
             @nSesionUsuarioId = @nSesionActorId,
             @nDispositivoUsuarioId = @nDispositivoActorId,
             @cAccion = 'CREAR_CUENTA',
             @cEsquemaEntidad = N'seg',
             @cNombreEntidad = N'Usuario',
             @cIdentificador = @nUsuarioId,
             @cDatosAnteriores = NULL,
