        @nDispositivoId BIGINT,
        @cNuevoPasswordHash VARCHAR(512),
        @cHashAnterior VARCHAR(512),
        @cIp VARCHAR(64),
        @gCorrelacionId UNIQUEIDENTIFIER,
        @dAhora DATETIME2(0) = SYSUTCDATETIME(),
        @nSesionesRevocadas INT,
        @nNotificacionId BIGINT,
