    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_Usuario_Upd_ConfirmarCambioCorreo',
    @cMensaje = @cMensaje OUTPUT,
