        (
            usuario_id,
            identificador_ingresado_hash,
            dispositivo_usuario_id,
            fecha_hora,
            resultado,
            ip,
            user_agent,
            estado
        )
        VALUES
        (
            @nUsuarioId,
            @binIdentificadorHash,
            NULL,
