-- seg.PA_UsuarioAdmin_Ins_CrearCuenta
CREATE OR ALTER PROCEDURE [seg].[PA_UsuarioAdmin_Ins_CrearCuenta]
(
    @cJson NVARCHAR(MAX),
    @nUsuarioNuevoId BIGINT OUTPUT,
    @bResultado BIT OUTPUT,
    @cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS
BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;
    SET ANSI_NULLS ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    BEGIN TRY

    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,
        @gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),
        @nOp BIGINT,@bRep BIT,@cEstadoOp VARCHAR(20),@cIdRes NVARCHAR(200),@cCodRes VARCHAR(40),
        @bIni BIT,@cMsg NVARCHAR(300),@bFin BIT,@cMsgFin NVARCHAR(300),
        @nAud BIGINT,@nTrans BIGINT,@nEmpleado BIGINT,@cNombre VARCHAR(80),
        @cHash VARCHAR(512),@cCorreo NVARCHAR(320),@cCorreoN NVARCHAR(320),
        @bCambio BIT,@cIdent NVARCHAR(200),@cRolesJson NVARCHAR(MAX),
        @bDelegable BIT,@cMsgDelegacion NVARCHAR(300);

    SELECT @nUsuarioNuevoId=NULL,@bResultado=0,@cMensaje=N'No se pudo crear la cuenta.';

    EXEC [seg].[PA_Operacion_Ins_IniciarIdempotente]
         @cJson=@cJson,@cCodigoPermiso='USUARIOS_CREAR',@cAmbito='USUARIO_CREAR',
         @nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,
         @nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,
         @nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,
         @gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,
         @nOperacionIdempotenteId=@nOp OUTPUT,@bEsRepetida=@bRep OUTPUT,
         @cEstadoOperacion=@cEstadoOp OUTPUT,@cIdentificadorResultado=@cIdRes OUTPUT,
         @cCodigoResultado=@cCodRes OUTPUT,@bResultado=@bIni OUTPUT,@cMensaje=@cMsg OUTPUT;

    IF @bIni=0 AND @bRep=0
    BEGIN
        SET @cMensaje=@cMsg;
        GOTO __DESCO_Salida;
    END;

    IF @bRep=1
    BEGIN
        IF @cEstadoOp='COMPLETADA'
            SET @nUsuarioNuevoId=TRY_CONVERT(BIGINT,@cIdRes);

        SET @bResultado=CASE WHEN @cEstadoOp='COMPLETADA' THEN 1 ELSE 0 END;
        SET @cMensaje=CASE WHEN @cEstadoOp='COMPLETADA'
                           THEN N'La solicitud ya fue procesada correctamente.'
                           ELSE N'La solicitud ya se encuentra en proceso.' END;
        GOTO __DESCO_Salida;
    END;

    SELECT
        @nEmpleado=empleadoId,
        @cNombre=LOWER(NULLIF(LTRIM(RTRIM(nombreUsuario)),'')),
        @cHash=NULLIF(LTRIM(RTRIM(passwordHash)),''),
        @cCorreo=NULLIF(LTRIM(RTRIM(correoSeguridad)),N''),
        @bCambio=COALESCE(requiereCambioPassword,CONVERT(BIT,1))
    FROM OPENJSON(@cJson,'$.usuario')
    WITH
    (
        empleadoId BIGINT '$.empleadoId',
        nombreUsuario VARCHAR(80) '$.nombreUsuario',
        passwordHash VARCHAR(512) '$.passwordHash',
        correoSeguridad NVARCHAR(320) '$.correoSeguridad',
        requiereCambioPassword BIT '$.requiereCambioPassword'
    );

    SET @cCorreoN=LOWER(@cCorreo);
    SET @cRolesJson=JSON_QUERY(@cJson,'$.roles');

    IF NOT EXISTS
    (
        SELECT 1
        FROM [org].[Empleado] E
        INNER JOIN [org].[Persona] P ON P.persona_id=E.empleado_id
        WHERE E.empleado_id=@nEmpleado
          AND E.estado=1
          AND P.estado=1
    )
       OR @cNombre IS NULL
       OR LEN(@cNombre)<3
       OR @cHash IS NULL
       OR LEFT(@cHash,10)<>'$argon2id$'
       OR @cCorreo IS NULL
       OR @cCorreo NOT LIKE N'%_@_%._%'
    BEGIN
        SET @cMensaje=N'Complete correctamente los datos de la cuenta.';
        GOTO Fallar;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM [seg].[Usuario]
        WHERE persona_id=@nEmpleado OR nombre_usuario=@cNombre
    )
    BEGIN
        SET @cMensaje=N'El empleado ya tiene una cuenta o el nombre de usuario no está disponible.';
        GOTO Fallar;
    END;

    EXEC [seg].[PA_Autorizacion_Sel_ValidarDelegacionRoles]
         @nUsuarioActorId=@nUsuario,
         @cRolesJson=@cRolesJson,
         @bRequerirAlMenosUno=1,
         @bResultado=@bDelegable OUTPUT,
         @cMensaje=@cMsgDelegacion OUTPUT;

    IF @bDelegable=0
    BEGIN
        SET @cMensaje=@cMsgDelegacion;
        GOTO Fallar;
    END;

    BEGIN TRY
        BEGIN
    IF @__DbTranEntrada = 0 BEGIN TRANSACTION;
    ELSE SAVE TRANSACTION @__DbSavepoint;
    SET @__DbTranAbierta = 1;
END;

        INSERT [seg].[Usuario]
        (
            persona_id,nombre_usuario,password_hash,estado,fecha_creacion,estado_cuenta,
            intentos_fallidos,requiere_cambio_password,segundo_factor_habilitado,token_version
        )
        VALUES
        (
            @nEmpleado,@cNombre,@cHash,1,SYSUTCDATETIME(),'PENDIENTE_VALIDACION',
            0,@bCambio,0,1
        );

        SET @nUsuarioNuevoId=SCOPE_IDENTITY();

        INSERT [seg].[UsuarioCorreoSeguridad]
        (
            usuario_id,correo,correo_normalizado,es_principal,es_verificado,
            fecha_verificacion,fecha_desde,fecha_hasta,creado_por_usuario_id,
            motivo_cambio,estado
        )
        VALUES
        (
            @nUsuarioNuevoId,@cCorreo,@cCorreoN,1,0,NULL,SYSUTCDATETIME(),NULL,
            @nUsuario,N'Correo inicial de seguridad.',1
        );

        INSERT [seg].[UsuarioRol]
        (
            usuario_id,rol_id,fecha_desde,fecha_hasta,estado,asignado_por_usuario_id
        )
        SELECT
            @nUsuarioNuevoId,
            J.rolId,
            SYSUTCDATETIME(),
            NULL,
            1,
            @nUsuario
        FROM
        (
            SELECT DISTINCT rolId
            FROM OPENJSON(@cRolesJson)
            WITH(rolId BIGINT '$.rolId')
        ) J;

        SET @cIdent=CONVERT(NVARCHAR(200),@nUsuarioNuevoId);

        EXEC [auditoria].[PA_Operacion_Ins_RegistrarCambio]
             @nUsuario,@nSesion,@nDisp,@nModulo,'CREAR','seg','Usuario',@cIdent,
             NULL,NULL,NULL,'estado_cuenta',NULL,'PENDIENTE_VALIDACION',
             @cIp,@gCorr,@gSol,@cEnd,@nAud OUTPUT,@nTrans OUTPUT;

        /* Confirmar datos e idempotencia juntos. */

        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
             @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='COMPLETADA',
             @cEsquemaEntidad='seg',@cNombreEntidad='Usuario',
             @cIdentificadorResultado=@cIdent,@cCodigoResultado='USUARIO_CREADO',
             @bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;
IF ISNULL(@bFin,0) = 0
    THROW 51003, N'DESCO_IDEMPOTENCIA_NO_CERRADA', 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 COMMIT TRANSACTION;
        SET @__DbTranAbierta = 0;
    END;
END;

        SET @bResultado=1;
        SET @cMensaje=N'Cuenta creada correctamente. Debe validar su correo antes de ingresar.';
        GOTO __DESCO_Salida;
    END TRY
    BEGIN CATCH
SET @bResultado = 0;

        IF XACT_STATE()<>0 BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
        SET @cMensaje=N'No se pudo crear la cuenta. Intente nuevamente.';
    
IF ISNULL(@bResultado,0) = 0
BEGIN
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_UsuarioAdmin_Ins_CrearCuenta',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END;
END CATCH;

Fallar:
    IF @nOp IS NOT NULL AND @bResultado=0
        EXEC [auditoria].[PA_OperacionIdempotente_Upd_Finalizar]
             @nOperacionIdempotenteId=@nOp,@cEstadoOperacion='FALLIDA',
             @cEsquemaEntidad=NULL,@cNombreEntidad=NULL,@cIdentificadorResultado=NULL,
             @cCodigoResultado='NO_PROCESADO',@bResultado=@bFin OUTPUT,@cMensaje=@cMsgFin OUTPUT;

    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_UsuarioAdmin_Ins_CrearCuenta',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

    IF @bResultado = 0 AND @nOp IS NOT NULL AND XACT_STATE() <> -1
    BEGIN
        IF ISNULL(@bRep,0) = 0
        BEGIN
        BEGIN TRY
            EXEC [auditoria].[PA_OperacionIdempotente_Upd_MensajeFallido]
                 @nOperacionIdempotenteId = @nOp, @cMensajeResultado = @cMensaje;
        END TRY
        BEGIN CATCH
            -- No sustituir el motivo funcional por un fallo de registro secundario.
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_UsuarioAdmin_Ins_CrearCuenta',
    @cMensaje = @__DbMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
        END CATCH;
        END
        ELSE
        BEGIN
            SELECT @cMensaje = COALESCE(mensaje_resultado,
                CASE WHEN estado_operacion = 'FALLIDA'
                     THEN N'La solicitud anterior no se completó. Corrija los datos y envíe una nueva solicitud.'
                     ELSE N'La solicitud todavía se está procesando. Consulte el resultado antes de repetirla.' END)
            FROM [auditoria].[OperacionIdempotente]
            WHERE operacion_idempotente_id = @nOp;
        END;
    END;
IF @bResultado = 0
    SELECT @nUsuarioNuevoId = NULL;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_UsuarioAdmin_Ins_CrearCuenta',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'seg.PA_UsuarioAdmin_Ins_CrearCuenta',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO


-- seg.PA_UsuarioAdmin_Sel_Detalle
CREATE OR ALTER PROCEDURE [seg].[PA_UsuarioAdmin_Sel_Detalle](@cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;

    BEGIN TRY
  SET NOCOUNT ON;
DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@bCtx BIT,@cMsg NVARCHAR(300);
SELECT @bResultado=0,@cMensaje=N'No se pudo consultar el usuario.';
EXEC seg.PA_Operacion_Sel_ContextoAutorizado @cJson=@cJson,@cCodigoPermiso='USUARIOS_VER',@nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@bResultado=@bCtx OUTPUT,@cMensaje=@cMsg OUTPUT;
IF @bCtx=0 BEGIN SET @cMensaje=@cMsg;
GOTO __DESCO_Salida;
END;
 DECLARE @nId BIGINT;
SELECT @nId=COALESCE(TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.usuario.usuarioId')),TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.usuarioId')),TRY_CONVERT(BIGINT,JSON_VALUE(@cJson,'$.filtros.usuarioId')));
IF NOT EXISTS(SELECT 1 FROM seg.Usuario WHERE usuario_id=@nId) BEGIN SET @cMensaje=N'El usuario seleccionado no está disponible.';
GOTO __DESCO_Salida;
END;
SELECT U.usuario_id usuarioId,U.nombre_usuario nombreUsuario,U.estado_cuenta estadoCuenta,U.estado,U.fecha_creacion fechaCreacion,U.ultimo_acceso_correcto ultimoAccesoCorrecto,U.fecha_cambio_password fechaCambioPassword,U.requiere_cambio_password requiereCambioPassword,U.segundo_factor_habilitado segundoFactorHabilitado,E.empleado_id empleadoId,P.numero_documento numeroDocumento,CONCAT(P.nombres,N' ',P.apellido_paterno,N' ',COALESCE(P.apellido_materno,N'')) empleado FROM seg.Usuario U INNER JOIN org.Empleado E ON E.empleado_id=U.persona_id INNER JOIN org.Persona P ON P.persona_id=U.persona_id WHERE U.usuario_id=@nId;
SELECT R.rol_id rolId,R.codigo,R.nombre,UR.fecha_desde fechaDesde,UR.fecha_hasta fechaHasta,UR.estado FROM seg.UsuarioRol UR INNER JOIN seg.Rol R ON R.rol_id=UR.rol_id WHERE UR.usuario_id=@nId ORDER BY UR.fecha_desde DESC;
SELECT D.dispositivo_usuario_id dispositivoUsuarioId,D.navegador,D.sistema_operativo sistemaOperativo,D.fecha_primera_deteccion primeraDeteccion,D.fecha_ultima_actividad ultimaActividad,D.es_reconocido esReconocido,D.fecha_reconocimiento fechaReconocimiento,D.fecha_retiro_reconocimiento fechaRetiroReconocimiento,D.estado FROM seg.DispositivoUsuario D WHERE D.usuario_id=@nId ORDER BY D.fecha_ultima_actividad DESC;
SET @bResultado=1;
SET @cMensaje=N'Usuario consultado correctamente.';
    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_UsuarioAdmin_Sel_Detalle',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_UsuarioAdmin_Sel_Detalle',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'seg.PA_UsuarioAdmin_Sel_Detalle',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;


GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

-- seg.PA_UsuarioAdmin_Sel_Listado
CREATE OR ALTER PROCEDURE [seg].[PA_UsuarioAdmin_Sel_Listado](@cJson NVARCHAR(MAX),@bResultado BIT OUTPUT,@cMensaje NVARCHAR(300) OUTPUT,
    @cCodigoRespuesta VARCHAR(60)=NULL OUTPUT,
    @nHttpRespuesta SMALLINT=NULL OUTPUT
)
AS BEGIN
    SET @cMensaje=NULL; SET @cCodigoRespuesta=NULL; SET @nHttpRespuesta=NULL;

    /* Respuesta explícita; mensajes públicos aprobados. */
    SET NOCOUNT ON;
    DECLARE @__DbTranEntrada INT = @@TRANCOUNT,
            @__DbTranAbierta BIT = 0,
            @__DbSavepoint VARCHAR(32) = REPLACE(CONVERT(VARCHAR(36),NEWID()),'-',''),
            @__DbMensaje NVARCHAR(300),
            @__DbError BIT = 0;
    SET @bResultado = 0;

    BEGIN TRY
  SET NOCOUNT ON;
    DECLARE @nPaginaListado INT, @nTamanoListado INT, @nOffsetListado BIGINT;
    EXEC [seg].[PA_Consulta_Sel_ResolverPaginacion]
         @cJson = @cJson,
         @nPagina = @nPaginaListado OUTPUT,
         @nTamanoPagina = @nTamanoListado OUTPUT,
         @nOffset = @nOffsetListado OUTPUT;
DECLARE @nUsuario BIGINT,@nSesion BIGINT,@nDisp BIGINT,@nEmp BIGINT,@nModulo INT,@gCorr UNIQUEIDENTIFIER,@gSol UNIQUEIDENTIFIER,@cIp VARCHAR(64),@cEnd NVARCHAR(250),@bCtx BIT,@cMsg NVARCHAR(300);
SELECT @bResultado=0,@cMensaje=N'No se pudieron consultar los usuarios.';
EXEC seg.PA_Operacion_Sel_ContextoAutorizado @cJson=@cJson,@cCodigoPermiso='USUARIOS_LISTAR',@nUsuarioId=@nUsuario OUTPUT,@nSesionUsuarioId=@nSesion OUTPUT,@nDispositivoUsuarioId=@nDisp OUTPUT,@nEmpleadoId=@nEmp OUTPUT,@nModuloId=@nModulo OUTPUT,@gCorrelacionId=@gCorr OUTPUT,@gSolicitudId=@gSol OUTPUT,@cIp=@cIp OUTPUT,@cEndpoint=@cEnd OUTPUT,@bResultado=@bCtx OUTPUT,@cMensaje=@cMsg OUTPUT;
IF @bCtx=0 BEGIN SET @cMensaje=@cMsg;
GOTO __DESCO_Salida;
END;
 DECLARE @cEstado VARCHAR(25),@nEmpresa BIGINT;
SELECT @cEstado=UPPER(NULLIF(LTRIM(RTRIM(estadoCuenta)),'')),@nEmpresa=empresaId FROM OPENJSON(@cJson,'$.filtros') WITH(estadoCuenta VARCHAR(25) '$.estadoCuenta',empresaId BIGINT '$.empresaId');
SELECT U.usuario_id usuarioId,U.nombre_usuario nombreUsuario,U.estado_cuenta estadoCuenta,U.fecha_creacion fechaCreacion,U.ultimo_acceso_correcto ultimoAccesoCorrecto,U.intentos_fallidos intentosFallidos,U.bloqueado_hasta bloqueadoHasta,U.segundo_factor_habilitado segundoFactorHabilitado,E.empleado_id empleadoId,E.codigo_empleado codigoEmpleado,EM.razon_social empresa,P.numero_documento numeroDocumento,CONCAT(P.nombres,N' ',P.apellido_paterno,N' ',COALESCE(P.apellido_materno,N'')) empleado,(SELECT COUNT_BIG(*) FROM seg.UsuarioRol UR WHERE UR.usuario_id=U.usuario_id AND UR.estado=1 AND UR.fecha_desde<=SYSUTCDATETIME() AND (UR.fecha_hasta IS NULL OR UR.fecha_hasta>=SYSUTCDATETIME())) rolesActivos,(SELECT COUNT_BIG(*) FROM seg.SesionUsuario S WHERE S.usuario_id=U.usuario_id AND S.estado=1 AND S.fecha_revocacion IS NULL) sesionesActivas , COUNT_BIG(*) OVER() AS totalRegistros FROM seg.Usuario U INNER JOIN org.Empleado E ON E.empleado_id=U.persona_id INNER JOIN org.Persona P ON P.persona_id=U.persona_id INNER JOIN org.Empresa EM ON EM.empresa_id=E.empresa_id WHERE (@cEstado IS NULL OR U.estado_cuenta=@cEstado) AND (@nEmpresa IS NULL OR E.empresa_id=@nEmpresa) ORDER BY P.apellido_paterno,P.nombres,U.usuario_id OFFSET @nOffsetListado ROWS FETCH NEXT @nTamanoListado ROWS ONLY;
SET @bResultado=1;
SET @cMensaje=N'Usuarios consultados correctamente.';
    END TRY
    BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_UsuarioAdmin_Sel_Listado',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
    END CATCH;

__DESCO_Salida:
BEGIN TRY

IF @__DbTranAbierta = 1
BEGIN
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
IF ISNULL(@bResultado,0) = 1 OR NULLIF(@cMensaje,N'') IS NULL SET @cMensaje = N'La operación no se completó y sus cambios fueron revertidos.';
SET @bResultado = 0;
END;

END TRY
BEGIN CATCH

        SET @__DbError = 1;
BEGIN
    IF @__DbTranAbierta = 1
    BEGIN
        IF @__DbTranEntrada = 0 AND XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        ELSE IF @__DbTranEntrada > 0 AND XACT_STATE() = 1
            ROLLBACK TRANSACTION @__DbSavepoint;
        SET @__DbTranAbierta = 0;
    END;
END;
SET @bResultado = 0;
EXEC [config].[PA_Respuesta_ResolverError]
    @cProcedimiento = N'seg.PA_UsuarioAdmin_Sel_Listado',
    @cMensaje = @cMensaje OUTPUT,
    @cJson = @cJson,
    @bMensajePublicoGenerico = 0;
END CATCH;
IF XACT_STATE() = -1 AND ISNULL(@bResultado,0) = 1
BEGIN
SET @bResultado = 0;
SET @cMensaje = N'La transacción no puede confirmarse. Vuelva a iniciar la solicitud.';
END;
SET @bResultado=ISNULL(@bResultado,0);
SELECT @cMensaje=R.mensaje,@cCodigoRespuesta=R.codigo,@nHttpRespuesta=R.http_sugerido
FROM config.FN_RespuestaUsuario(N'seg.PA_UsuarioAdmin_Sel_Listado',@bResultado,@cMensaje) R;
IF @bResultado=1 RETURN 0;
RETURN 1;
END;

