CREATE OR ALTER TRIGGER logistica.TR_DESCO_RecursoMovimiento_Kardex
ON logistica.RecursoMovimiento AFTER INSERT,UPDATE,DELETE AS
BEGIN
 IF ROWCOUNT_BIG()=0 RETURN;
 SET NOCOUNT ON;
 IF EXISTS(SELECT 1 FROM deleted) THROW 51100,N'DESCO_MOVIMIENTO_INMUTABLE',1;
 IF EXISTS(SELECT 1 FROM inserted WHERE tipo_movimiento='AJUSTE')
  THROW 51000,N'Registre una devolución o un consumo para ajustar el recurso.',1;
 IF EXISTS(SELECT 1 FROM inserted I JOIN logistica.RecursoProgramado R ON R.recurso_programado_id=I.recurso_programado_id
  WHERE I.estado<>1 OR R.estado<>1 OR R.estado_proceso<>'EN_EJECUCION'
   OR (R.bien_inventario_id IS NOT NULL AND (I.cantidad<>1 OR I.tipo_movimiento NOT IN('ASIGNACION','DEVOLUCION')))
   OR (R.suministro_id IS NOT NULL AND I.tipo_movimiento='ASIGNACION'))
  THROW 51100,N'DESCO_RECURSO_NO_DISPONIBLE',1;
 ;WITH D AS(SELECT recurso_programado_id,
  SUM(CASE WHEN tipo_movimiento IN('ASIGNACION','ENTREGA') THEN CONVERT(DECIMAL(19,3),cantidad) ELSE 0 END) entregada,
  SUM(CASE WHEN tipo_movimiento='DEVOLUCION' THEN CONVERT(DECIMAL(19,3),cantidad) ELSE 0 END) devuelta,
  SUM(CASE WHEN tipo_movimiento='CONSUMO' THEN CONVERT(DECIMAL(19,3),cantidad) ELSE 0 END) consumida
  FROM inserted GROUP BY recurso_programado_id)
 UPDATE R SET cantidad_entregada=R.cantidad_entregada+D.entregada,
  cantidad_devuelta=R.cantidad_devuelta+D.devuelta,cantidad_consumida=R.cantidad_consumida+D.consumida
 FROM logistica.RecursoProgramado R JOIN D ON D.recurso_programado_id=R.recurso_programado_id;
 INSERT logistica.SuministroMovimiento(suministro_id,recurso_programado_id,recurso_movimiento_id,
  tipo_movimiento,cantidad,fecha_hora,usuario_id,observacion,estado)
 SELECT R.suministro_id,I.recurso_programado_id,I.recurso_movimiento_id,
  CASE WHEN I.tipo_movimiento='ENTREGA' THEN 'SALIDA' ELSE 'DEVOLUCION' END,
  I.cantidad,I.fecha_hora,I.usuario_id,I.observacion,1
 FROM inserted I JOIN logistica.RecursoProgramado R ON R.recurso_programado_id=I.recurso_programado_id
 WHERE R.suministro_id IS NOT NULL AND I.tipo_movimiento IN('ENTREGA','DEVOLUCION');
 -- El consumo no vuelve a descontar: la salida física se contabilizó al entregar.
 UPDATE R SET estado_proceso='COMPLETADO' FROM logistica.RecursoProgramado R
 WHERE R.estado_proceso='EN_EJECUCION' AND R.cantidad_entregada>0 AND R.cantidad_pendiente=0
 AND EXISTS(SELECT 1 FROM inserted I WHERE I.recurso_programado_id=R.recurso_programado_id);
 UPDATE B SET estado_bien='DISPONIBLE' FROM logistica.BienInventario B
 JOIN logistica.RecursoProgramado R ON R.bien_inventario_id=B.bien_inventario_id
 WHERE R.estado_proceso='COMPLETADO' AND B.estado_bien='ASIGNADO'
 AND EXISTS(SELECT 1 FROM inserted I WHERE I.recurso_programado_id=R.recurso_programado_id AND I.tipo_movimiento='DEVOLUCION');
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER TRIGGER logistica.TR_DESCO_RecursoProgramado_Reserva
ON logistica.RecursoProgramado AFTER INSERT,UPDATE,DELETE AS
BEGIN
 IF ROWCOUNT_BIG()=0 RETURN;
 SET NOCOUNT ON;
 IF EXISTS(SELECT 1 FROM deleted D LEFT JOIN inserted I ON I.recurso_programado_id=D.recurso_programado_id WHERE I.recurso_programado_id IS NULL)
  THROW 51100,N'DESCO_MOVIMIENTO_INMUTABLE',1;
 IF EXISTS(SELECT 1 FROM inserted I JOIN deleted D ON D.recurso_programado_id=I.recurso_programado_id
  WHERE D.cantidad_entregada>0 AND
   (ISNULL(I.bien_inventario_id,0)<>ISNULL(D.bien_inventario_id,0) OR ISNULL(I.suministro_id,0)<>ISNULL(D.suministro_id,0)
    OR I.cantidad_programada<>D.cantidad_programada OR ISNULL(I.campania_venta_id,0)<>ISNULL(D.campania_venta_id,0)
    OR ISNULL(I.operativo_venta_id,0)<>ISNULL(D.operativo_venta_id,0) OR ISNULL(I.salida_campo_id,0)<>ISNULL(D.salida_campo_id,0)))
  THROW 51100,N'DESCO_MOVIMIENTO_INMUTABLE',1;
 IF EXISTS(SELECT 1 FROM inserted I JOIN deleted D ON D.recurso_programado_id=I.recurso_programado_id
  WHERE I.estado_proceso<>D.estado_proceso AND NOT
   ((D.estado_proceso='PROGRAMADO' AND I.estado_proceso IN('EN_EJECUCION','CANCELADO'))
     OR (D.estado_proceso='EN_EJECUCION' AND I.estado_proceso='COMPLETADO')))
  THROW 51100,N'DESCO_RECURSO_NO_DISPONIBLE',1;
 IF EXISTS(SELECT 1 FROM inserted I LEFT JOIN deleted D ON D.recurso_programado_id=I.recurso_programado_id
  WHERE D.recurso_programado_id IS NULL AND (I.estado_proceso<>'PROGRAMADO' OR I.cantidad_entregada<>0 OR I.cantidad_devuelta<>0 OR I.cantidad_consumida<>0))
  THROW 51100,N'DESCO_RECURSO_NO_DISPONIBLE',1;
 IF EXISTS(SELECT 1 FROM inserted I JOIN deleted D ON D.recurso_programado_id=I.recurso_programado_id
  WHERE D.estado=1 AND I.estado=0 AND (D.estado_proceso='EN_EJECUCION' OR D.cantidad_pendiente>0))
  THROW 51100,N'DESCO_RECURSO_NO_DISPONIBLE',1;
 IF EXISTS(SELECT 1 FROM inserted I LEFT JOIN logistica.Suministro S ON S.suministro_id=I.suministro_id
  WHERE I.estado=1 AND I.estado_proceso IN('PROGRAMADO','EN_EJECUCION') AND I.suministro_id IS NOT NULL AND S.estado<>1)
  THROW 51100,N'DESCO_RECURSO_NO_DISPONIBLE',1;
 IF EXISTS(SELECT 1 FROM inserted WHERE (bien_inventario_id IS NOT NULL AND cantidad_programada<>1)
  OR (estado_proceso='COMPLETADO' AND (cantidad_entregada<=0 OR cantidad_pendiente<>0)))
  THROW 51100,N'DESCO_RECURSO_EXCESO',1;
 ;WITH X AS(
  SELECT suministro_id,CONVERT(DECIMAL(19,3),cantidad_programada) cantidad FROM inserted WHERE suministro_id IS NOT NULL AND estado=1 AND estado_proceso='PROGRAMADO'
  UNION ALL SELECT suministro_id,-CONVERT(DECIMAL(19,3),cantidad_programada) FROM deleted WHERE suministro_id IS NOT NULL AND estado=1 AND estado_proceso='PROGRAMADO'),
 D AS(SELECT suministro_id,SUM(cantidad) cantidad FROM X GROUP BY suministro_id)
 UPDATE S SET stock_reservado=S.stock_reservado+D.cantidad,fecha_actualizacion=SYSUTCDATETIME()
 FROM logistica.SuministroSaldo S JOIN D ON D.suministro_id=S.suministro_id WHERE D.cantidad<>0;
 IF EXISTS(SELECT 1 FROM inserted I WHERE I.suministro_id IS NOT NULL AND NOT EXISTS
  (SELECT 1 FROM logistica.SuministroSaldo S WHERE S.suministro_id=I.suministro_id))
  THROW 51100,N'DESCO_KARDEX_REVISAR',1;
END;

GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

