GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER TRIGGER [org].[TR_Area_ValidarJerarquia]
ON [org].[Area]
AFTER INSERT, UPDATE
AS
BEGIN
    IF ROWCOUNT_BIG() = 0 RETURN;
    SET NOCOUNT ON;
    IF NOT (UPDATE(area_padre_id) OR UPDATE(empresa_id)) RETURN;
    DECLARE @nBloqueo BIGINT, @bCiclo BIT = 0;
    -- La jerarquía es pequeña; serializar su inspección evita dos enlaces cruzados simultáneos.
    SELECT @nBloqueo = COUNT_BIG(*) FROM [org].[Area] WITH (UPDLOCK,HOLDLOCK);
    ;WITH Ruta AS
    (
        SELECT I.area_id AS origen, I.area_id, I.area_padre_id,
               CONVERT(VARCHAR(MAX), '/' + CONVERT(VARCHAR(20),I.area_id) + '/') AS ruta,
               CONVERT(BIT,0) AS ciclo
        FROM inserted I
        UNION ALL
        SELECT R.origen, A.area_id, A.area_padre_id,
               CONVERT(VARCHAR(MAX), R.ruta + CONVERT(VARCHAR(20),A.area_id) + '/'),
               CONVERT(BIT, CASE WHEN CHARINDEX('/'+CONVERT(VARCHAR(20),A.area_id)+'/',R.ruta)>0 THEN 1 ELSE 0 END)
        FROM Ruta R JOIN [org].[Area] A ON A.area_id = R.area_padre_id
        WHERE R.ciclo = 0
    )
    SELECT @bCiclo = CONVERT(BIT, MAX(CONVERT(INT,ciclo))) FROM Ruta
    OPTION (MAXRECURSION 32767);
    IF @bCiclo = 1 THROW 51001, N'DESCO_AREA_CICLICA', 1;
END;


GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER TRIGGER org.TR_Asociacion_SincronizarUOTLegacy
ON org.Asociacion AFTER INSERT,UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Root BIGINT=(SELECT TOP(1) uot_id FROM org.UOT WHERE es_raiz=1 AND estado=1 ORDER BY uot_id);
    UPDATE A SET uot_id=@Root FROM org.Asociacion A JOIN inserted I ON I.asociacion_id=A.asociacion_id WHERE A.uot_id IS NULL;
    INSERT org.ConvenioUOTOrganizacion(uot_id,empresa_id,tipo_vinculo,fecha_inicio,descripcion,estado)
    SELECT A.uot_id,A.asociacion_id,'ASOCIACION',A.fecha_constitucion,N'Convenio/vínculo generado automáticamente para compatibilidad.',A.estado
    FROM org.Asociacion A JOIN inserted I ON I.asociacion_id=A.asociacion_id
    WHERE I.uot_id IS NULL AND A.uot_id IS NOT NULL AND A.estado=1
      AND NOT EXISTS(SELECT 1 FROM org.ConvenioUOTOrganizacion C WHERE C.uot_id=A.uot_id AND C.empresa_id=A.asociacion_id AND C.tipo_vinculo='ASOCIACION' AND C.estado=1 AND C.fecha_fin IS NULL);
END;

